param(
    [switch]$Unattended
)

# Защита от PowerShell ISE (Авто-перезапуск)
if ($Host.Name -match "ISE") {
    $wshell = New-Object -ComObject Wscript.Shell
    $wshell.Popup("Скрипт содержит графический интерфейс и функции, которые зависают в ISE.`n`nСкрипт будет перезапущен в стандартной консоли.", 5, "Eastrica Optimizer", 48) | Out-Null
    $iseArgs = "-NoProfile -ExecutionPolicy Bypass -File `"$PSCommandPath`""
    if ($Unattended) { $iseArgs += " -Unattended" }
    Start-Process powershell.exe -ArgumentList $iseArgs -Verb RunAs
    Exit
}

# Профессиональная темная тема (В стиле GUI)
$ProgressPreference = 'SilentlyContinue' # Убираем уродливый синий блок прогресс-бара ОС
try {
    [Console]::BackgroundColor = [ConsoleColor]::Black # Темный фон
    [Console]::ForegroundColor = [ConsoleColor]::Gray  # Серый текст по умолчанию
    Clear-Host
} catch {}

# Умный фильтр цветов (Авто-превращение в строгий темный стиль)
function Write-Host {
    param([Parameter(Position=0, ValueFromRemainingArguments=$true)] $Object, [switch]$NoNewline, $ForegroundColor, $BackgroundColor)
    
    if ($ForegroundColor) {
        switch ($ForegroundColor) {
            "Cyan"     { $ForegroundColor = "White" }     # Заголовки разделов делаем белыми
            "Magenta"  { $ForegroundColor = "Yellow" }    # Предупреждения делаем желтыми
            "Red"      { $ForegroundColor = "Red" }       # Ошибки оставляем красными
            "Yellow"   { $ForegroundColor = "DarkGray" }  # Обычный текст и акценты делаем темно-серыми
            "Green"    { $ForegroundColor = "Green" }     # Успешные[OK] оставляем зелеными
            "Gray"     { $ForegroundColor = "DarkGray" }  # Серый переводим в темно-серый
            "DarkGray" { $ForegroundColor = "DarkGray" }  # Разделители (===) и детали оставляем темно-серыми
            Default    { $ForegroundColor = "DarkGray" }  # Всё остальное - темно-серое
        }
    } else {
        $ForegroundColor = "DarkGray"
    }

    # Превращаем текст в строку для поиска и логов
    $str = if ($null -ne $Object) { $Object -join ' ' } else { "" }
    
    # Скоростное буферизированное логирование
    try {
        if ($global:LogWriter -ne $null) {
            if ($NoNewline) { $global:LogWriter.Write($str) }
            else { $global:LogWriter.WriteLine($str) }
        } elseif ($global:LogPath -and (Test-Path $global:LogPath)) {
            if ($NoNewline) { [System.IO.File]::AppendAllText($global:LogPath, $str, [System.Text.Encoding]::UTF8) } 
            else { [System.IO.File]::AppendAllText($global:LogPath, $str + [Environment]::NewLine, [System.Text.Encoding]::UTF8) }
        }
    } catch {}

    # Собираем параметры фона, если они заданы
    $bgParam = @{}
    if ($BackgroundColor) { $bgParam.Add('BackgroundColor', $BackgroundColor) }

    # Магия раскраски: Ищем маркеры успеха, ошибок, предупреждений и стрелочки
    if ($str -match "►|\[OK\]|\[FAIL\]|\[ERROR\]|\[WARNING\]") {
        # Разбиваем строку, сохраняя сами маркеры благодаря круглым скобкам
        $parts = $str -split "(►|\[OK\]|\[FAIL\]|\[ERROR\]|\[WARNING\])"
        
        foreach ($part in $parts) {
            if ($part) { # Пропускаем пустые куски
                
                # Если текущий кусок - это стрелочка или успех ► ЗЕЛЕНЫЙ
                if ($part -eq "►" -or $part.ToUpper() -eq "[OK]") {
                    Microsoft.PowerShell.Utility\Write-Host $part -NoNewline -ForegroundColor Green @bgParam
                }
                # Если текущий кусок - это провал или ошибка ► КРАСНЫЙ
                elseif ($part.ToUpper() -eq "[FAIL]" -or $part.ToUpper() -eq "[ERROR]") {
                    Microsoft.PowerShell.Utility\Write-Host $part -NoNewline -ForegroundColor Red @bgParam
                }
                # Если текущий кусок - это предупреждение ► ЖЕЛТЫЙ
                elseif ($part.ToUpper() -eq "[WARNING]") {
                    Microsoft.PowerShell.Utility\Write-Host $part -NoNewline -ForegroundColor Yellow @bgParam
                }
                # Всё остальное (обычный текст) ► СТАНДАРТНЫЙ ЦВЕТ
                else {
                    Microsoft.PowerShell.Utility\Write-Host $part -NoNewline -ForegroundColor $ForegroundColor @bgParam
                }
            }
        }
        # Делаем перенос строки, если скрипт не запретил это флагом -NoNewline
        if (-not $NoNewline) {
            Microsoft.PowerShell.Utility\Write-Host ""
        }
    } else {
        # Если маркеров нет, выводим всё как обычно (быстрый путь)
        $params = @{}
        if ($Object) { $params.Add('Object', $Object) }
        if ($NoNewline) { $params.Add('NoNewline', $true) }
        if ($ForegroundColor) { $params.Add('ForegroundColor', $ForegroundColor) }
        if ($BackgroundColor) { $params.Add('BackgroundColor', $BackgroundColor) }
        
        Microsoft.PowerShell.Utility\Write-Host @params
    }
}

# Базовые функции
function Show-ProgressStep {
    param ([int]$StepNum, [int]$TotalSteps, [string]$Activity)
    
    # Вычисляем процент
    $Percent = [math]::Round(($StepNum / $TotalSteps) * 100)
    if ($Percent -gt 100) { $Percent = 100 }
    
    # 1. Выводим статус в ЗАГОЛОВОК ОКНА (видно на панели задач)
    $Host.UI.RawUI.WindowTitle = "Оптимизация: $Percent% ($StepNum/$TotalSteps)"
    
    # 2. Выводим аккуратный синий (Cyan) шаг в консоль
    # Cyan используется в PowerShell как идеальный "неоново-синий" для темного фона (тот же цвет, что и в вашем GUI)
    Microsoft.PowerShell.Utility\Write-Host "`n• ШАГ $StepNum/$TotalSteps [$Percent%] : $Activity" -ForegroundColor Cyan
}

$global:ErrorLogPath = "$env:SystemDrive\EastricaTools\Eastrica_ErrorTrace.log"

function Write-SafeFileLog {
    param([string]$FilePath, [string]$Message)
    for ($attempt = 0; $attempt -lt 10; $attempt++) {
        try {
            $dir = [System.IO.Path]::GetDirectoryName($FilePath)
            if (-not (Test-Path $dir)) { [System.IO.Directory]::CreateDirectory($dir) | Out-Null }
            $stream = [System.IO.File]::Open($FilePath, [System.IO.FileMode]::Append, [System.IO.FileAccess]::Write, [System.IO.FileShare]::ReadWrite)
            $bytes = [System.Text.Encoding]::UTF8.GetBytes($Message)
            $stream.Write($bytes, 0, $bytes.Length)
            $stream.Close()
            break
        } catch {
            Start-Sleep -Milliseconds 100
        }
    }
}

function Write-TraceLog {
    param ([System.Management.Automation.ErrorRecord]$ErrorRecord, [string]$Context = "General")
    $LogEntry = "[$(Get-Date -Format 'HH:mm:ss')][ERROR] Line: $($ErrorRecord.InvocationInfo.ScriptLineNumber)`nMsg: $($ErrorRecord.Exception.Message)`r`n"
    Write-SafeFileLog -FilePath $global:ErrorLogPath -Message $LogEntry
}
trap { Write-TraceLog -ErrorRecord $_ -Context "GlobalTrap"; continue }

# ==============================================================================
# Инициализация и проверка прав
# ==============================================================================

Write-Host ""

# Детектор языка системы (Авто-перевод GUI)
$global:IsRU = ((Get-UICulture).TwoLetterISOLanguageName -eq "ru")
function L ([string]$Ru, [string]$En) {
    if ($global:IsRU) { return $Ru } else { return $En }
}

Show-ProgressStep -StepNum 0 -TotalSteps 81 -Activity "Инициализация и проверка прав..."
Write-Host "==============================================================================" -ForegroundColor DarkGray
Write-Host "РАЗДЕЛ 0: ИНИЦИАЛИЗАЦИЯ И ПРОВЕРКА ПРАВ" -ForegroundColor Cyan
Write-Host "==============================================================================" -ForegroundColor DarkGray

if (!([Security.Principal.WindowsPrincipal][Security.Principal.WindowsIdentity]::GetCurrent()).IsInRole([Security.Principal.WindowsBuiltInRole] "Administrator")) { # Проверяем, запущен ли скрипт от имени Администратора
    Write-Warning "ОШИБКА: Запустите PowerShell от имени Администратора!" # Выводим предупреждение, если прав нет
    Start-Sleep -Seconds 5 # Ждем 5 секунд перед закрытием
    Exit # Завершаем выполнение скрипта
}

# Проверка незавершенных обновлений Windows (Pending reboot guard)
Write-Host " ► Проверка состояния перезагрузки системы..." -ForegroundColor DarkGray

$CbsPending = Test-Path "HKLM:\SOFTWARE\Microsoft\Windows\CurrentVersion\Component Based Servicing\RebootPending"
$WuPending  = Test-Path "HKLM:\SOFTWARE\Microsoft\Windows\CurrentVersion\WindowsUpdate\Auto Update\RebootRequired"
$SmPending  = $false

try {
    $SmKey = Get-ItemProperty -Path "HKLM:\SYSTEM\CurrentControlSet\Control\Session Manager" -Name "PendingFileRenameOperations" -ErrorAction SilentlyContinue 2>> $env:SystemDrive\EastricaTools\Eastrica_ErrorTrace.log
    if ($null -ne $SmKey -and $null -ne $SmKey.PendingFileRenameOperations -and $SmKey.PendingFileRenameOperations.Count -gt 0) {
        $SmPending = $true
    }
} catch { }

if ($CbsPending -or $WuPending -or $SmPending) {
    Write-Host ""
    Write-Host "==============================================================================" -ForegroundColor Yellow
    Write-Host "[WARNING] ВНИМАНИЕ: СИСТЕМА ОЖИДАЕТ ПЕРЕЗАГРУЗКИ ПОСЛЕ ОБНОВЛЕНИЙ!" -ForegroundColor Red
    Write-Host "==============================================================================" -ForegroundColor Yellow
    Write-Host "Обнаружены незавершенные операции обслуживания ядра (Component Servicing / WU)." -ForegroundColor DarkGray
    Write-Host "Применение твиков BCD, правки загрузчика и реестра прямо сейчас может вызвать" -ForegroundColor DarkGray
    Write-Host "ошибку восстановления или циклический сбой загрузки системы (Boot Loop)." -ForegroundColor DarkGray
    Write-Host ""

    if ([Environment]::UserInteractive -and $env:USERNAME -ne "SYSTEM" -and -not $Unattended) {
        $RebootChoice = Read-Host "Всё равно продолжить оптимизацию на свой страх и риск? (Y - Да / N - Выйти и перезагрузить)"
        if ($RebootChoice -notmatch "^[YyДд]") {
            Write-Host "Выход из скрипта. Пожалуйста, перезагрузите ПК и запустите оптимизатор снова." -ForegroundColor Yellow
            Start-Sleep -Seconds 3
            Exit
        }
        Write-Host " ► Принудительное продолжение по запросу пользователя..." -ForegroundColor Yellow
    } else {
        Write-Host " ► Режим SYSTEM/Unattended: продолжение выполнения..." -ForegroundColor DarkGray
    }
} else {
    Write-Host "[OK] Перезагрузка не требуется, компоненты стабильны." -ForegroundColor DarkGray
}

# Безопасная проверка репозитория WMI с жестким таймаутом (защита от бесконечного зависания при повреждении базы)
Write-Host " ► Проверка репозитория WMI (Защита от зависания опроса железа)..." -ForegroundColor DarkGray
$wmiProc = Start-Process -FilePath "winmgmt.exe" -ArgumentList "/verifyrepository" -WindowStyle Hidden -PassThru -ErrorAction SilentlyContinue

# Ожидаем ответа не более 5 секунд; если WMI завис — принудительно убиваем процесс и лечим базу
$wmiCorrupt = $false
if ($wmiProc) {
    if (-not $wmiProc.WaitForExit(5000)) {
        try { $wmiProc.Kill() } catch {}
        $wmiCorrupt = $true
    } elseif ($wmiProc.ExitCode -ne 0) {
        $wmiCorrupt = $true
    }
}

if ($wmiCorrupt) {
    Write-Host "[WARNING] База WMI зависла или повреждена! Выполняется автоматическое лечение..." -ForegroundColor Yellow
    cmd.exe /c "winmgmt /salvagerepository >nul 2>&1"
} else {
    Write-Host "[OK] Репозиторий WMI стабилен." -ForegroundColor DarkGray
}

# Восстановление автопоиска Wi-Fi сетей (на случай аварийного закрытия игр)
try {
    $wifiInterfaces = (cmd.exe /c "netsh wlan show interfaces" 2>$null | Out-String)
    if ($wifiInterfaces -match '(?i)Auto\s*configuration\s*:\s*Disabled|Автоконфигурация\s*:\s*Отключено') {
        Write-Host " ► Восстановление службы автоподключения Wi-Fi..." -ForegroundColor Yellow
        cmd.exe /c "netsh wlan set autoconfig enabled=yes interface=* >nul 2>&1"
    }
} catch {}

$global:ScriptSourcePath = $PSCommandPath # Сохраняем путь к текущему скрипту для функции Builder Mode

$BaseDir = "$env:SystemDrive\EastricaTools" # Задаем базовую директорию для хранения утилит и логов
if (!(Test-Path $BaseDir)) { New-Item -ItemType Directory -Force -Path $BaseDir > $null } # Создаем базовую директорию, если её нет

$OptimizerDir = "$BaseDir\Scripts" # Задаем путь для хранения сгенерированных скриптов
if (!(Test-Path $OptimizerDir)) { New-Item -ItemType Directory -Path $OptimizerDir -Force > $null } # Создаем папку системного оптимизатора

# Глобальная компиляция C# WinAPI (Ускорение запуска)
if (-not ("EastricaNativeInterop" -as [type])) {
    $GlobalCSharpCode = @"
    using System;
    using System.Runtime.InteropServices;

    public class TokenManipulator {
        [DllImport("advapi32.dll", ExactSpelling = true, SetLastError = true)]
        internal static extern bool AdjustTokenPrivileges(IntPtr htok, bool disall, ref TokPriv1Luid newst, int len, IntPtr prev, IntPtr relen);
        [DllImport("advapi32.dll", ExactSpelling = true, SetLastError = true)]
        internal static extern bool OpenProcessToken(IntPtr h, int acc, ref IntPtr phtok);
        [DllImport("advapi32.dll", SetLastError = true)]
        internal static extern bool LookupPrivilegeValue(string host, string name, ref long pluid);
        [DllImport("kernel32.dll", ExactSpelling = true)]
        internal static extern bool CloseHandle(IntPtr h);
        [StructLayout(LayoutKind.Sequential, Pack = 1)]
        internal struct TokPriv1Luid { public int Count; public long Luid; public int Attr; }
        
        public static void AddPrivilege(string privilege) {
            IntPtr hproc = System.Diagnostics.Process.GetCurrentProcess().Handle;
            IntPtr htok = IntPtr.Zero;
            OpenProcessToken(hproc, 0x00000020 | 0x00000008, ref htok);
            TokPriv1Luid tp = new TokPriv1Luid();
            tp.Count = 1; tp.Luid = 0; tp.Attr = 0x00000002;
            LookupPrivilegeValue(null, privilege, ref tp.Luid);
            AdjustTokenPrivileges(htok, false, ref tp, 0, IntPtr.Zero, IntPtr.Zero);
            CloseHandle(htok);
        }
    }

    public class DisplayAPI { 
        [StructLayout(LayoutKind.Sequential, CharSet = CharSet.Ansi)] 
        public struct DEVMODE { 
            [MarshalAs(UnmanagedType.ByValTStr, SizeConst = 32)] public string dmDeviceName; 
            public short dmSpecVersion; public short dmDriverVersion; public short dmSize; public short dmDriverExtra; 
            public int dmFields; public int dmPositionX; public int dmPositionY; public int dmDisplayOrientation; 
            public int dmDisplayFixedOutput; public short dmColor; public short dmDuplex; public short dmYResolution; 
            public short dmTTOption; public short dmCollate; 
            [MarshalAs(UnmanagedType.ByValTStr, SizeConst = 32)] public string dmFormName; 
            public short dmLogPixels; public int dmBitsPerPel; public int dmPelsWidth; public int dmPelsHeight; 
            public int dmDisplayFlags; public int dmDisplayFrequency; 
        } 
        [DllImport("user32.dll")] public static extern bool EnumDisplaySettings(string deviceName, int modeNum, ref DEVMODE devMode); 
        public static int GetPrimaryHz() { 
            DEVMODE dm = new DEVMODE(); 
            dm.dmSize = (short)Marshal.SizeOf(typeof(DEVMODE)); 
            if (EnumDisplaySettings(null, -1, ref dm)) { return dm.dmDisplayFrequency; } 
            return 60; 
        } 
    }

    public class UIAnim {
        [DllImport("user32.dll", SetLastError = true)]
        public static extern bool SystemParametersInfo(uint uiAction, uint uiParam, IntPtr pvParam, uint fWinIni);
    }

    public class CacheAPI {
        [DllImport("kernel32.dll", SetLastError = true)]
        public static extern bool SetSystemFileCacheSize(IntPtr MinimumFileCacheSize, IntPtr MaximumFileCacheSize, int Flags);
    }

    namespace Win32Functions {
        public class Win32SystemParamInfo {
            [DllImport("user32.dll", SetLastError = true)]
            public static extern bool SystemParametersInfo(uint uiAction, uint uiParam, uint pvParam, uint fWinIni);
            [DllImport("user32.dll", SetLastError = true)]
            public static extern bool SystemParametersInfo(uint uiAction, uint uiParam, int[] pvParam, uint fWinIni);
        }
    }
    
    public class EastricaNativeInterop { }
"@
    Add-Type -TypeDefinition $GlobalCSharpCode -Language CSharp 2>> $env:SystemDrive\EastricaTools\Eastrica_ErrorTrace.log
}

