Write-Host "==============================================================================" -ForegroundColor DarkGray
Write-Host "РАЗДЕЛ 1: НАСТРОЙКА КОДИРОВКИ И СИСТЕМЫ ЛОГИРОВАНИЯ" -ForegroundColor Cyan
Write-Host "==============================================================================" -ForegroundColor DarkGray
$global:LogPath = "$BaseDir\Eastrica_Log_$(Get-Date -Format 'yyyyMMdd_HHmm').txt" # Генерируем уникальное имя файла лога с текущей датой и временем

try {
    # Получаем OEM-кодировку Windows (Обычно CP866 для консольных утилит в РФ)
    $OEMCP = [System.Text.Encoding]::GetEncoding([int](Get-ItemProperty HKLM:\SYSTEM\CurrentControlSet\Control\Nls\CodePage -Name OEMCP).OEMCP)
    
    # Жестко переводим консоль и пайплайны PowerShell в OEM, 
    # чтобы netsh, logman и fsutil выводили текст без "кракозябр"
    cmd.exe /c "chcp $($OEMCP.CodePage) >nul 2>&1"
    
    [Console]::OutputEncoding = $OEMCP 
    [Console]::InputEncoding  = $OEMCP
