# Функция глубокого сканирования целостности (вызывается в Разделе 7 после подтверждения в GUI)
function Invoke-SystemIntegrityScan {
    Write-Host " ► Проверка целостности компонентов системы (DISM)..." -ForegroundColor Cyan
    try {
        $DismCheck = DISM /Online /Cleanup-Image /ScanHealth 2>&1 | Out-String
        if ($DismCheck -match "(?i)repairable|подлежит восстановлению|может быть восстановлено|wiederherstellbar|réparable|reparable") {
            Write-Host "[WARNING] Обнаружены повреждения хранилища компонентов! Запуск восстановления..." -ForegroundColor Yellow
            Apply-Tweak "Глубокое восстановление компонентов ОС (DISM)" { 
                DISM /Online /Cleanup-Image /RestoreHealth *>&1 | Out-File -FilePath $global:LogPath -Append -Encoding UTF8 
            }
        } else {
            Write-Host "[OK] Хранилище компонентов Windows в норме." -ForegroundColor DarkGray
        }
    } catch {}

    Write-Host " ► Проверка системных файлов (SFC)..." -ForegroundColor Cyan
    $TempEnc = [Console]::OutputEncoding
    $TempOut = $OutputEncoding
    try { 
        [Console]::OutputEncoding = [System.Text.Encoding]::Unicode 
        $OutputEncoding = [System.Text.Encoding]::Unicode
        $sfcProcess = Start-Process -FilePath "sfc.exe" -ArgumentList "/scannow" -Wait -NoNewWindow -PassThru
        if ($sfcProcess.ExitCode -eq 0) {
            Write-Host "[OK] Проверка SFC: системные файлы целы" -ForegroundColor Green
        } elseif ($sfcProcess.ExitCode -in 1, 2) {
            Write-Host "[OK] Поврежденные файлы успешно восстановлены (требуется перезагрузка)" -ForegroundColor Green
        }
    } catch {
        Write-Host "[FAIL] Проверка SFC завершилась с ошибкой" -ForegroundColor Red
    } finally {
        try { 
            [Console]::OutputEncoding = $TempEnc 
            $OutputEncoding = $TempOut
        } catch {}
    }
}

# Умная защита BitLocker (Безопасная приостановка и диагностика производительности)
try {
    $BdeVolume = Get-CimInstance -Namespace "root\CIMV2\Security\MicrosoftVolumeEncryption" -ClassName Win32_EncryptableVolume -Filter "DriveLetter='$env:SystemDrive'" -ErrorAction Stop
    if ($BdeVolume.ProtectionStatus -eq 1 -or $BdeVolume.ProtectionStatus -eq 2) {
        Write-Host ""
        Write-Host "[WARNING] Обнаружено шифрование BitLocker на диске С:!" -ForegroundColor Yellow
        
        # Проверка программного метода шифрования (Методы 3, 4 = AES, 6, 7 = XTS-AES)
        if ($BdeVolume.EncryptionMethod -in 3, 4, 6, 7) {
            Write-Host " [ВНИМАНИЕ] На диске C: активно ПРОГРАММНОЕ шифрование процессором (Software AES)!" -ForegroundColor Red
            Write-Host " Это снижает скорость случайного чтения 4K и IOPS вашего NVMe на 25-40%." -ForegroundColor DarkGray
            Write-Host " Для максимального FPS рекомендуется расшифровать диск вручную: manage-bde -off C:" -ForegroundColor DarkGray
        }

        Write-Host "Выполняем безопасную приостановку защиты на 1 перезагрузку, чтобы твики" -ForegroundColor DarkGray
        Write-Host "загрузчика (bcdedit) не заблокировали ваш компьютер..." -ForegroundColor DarkGray
        
        Suspend-BitLocker -MountPoint $env:SystemDrive -RebootCount 1 -ErrorAction Stop | Out-Null
        Write-Host "[OK] BitLocker приостановлен. Оптимизация абсолютно безопасна." -ForegroundColor Green
    }
} catch { }

# ==============================================================================
# Модуль 1: Детектор и исправление вредоносных твиков (Broken tweaks audit)
# ==============================================================================
Write-Host ""
Write-Host "==============================================================================" -ForegroundColor DarkGray
Write-Host "Детектор и исправление поврежденных и мусорных твиков реестра" -ForegroundColor Cyan
Write-Host "==============================================================================" -ForegroundColor DarkGray
Write-Host " ► Сканирование реестра на скрытые твики, вызывающие заикания, краши и DPC-лаги..." -ForegroundColor DarkGray

$script:FixedTweaksCount = 0

function Audit-RegistryValue {
    param (
        [string]$Path,
        [string]$Name,
        [string]$Action,
        $TargetValue = $null,
        [string]$Type = "DWord",
        [scriptblock]$Condition = $null,
        [string]$Description = ""
    )

    if (Test-Path -LiteralPath $Path) {
        # Убран оператор 2>>, вызывавший ошибку "файл используется другим процессом"
        $key = Get-ItemProperty -LiteralPath $Path -Name $Name -ErrorAction SilentlyContinue
        if ($null -ne $key -and $null -ne $key.$Name) {
            $currentVal = $key.$Name
            $needsFix = $false

            if ($null -ne $Condition) {
                $needsFix = & $Condition $currentVal
            } else {
                $needsFix = $true
            }

            if ($needsFix) {
                if ($Action -eq "Remove") {
                    Apply-Tweak "[РЕПАРАЦИЯ] Удаление опасного ключа '$Name' ($Description)" {
                        Remove-ItemProperty -LiteralPath $Path -Name $Name -Force *>&1 | Out-File -FilePath $global:LogPath -Append -Encoding UTF8
                    }
                    $script:FixedTweaksCount++
                } elseif ($Action -eq "Set") {
                    if ($currentVal -ne $TargetValue) {
                        Apply-Tweak "[РЕПАРАЦИЯ] Исправление '$Name' с '$currentVal' на '$TargetValue' ($Description)" {
                            Set-ItemProperty -LiteralPath $Path -Name $Name -Value $TargetValue -Type $Type -Force *>&1 | Out-File -FilePath $global:LogPath -Append -Encoding UTF8
                        }
                        $script:FixedTweaksCount++
                    }
                }
            }
        }
    }
}

# 1. Сломанные твики сети и TCP/IP
# Опасный NetworkThrottlingIndex = 0 или 1 (вместо -1 / 0xFFFFFFFF), который искусственно сжимает сеть до 10 пакетов/мс
Audit-RegistryValue -Path "HKLM:\SOFTWARE\Microsoft\Windows NT\CurrentVersion\Multimedia\SystemProfile" -Name "NetworkThrottlingIndex" -Action "Set" -TargetValue -1 -Type "DWord" -Condition { param($v) $v -ge 0 -and $v -le 10 } -Description "Устранение удушения сетевого стека мультимедиа"

# Старые лимиты окна TCP, убивающие скорость на тарифах 100+ Мбит/с
Audit-RegistryValue -Path "HKLM:\SYSTEM\CurrentControlSet\Services\Tcpip\Parameters" -Name "TcpWindowSize" -Action "Remove" -Description "Удаление устаревшего лимита TCP Window"
Audit-RegistryValue -Path "HKLM:\SYSTEM\CurrentControlSet\Services\Tcpip\Parameters" -Name "GlobalMaxTcpWindowSize" -Action "Remove" -Description "Удаление ручного лимита Max TCP Window"
Audit-RegistryValue -Path "HKLM:\SYSTEM\CurrentControlSet\Services\Tcpip\Parameters" -Name "Tcp1323Opts" -Action "Remove" -Condition { param($v) $v -eq 0 } -Description "Исправление блокировки масштабирования окна RFC 1323"

# Несуществующие и вредные ключи в AFD (драйвер сокетов)
Audit-RegistryValue -Path "HKLM:\SYSTEM\CurrentControlSet\Services\AFD\Parameters" -Name "DefaultReceiveWindow" -Action "Remove" -Condition { param($v) $v -lt 65536 } -Description "Удаление микро-буфера приема сокетов AFD"
Audit-RegistryValue -Path "HKLM:\SYSTEM\CurrentControlSet\Services\AFD\Parameters" -Name "DefaultSendWindow" -Action "Remove" -Condition { param($v) $v -lt 65536 } -Description "Удаление микро-буфера отправки сокетов AFD"
Audit-RegistryValue -Path "HKLM:\SYSTEM\CurrentControlSet\Services\AFD\Parameters" -Name "TransmitWorker" -Action "Remove" -Description "Удаление выдуманного твика TransmitWorker"

# 2. Вредоносные и выдуманные твики ядра и памяти
# Мифические приоритеты прерываний DOS/Win95
Audit-RegistryValue -Path "HKLM:\SYSTEM\CurrentControlSet\Control\PriorityControl" -Name "IRQ8Priority" -Action "Remove" -Description "Удаление плацебо-ключа IRQ8Priority"
Audit-RegistryValue -Path "HKLM:\SYSTEM\CurrentControlSet\Control\PriorityControl" -Name "IRQ16Priority" -Action "Remove" -Description "Удаление плацебо-ключа IRQ16Priority"
Audit-RegistryValue -Path "HKLM:\SYSTEM\CurrentControlSet\Control\PriorityControl" -Name "IRQ14Priority" -Action "Remove" -Description "Удаление плацебо-ключа IRQ14Priority"
Audit-RegistryValue -Path "HKLM:\SYSTEM\CurrentControlSet\Control\PriorityControl" -Name "IRQ15Priority" -Action "Remove" -Description "Удаление плацебо-ключа IRQ15Priority"

# Принудительный разброс таймеров по игровым ядрам
Audit-RegistryValue -Path "HKLM:\SYSTEM\CurrentControlSet\Control\Session Manager\kernel" -Name "DistributeTimers" -Action "Remove" -Description "Защита игровых ядер от таймерных прерываний"

# Поврежденные значения квантов Win32PrioritySeparation (например, 0, 1, 63 или случайные числа)
Audit-RegistryValue -Path "HKLM:\SYSTEM\CurrentControlSet\Control\PriorityControl" -Name "Win32PrioritySeparation" -Action "Set" -TargetValue 42 -Type "DWord" -Condition { param($v) $v -notin @(2, 24, 38, 40, 42) } -Description "Нормализация квантов планировщика"

# Устаревшие ручные лимиты пулов памяти x86 эпохи (ломают распределение ОЗУ на 64-бит)
Audit-RegistryValue -Path "HKLM:\SYSTEM\CurrentControlSet\Control\Session Manager\Memory Management" -Name "SystemPages" -Action "Remove" -Condition { param($v) $v -ne 0 } -Description "Сброс жесткого лимита SystemPages"
Audit-RegistryValue -Path "HKLM:\SYSTEM\CurrentControlSet\Control\Session Manager\Memory Management" -Name "PoolUsageMaximum" -Action "Remove" -Description "Сброс ручного порога выгрузки пула памяти"
Audit-RegistryValue -Path "HKLM:\SYSTEM\CurrentControlSet\Control\Session Manager\Memory Management" -Name "NonPagedPoolSize" -Action "Remove" -Condition { param($v) $v -ne 0 } -Description "Сброс жесткого лимита NonPagedPool"
Audit-RegistryValue -Path "HKLM:\SYSTEM\CurrentControlSet\Control\Session Manager\Memory Management" -Name "PagedPoolSize" -Action "Remove" -Condition { param($v) $v -ne 0 } -Description "Сброс жесткого лимита PagedPool"
Audit-RegistryValue -Path "HKLM:\SYSTEM\CurrentControlSet\Control\Session Manager\Memory Management" -Name "SecondLevelDataCache" -Action "Remove" -Description "Удаление устаревшего ручного кэша L2"
Audit-RegistryValue -Path "HKLM:\SYSTEM\CurrentControlSet\Control\Session Manager\Memory Management" -Name "IOPageLockLimit" -Action "Remove" -Description "Удаление древнего твика IOPageLockLimit"

# LargeSystemCache = 1 на игровых ПК отбирает память у приложений под кэш файлов, вызывая дикие фризы
Audit-RegistryValue -Path "HKLM:\SYSTEM\CurrentControlSet\Control\Session Manager\Memory Management" -Name "LargeSystemCache" -Action "Set" -TargetValue 0 -Type "DWord" -Condition { param($v) $v -eq 1 } -Description "Запрет серверного файлового кэширования ОЗУ"

# 3. Выдуманные твики файловой системы (NTFS)
Audit-RegistryValue -Path "HKLM:\SYSTEM\CurrentControlSet\Control\FileSystem" -Name "NameCache" -Action "Remove" -Description "Удаление фейкового ключа NameCache"
Audit-RegistryValue -Path "HKLM:\SYSTEM\CurrentControlSet\Control\FileSystem" -Name "PathCache" -Action "Remove" -Description "Удаление фейкового ключа PathCache"

# 4. Драйверы, графика и оконный менеджер (DWM)
# Ключ Composition=0 в Windows 10/11 приводит к черным экранам или бесконечному падению DWM
Audit-RegistryValue -Path "HKLM:\SOFTWARE\Microsoft\Windows\Dwm" -Name "Composition" -Action "Remove" -Description "Устранение сбоя композитинга DWM"
Audit-RegistryValue -Path "HKCU:\Software\Microsoft\Windows\DWM" -Name "Composition" -Action "Remove" -Description "Устранение сбоя композитинга DWM (CU)"

# Сломанный лимит кадров DWM, порождающий неравномерный фреймтайм
Audit-RegistryValue -Path "HKCU:\Software\Microsoft\Windows\DWM" -Name "Max3DWindowedPresentLimit" -Action "Remove" -Description "Сброс сломанной очереди кадра Max3DWindowedPresentLimit"

# ForceVsyncOff в DWM ломает кадровые очереди WDDM
Audit-RegistryValue -Path "HKLM:\SOFTWARE\Microsoft\Windows\Dwm" -Name "ForceVsyncOff" -Action "Remove" -Description "Удаление принудительного сбоя VSync DWM"
Audit-RegistryValue -Path "HKCU:\Software\Microsoft\Windows\DWM" -Name "ForceVsyncOff" -Action "Remove" -Description "Удаление принудительного сбоя VSync DWM (CU)"

# Опасный твик DisableWriteCombining (убивает пропускную способность шины видеокарты)
Audit-RegistryValue -Path "HKLM:\SYSTEM\CurrentControlSet\Services\nvlddmkm" -Name "DisableWriteCombining" -Action "Remove" -Description "Восстановление склеивания видеопамяти NVIDIA"
Audit-RegistryValue -Path "HKLM:\SYSTEM\CurrentControlSet\Services\amdkmdag" -Name "DisableWriteCombining" -Action "Remove" -Description "Восстановление склеивания видеопамяти AMD"

# Опасный твик DisableDynamicPstate (P0 State Lock), вызывающий деградацию и перегрев памяти GDDR6X в простое
$GpuClassPath = "HKLM:\SYSTEM\CurrentControlSet\Control\Class\{4d36e968-e325-11ce-bfc1-08002be10318}"
if (Test-Path $GpuClassPath) {
    Get-ChildItem -Path $GpuClassPath -ErrorAction SilentlyContinue 2>> $env:SystemDrive\EastricaTools\Eastrica_ErrorTrace.log | Where-Object { $_.PSChildName -match "^\d{4}$" } | ForEach-Object {
        Audit-RegistryValue -Path $_.PSPath -Name "DisableDynamicPstate" -Action "Remove" -Description "Защита памяти видеокарты от перегрева в простое"
        Audit-RegistryValue -Path $_.PSPath -Name "PerfLevelSrc" -Action "Remove" -Description "Удаление мусорного ключа PerfLevelSrc"
        Audit-RegistryValue -Path $_.PSPath -Name "DscDisable" -Action "Remove" -Description "Восстановление Display Stream Compression (240Hz+ Fix)"
        Audit-RegistryValue -Path $_.PSPath -Name "DalDramClockChangeLatencyNs" -Action "Remove" -Description "Устранение черных вспышек экрана AMD"
        Audit-RegistryValue -Path $_.PSPath -Name "DalUrgentLatencyNs" -Action "Remove" -Description "Устранение черных вспышек экрана AMD"
    }
}

# 5. Удушение мыши и клавиатуры (Кривые очереди буфера)
# Установка размера очереди мыши в значения меньше 50 вызывает мгновенный срыв курсора при 1000Hz+
Audit-RegistryValue -Path "HKLM:\SYSTEM\CurrentControlSet\Services\mouclass\Parameters" -Name "MouseDataQueueSize" -Action "Set" -TargetValue 100 -Type "DWord" -Condition { param($v) $v -lt 50 -or $v -gt 1000 } -Description "Восстановление буфера очереди мыши"
Audit-RegistryValue -Path "HKLM:\SYSTEM\CurrentControlSet\Services\kbdclass\Parameters" -Name "KeyboardDataQueueSize" -Action "Set" -TargetValue 100 -Type "DWord" -Condition { param($v) $v -lt 50 -or $v -gt 1000 } -Description "Восстановление буфера очереди клавиатуры"

# Известные опечатки из популярных русскоязычных твик-паков
Audit-RegistryValue -Path "HKLM:\SOFTWARE\Microsoft\Windows NT\CurrentVersion\Windows" -Name "RITdemonTimerPowerSaveElapse" -Action "Remove" -Description "Удаление ошибочного ключа RITdemon..."
Audit-RegistryValue -Path "HKLM:\SOFTWARE\Microsoft\Windows NT\CurrentVersion\Windows" -Name "RITdemonTimerPowerSaveCoalescing" -Action "Remove" -Description "Удаление ошибочного ключа RITdemon..."

# 6. Критические дисковые ошибки и опасный polling NVMe
# EnablePolling = 1 на потребительских NVMe SSD вызывает циклический BSOD DPC_WATCHDOG_VIOLATION (0x133)
Audit-RegistryValue -Path "HKLM:\SYSTEM\CurrentControlSet\Services\stornvme\Parameters\Device" -Name "EnablePolling" -Action "Set" -TargetValue 0 -Type "DWord" -Condition { param($v) $v -eq 1 } -Description "Устранение синих экранов DPC от поллинга NVMe"

# Заниженный таймаут диска disk.sys, приводящий к отвалу диска при фоновой нагрузке
Audit-RegistryValue -Path "HKLM:\SYSTEM\CurrentControlSet\Services\disk" -Name "TimeOutValue" -Action "Set" -TargetValue 20 -Type "DWord" -Condition { param($v) $v -lt 10 } -Description "Исправление критического таймаута системного накопителя"

# 7. Аудит ошибочных и разрушительных правил IFEO (Image File Execution Options)
# Проверка на наличие безумного приоритета RealTime (CpuPriorityClass = 4), который вешает ядро ОС
$CriticalSystemApps = @("dwm.exe", "explorer.exe", "csrss.exe", "lsass.exe", "audiodg.exe")
foreach ($sysApp in $CriticalSystemApps) {
    $ifeoPerf = "HKLM:\SOFTWARE\Microsoft\Windows NT\CurrentVersion\Image File Execution Options\$sysApp\PerfOptions"
    if (Test-Path $ifeoPerf) {
        $prio = (Get-ItemProperty -Path $ifeoPerf -Name "CpuPriorityClass" -ErrorAction SilentlyContinue).CpuPriorityClass
        if ($prio -eq 4) {
            Apply-Tweak "[РЕПАРАЦИЯ] Сброс опасного приоритета RealTime для $sysApp" {
                Remove-ItemProperty -Path $ifeoPerf -Name "CpuPriorityClass" -Force *>&1 | Out-File -FilePath $global:LogPath -Append -Encoding UTF8
            }
            $script:FixedTweaksCount++
        }
    }
}

# Удаление Debugger-заглушек с системных компонентов (если кривой твикер пытался заблокировать процесс)
$IfeoRoot = "HKLM:\SOFTWARE\Microsoft\Windows NT\CurrentVersion\Image File Execution Options"
$ProtectedProcesses = @("explorer.exe", "taskmgr.exe", "cmd.exe", "powershell.exe", "regedit.exe", "msconfig.exe", "svchost.exe")
foreach ($proc in $ProtectedProcesses) {
    $procKey = "$IfeoRoot\$proc"
    Audit-RegistryValue -Path $procKey -Name "Debugger" -Action "Remove" -Description "Снятие вредоносной блокировки запуска $proc"
}

if ($script:FixedTweaksCount -gt 0) {
    Write-Host "[OK] Ревизия завершена: успешно исправлено потенциально опасных твиков: $script:FixedTweaksCount" -ForegroundColor Green
} else {
    Write-Host "[OK] Ревизия завершена: скрытых критических повреждений реестра не обнаружено." -ForegroundColor DarkGray
}

# Сбор информации о железе (для адаптивных твиков)
$global:ProcInfo = Get-CimInstance Win32_Processor | Select-Object -First 1 # Получаем информацию о процессоре
$global:SysInfo = Get-CimInstance Win32_ComputerSystem | Select-Object -First 1 # Получаем информацию о компьютере
$global:TotalLogCores = $global:SysInfo.NumberOfLogicalProcessors # Записываем общее количество логических потоков CPU
$global:IsAMD = $global:ProcInfo.Manufacturer -match "AMD" # Проверяем, является ли процессор от AMD
$global:TotalRAM = [math]::Round(($global:SysInfo.TotalPhysicalMemory / 1GB)) # Подсчитываем общий объем оперативной памяти в гигабайтах
$global:GPUs = @(Get-CimInstance Win32_VideoController | Where-Object { $_.PNPDeviceID -match "^PCI\\" -and $_.Name -notmatch "Basic|Microsoft|Parsec|Virtual|Idd" }) # Ищем реальные видеокарты в системе

if ($global:GPUs.Count -eq 0) {
    Write-Warning "Видеокарты не обнаружены! Некоторые твики будут пропущены." # Предупреждаем, если видеокарт нет (например, на виртуалке)
}

# Умная проверка на ноутбук (Игнорирует ИБП/UPS на стационарных ПК)
$SysInfoType = (Get-CimInstance Win32_ComputerSystem).PCSystemType # Получаем тип системы от материнской платы
$ChassisType = (Get-CimInstance Win32_SystemEnclosure).ChassisTypes[0] # Получаем физический тип корпуса
# Коды мобильных корпусов: 8(Portable), 9(Laptop), 10(Notebook), 14(SubNotebook), 30(Tablet)
$MobileChassis = @(8, 9, 10, 11, 12, 14, 18, 21, 30, 31, 32) # Массив кодов, присущих ноутбукам и планшетам
# Считаем ПК ноутбуком ТОЛЬКО если Windows называет его Mobile (2) или у него мобильный корпус
$global:IsLaptop = ($SysInfoType -eq 2) -or ($MobileChassis -contains $ChassisType)

# Проверка на ARM64 (Snapdragon X Elite)
$ProcessArch = [System.Runtime.InteropServices.RuntimeInformation]::ProcessArchitecture
$global:IsARM64 = ($ProcessArch -eq [System.Runtime.InteropServices.Architecture]::Arm64)
if ($global:IsARM64) {
    Write-Host "[WARNING] Обнаружена архитектура ARM64!" -ForegroundColor Magenta
    $global:TotalLogCores = 1 # Отключение логики P-Cores
    $global:OptHwSleep = $false # Сон шины критичен для ARM
}

# Защита системы охлаждения ноутбуков
$Vendor = $global:SysInfo.Manufacturer
$global:IsUnsafeBatteryTweak = $false
if ($global:IsLaptop -and $Vendor -match "ASUS|Lenovo|Razer|Alienware") {
    $global:IsUnsafeBatteryTweak = $true
}

# Сбор данных WHEA до очистки журналов
$global:WheaAuditRun = $true
$global:TotalWhea = 0
$global:WheaSummary = @{ CpuCacheErrors = 0; PcieErrors = 0; MemoryErrors = 0; FatalMceErrors = 0; OtherErrors = 0 }
$global:FailingCores = [System.Collections.Generic.List[int]]::new()
$global:OtherWheaIDs = [System.Collections.Generic.List[int]]::new()
$global:WheaEventsFound = $false

try {
    $StartTime = (Get-Date).AddDays(-7)
    $WheaFilter = @{ LogName = 'System'; ProviderName = 'Microsoft-Windows-WHEA-Logger'; StartTime = $StartTime }
    $WheaEvents = Get-WinEvent -FilterHashtable $WheaFilter -MaxEvents 50 -ErrorAction SilentlyContinue

    if ($null -ne $WheaEvents -and $WheaEvents.Count -gt 0) {
        $global:WheaEventsFound = $true
        $global:TotalWhea = $WheaEvents.Count
        foreach ($evt in $WheaEvents) {
            $id = $evt.Id
            if ($id -in @(18, 19)) {
                if ($id -eq 18) { $global:WheaSummary.FatalMceErrors++ } else { $global:WheaSummary.CpuCacheErrors++ }
                try {
                    $xml = [xml]$evt.ToXml()
                    $rawApic = ($xml.Event.EventData.Data | Where-Object { $_.Name -eq 'ProcessorAPICID' -or $_.Name -eq 'ApicId' } | Select-Object -First 1).'#text'
                    if ($null -ne $rawApic -and $rawApic -match '^\d+$') {
                        $apicInt = [int]$rawApic
                        if (-not $global:FailingCores.Contains($apicInt)) { $global:FailingCores.Add($apicInt) }
                    }
                } catch {}
            }
            elseif ($id -eq 17) { $global:WheaSummary.PcieErrors++ }
            elseif ($id -in @(47, 1)) { $global:WheaSummary.MemoryErrors++ }
            else { 
                $global:WheaSummary.OtherErrors++ 
                if (-not $global:OtherWheaIDs.Contains($id)) { $global:OtherWheaIDs.Add($id) }
            }
        }
    }
} catch {
    $global:WheaAuditRun = $false
}

Write-Host ""
Write-Host ""
Write-Host ">>>  ЗАПУСК ПОЛНОЙ ОПТИМИЗАЦИИ СИСТЕМЫ  <<<" -ForegroundColor Red
Write-Host ""

# ==============================================================================
# Раздел 5: Графическое меню выбора опций (GUI - Windows Forms)
# ==============================================================================
Show-ProgressStep -StepNum 5 -TotalSteps 81 -Activity (L "Генерация графического интерфейса..." "Generating graphical interface...")
Write-Host "==============================================================================" -ForegroundColor DarkGray
Write-Host (L "РАЗДЕЛ 5: ГРАФИЧЕСКОЕ МЕНЮ ВЫБОРА ОПЦИЙ (GUI - WINDOWS FORMS)" "SECTION 5: GRAPHICAL OPTION SELECTION MENU (GUI - WINDOWS FORMS)") -ForegroundColor Cyan
Write-Host "==============================================================================" -ForegroundColor DarkGray
Add-Type -AssemblyName System.Windows.Forms # Загружаем сборку для создания окон
Add-Type -AssemblyName System.Drawing # Загружаем сборку для работы со шрифтами и графикой

$g = [System.Drawing.Graphics]::FromHwnd([IntPtr]::Zero)
$Scale = $g.DpiX / 96.0
$g.Dispose()

try { [System.Windows.Forms.Application]::EnableVisualStyles() } catch {} # Включаем современные стили кнопок ОС
try { [System.Windows.Forms.Application]::SetHighDpiMode([System.Windows.Forms.HighDpiMode]::SystemAware) } catch {} # Делаем окно четким на 4K/DPI мониторах

$form = New-Object System.Windows.Forms.Form -Property @{TopMost=$true} # Создаем главное окно
$form.Text = (L "Eastrica Ultimate Windows Optimizer" "Eastrica Ultimate Windows Optimizer") # Заголовок окна
$form.ClientSize = New-Object System.Drawing.Size([int](820 * $Scale), [int](800 * $Scale)) # Размер окна (Ширина, Высота)
$form.StartPosition = "CenterScreen" # Появляется по центру экрана
$form.FormBorderStyle = "FixedDialog" # Запрещаем изменять размер окна
$form.MaximizeBox = $false # Убираем кнопку Развернуть
$form.MinimizeBox = $false # Убираем кнопку Свернуть
$form.BackColor = [System.Drawing.Color]::FromArgb(26, 26, 30) # Темно-серый фон
$form.ForeColor = [System.Drawing.Color]::White # Белый текст
$form.TopMost = $true # Поверх всех окон

# Принудительная темная полоса заголовка окна (DWM Immersive Dark Mode)
try {
    $DwmCode = @"
    using System;
    using System.Runtime.InteropServices;
    public class DWM {
        [DllImport("dwmapi.dll")]
        public static extern int DwmSetWindowAttribute(IntPtr hwnd, int attr, ref int attrValue, int attrSize);
    }
"@
    if (-not ("DWM" -as [type])) { Add-Type -TypeDefinition $DwmCode -ErrorAction SilentlyContinue }
    $darkMode = 1
    [DWM]::DwmSetWindowAttribute($form.Handle, 20, [ref]$darkMode, 4) | Out-Null # Windows 11
    [DWM]::DwmSetWindowAttribute($form.Handle, 19, [ref]$darkMode, 4) | Out-Null # Windows 10
} catch {}

$titleFont = New-Object System.Drawing.Font("Segoe UI", 16, [System.Drawing.FontStyle]::Bold) # Шрифт для заголовка
$checkFont = New-Object System.Drawing.Font("Segoe UI", 12, [System.Drawing.FontStyle]::Bold) # Шрифт для галочек
$descFont  = New-Object System.Drawing.Font("Segoe UI", 10, [System.Drawing.FontStyle]::Regular) # Шрифт для описания

$titlePanel = New-Object System.Windows.Forms.Panel # Верхняя панель
$titlePanel.Dock = [System.Windows.Forms.DockStyle]::Top # Привязываем к верху
$titlePanel.Height = [int](70 * $Scale) # Высота панели

$lblTitle = New-Object System.Windows.Forms.Label # Текст заголовка
$lblTitle.Text = (L "ВЫБЕРИТЕ ОПЦИИ ДЛЯ ОПТИМИЗАЦИИ:" "SELECT OPTIMIZATION OPTIONS:") # Текст
$lblTitle.Font = $titleFont # Применяем шрифт
$lblTitle.AutoSize = $true # Подстройка размера
$lblTitle.Location = New-Object System.Drawing.Point([int](25 * $Scale), [int](25 * $Scale)) # Отступы (X, Y)
$lblTitle.ForeColor = [System.Drawing.Color]::FromArgb(0, 200, 255) # Неоново-голубой цвет
$titlePanel.Controls.Add($lblTitle) # Добавляем текст на панель

$btnUninstall = New-Object System.Windows.Forms.Label
$btnUninstall.Text = "🗑" # Значок корзины
$btnUninstall.Font = New-Object System.Drawing.Font("Segoe UI Emoji", 16)
$btnUninstall.ForeColor = [System.Drawing.Color]::Red
$btnUninstall.Location = New-Object System.Drawing.Point([int](760 * $Scale), [int](22 * $Scale)) # Размещаем рядом со значком справки
$btnUninstall.AutoSize = $true
$btnUninstall.Cursor = [System.Windows.Forms.Cursors]::Hand

# Подсветка при наведении
$btnUninstall.Add_MouseEnter({ $this.ForeColor = [System.Drawing.Color]::White })
$btnUninstall.Add_MouseLeave({ $this.ForeColor = [System.Drawing.Color]::Red })

# Всплывающая подсказка
$toolTipUninstall = New-Object System.Windows.Forms.ToolTip
$toolTipUninstall.SetToolTip($btnUninstall, "Удалить Eastrica Optimizer и откатить систему")

$btnUninstall.Add_Click({
    $wshell = New-Object -ComObject Wscript.Shell
    $confirmTitle = L "Деинсталляция Eastrica" "Eastrica Uninstallation"
    $confirmMsg = L "Вы уверены, что хотите полностью удалить Eastrica Optimizer и откатить систему?`n`nБудет запущен скрипт Eastrica_Complete_Rollback.cmd, удалены все задачи, контекстные меню и папка программы." "Are you sure you want to completely uninstall Eastrica Optimizer and restore system defaults?`n`nThe Eastrica_Complete_Rollback.cmd script will be executed, and all custom tasks, context menus, and tools folder will be removed."
    $confirm = $wshell.Popup($confirmMsg, 0, $confirmTitle, 4 + 32)
    
    if ($confirm -eq 6) { # 6 = Нажата кнопка "Да" / Yes
        $BaseDir = "$env:SystemDrive\EastricaTools"
        $RollbackBat = $null
        
        # Ищем самый свежий бэкап в папке Backups
        if (Test-Path "$BaseDir\Backups") {
            $LatestBackup = Get-ChildItem -Path "$BaseDir\Backups" -Directory | Sort-Object CreationTime -Descending | Select-Object -First 1
            if ($LatestBackup) {
                $RollbackBat = "$($LatestBackup.FullName)\Eastrica_Complete_Rollback.cmd"
            }
        }
        
        if ($RollbackBat -and (Test-Path $RollbackBat)) {
            $wshell.Popup((L "Запуск скрипта восстановления реестра, служб и драйверов...`nПожалуйста, дождитесь завершения в окне командной строки." "Launching registry, services, and drivers restoration script...`nPlease wait for completion in the console window."), 3, (L "Откат" "Rollback"), 64) | Out-Null
            Start-Process -FilePath $RollbackBat -Verb RunAs -Wait
        } else {
            $wshell.Popup((L "Файл бэкапа (Eastrica_Complete_Rollback.cmd) не найден.`nОткат реестра невозможен. Выполняется удаление файлов и задач." "Backup file (Eastrica_Complete_Rollback.cmd) was not found.`nRegistry restore is impossible. Proceeding with file and task cleanup."), 4, (L "Предупреждение" "Warning"), 48) | Out-Null
        }

        # Удаляем задачи из Планировщика
        $Tasks = @("Eastrica_Persistence_BloatBlocker", "Eastrica_AutoPowerSwitch", "Eastrica_ManualShaderCleaner")
        foreach ($t in $Tasks) {
            Unregister-ScheduledTask -TaskName $t -Confirm:$false -ErrorAction SilentlyContinue
        }

        # Сбрасываем схему питания на стандартную Сбалансированную
        $POWER_GUID_BALANCED = "381b4222-f694-41f0-9685-ff5bb260df2e"
        powercfg -setactive $POWER_GUID_BALANCED > $null 2>&1

        # Удаляем оба контекстных меню программы с Рабочего стола
        Remove-Item -LiteralPath "HKCR:\Directory\Background\shell\EastricaTools" -Recurse -Force -ErrorAction SilentlyContinue
        Remove-Item -LiteralPath "HKCR:\Directory\Background\shell\EastricaToolsExtra" -Recurse -Force -ErrorAction SilentlyContinue

        # Удаляем контекстные меню Thread Director
        Remove-Item -LiteralPath "HKCR:\exefile\shell\EastricaThreadDirectorLaunch" -Recurse -Force -ErrorAction SilentlyContinue
        Remove-Item -LiteralPath "HKCR:\lnkfile\shell\EastricaThreadDirectorLaunch" -Recurse -Force -ErrorAction SilentlyContinue

        # Удаляем контекстное меню тумблера Брандмауэра для .exe
        Remove-Item -LiteralPath "HKCR:\exefile\shell\EastricaToggleFirewall" -Recurse -Force -ErrorAction SilentlyContinue

        # Удаляем ключи настроек GUI в реестре
        Remove-Item -LiteralPath "HKCU:\Software\Eastrica" -Recurse -Force -ErrorAction SilentlyContinue

        # Самоудаление папки EastricaTools
        $wshell.Popup((L "Деинсталляция успешно завершена! Программа будет закрыта." "Uninstallation completed successfully! The program will exit."), 3, (L "Успех" "Success"), 64) | Out-Null
        Start-Process -FilePath "cmd.exe" -ArgumentList "/c timeout /t 2 /nobreak >nul & rmdir /s /q `"$BaseDir`"" -WindowStyle Hidden
        [System.Environment]::Exit(0)
    }
})
$titlePanel.Controls.Add($btnUninstall)

$form.Controls.Add($titlePanel) # Добавляем панель в окно

$bottomPanel = New-Object System.Windows.Forms.Panel # Нижняя панель для кнопок
$bottomPanel.Dock = [System.Windows.Forms.DockStyle]::Bottom # Привязываем вниз
$bottomPanel.Height = [int](80 * $Scale) # Высота панели
$form.Controls.Add($bottomPanel) # Добавляем в окно

# Кнопка импорта профиля
$btnImport = New-Object System.Windows.Forms.Button # Создаем кнопку
$btnImport.Text = (L "Импорт" "Import") # Текст кнопки
$btnImport.Size = New-Object System.Drawing.Size([int](100 * $Scale), [int](40 * $Scale)) # Размер
$btnImport.Location = New-Object System.Drawing.Point([int](25 * $Scale), [int](20 * $Scale)) # Отступы
$btnImport.BackColor = [System.Drawing.Color]::FromArgb(50, 50, 55) # Цвет кнопки
$btnImport.ForeColor = [System.Drawing.Color]::White # Цвет текста
$btnImport.FlatStyle = "Flat" # Плоский дизайн
$btnImport.Add_Click({ # Действие при нажатии
    $openDlg = New-Object System.Windows.Forms.OpenFileDialog
    $openDlg.Filter = "JSON Profile (*.json)|*.json"
    if ($openDlg.ShowDialog() -eq "OK") {
        try {
            $loaded = Get-Content -Path $openDlg.FileName -Raw | ConvertFrom-Json
            foreach ($prop in $loaded.psobject.properties) {
                if ($checkBoxes.ContainsKey($prop.Name)) { $checkBoxes[$prop.Name].Checked = [bool]$prop.Value }
            }
            [System.Windows.Forms.MessageBox]::Show((L "Профиль загружен!" "Profile loaded!"), (L "Успех" "Success"), 0, 64)
        } catch {
            [System.Windows.Forms.MessageBox]::Show((L "Ошибка чтения файла JSON." "Error reading JSON file."), (L "Ошибка" "Error"), 0, 16)
        }
    }
})
$bottomPanel.Controls.Add($btnImport)

# Кнопка экспорта профиля
$btnExport = New-Object System.Windows.Forms.Button
$btnExport.Text = (L "Экспорт" "Export")
$btnExport.Size = New-Object System.Drawing.Size([int](100 * $Scale), [int](40 * $Scale))
$btnExport.Location = New-Object System.Drawing.Point([int](135 * $Scale), [int](20 * $Scale))
$btnExport.BackColor = [System.Drawing.Color]::FromArgb(50, 50, 55)
$btnExport.ForeColor = [System.Drawing.Color]::White
$btnExport.FlatStyle = "Flat"
$btnExport.Add_Click({
    $saveDlg = New-Object System.Windows.Forms.SaveFileDialog
    $saveDlg.Filter = "JSON Profile (*.json)|*.json"
    $saveDlg.FileName = "EastricaProfile.json"
    if ($saveDlg.ShowDialog() -eq "OK") {
        $profileObj = New-Object PSObject
        foreach ($key in $checkBoxes.Keys) { $profileObj | Add-Member -MemberType NoteProperty -Name $key -Value $checkBoxes[$key].Checked }
        $profileObj | ConvertTo-Json -Depth 5 | Set-Content -Path $saveDlg.FileName -Encoding UTF8
        [System.Windows.Forms.MessageBox]::Show((L "Профиль сохранен!" "Profile saved!"), (L "Успех" "Success"), 0, 64)
    }
})
$bottomPanel.Controls.Add($btnExport)

# Кнопка Builder Mode
$btnBuilder = New-Object System.Windows.Forms.Button 
$btnBuilder.Text = (L "Создать Autounattend.xml" "Create Autounattend.xml")
$btnBuilder.Size = New-Object System.Drawing.Size([int](200 * $Scale), [int](40 * $Scale)) 
$btnBuilder.Location = New-Object System.Drawing.Point([int](245 * $Scale), [int](20 * $Scale)) 
$btnBuilder.BackColor = [System.Drawing.Color]::DarkOrchid 
$btnBuilder.ForeColor = [System.Drawing.Color]::White 
$btnBuilder.FlatStyle = "Flat" 
$btnBuilder.Add_Click({ 
    $ScriptPath = $global:ScriptSourcePath
    $ScriptContent = Get-Content -Path $ScriptPath -Raw -Encoding UTF8
    $ScriptContent = $ScriptContent.Replace('$result = $form.ShowDialog()', '$result = [System.Windows.Forms.DialogResult]::OK')
    foreach ($key in $checkBoxes.Keys) {
        $varName = if ($key -eq "AIOpt") { "AI" } else { $key }
        $val = if ($checkBoxes[$key].Checked) { "`$true" } else { "`$false" }
        $pattern = '\$global:Opt' + $varName + '\s*=\s*\$checkBoxes\["' + $key + '"\]\.Checked'
        $ScriptContent = $ScriptContent -replace $pattern, "`$global:Opt$varName = $val"
    }
    $ScriptContent = $ScriptContent -replace '(?m)^\s*\$GamePaths\s*=\s*Show-FileDialog-STA.*', '$$GamePaths = @()'
    $ScriptContent = $ScriptContent -replace '(?m)^\s*\$FolderPath\s*=\s*Show-FolderBrowser-STA.*', '$$FolderPath = $$null'
    $ScriptContent = $ScriptContent -replace '(?m)^\s*\$CustomAIFiles\s*=\s*Show-FileDialog-STA.*', '$$CustomAIFiles = @()'
    $ScriptContent = $ScriptContent -replace 'Read-Host "Нажмите Enter для выхода..."', ''
    $Utf8Preamble = [System.Text.Encoding]::UTF8.GetPreamble()
    $ScriptBytes = [System.Text.Encoding]::UTF8.GetBytes($ScriptContent)
    $Bytes = New-Object byte[] ($Utf8Preamble.Length + $ScriptBytes.Length)
    [Array]::Copy($Utf8Preamble, 0, $Bytes, 0, $Utf8Preamble.Length)
    [Array]::Copy($ScriptBytes, 0, $Bytes, $Utf8Preamble.Length, $ScriptBytes.Length)
    $B64 = [Convert]::ToBase64String($Bytes)
    $ChunkSize = 4000
    $TotalChunks = [Math]::Ceiling($B64.Length / $ChunkSize)
    $XmlChunks = ""
    $order = 10
    for ($i = 0; $i -lt $TotalChunks; $i++) {
        $start = $i * $ChunkSize
        $len = [Math]::Min($ChunkSize, $B64.Length - $start)
        $chunk = $B64.Substring($start, $len)
        $XmlChunks += "        <SynchronousCommand wcm:action=`"add`"><Order>$order</Order><CommandLine>powershell -NoProfile -Command `"Add-Content -Value '$chunk' -Path `"`$env:SystemDrive\Eastrica.b64`" -NoNewline`"</CommandLine></SynchronousCommand>`n"
        $order++
    }
    $XmlChunks += "        <SynchronousCommand wcm:action=`"add`"><Order>$order</Order><CommandLine>powershell -NoProfile -Command `"`$drv = [Environment]::GetEnvironmentVariable('SystemDrive'); `$b = (Get-Content \`"`$drv\Eastrica.b64\`" -Raw) -replace '\s',''; [IO.File]::WriteAllBytes(\`"`$drv\EastricaBooster.ps1\`", [Convert]::FromBase64String(`$b))`"</CommandLine></SynchronousCommand>`n"
    $order++
    $XmlChunks += "        <SynchronousCommand wcm:action=`"add`"><Order>$order</Order><CommandLine>powershell -NoProfile -ExecutionPolicy Bypass -File `"%SystemDrive%\EastricaBooster.ps1`" -Unattended</CommandLine></SynchronousCommand>`n"
    $order++
    $XmlChunks += "        <SynchronousCommand wcm:action=`"add`"><Order>$order</Order><CommandLine>cmd /c del %SystemDrive%\Eastrica.b64 /f /q</CommandLine></SynchronousCommand>`n"
    $order++
    $XmlChunks += "        <SynchronousCommand wcm:action=`"add`"><Order>$order</Order><CommandLine>cmd /c del %SystemDrive%\EastricaBooster.ps1 /f /q</CommandLine></SynchronousCommand>`n"

    $xmlContent = @"
<?xml version="1.0" encoding="utf-8"?>
<unattend xmlns="urn:schemas-microsoft-com:unattend">
  <settings pass="windowsPE">
    <component name="Microsoft-Windows-Setup" processorArchitecture="amd64" publicKeyToken="31bf3856ad364e35" language="neutral" versionScope="nonSxS">
      <RunSynchronous>
        <RunSynchronousCommand wcm:action="add"><Order>1</Order><Path>reg add HKLM\SYSTEM\Setup\LabConfig /v BypassTPMCheck /t REG_DWORD /d 1 /f</Path></RunSynchronousCommand>
        <RunSynchronousCommand wcm:action="add"><Order>2</Order><Path>reg add HKLM\SYSTEM\Setup\LabConfig /v BypassSecureBootCheck /t REG_DWORD /d 1 /f</Path></RunSynchronousCommand>
        <RunSynchronousCommand wcm:action="add"><Order>3</Order><Path>reg add HKLM\SYSTEM\Setup\LabConfig /v BypassRAMCheck /t REG_DWORD /d 1 /f</Path></RunSynchronousCommand>
        <RunSynchronousCommand wcm:action="add"><Order>4</Order><Path>reg add HKLM\SYSTEM\Setup\LabConfig /v BypassStorageCheck /t REG_DWORD /d 1 /f</Path></RunSynchronousCommand>
      </RunSynchronous>
      <UserData><AcceptEula>true</AcceptEula></UserData>
    </component>
  </settings>
  <settings pass="oobeSystem">
    <component name="Microsoft-Windows-Shell-Setup" processorArchitecture="amd64" publicKeyToken="31bf3856ad364e35" language="neutral" versionScope="nonSxS">
      <OOBE>
        <HideEULAPage>true</HideEULAPage>
        <HideOnlineAccountScreens>true</HideOnlineAccountScreens>
        <ProtectYourPC>3</ProtectYourPC>
      </OOBE>
      <UserAccounts>
        <LocalAccounts>
          <LocalAccount wcm:action="add">
            <Name>Admin</Name><Group>Administrators</Group><Password><Value></Value><PlainText>true</PlainText></Password>
          </LocalAccount>
        </LocalAccounts>
      </UserAccounts>
      <AutoLogon><Password><Value></Value><PlainText>true</PlainText></Password><Enabled>true</Enabled><LogonCount>1</LogonCount><Username>Admin</Username></AutoLogon>
      <FirstLogonCommands>
        <SynchronousCommand wcm:action="add"><Order>1</Order><CommandLine>powercfg -h off</CommandLine></SynchronousCommand>
$XmlChunks      </FirstLogonCommands>
    </component>
  </settings>
</unattend>
"@
    $desktop = [Environment]::GetFolderPath("Desktop")
    # Записываем XML строго в UTF-8 без BOM для совместимости с установщиком Windows
    [System.IO.File]::WriteAllText("$desktop\autounattend.xml", $xmlContent, (New-Object System.Text.UTF8Encoding $false))
    [System.Windows.Forms.MessageBox]::Show((L "Файл autounattend.xml создан на Рабочем столе!" "autounattend.xml created on Desktop!"), "Builder Mode", 0, 64)
})
$bottomPanel.Controls.Add($btnBuilder) 

# Кнопка "Применить и начать"
$btnApply = New-Object System.Windows.Forms.Button
$btnApply.Text = (L "ПРИМЕНИТЬ И НАЧАТЬ" "APPLY AND START")
$btnApply.Size = New-Object System.Drawing.Size([int](260 * $Scale), [int](40 * $Scale))
$btnApply.Location = New-Object System.Drawing.Point([int](455 * $Scale), [int](20 * $Scale))
$btnApply.BackColor = [System.Drawing.Color]::FromArgb(0, 120, 215)
$btnApply.ForeColor = [System.Drawing.Color]::White
$btnApply.FlatStyle = "Flat"
