# Создание каталога бэкапа реестра и инициализация контроллеров устройств
$RegDir = "$BackupDir\Registry_Backup"
if (!(Test-Path $RegDir)) { New-Item -ItemType Directory -Force -Path $RegDir > $null }

$GPU_Adapters = $global:GPUs
$USB_Controllers = Get-CimInstance Win32_USBController 2>> $env:SystemDrive\EastricaTools\Eastrica_ErrorTrace.log

# ЭТАП 1: Добавление команд импорта всех сохраненных .reg файлов (без лишнего спама в консоль)
foreach ($Name in $RegKeysToBackup.Keys) {
    $psPath = $RegKeysToBackup[$Name]
    $cmdPath = $psPath -replace "^HKLM:\\", "HKLM\" -replace "^HKCU:\\", "HKCU\" -replace "^HKCR:\\", "HKCR\"
    $File = "$RegDir\$Name.reg"
    Write-Host " ► Экспорт: $Name..." -NoNewline
    
    if (Test-Path -Path $psPath 2>> $env:SystemDrive\EastricaTools\Eastrica_ErrorTrace.log) {
        cmd /c "reg export `"$cmdPath`" `"$File`" /y >nul 2>&1"
        
        if ((Test-Path -LiteralPath $File) -and ((Get-Item -LiteralPath $File).Length -gt 0)) {
            Write-Host "[OK]" -ForegroundColor DarkGray
            Add-Content -Path $RestoreScript -Value "reg import `"%~dp0Registry_Backup\$Name.reg`" >nul 2>&1" -Encoding Default
        } else {
            Write-Host "[FAIL]" -ForegroundColor Red
        }
    } else {
        Write-Host "[WARNING]" -ForegroundColor Yellow
    }
}

# Экспорт и добавление отката аппаратных прерываний MSI для видеокарт
if ($GPU_Adapters) {
    foreach ($gpu in $GPU_Adapters) {
        if ($gpu.PNPDeviceID) {
            $GpuCleanName = Clean-FileName -Name $gpu.Name
            $PnpID = $gpu.PNPDeviceID
            $RegPathCMD = "HKLM\SYSTEM\CurrentControlSet\Enum\$PnpID\Device Parameters\Interrupt Management"
            $SaveFile   = "$RegDir\MSI_GPU_$GpuCleanName.reg"
            if (Test-Path "HKLM:\SYSTEM\CurrentControlSet\Enum\$PnpID\Device Parameters\Interrupt Management") {
                cmd /c "reg export `"$RegPathCMD`" `"$SaveFile`" /y >nul 2>&1"
                if (Test-Path $SaveFile) {
                    Add-Content -Path $RestoreScript -Value "reg import `"%~dp0Registry_Backup\MSI_GPU_$GpuCleanName.reg`" >nul 2>&1" -Encoding Default
                }
            }
        }
    }
}

# Экспорт и добавление отката аппаратных прерываний MSI для USB-контроллеров
if ($USB_Controllers) {
    foreach ($usb in $USB_Controllers) {
        if ($usb.Name -match "xHCI|3\.0|3\.1" -and $usb.PNPDeviceID) {
            $UsbCleanName = Clean-FileName -Name $usb.Name
            $PnpID = $usb.PNPDeviceID
            $RegPathCMD = "HKLM\SYSTEM\CurrentControlSet\Enum\$PnpID\Device Parameters\Interrupt Management"
            $SaveFile   = "$RegDir\MSI_USB_$UsbCleanName.reg"
            if (Test-Path "HKLM:\SYSTEM\CurrentControlSet\Enum\$PnpID\Device Parameters\Interrupt Management") {
                cmd /c "reg export `"$RegPathCMD`" `"$SaveFile`" /y >nul 2>&1"
                if (Test-Path $SaveFile) {
                    Add-Content -Path $RestoreScript -Value "reg import `"%~dp0Registry_Backup\MSI_USB_$UsbCleanName.reg`" >nul 2>&1" -Encoding Default
                }
            }
        }
    }
}

# ЭТАП 2: Восстановление заводского профиля видеокарты NVIDIA (NPI)
