Add-Content -Path $RestoreScript -Value "echo [6/8] Сброс сетевого стека и включение протоколов..." -Encoding Default
Add-Content -Path $RestoreScript -Value "netsh int ip reset >nul 2>&1" -Encoding Default
Add-Content -Path $RestoreScript -Value "netsh winsock reset >nul 2>&1" -Encoding Default
