Add-Content -Path $RestoreScript -Value "echo." -Encoding Default
Add-Content -Path $RestoreScript -Value "pause" -Encoding Default

# Функция экстренного "лечения" службы восстановления системы, если она сломана
function Repair-SystemRestore {
    Write-Host "[REPAIR] Запуск процедуры восстановления службы System Restore..." -ForegroundColor Magenta

    # 1. Включение критических служб (Теневое копирование тома)
    $Services = @("VSS", "swprv")
    foreach ($Svc in $Services) {
        try {
            Apply-Tweak "Включение службы теневого копирования $Svc" { Set-Service -Name $Svc -StartupType Automatic *>&1 | Out-File -FilePath $global:LogPath -Append -Encoding UTF8 } # Ставим тип запуска АВТО
            if ((Get-Service -Name $Svc).Status -ne 'Running') {
                Apply-Tweak "Запуск службы $Svc" { Start-Service -Name $Svc *>&1 | Out-File -FilePath $global:LogPath -Append -Encoding UTF8 } # Запускаем службу
            }
        } catch {
            Write-Warning "► Не удалось запустить службу $Svc."
        }
    }

    # 2. Исправление реестра (Снятие блокировки админом)
    $RegKeys = @("HKLM:\SOFTWARE\Microsoft\Windows NT\CurrentVersion\SystemRestore", "HKLM:\SOFTWARE\Policies\Microsoft\Windows NT\SystemRestore")
    foreach ($Key in $RegKeys) {
        if (Test-Path $Key) {
            Apply-Tweak "Удаление блокировки Защиты системы в $Key" { Remove-ItemProperty -Path $Key -Name "DisableSR" *>&1 | Out-File -FilePath $global:LogPath -Append -Encoding UTF8 } # Удаляем блокирующий ключ Защиты системы
            Apply-Tweak "Удаление запрета конфигурации в $Key" { Remove-ItemProperty -Path $Key -Name "DisableConfig" *>&1 | Out-File -FilePath $global:LogPath -Append -Encoding UTF8 } # Удаляем ключ запрета конфигурации
            Apply-Tweak "Отключение лимита на частоту точек восстановления" { Set-ItemProperty -Path $Key -Name "SystemRestorePointCreationFrequency" -Value 0 -Type DWord -Force *>&1 | Out-File -FilePath $global:LogPath -Append -Encoding UTF8 } # Отключаем лимит на 1 точку в 24 часа
        }
    }

    # 3. Настройка выделенного места на диске через vssadmin
    Apply-Tweak "Добавление теневого хранилища (10% диска)" { cmd /c "vssadmin add shadowstorage /for=$env:SystemDrive /on=$env:SystemDrive /maxsize=10%" *>&1 | Out-File -FilePath $global:LogPath -Append -Encoding UTF8 }
    Apply-Tweak "Изменение размера теневого хранилища до 10%" { cmd /c "vssadmin resize shadowstorage /for=$env:SystemDrive /on=$env:SystemDrive /maxsize=10%" *>&1 | Out-File -FilePath $global:LogPath -Append -Encoding UTF8 }

    # 4. Принудительное включение защиты на диске C
    try {
        Apply-Tweak "Активация защиты диска $env:SystemDrive\" { Enable-ComputerRestore -Drive "$env:SystemDrive\" -ErrorAction Stop } # Включаем
        return $true
    } catch {
        Write-Warning "► Ошибка при активации Enable-ComputerRestore."
        return $false
    }
}

Write-Host ""
# Предварительно выделяем 5% объема диска C: под теневые снимки VSS, чтобы Checkpoint-Computer гарантированно не упал из-за нехватки квоты
Apply-Tweak "Предварительное расширение квоты теневого хранилища VSS до 5%" {
    cmd.exe /c "vssadmin resize shadowstorage /for=$env:SystemDrive /on=$env:SystemDrive /maxsize=5% >nul 2>&1"
    if ($LASTEXITCODE -ne 0) {
        # Если ассоциация хранилища еще не была создана в системе, создаем ее с нуля
        cmd.exe /c "vssadmin add shadowstorage /for=$env:SystemDrive /on=$env:SystemDrive /maxsize=5% >nul 2>&1"
    }
    $global:LASTEXITCODE = 0
}

$SR_Key = "HKLM:\SOFTWARE\Microsoft\Windows NT\CurrentVersion\SystemRestore"
if (Test-Path $SR_Key) {
    Apply-Tweak "Снятие лимита на создание точек восстановления" { Set-ItemProperty -Path $SR_Key -Name "SystemRestorePointCreationFrequency" -Value 0 -Type DWord -Force *>&1 | Out-File -FilePath $global:LogPath -Append -Encoding UTF8 } # Заранее убираем лимит создания точек (разрешаем чаще 1 раза в сутки)
}

try {
    # Первая попытка создания точки восстановления
    Apply-Tweak "Создание точки восстановления (Eastrica_Full_Backup_$(Get-Date -Format 'yyyyMMdd_HHmm'))" { Checkpoint-Computer -Description "Eastrica_Full_Backup_$(Get-Date -Format 'yyyyMMdd_HHmm')" -RestorePointType "MODIFY_SETTINGS" -ErrorAction Stop }

} catch {
    Write-Warning "[ERROR] Не удалось создать точку восстановления. Запускаем лечение..."
    Write-Warning " Код ошибки: $($_.Exception.Message)"
    
    # Запуск функции "лечения" службы восстановления
    Repair-SystemRestore
    
    Start-Sleep -Seconds 3 # Пауза для того, чтобы запущенные службы (VSS) успели проинициализироваться
    
    Write-Host "Повторная попытка создания..." -ForegroundColor Yellow
    try {
        # Вторая попытка после лечения
        Apply-Tweak "Повторное создание точки восстановления после лечения" { Checkpoint-Computer -Description "Eastrica_Full_Backup_$(Get-Date -Format 'yyyyMMdd_HHmm')" -RestorePointType "MODIFY_SETTINGS" -ErrorAction Stop }
    } catch {
        Write-Host "[FAIL] КРИТИЧЕСКАЯ ОШИБКА. Восстановить работу службы не удалось." -ForegroundColor DarkGray
        Write-Host " Возможные причины: повреждение WMI, повреждение файловой системы или отключение компонентов Windows." -ForegroundColor DarkGray
    }
}

Apply-Tweak "Очистка кэша ARP и таблицы маршрутизации" { cmd.exe /c "netsh interface ip delete arpcache >nul 2>&1"; $global:LASTEXITCODE = 0 }
Apply-Tweak "Сброс каталогов Winsock" { cmd.exe /c "netsh winsock reset >nul 2>&1" *>&1 | Out-File -FilePath $global:LogPath -Append -Encoding UTF8 } # Сброс каталогов Winsock
Apply-Tweak "Очистка DNS Resolver (ipconfig /flushdns)" { ipconfig /flushdns *>&1 | Out-File -FilePath $global:LogPath -Append -Encoding UTF8 } # Очищаем DNS Resolver

Write-Host ""
function Build-RegistryRollbackScript {
    $RollbackScriptPath = "$BackupDir\Eastrica_Registry_Rollback.ps1"
    $RollbackHeader = @'
# ==========================================================
# Eastrica Ultimate - точечное восстановление системы
# ==========================================================
if (!([Security.Principal.WindowsPrincipal][Security.Principal.WindowsIdentity]::GetCurrent()).IsInRole([Security.Principal.WindowsBuiltInRole] "Administrator")) {
    Start-Process powershell.exe -ArgumentList "-NoProfile -ExecutionPolicy Bypass -File `"$PSCommandPath`"" -Verb RunAs
    Exit
}
Write-Host "Запуск точечного возврата изменений реестра..." -ForegroundColor Cyan
$ErrorActionPreference = "SilentlyContinue"
$SuccessCount = 0
$FailCount = 0
'@
    Set-Content -Path $RollbackScriptPath -Value $RollbackHeader -Encoding UTF8
    if (Test-Path $global:ChangeHistoryPath) {
        $HistoryLines = Get-Content $global:ChangeHistoryPath -Encoding UTF8
        foreach ($Line in $HistoryLines) {
            if (-not [string]::IsNullOrWhiteSpace($Line) -and $Line -notmatch "^#") {
                $WrappedLine = @"
try {
    $Line
    `$SuccessCount++
} catch {
    `$FailCount++
}
"@
                Add-Content -Path $RollbackScriptPath -Value $WrappedLine -Encoding UTF8
            }
        }
    }
    $RollbackFooter = @'
Write-Host ""
Write-Host "Восстановление завершено!" -ForegroundColor DarkGray
Write-Host "Успешно возвращено ключей/состояний: $SuccessCount" -ForegroundColor DarkGray
if ($FailCount -gt 0) { Write-Host "Ошибок при восстановлении: $FailCount" -ForegroundColor Red }
Write-Host "Пожалуйста, перезагрузите компьютер." -ForegroundColor Yellow
Read-Host "Нажмите Enter для выхода..."
'@
    Add-Content -Path $RollbackScriptPath -Value $RollbackFooter -Encoding UTF8
    Write-Host " ► Деинсталлятор твиков реестра создан: $RollbackScriptPath" -ForegroundColor DarkGray
}

Write-Host ""
# ==============================================================================
# Раздел 8: Электропитание (Ultimate Performance и P/E-Cores)
# ==============================================================================
Show-ProgressStep -StepNum 8 -TotalSteps 81 -Activity "Активация плана 'Максимальная производительность'..."
Write-Host "==============================================================================" -ForegroundColor DarkGray
Write-Host "РАЗДЕЛ 8: ЭЛЕКТРОПИТАНИЕ (ULTIMATE PERFORMANCE И P/E-CORES)" -ForegroundColor Cyan
Write-Host "==============================================================================" -ForegroundColor DarkGray

$POWER_GUID_BALANCED  = '381b4222-f694-41f0-9685-ff5bb260df2e' # Системный GUID "Сбалансированной" схемы питания
$POWER_GUID_ULTIMATE  = 'e9a42b02-d5df-448d-aa00-03f14749eb61' # Системный GUID "Максимальной производительности"

$AllSchemes = powercfg /list # Запрашиваем список всех существующих схем питания в ОС
# Поиск схемы строго по аппаратному GUID или эксклюзивному имени Ultimate Performance
$UltimateSchemes = $AllSchemes | Select-String -Pattern "e9a42b02-d5df-448d-aa00-03f14749eb61|Ultimate|Максимальная производительность"

$global:TargetGUID = $null # Инициализируем пустую переменную для целевого GUID схемы

if ($UltimateSchemes) {
    # Если схема уже есть в системе, берем первую найденную
    $firstMatch = $UltimateSchemes | Select-Object -First 1 # Выбираем первый совпавший элемент
    $line = if ($firstMatch -is [System.Text.RegularExpressions.Match]) { $firstMatch.Value } else { $firstMatch.ToString() } # Преобразуем в строку
    if ($line -match "([a-f0-9]{8}-[a-f0-9]{4}-[a-f0-9]{4}-[a-f0-9]{4}-[a-f0-9]{12})") { $global:TargetGUID = $matches[1] } # Извлекаем GUID регулярным выражением
    
    # Очистка мусора: удаляем все накопившиеся дубликаты, оставляя только один план
    if (@($UltimateSchemes).Count -gt 1) {
        Write-Host " ► Удаление накопившихся дублей схем питания..." -ForegroundColor DarkGray
        Apply-Tweak "Временное переключение на Сбалансированный план" { powercfg -setactive $POWER_GUID_BALANCED *>&1 | Out-File -FilePath $global:LogPath -Append -Encoding UTF8 } # Временно переключаемся на баланс, чтобы ОС отпустила профили
        for ($i = 1; $i -lt @($UltimateSchemes).Count; $i++) { 
            if ($UltimateSchemes[$i].ToString() -match "([a-f0-9]{8}-[a-f0-9]{4}-[a-f0-9]{4}-[a-f0-9]{4}-[a-f0-9]{12})") {
                $DupGUID = $matches[1]
                Apply-Tweak "Удаление дубликата схемы ($DupGUID)" { powercfg -delete $DupGUID *>&1 | Out-File -FilePath $global:LogPath -Append -Encoding UTF8 }
            }
        }
    }
} else {
    # Если схемы нет вообще (на некоторых редакциях Win10/11) - создаем её принудительно
    $result = powercfg -duplicatescheme $POWER_GUID_ULTIMATE # Дублируем скрытую системную схему
    Apply-Tweak "Создание схемы 'Максимальная производительность'" { if ($result -match "([a-f0-9]{8}-[a-f0-9]{4}-[a-f0-9]{4}-[a-f0-9]{4}-[a-f0-9]{12})") { $global:TargetGUID = $matches[1] } }
}

if ($global:TargetGUID -and ($global:TargetGUID -match "^[a-f0-9]{8}-[a-f0-9]{4}-[a-f0-9]{4}-[a-f0-9]{4}-[a-f0-9]{12}$")) {
    Apply-Tweak "Активация плана 'Максимальная производительность'" { powercfg -setactive $global:TargetGUID *>&1 | Out-File -FilePath $global:LogPath -Append -Encoding UTF8 } # Активируем найденную/созданную схему Максимальной производительности
} else {
    Write-Warning "Не удалось создать/найти схему Ultimate Performance. Используем Высокую производительность." # Предупреждение при ошибке
    $global:TargetGUID = "8c5e7fda-e8bf-4a96-9a85-a6e23a8c635c"
    Apply-Tweak "Активация плана 'Высокая производительность' (Резерв)" { powercfg -setactive $global:TargetGUID *>&1 | Out-File -FilePath $global:LogPath -Append -Encoding UTF8 } # Активируем план Высокой производительности как резервный вариант
}

# Запрет отключения шины PCI-E (Link State Power Management)
Apply-Tweak "Запрет отключения шины PCI-E от сети (ASPM Off)" { powercfg -setacvalueindex scheme_current SUB_PCIEXPRESS ASPM 0 *>&1 | Out-File -FilePath $global:LogPath -Append -Encoding UTF8 } # Отключаем сон PCIe при питании от сети (Макс. отзывчивость видеокарты)
Apply-Tweak "Включение среднего сна PCI-E от батареи (ASPM)" { powercfg -setdcvalueindex scheme_current SUB_PCIEXPRESS ASPM 1 *>&1 | Out-File -FilePath $global:LogPath -Append -Encoding UTF8 } # Включаем средний уровень сна PCIe от батареи (Экономия заряда)

# Принудительная активная политика охлаждения
Apply-Tweak "Принудительная активная политика охлаждения (SysCoolPol)" { powercfg -setacvalueindex scheme_current SUB_PROCESSOR SYSCOOLPOL 1 *>&1 | Out-File -FilePath $global:LogPath -Append -Encoding UTF8 } # Кулеры начинают вращаться до того, как процессор начнет троттлить

# Отключение фонового эко-троттлинга процессора (Power Throttling)
$PowerThrottlingKey = "HKLM:\SYSTEM\CurrentControlSet\Control\Power\PowerThrottling"
if (!(Test-Path $PowerThrottlingKey)) { Apply-Tweak "Создание раздела PowerThrottling" { New-Item -Path $PowerThrottlingKey -Force *>&1 | Out-File -FilePath $global:LogPath -Append -Encoding UTF8 } } # Создаем раздел в реестре

# Оставляем инфраструктуру Power Throttling активной (Значение 0), чтобы работали точечные IFEO-правила EcoQoS для браузеров и лаунчеров.
Apply-Tweak "Включение инфраструктуры Power Throttling (Для работы EcoQoS)" { Set-ItemProperty -Path $PowerThrottlingKey -Name "PowerThrottlingOff" -Value 0 -Type DWord -Force *>&1 | Out-File -FilePath $global:LogPath -Append -Encoding UTF8 }

# Настройка порогов процессора (Utility Handling)
# 12a0ab44-fe28-4fa9-b3bd-4b64f44960a6 = Processor performance decrease threshold (Порог снижения частоты)
Apply-Tweak "Оптимизация порога снижения частоты CPU при простое (10%)" { Set-SafeCpuPower "12a0ab44-fe28-4fa9-b3bd-4b64f44960a6" 10 10 } # Устанавливаем сбалансированный порог снижения частоты (10% вместо 0%), что позволяет процессору снижать частоту и охлаждаться при отсутствии реальной нагрузки.

# 4d2b0152-7d5c-498b-88e2-34345392a2c5 = реакция планировщика на прерывания
if ($global:IsLaptop) {
    Apply-Tweak "Установка интервала проверки процессора (10мс для ноутбука)" { Set-SafeCpuPower "4d2b0152-7d5c-498b-88e2-34345392a2c5" 10 10 } # Для ноутбуков задаем балансный интервал (10 мс)
} else {
    Apply-Tweak "Установка интервала проверки процессора (1мс для ПК)" { Set-SafeCpuPower "4d2b0152-7d5c-498b-88e2-34345392a2c5" 1 1 } # Для ПК ставим абсолютный минимум (1 мс). Значение 0 недопустимо ядром ОС!
}

# Восстанавливаем способность ядер засыпать (Critical for AMD PBO & Intel TurboBoost)
Apply-Tweak "Разблокировка настройки засыпания ядер (IDLEDISABLE)" { powercfg -attributes SUB_PROCESSOR IDLEDISABLE -ATTRIB_HIDE *>&1 | Out-File -FilePath $global:LogPath -Append -Encoding UTF8 } # Делаем настройку видимой
Apply-Tweak "Разрешение ядрам засыпать от сети (Для работы TurboBoost/PBO)" { powercfg -setacvalueindex scheme_current SUB_PROCESSOR IDLEDISABLE 0 *>&1 | Out-File -FilePath $global:LogPath -Append -Encoding UTF8 } # 0 = Разрешаем ядрам простаивать (Если ядра не спят, они не могут буститься выше базовой частоты)
Apply-Tweak "Разрешение ядрам засыпать от батареи" { powercfg -setdcvalueindex scheme_current SUB_PROCESSOR IDLEDISABLE 0 *>&1 | Out-File -FilePath $global:LogPath -Append -Encoding UTF8 } # То же самое для батареи

# Разблокировка скрытой настройки планировщика "Heterogeneous thread scheduling policy"
Apply-Tweak "Разблокировка политики гетерогенных потоков" { powercfg -attributes SUB_PROCESSOR 7f2f5cfa-f10c-4823-b5e1-e93ae85f46b5 -ATTRIB_HIDE *>&1 | Out-File -FilePath $global:LogPath -Append -Encoding UTF8 } # Раскрываем настройку
Apply-Tweak "Запуск активных задач строго на P-Cores" { powercfg -setacvalueindex scheme_current SUB_PROCESSOR 7f2f5cfa-f10c-4823-b5e1-e93ae85f46b5 1 *>&1 | Out-File -FilePath $global:LogPath -Append -Encoding UTF8 } # 1 = Загоняем все активные задачи строго на мощные P-Cores (Intel 12+)

# Максимальная частота процессора
Apply-Tweak "Безлимитная максимальная частота процессора (PROCFREQMAX)" { powercfg /setacvalueindex scheme_current SUB_PROCESSOR PROCFREQMAX 0 *>&1 | Out-File -FilePath $global:LogPath -Append -Encoding UTF8 } # 0 = Безлимитная частота процессора (Нет искусственного капа)

# Управление частотой процессора (Hardware P-States / Autonomous C-State)
Apply-Tweak "Разблокировка аппаратного управления частотой (PERFAUTONOMOUS)" { powercfg -attributes SUB_PROCESSOR PERFAUTONOMOUS -ATTRIB_HIDE *>&1 | Out-File -FilePath $global:LogPath -Append -Encoding UTF8 } # Раскрываем настройку
Apply-Tweak "Включение Speed Shift / CPPC от сети" { powercfg -setacvalueindex scheme_current SUB_PROCESSOR PERFAUTONOMOUS 1 *>&1 | Out-File -FilePath $global:LogPath -Append -Encoding UTF8 } # 1 = Включаем аппаратное управление частотой самим процессором (Intel Speed Shift / AMD CPPC)
Apply-Tweak "Включение Speed Shift / CPPC от батареи" { powercfg -setdcvalueindex scheme_current SUB_PROCESSOR PERFAUTONOMOUS 1 *>&1 | Out-File -FilePath $global:LogPath -Append -Encoding UTF8 } # То же для батареи

# Пропуск тактов процессором (Processor Duty Cycling)
Apply-Tweak "Разблокировка пропуска тактов (PERFDUTYCYCLING)" { powercfg -attributes SUB_PROCESSOR PERFDUTYCYCLING -ATTRIB_HIDE *>&1 | Out-File -FilePath $global:LogPath -Append -Encoding UTF8 } # Раскрываем настройку
Apply-Tweak "Отключение программного пропуска тактов от сети" { powercfg -setacvalueindex scheme_current SUB_PROCESSOR PERFDUTYCYCLING 0 *>&1 | Out-File -FilePath $global:LogPath -Append -Encoding UTF8 } # Отключаем программный пропуск тактов (Duty Cycling) от сети
Apply-Tweak "Включение пропуска тактов от батареи (Экономия)" { powercfg -setdcvalueindex scheme_current SUB_PROCESSOR PERFDUTYCYCLING 1 *>&1 | Out-File -FilePath $global:LogPath -Append -Encoding UTF8 } # Включаем пропуск тактов от батареи для жесткой экономии энергии

# Режим усиления производительности (Boost Mode)
Apply-Tweak "Разблокировка турбо-буста (PERFBOOSTMODE)" { powercfg -attributes SUB_PROCESSOR PERFBOOSTMODE -ATTRIB_HIDE *>&1 | Out-File -FilePath $global:LogPath -Append -Encoding UTF8 } # Раскрываем настройку
if ($global:IsLaptop) {
    Apply-Tweak "Установка стандартного турбо-буста от сети" { powercfg -setacvalueindex scheme_current SUB_PROCESSOR PERFBOOSTMODE 1 *>&1 | Out-File -FilePath $global:LogPath -Append -Encoding UTF8 } # 1 = Включен (Стандартный турбо-буст без агрессии)
    Apply-Tweak "Установка стандартного турбо-буста от батареи" { powercfg -setdcvalueindex scheme_current SUB_PROCESSOR PERFBOOSTMODE 1 *>&1 | Out-File -FilePath $global:LogPath -Append -Encoding UTF8 } # То же для батареи
} else {
    Apply-Tweak "Установка агрессивного турбо-буста от сети" { powercfg -setacvalueindex scheme_current SUB_PROCESSOR PERFBOOSTMODE 2 *>&1 | Out-File -FilePath $global:LogPath -Append -Encoding UTF8 } # 2 = Агрессивный (Все ядра бустятся до максимума при малейшей нагрузке)
    Apply-Tweak "Установка агрессивного турбо-буста от батареи" { powercfg -setdcvalueindex scheme_current SUB_PROCESSOR PERFBOOSTMODE 2 *>&1 | Out-File -FilePath $global:LogPath -Append -Encoding UTF8 } # То же для батареи
}

# Минимальное состояние процессора (Снижение шума кулеров в простое)
Apply-Tweak "Снижение мин. состояния CPU до 5% от сети (Тишина)" { powercfg /setacvalueindex scheme_current SUB_PROCESSOR PROCTHROTTLEMIN 5 *>&1 | Out-File -FilePath $global:LogPath -Append -Encoding UTF8 } # Позволяет процессору скидывать частоту до 5% в полном простое, чтобы кулеры затихали
Apply-Tweak "Снижение мин. состояния CPU до 5% от батареи (Тишина)" { powercfg /setdcvalueindex scheme_current SUB_PROCESSOR PROCTHROTTLEMIN 5 *>&1 | Out-File -FilePath $global:LogPath -Append -Encoding UTF8 } # То же для батареи

# Разблокировка настройки сна SATA-накопителей (AHCI Link Power Management)
Apply-Tweak "Разблокировка сна AHCI SATA" { powercfg -attributes SUB_DISK 0b2d69d7-a2a1-449c-9680-f91c70521c60 -ATTRIB_HIDE *>&1 | Out-File -FilePath $global:LogPath -Append -Encoding UTF8 } # Раскрываем настройку

# Установка значения AHCI LPM
Apply-Tweak "Отключение сна SATA-дисков от сети" { powercfg -setacvalueindex scheme_current SUB_DISK 0b2d69d7-a2a1-449c-9680-f91c70521c60 0 *>&1 | Out-File -FilePath $global:LogPath -Append -Encoding UTF8 } # 0 = Active (Сон шины SATA полностью отключен от сети)
Apply-Tweak "Разрешение сна SATA-дисков от батареи" { powercfg -setdcvalueindex scheme_current SUB_DISK 0b2d69d7-a2a1-449c-9680-f91c70521c60 1 *>&1 | Out-File -FilePath $global:LogPath -Append -Encoding UTF8 } # 1 = Разрешен сон от батареи

# Отключение таймаута сна для системного NVMe SSD
Apply-Tweak "Отключение таймаута сна NVMe от сети" { powercfg /setacvalueindex scheme_current SUB_DISK d639518a-e56d-4345-8af2-b9f32fb26109 0 *>&1 | Out-File -FilePath $global:LogPath -Append -Encoding UTF8 } # Запрет NVMe накопителю уходить в спячку при работе от сети (0 = Отключено)
Apply-Tweak "Разрешение сна NVMe от батареи (15 сек)" { powercfg /setdcvalueindex scheme_current SUB_DISK d639518a-e56d-4345-8af2-b9f32fb26109 15000 *>&1 | Out-File -FilePath $global:LogPath -Append -Encoding UTF8 } # Разрешение сна от батареи (100 мс - системный минимум для этого параметра)

# Глубокие параметры управления питанием и телеметрия энергии
$PowerKey = "HKLM:\SYSTEM\CurrentControlSet\Control\Power"
$PowerTweaks = @{
    "EnforceDisconnectedStandby" = 0    # Запрет отключения сети во время простоя
    "EnergyEstimationEnabled" = 0       # Отключение оценки энергопотребления (телеметрия)
    "EnergyEstimationDisabled" = 1      # Принудительное отключение оценки энергии
    "EventProcessorEnabled" = 0         # Отключение процессора событий питания
    "FxAccountingTelemetryDisabled" = 1 # Отключение телеметрии фреймворка энергопотребления
    "SleepstudyAccountingEnabled" = 0   # Отключение логирования Sleep Study (сильно экономит SSD)
    "DisableSensorWatchdog" = 1         # Отключение watchdog таймера для сенсоров
    "DisableVsyncLatencyUpdate" = 1     # Отвязывает VSync от управления питанием (убивает инпут-лаг интерфейса)
    "QosManagesIdleProcessors" = 0      # Запрещает QoS будить ядра процессора без необходимости
    "ParkUsingConcurrency" = 0          # Отключает умную парковку ядер по потокам
    "ParkWithCoreGranularity" = 0       # Отключает парковку по гранулярности
}
foreach ($Tweak in $PowerTweaks.GetEnumerator()) {
    Apply-Tweak "Глубокая настройка питания: $($Tweak.Name)" { Set-ItemProperty -Path $PowerKey -Name $Tweak.Name -Value $Tweak.Value -Type DWord -Force *>&1 | Out-File -FilePath $global:LogPath -Append -Encoding UTF8 } # Применяем массив настроек
}
Remove-ItemProperty -Path $PowerKey -Name "PlatformAoAcOverride" *>&1 | Out-File -FilePath $global:LogPath -Append -Encoding UTF8 # Удаление устаревшего флага PlatformAoAcOverride
if ($global:IsLaptop) {
    Apply-Tweak "Восстановление сна Modern Standby для ноутбуков" { 
        Remove-ItemProperty -Path $PowerKey -Name "EnforceDisconnectedStandby" *>&1 | Out-File -FilePath $global:LogPath -Append -Encoding UTF8
    }
    Apply-Tweak "Защита ноутбука от перегрева в рюкзаке (Отключение сети в Standby)" {
        powercfg /setdcvalueindex scheme_current SUB_NONE F15576E8-98B7-4186-B944-EAFA664402D9 0 *>&1 | Out-File -FilePath $global:LogPath -Append -Encoding UTF8
    }
    Apply-Tweak "Защита ноутбука от перегрева (Гибернация через 20 минут сна)" {
        powercfg /setdcvalueindex scheme_current SUB_SLEEP 49cb1a0e-7460-4eb6-936b-610740490771 1200 *>&1 | Out-File -FilePath $global:LogPath -Append -Encoding UTF8
    }
}

# Жесткое отключение логов TaggedEnergy (Windows 11)
$EnergyTag = "$PowerKey\EnergyEstimation\TaggedEnergy"
$EnergyWork = "$PowerKey\EnergyEstimation\WorkOnBehalf"
if (!(Test-Path $EnergyTag)) { Apply-Tweak "Создание раздела TaggedEnergy" { New-Item $EnergyTag -Force *>&1 | Out-File -FilePath $global:LogPath -Append -Encoding UTF8 } } # Создаем ветку
if (!(Test-Path $EnergyWork)) { Apply-Tweak "Создание раздела WorkOnBehalf" { New-Item $EnergyWork -Force *>&1 | Out-File -FilePath $global:LogPath -Append -Encoding UTF8 } } # Создаем ветку

Apply-Tweak "Отключение энерго-логирования для приложений" { Set-ItemProperty -Path $EnergyTag -Name "DisableTaggedEnergyLogging" -Value 1 -Type DWord -Force *>&1 | Out-File -FilePath $global:LogPath -Append -Encoding UTF8 } # Полностью убиваем энерго-логирование для приложений
Apply-Tweak "Сброс лимита приложений в телеметрии энергии" { Set-ItemProperty -Path $EnergyTag -Name "TelemetryMaxApplication" -Value 0 -Type DWord -Force *>&1 | Out-File -FilePath $global:LogPath -Append -Encoding UTF8 } # Лимит приложений в телеметрии = 0
Apply-Tweak "Сброс лимита тегов в телеметрии энергии" { Set-ItemProperty -Path $EnergyTag -Name "TelemetryMaxTagPerApplication" -Value 0 -Type DWord -Force *>&1 | Out-File -FilePath $global:LogPath -Append -Encoding UTF8 } # Лимит тегов = 0
Apply-Tweak "Запрет перераспределения энергопотребления" { Set-ItemProperty -Path $EnergyWork -Name "DisableWorkOnBehalfAttribution" -Value 1 -Type DWord -Force *>&1 | Out-File -FilePath $global:LogPath -Append -Encoding UTF8 } # Запрет перераспределения энергопотребления

# Разблокировка скрытых настроек питания в Панели Управления
$PowerSettingsBase = "HKLM:\SYSTEM\CurrentControlSet\Control\Power\PowerSettings"
$SettingsToUnlock = @(
    "$PowerSettingsBase\54533251-82be-4824-96c1-47b60b740d00", # Настройки CPU
    "$PowerSettingsBase\501a4d13-42af-4429-9fd1-a8218c268e20", # Настройки PCI-E
    "$PowerSettingsBase\2a737441-1930-4402-8d77-b2bebba308a3"  # Настройки USB
)
foreach ($Path in $SettingsToUnlock) {
    if (Test-Path $Path) {
        Get-ChildItem -Path $Path 2>> $env:SystemDrive\EastricaTools\Eastrica_ErrorTrace.log | ForEach-Object {
            Apply-Tweak "Разблокировка скрытой настройки питания ($($_.PSChildName))" { Set-ItemProperty -Path $_.PSPath -Name "Attributes" -Value 0 -Type DWord -Force *>&1 | Out-File -FilePath $global:LogPath -Append -Encoding UTF8 } # Attributes = 0 делает их видимыми в GUI
        }
    }
}

# Раскрытие настроек Thread Director (P-Cores & E-Cores Scheduling)
$PowerSettingsBase = "HKLM:\SYSTEM\CurrentControlSet\Control\Power\PowerSettings\54533251-82be-4824-96c1-47b60b740d00"
$HeteroSettings = @(
    "7f2f5cfa-f10c-4823-b5e1-e93ae85f46b5", # Политика планирования разнородных потоков
    "93b8b6dc-0698-4d1c-9ee4-0644e900c85d", # Политика для коротких потоков
    "bae08b81-2d5e-4668-ba25-3c0590f1659e"  # Действующая гетерогенная политика
)
foreach ($Setting in $HeteroSettings) {
    $FullPath = "$PowerSettingsBase\$Setting"
    if (Test-Path $FullPath) {
        Apply-Tweak "Раскрытие настройки гибридных ядер Intel ($Setting)" { Set-ItemProperty -Path $FullPath -Name "Attributes" -Value 0 -Type DWord -Force *>&1 | Out-File -FilePath $global:LogPath -Append -Encoding UTF8 } # Раскрываем настройки гибридных процессоров Intel в Панели управления
    }
}

Apply-Tweak "Удаление опасных микросекундных лимитов задержек питания" {
    $BadLatKeys = @("ExitLatency", "ExitLatencyCheckEnabled", "Latency", "LatencyToleranceDefault", "LatencyToleranceFSVP", "LatencyTolerancePerfOverride")
    foreach ($k in $BadLatKeys) {
        Remove-ItemProperty -Path "HKLM:\SYSTEM\CurrentControlSet\Control\Power" -Name $k *>&1 | Out-File -FilePath $global:LogPath -Append -Encoding UTF8
    }
}

# Настройка аппаратного распределения разнородных ядер Intel 12-14th Gen и Core Ultra (Intel Thread Director)
# 7f2f5cfa-f10c-4823-b5e1-e93ae85f46b5 = Heterogeneous thread scheduling policy (Длительные и активные задачи)
# Значение 1 = Performant processors (Запуск основных игровых потоков строго на мощных P-ядрах)
Apply-Tweak "Форсирование P-Cores для активных задач (Performant processors)" { Set-SafeCpuPower "7f2f5cfa-f10c-4823-b5e1-e93ae85f46b5" 1 1 }

# 93b8b6dc-0698-4d1c-9ee4-0644e900c85d = Heterogeneous short running thread scheduling policy (Короткие системные задачи)
# Значение 2 = Efficient processors (Сброс микро-задач, фоновых системных таймеров и прерываний DPC на E-ядра)
# Это защищает кэш первого уровня L1/L2 и такты больших P-ядер от системного шума во время игрового процесса.
Apply-Tweak "Сброс коротких системных задач на E-Cores (Efficient processors)" { Set-SafeCpuPower "93b8b6dc-0698-4d1c-9ee4-0644e900c85d" 2 2 }

# Настройка Wireless Adapter Power Saving
Apply-Tweak "Запрет Wi-Fi адаптеру отключаться от сети" { powercfg /setacvalueindex scheme_current 19cbb8fa-5279-450e-9fac-8a3d5fedd0c1 12bbebe6-58d6-4636-95bb-3217ef867c1a 0 *>&1 | Out-File -FilePath $global:LogPath -Append -Encoding UTF8 } # 0 = Maximum Performance (Запрет Wi-Fi отключаться от сети)
Apply-Tweak "Запрет Wi-Fi адаптеру отключаться от батареи" { powercfg /setdcvalueindex scheme_current 19cbb8fa-5279-450e-9fac-8a3d5fedd0c1 12bbebe6-58d6-4636-95bb-3217ef867c1a 0 *>&1 | Out-File -FilePath $global:LogPath -Append -Encoding UTF8 } # То же для батареи (стабильный пинг)

# Порог перехода процессора в сон (Idle Promotion)
Apply-Tweak "Установка порога глубокого сна процессора в 100%" { Set-SafeCpuPower "7b224883-b3cc-4d79-819f-8374152cbe7c" 100 100 } # Процессору нужно 100% времени простаивать, чтобы уйти в глубокий сон
Apply-Tweak "Применение изменений питания к текущей схеме" { powercfg /setactive $global:TargetGUID *>&1 | Out-File -FilePath $global:LogPath -Append -Encoding UTF8 } # Применяем все изменения к текущей схеме

# Нейтрализация принудительного Energy Saver в Windows 11 24H2
$EnergySaver = "HKLM:\SOFTWARE\Policies\Microsoft\Windows\Power\EnergySaver"
if (!(Test-Path $EnergySaver)) { Apply-Tweak "Создание раздела EnergySaver" { New-Item -Path $EnergySaver -Force *>&1 | Out-File -FilePath $global:LogPath -Append -Encoding UTF8 } }
Apply-Tweak "Отключение Energy Saver от батареи" { Set-ItemProperty -Path $EnergySaver -Name "EnergySaverBatteryThresholdOnBattery" -Value 0 -Type DWord -Force *>&1 | Out-File -FilePath $global:LogPath -Append -Encoding UTF8 } # Отключаем включение эко-режима от батареи
Apply-Tweak "Отключение Energy Saver от сети" { Set-ItemProperty -Path $EnergySaver -Name "EnergySaverBatteryThresholdPluggedIn" -Value 0 -Type DWord -Force *>&1 | Out-File -FilePath $global:LogPath -Append -Encoding UTF8 } # Отключаем включение эко-режима от сети
Apply-Tweak "Глобальное отключение Energy Saver" { Set-ItemProperty -Path $EnergySaver -Name "EsEnabled" -Value 0 -Type DWord -Force *>&1 | Out-File -FilePath $global:LogPath -Append -Encoding UTF8 } # Глобальное отключение Energy Saver

Write-Host ""
# ==============================================================================
# Раздел 8.1: Автоматическое переключение питания для ноутбуков
# ==============================================================================
Show-ProgressStep -StepNum 8 -TotalSteps 81 -Activity "Настройка автоматического переключения питания..."
Write-Host "==============================================================================" -ForegroundColor DarkGray
Write-Host "РАЗДЕЛ 8.1: АВТОМАТИЧЕСКОЕ ПЕРЕКЛЮЧЕНИЕ ПИТАНИЯ ДЛЯ НОУТБУКОВ" -ForegroundColor Cyan
Write-Host "==============================================================================" -ForegroundColor DarkGray
if ($global:IsLaptop) {
    $TaskName = "Eastrica_AutoPowerSwitch" # Имя задачи
    Apply-Tweak "Удаление старой задачи переключения питания" { Unregister-ScheduledTask -TaskName $TaskName -Confirm:$false -ErrorAction SilentlyContinue *>&1 | Out-File -FilePath $global:LogPath -Append -Encoding UTF8 } # Удаляем старую задачу, если была
    
    # Скрипт-переключатель
    $PowerScript = @"
    `$gameActive = (Get-ItemProperty -Path "HKLM:\SOFTWARE\Eastrica" -Name "GameActive" -ErrorAction SilentlyContinue).GameActive
    if (`$gameActive -eq 1) { exit } # ЗАЩИТА: Не переключать питание, так как идет игра

    `$Battery = Get-CimInstance -Namespace root\wmi -ClassName BatteryStatus -ErrorAction SilentlyContinue
    `$IsPluggedIn = if (`$Battery -is [array]) { `$Battery[0].PowerOnline } else { `$Battery.PowerOnline }
    if (`$IsPluggedIn -eq `$true) { 
        powercfg /setactive $($global:TargetGUID)
    } else { 
        powercfg /setactive $POWER_GUID_BALANCED
    }
"@
    $ScriptPath = "$BaseDir\Scripts\EastricaAutoPower.ps1" # Путь сохранения
    Apply-Tweak "Создание скрипта автопереключения питания" { Set-Content -Path $ScriptPath -Value $PowerScript -Encoding UTF8 } # Создаем файл скрипта
    
    # Настройка триггеров планировщика (Срабатывает при входе в систему и при Событии Ядра №105 - отключение/подключение зарядки)
    $TriggerLogon = New-ScheduledTaskTrigger -AtLogon
    $TriggerEvent = New-CimInstance -CimClass (Get-CimClass -Namespace Root\Microsoft\Windows\TaskScheduler -ClassName MSFT_TaskEventTrigger) -ClientOnly
    $TriggerEvent.Subscription = "<QueryList><Query Id='0' Path='System'><Select Path='System'>*[System[Provider[@Name='Microsoft-Windows-Kernel-Power'] and (EventID=105)]]</Select></Query></QueryList>"
    $TriggerEvent.Enabled = $true

    $Action = New-ScheduledTaskAction -Execute "powershell.exe" -Argument "-WindowStyle Hidden -ExecutionPolicy Bypass -File `"$ScriptPath`"" # Действие запуска скрытого PowerShell
    Apply-Tweak "Регистрация задачи автопереключения питания (SYSTEM)" { Register-ScheduledTask -TaskName $TaskName -Trigger @($TriggerLogon, $TriggerEvent) -Action $Action -User "SYSTEM" -Force *>&1 | Out-File -FilePath $global:LogPath -Append -Encoding UTF8 } # Регистрируем задачу от имени SYSTEM
} else {
    Apply-Tweak "Удаление задачи автопереключения питания" { 
        if (Get-ScheduledTask -TaskName "Eastrica_AutoPowerSwitch" -ErrorAction SilentlyContinue) {
            Unregister-ScheduledTask -TaskName "Eastrica_AutoPowerSwitch" -Confirm:$false -ErrorAction Stop *>&1 | Out-File -FilePath $global:LogPath -Append -Encoding UTF8 
        }
    }
    Apply-Tweak "Удаление скрипта автопереключения питания" { Remove-Item -Path "$BaseDir\Scripts\EastricaAutoPower.ps1" -Force *>&1 | Out-File -FilePath $global:LogPath -Append -Encoding UTF8 }
}

# Отключение питания (засыпания) дисков
Apply-Tweak "Запрет отключения жестких дисков от сети" { powercfg /change disk-timeout-ac 0 *>&1 | Out-File -FilePath $global:LogPath -Append -Encoding UTF8 } # 0 = Никогда не отключать диски при работе от розетки

if ($global:IsLaptop) {
    Apply-Tweak "Установка таймаута отключения дисков от батареи (20 мин)" { powercfg /change disk-timeout-dc 20 *>&1 | Out-File -FilePath $global:LogPath -Append -Encoding UTF8 } # Для ноутбука от батареи отключать диски через 20 минут
} else {
    Apply-Tweak "Запрет отключения жестких дисков от батареи (ПК)" { powercfg /change disk-timeout-dc 0 *>&1 | Out-File -FilePath $global:LogPath -Append -Encoding UTF8 } # Для ПК никогда не отключать диски от батареи (если стоит ИБП)
}

# Глобальный запрет Plug and Play управлению питанием устройств
$PnpManager = "HKLM:\SYSTEM\CurrentControlSet\Control\PnP"
if (!(Test-Path $PnpManager)) { Apply-Tweak "Создание раздела PnP" { New-Item -Path $PnpManager -Force *>&1 | Out-File -FilePath $global:LogPath -Append -Encoding UTF8 } }
Apply-Tweak "Глобальный запрет системы усыплять PnP устройства (DisableMSPowerDeviceEnable)" { Set-ItemProperty -Path $PnpManager -Name "DisableMSPowerDeviceEnable" -Value 1 -Type DWord -Force *>&1 | Out-File -FilePath $global:LogPath -Append -Encoding UTF8 } # 1 = Запрет ОС "самовольно" усыплять USB/PCIe устройства на аппаратной шине

Write-Host ""
# ==============================================================================
# Раздел 9: Spectre & Meltdown и уязвимости процессора
# ==============================================================================
Show-ProgressStep -StepNum 9 -TotalSteps 81 -Activity "Настройка уязвимостей процессора (Spectre & Meltdown) и защиты памяти..."
Write-Host "==============================================================================" -ForegroundColor DarkGray
Write-Host "РАЗДЕЛ 9: SPECTRE & MELTDOWN И УЯЗВИМОСТИ ПРОЦЕССОРА" -ForegroundColor Cyan
Write-Host "==============================================================================" -ForegroundColor DarkGray

$SpecKey = "HKLM:\SYSTEM\CurrentControlSet\Control\Session Manager\Memory Management" # Ветка управления памятью
$KernelPath = "HKLM:\SYSTEM\CurrentControlSet\Control\Session Manager\kernel" # Ветка ядра

# Безопасная проверка поколения CPU
$CpuName = $global:ProcInfo.Name
$HasHardwareMitigation = $false # Флаг наличия аппаратной защиты в кристалле

try {
    # Проверка через аппаратные идентификаторы WMI и строку описания CPUID
    $CpuFamily = $global:ProcInfo.Family
    $CpuCaption = $global:ProcInfo.Caption
    if ($CpuFamily -in 207, 198 -or $CpuCaption -match "Family (25|26|27)\b") {
        $HasHardwareMitigation = $true
    }
} catch {}

# Альтернативная проверка по текстовому имени процессора
if (-not $HasHardwareMitigation) {
    $HasHardwareMitigation = ($CpuName -match "i[3579]-(10|11|12|13|14|15)\d{3}") -or ($CpuName -match "i[3579]-\d{5}") -or ($CpuName -match "Ryzen [3579] (5|7|8|9)\d{3}") -or ($CpuName -match "Ryzen AI") -or ($CpuName -match "Ultra [3579]")
}

# Настройка CET (Control-flow Enforcement Technology)
if (-not $global:OptAntiCheat) {
    Apply-Tweak "Отключение совместимости CET" { Set-ItemProperty -Path "HKLM:\SYSTEM\CurrentControlSet\Control\Session Manager\kernel" -Name "CetAppCompatState" -Value 0 -Type DWord -Force *>&1 | Out-File -FilePath $global:LogPath -Append -Encoding UTF8 } # Отключаем совместимость CET
    try { Apply-Tweak "Отключение теневого стека (UserShadowStack)" { Set-ProcessMitigation -System -Disable UserShadowStack *>&1 | Out-File -FilePath $global:LogPath -Append -Encoding UTF8 } } catch { } # Отключаем теневой стек (Shadow Stack) для ускорения обработки инструкций
} else {
    # В режиме античита оставляем CET включенным (FACEIT/Vanguard требуют его для целостности памяти)
    Apply-Tweak "Удаление ограничения CET для совместимости с античитами" { Remove-ItemProperty -Path "HKLM:\SYSTEM\CurrentControlSet\Control\Session Manager\kernel" -Name "CetAppCompatState" *>&1 | Out-File -FilePath $global:LogPath -Append -Encoding UTF8 }
}

# Отключение программных заплаток Spectre/Meltdown
if ($global:OptSpectre -and -not $global:OptAntiCheat -and $HasHardwareMitigation) {
    Write-Host " ► [Secure] CPU имеет аппаратную защиту. Программные заплатки отключены." -ForegroundColor DarkGray
    
    if (!(Test-Path $SpecKey)) { Apply-Tweak "Создание раздела Memory Management" { New-Item -Path $SpecKey -Force *>&1 | Out-File -FilePath $global:LogPath -Append -Encoding UTF8 } }
    Apply-Tweak "Отключение KVA Shadowing (Meltdown)" { Set-ItemProperty -Path $SpecKey -Name "FeatureSettings" -Value 1 -Type DWord -Force *>&1 | Out-File -FilePath $global:LogPath -Append -Encoding UTF8 } # Отключает KVA Shadowing (Meltdown)
    Apply-Tweak "Отключение Branch Target Injection (Spectre Variant 2)" { Set-ItemProperty -Path $SpecKey -Name "FeatureSettingsOverride" -Value 3 -Type DWord -Force *>&1 | Out-File -FilePath $global:LogPath -Append -Encoding UTF8 } # Отключает Branch Target Injection (Spectre Variant 2)
    Apply-Tweak "Применение маски переопределения уязвимостей" { Set-ItemProperty -Path $SpecKey -Name "FeatureSettingsOverrideMask" -Value 3 -Type DWord -Force *>&1 | Out-File -FilePath $global:LogPath -Append -Encoding UTF8 } # Маска переопределения
    Apply-Tweak "Глобальное отключение CFG (Control Flow Guard)" { Set-ItemProperty -Path $SpecKey -Name "EnableCfg" -Value 0 -Type DWord -Force *>&1 | Out-File -FilePath $global:LogPath -Append -Encoding UTF8 } # Глобальное отключение CFG (Control Flow Guard)
    Apply-Tweak "Отключение проверки цепочек исключений" { Set-ItemProperty -Path $SpecKey -Name "DisableExceptionChainValidation" -Value 1 -Type DWord -Force *>&1 | Out-File -FilePath $global:LogPath -Append -Encoding UTF8 } # Отключает проверку цепочек исключений
    Apply-Tweak "Отключение SEHOP в ядре" { Set-ItemProperty -Path $SpecKey -Name "KernelSEHOPEnabled" -Value 0 -Type DWord -Force *>&1 | Out-File -FilePath $global:LogPath -Append -Encoding UTF8 } # Отключает SEHOP в ядре
    Apply-Tweak "Установка DEP в режим OptIn (Легкий режим)" { bcdedit /set nx OptIn *>&1 | Out-File -FilePath $global:LogPath -Append -Encoding UTF8 } # Устанавливает Data Execution Prevention (DEP) в режим "только для системных служб"
} else {
    # Восстановление защиты по умолчанию (Если старый процессор, либо стоит режим Античита)
    if ($global:OptSpectre -and -not $HasHardwareMitigation) { Write-Warning " ► [БЛОКИРОВКА] CPU НЕ имеет аппаратной защиты. Заплатки НЕ отключены (безопасность)." }
    if ($global:OptAntiCheat) { Write-Host " ► [AntiCheat] Заплатки оставлены для совместимости." -ForegroundColor DarkGray }
    
    Apply-Tweak "Восстановление KVA Shadowing" { Remove-ItemProperty -Path $SpecKey -Name "FeatureSettings" *>&1 | Out-File -FilePath $global:LogPath -Append -Encoding UTF8 }
    Apply-Tweak "Восстановление Branch Target Injection" { Set-ItemProperty -Path $SpecKey -Name "FeatureSettingsOverride" -Value 0 -Type DWord -Force *>&1 | Out-File -FilePath $global:LogPath -Append -Encoding UTF8 }
    Apply-Tweak "Восстановление маски уязвимостей" { Remove-ItemProperty -Path $SpecKey -Name "FeatureSettingsOverrideMask" *>&1 | Out-File -FilePath $global:LogPath -Append -Encoding UTF8 }
    Apply-Tweak "Включение CFG" { Remove-ItemProperty -Path $SpecKey -Name "EnableCfg" *>&1 | Out-File -FilePath $global:LogPath -Append -Encoding UTF8 }
    Apply-Tweak "Восстановление опций безопасности ядра" { Remove-ItemProperty -Path $KernelPath -Name "MitigationOptions" *>&1 | Out-File -FilePath $global:LogPath -Append -Encoding UTF8 }
    Apply-Tweak "Включение проверки цепочек исключений" { Remove-ItemProperty -Path $KernelPath -Name "DisableExceptionChainValidation" *>&1 | Out-File -FilePath $global:LogPath -Append -Encoding UTF8 }
    Apply-Tweak "Включение SEHOP в ядре" { Remove-ItemProperty -Path $KernelPath -Name "KernelSEHOPEnabled" *>&1 | Out-File -FilePath $global:LogPath -Append -Encoding UTF8 }
    Apply-Tweak "Удаление запрета Intel TSX" { Remove-ItemProperty -Path $KernelPath -Name "DisableTsx" *>&1 | Out-File -FilePath $global:LogPath -Append -Encoding UTF8 }
    Apply-Tweak "Установка штатного режима DEP (OptIn)" { bcdedit /set nx OptIn *>&1 | Out-File -FilePath $global:LogPath -Append -Encoding UTF8 }
    
    if ($global:OptSpectre -and -not $global:OptAntiCheat) {
        # Включаем аппаратное ускорение транзакций (Intel TSX), которое Microsoft заблокировала микрокодом
        Apply-Tweak "Принудительное включение Intel TSX" { Set-ItemProperty -Path $KernelPath -Name "DisableTsx" -Value 0 -Type DWord -Force *>&1 | Out-File -FilePath $global:LogPath -Append -Encoding UTF8 }
        Write-Host " ► Аппаратное ускорение Intel TSX принудительно включено" -ForegroundColor DarkGray
    }
}

# Отключение лимита задержек I/O (Позволяет процессору обрабатывать запросы накопителей без искусственных тормозов)
Apply-Tweak "Отключение лимита задержек I/O процессора (IoLatencyCap)" { Set-ItemProperty -Path $KernelPath -Name "IoLatencyCap" -Value 0 -Type DWord -Force *>&1 | Out-File -FilePath $global:LogPath -Append -Encoding UTF8 }
Apply-Tweak "Отключение флага лимитов I/O" { Set-ItemProperty -Path $KernelPath -Name "IoLatencyCapEnabled" -Value 0 -Type DWord -Force *>&1 | Out-File -FilePath $global:LogPath -Append -Encoding UTF8 }

Write-Host ""
# ==============================================================================
# Раздел 10: VBS, изоляция ядра, WSL2 и Docker (виртуализация)
# ==============================================================================
Show-ProgressStep -StepNum 10 -TotalSteps 81 -Activity "Настройка виртуализации (VBS, Hyper-V, WSL, Docker)..."
Write-Host "==============================================================================" -ForegroundColor DarkGray
Write-Host "РАЗДЕЛ 10: VBS, ИЗОЛЯЦИЯ ЯДРА, WSL2 И DOCKER (ВИРТУАЛИЗАЦИЯ)" -ForegroundColor Cyan
Write-Host "==============================================================================" -ForegroundColor DarkGray

$DevGuard = "HKLM:\SYSTEM\CurrentControlSet\Control\DeviceGuard" # Ветка Device Guard
$ScenGuard = "HKLM:\SYSTEM\CurrentControlSet\Control\DeviceGuard\Scenarios\HypervisorEnforcedCodeIntegrity" # Ветка HVCI (Изоляция ядра)
$CredGuard = "HKLM:\SYSTEM\CurrentControlSet\Control\DeviceGuard\Scenarios\CredentialGuard" # Ветка Credential Guard
$SysGuard  = "HKLM:\SYSTEM\CurrentControlSet\Control\DeviceGuard\Scenarios\SystemGuard" # Ветка System Guard
$LsaPath = "HKLM:\SYSTEM\CurrentControlSet\Control\Lsa" # Ветка LSA (Local Security Authority)
$DmaKey = "HKLM:\SOFTWARE\Policies\Microsoft\Windows\Kernel DMA Protection" # Ветка DMA Protection

$VirtServices = @(
    "vmms",        # Служба управления виртуальными машинами Hyper-V
    "VmCompute",   # Вычислительная служба Hyper-V
    "hns",         # Служба главной сети (Host Network Service)
    "LxssManager"  # Диспетчер WSL
)

if ($global:OptVBS) {
    # Сценарий 1: Полное отключение виртуализации (Режим киберспорта)
    Write-Host " ► [Киберспорт] Полное уничтожение гипервизора, VBS и подсистем Linux..." -ForegroundColor DarkGray
    
    # 1. Отключение VBS в реестре (Убирает микро-статтеры)
    if (!(Test-Path $DevGuard)) { Apply-Tweak "Создание раздела DeviceGuard" { New-Item $DevGuard -Force *>&1 | Out-File -FilePath $global:LogPath -Append -Encoding UTF8 } }
    if (!(Test-Path $ScenGuard)) { Apply-Tweak "Создание раздела HVCI" { New-Item $ScenGuard -Force *>&1 | Out-File -FilePath $global:LogPath -Append -Encoding UTF8 } }
    Apply-Tweak "Отключение виртуализации безопасности (VBS)" { Set-ItemProperty -Path $DevGuard -Name "EnableVirtualizationBasedSecurity" -Value 0 -Type DWord -Force *>&1 | Out-File -FilePath $global:LogPath -Append -Encoding UTF8 } # Отключаем VBS
    Apply-Tweak "Отключение Изоляции ядра (Memory Integrity)" { Set-ItemProperty -Path $ScenGuard -Name "Enabled" -Value 0 -Type DWord -Force *>&1 | Out-File -FilePath $global:LogPath -Append -Encoding UTF8 } # Отключаем Изоляцию ядра (Memory Integrity)
    Apply-Tweak "Отключение защиты процессов LSA" { Set-ItemProperty -Path $LsaPath -Name "RunAsPPL" -Value 0 -Type DWord -Force *>&1 | Out-File -FilePath $global:LogPath -Append -Encoding UTF8 } # Отключаем защиту процессов LSA
    Apply-Tweak "Отключение защиты LSA при загрузке" { Set-ItemProperty -Path $LsaPath -Name "RunAsPPLBoot" -Value 0 -Type DWord -Force *>&1 | Out-File -FilePath $global:LogPath -Append -Encoding UTF8 }
    Apply-Tweak "Сброс флагов конфигурации LSA" { Set-ItemProperty -Path $LsaPath -Name "LsaCfgFlags" -Value 0 -Type DWord -Force *>&1 | Out-File -FilePath $global:LogPath -Append -Encoding UTF8 }
    
    if (!(Test-Path $CredGuard)) { Apply-Tweak "Создание раздела CredentialGuard" { New-Item $CredGuard -Force *>&1 | Out-File -FilePath $global:LogPath -Append -Encoding UTF8 } }
    if (!(Test-Path $SysGuard)) { Apply-Tweak "Создание раздела SystemGuard" { New-Item $SysGuard -Force *>&1 | Out-File -FilePath $global:LogPath -Append -Encoding UTF8 } }
    Apply-Tweak "Отключение Credential Guard" { Set-ItemProperty -Path $CredGuard -Name "Enabled" -Value 0 -Type DWord -Force *>&1 | Out-File -FilePath $global:LogPath -Append -Encoding UTF8 } # Отключаем Credential Guard
    Apply-Tweak "Отключение System Guard (SMM)" { Set-ItemProperty -Path $SysGuard -Name "Enabled" -Value 0 -Type DWord -Force *>&1 | Out-File -FilePath $global:LogPath -Append -Encoding UTF8 } # Отключаем System Guard (SMM)
    
    # Обход UEFI LOCK для VBS и HVCI
    Apply-Tweak "Снятие флага блокировки VBS в UEFI (Locked = 0)" { Set-ItemProperty -Path $DevGuard -Name "Locked" -Value 0 -Type DWord -Force *>&1 | Out-File -FilePath $global:LogPath -Append -Encoding UTF8 }
    Apply-Tweak "Снятие флага блокировки HVCI (Изоляции ядра) в UEFI" { Set-ItemProperty -Path $ScenGuard -Name "Locked" -Value 0 -Type DWord -Force *>&1 | Out-File -FilePath $global:LogPath -Append -Encoding UTF8 }
    Apply-Tweak "Принудительный сброс политик Credential Guard (LSA)" { Set-ItemProperty -Path "HKLM:\SYSTEM\CurrentControlSet\Control\Lsa" -Name "LsaCfgFlags" -Value 0 -Type DWord -Force *>&1 | Out-File -FilePath $global:LogPath -Append -Encoding UTF8 }
    
    # Удаление защищенной EFI-переменной через нативный инструмент Windows
    $DG_Tool = "$env:SystemRoot\System32\SecConfig.efi"
    if (Test-Path $DG_Tool) {
        Apply-Tweak "Деактивация EFI-переменной SecConfig (VBS UEFI Lock)" { 
            cmd.exe /c "bcdedit /set {globalsettings} advancedoptions true >nul 2>&1"
            $global:LASTEXITCODE = 0
        }
    }
    
    # 2. Выгрузка загрузчика Hypervisor из BCD
    Apply-Tweak "Выключение загрузки гипервизора в BCD" { bcdedit /set hypervisorlaunchtype Off *>&1 | Out-File -FilePath $global:LogPath -Append -Encoding UTF8 } # Выключаем загрузку гипервизора ОС на старте
    if (-not $global:OptAntiCheat) {
        Apply-Tweak "Отключение аппаратной трансляции памяти IOMMU" { bcdedit /set iommupolicy disable *>&1 | Out-File -FilePath $global:LogPath -Append -Encoding UTF8 } # Отключаем аппаратную трансляции памяти IOMMU
        Apply-Tweak "Отключение IOMMU для гипервизора" { bcdedit /set hypervisoriommupolicy disable *>&1 | Out-File -FilePath $global:LogPath -Append -Encoding UTF8 } # Отключаем IOMMU для гипервизора
        Apply-Tweak "Скрытие статуса виртуальной машины от системы" { bcdedit /set vm No *>&1 | Out-File -FilePath $global:LogPath -Append -Encoding UTF8 } # Скрываем от ОС статус виртуальной машины
    }
    
    # 3. Физическое удаление компонентов Hyper-V и WSL (Освобождение места на диске)
    try { 
        Apply-Tweak "Физическое удаление компонентов Hyper-V и WSL" { 
            $VirtFeatures = @("Microsoft-Hyper-V-All", "VirtualMachinePlatform", "Microsoft-Windows-Subsystem-Linux")
            foreach ($Feat in $VirtFeatures) {
                Disable-WindowsOptionalFeature -Online -FeatureName $Feat -NoRestart -ErrorAction SilentlyContinue *>&1 | Out-File -FilePath $global:LogPath -Append -Encoding UTF8 
            }
        } 
    } catch {}
    
    # 4. Жесткая остановка служб Docker/WSL2/Hyper-V
    foreach ($Svc in $VirtServices) {
        if (Get-Service -Name $Svc -ErrorAction SilentlyContinue 2>> $env:SystemDrive\EastricaTools\Eastrica_ErrorTrace.log) {
            Apply-Tweak "Остановка службы виртуализации ($Svc)" { Stop-Service -Name $Svc -Force *>&1 | Out-File -FilePath $global:LogPath -Append -Encoding UTF8 } # Останавливаем процесс службы
            Apply-Tweak "Отключение автозапуска службы ($Svc)" { Set-Service -Name $Svc -StartupType Disabled *>&1 | Out-File -FilePath $global:LogPath -Append -Encoding UTF8 } # Ставим тип Disabled
        }
    }
    
    # Остановка брокера System Guard (Один из триггеров DPC)
    if (Get-Service -Name "SgrmBroker" -ErrorAction SilentlyContinue 2>> $env:SystemDrive\EastricaTools\Eastrica_ErrorTrace.log) {
        Apply-Tweak "Остановка брокера System Guard (SgrmBroker)" { Stop-Service -Name "SgrmBroker" -Force *>&1 | Out-File -FilePath $global:LogPath -Append -Encoding UTF8 }
        Apply-Tweak "Отключение брокера System Guard в реестре" { Set-ItemProperty -Path "HKLM:\SYSTEM\CurrentControlSet\Services\SgrmBroker" -Name "Start" -Value 4 -Type DWord -Force *>&1 | Out-File -FilePath $global:LogPath -Append -Encoding UTF8 }
    }
    
    # 5. Оптимизация сети: Отключение Virtual Machine Queues (VMQ)
    Get-NetAdapter -Physical | Where-Object { $_.Status -eq 'Up' -and $_.HardwareInterface -eq $true } | ForEach-Object {
        try { Apply-Tweak "Отключение очередей VMQ на сетевой карте ($($_.Name))" { Disable-NetAdapterVmq -Name $_.Name -ErrorAction Stop *>&1 | Out-File -FilePath $global:LogPath -Append -Encoding UTF8 } } catch { } # Выключает аппаратную сегментацию трафика для виртуалок
    }
    
    # 6. Отключение Kernel DMA Protection (Прямой доступ к шине PCIe без TLB-оверхеда)
    if (!(Test-Path $DmaKey)) { Apply-Tweak "Создание раздела DMA Protection" { New-Item $DmaKey -Force *>&1 | Out-File -FilePath $global:LogPath -Append -Encoding UTF8 } }
    if (-not $global:OptAntiCheat) {
        Apply-Tweak "Отключение Kernel DMA Protection" { Set-ItemProperty -Path $DmaKey -Name "DeviceEnumerationPolicy" -Value 0 -Type DWord -Force *>&1 | Out-File -FilePath $global:LogPath -Append -Encoding UTF8 } # Выключаем DMA защиту для хардкорного буста
    } else {
        Apply-Tweak "Оставление Kernel DMA Protection (Для Vanguard/FACEIT)" { Set-ItemProperty -Path $DmaKey -Name "DeviceEnumerationPolicy" -Value 1 -Type DWord -Force *>&1 | Out-File -FilePath $global:LogPath -Append -Encoding UTF8 } # Для Vanguard/FACEIT защита DMA должна быть включена!
    }
    
    # 7. Физическое уничтожение защиты VBS в UEFI BIOS (EFI-переменная SecConfig)
    $CgHostPath = "$env:SystemRoot\System32\DeviceGuard\cg10cli.exe"
    if (Test-Path $CgHostPath) {
        Write-Host " [ВНИМАНИЕ] При следующей перезагрузке появится черный экран BIOS!" -ForegroundColor Magenta
        Write-Host " Обязательно нажмите клавишу [F3] или [Win], чтобы подтвердить отключение VBS." -ForegroundColor DarkGray
        Apply-Tweak "Сброс защищенной UEFI-переменной VBS/DeviceGuard" { 
            # Вызываем встроенную утилиту Windows для отвязки гипервизора от UEFI
            Start-Process $CgHostPath -ArgumentList "disable" -Wait -WindowStyle Hidden 2>> $env:SystemDrive\EastricaTools\Eastrica_ErrorTrace.log
        }
    }
} else {
    # Сценарий 2: Включение виртуализации (Режим ИИ / разработчик)
    Write-Host " ► [Безопасность/ИИ] Виртуализация оставлена включенной. Подготовка WSL2/Docker..." -ForegroundColor DarkGray
    
    # 1. Восстановление VBS и явная активация Hypervisor в загрузчике
    Apply-Tweak "Активация гипервизора в загрузчике (Auto)" { bcdedit /set hypervisorlaunchtype Auto *>&1 | Out-File -FilePath $global:LogPath -Append -Encoding UTF8 }
    Apply-Tweak "Удаление статуса скрытой виртуальной машины из BCD" { 
        if ((cmd.exe /c "bcdedit /enum {current}") -match "\bvm\b") { cmd.exe /c "bcdedit /deletevalue {current} vm >nul 2>&1" }
        $global:LASTEXITCODE = 0 
    }
    
    if ($global:ForceEnableVBS) {
        if (!(Test-Path $DevGuard)) { Apply-Tweak "Создание раздела DeviceGuard" { New-Item $DevGuard -Force *>&1 | Out-File -FilePath $global:LogPath -Append -Encoding UTF8 } }
        if (!(Test-Path $ScenGuard)) { Apply-Tweak "Создание раздела HVCI" { New-Item $ScenGuard -Force *>&1 | Out-File -FilePath $global:LogPath -Append -Encoding UTF8 } }
        Apply-Tweak "Включение виртуализации безопасности (VBS)" { Set-ItemProperty -Path $DevGuard -Name "EnableVirtualizationBasedSecurity" -Value 1 -Type DWord -Force *>&1 | Out-File -FilePath $global:LogPath -Append -Encoding UTF8 }
        Apply-Tweak "Включение Изоляции ядра" { Set-ItemProperty -Path $ScenGuard -Name "Enabled" -Value 1 -Type DWord -Force *>&1 | Out-File -FilePath $global:LogPath -Append -Encoding UTF8 }
        Apply-Tweak "Восстановление защиты процессов LSA" { Remove-ItemProperty -Path $LsaPath -Name "RunAsPPL" *>&1 | Out-File -FilePath $global:LogPath -Append -Encoding UTF8 }
        Apply-Tweak "Восстановление защиты LSA при загрузке" { Remove-ItemProperty -Path $LsaPath -Name "RunAsPPLBoot" *>&1 | Out-File -FilePath $global:LogPath -Append -Encoding UTF8 }
        Apply-Tweak "Восстановление флагов конфигурации LSA" { Remove-ItemProperty -Path $LsaPath -Name "LsaCfgFlags" *>&1 | Out-File -FilePath $global:LogPath -Append -Encoding UTF8 }
        Apply-Tweak "Удаление ручного снятия блокировки VBS в UEFI" { Remove-ItemProperty -Path $DevGuard -Name "Locked" -ErrorAction SilentlyContinue *>&1 | Out-File -FilePath $global:LogPath -Append -Encoding UTF8 }
        Apply-Tweak "Удаление ручного снятия блокировки HVCI в UEFI" { Remove-ItemProperty -Path $ScenGuard -Name "Locked" -ErrorAction SilentlyContinue *>&1 | Out-File -FilePath $global:LogPath -Append -Encoding UTF8 }
        Apply-Tweak "Отмена деактивации EFI-переменной SecConfig" {
            if ((cmd.exe /c "bcdedit /enum {globalsettings} 2>&1") -match "\badvancedoptions\b") {
                cmd.exe /c "bcdedit /deletevalue {globalsettings} advancedoptions >nul 2>&1"
            }
            $global:LASTEXITCODE = 0
        }
    }
    
    # 2. Принудительная установка платформы виртуализации (Критично для работы Docker и Ollama)
    if ($global:OptAI) {
        $VirtFeatures = @("Microsoft-Hyper-V-All", "VirtualMachinePlatform", "Microsoft-Windows-Subsystem-Linux")
        foreach ($Feat in $VirtFeatures) {
            try { Apply-Tweak "Установка компонента $Feat" { Enable-WindowsOptionalFeature -Online -FeatureName $Feat -All -NoRestart -ErrorAction Stop *>&1 | Out-File -FilePath $global:LogPath -Append -Encoding UTF8 } } catch {}
        }
    }
    
    # 3. Настройка служб Hyper-V и зависимостей с учетом отложенного запуска
    # VmCompute переводим в отложенный запуск, а vmms исключаем (Hyper-V должен работать сразу)
    $DelayedVirtServices = @("VmCompute")
    foreach ($Svc in $DelayedVirtServices) {
        if (Get-Service -Name $Svc -ErrorAction SilentlyContinue 2>> $env:SystemDrive\EastricaTools\Eastrica_ErrorTrace.log) {
            Apply-Tweak "Настройка отложенного автозапуска для $Svc" {
                Set-Service -Name $Svc -StartupType Automatic *>&1 | Out-File -FilePath $global:LogPath -Append -Encoding UTF8
                Set-ItemProperty -Path "HKLM:\SYSTEM\CurrentControlSet\Services\$Svc" -Name "DelayedAutoStart" -Value 1 -Type DWord -Force *>&1 | Out-File -FilePath $global:LogPath -Append -Encoding UTF8
                cmd.exe /c "sc.exe failure $Svc reset= 86400 actions= restart/5000/restart/5000/restart/5000 >nul 2>&1"
                Start-Service -Name $Svc *>&1 | Out-File -FilePath $global:LogPath -Append -Encoding UTF8
            }
        }
    }
    
    # vmms, hns, iphlpsvc должны стартовать без задержек сразу при загрузке
    $ImmediateVirtServices = @("vmms", "hns", "iphlpsvc", "Winmgmt")
    foreach ($Svc in $ImmediateVirtServices) {
        if (Get-Service -Name $Svc -ErrorAction SilentlyContinue 2>> $env:SystemDrive\EastricaTools\Eastrica_ErrorTrace.log) {
            Apply-Tweak "Настройка прямого автозапуска для $Svc" {
                Set-Service -Name $Svc -StartupType Automatic *>&1 | Out-File -FilePath $global:LogPath -Append -Encoding UTF8
                Set-ItemProperty -Path "HKLM:\SYSTEM\CurrentControlSet\Services\$Svc" -Name "DelayedAutoStart" -Value 0 -Type DWord -Force *>&1 | Out-File -FilePath $global:LogPath -Append -Encoding UTF8
                Start-Service -Name $Svc *>&1 | Out-File -FilePath $global:LogPath -Append -Encoding UTF8
            }
        }
    }
    
    # LxssManager (WSL) переводим в запуск вручную по требованию
    if (Get-Service -Name "LxssManager" -ErrorAction SilentlyContinue 2>> $env:SystemDrive\EastricaTools\Eastrica_ErrorTrace.log) {
        Apply-Tweak "Перевод службы LxssManager в режим Вручную" {
            Set-Service -Name "LxssManager" -StartupType Manual *>&1 | Out-File -FilePath $global:LogPath -Append -Encoding UTF8
            Set-ItemProperty -Path "HKLM:\SYSTEM\CurrentControlSet\Services\LxssManager" -Name "DelayedAutoStart" -Value 0 -Type DWord -Force *>&1 | Out-File -FilePath $global:LogPath -Append -Encoding UTF8
        }
    }
    
    if (Get-Service -Name "SgrmBroker" -ErrorAction SilentlyContinue 2>> $env:SystemDrive\EastricaTools\Eastrica_ErrorTrace.log) {
        Apply-Tweak "Включение брокера System Guard" { Set-ItemProperty -Path "HKLM:\SYSTEM\CurrentControlSet\Services\SgrmBroker" -Name "Start" -Value 2 -Type DWord -Force *>&1 | Out-File -FilePath $global:LogPath -Append -Encoding UTF8 } # Возвращаем System Guard
        Apply-Tweak "Запуск брокера System Guard" { Start-Service -Name "SgrmBroker" *>&1 | Out-File -FilePath $global:LogPath -Append -Encoding UTF8 }
    }
    
    # 4. Включение Virtual Machine Queues на сетевых адаптерах (Для мостов Hyper-V)
    Get-NetAdapter | Where-Object { $_.PhysicalMediaType -eq '802.3' } | ForEach-Object {
        $adapterName = $_.Name
        if (Get-NetAdapterVmq -Name $adapterName -ErrorAction SilentlyContinue) {
            try { Apply-Tweak "Включение очередей VMQ на сетевой карте ($adapterName)" { Enable-NetAdapterVmq -Name $adapterName -ErrorAction Stop *>&1 | Out-File -FilePath $global:LogPath -Append -Encoding UTF8 } } catch {}
        } else {
            Write-Host " ► [Пропуск] VMQ не поддерживается сетевой картой ($adapterName)." -ForegroundColor DarkGray
        }
    }
    
    # 5. Включение Kernel DMA Protection
    if (!(Test-Path $DmaKey)) { Apply-Tweak "Создание раздела DMA Protection" { New-Item $DmaKey -Force *>&1 | Out-File -FilePath $global:LogPath -Append -Encoding UTF8 } }
    Apply-Tweak "Включение Kernel DMA Protection" { Set-ItemProperty -Path $DmaKey -Name "DeviceEnumerationPolicy" -Value 1 -Type DWord -Force *>&1 | Out-File -FilePath $global:LogPath -Append -Encoding UTF8 } # Включаем DMA защиту аппаратно
}

# Скрытие предупреждения в Центре безопасности Защитника об отключенной Изоляции Ядра
$WSC_DeviceGuard = "HKLM:\SOFTWARE\Microsoft\Windows Defender Security Center\Device guard"
if (!(Test-Path $WSC_DeviceGuard)) { Apply-Tweak "Создание раздела WSC Device Guard" { New-Item $WSC_DeviceGuard -Force *>&1 | Out-File -FilePath $global:LogPath -Append -Encoding UTF8 } }
Apply-Tweak "Скрытие предупреждения Защитника об отключенной изоляции" { Set-ItemProperty -Path $WSC_DeviceGuard -Name "DisableDeviceGuard" -Value 1 -Type DWord -Force *>&1 | Out-File -FilePath $global:LogPath -Append -Encoding UTF8 } # Игнорировать предупреждения Device Guard

Write-Host ""
# ==============================================================================
# Раздел 11: Таймеры ядра, DWM и визуальные эффекты (понижение инпут-лага)
# ==============================================================================
Show-ProgressStep -StepNum 11 -TotalSteps 81 -Activity "Сброс таймеров, твики DWM и умная адаптация..."
Write-Host "==============================================================================" -ForegroundColor DarkGray
Write-Host "РАЗДЕЛ 11: ТАЙМЕРЫ ЯДРА, DWM И ВИЗУАЛЬНЫЕ ЭФФЕКТЫ (ПОНИЖЕНИЕ ИНПУТ-ЛАГА)" -ForegroundColor Cyan
Write-Host "==============================================================================" -ForegroundColor DarkGray

# Компиляция API для высокоточного замера системного таймера ядра (NtQueryTimerResolution)
if (-not ("TimerAPI" -as [type])) {
    Add-Type -TypeDefinition @"
    using System;
    using System.Runtime.InteropServices;
    public class TimerAPI {
        [DllImport("ntdll.dll")]
        public static extern int NtQueryTimerResolution(out uint MaximumResolution, out uint MinimumResolution, out uint CurrentResolution);
        public static double GetCurrentResolutionMs() {
            uint max, min, cur;
            if (NtQueryTimerResolution(out max, out min, out cur) == 0) {
                return cur / 10000.0;
            }
            return 0.0;
        }
    }
"@
}
$global:TimerResBefore = [TimerAPI]::GetCurrentResolutionMs()

$global:RefreshRate = [DisplayAPI]::GetPrimaryHz() # Сохраняем герцовку монитора (например, 144 или 240) в глобальную переменную

# Возврат системы к штатному заводскому состоянию таймеров ядра
$BcdState = cmd.exe /c "bcdedit /enum {current}" # Считываем текущую конфигурацию загрузчика BCD

# Явно указываем идентификатор {current}, чтобы bcdedit на Windows 10/11 не выдавал ошибку синтаксиса
# Удаляем принудительный флаг платформенного тика (возврат к авто-выбору ОС)
if ($BcdState -match "useplatformtick") {
    Apply-Tweak "Удаление принудительного флага платформенного тика (useplatformtick)" { 
        cmd.exe /c "bcdedit /deletevalue {current} useplatformtick >nul 2>&1"
        $global:LASTEXITCODE = 0
    }
}
# Удаляем принудительное использование HPET
if ($BcdState -match "useplatformclock") {
    Apply-Tweak "Удаление принудительного использования HPET в BCD (useplatformclock)" { 
        cmd.exe /c "bcdedit /deletevalue {current} useplatformclock >nul 2>&1"
        $global:LASTEXITCODE = 0
    }
}
# Удаляем отключение динамических тиков (на современных ПК они экономят энергию без вреда)
if ($BcdState -match "disabledynamictick") {
    Apply-Tweak "Удаление запрета динамических тиков ядра (disabledynamictick)" { 
        cmd.exe /c "bcdedit /deletevalue {current} disabledynamictick >nul 2>&1"
        $global:LASTEXITCODE = 0
    }
}
# Удаляем аппаратную синхронизацию таймеров процессора
if ($BcdState -match "tscsyncpolicy") {
    Apply-Tweak "Удаление принудительной синхронизации TSC (tscsyncpolicy)" { 
        cmd.exe /c "bcdedit /deletevalue {current} tscsyncpolicy >nul 2>&1"
        $global:LASTEXITCODE = 0
    }
}

# Восстановление таймеров сырого ввода мыши (защита от жесткости и пропусков опроса)
$WinNT = "HKLM:\SOFTWARE\Microsoft\Windows NT\CurrentVersion\Windows"
if (!(Test-Path $WinNT)) { Apply-Tweak "Создание раздела Windows NT" { New-Item -Path $WinNT -Force *>&1 | Out-File -FilePath $global:LogPath -Append -Encoding UTF8 } }

Apply-Tweak "Восстановление пауз между прерываниями мыши" { Remove-ItemProperty -Path $WinNT -Name "RITDaemonTimerPowerSaveElapse" *>&1 | Out-File -FilePath $global:LogPath -Append -Encoding UTF8 }
Apply-Tweak "Восстановление склеивания таймеров прерываний мыши" { Remove-ItemProperty -Path $WinNT -Name "RITDaemonTimerPowerSaveCoalescing" *>&1 | Out-File -FilePath $global:LogPath -Append -Encoding UTF8 }
Apply-Tweak "Удаление обнуления бинарного кэша таймеров (TimerCoalescing)" { Remove-ItemProperty -Path $WinNT -Name "TimerCoalescing" *>&1 | Out-File -FilePath $global:LogPath -Append -Encoding UTF8 }

# Удаляем ошибочные ключи (с опечаткой "demon"), которые годами гуляют по интернету
Apply-Tweak "Удаление ошибочного ключа RITdemonTimerPowerSaveElapse" { Remove-ItemProperty -Path $WinNT -Name "RITdemonTimerPowerSaveElapse" *>&1 | Out-File -FilePath $global:LogPath -Append -Encoding UTF8 } # Очищаем мусорный ключ-опечатку
Apply-Tweak "Удаление ошибочного ключа RITdemonTimerPowerSaveCoalescing" { Remove-ItemProperty -Path $WinNT -Name "RITdemonTimerPowerSaveCoalescing" *>&1 | Out-File -FilePath $global:LogPath -Append -Encoding UTF8 } # Очищаем мусорный ключ-опечатку

# Оптимизация MPO (Multi-Plane Overlay) в оконном менеджере (DWM)
$DwmKey = "HKLM:\SOFTWARE\Microsoft\Windows\Dwm"
if (!(Test-Path $DwmKey)) { Apply-Tweak "Создание раздела DWM" { New-Item $DwmKey -Force *>&1 | Out-File -FilePath $global:LogPath -Append -Encoding UTF8 } } # Создаем раздел DWM
Apply-Tweak "Захват прав на ветку DWM" { Grant-RegPermission -RegPath $DwmKey } # Взламываем права на ветку DWM

# Умное определение мониторов (с отсевом виртуальных адаптеров и заглушек)
Add-Type -AssemblyName System.Windows.Forms 2>> $env:SystemDrive\EastricaTools\Eastrica_ErrorTrace.log
$TotalScreens = [System.Windows.Forms.Screen]::AllScreens.Count

# Если в системе висит Parsec Virtual Adapter, вычитаем его из списка дисплеев
$HasVirtualDisplay = (Get-CimInstance Win32_VideoController | Where-Object { $_.Name -match "Parsec|Virtual|Idd" })
if ($HasVirtualDisplay -and $TotalScreens -gt 1) {
    $RealScreensCount = $TotalScreens - 1
} else {
    $RealScreensCount = $TotalScreens
}

# Считаем систему многомониторной, только если РЕАЛЬНЫХ рабочих экранов больше одного
$global:IsMultiMonitor = ($RealScreensCount -gt 1)

if ($global:IsMultiMonitor) {
    Write-Host " ► Обнаружено несколько активных мониторов ($RealScreensCount шт.). Режим защиты DWM активен." -ForegroundColor Yellow
} else {
    Write-Host " ► Обнаружен одиночный игровой монитор. Активирован режим минимального инпут-лага." -ForegroundColor Green
}

if ($global:IsMultiMonitor) {
    Write-Host " ► [2 Монитора] Применяем безопасные настройки MPO (Защита DWM)" -ForegroundColor Yellow
    Apply-Tweak "Удаление лимитов MPO (Возврат аппаратного многоплоскостного вывода)" { Remove-ItemProperty -Path $DwmKey -Name "OverlayTestMode" *>&1 | Out-File -FilePath $global:LogPath -Append -Encoding UTF8 }
    Apply-Tweak "Удаление лимитов кадров MPO" { Remove-ItemProperty -Path $DwmKey -Name "OverlayMinFPS" *>&1 | Out-File -FilePath $global:LogPath -Append -Encoding UTF8 }
    Apply-Tweak "Разрешение аппаратного DirectFlip в драйвере" { Set-ItemProperty -Path $DwmKey -Name "MpoDisable" -Value 0 -Type DWord -Force *>&1 | Out-File -FilePath $global:LogPath -Append -Encoding UTF8 }
} else {
    if ($global:RefreshRate -le 75) {
        Apply-Tweak "Удаление лимитов MPO (Штатный режим)" { Remove-ItemProperty -Path $DwmKey -Name "OverlayTestMode" *>&1 | Out-File -FilePath $global:LogPath -Append -Encoding UTF8 }
    } else {
        # OverlayTestMode = 5 переводит DWM в Single-Plane режим (отключает многоплоскостные слои MPO),
        # что устраняет мерцание (flickering) и черные вспышки в играх на видеокартах NVIDIA и AMD.
        Apply-Tweak "Отключение многоплоскостного оверлея MPO (OverlayTestMode 5 - Фикс мерцания)" { Set-ItemProperty -Path $DwmKey -Name "OverlayTestMode" -Value 5 -Type DWord -Force *>&1 | Out-File -FilePath $global:LogPath -Append -Encoding UTF8 }
    }
    Apply-Tweak "Устранение зависаний Chromium-приложений (OverlayMinFPS)" { Set-ItemProperty -Path $DwmKey -Name "OverlayMinFPS" -Value 0 -Type DWord -Force *>&1 | Out-File -FilePath $global:LogPath -Append -Encoding UTF8 }
    Apply-Tweak "Удаление отключения MPO DirectFlip" { Remove-ItemProperty -Path $DwmKey -Name "MpoDisable" *>&1 | Out-File -FilePath $global:LogPath -Append -Encoding UTF8 }
}
Apply-Tweak "Асинхронные порты IOCP для ввода DWM" { Set-ItemProperty -Path $DwmKey -Name "DwmInputUsesIoCompletionPort" -Value 1 -Type DWord -Force *>&1 | Out-File -FilePath $global:LogPath -Append -Encoding UTF8 } # Перевод обработки ввода DWM на асинхронные порты завершения (IOCP)
Apply-Tweak "Разрешение прямой обработки ввода DWM" { Set-ItemProperty -Path $DwmKey -Name "EnableDwmInputProcessing" -Value 1 -Type DWord -Force *>&1 | Out-File -FilePath $global:LogPath -Append -Encoding UTF8 } # Разрешение прямой обработки ввода
Apply-Tweak "Ускорение маршрутизации мыши (MIT)" { Set-ItemProperty -Path $DwmKey -Name "EnableMitInputProcessing" -Value 1 -Type DWord -Force *>&1 | Out-File -FilePath $global:LogPath -Append -Encoding UTF8 } # Ускорение маршрутизации мыши (MIT)
Apply-Tweak "Запрет выгрузки текстур DWM в файл подкачки" { Set-ItemProperty -Path $DwmKey -Name "EnableSystematicTrimming" -Value 0 -Type DWord -Force *>&1 | Out-File -FilePath $global:LogPath -Append -Encoding UTF8 } # Запрет выгрузки текстур оконного менеджера в файл подкачки
Apply-Tweak "Аппаратный курсор мыши" { Set-ItemProperty -Path $DwmKey -Name "EnableHardwareCursor" -Value 1 -Type DWord -Force *>&1 | Out-File -FilePath $global:LogPath -Append -Encoding UTF8 } # Аппаратный курсор мыши (Снимает нагрузку с CPU при фликах)
Apply-Tweak "Включение современного конвейера вывода (Modern Present)" { Set-ItemProperty -Path $DwmKey -Name "EnableModernPresent" -Value 1 -Type DWord -Force *>&1 | Out-File -FilePath $global:LogPath -Append -Encoding UTF8 } # Включает современный конвейер вывода кадров (Modern Present)
Apply-Tweak "Удаление форсированного отключения Vsync DWM (Фикс задержек кадра)" { 
    Remove-ItemProperty -Path $DwmKey -Name "ForceVsyncOff" *>&1 | Out-File -FilePath $global:LogPath -Append -Encoding UTF8 # Удаляем ForceVsyncOff, так как принудительное отключение VSync на уровне DWM ломает кадровые очереди и вызывает микрофризы.
    Remove-ItemProperty -Path "HKCU:\Software\Microsoft\Windows\DWM" -Name "ForceVsyncOff" *>&1 | Out-File -FilePath $global:LogPath -Append -Encoding UTF8
}
Apply-Tweak "Восстановление системной задержки оконного вывода" { Remove-ItemProperty -Path $DwmKey -Name "EnableWindowedLatencyReduction" *>&1 | Out-File -FilePath $global:LogPath -Append -Encoding UTF8 }
Apply-Tweak "Разрешение DWM склеивать кадры при перегрузке GPU" { Set-ItemProperty -Path $DwmKey -Name "DisableFramePacing" -Value 0 -Type DWord -Force *>&1 | Out-File -FilePath $global:LogPath -Append -Encoding UTF8 } # Разрешает DWM склеивать кадры при перегрузке GPU (защита от слайд-шоу)
Apply-Tweak "Удаление старого ключа Composition (Фикс черного экрана)" { Remove-ItemProperty -Path $DwmKey -Name "Composition" *>&1 | Out-File -FilePath $global:LogPath -Append -Encoding UTF8 } # Удаляем старый ключ отключения композитинга (В Win10+ он вызывает черный экран)

# Оптимизация усреднения кадров DWM (Exclusive mode / Low latency)
$DwmExtKey = "HKLM:\SOFTWARE\Microsoft\Windows\Dwm\ExtendedComposition"
if (!(Test-Path $DwmExtKey)) { Apply-Tweak "Создание подраздела ExtendedComposition DWM" { New-Item -Path $DwmExtKey -Force *>&1 | Out-File -FilePath $global:LogPath -Append -Encoding UTF8 } }

Apply-Tweak "Захват прав на ветку ExtendedComposition" { Grant-RegPermission -RegPath $DwmExtKey }

# Выставляем период усреднения 100 мс (0x64) для минимального инпут-лага эксклюзивного режима
Apply-Tweak "Ускорение периода усреднения кадров DWM (AveragingPeriodMs = 100ms)" { 
    Set-ItemProperty -Path $DwmExtKey -Name "ExclusiveModeFramerateAveragingPeriodMs" -Value 100 -Type DWord -Force *>&1 | Out-File -FilePath $global:LogPath -Append -Encoding UTF8 
}
Apply-Tweak "Возврат прав системе на ExtendedComposition" { Restore-RegPermission -RegPath $DwmExtKey }

# Отключение анимации при смене разрешения (Мгновенный Alt+Tab в играх)
Apply-Tweak "Отключение анимации смены видеорежима DWM (ForceDisableModeChangeAnimation)" {
    Set-ItemProperty -Path $DwmKey -Name "ForceDisableModeChangeAnimation" -Value 1 -Type DWord -Force *>&1 | Out-File -FilePath $global:LogPath -Append -Encoding UTF8
}

# Аппаратное отключение композитора голографии VR в DWM
Apply-Tweak "Отключение VR-композитора в DWM (DisableHologramCompositor)" {
    Set-ItemProperty -Path $DwmKey -Name "DisableHologramCompositor" -Value 1 -Type DWord -Force *>&1 | Out-File -FilePath $global:LogPath -Append -Encoding UTF8
}

# Отключение паразитной подсистемы Super Wet Ink (Устранение DPC-спайков ввода)
Apply-Tweak "Отключение подсистемы Super Wet Ink" {
    Set-ItemProperty -Path $DwmKey -Name "SuperWetEnabled" -Value 0 -Type DWord -Force *>&1 | Out-File -FilePath $global:LogPath -Append -Encoding UTF8
    Set-ItemProperty -Path $DwmKey -Name "SuperWetExtensionTimeMicroseconds" -Value 0 -Type DWord -Force *>&1 | Out-File -FilePath $global:LogPath -Append -Encoding UTF8
}

# Отключение внутренней телеметрии сбора кадров DWM
Apply-Tweak "Отключение телеметрии кадров DWM" {
    Set-ItemProperty -Path $DwmKey -Name "TelemetryFramesReportPeriodMilliseconds" -Value 0 -Type DWord -Force *>&1 | Out-File -FilePath $global:LogPath -Append -Encoding UTF8
    Set-ItemProperty -Path $DwmKey -Name "TelemetryFramesSequenceMaximumPeriodMilliseconds" -Value 0 -Type DWord -Force *>&1 | Out-File -FilePath $global:LogPath -Append -Encoding UTF8
    Set-ItemProperty -Path $DwmKey -Name "TelemetryFramesSequenceIdleIntervalMilliseconds" -Value 0 -Type DWord -Force *>&1 | Out-File -FilePath $global:LogPath -Append -Encoding UTF8
}
Apply-Tweak "Восстановление прав системы на ветку DWM" { Restore-RegPermission -RegPath $DwmKey } # Возвращаем права системе

$GraphicsDriversKey = "HKLM:\SYSTEM\CurrentControlSet\Control\GraphicsDrivers"
if (!(Test-Path $GraphicsDriversKey)) { Apply-Tweak "Создание раздела GraphicsDrivers" { New-Item $GraphicsDriversKey -Force *>&1 | Out-File -FilePath $global:LogPath -Append -Encoding UTF8 } } # Создаем раздел графических драйверов
Apply-Tweak "Разрешение оверлеев (Xbox Game Bar/Discord)" { Set-ItemProperty -Path $GraphicsDriversKey -Name "DisableOverlays" -Value 0 -Type DWord -Force *>&1 | Out-File -FilePath $global:LogPath -Append -Encoding UTF8 } # 0 = Оверлеи разрешены (Это важно для работы Xbox Game Bar и Discord Overlay)

# Настройка визуальных эффектов (освобождение VRAM и снижение задержек)
$ExplorerAdv = "HKCU:\Software\Microsoft\Windows\CurrentVersion\Explorer\Advanced"
$Desktop = "HKCU:\Control Panel\Desktop"
$WindowMetrics = "HKCU:\Control Panel\Desktop\WindowMetrics"
$DWM = "HKCU:\Software\Microsoft\Windows\DWM"
$VisualFX = "HKCU:\Software\Microsoft\Windows\CurrentVersion\Explorer\VisualEffects"

if (!(Test-Path $DWM)) { Apply-Tweak "Создание раздела DWM пользователя" { New-Item -Path $DWM -Force *>&1 | Out-File -FilePath $global:LogPath -Append -Encoding UTF8 } }
if (!(Test-Path $VisualFX)) { Apply-Tweak "Создание раздела VisualEffects" { New-Item -Path $VisualFX -Force *>&1 | Out-File -FilePath $global:LogPath -Append -Encoding UTF8 } }

Apply-Tweak "Включение пользовательских визуальных эффектов" { Set-ItemProperty -Path $VisualFX -Name "VisualFXSetting" -Value 3 -Type DWord -Force *>&1 | Out-File -FilePath $global:LogPath -Append -Encoding UTF8 } # 3 = Пользовательские (Кастомные) настройки визуальных эффектов
Apply-Tweak "Анимации панели задач (Защита от лагов GUI)" { Set-ItemProperty -Path $ExplorerAdv -Name "TaskbarAnimations" -Value 1 -Type DWord -Force *>&1 | Out-File -FilePath $global:LogPath -Append -Encoding UTF8 } # 1 = Оставляем базовые анимации панели задач (иначе она "лагает" визуально)
Apply-Tweak "Мгновенное сворачивание/разворачивание окон (MinAnimate)" { Set-ItemProperty -Path $WindowMetrics -Name "MinAnimate" -Value "0" -Type String -Force *>&1 | Out-File -FilePath $global:LogPath -Append -Encoding UTF8 } # 0 = Отключаем анимацию сворачивания/разворачивания окон (Мгновенное открытие)
Apply-Tweak "Отключение Aero Peek (Предпросмотр стола)" { Set-ItemProperty -Path $DWM -Name "EnableAeroPeek" -Value 0 -Type DWord -Force *>&1 | Out-File -FilePath $global:LogPath -Append -Encoding UTF8 } # 0 = Отключаем Aero Peek (предпросмотр рабочего стола при наведении в правый нижний угол)
if ($global:RefreshRate -le 75) {
    Apply-Tweak "Запрет разрывов кадров в окне (Обычный монитор)" { Remove-ItemProperty -Path $DWM -Name "AllowTearing" *>&1 | Out-File -FilePath $global:LogPath -Append -Encoding UTF8 }
} else {
    Apply-Tweak "Разрешение разрывов кадров (Tearing) в окне" { Set-ItemProperty -Path $DWM -Name "AllowTearing" -Value 1 -Type DWord -Force *>&1 | Out-File -FilePath $global:LogPath -Append -Encoding UTF8 } # 1 = Разрешаем разрывы кадров (Tearing) в оконном режиме (снижает инпут-лаг)
}
Apply-Tweak "Отображение эскизов файлов вместо иконок" { Set-ItemProperty -Path $ExplorerAdv -Name "IconsOnly" -Value 0 -Type DWord -Force *>&1 | Out-File -FilePath $global:LogPath -Append -Encoding UTF8 } # 0 = Показывать эскизы файлов (картинки, видео), а не только иконки
Apply-Tweak "Отключение теней под значками на рабочем столе" { Set-ItemProperty -Path $ExplorerAdv -Name "ListviewShadow" -Value 0 -Type DWord -Force *>&1 | Out-File -FilePath $global:LogPath -Append -Encoding UTF8 } # 0 = Отключаем тени под значками на рабочем столе (Разгружает DWM)
Apply-Tweak "Полупрозрачный прямоугольник выделения (Удобство)" { Set-ItemProperty -Path $ExplorerAdv -Name "ListviewAlphaSelect" -Value 1 -Type DWord -Force *>&1 | Out-File -FilePath $global:LogPath -Append -Encoding UTF8 } # 1 = Оставляем полупрозрачный прямоугольник выделения (удобство)
Apply-Tweak "Отображение содержимого окна при перетаскивании" { Set-ItemProperty -Path $Desktop -Name "DragFullWindows" -Value "1" -Type String -Force *>&1 | Out-File -FilePath $global:LogPath -Append -Encoding UTF8 } # 1 = Показывать содержимое окна при перетаскивании
Apply-Tweak "Сглаживание шрифтов ClearType" { Set-ItemProperty -Path $Desktop -Name "FontSmoothing" -Value "2" -Type String -Force *>&1 | Out-File -FilePath $global:LogPath -Append -Encoding UTF8 } # 2 = Оставляем сглаживание шрифтов ClearType (иначе текст будет "вырвиглазным")
Apply-Tweak "Тип сглаживания ClearType (FontSmoothingType)" { Set-ItemProperty -Path $Desktop -Name "FontSmoothingType" -Value 2 -Type DWord -Force *>&1 | Out-File -FilePath $global:LogPath -Append -Encoding UTF8 } # Тип сглаживания = ClearType
Apply-Tweak "Запрет DWM усыплять эскизы окон (Мгновенный Alt+Tab)" { Set-ItemProperty -Path $DWM -Name "AlwaysHibernateThumbnails" -Value 0 -Type DWord -Force *>&1 | Out-File -FilePath $global:LogPath -Append -Encoding UTF8 } # 0 = Запрещаем DWM усыплять эскизы окон (мгновенный Alt+Tab)

# Отключение эффектов прозрачности (Aero Glass / Mica)
$ThemesPersonalize = "HKCU:\Software\Microsoft\Windows\CurrentVersion\Themes\Personalize"
Apply-Tweak "Отключение эффектов прозрачности (Снижение нагрузки GPU)" { Set-ItemProperty -Path $ThemesPersonalize -Name "EnableTransparency" -Value 0 -Type DWord -Force *>&1 | Out-File -FilePath $global:LogPath -Append -Encoding UTF8 } # 0 = Прозрачность отключена (Снимает колоссальную нагрузку с видеокарты при отрисовке интерфейса)

# Отключение размытия (Акрила) на экране входа в систему
$SystemExt = "HKLM:\SOFTWARE\Policies\Microsoft\Windows\System"
if (!(Test-Path $SystemExt)) { Apply-Tweak "Создание раздела политик System" { New-Item $SystemExt -Force *>&1 | Out-File -FilePath $global:LogPath -Append -Encoding UTF8 } }
Apply-Tweak "Отключение размытия на экране входа в систему" { Set-ItemProperty -Path $SystemExt -Name "DisableAcrylicBackgroundOnLogon" -Value 1 -Type DWord -Force *>&1 | Out-File -FilePath $global:LogPath -Append -Encoding UTF8 } # 1 = Отключает блюр на лок-скрине

# Отключение DWM Holographic (Скрытый стек VR)
$Holographic = "HKLM:\SOFTWARE\Microsoft\Windows\CurrentVersion\Holographic"
if (!(Test-Path $Holographic)) { Apply-Tweak "Создание раздела Holographic" { New-Item $Holographic -Force *>&1 | Out-File -FilePath $global:LogPath -Append -Encoding UTF8 } }
Apply-Tweak "Выгрузка библиотек голографии (Holographic) из DWM" { Set-ItemProperty -Path $Holographic -Name "FirstRunSucceeded" -Value 0 -Type DWord -Force *>&1 | Out-File -FilePath $global:LogPath -Append -Encoding UTF8 } # Сбрасываем флаг успешного запуска голографии (выгружает библиотеки из DWM)

if (Get-Service -Name "MixedRealityOpenXRSvc" -ErrorAction SilentlyContinue 2>> $env:SystemDrive\EastricaTools\Eastrica_ErrorTrace.log) {
    Apply-Tweak "Отключение службы Mixed Reality OpenXR" { Set-ItemProperty -Path "HKLM:\SYSTEM\CurrentControlSet\Services\MixedRealityOpenXRSvc" -Name "Start" -Value 4 -Type DWord -Force *>&1 | Out-File -FilePath $global:LogPath -Append -Encoding UTF8 } # Отключаем службу Mixed Reality OpenXR
}

$DwmLimit = "HKCU:\Software\Microsoft\Windows\DWM"
if (!(Test-Path $DwmLimit)) { Apply-Tweak "Создание раздела лимитов DWM" { New-Item $DwmLimit -Force *>&1 | Out-File -FilePath $global:LogPath -Append -Encoding UTF8 } }
Apply-Tweak "Удаление Max3DWindowedPresentLimit (Возврат к системному Present Queue)" { Remove-ItemProperty -Path $DwmLimit -Name "Max3DWindowedPresentLimit" *>&1 | Out-File -FilePath $global:LogPath -Append -Encoding UTF8 }

$Flags = 3 # Флаг обновления профиля пользователя (SPIF_UPDATEINIFILE | SPIF_SENDCHANGE)

Apply-Tweak "Аппаратное ускорение анимаций (SPI_SETUIEFFECTS)" { [void][UIAnim]::SystemParametersInfo(0x1043, 0, [IntPtr]1, $Flags) } # Включаем аппаратное ускорение анимаций (оставшихся)
Apply-Tweak "Отключение выцветания меню (SPI_SETMENUFADE)" { [void][UIAnim]::SystemParametersInfo(0x1015, 0, [IntPtr]0, $Flags) } # Отключаем анимацию меню (выцветание)
Apply-Tweak "Отключение аппаратной тени окна (SPI_SETDROPSHADOW)" { [void][UIAnim]::SystemParametersInfo(0x1025, 0, [IntPtr]0, $Flags) } # Отключаем грязную рамку (тень)
Apply-Tweak "Включение ClearType на аппаратном уровне (SPI_SETCLEARTYPE)" { [void][UIAnim]::SystemParametersInfo(0x1049, 0, [IntPtr]1, $Flags) } # Включаем ClearType на аппаратном уровне
Apply-Tweak "Отключение скольжения комбо-боксов (SPI_SETCOMBOBOXANIMATION)" { [void][UIAnim]::SystemParametersInfo(0x101B, 0, [IntPtr]0, $Flags) } # Отключаем скольжение комбо-боксов
Apply-Tweak "Отключение анимации фокуса кнопок (SPI_SETMENUANIMATION)" { [void][UIAnim]::SystemParametersInfo(0x1005, 0, [IntPtr]0, $Flags) } # Отключаем анимацию фокуса кнопок
Apply-Tweak "Отключение анимации списков (SPI_SETLISTBOXSMOOTHSCROLLING)" { [void][UIAnim]::SystemParametersInfo(0x1003, 0, [IntPtr]0, $Flags) } # Отключаем анимацию списков
Apply-Tweak "Отключение тени от курсора мыши (SPI_SETCURSORSHADOW)" { [void][UIAnim]::SystemParametersInfo(0x1017, 0, [IntPtr]0, $Flags) } # Отключаем тень от курсора мыши
Apply-Tweak "Включение плоского отображения меню (SPI_SETFLATMENU)" { [void][UIAnim]::SystemParametersInfo(0x103F, 0, [IntPtr]1, $Flags) } # Включаем плоское отображение меню

Write-Host ""
# ==============================================================================
# Раздел 12: Планировщик, приоритеты и IFEO (Image File Execution Options)
# ==============================================================================
Show-ProgressStep -StepNum 12 -TotalSteps 81 -Activity "Настройка планировщика и приоритетов IFEO..."
Write-Host "==============================================================================" -ForegroundColor DarkGray
Write-Host "РАЗДЕЛ 12: ПЛАНИРОВЩИК, ПРИОРИТЕТЫ И IFEO (IMAGE FILE EXECUTION OPTIONS)" -ForegroundColor Cyan
Write-Host "==============================================================================" -ForegroundColor DarkGray
$Kernel = "HKLM:\SYSTEM\CurrentControlSet\Control\Session Manager\kernel"
$PriControl = "HKLM:\SYSTEM\CurrentControlSet\Control\PriorityControl"
$KernelVelocity = "HKLM:\SYSTEM\CurrentControlSet\Control\KernelVelocity"

# Системные таймеры должны оставаться на Core 0, чтобы не прерывать потоки игры на остальных ядрах
Apply-Tweak "Удаление DistributeTimers (Защита игровых ядер от прерываний таймера)" { 
    Remove-ItemProperty -Path $Kernel -Name "DistributeTimers" *>&1 | Out-File -FilePath $global:LogPath -Append -Encoding UTF8 
}

# Фикс деградации FPS (Foreground Boost Decay)
Apply-Tweak "Запрет постепенного снятия приоритета с игры (ForegroundBoostDecay)" { Set-ItemProperty -Path $Kernel -Name "ForceForegroundBoostDecay" -Value 0 -Type DWord -Force *>&1 | Out-File -FilePath $global:LogPath -Append -Encoding UTF8 } # 0 = Запрещает ядру плавно снимать выданный игре приоритет. FPS перестанет падать через 30 минут игры.

# Аппаратный контроль зависаний процессора (DPC Watchdog)
Apply-Tweak "Включение мгновенного BSOD при зависании драйвера (DpcWatchdog)" { Set-ItemProperty -Path $Kernel -Name "ForceBugcheckForDpcWatchdog" -Value 1 -Type DWord -Force *>&1 | Out-File -FilePath $global:LogPath -Append -Encoding UTF8 } # 1 = Если драйвер повесил CPU, система мгновенно выдаст BSOD, а не будет "намертво" висеть.

# Предсказуемый планировщик (Kernel Auto-Boost)
Apply-Tweak "Разрешение мгновенного авто-повышения приоритетов фоновых задач" { Set-ItemProperty -Path $Kernel -Name "DisableAutoBoost" -Value 0 -Type DWord -Force *>&1 | Out-File -FilePath $global:LogPath -Append -Encoding UTF8 } # 0 = Разрешает ядру мгновенно повышать приоритет фоновых задач для быстрого освобождения ресурсов и ухода обратно в фон.

# Плавность распределения нагрузки (Idle Grace Period)
Apply-Tweak "Увеличение буфера простоя (Сглаживание микрофризов)" { Set-ItemProperty -Path $Kernel -Name "ForceIdleGracePeriod" -Value 5 -Type DWord -Force *>&1 | Out-File -FilePath $global:LogPath -Append -Encoding UTF8 } # Увеличиваем буфер простоя до 5 секунд (сглаживает микрофризы при резких скачках нагрузки)

# Игнорирование запросов BIOS на парковку ядер
Apply-Tweak "Игнорирование ACPI-команд парковки ядер" { Set-ItemProperty -Path $Kernel -Name "ForceParkingRequested" -Value 1 -Type DWord -Force *>&1 | Out-File -FilePath $global:LogPath -Append -Encoding UTF8 } # 1 = ОС игнорирует ACPI-команды на парковку (Парковкой управляет только наш профиль питания)

# Кванты планировщика (Win32PrioritySeparation)
if (!(Test-Path $PriControl)) { Apply-Tweak "Создание раздела PriorityControl" { New-Item -Path $PriControl -Force *>&1 | Out-File -FilePath $global:LogPath -Append -Encoding UTF8 } }
Apply-Tweak "Установка монолитных квантов планировщика (Win32PrioritySeparation = 42)" { Set-ItemProperty -Path $PriControl -Name "Win32PrioritySeparation" -Value 42 -Type DWord -Force *>&1 | Out-File -FilePath $global:LogPath -Append -Encoding UTF8 } # 42 (0x2A Hex). Эта бинарная маска задает короткие фиксированные кванты (Short Fixed) с максимальным приоритетом активного окна (3:1). Снижает задержки ввода (отклик мыши и клавиатуры в играх), даёт высокую отзывчивость активному приложению.

# DeepIoCoalescingEnabled считывается менеджером питания Windows строго из ветки Control\Power (в PriorityControl ключ не работает)
# 0 = Полное отключение объединения запросов ввода-вывода (мгновенное выполнение дисковых операций без задержки ожидания пачки)
$PowerRoot = "HKLM:\SYSTEM\CurrentControlSet\Control\Power"
Apply-Tweak "Отключение склеивания запросов накопителей (DeepIoCoalescingEnabled = 0)" { 
    Set-ItemProperty -Path $PowerRoot -Name "DeepIoCoalescingEnabled" -Value 0 -Type DWord -Force *>&1 | Out-File -FilePath $global:LogPath -Append -Encoding UTF8
}

# Очистка ошибочных записей из PriorityControl (эти ключи никогда не считывались планировщиком Windows)
Apply-Tweak "Очистка невалидных параметров PriorityControl" { 
    Remove-ItemProperty -Path $PriControl -Name "DeepIoCoalescingEnabled" -Force -ErrorAction SilentlyContinue *>&1 | Out-File -FilePath $global:LogPath -Append -Encoding UTF8
    Remove-ItemProperty -Path $PriControl -Name "EnableInputThreadBoost" -Force -ErrorAction SilentlyContinue *>&1 | Out-File -FilePath $global:LogPath -Append -Encoding UTF8
}

# Отключение опроса режима планшета в планировщике
Apply-Tweak "Отключение датчиков трансформации в планшет (ConvertibilityEnabled=0)" { 
    Set-ItemProperty -Path $PriControl -Name "ConvertibilityEnabled" -Value 0 -Type DWord -Force *>&1 | Out-File -FilePath $global:LogPath -Append -Encoding UTF8
    Set-ItemProperty -Path $PriControl -Name "ConvertibleSlateMode" -Value 0 -Type DWord -Force *>&1 | Out-File -FilePath $global:LogPath -Append -Encoding UTF8 # 0 = Запрещает драйверам (mouclass/kbdclass) непрерывно опрашивать ACPI/GPIO пины материнской платы на предмет того, не отсоединили ли вы экран от клавиатуры (как в Surface). На стационарных ПК этот опрос работает вхолостую и генерирует DPC-задержки.
}

# Очистка фиктивных параметров из Session Manager\kernel (ядро ntoskrnl.exe не поддерживает ручные ключи TSCDeadline и KdDisable)
Apply-Tweak "Очистка невалидных параметров ядра (TSCDeadline, KdDisable)" { 
    Remove-ItemProperty -Path $Kernel -Name "TSCDeadline" -Force -ErrorAction SilentlyContinue *>&1 | Out-File -FilePath $global:LogPath -Append -Encoding UTF8
    Remove-ItemProperty -Path $Kernel -Name "KdDisable" -Force -ErrorAction SilentlyContinue *>&1 | Out-File -FilePath $global:LogPath -Append -Encoding UTF8
}

# Защита от деградации приоритета игры в Windows 11 (KernelVelocity)
if (!(Test-Path $KernelVelocity)) { Apply-Tweak "Создание раздела KernelVelocity" { New-Item -Path $KernelVelocity -Force *>&1 | Out-File -FilePath $global:LogPath -Append -Encoding UTF8 } }
Apply-Tweak "Запрет снятия приоритета окна в Windows 11 (DisableFGBoostDecay = 1)" { 
    Set-ItemProperty -Path $KernelVelocity -Name "DisableFGBoostDecay" -Value 1 -Type DWord -Force *>&1 | Out-File -FilePath $global:LogPath -Append -Encoding UTF8
}

# Очистка старых твиков IFEO
# IFEO часто используется мамкиными "твикерами" для установки безумных приоритетов системным процессам, что ломает ОС.
$ifeoPaths = @(
    "HKLM:\SOFTWARE\Microsoft\Windows NT\CurrentVersion\Image File Execution Options\dwm.exe",
    "HKLM:\SOFTWARE\Microsoft\Windows NT\CurrentVersion\Image File Execution Options\csrss.exe",
    "HKLM:\SOFTWARE\Microsoft\Windows NT\CurrentVersion\Image File Execution Options\ctfmon.exe",
    "HKLM:\SOFTWARE\Microsoft\Windows NT\CurrentVersion\Image File Execution Options\lsass.exe",
    "HKLM:\SOFTWARE\Microsoft\Windows NT\CurrentVersion\Image File Execution Options\winlogon.exe",
    "HKLM:\SOFTWARE\Microsoft\Windows NT\CurrentVersion\Image File Execution Options\wmiadap.exe"
)
foreach ($ifeoPath in $ifeoPaths) {
    if (Test-Path -LiteralPath $ifeoPath) { Apply-Tweak "Удаление старых твиков IFEO ($ifeoPath)" { Remove-Item -LiteralPath $ifeoPath -Recurse -Force *>&1 | Out-File -FilePath $global:LogPath -Append -Encoding UTF8 } } # Удаляем старые ветки
}

# Оптимизация локальной службы безопасности (LSASS)
if (-not $global:OptAntiCheat) {
    $LsassPerf = "HKLM:\SOFTWARE\Microsoft\Windows NT\CurrentVersion\Image File Execution Options\lsass.exe\PerfOptions"
    if (!(Test-Path $LsassPerf)) { Apply-Tweak "Создание раздела PerfOptions для lsass.exe" { New-Item -Path $LsassPerf -Force | Out-Null } }
    Apply-Tweak "Высокий приоритет CPU для lsass.exe (Защита от фризов аутентификации)" { Set-ItemProperty -Path $LsassPerf -Name "CpuPriorityClass" -Value 3 -Type DWord -Force *>&1 | Out-File -FilePath $global:LogPath -Append -Encoding UTF8 }
} else {
    # В режиме античита ветка lsass.exe уже гарантированно очищена выше в общем блоке ifeoPaths
    $LsassKey = "HKLM:\SOFTWARE\Microsoft\Windows NT\CurrentVersion\Image File Execution Options\lsass.exe"
    if (Test-Path $LsassKey) {
        Apply-Tweak "Удаление IFEO для lsass.exe (Режим Античита)" { Remove-Item -LiteralPath $LsassKey -Recurse -Force *>&1 | Out-File -FilePath $global:LogPath -Append -Encoding UTF8 }
    }
}

# Оптимизация DWM.exe (Менеджер окон рабочего стола)
$DwmPerf = "HKLM:\SOFTWARE\Microsoft\Windows NT\CurrentVersion\Image File Execution Options\dwm.exe\PerfOptions"
if (!(Test-Path $DwmPerf)) { Apply-Tweak "Создание раздела PerfOptions для dwm.exe" { New-Item -Path $DwmPerf -Force | Out-Null } }
Apply-Tweak "Очистка статической маски ядер DWM (Делегирование Thread Director)" { Remove-ItemProperty -Path $DwmPerf -Name "CpuAffinityMask" *>&1 | Out-File -FilePath $global:LogPath -Append -Encoding UTF8 } # Очищаем постоянную статическую маску DWM. Динамической изоляцией займется Thread Director во время игры.

if ($global:RefreshRate -le 75) {
    # Если монитор 60 Гц, DWM справляется сам. Высокий приоритет только задушит процессор.
    Apply-Tweak "Сброс приоритета DWM (Монитор <= 75Hz)" { Remove-ItemProperty -Path $DwmPerf -Name "CpuPriorityClass" *>&1 | Out-File -FilePath $global:LogPath -Append -Encoding UTF8 }
} else {
    # Для мониторов 120Hz+ DWM должен получать процессорное время моментально, иначе курсор на рабочем столе будет лагать.
    Apply-Tweak "Высокий приоритет DWM (Монитор 120Hz+)" { Set-ItemProperty -Path $DwmPerf -Name "CpuPriorityClass" -Value 3 -Type DWord -Force *>&1 | Out-File -FilePath $global:LogPath -Append -Encoding UTF8 } # 3 = High
}

# Изоляция телеметрии WMI (WmiPrvSE.exe)
$WmiIfeo = "HKLM:\SOFTWARE\Microsoft\Windows NT\CurrentVersion\Image File Execution Options\WmiPrvSE.exe\PerfOptions"
if (-not $global:OptAntiCheat) {
    if (!(Test-Path $WmiIfeo)) { Apply-Tweak "Создание раздела PerfOptions для WmiPrvSE.exe" { New-Item -Path $WmiIfeo -Force *>&1 | Out-File -FilePath $global:LogPath -Append -Encoding UTF8 } }
    Apply-Tweak "Активация EcoQoS для WMI телеметрии" { Set-ItemProperty -Path $WmiIfeo -Name "EcoLevel" -Value 1 -Type DWord -Force *>&1 | Out-File -FilePath $global:LogPath -Append -Encoding UTF8 } # 1 = EcoQoS (Жесткий энергосберегающий режим)
    Apply-Tweak "Удаление старого приоритета WMI" { Remove-ItemProperty -Path $WmiIfeo -Name "CpuPriorityClass" *>&1 | Out-File -FilePath $global:LogPath -Append -Encoding UTF8 } # Удаляем попытки выставить приоритет
    Apply-Tweak "Минимальный приоритет I/O для WMI" { Set-ItemProperty -Path $WmiIfeo -Name "IoPriority" -Value 1 -Type DWord -Force *>&1 | Out-File -FilePath $global:LogPath -Append -Encoding UTF8 } # 1 = Low I/O (Минимальная скорость чтения диска)
} else {
    # Античиты мониторят WMI для проверки состояния системы. Удаляем ограничения.
    if (Test-Path $WmiIfeo) { Apply-Tweak "Удаление IFEO для WmiPrvSE.exe (Режим Античита)" { Remove-Item -LiteralPath $WmiIfeo -Recurse -Force 2>> $env:SystemDrive\EastricaTools\Eastrica_ErrorTrace.log } }
}

# Очистка браузеров от постоянного занижения приоритета в реестре.
# Браузеры должны работать на штатном приоритете при повседневном использовании.
# Их временным переводом в EcoQoS во время матча управляет исключительно Eastrica Thread Director.
$BgApps = @("chrome.exe", "msedge.exe", "opera.exe", "brave.exe", "firefox.exe", "Spotify.exe")
foreach ($App in $BgApps) {
    $AppPerf = "HKLM:\SOFTWARE\Microsoft\Windows NT\CurrentVersion\Image File Execution Options\$App\PerfOptions"
    if (Test-Path $AppPerf) {
        Apply-Tweak "Удаление постоянного занижения приоритета для $App" { 
            Remove-ItemProperty -Path $AppPerf -Name "CpuPriorityClass" -Force -ErrorAction SilentlyContinue *>&1 | Out-File -FilePath $global:LogPath -Append -Encoding UTF8
            Remove-ItemProperty -Path $AppPerf -Name "IoPriority" -Force -ErrorAction SilentlyContinue *>&1 | Out-File -FilePath $global:LogPath -Append -Encoding UTF8
        }
    }
}

# Занижение приоритета ТОЛЬКО для сторонних игровых лаунчеров и второстепенных хелперов
$IdleApps = @("EpicWebHelper.exe", "RockstarService.exe", "SocialClubHelper.exe", "UplayWebCore.exe", "upc.exe", "EABackgroundService.exe", "EADesktop.exe", "QtWebEngineProcess.exe", "splwow64.exe", "SearchApp.exe", "SearchHost.exe")
foreach ($App in $IdleApps) {
    $AppPath = "HKLM:\SOFTWARE\Microsoft\Windows NT\CurrentVersion\Image File Execution Options\$App\PerfOptions"
    if (!(Test-Path $AppPath)) { Apply-Tweak "Создание IFEO для $App" { New-Item -Path $AppPath -Force *>&1 | Out-File -FilePath $global:LogPath -Append -Encoding UTF8 } }
    # 1 = IdlePriorityClass (процессы выполняются только тогда, когда процессор свободен от игры)
    Apply-Tweak "Простаивающий приоритет (Idle) для $App" { Set-ItemProperty -Path $AppPath -Name "CpuPriorityClass" -Value 1 -Type DWord -Force *>&1 | Out-File -FilePath $global:LogPath -Append -Encoding UTF8 }
}

# Очистка системных компонентов Windows от ошибочного замедления:
# runtimebroker.exe отвечает за работу UWP и меню Пуск, SystemSettings.exe — окно Параметры, sppsvc.exe — служба лицензий.
# Их принудительное замедление до Idle вызывало мертвое зависание интерфейса Windows 10/11.
$CriticalSystemComponents = @("runtimebroker.exe", "SystemSettings.exe", "sppsvc.exe")
foreach ($SysApp in $CriticalSystemComponents) {
    $SysAppPath = "HKLM:\SOFTWARE\Microsoft\Windows NT\CurrentVersion\Image File Execution Options\$SysApp\PerfOptions"
    if (Test-Path $SysAppPath) {
        Apply-Tweak "Восстановление стандартного приоритета для $SysApp" { 
            Remove-Item -LiteralPath $SysAppPath -Recurse -Force -ErrorAction SilentlyContinue *>&1 | Out-File -FilePath $global:LogPath -Append -Encoding UTF8 
        }
    }
}

# Изоляция античитов (Только если пользователь сам отключил режим совместимости с античитами)
if (-not $global:OptAntiCheat) {
    $AntiCheats = @("EasyAntiCheat.exe", "EasyAntiCheat_EOS.exe", "BEService.exe", "BlackCipher.exe")
    foreach ($AC in $AntiCheats) {
        $AcPath = "HKLM:\SOFTWARE\Microsoft\Windows NT\CurrentVersion\Image File Execution Options\$AC\PerfOptions"
        if (!(Test-Path $AcPath)) { Apply-Tweak "Создание IFEO для $AC" { New-Item -Path $AcPath -Force *>&1 | Out-File -FilePath $global:LogPath -Append -Encoding UTF8 } }
        
        Apply-Tweak "Понижение приоритета CPU для $AC" { Set-ItemProperty -Path $AcPath -Name "CpuPriorityClass" -Value 5 -Type DWord -Force *>&1 | Out-File -FilePath $global:LogPath -Append -Encoding UTF8 }
        Apply-Tweak "Понижение приоритета I/O для $AC" { Set-ItemProperty -Path $AcPath -Name "IoPriority" -Value 1 -Type DWord -Force *>&1 | Out-File -FilePath $global:LogPath -Append -Encoding UTF8 }
        
        if ($global:TotalLogCores -ge 8) {
            [uint64]$ValidSysMask = if ($global:TotalLogCores -ge 64) { [uint64]::MaxValue } else { ([uint64]1 -shl $global:TotalLogCores) - 1 }
            [uint64]$AcAffinity = $ValidSysMask -band (-bnot [uint64]15)
            Apply-Tweak "Изоляция ядер для $AC" { Set-ItemProperty -Path $AcPath -Name "CpuAffinityMask" -Value $AcAffinity -Type QWord -Force *>&1 | Out-File -FilePath $global:LogPath -Append -Encoding UTF8 }
        }
    }
} else {
    # В режиме совместимости гарантированно очищаем любые старые ограничения с античитов
    $AntiCheats = @("EasyAntiCheat.exe", "EasyAntiCheat_EOS.exe", "BEService.exe", "BlackCipher.exe")
    foreach ($AC in $AntiCheats) {
        $AcPath = "HKLM:\SOFTWARE\Microsoft\Windows NT\CurrentVersion\Image File Execution Options\$AC"
        if (Test-Path $AcPath) {
            Apply-Tweak "Очистка ограничений с античита $AC (Режим совместимости)" { Remove-Item -LiteralPath $AcPath -Recurse -Force *>&1 | Out-File -FilePath $global:LogPath -Append -Encoding UTF8 }
        }
    }
}

# Активация EcoQoS (Режим эффективности Windows 11) для лаунчеров
$EcoApps = @("steamwebhelper.exe", "EpicWebHelper.exe", "Spotify.exe", "EADesktop.exe", "upc.exe")
foreach ($App in $EcoApps) {
    $AppPath = "HKLM:\SOFTWARE\Microsoft\Windows NT\CurrentVersion\Image File Execution Options\$App\PerfOptions"
    if (!(Test-Path $AppPath)) { Apply-Tweak "Создание IFEO для $App" { New-Item -Path $AppPath -Force *>&1 | Out-File -FilePath $global:LogPath -Append -Encoding UTF8 } }
    Apply-Tweak "Активация EcoQoS (Эффективность) для $App" { Set-ItemProperty -Path $AppPath -Name "EcoLevel" -Value 1 -Type DWord -Force *>&1 | Out-File -FilePath $global:LogPath -Append -Encoding UTF8 } # 1 = EcoQoS Level 1 (Позволяет планировщику Windows скидывать эти процессы на энергоэффективные E-Cores).
}

# Восстановление стандартного приоритета для драйвера шрифтов (Защита от заиканий UI)
$FontHostPerf = "HKLM:\SOFTWARE\Microsoft\Windows NT\CurrentVersion\Image File Execution Options\FontDrvHost.exe\PerfOptions"
if (Test-Path $FontHostPerf) {
    Apply-Tweak "Удаление ограничений приоритета FontDrvHost.exe" { Remove-Item -LiteralPath $FontHostPerf -Recurse -Force *>&1 | Out-File -FilePath $global:LogPath -Append -Encoding UTF8 }
}

if (-not $global:OptAntiCheat) {
    $IsDualCcdX3D = ($global:ProcInfo.Name -match "7900X3D|7950X3D|9900X3D|9950X3D")
    $TrapApps = @("GameBarFTServer.exe", "bcastdvr.exe", "Cortana.exe")
    if (-not $IsDualCcdX3D) { $TrapApps += "GameBarPresenceWriter.exe" }
    foreach ($Trap in $TrapApps) {
        $TrapPath = "HKLM:\SOFTWARE\Microsoft\Windows NT\CurrentVersion\Image File Execution Options\$Trap"
        $SilentExitPath = "HKLM:\SOFTWARE\Microsoft\Windows NT\CurrentVersion\SilentProcessExit\$Trap"
        
        if (!(Test-Path $TrapPath)) { Apply-Tweak "Создание IFEO для $Trap" { New-Item -Path $TrapPath -Force *>&1 | Out-File -FilePath $global:LogPath -Append -Encoding UTF8 } }
        if (!(Test-Path $SilentExitPath)) { Apply-Tweak "Создание SilentProcessExit для $Trap" { New-Item -Path $SilentExitPath -Force *>&1 | Out-File -FilePath $global:LogPath -Append -Encoding UTF8 } }
        
        Apply-Tweak "Активация перенаправления (GlobalFlag) для $Trap" { Set-ItemProperty -Path $TrapPath -Name "GlobalFlag" -Value 512 -Type DWord -Force *>&1 | Out-File -FilePath $global:LogPath -Append -Encoding UTF8 } # 512 = Разрешить Silent Process Exit (Перенаправление)
        Apply-Tweak "Удаление ложного Debugger для $Trap" { Remove-ItemProperty -Path $TrapPath -Name "Debugger" *>&1 | Out-File -FilePath $global:LogPath -Append -Encoding UTF8 }
        Apply-Tweak "Тихое завершение работы (ReportingMode) для $Trap" { Set-ItemProperty -Path $SilentExitPath -Name "ReportingMode" -Value 0 -Type DWord -Force *>&1 | Out-File -FilePath $global:LogPath -Append -Encoding UTF8 } # 0 = Тихо завершить работу без создания отчета об ошибке
    }
} else {
    # Восстанавливаем процессы для античитов (иначе могут кикнуть за вмешательство в ОС)
    $TrapApps = @("GameBarFTServer.exe", "GameBarPresenceWriter.exe", "bcastdvr.exe", "Cortana.exe")
    foreach ($Trap in $TrapApps) {
        $TrapIfeo = "HKLM:\SOFTWARE\Microsoft\Windows NT\CurrentVersion\Image File Execution Options\$Trap"
        $TrapSilent = "HKLM:\SOFTWARE\Microsoft\Windows NT\CurrentVersion\SilentProcessExit\$Trap"
        if (Test-Path $TrapIfeo) {
            Apply-Tweak "Удаление IFEO для $Trap (Режим Античита)" { Remove-Item -LiteralPath $TrapIfeo -Recurse -Force *>&1 | Out-File -FilePath $global:LogPath -Append -Encoding UTF8 }
        }
        if (Test-Path $TrapSilent) {
            Apply-Tweak "Удаление SilentProcessExit для $Trap (Режим Античита)" { Remove-Item -LiteralPath $TrapSilent -Recurse -Force *>&1 | Out-File -FilePath $global:LogPath -Append -Encoding UTF8 }
        }
    }
}

# Изоляция периферии и СВО (Убийство DPC LATENCY от фонового поллинга USB)
# Расчет безопасной маски для софта охлаждения (Исключаем Core 0 и Core 1, но даем доступ ко всем остальным)
$PhysCores = [int]$global:ProcInfo.NumberOfCores
$HasSMT = ($global:TotalLogCores -gt $PhysCores)
$SkipThreads = if ($HasSMT) { 4 } else { 2 } # Пропускаем потоки первых 2 физических ядер

[uint64]$CoolingAffinityMask = 0
for ($i = $SkipThreads; $i -lt $global:TotalLogCores; $i++) {
    if ($i -lt 64) {
        $CoolingAffinityMask = $CoolingAffinityMask -bor ([uint64]1 -shl $i)
    }
}
if ($CoolingAffinityMask -eq 0) { $CoolingAffinityMask = [uint64]::MaxValue }

# Группа А: Критический софт помп и вентиляторов
# Приоритет Below Normal (5) уступает игре, но гарантирует своевременное срабатывание вентиляторов при нагреве CPU/GPU.
# Внимание: MSI Afterburner и HWiNFO сюда добавлять нельзя! Они должны работать на стандартном приоритете.
$CoolingHardwareApps = @(
    "NZXTCAM.exe", "cam_helper.exe",                  # NZXT
    "L-Connect 3.exe", "L-Connect.exe",               # Lian Li
    "Aquasuite.exe", "AquaComputerService.exe",       # Aqua Computer
    "FanControl.exe",                                 # Rem0o Fan Control (Самая популярная утилита)
    "ArgusMonitor.exe",                               # Argus Monitor
    "SpeedFan.exe",                                   # SpeedFan
    "Corsair.Service.exe",                            # Аппаратная служба Corsair (Управляет помпами iCUE)
    "AsusFanControlService.exe",                      # ASUS AI Suite (Кулеры)
    "GCC.exe",                                        # Gigabyte Control Center
    "MSI.CentralServer.exe",                          # Ядро MSI Center
    "TT RGB Plus.exe",                                # Thermaltake (Управляет помпами)
    "MasterPlus.exe",                                 # Cooler Master
    "PrecisionX_x64.exe", "PrecisionX.exe",           # EVGA Precision X1
    "GPU Tweak III.exe"                               # ASUS GPU Tweak
)

foreach ($App in $CoolingHardwareApps) {
    $PerfPath = "HKLM:\SOFTWARE\Microsoft\Windows NT\CurrentVersion\Image File Execution Options\$App\PerfOptions"
    if (!(Test-Path $PerfPath)) { 
        Apply-Tweak "Создание IFEO для софта охлаждения $App" { New-Item -Path $PerfPath -Force *>&1 | Out-File -FilePath $global:LogPath -Append -Encoding UTF8 } 
    }
    
    # 5 = Below Normal (Уступает игре, но не зависает при 100% нагрузке CPU)
    Apply-Tweak "Безопасный приоритет CPU для $App (Below Normal)" { Set-ItemProperty -Path $PerfPath -Name "CpuPriorityClass" -Value 5 -Type DWord -Force *>&1 | Out-File -FilePath $global:LogPath -Append -Encoding UTF8 }
    Apply-Tweak "Низкий приоритет I/O для $App" { Set-ItemProperty -Path $PerfPath -Name "IoPriority" -Value 1 -Type DWord -Force *>&1 | Out-File -FilePath $global:LogPath -Append -Encoding UTF8 }
    Apply-Tweak "Запрет Large Pages для $App" { Set-ItemProperty -Path $PerfPath -Name "UseLargePages" -Value 0 -Type DWord -Force *>&1 | Out-File -FilePath $global:LogPath -Append -Encoding UTF8 }
    
    # Удаляем жесткую заморозку EcoQoS, чтобы помпа мгновенно реагировала на скачки температур
    Apply-Tweak "Удаление замедления EcoQoS для термоконтроля $App" { Remove-ItemProperty -Path $PerfPath -Name "EcoLevel" *>&1 | Out-File -FilePath $global:LogPath -Append -Encoding UTF8 }
    
    # Уводим софт с Core 0 (ОС) и Core 1 (Игра), но оставляем широкий пул ядер для снятия показаний датчиков
    if ($global:TotalLogCores -ge 6) {
        Apply-Tweak "Изоляция софта СВО $App вне игровых ядер" { Set-ItemProperty -Path $PerfPath -Name "CpuAffinityMask" -Value $CoolingAffinityMask -Type QWord -Force *>&1 | Out-File -FilePath $global:LogPath -Append -Encoding UTF8 }
    }
}

# Группа Б: Паразитный софт, подсветка и периферия (Bloatware)
# Этот софт не управляет жизнью железа. Его интерфейсы, телеметрия и облачные синхронизации вызывают огромные DPC-скачки.
# Мы удушаем их до "коматозного" состояния. Мыши и клавиатуры продолжат работать отлично через аппаратный Raw Input.
$BloatHardwareApps = @(
    # --- ASUS ---
    "LightingService.exe", "ArmouryCrate.UserSessionHelper.exe", "ArmouryCrate.Service.exe", 
    "AsusCertService.exe", "ROG Live Service.exe", "Aura.exe", 
    # --- CORSAIR ---
    "iCUE.exe", "Corsair.Service.DisplayAdapter.exe", "Corsair.Service.CpuIdRemote.exe", 
    # --- RAZER ---
    "Razer Synapse Service.exe", "Razer Central.exe", "RazerCortex.exe", 
    "GameManagerService.exe", "Razer Synapse 3.exe", 
    # --- LOGITECH ---
    "lghub.exe", "lghub_agent.exe", "lghub_updater.exe", "LogiOverlay.exe", 
    # --- STEELSERIES ---
    "SteelSeriesGG.exe", "SteelSeriesEngine.exe", "SteelSeriesGGClient.exe", 
    # --- ДРУГАЯ ПЕРИФЕРИЯ ---
    "NGenuity2.exe",           # HyperX
    "ROCCAT Swarm.exe",        # Roccat
    "Glorious Core.exe",       # Glorious
    "VPC.exe",                 # VGN / VXE / ATK Hub
    # --- RGB И МАТЕРИНСКИЕ ПЛАТЫ ---
    "RGBFusion.exe", "AORUS LCD Panel Setting.exe", # Gigabyte RGB
    "LightKeeperService.exe", "LedKeeper2.exe", "MysticLight.exe", # MSI RGB
    "PolychromeRGB.exe",       # ASRock
    "TridentZNvidia.exe",      # G.Skill
    "OpenRGB.exe", "SignalRGB.exe" # Универсальные RGB-контроллеры
)

$SafeLogCores = if ($global:TotalLogCores -gt 64) { 64 } else { $global:TotalLogCores }
$LastTwoThreadsMask = ([uint64]1 -shl ($SafeLogCores - 1)) -bor ([uint64]1 -shl ($SafeLogCores - 2))

foreach ($App in $BloatHardwareApps) {
    $PerfPath = "HKLM:\SOFTWARE\Microsoft\Windows NT\CurrentVersion\Image File Execution Options\$App\PerfOptions"
    if (!(Test-Path $PerfPath)) { 
        Apply-Tweak "Создание IFEO для фонового софта $App" { New-Item -Path $PerfPath -Force *>&1 | Out-File -FilePath $global:LogPath -Append -Encoding UTF8 } 
    }
    
    # 1 = Idle (Простой, выполняется только когда система полностью свободна)
    Apply-Tweak "Простаивающий приоритет (Idle) для подсветки $App" { Set-ItemProperty -Path $PerfPath -Name "CpuPriorityClass" -Value 1 -Type DWord -Force *>&1 | Out-File -FilePath $global:LogPath -Append -Encoding UTF8 }
    Apply-Tweak "Минимальный приоритет I/O для $App" { Set-ItemProperty -Path $PerfPath -Name "IoPriority" -Value 0 -Type DWord -Force *>&1 | Out-File -FilePath $global:LogPath -Append -Encoding UTF8 }
    Apply-Tweak "Активация EcoQoS для подсветки $App" { Set-ItemProperty -Path $PerfPath -Name "EcoLevel" -Value 1 -Type DWord -Force *>&1 | Out-File -FilePath $global:LogPath -Append -Encoding UTF8 }
    Apply-Tweak "Запрет Large Pages для $App" { Set-ItemProperty -Path $PerfPath -Name "UseLargePages" -Value 0 -Type DWord -Force *>&1 | Out-File -FilePath $global:LogPath -Append -Encoding UTF8 }
    
    if ($global:TotalLogCores -ge 8) {
        Apply-Tweak "Вытеснение подсветки/периферии $App на последние потоки" { Set-ItemProperty -Path $PerfPath -Name "CpuAffinityMask" -Value $LastTwoThreadsMask -Type QWord -Force *>&1 | Out-File -FilePath $global:LogPath -Append -Encoding UTF8 }
    }
}

# Отключение принудительного создания пула исполнительных потоков (Executive Worker Threads)
$Exec = "HKLM:\SYSTEM\CurrentControlSet\Control\Session Manager\Executive"
Apply-Tweak "Удаление ручного лимита критических потоков ядра" { Remove-ItemProperty -Path $Exec -Name "AdditionalCriticalWorkerThreads" *>&1 | Out-File -FilePath $global:LogPath -Append -Encoding UTF8 } # ОС должна сама динамически создавать потоки, ручной лимит вызывает DPC Latency
Apply-Tweak "Удаление ручного лимита отложенных потоков ядра" { Remove-ItemProperty -Path $Exec -Name "AdditionalDelayedWorkerThreads" *>&1 | Out-File -FilePath $global:LogPath -Append -Encoding UTF8 } # Удаление твика

# Настройка инфраструктуры DXGI (DirectX)
$DXGI = "HKLM:\SOFTWARE\Microsoft\DirectX\GraphicsInfrastructure"
if (!(Test-Path $DXGI)) { Apply-Tweak "Создание раздела DXGI" { New-Item -Path $DXGI -Force | Out-Null } }

# Удаляем устаревший лимит предрендера на уровне ОС (чтобы не душить отрисовку рабочего стола)
Apply-Tweak "Удаление устаревшего лимита предрендера DWM" { Remove-ItemProperty -Path $DXGI -Name "MaxFrameLatency" *>&1 | Out-File -FilePath $global:LogPath -Append -Encoding UTF8 }
# Разрешаем Windows использовать Independent Flip (Отсоединение окна от композитора DWM)
Apply-Tweak "Разрешение Independent Flip для окон" { Set-ItemProperty -Path $DXGI -Name "DisableIndependentFlip" -Value 0 -Type DWord -Force *>&1 | Out-File -FilePath $global:LogPath -Append -Encoding UTF8 }

# Активация Waitable SwapChain Lock
# Современный метод синхронизации CPU и GPU (Снижает инпут-лаг в окне).
$DxgiPaths = @("HKLM:\SOFTWARE\Microsoft\DirectX\GraphicsInfrastructure", "HKCU:\Software\Microsoft\DirectX\GraphicsInfrastructure")
$MaxFramesDwm = if ($global:RefreshRate -le 75) { 3 } else { 1 }

foreach ($Dxgi in $DxgiPaths) {
    if (!(Test-Path $Dxgi)) { Apply-Tweak "Создание подраздела DXGI ($Dxgi)" { New-Item $Dxgi -Force *>&1 | Out-File -FilePath $global:LogPath -Append -Encoding UTF8 } }
    if ($global:IsMultiMonitor) {
        Apply-Tweak "Откат очереди кадров Waitable SwapChain (Мультимонитор)" { Remove-ItemProperty -Path $Dxgi -Name "MaxWaitableSwapChainFrames" *>&1 | Out-File -FilePath $global:LogPath -Append -Encoding UTF8 }
        Apply-Tweak "Откат технологии Waitable SwapChain (Мультимонитор)" { Remove-ItemProperty -Path $Dxgi -Name "EnableWaitableSwapChain" *>&1 | Out-File -FilePath $global:LogPath -Append -Encoding UTF8 }
    } else {
        Apply-Tweak "Синхронизация кадрового буфера (MaxWaitableSwapChainFrames)" { Set-ItemProperty -Path $Dxgi -Name "MaxWaitableSwapChainFrames" -Value $MaxFramesDwm -Type DWord -Force *>&1 | Out-File -FilePath $global:LogPath -Append -Encoding UTF8 } # 1 = Заставляет процессор ждать, пока видеокарта не закончит рендер текущего кадра, прежде чем готовить следующий. Это убивает "буферизацию команд" и дает абсолютно синхронный отклик мыши в оконном режиме (как в эксклюзивном Fullscreen).
        Apply-Tweak "Включение технологии Waitable SwapChain" { Set-ItemProperty -Path $Dxgi -Name "EnableWaitableSwapChain" -Value 1 -Type DWord -Force *>&1 | Out-File -FilePath $global:LogPath -Append -Encoding UTF8 }
    }
}

# Предрендер для старых игр DirectX 9
$D3D9 = "HKLM:\SOFTWARE\Microsoft\Direct3D"
if (!(Test-Path $D3D9)) { Apply-Tweak "Создание раздела Direct3D" { New-Item $D3D9 -Force *>&1 | Out-File -FilePath $global:LogPath -Append -Encoding UTF8 } }
Apply-Tweak "Установка очереди кадров DirectX 9 ($MaxFramesDwm)" { Set-ItemProperty -Path $D3D9 -Name "MaxPrerenderedFrames" -Value $MaxFramesDwm -Type DWord -Force *>&1 | Out-File -FilePath $global:LogPath -Append -Encoding UTF8 } # CPU готовит кадры заранее

# Синхронизация DWM для мульти-мониторных систем
if ($global:IsMultiMonitor) {
    Apply-Tweak "Восстановление синхронизации окон между мониторами" { [Environment]::SetEnvironmentVariable("D3D11_ENABLE_PRESENT_ON_MULTIPLE_MONITORS", $null, "Machine") }
} else {
    Apply-Tweak "Отключение синхронизации окон между разными мониторами" { [Environment]::SetEnvironmentVariable("D3D11_ENABLE_PRESENT_ON_MULTIPLE_MONITORS", "0", "Machine") }
}

# Запрет отключения DirectFlip
Apply-Tweak "Разрешение аппаратного DirectFlip" { Set-ItemProperty -Path "HKLM:\SOFTWARE\Microsoft\DirectX" -Name "DisableDirectFlip" -Value 0 -Type DWord -Force *>&1 | Out-File -FilePath $global:LogPath -Append -Encoding UTF8 } # 0 = Разрешает использовать аппаратный DirectFlip

$WinNT = "HKLM:\SOFTWARE\Microsoft\Windows NT\CurrentVersion\Windows"
Apply-Tweak "Расширение квоты дескрипторов (Защита от крашей браузера)" { Set-ItemProperty -Path $WinNT -Name "UserProcessHandleQuota" -Value 18000 -Type DWord -Force *>&1 | Out-File -FilePath $global:LogPath -Append -Encoding UTF8 } # Расширяет квоту дескрипторов (Позволяет открывать тяжелые сцены в браузерах без крашей)
Apply-Tweak "Запрет авто-загрузки DLL в процессы (AppInit_DLLs)" { Set-ItemProperty -Path $WinNT -Name "LoadAppInit_DLLs" -Value 0 -Type DWord -Force *>&1 | Out-File -FilePath $global:LogPath -Append -Encoding UTF8 } # Запрет автоматической загрузки DLL в каждый процесс (Ускоряет запуск программ и защищает от вирусов)

# Принудительное включение VRR (Variable Refresh Rate) для старых игр
$DXUser = "HKCU:\Software\Microsoft\DirectX\UserGpuPreferences"
if (!(Test-Path $DXUser)) { Apply-Tweak "Создание раздела UserGpuPreferences" { New-Item -Path $DXUser -Force *>&1 | Out-File -FilePath $global:LogPath -Append -Encoding UTF8 } }
Apply-Tweak "Форсирование VRR (G-Sync/FreeSync) для старых игр" { Set-ItemProperty -Path $DXUser -Name "DirectXUserGlobalSettings" -Value "VRROptimizeEnable=1;SwapEffectUpgradeEnable=1;AutoHDR=0;GpuPreference=2;" -Type String -Force *>&1 | Out-File -FilePath $global:LogPath -Append -Encoding UTF8 } # VRROptimizeEnable=1 включает поддержку FreeSync/G-Sync в оконном режиме. AutoHDR=0 убивает лаги матрицы.

# Дополнительное форсирование DXGI Flip Model
$DXGraphics = "HKCU:\Software\Microsoft\DirectX\GraphicsSettings"
if (!(Test-Path $DXGraphics)) { Apply-Tweak "Создание раздела GraphicsSettings" { New-Item -Path $DXGraphics -Force *>&1 | Out-File -FilePath $global:LogPath -Append -Encoding UTF8 } }
Apply-Tweak "Оптимизация Vsync для игр" { Set-ItemProperty -Path $DXGraphics -Name "VsyncGameOptimize" -Value 1 -Type DWord -Force *>&1 | Out-File -FilePath $global:LogPath -Append -Encoding UTF8 } # Оптимизация Vsync для игр
Apply-Tweak "Кэш эффекта обмена кадров (SwapEffectUpgradeCache)" { Set-ItemProperty -Path $DXGraphics -Name "SwapEffectUpgradeCache" -Value 1 -Type DWord -Force *>&1 | Out-File -FilePath $global:LogPath -Append -Encoding UTF8 } # Кэш эффекта обмена кадров
Apply-Tweak "Аппаратный апгрейд оконных игр до DXGI Flip Model (SwapEffectUpgradeEnable = 1)" { Set-ItemProperty -Path $DXGraphics -Name "SwapEffectUpgradeEnable" -Value 1 -Type DWord -Force *>&1 | Out-File -FilePath $global:LogPath -Append -Encoding UTF8 } # Аппаратное включение Flip Model для DirectX 10/11
Apply-Tweak "Аппаратное форсирование Variable Rate Shading (VRSControl = 1)" { Set-ItemProperty -Path $DXGraphics -Name "VRSControl" -Value 1 -Type DWord -Force *>&1 | Out-File -FilePath $global:LogPath -Append -Encoding UTF8 } # Глобальное включение Variable Rate Shading (VRS) для DX12 (Дает 5-15% бесплатного FPS)

# Глобальное отключение Auto HDR (Убирает задержку конвертации цветового пространства)
$AutoHdr = "HKCU:\Software\Microsoft\Windows\CurrentVersion\VideoSettings"
if (!(Test-Path $AutoHdr)) { Apply-Tweak "Создание раздела VideoSettings" { New-Item $AutoHdr -Force | Out-Null } }
Apply-Tweak "Глобальное отключение Auto HDR" { Set-ItemProperty -Path $AutoHdr -Name "EnableAutoHDR" -Value 0 -Type DWord -Force *>&1 | Out-File -FilePath $global:LogPath -Append -Encoding UTF8 }

# Снятие ограничений аппаратного ускорения 2D-графики (GDI+ / DirectDraw)
$DirectDraw = "HKLM:\SOFTWARE\Microsoft\DirectDraw"
if (!(Test-Path $DirectDraw)) { Apply-Tweak "Создание раздела DirectDraw" { New-Item $DirectDraw -Force *>&1 | Out-File -FilePath $global:LogPath -Append -Encoding UTF8 } }
if ($global:IsMultiMonitor) {
    Apply-Tweak "Сброс запрета программного рендера 2D (ForceWDDMSoftware)" { Remove-ItemProperty -Path $DirectDraw -Name "ForceWDDMSoftware" *>&1 | Out-File -FilePath $global:LogPath -Append -Encoding UTF8 }
    Apply-Tweak "Сброс жесткого отключения 2D (DisableWDDMSoftware)" { Remove-ItemProperty -Path $DirectDraw -Name "DisableWDDMSoftware" *>&1 | Out-File -FilePath $global:LogPath -Append -Encoding UTF8 }
} else {
    Apply-Tweak "Запрет программного рендеринга 2D-графики (ForceWDDMSoftware)" { Set-ItemProperty -Path $DirectDraw -Name "ForceWDDMSoftware" -Value 0 -Type DWord -Force *>&1 | Out-File -FilePath $global:LogPath -Append -Encoding UTF8 }
    Apply-Tweak "Жесткое отключение программного рендеринга 2D (DisableWDDMSoftware)" { Set-ItemProperty -Path $DirectDraw -Name "DisableWDDMSoftware" -Value 1 -Type DWord -Force *>&1 | Out-File -FilePath $global:LogPath -Append -Encoding UTF8 }
}

Write-Host ""
# ==============================================================================
# Раздел 13: Прерывания, память и кэширование
# ==============================================================================
Show-ProgressStep -StepNum 13 -TotalSteps 81 -Activity "Настройка прерываний, памяти и чистка от устаревших твиков реестра..."
Write-Host "==============================================================================" -ForegroundColor DarkGray
Write-Host "РАЗДЕЛ 13: ПРЕРЫВАНИЯ, ПАМЯТЬ И КЭШИРОВАНИЕ" -ForegroundColor Cyan
Write-Host "==============================================================================" -ForegroundColor DarkGray

$MemMan = "HKLM:\SYSTEM\CurrentControlSet\Control\Session Manager\Memory Management" # Задаем путь к ветке управления памятью
$Prefetch = "HKLM:\SYSTEM\CurrentControlSet\Control\Session Manager\Memory Management\PrefetchParameters" # Задаем путь к параметрам предвыборки
$Video = "HKLM:\SYSTEM\CurrentControlSet\Services\nvlddmkm" # Путь к драйверу видеокарты NVIDIA
$TotalRAM = $global:TotalRAM # Получаем общий объем ОЗУ из глобальной переменной

Apply-Tweak "Отключение агрессивного кэширования файлов (LargeSystemCache)" { Set-ItemProperty -Path $MemMan -Name "LargeSystemCache" -Value 0 -Type DWord -Force *>&1 | Out-File -FilePath $global:LogPath -Append -Encoding UTF8 } # 0 = Отключаем агрессивное кэширование файлов (защита от утечек ОЗУ и фризов в играх)
Apply-Tweak "Отключение строгой защиты от записи в память" { Set-ItemProperty -Path $MemMan -Name "EnforceWriteProtection" -Value 0 -Type DWord -Force *>&1 | Out-File -FilePath $global:LogPath -Append -Encoding UTF8 } # 0 = Отключаем строгую защиту от записи в память
Apply-Tweak "Разрешение тримминга неактивной памяти Windows (Защита от OOM крашей)" { Remove-ItemProperty -Path $MemMan -Name "TrimWorkingSet" *>&1 | Out-File -FilePath $global:LogPath -Append -Encoding UTF8 } # Разрешить Windows нормально балансировать рабочий набор памяти и удалить запрет на тримминг

# Запрет выгрузки ядра отключен (Защита от синих экранов при работе NVIDIA Frame Generation)
Apply-Tweak "Разрешение выгрузки ядра ОС на диск (Защита от BSOD)" { Set-ItemProperty -Path $MemMan -Name "DisablePagingExecutive" -Value 0 -Type DWord -Force *>&1 | Out-File -FilePath $global:LogPath -Append -Encoding UTF8 } # 0 = Разрешаем выгрузку. Кэширование в Win11 работает отлично, жесткий запрет (1) приводит к BSOD в новых играх.

# Очистка устаревших твиков реестра (времен Windows XP/7)
Apply-Tweak "Удаление ручного лимита SystemPages" { Remove-ItemProperty -Path $MemMan -Name "SystemPages" *>&1 | Out-File -FilePath $global:LogPath -Append -Encoding UTF8 } # Удаляем ручной лимит SystemPages (в x64 ОС управляет автоматически)
Apply-Tweak "Удаление ручного лимита невыгружаемого пула" { Remove-ItemProperty -Path $MemMan -Name "NonPagedPoolSize" *>&1 | Out-File -FilePath $global:LogPath -Append -Encoding UTF8 } # Удаляем ручной лимит невыгружаемого пула
Apply-Tweak "Удаление лимита использования пула" { Remove-ItemProperty -Path $MemMan -Name "PoolUsageMaximum" *>&1 | Out-File -FilePath $global:LogPath -Append -Encoding UTF8 } # Удаляем лимит использования пула

Apply-Tweak "Мгновенное выключение ПК без зануления подкачки (ClearPageFileAtShutdown = 0)" { Set-ItemProperty -Path $MemMan -Name "ClearPageFileAtShutdown" -Value 0 -Type DWord -Force *>&1 | Out-File -FilePath $global:LogPath -Append -Encoding UTF8 } # Устранение 2-минутной задержки выключения ПК

# Эти ключи реестра никогда не существовали в архитектуре Windows NT. Это выдумка с форумов.
Apply-Tweak "Удаление фейкового твика IRQ8Priority" { Remove-ItemProperty -Path $PriControl -Name "IRQ8Priority" *>&1 | Out-File -FilePath $global:LogPath -Append -Encoding UTF8 } # Удаляем фейковый твик приоритета IRQ8
Apply-Tweak "Удаление фейкового твика IRQ16Priority" { Remove-ItemProperty -Path $PriControl -Name "IRQ16Priority" *>&1 | Out-File -FilePath $global:LogPath -Append -Encoding UTF8 } # Удаляем фейковый твик приоритета IRQ16

# Откат глубины очереди прерываний (DPC Queue Depth)
Apply-Tweak "Удаление ограничения глубины очереди DPC" { Remove-ItemProperty -Path $Kernel -Name "DpcQueueDepth" *>&1 | Out-File -FilePath $global:LogPath -Append -Encoding UTF8 } # Удаляем ограничение очереди DPC (снижает задержки)
Apply-Tweak "Удаление потоковых DPC (Возврат аппаратных прерываний)" { Remove-ItemProperty -Path $Kernel -Name "ThreadDpcEnable" *>&1 | Out-File -FilePath $global:LogPath -Append -Encoding UTF8 } # Удаляем потоковые DPC (возвращаем аппаратные)

# Зачистка вредоносных DPC-твиков ядра (Защита от BSOD 0x133 и хруста звука)
$KernelDpcTrash = @(
    "IdealDpcRate", "MaximumDpcQueueDepth", "MinimumDpcRate", "UnlimitDpcQueue",
    "AdjustDpcThreshold", "VerifierDpcScalingFactor", "DpcCumulativeSoftTimeout",
    "DpcWatchdogProfileBufferSizeBytes", "DynamicDpcProtocol", "MaximumDpcRate",
    "DpcRequestRate", "DpcRoutineActive", "DpcSoftTimeout", "DpcTimeLimit",
    "DpcWatchdogProfileCumulativeDpcThreshold", "DpcWatchdogProfileSingleDpcThreshold",
    "DpcDuration", "DpcLastCount", "DpcTimeCount", "ForceDpcDmaCoalesce"
)

foreach ($dpcKey in $KernelDpcTrash) {
    Apply-Tweak "Очистка опасного DPC-твика ($dpcKey)" {
        Remove-ItemProperty -Path "HKLM:\SYSTEM\CurrentControlSet\Control\Session Manager\kernel" -Name $dpcKey *>&1 | Out-File -FilePath $global:LogPath -Append -Encoding UTF8
        Remove-ItemProperty -Path "HKLM:\SYSTEM\CurrentControlSet\Control\PriorityControl" -Name $dpcKey *>&1 | Out-File -FilePath $global:LogPath -Append -Encoding UTF8
    }
}

# DPC Watchdog: удаление ручных заниженных таймаутов ядра во избежание BSOD 0x133
Apply-Tweak "Удаление ручного таймаута DPC (Защита от BSOD)" { 
    Remove-ItemProperty -Path $Kernel -Name "DpcTimeout" -Force -ErrorAction SilentlyContinue *>&1 | Out-File -FilePath $global:LogPath -Append -Encoding UTF8
    Remove-ItemProperty -Path $Kernel -Name "DpcWatchdogPeriod" -Force -ErrorAction SilentlyContinue *>&1 | Out-File -FilePath $global:LogPath -Append -Encoding UTF8
    Remove-ItemProperty -Path $Kernel -Name "DpcWatchdogProfileOffset" -Force -ErrorAction SilentlyContinue *>&1 | Out-File -FilePath $global:LogPath -Append -Encoding UTF8
}

$MinCache = [IntPtr](1024 * 1024) # 1 MB (Стандартный минимальный кэш ОС)
$MaxCache = [IntPtr](-1) # -1 = Безлимитный кэш (Ограничение кэша вызывает фризы в играх с открытым миром и убивает SSD)
Apply-Tweak "Снятие лимитов системного файлового кэша (API)" { [void][CacheAPI]::SetSystemFileCacheSize($MinCache, $MaxCache, 0) } # Применяем безлимитный кэш через CacheAPI

# Восстанавливаем стандартное управление памятью для видеодрайверов (Защита от TDR и зависаний памяти)
$AmdParams = "HKLM:\SYSTEM\CurrentControlSet\Services\amdkmdag"
if (Test-Path $AmdParams) { 
    Apply-Tweak "Восстановление управления памятью для AMD" { Remove-ItemProperty -Path $AmdParams -Name "DisablePagefileSwap" *>&1 | Out-File -FilePath $global:LogPath -Append -Encoding UTF8 } 
}
Apply-Tweak "Восстановление управления памятью для NVIDIA" { 
    Remove-ItemProperty -Path $Video -Name "DisablePagefileSwap" *>&1 | Out-File -FilePath $global:LogPath -Append -Encoding UTF8 
}

# Оптимизация буфера записи на SSD (Снижение износа NVMe и устранение I/O спайков)
$MemMan = "HKLM:\SYSTEM\CurrentControlSet\Control\Session Manager\Memory Management"
Apply-Tweak "Увеличение порога грязных страниц памяти (SystemCacheDirtyPageThreshold)" { 
    # Устанавливаем порог грязных страниц, при котором начинается сброс на диск
    Set-ItemProperty -Path $MemMan -Name "SystemCacheDirtyPageThreshold" -Value 65536 -Type DWord -Force *>&1 | Out-File -FilePath $global:LogPath -Append -Encoding UTF8 
}

# Оптимизация NUMA (Неравномерный доступ к памяти)
$NumaKey = "HKLM:\SYSTEM\CurrentControlSet\Control\NUMA" # Путь к ветке NUMA
if (!(Test-Path $NumaKey)) { Apply-Tweak "Создание раздела NUMA" { New-Item -Path $NumaKey -Force *>&1 | Out-File -FilePath $global:LogPath -Append -Encoding UTF8 } } # Создаем ветку, если её нет
Apply-Tweak "Удаление строгой групповой привязки потоков (NUMA)" { Remove-ItemProperty -Path $NumaKey -Name "GroupAffinityAssignment" *>&1 | Out-File -FilePath $global:LogPath -Append -Encoding UTF8 } # Включение параметра приводит к микрозадержкам шины Infinity Fabric и потере плавности в играх
Apply-Tweak "Удаление запрета миграции потоков между чиплетами (AMD CCD)" { Remove-ItemProperty -Path $NumaKey -Name "StrictNumaNodeAffinity" *>&1 | Out-File -FilePath $global:LogPath -Append -Encoding UTF8 } # Разрешаем ОС хаотично перекидывать потоки между чиплетами

if ($global:TotalLogCores -gt 16) {
    Apply-Tweak "Оптимизация распределения страниц памяти (NodeOptions)" { Set-ItemProperty -Path $MemMan -Name "NodeOptions" -Value 1 -Type DWord -Force *>&1 | Out-File -FilePath $global:LogPath -Append -Encoding UTF8 } # Оптимизируем распределение страниц памяти для многоядерных систем
}

# Очистка опасных твиков
Apply-Tweak "Восстановление склеивания записи NVIDIA (DisableWriteCombining)" { Remove-ItemProperty -Path $Video -Name "DisableWriteCombining" *>&1 | Out-File -FilePath $global:LogPath -Append -Encoding UTF8 } # Восстанавливаем склеивание записи для NVIDIA (ускоряет рендеринг)
Apply-Tweak "Удаление устаревшего твика LargePageDrivers" { Remove-ItemProperty -Path $MemMan -Name "LargePageDrivers" *>&1 | Out-File -FilePath $global:LogPath -Append -Encoding UTF8 } # Очистка устаревшего твика (защита от BSOD)
Apply-Tweak "Удаление интерливинга NUMA-узлов" { Remove-ItemProperty -Path $MemMan -Name "NumaNodeInterleave" *>&1 | Out-File -FilePath $global:LogPath -Append -Encoding UTF8 } # Очистка интерливинга NUMA-узлов
Apply-Tweak "Удаление твика MapPteNoExecute (Защита от BSOD)" { Remove-ItemProperty -Path $MemMan -Name "MapPteNoExecute" *>&1 | Out-File -FilePath $global:LogPath -Append -Encoding UTF8 } # Удаление твика (защита от банов в Античитах и BSOD)

Write-Host ""
# ==============================================================================
# Раздел 14: Мультимедиа, MMCSS и игровой режим
# ==============================================================================
Show-ProgressStep -StepNum 14 -TotalSteps 81 -Activity "Настройка MMCSS и Game Mode..."
Write-Host "==============================================================================" -ForegroundColor DarkGray
Write-Host "РАЗДЕЛ 14: МУЛЬТИМЕДИА, MMCSS И ИГРОВОЙ РЕЖИМ" -ForegroundColor Cyan
Write-Host "==============================================================================" -ForegroundColor DarkGray

$MMCSS = "HKLM:\SOFTWARE\Microsoft\Windows NT\CurrentVersion\Multimedia\SystemProfile" # Путь к мультимедийному профилю системы
# 0 = 100% процессорного времени доступно для активных мультимедиа и игровых потоков (значение 3 не входит в сетку шагов планировщика)
Apply-Tweak "Максимальный приоритет CPU для игр и мультимедиа (SystemResponsiveness = 0)" { 
    Set-ItemProperty -Path $MMCSS -Name "SystemResponsiveness" -Value 0 -Type DWord -Force *>&1 | Out-File -FilePath $global:LogPath -Append -Encoding UTF8 
}
# -1 (0xFFFFFFFF) = Полное отключение троттлинга сетевых пакетов при активности мультимедиа
Apply-Tweak "Отключение сетевого троттлинга MMCSS (NetworkThrottlingIndex = -1)" { Set-ItemProperty -Path $MMCSS -Name "NetworkThrottlingIndex" -Value -1 -Type DWord -Force *>&1 | Out-File -FilePath $global:LogPath -Append -Encoding UTF8 }
# 1 = Запрет диспетчеру задач переходить в режим экономии циклов при низкой активности потоков
Apply-Tweak "Отключение ленивого режима MMCSS (NoLazyMode = 1)" { Set-ItemProperty -Path $MMCSS -Name "NoLazyMode" -Value 1 -Type DWord -Force *>&1 | Out-File -FilePath $global:LogPath -Append -Encoding UTF8 }
# 0 = Мгновенная реакция планировщика без задержки ожидания
Apply-Tweak "Обнуление таймаута ленивого режима (LazyModeTimeout = 0)" { Set-ItemProperty -Path $MMCSS -Name "LazyModeTimeout" -Value 0 -Type DWord -Force *>&1 | Out-File -FilePath $global:LogPath -Append -Encoding UTF8 }

# Снятие ограничений пула потоков MMCSS
Apply-Tweak "Увеличение лимита мультимедиа потоков на процесс" { Set-ItemProperty -Path $MMCSS -Name "MaxThreadsPerProcess" -Value 128 -Type DWord -Force *>&1 | Out-File -FilePath $global:LogPath -Append -Encoding UTF8 } # Увеличиваем макс. количество мультимедиа-потоков на процесс до 128
Apply-Tweak "Увеличение глобального лимита мультимедиа потоков" { Set-ItemProperty -Path $MMCSS -Name "MaxThreadsTotal" -Value 65535 -Type DWord -Force *>&1 | Out-File -FilePath $global:LogPath -Append -Encoding UTF8 } # Увеличиваем глобальный лимит потоков в системе

# Ускорение цикла планировщика MMCSS
Apply-Tweak "Ускорение периода планировщика MMCSS (5 мс)" { Set-ItemProperty -Path $MMCSS -Name "SchedulerPeriod" -Value 50000 -Type DWord -Force *>&1 | Out-File -FilePath $global:LogPath -Append -Encoding UTF8 } # 50000 = 5мс (Минимально допустимый порог планировщика, по умолчанию 10мс)
Apply-Tweak "Ускорение таймера MMCSS (0.5 мс)" { Set-ItemProperty -Path $MMCSS -Name "SchedulerTimerResolution" -Value 5000 -Type DWord -Force *>&1 | Out-File -FilePath $global:LogPath -Append -Encoding UTF8 } # 5000 = 0.5мс (Синхронизируем таймер MMCSS с нашим C# таймером)

$GamesTask = "HKLM:\SOFTWARE\Microsoft\Windows NT\CurrentVersion\Multimedia\SystemProfile\Tasks\Games"
if (!(Test-Path $GamesTask)) { Apply-Tweak "Создание игрового профиля MMCSS" { New-Item -Path $GamesTask -Force *>&1 | Out-File -FilePath $global:LogPath -Append -Encoding UTF8 } }
# 8 = Максимально допустимое значение GPU Priority в архитектуре MMCSS (значения выше 8 недопустимы и сбрасывают приоритет в 0)
Apply-Tweak "Высший допустимый приоритет GPU для игр (GPU Priority = 8)" { Set-ItemProperty -Path $GamesTask -Name "GPU Priority" -Value 8 -Type DWord -Force *>&1 | Out-File -FilePath $global:LogPath -Append -Encoding UTF8 }
Apply-Tweak "Экстремальный приоритет CPU для игр" { Set-ItemProperty -Path $GamesTask -Name "Priority" -Value 3 -Type DWord -Force *>&1 | Out-File -FilePath $global:LogPath -Append -Encoding UTF8 }
Apply-Tweak "Категория диспетчеризации High для игр" { Set-ItemProperty -Path $GamesTask -Name "Scheduling Category" -Value "High" -Type String -Force *>&1 | Out-File -FilePath $global:LogPath -Append -Encoding UTF8 } # Высокая категория диспетчеризации
Apply-Tweak "Ускорение таймера MMCSS для профиля Games" { Set-ItemProperty -Path $GamesTask -Name "Clock Rate" -Value 5000 -Type DWord -Force *>&1 | Out-File -FilePath $global:LogPath -Append -Encoding UTF8 } # Ускоряем таймер для игр до 0.5ms
Apply-Tweak "Запрет игре уступать такты процессора (NoYield)" { Set-ItemProperty -Path $GamesTask -Name "NoYield" -Value 1 -Type DWord -Force *>&1 | Out-File -FilePath $global:LogPath -Append -Encoding UTF8 } # 1 = Запрещаем процессу игры уступать такты процессора другим задачам
Apply-Tweak "Маркировка игр как чувствительных к задержкам" { Set-ItemProperty -Path $GamesTask -Name "Latency Sensitive" -Value "True" -Type String -Force *>&1 | Out-File -FilePath $global:LogPath -Append -Encoding UTF8 } # Игра помечается как чувствительная к задержкам (как аудио-студия)

# Защита микрофона и вывода звука Discord от игровых статтеров
$AudioTasks = @("Audio", "Capture") # Профили воспроизведения и записи звука
foreach ($Task in $AudioTasks) {
    $TaskPath = "HKLM:\SOFTWARE\Microsoft\Windows NT\CurrentVersion\Multimedia\SystemProfile\Tasks\$Task"
    if (!(Test-Path $TaskPath)) { Apply-Tweak "Создание профиля MMCSS: $Task" { New-Item -Path $TaskPath -Force *>&1 | Out-File -FilePath $global:LogPath -Append -Encoding UTF8 } } # Создаем ветку
    Apply-Tweak "Приоритет 6 для профиля $Task (Защита звука)" { Set-ItemProperty -Path $TaskPath -Name "Priority" -Value 6 -Type DWord -Force *>&1 | Out-File -FilePath $global:LogPath -Append -Encoding UTF8 } # Ставим приоритет 6 (Защита от заиканий звука)
    Apply-Tweak "Высокая категория для профиля $Task" { Set-ItemProperty -Path $TaskPath -Name "Scheduling Category" -Value "High" -Type String -Force *>&1 | Out-File -FilePath $global:LogPath -Append -Encoding UTF8 } # Высокая категория
    Apply-Tweak "Приоритетная работа звука в фоне для $Task (Background Only = False)" { Set-ItemProperty -Path $TaskPath -Name "Background Only" -Value "False" -Type String -Force *>&1 | Out-File -FilePath $global:LogPath -Append -Encoding UTF8 }
}

# Разрешение доступа к микрофону (Защита от отключения голосового чата в играх и Discord)
$PrivacyAudio = "HKLM:\SOFTWARE\Microsoft\Windows\CurrentVersion\CapabilityAccessManager\ConsentStore\microphone"
Apply-Tweak "Разрешение доступа к микрофону для голосовых чатов" { Set-ItemProperty -Path $PrivacyAudio -Name "Value" -Value "Allow" -Type String -Force *>&1 | Out-File -FilePath $global:LogPath -Append -Encoding UTF8 }

# Профиль "Pro Audio" (Профессиональное аудио)
$ProAudioPath = "HKLM:\SOFTWARE\Microsoft\Windows NT\CurrentVersion\Multimedia\SystemProfile\Tasks\Pro Audio"
if (!(Test-Path $ProAudioPath)) { Apply-Tweak "Создание профиля Pro Audio" { New-Item -Path $ProAudioPath -Force *>&1 | Out-File -FilePath $global:LogPath -Append -Encoding UTF8 } }
Apply-Tweak "Разрешение Pro Audio использовать все ядра" { Set-ItemProperty -Path $ProAudioPath -Name "Affinity" -Value 0 -Type DWord -Force *>&1 | Out-File -FilePath $global:LogPath -Append -Encoding UTF8 } # Разрешаем использовать все ядра
Apply-Tweak "Отключение Background Only для Pro Audio" { Set-ItemProperty -Path $ProAudioPath -Name "Background Only" -Value "False" -Type String -Force *>&1 | Out-File -FilePath $global:LogPath -Append -Encoding UTF8 } # Работает не только в фоне
Apply-Tweak "Ускорение таймера для Pro Audio" { Set-ItemProperty -Path $ProAudioPath -Name "Clock Rate" -Value 5000 -Type DWord -Force *>&1 | Out-File -FilePath $global:LogPath -Append -Encoding UTF8 } # Таймер 0.5ms
Apply-Tweak "Высший приоритет для Pro Audio" { Set-ItemProperty -Path $ProAudioPath -Name "Priority" -Value 4 -Type DWord -Force *>&1 | Out-File -FilePath $global:LogPath -Append -Encoding UTF8 } # Высший приоритет
Apply-Tweak "Высокая категория для Pro Audio" { Set-ItemProperty -Path $ProAudioPath -Name "Scheduling Category" -Value "High" -Type String -Force *>&1 | Out-File -FilePath $global:LogPath -Append -Encoding UTF8 } # Высокая категория
Apply-Tweak "Резерв 3% для Pro Audio" { Set-ItemProperty -Path $ProAudioPath -Name "SystemResponsiveness" -Value 3 -Type DWord -Force *>&1 | Out-File -FilePath $global:LogPath -Append -Encoding UTF8 } # 5% резерва

# Настройка очереди реального времени (RTWorkQ)
$RTWorkQ = "HKLM:\SOFTWARE\Microsoft\Windows NT\CurrentVersion\RTWorkQ"
if (!(Test-Path $RTWorkQ)) { Apply-Tweak "Создание раздела RTWorkQ" { New-Item -Path $RTWorkQ -Force *>&1 | Out-File -FilePath $global:LogPath -Append -Encoding UTF8 } }
Apply-Tweak "Исключение RTWorkQ из энергосбережения" { Set-ItemProperty -Path $RTWorkQ -Name "Enable" -Value 1 -Type DWord -Force *>&1 | Out-File -FilePath $global:LogPath -Append -Encoding UTF8 } # Исключаем RTWorkQ из энергосбережения
Apply-Tweak "Максимальный приоритет таймера RTWorkQ" { Set-ItemProperty -Path $RTWorkQ -Name "TimerResolution" -Value 1 -Type DWord -Force *>&1 | Out-File -FilePath $global:LogPath -Append -Encoding UTF8 } # Заставляем работать на максимальном приоритете таймера

# Оптимизация отрисовки рабочего стола при нагрузке
$WM_Task = "HKLM:\SOFTWARE\Microsoft\Windows NT\CurrentVersion\Multimedia\SystemProfile\Tasks\Window Manager"
if (!(Test-Path $WM_Task)) { Apply-Tweak "Создание профиля Window Manager" { New-Item -Path $WM_Task -Force *>&1 | Out-File -FilePath $global:LogPath -Append -Encoding UTF8 } }
Apply-Tweak "Высший приоритет Window Manager (Защита DWM от фризов)" { Set-ItemProperty -Path $WM_Task -Name "Priority" -Value 8 -Type DWord -Force *>&1 | Out-File -FilePath $global:LogPath -Append -Encoding UTF8 } # 8 = Высший приоритет (Чтобы окна не лагали во время игры)
Apply-Tweak "Высокая категория для Window Manager" { Set-ItemProperty -Path $WM_Task -Name "Scheduling Category" -Value "High" -Type String -Force *>&1 | Out-File -FilePath $global:LogPath -Append -Encoding UTF8 } # Категория High

# FSE Tweaks (Оптимизация полноэкранного режима)
$GameConfig = "HKCU:\System\GameConfigStore"
if (!(Test-Path $GameConfig)) { Apply-Tweak "Создание раздела GameConfigStore" { New-Item $GameConfig -Force *>&1 | Out-File -FilePath $global:LogPath -Append -Encoding UTF8 } }
Apply-Tweak "Отключение фоновой записи GameDVR (GameDVR_Enabled)" { Set-ItemProperty -Path $GameConfig -Name "GameDVR_Enabled" -Value 0 -Type DWord -Force *>&1 | Out-File -FilePath $global:LogPath -Append -Encoding UTF8 } # 0 = Отключаем фоновую запись GameDVR (убивает статтеры)
Apply-Tweak "Разрешение современной Flip-модели (FSEBehavior)" { Set-ItemProperty -Path $GameConfig -Name "GameDVR_FSEBehavior" -Value 2 -Type DWord -Force *>&1 | Out-File -FilePath $global:LogPath -Append -Encoding UTF8 } # 2 = Принудительно переводит старые игры из устаревшего режима Exclusive Fullscreen в современный DXGI Flip Model. Позволяет DWM выводить кадр на экран без копирования буфера (Zero-Copy), снижая инпут-лаг и ускоряя Alt+Tab.
Apply-Tweak "Форсирование DXGI Flip Model (FSEBehaviorMode)" { Set-ItemProperty -Path $GameConfig -Name "GameDVR_FSEBehaviorMode" -Value 2 -Type DWord -Force *>&1 | Out-File -FilePath $global:LogPath -Append -Encoding UTF8 } # 2 = Отключает старый композитинг DWM для полноэкранных окон.
Apply-Tweak "Поведение DSE" { Set-ItemProperty -Path $GameConfig -Name "GameDVR_DSEBehavior" -Value 2 -Type DWord -Force *>&1 | Out-File -FilePath $global:LogPath -Append -Encoding UTF8 } # 2 = Поведение DSE
Apply-Tweak "Использование пользовательских настроек FSE" { Set-ItemProperty -Path $GameConfig -Name "GameDVR_HonorUserFSEBehaviorMode" -Value 1 -Type DWord -Force *>&1 | Out-File -FilePath $global:LogPath -Append -Encoding UTF8 } # 1 = Использовать пользовательские настройки FSE
Apply-Tweak "Отключение навязанной совместимости FSE" { Set-ItemProperty -Path $GameConfig -Name "GameDVR_DXGIHonorFSEWindowsCompatible" -Value 1 -Type DWord -Force *>&1 | Out-File -FilePath $global:LogPath -Append -Encoding UTF8 } # 1 = Отключаем навязанную совместимость
Apply-Tweak "Отключение экспериментальных функций FSE" { Set-ItemProperty -Path $GameConfig -Name "GameDVR_EFSEFeatureFlags" -Value 0 -Type DWord -Force *>&1 | Out-File -FilePath $global:LogPath -Append -Encoding UTF8 } # 0 = Отключаем экспериментальные функции FSE
Apply-Tweak "Отключение тестовых функций графики" { Set-ItemProperty -Path $GameConfig -Name "FeatureTestControl" -Value 0 -Type DWord -Force *>&1 | Out-File -FilePath $global:LogPath -Append -Encoding UTF8 } # 0 = Отключаем тестовые функции

$GameDVR = "HKCU:\Software\Microsoft\Windows\CurrentVersion\GameDVR"
if (!(Test-Path $GameDVR)) { Apply-Tweak "Создание раздела GameDVR" { New-Item $GameDVR -Force *>&1 | Out-File -FilePath $global:LogPath -Append -Encoding UTF8 } }

# Отключение всех компонентов захвата GameDVR
$DVRKeys = @(
    "AppCaptureEnabled", "AudioCaptureEnabled", "CursorCaptureEnabled", "HistoricalCaptureEnabled",
    "MicrophoneCaptureEnabled", "VKMSaveHistoricalVideo", "VKMTakeScreenshot", "VKMToggleGameBar",
    "VKMToggleRecording", "VKMToggleRecordingIndicator", "VKToggleGameBar", "VKToggleMicrophoneCapture",
    "VKMToggleBroadcast", "VKMToggleCameraCapture"
)
foreach ($Key in $DVRKeys) {
    Apply-Tweak "Отключение функции захвата GameDVR ($Key)" { Set-ItemProperty -Path $GameDVR -Name $Key -Value 0 -Type DWord -Force *>&1 | Out-File -FilePath $global:LogPath -Append -Encoding UTF8 } # 0 = Отключаем горячие клавиши и запись
}

$GamePol = "HKLM:\SOFTWARE\Policies\Microsoft\Windows\GameDVR"
if (!(Test-Path $GamePol)) { Apply-Tweak "Создание раздела политик GameDVR" { New-Item -Path $GamePol -Force *>&1 | Out-File -FilePath $global:LogPath -Append -Encoding UTF8 } }
Apply-Tweak "Разрешение открытия оверлея Xbox Game Bar через Win + G для игр Xbox Live" { Set-ItemProperty -Path $GamePol -Name "AllowGameDVR" -Value 1 -Type DWord -Force *>&1 | Out-File -FilePath $global:LogPath -Append -Encoding UTF8 }

# Режим игры Windows (Game Mode)
$gameModePath = "HKCU:\Software\Microsoft\GameBar"
if (!(Test-Path $gameModePath)) { Apply-Tweak "Создание раздела GameBar" { New-Item -Path $gameModePath -Force *>&1 | Out-File -FilePath $global:LogPath -Append -Encoding UTF8 } }
Apply-Tweak "Разрешение автоматического игрового режима" { Set-ItemProperty -Path $gameModePath -Name "AllowAutoGameMode" -Value 1 -Type DWord -Force *>&1 | Out-File -FilePath $global:LogPath -Append -Encoding UTF8 }
Apply-Tweak "Включение игрового режима (AutoGameModeEnabled)" { Set-ItemProperty -Path $gameModePath -Name "AutoGameModeEnabled" -Value 1 -Type DWord -Force *>&1 | Out-File -FilePath $global:LogPath -Append -Encoding UTF8 }

# Уничтожение фоновых процессов GameBar
Apply-Tweak "Мгновенное уничтожение процессов GameBar и BcastDVR" { Get-Process -Name "GameBar*", "bcastdvr" -ErrorAction SilentlyContinue 2>> $env:SystemDrive\EastricaTools\Eastrica_ErrorTrace.log | Stop-Process -Force } # Мгновенно убиваем процессы Xbox

# Блокировка Presence Writer (Следит, в какую игру вы играете, и транслирует статус в Xbox Live). PresenceWriter сохраняется, если в системе обнаружен двухчиплетный X3D.
$GbKey = "HKLM:\SOFTWARE\Microsoft\WindowsRuntime\ActivatableClassId\Windows.Gaming.GameBar.PresenceServer.Internal.PresenceWriter"
$IsDualCcdX3D = ($global:ProcInfo.Name -match "7900X3D|7950X3D|9900X3D|9950X3D")
if ((Test-Path $GbKey) -and (-not $IsDualCcdX3D)) { 
    Grant-RegPermission -RegPath $GbKey
    try { Apply-Tweak "Запрет активации COM-объекта PresenceWriter" { Set-ItemProperty -LiteralPath $GbKey -Name "ActivationType" -Value 0 -Type DWord -Force -ErrorAction Stop *>&1 | Out-File -FilePath $global:LogPath -Append -Encoding UTF8 } } catch { }
    Restore-RegPermission -RegPath $GbKey
}

# Уничтожение скрытых системных служб записи экрана (BcastDVR и CaptureService)
$DvrServices = @("BcastDVRUserService", "CaptureService")
foreach ($Svc in $DvrServices) {
    $RegSvc = "HKLM:\SYSTEM\CurrentControlSet\Services\$Svc"
    if (Test-Path $RegSvc) { Apply-Tweak "Отключение службы записи экрана ($Svc)" { Set-ItemProperty -Path $RegSvc -Name "Start" -Value 4 -Type DWord -Force *>&1 | Out-File -FilePath $global:LogPath -Append -Encoding UTF8 } } # 4 = Отключаем службы через реестр (так как они защищены от Stop-Service)
}

# Отключение Focus Assist (Фокусировка внимания) - убирает оверлей "Полноэкранный режим включен"
$FocusAssist = "HKCU:\Software\Microsoft\Windows\CurrentVersion\Notifications\Settings"
if (!(Test-Path $FocusAssist)) { Apply-Tweak "Создание раздела настроек уведомлений" { New-Item -Path $FocusAssist -Force *>&1 | Out-File -FilePath $global:LogPath -Append -Encoding UTF8 } }
Apply-Tweak "Запрет уведомлений поверх блокировки (FocusAssist)" { Set-ItemProperty -Path $FocusAssist -Name "NOC_GLOBAL_SETTING_ALLOW_TOASTS_ABOVE_LOCK" -Value 0 -Type DWord -Force *>&1 | Out-File -FilePath $global:LogPath -Append -Encoding UTF8 } # Запрет уведомлений поверх блокировки
Apply-Tweak "Запрет критических уведомлений поверх блокировки" { Set-ItemProperty -Path $FocusAssist -Name "NOC_GLOBAL_SETTING_ALLOW_CRITICAL_TOASTS_ABOVE_LOCK" -Value 0 -Type DWord -Force *>&1 | Out-File -FilePath $global:LogPath -Append -Encoding UTF8 } # Запрет критических уведомлений
$FocusRules = "HKCU:\Software\Microsoft\Windows\CurrentVersion\Notifications\Settings\Microsoft.SkyDrive.Desktop"
if (Test-Path $FocusRules) { Apply-Tweak "Отключение уведомлений от OneDrive" { Set-ItemProperty -Path $FocusRules -Name "Enabled" -Value 0 -Type DWord -Force *>&1 | Out-File -FilePath $global:LogPath -Append -Encoding UTF8 } } # Отключаем уведомления от OneDrive

# Отключение Windows 11 Auto Color Management (устранение накладных расходов DWM)
$VideoSettingsUser = "HKCU:\Software\Microsoft\Windows\CurrentVersion\VideoSettings"
if (!(Test-Path $VideoSettingsUser)) { 
    Apply-Tweak "Создание раздела VideoSettings пользователя" { 
        New-Item -Path $VideoSettingsUser -Force *>&1 | Out-File -FilePath $global:LogPath -Append -Encoding UTF8 | Out-Null 
    } 
}

Apply-Tweak "Отключение Auto Color Management DWM (EnableACM = 0)" { 
    Set-ItemProperty -Path $VideoSettingsUser -Name "EnableACM" -Value 0 -Type DWord -Force *>&1 | Out-File -FilePath $global:LogPath -Append -Encoding UTF8 
}

# Отключение глобальной конвертации цветовых профилей дисплеев
$DisplayACMPath = "HKLM:\SOFTWARE\Microsoft\Windows NT\CurrentVersion\ICM"
if (!(Test-Path $DisplayACMPath)) { 
    Apply-Tweak "Создание раздела ICM" { 
        New-Item -Path $DisplayACMPath -Force *>&1 | Out-File -FilePath $global:LogPath -Append -Encoding UTF8 | Out-Null 
    } 
}

Apply-Tweak "Отключение фоновой калибровки ICM (CalibrationLoaded = 0)" { 
    Set-ItemProperty -Path $DisplayACMPath -Name "CalibrationLoaded" -Value 0 -Type DWord -Force *>&1 | Out-File -FilePath $global:LogPath -Append -Encoding UTF8 
}

Write-Host ""
# ==============================================================================
# Раздел 15: Планировщик WDDM, HAGS и TDR (графика)
# ==============================================================================
Show-ProgressStep -StepNum 15 -TotalSteps 81 -Activity "Настройка HAGS, планировщика WDDM и TDR..."
Write-Host "==============================================================================" -ForegroundColor DarkGray
Write-Host "РАЗДЕЛ 15: ПЛАНИРОВЩИК WDDM, HAGS И TDR (ГРАФИКА)" -ForegroundColor Cyan
Write-Host "==============================================================================" -ForegroundColor DarkGray

$GraphicsPath = "HKLM:\SYSTEM\CurrentControlSet\Control\GraphicsDrivers"
if (!(Test-Path $GraphicsPath)) { Apply-Tweak "Создание корневого раздела GraphicsDrivers" { New-Item -Path $GraphicsPath -Force *>&1 | Out-File -FilePath $global:LogPath -Append -Encoding UTF8 } }

# Интеллектуальная логика HAGS (Hardware-Accelerated GPU Scheduling)
$FinalHagsValue = $null # Инициализируем переменную для HAGS
$VideoControllers = $global:GPUs # Берем список видеокарт
$HasNextGenGpu = $false # Флаг наличия современных видеокарт
$ForceDisableHags = $false # Флаг принудительного отключения

if ($VideoControllers) {
    foreach ($gpu in $VideoControllers) {
        $Name = $gpu.Name
        # Ищем видеокарты с аппаратной поддержкой Frame Generation
        if ($Name -match "RTX [3-9]\d{3}" -or $Name -match "RX [6-9]\d{3}" -or $Name -match "RX [1-9]\d{4}") {
            $HasNextGenGpu = $true # Найдена современная видеокарта
            break
        }
    }
}

if ($ForceDisableHags) {
    $FinalHagsValue = 1 # Отключаем, если стоит флаг
    Write-Host " ► HAGS принудительно отключен (ForceDisableHags)" -ForegroundColor Yellow
} elseif ($HasNextGenGpu -or $global:RefreshRate -gt 75) {
    $FinalHagsValue = 2 # 2 = Включено с приоритетом GPU (Только для современных видеокарт или мониторов >75Hz)
    Write-Host " ► HAGS включен (Режим 2, GPU Priority.)" -ForegroundColor DarkGray
} else {
    $FinalHagsValue = 1 # 1 = Отключено (Возврат к программному планировщику CPU для старых карт)
    Write-Host " ► HAGS отключен (Legacy GPU или 60Hz)" -ForegroundColor DarkGray
}

$DxgKey = "HKLM:\SYSTEM\CurrentControlSet\Services\DXGKrnl\Parameters"
if (!(Test-Path $DxgKey)) { Apply-Tweak "Создание параметров DXGKrnl" { New-Item -Path $DxgKey -Force *>&1 | Out-File -FilePath $global:LogPath -Append -Encoding UTF8 } }
Apply-Tweak "Сброс прерываний GPU (GPUPreemption)" { Remove-ItemProperty -Path $DxgKey -Name "GPUPreemption" *>&1 | Out-File -FilePath $global:LogPath -Append -Encoding UTF8 }
Apply-Tweak "Отключение аппаратной передачи кадров дисплею (HardwareFlipQueueEnabled)" { Set-ItemProperty -Path $DxgKey -Name "HardwareFlipQueueEnabled" -Value 0 -Type DWord -Force *>&1 | Out-File -FilePath $global:LogPath -Append -Encoding UTF8 } # Включение вызывает непрерывное мерцание экрана, черные вспышки при просмотре YouTube и отвал интерфейса Windows 11 на видеокартах старых поколений.

# Применение HAGS в реестр
Apply-Tweak "Установка режима аппаратного планировщика (HAGS)" { 
    Set-ItemProperty -Path $GraphicsPath -Name "HwSchMode" -Value $FinalHagsValue -Type DWord -Force *>&1 | Out-File -FilePath $global:LogPath -Append -Encoding UTF8 
    # Старый алиас для ранних билдов Windows 10
    Set-ItemProperty -Path $GraphicsPath -Name "HwSchedMode" -Value $FinalHagsValue -Type DWord -Force *>&1 | Out-File -FilePath $global:LogPath -Append -Encoding UTF8 
}

if ($FinalHagsValue -ge 2) {
    Apply-Tweak "Высший приоритет аппаратному планировщику GPU" { Set-ItemProperty -Path $GraphicsPath -Name "HwSchPriority" -Value 1 -Type DWord -Force *>&1 | Out-File -FilePath $global:LogPath -Append -Encoding UTF8 }
    Apply-Tweak "Использование высокопроизводительного GPU (GpuPreference)" { Set-ItemProperty -Path $GraphicsPath -Name "GpuPreference" -Value 2 -Type DWord -Force *>&1 | Out-File -FilePath $global:LogPath -Append -Encoding UTF8 }
    Apply-Tweak "Разрешение аппаратной очереди HwFlipQueue" { Set-ItemProperty -Path $GraphicsPath -Name "DisableHwFlipQueue" -Value 0 -Type DWord -Force *>&1 | Out-File -FilePath $global:LogPath -Append -Encoding UTF8 }
    
    # Принудительная разблокировка HAGS для экспериментальных драйверов (из GPU_SCHEDULING)
    Apply-Tweak "Принудительное включение HAGS для всех совместимых GPU (HwSchTreatExperimentalAsStable)" {
        Set-ItemProperty -Path $GraphicsPath -Name "HwSchTreatExperimentalAsStable" -Value 1 -Type DWord -Force *>&1 | Out-File -FilePath $global:LogPath -Append -Encoding UTF8
    }
    
    # Полное снятие черного списка ядра для HAGS (AMD, Intel Arc, Ноутбуки)
    $UnblockHWSCH = "$($GraphicsPath)\BlockList\Kernel"
    if (Test-Path $UnblockHWSCH) {
        Apply-Tweak "Полное удаление черного списка HAGS (BlockList\Kernel)" {
            Remove-Item -Path $UnblockHWSCH -Recurse -Force *>&1 | Out-File -FilePath $global:LogPath -Append -Encoding UTF8
        }
    }
} else {
    Apply-Tweak "Сброс приоритета аппаратного планировщика" { Remove-ItemProperty -Path $GraphicsPath -Name "HwSchPriority" *>&1 | Out-File -FilePath $global:LogPath -Append -Encoding UTF8 }
    Apply-Tweak "Сброс предпочтений GPU" { Remove-ItemProperty -Path $GraphicsPath -Name "GpuPreference" *>&1 | Out-File -FilePath $global:LogPath -Append -Encoding UTF8 }
    Apply-Tweak "Отключение аппаратной очереди HwFlipQueue" { Set-ItemProperty -Path $GraphicsPath -Name "DisableHwFlipQueue" -Value 1 -Type DWord -Force *>&1 | Out-File -FilePath $global:LogPath -Append -Encoding UTF8 }
    Apply-Tweak "Отключение экспериментального HAGS" { Set-ItemProperty -Path $GraphicsPath -Name "HwSchTreatExperimentalAsStable" -Value 0 -Type DWord -Force *>&1 | Out-File -FilePath $global:LogPath -Append -Encoding UTF8 }
}

if ($global:OptAntiCheat) {
    Apply-Tweak "Включение проверки цифровых подписей драйверов (Режим Античита)" { Remove-ItemProperty -Path $GraphicsPath -Name "DisableSignatureCheck" *>&1 | Out-File -FilePath $global:LogPath -Append -Encoding UTF8 } # В режиме античита подпись драйверов ОБЯЗАТЕЛЬНА
} else {
    Apply-Tweak "Отключение проверки цифровой подписи видеодрайверов" { Set-ItemProperty -Path $GraphicsPath -Name "DisableSignatureCheck" -Value 1 -Type DWord -Force *>&1 | Out-File -FilePath $global:LogPath -Append -Encoding UTF8 } # 1 = Отключаем проверку подписи драйверов (для кастомных модов)
}

# TDR Delay (Защита от зависаний видеодрайвера)
Apply-Tweak "Включение безопасного восстановления драйвера при сбое (TdrLevel)" { Set-ItemProperty -Path $GraphicsPath -Name "TdrLevel" -Value 3 -Type DWord -Force *>&1 | Out-File -FilePath $global:LogPath -Append -Encoding UTF8 } # 3 = Включаем безопасное восстановление драйвера при сбое

# Увеличиваем время ожидания ответа GPU
$tdrVal = if ($global:OptAI) { 60 } else { 10 } # 60 сек для генерации ИИ, 10 сек для игр
Apply-Tweak "Установка таймаута GPU (TdrDelay = $tdrVal сек)" { Set-ItemProperty -Path $GraphicsPath -Name "TdrDelay" -Value $tdrVal -Type DWord -Force *>&1 | Out-File -FilePath $global:LogPath -Append -Encoding UTF8 } # Время в секундах до сброса GPU
Apply-Tweak "Установка таймаута DDI (TdrDdiDelay = $tdrVal сек)" { Set-ItemProperty -Path $GraphicsPath -Name "TdrDdiDelay" -Value $tdrVal -Type DWord -Force *>&1 | Out-File -FilePath $global:LogPath -Append -Encoding UTF8 } # Время в секундах для DDI интерфейса
Apply-Tweak "Разрешение до 10 сбросов видеодрайвера подряд (TdrLimitCount)" { Set-ItemProperty -Path $GraphicsPath -Name "TdrLimitCount" -Value 10 -Type DWord -Force *>&1 | Out-File -FilePath $global:LogPath -Append -Encoding UTF8 } # Разрешаем до 10 сбросов драйвера подряд
Apply-Tweak "Окно времени для подсчета сбросов драйвера (TdrLimitTime = 120 сек)" { Set-ItemProperty -Path $GraphicsPath -Name "TdrLimitTime" -Value 120 -Type DWord -Force *>&1 | Out-File -FilePath $global:LogPath -Append -Encoding UTF8 } # Окно времени (в сек) для подсчета сбросов
Apply-Tweak "Тихое восстановление WDDM без BSOD (TdrDebugMode)" { Set-ItemProperty -Path $GraphicsPath -Name "TdrDebugMode" -Value 2 -Type DWord -Force *>&1 | Out-File -FilePath $global:LogPath -Append -Encoding UTF8 } # 2 = Тихое восстановление WDDM без генерации синих экранов
Apply-Tweak "Ускорение переподключения монитора (TdrDodPresentDelay)" { Set-ItemProperty -Path $GraphicsPath -Name "TdrDodPresentDelay" -Value 2 -Type DWord -Force *>&1 | Out-File -FilePath $global:LogPath -Append -Encoding UTF8 } # Ускоряем переподключение монитора после сброса

# 0 = Запрещаем драйверу WDDM генерировать краш-дампы памяти при падении видеокарты.
# Это позволит игре закрыться мгновенно с ошибкой DirectX, а не вешать ПК на 15 секунд с черным экраном.
Apply-Tweak "Отключение тестового режима TDR" { Set-ItemProperty -Path $GraphicsPath -Name "TdrTestMode" -Value 0 -Type DWord -Force *>&1 | Out-File -FilePath $global:LogPath -Append -Encoding UTF8 }
Apply-Tweak "Запрет отчетов о дампах WDDM" { Set-ItemProperty -Path $GraphicsPath -Name "DbgDumpReportDisable" -Value 1 -Type DWord -Force *>&1 | Out-File -FilePath $global:LogPath -Append -Encoding UTF8 }
Apply-Tweak "Запрет генерации краш-дампов видеопамяти при сбоях (CrashDumpEnabled)" { Set-ItemProperty -Path $GraphicsPath -Name "CrashDumpEnabled" -Value 0 -Type DWord -Force *>&1 | Out-File -FilePath $global:LogPath -Append -Encoding UTF8 }

# Разблокировка HAGS для старых/заблокированных видеокарт AMD на уровне ядра
$UnblockHWSCH = "$($GraphicsPath)\BlockList\Kernel" # Путь к черному списку планировщика ядра
$AMDHWSCH = 'Vendor=1002#Device=*#Version=*#Model=*#' # Идентификатор всех видеокарт AMD
try {
    if (Test-Path $UnblockHWSCH) { # Если черный список существует
        if ($FinalHagsValue -gt 1) { # Если скрипт принял решение включить HAGS
            $value = Get-ItemProperty -Path $UnblockHWSCH -Name $AMDHWSCH 2>> $env:SystemDrive\EastricaTools\Eastrica_ErrorTrace.log # Проверяем, заблокирована ли карта AMD
            if ($value) { 
                Apply-Tweak "Удаление видеокарт AMD из черного списка HAGS" { Remove-ItemProperty -Path $UnblockHWSCH -Name $AMDHWSCH -Force *>&1 | Out-File -FilePath $global:LogPath -Append -Encoding UTF8 } # Удаляем AMD из черного списка
            }
        }
    }
} catch {
    Write-Warning "Ошибка при выполнении: $($_.Exception.Message)" # Выводим ошибку, если нет прав
}

# Оптимизация планировщика WDDM (Адаптация под герцовку)
$GpuScheduler = "HKLM:\SYSTEM\CurrentControlSet\Control\GraphicsDrivers\Scheduler"
if (!(Test-Path $GpuScheduler)) { Apply-Tweak "Создание раздела WDDM Scheduler" { New-Item $GpuScheduler -Force *>&1 | Out-File -FilePath $global:LogPath -Append -Encoding UTF8 } }

if ($global:RefreshRate -le 75) {
    # Для 60-75 Гц: Плавный VSync, приоритет активному окну
    $SchTweaks = @{
        "EnablePreemption"                = 1 # Обязательно 1 (Разрешает прерывания, спасает от фризов)
        "FlipOnVSyncWithNoWait"           = 0 # Ждать синхроимпульс (Плавная картинка без разрывов)
        "AdjustWorkerThreadPriority"      = 1 # Адаптивный приоритет потоков
        "ForegroundPriorityBoost"         = 1 # Буст активного окна (Игры)
    }
    foreach ($Tweak in $SchTweaks.GetEnumerator()) {
        Apply-Tweak "Оптимизация WDDM для 60-75Hz ($($Tweak.Name))" { Set-ItemProperty -Path $GpuScheduler -Name $Tweak.Name -Value $Tweak.Value -Type DWord -Force *>&1 | Out-File -FilePath $global:LogPath -Append -Encoding UTF8 }
    }
    # Удаляем агрессивные Flip-очереди для старых мониторов
    $BadTweaks = @("EnableFlipImmediateSwFlipQueue", "EnableFlipOnVSyncHwFlipQueue", "EnableFlipOnVSyncSwFlipQueue")
    foreach ($Tweak in $BadTweaks) { Apply-Tweak "Удаление агрессивного твика Flip: $Tweak" { Remove-ItemProperty -Path $GpuScheduler -Name $Tweak *>&1 | Out-File -FilePath $global:LogPath -Append -Encoding UTF8 } }
} else {
    # Для 120+ Гц: Современный Flip-модель с сохранением плавности
    $SchTweaks = @{
        "EnablePreemption"                = 1 # Обязательно 1! (0 вызывает мертвые зависания)
        "EnableFlipImmediateSwFlipQueue"  = 1 # Включаем немедленный программный Flip (Снижает инпут-лаг)
        "EnableFlipOnVSyncHwFlipQueue"    = 1 # Включаем аппаратный Flip по VSync
        "EnableFlipOnVSyncSwFlipQueue"    = 1 # Включаем программный Flip по VSync
        "FlipOnVSyncWithNoWait"           = 0 # 0 = Правильная синхронизация кадров без статтеров
        "AdjustWorkerThreadPriority"      = 1 # Включаем регулировку приоритета потоков
        "ForegroundPriorityBoost"         = 1 # 1 = Выдаем максимальный приоритет активной игре
    }
    foreach ($Tweak in $SchTweaks.GetEnumerator()) {
        Apply-Tweak "Оптимизация WDDM для 120Hz+ ($($Tweak.Name))" { Set-ItemProperty -Path $GpuScheduler -Name $Tweak.Name -Value $Tweak.Value -Type DWord -Force *>&1 | Out-File -FilePath $global:LogPath -Append -Encoding UTF8 }
    }
}

if ($global:RefreshRate -ge 120) {
    Apply-Tweak "Прямая запись кадра в железный буфер (HwFlipQueue)" { Set-ItemProperty -Path $GpuScheduler -Name "EnableFlipImmediateHwFlipQueue" -Value 1 -Type DWord -Force *>&1 | Out-File -FilePath $global:LogPath -Append -Encoding UTF8 }
    # Удаляем VBlankTimeout = 0 во избежание холостых циклов CPU (Spin-wait)
    Apply-Tweak "Удаление VBlankTimeout (Устранение холостых циклов CPU)" { Remove-ItemProperty -Path $GpuScheduler -Name "VBlankTimeout" *>&1 | Out-File -FilePath $global:LogPath -Append -Encoding UTF8 }
}

# Удаление опасного лимита прерываний GPU (Возврат системного таймаута WDDM)
Apply-Tweak "Удаление ручного PreemptionTimeout (Защита от сброса драйвера)" { Remove-ItemProperty -Path $GpuScheduler -Name "PreemptionTimeout" *>&1 | Out-File -FilePath $global:LogPath -Append -Encoding UTF8 }
# Удаляем ленивое переключение контекста во избежание рассинхронизации кадрового потока
Apply-Tweak "Удаление LazyContextSwitch (Устранение задержек смены контекста GPU)" { Remove-ItemProperty -Path $GpuScheduler -Name "LazyContextSwitch" *>&1 | Out-File -FilePath $global:LogPath -Append -Encoding UTF8 }

# Страховочный запрет на отключение прерываний и включение Mid-Buffer Preemption
Apply-Tweak "Аппаратное вытеснение буфера команд (MidBuffer Preemption)" {
    Set-ItemProperty -Path $GpuScheduler -Name "DisablePreemption" -Value 0 -Type DWord -Force *>&1 | Out-File -FilePath $global:LogPath -Append -Encoding UTF8
    Set-ItemProperty -Path $GpuScheduler -Name "EnableMidBufferPreemption" -Value 1 -Type DWord -Force *>&1 | Out-File -FilePath $global:LogPath -Append -Encoding UTF8
}

# [WDDM 3.0] GPU Upload Heaps (Прямая запись CPU-to-VRAM)
$GpuMemManager = "HKLM:\SYSTEM\CurrentControlSet\Control\GraphicsDrivers\MemoryManager"
if (!(Test-Path $GpuMemManager)) { Apply-Tweak "Создание раздела MemoryManager для WDDM" { New-Item $GpuMemManager -Force *>&1 | Out-File -FilePath $global:LogPath -Append -Encoding UTF8 } }
Apply-Tweak "Активация аппаратных куч Upload Heap (ReBAR)" { Set-ItemProperty -Path $GpuMemManager -Name "EnableUploadHeap" -Value 1 -Type DWord -Force *>&1 | Out-File -FilePath $global:LogPath -Append -Encoding UTF8 } # 1 = Активируем функцию аппаратных куч (Требуется Resizable BAR)
Apply-Tweak "Безлимитный размер Upload Heap" { Set-ItemProperty -Path $GpuMemManager -Name "UploadHeapSize" -Value 0 -Type DWord -Force *>&1 | Out-File -FilePath $global:LogPath -Append -Encoding UTF8 } # 0 = Динамический размер без искусственных ограничений

# Блокировка микро-сна для видеопамяти и дисплеев (D3 Transitions)
$GpuPower = "HKLM:\SYSTEM\CurrentControlSet\Control\GraphicsDrivers\Power"
if (!(Test-Path $GpuPower)) { Apply-Tweak "Создание раздела Power для WDDM" { New-Item $GpuPower -Force *>&1 | Out-File -FilePath $global:LogPath -Append -Encoding UTF8 } }

$PowerTweaks = @(
    "DefaultActiveIdleThreshold", "DefaultD3TransitionIdleLongTimeThreshold",
    "DefaultD3TransitionIdleShortTimeThreshold", "DefaultD3TransitionIdleVeryLongTimeThreshold",
    "DefaultD3TransitionLatencyActivelyUsed", "DefaultD3TransitionLatencyIdleLongTime",
    "DefaultD3TransitionLatencyIdleMonitorOff", "DefaultD3TransitionLatencyIdleNoContext",
    "DefaultD3TransitionLatencyIdleShortTime", "DefaultD3TransitionLatencyIdleVeryLongTime",
    "DefaultExpectedResidency", "DefaultLatencyToleranceIdle0", "DefaultLatencyToleranceMemory",
    "DefaultMemoryRefreshLatencyToleranceActivelyUsed", "MonitorLatencyTolerance", "MonitorRefreshLatencyTolerance"
)
foreach ($Tweak in $PowerTweaks) {
    Apply-Tweak "Запрет сна видеопамяти и дисплеев ($Tweak)" { Set-ItemProperty -Path $GpuPower -Name $Tweak -Value 1 -Type DWord -Force *>&1 | Out-File -FilePath $global:LogPath -Append -Encoding UTF8 } # Ставим задержку 1 мс, чтобы драйвер не смел усыплять железо
}
Apply-Tweak "Запрет режима самообновления VRAM (S3)" { Set-ItemProperty -Path $GpuPower -Name "UseSelfRefreshVRAMInS3" -Value 0 -Type DWord -Force *>&1 | Out-File -FilePath $global:LogPath -Append -Encoding UTF8 } # 0 = Запрет перевода VRAM в режим самообновления

Write-Host ""
# ==============================================================================
# Раздел 16: Оптимизация памяти GPU, IOMMU и буферов DirectX
# ==============================================================================
Show-ProgressStep -StepNum 16 -TotalSteps 81 -Activity "Оптимизация памяти GPU, IOMMU и буферов DirectX..."
Write-Host "==============================================================================" -ForegroundColor DarkGray
Write-Host "РАЗДЕЛ 16: ОПТИМИЗАЦИЯ ПАМЯТИ GPU, IOMMU И БУФЕРОВ DIRECTX" -ForegroundColor Cyan
Write-Host "==============================================================================" -ForegroundColor DarkGray

# Отключение фоновой диагностики WDDM и оптимизация IOMMU
$GpuMem = "HKLM:\SYSTEM\CurrentControlSet\Control\GraphicsDrivers\MemoryManager"
if (!(Test-Path $GpuMem)) { Apply-Tweak "Создание раздела MemoryManager" { New-Item $GpuMem -Force *>&1 | Out-File -FilePath $global:LogPath -Append -Encoding UTF8 } } # Создаем раздел управления памятью GPU

Apply-Tweak "Снижение издержек IOMMU на трансляцию адресов" { Set-ItemProperty -Path $GpuMem -Name "DisableMakeIoMmuAddressValid" -Value 1 -Type DWord -Force *>&1 | Out-File -FilePath $global:LogPath -Append -Encoding UTF8 } # 1 = Снижает накладные расходы процессора на аппаратную трансляцию адресов IOMMU
Apply-Tweak "Смена агрессивности освобождения VRAM (Фоновый режим)" { Set-ItemProperty -Path $GpuMem -Name "DxgMms2OfferReclaim" -Value 2 -Type DWord -Force *>&1 | Out-File -FilePath $global:LogPath -Append -Encoding UTF8 } # 2 = Background (Меняем агрессивность освобождения видеопамяти, чтобы не было фризов)
Apply-Tweak "Повышение порога паники VRAM до 90%" { Set-ItemProperty -Path $GpuMem -Name "VramEvictThreshold" -Value 90 -Type DWord -Force *>&1 | Out-File -FilePath $global:LogPath -Append -Encoding UTF8 } # 90 = Поднимаем порог паники драйвера (ОС начнет выгружать текстуры из VRAM в RAM только при 90% заполнения, а не при 80%)
Apply-Tweak "Запрет выгрузки таблиц IOMMU и MDL" { Set-ItemProperty -Path $GpuMem -Name "DisableMdlAndIoMmuEvict" -Value 1 -Type DWord -Force *>&1 | Out-File -FilePath $global:LogPath -Append -Encoding UTF8 } # 1 = Запрещаем WDDM выгружать таблицы трансляции (IoMmu) и списки дескрипторов (MDL)

# Абсолютный глобальный Low Latency для DX12/Vulkan на уровне ядра ОС
$maxFrames = if ($global:RefreshRate -le 75) { 2 } else { 1 } # Оптимальные значения: 1 для 120Hz+ (GPU всегда занят), 2 для 60Hz.
Apply-Tweak "Глобальное снижение задержки очереди кадров (MaxQueuedFrames = $maxFrames)" { Set-ItemProperty -Path $DxgKey -Name "MaxQueuedFrames" -Value $maxFrames -Type DWord -Force *>&1 | Out-File -FilePath $global:LogPath -Append -Encoding UTF8 } # Ограничиваем очередь подготовленных кадров на уровне ядра графики

Apply-Tweak "Отвязка основного потока графики от Core 0" { Remove-ItemProperty -Path $DxgKey -Name "ThreadAffinity" *>&1 | Out-File -FilePath $global:LogPath -Append -Encoding UTF8 } # Удаляем привязку к Core 0, даем ОС самостоятельно распределить основной поток рендеринга
Apply-Tweak "Увеличение буфера DMA до 16 МБ для PCIe 4.0/5.0" { Set-ItemProperty -Path $DxgKey -Name "DmaBufferSizeBytes" -Value 16777216 -Type DWord -Force *>&1 | Out-File -FilePath $global:LogPath -Append -Encoding UTF8 } # 16777216 = Увеличиваем лимит буферов прямого доступа (DMA) до 16 МБ для современных шин PCIe 4.0/5.0

# Исправление утечки невыгружаемого пула (Non-Paged Pool) и вылетов игр из-за «нехватки памяти» через 2–3 часа непрерывной игры
Apply-Tweak "Удаление лимита токенов GPU" { Remove-ItemProperty -Path $DxgKey -Name "MaxTokenLimit" *>&1 | Out-File -FilePath $global:LogPath -Append -Encoding UTF8 } # Удаляем лимит токенов GPU
Apply-Tweak "Удаление списка аллокаций графики" { Remove-ItemProperty -Path $DxgKey -Name "MaxAllocationList" *>&1 | Out-File -FilePath $global:LogPath -Append -Encoding UTF8 } # Удаление списка аллокаций
Apply-Tweak "Удаление списка патчей графики" { Remove-ItemProperty -Path $DxgKey -Name "MaxPatchLocationList" *>&1 | Out-File -FilePath $global:LogPath -Append -Encoding UTF8 } # Удаление списка патчей

Apply-Tweak "Отключение артефактов при смене разрешения в Fullscreen" { Set-ItemProperty -Path $GraphicsPath -Name "DisableWindowTransitionsOnResolving" -Value 1 -Type DWord -Force *>&1 | Out-File -FilePath $global:LogPath -Append -Encoding UTF8 } # 1 = Отключает визуальные артефакты (переходы) при смене разрешения в эксклюзивном полном экране

# Очистка системного реестра от фиктивных ключей DirectX.
# Флаги вроде D3D12_FORCE_REBAR и D3D11_MULTITHREADED являются внутренними переменными SDK для сборки игр,
# и релизные библиотеки DirectX (d3d11.dll / d3d12.dll) никогда не считывают их из реестра Windows.
$DirectXPath = "HKLM:\SOFTWARE\Microsoft\DirectX"
if (Test-Path $DirectXPath) {
    $DummyDxKeys = @(
        "D3D12_ENABLE_RUNTIME_DRIVER_OPTIMIZATIONS", "D3D12_RESOURCE_ALIGNMENT",
        "D3D11_MULTITHREADED", "D3D12_MULTITHREADED", "D3D11_DEFERRED_CONTEXTS",
        "D3D12_DEFERRED_CONTEXTS", "D3D11_ALLOW_TILING", "D3D11_ENABLE_DYNAMIC_CODEGEN",
        "D3D12_ALLOW_TILING", "D3D12_CPU_PAGE_TABLE_ENABLED", "D3D12_HEAP_SERIALIZATION_ENABLED",
        "D3D12_MAP_HEAP_ALLOCATIONS", "D3D12_RESIDENCY_MANAGEMENT_ENABLED",
        "D3D12_FORCE_REBAR", "D3D12_FORCE_INLINE_DESCRIPTOR_OPTIMIZATIONS",
        "D3D12_ALLOW_DYNAMIC_SHADING_RATE"
    )
    foreach ($DummyKey in $DummyDxKeys) {
        Apply-Tweak "Очистка невалидного ключа DirectX: $DummyKey" { 
            Remove-ItemProperty -Path $DirectXPath -Name $DummyKey -Force -ErrorAction SilentlyContinue *>&1 | Out-File -FilePath $global:LogPath -Append -Encoding UTF8 
        }
    }
}

# Форсирование аппаратного Flip-моделирования (Отключение старого композитинга)
Apply-Tweak "Форсирование прямого вывода кадра (ForceDirectFlip)" { Set-ItemProperty -Path $GraphicsPath -Name "ForceDirectFlip" -Value 1 -Type DWord -Force *>&1 | Out-File -FilePath $global:LogPath -Append -Encoding UTF8 } # 1 = Форсируем прямой вывод кадра (DirectFlip)
Apply-Tweak "Включение MPO для декодирования видео" { Set-ItemProperty -Path $GraphicsPath -Name "EnableDecodeMPO" -Value 1 -Type DWord -Force *>&1 | Out-File -FilePath $global:LogPath -Append -Encoding UTF8 } # 1 = Включаем MPO для декодирования видео
Apply-Tweak "Включение 3D DDI MPO" { Set-ItemProperty -Path $GraphicsPath -Name "EnableMultiPlaneOverlay3DDIs" -Value 1 -Type DWord -Force *>&1 | Out-File -FilePath $global:LogPath -Append -Encoding UTF8 } # 1 = Включаем 3D DDI MPO
Apply-Tweak "Поддержка MPO на вторичных дисплеях" { Set-ItemProperty -Path $GraphicsPath -Name "ForceSecondaryMPOsupport" -Value 1 -Type DWord -Force *>&1 | Out-File -FilePath $global:LogPath -Append -Encoding UTF8 } # 1 = Включаем поддержку MPO на вторичных дисплеях
Apply-Tweak "Поддержка Flip на вторичных дисплеях" { Set-ItemProperty -Path $GraphicsPath -Name "ForceSecondaryFlipSupport" -Value 1 -Type DWord -Force *>&1 | Out-File -FilePath $global:LogPath -Append -Encoding UTF8 } # 1 = Включаем поддержку Flip на вторичных дисплеях

Write-Host ""
# ==============================================================================
# Раздел 17: Активация MSI (Message Signaled Interrupts) и приоритеты шины
# ==============================================================================
Show-ProgressStep -StepNum 17 -TotalSteps 81 -Activity "Активация MSI Mode (GPU, USB xHCI, NVMe)..."
Write-Host "==============================================================================" -ForegroundColor DarkGray
Write-Host "РАЗДЕЛ 17: АКТИВАЦИЯ MSI (MESSAGE SIGNALED INTERRUPTS) И ПРИОРИТЕТЫ ШИНЫ" -ForegroundColor Cyan
Write-Host "==============================================================================" -ForegroundColor DarkGray

# Диагностика разделяемых линий прерываний (Shared IRQ Conflict Scanner)
try {
    Write-Host " ► Сканирование шины на наличие конфликтов аппаратных прерываний..." -ForegroundColor DarkGray
    $GpuDevices = $global:GPUs | Where-Object { $_.Name -match "NVIDIA|AMD|Radeon" }
    foreach ($Gpu in $GpuDevices) {
        if ($Gpu.PNPDeviceID) {
            $MsiKey = "HKLM:\SYSTEM\CurrentControlSet\Enum\$($Gpu.PNPDeviceID)\Device Parameters\Interrupt Management\MessageSignaledInterruptProperties"
            $MsiVal = (Get-ItemProperty -Path $MsiKey -Name "MSISupported" -ErrorAction SilentlyContinue).MSISupported
            if ($MsiVal -ne 1) {
                Write-Host "[WARNING] Видеокарта $($Gpu.Name) работает в устаревшем режиме Line-based IRQ!" -ForegroundColor Yellow
                Write-Host "          Возможны задержки кадров при одновременной нагрузке на шину PCIe." -ForegroundColor DarkGray
            }
        }
    }
} catch {}

# Сверхбыстрый точечный поиск и сброс масок прерываний через прямое дерево .NET
$EnumBase = [Microsoft.Win32.Registry]::LocalMachine.OpenSubKey("SYSTEM\CurrentControlSet\Enum")
if ($EnumBase) {
    foreach ($EnumeratorName in $EnumBase.GetSubKeyNames()) {
        $EnumeratorKey = $EnumBase.OpenSubKey($EnumeratorName)
        if ($EnumeratorKey) {
            foreach ($DeviceName in $EnumeratorKey.GetSubKeyNames()) {
                $DeviceKey = $EnumeratorKey.OpenSubKey($DeviceName)
                if ($DeviceKey) {
                    foreach ($InstanceName in $DeviceKey.GetSubKeyNames()) {
                        $AffinitySubPath = "$EnumeratorName\$DeviceName\$InstanceName\Device Parameters\Interrupt Management\Affinity Policy"
                        $TargetKey = $EnumBase.OpenSubKey($AffinitySubPath, $false)
                        if ($TargetKey) {
                            $FullAffinityPSPath = "HKLM:\SYSTEM\CurrentControlSet\Enum\$AffinitySubPath"
                            Apply-Tweak "Удаление старой маски прерываний ($FullAffinityPSPath)" { Remove-ItemProperty -LiteralPath $FullAffinityPSPath -Name "AssignmentSetOverride" *>&1 | Out-File -FilePath $global:LogPath -Append -Encoding UTF8 }
                            Apply-Tweak "Удаление старой политики устройства ($FullAffinityPSPath)" { Remove-ItemProperty -LiteralPath $FullAffinityPSPath -Name "DevicePolicy" *>&1 | Out-File -FilePath $global:LogPath -Append -Encoding UTF8 }
                            $TargetKey.Close()
                        }
                    }
                    $DeviceKey.Close()
                }
            }
            $EnumeratorKey.Close()
        }
    }
    $EnumBase.Close()
}

# Принудительный Low приоритет для Wi-Fi (чтобы пинг не вешал мышку)
$WiFiAdapters = Get-CimInstance Win32_PnPEntity | Where-Object { $_.PNPDeviceID -match "^PCI" -and ($_.Name -match "Wi-Fi" -or $_.Name -match "Wireless" -or $_.Name -match "802\.11") }
if ($WiFiAdapters) {
    foreach ($WiFi in $WiFiAdapters) {
        $PnpID = $WiFi.PnPDeviceID
        $RegBase = "HKLM:\SYSTEM\CurrentControlSet\Enum\$PnpID\Device Parameters\Interrupt Management"
        $MsiKey  = "$RegBase\MessageSignaledInterruptProperties"
        $AffinityKey = "$RegBase\Affinity Policy"
        
        if (!(Test-Path $MsiKey)) { Apply-Tweak "Создание ключа MSI для Wi-Fi" { New-Item -Path $MsiKey -Force *>&1 | Out-File -FilePath $global:LogPath -Append -Encoding UTF8 } }
        if (!(Test-Path $AffinityKey)) { Apply-Tweak "Создание ключа Affinity для Wi-Fi" { New-Item -Path $AffinityKey -Force *>&1 | Out-File -FilePath $global:LogPath -Append -Encoding UTF8 } }
        
        Apply-Tweak "Включение MSI Mode для Wi-Fi" { Set-ItemProperty -Path $MsiKey -Name "MSISupported" -Value 1 -Type DWord -Force *>&1 | Out-File -FilePath $global:LogPath -Append -Encoding UTF8 } # Включаем режим MSI
        Apply-Tweak "Низкий приоритет прерываний для Wi-Fi" { Set-ItemProperty -Path $AffinityKey -Name "DevicePriority" -Value 1 -Type DWord -Force *>&1 | Out-File -FilePath $global:LogPath -Append -Encoding UTF8 } # 1 = Low Priority (Сетевая карта не может перебить видеокарту)
    }
}

# Активация MSI для видеокарт (GPU)
$VideoControllers = $global:GPUs
if ($VideoControllers) {
    foreach ($vc in $VideoControllers) {
        $Name = $vc.Name
        # Исключаем базовые драйверы и оставляем только реальные видеокарты
        if (($Name -match "NVIDIA" -or $Name -match "AMD" -or $Name -match "Radeon" -or $Name -match "Intel") -and ($Name -notmatch "Basic") -and ($Name -notmatch "Microsoft")) {
            Enable-MSI-Safe -PnpID $vc.PNPDeviceID -DeviceName $Name -Type "GPU" # Вызываем нашу функцию
        }
    }
}

# Активация MSI для NVMe накопителей
$SCSIControllers = Get-CimInstance Win32_SCSIController 2>> $env:SystemDrive\EastricaTools\Eastrica_ErrorTrace.log
if ($SCSIControllers) {
    foreach ($scsi in $SCSIControllers) {
        $Name = $scsi.Name
        if ($Name -match "NVMe" -or $Name -match "NVM Express") {
            Enable-MSI-Safe -PnpID $scsi.PNPDeviceID -DeviceName $Name -Type "Storage" # Вызываем функцию (SATA игнорируется ради безопасности)
        }
    }
}

# Активация MSI для USB xHCI контроллеров
$USBControllers = Get-CimInstance Win32_USBController 2>> $env:SystemDrive\EastricaTools\Eastrica_ErrorTrace.log | Where-Object { $_.Name -match "xHCI|3\.0|3\.1" }
if ($USBControllers) {
    foreach ($usb in $USBControllers) {
        if ($usb.PNPDeviceID) {
            Enable-MSI-Safe -PnpID $usb.PNPDeviceID -DeviceName $usb.Name -Type "USB"
        }
    }
}

# Жесткая изоляция прерываний звука (Zero Audio Latency)
$AudioControllers = Get-CimInstance Win32_PnPEntity -Filter "PNPClass='Media'" 2>> $env:SystemDrive\EastricaTools\Eastrica_ErrorTrace.log
if ($AudioControllers) {
    foreach ($audio in $AudioControllers) {
        $PnpID = $audio.PNPDeviceID
        # Класс PNPClass='Media' на шине PCI уже гарантирует аппаратный мультимедиа/аудио контроллер без привязки к языку
        if ($PnpID -match "^PCI") {
            
            $RegBase = "HKLM:\SYSTEM\CurrentControlSet\Enum\$PnpID\Device Parameters\Interrupt Management"
            $MsiKey  = "$RegBase\MessageSignaledInterruptProperties"
            $AffinityKey = "$RegBase\Affinity Policy"
            
            if (!(Test-Path $MsiKey)) { Apply-Tweak "Создание ключа MSI для звуковой карты" { New-Item -Path $MsiKey -Force *>&1 | Out-File -FilePath $global:LogPath -Append -Encoding UTF8 } }
            if (!(Test-Path $AffinityKey)) { Apply-Tweak "Создание ключа Affinity для звуковой карты" { New-Item -Path $AffinityKey -Force *>&1 | Out-File -FilePath $global:LogPath -Append -Encoding UTF8 } }
            
            Apply-Tweak "Включение MSI Mode для звука" { Set-ItemProperty -Path $MsiKey -Name "MSISupported" -Value 1 -Type DWord -Force *>&1 | Out-File -FilePath $global:LogPath -Append -Encoding UTF8 } # Включаем MSI
            Apply-Tweak "Высокий приоритет прерываний для звука" { Set-ItemProperty -Path $AffinityKey -Name "DevicePriority" -Value 3 -Type DWord -Force *>&1 | Out-File -FilePath $global:LogPath -Append -Encoding UTF8 } # 3 = High Priority (Звук обрабатывается мгновенно, не "хрустит")
            Apply-Tweak "Размазывание очередей аудио по ядрам (Zero Audio Latency)" { Set-ItemProperty -Path $AffinityKey -Name "DevicePolicy" -Value 5 -Type DWord -Force *>&1 | Out-File -FilePath $global:LogPath -Append -Encoding UTF8 } # 5 = Размазать по всем ядрам (Для слабых ПК)
            Apply-Tweak "Удаление старой привязки звука" { Remove-ItemProperty -Path $AffinityKey -Name "AssignmentSetOverride" *>&1 | Out-File -FilePath $global:LogPath -Append -Encoding UTF8 }
        }
    }
}

# Включение MSI для системного хост-контроллера High Definition Audio (HDAudBus)
$HdAudBusControllers = Get-CimInstance Win32_PnPEntity | Where-Object { $_.Service -eq 'HDAudBus' }
if ($HdAudBusControllers) {
    foreach ($Controller in $HdAudBusControllers) {
        $PnpID = $Controller.PNPDeviceID
        $RegBase = "HKLM:\SYSTEM\CurrentControlSet\Enum\$PnpID\Device Parameters\Interrupt Management"
        if (!(Test-Path "$RegBase\MessageSignaledInterruptProperties")) { Apply-Tweak "Создание ключа MSI для HDAudBus" { New-Item -Path "$RegBase\MessageSignaledInterruptProperties" -Force *>&1 | Out-File -FilePath $global:LogPath -Append -Encoding UTF8 } }
        if (!(Test-Path "$RegBase\Affinity Policy")) { Apply-Tweak "Создание ключа Affinity для HDAudBus" { New-Item -Path "$RegBase\Affinity Policy" -Force *>&1 | Out-File -FilePath $global:LogPath -Append -Encoding UTF8 } }
        
        Apply-Tweak "Включение MSI Mode для системной аудиошины" { Set-ItemProperty -Path "$RegBase\MessageSignaledInterruptProperties" -Name "MSISupported" -Value 1 -Type DWord -Force *>&1 | Out-File -FilePath $global:LogPath -Append -Encoding UTF8 } # Включаем MSI
        Apply-Tweak "Высокий приоритет системной аудиошины" { Set-ItemProperty -Path "$RegBase\Affinity Policy" -Name "DevicePriority" -Value 3 -Type DWord -Force *>&1 | Out-File -FilePath $global:LogPath -Append -Encoding UTF8 } # 3 = High
    }
}

# Приоритет потоков видеокарты в Ядре
$NvKey = "HKLM:\SYSTEM\CurrentControlSet\Services\nvlddmkm\Parameters"
if ($global:RefreshRate -le 75) {
    # Для 60-75 Гц и ноутбуков возвращаем стандартный приоритет, чтобы не душить DWM и Intel GPU.
    Apply-Tweak "Сброс приоритета графического ядра DXG" { Remove-ItemProperty -Path $DxgKey -Name "ThreadPriority" *>&1 | Out-File -FilePath $global:LogPath -Append -Encoding UTF8 }
    if (Test-Path $NvKey) { Apply-Tweak "Сброс приоритета ядра NVIDIA" { Remove-ItemProperty -Path $NvKey -Name "ThreadPriority" *>&1 | Out-File -FilePath $global:LogPath -Append -Encoding UTF8 } }
} else {
    # Для 120+ Гц ставим приоритет 2 (High). Значение 15 (Time Critical) вешает ПК при сбоях драйвера!
    Apply-Tweak "Высокий приоритет графического ядра DXG" { Set-ItemProperty -Path $DxgKey -Name "ThreadPriority" -Value 2 -Type DWord -Force *>&1 | Out-File -FilePath $global:LogPath -Append -Encoding UTF8 }
    if (Test-Path $NvKey) { Apply-Tweak "Высокий приоритет ядра NVIDIA" { Set-ItemProperty -Path $NvKey -Name "ThreadPriority" -Value 2 -Type DWord -Force *>&1 | Out-File -FilePath $global:LogPath -Append -Encoding UTF8 } }
}

# Оптимизация контроллера шины PCI
$PciParams = "HKLM:\SYSTEM\CurrentControlSet\Control\PnP\Pci"
if (!(Test-Path $PciParams)) { Apply-Tweak "Создание раздела Pci" { New-Item $PciParams -Force *>&1 | Out-File -FilePath $global:LogPath -Append -Encoding UTF8 } }
Apply-Tweak "Увеличение лимита прерываний PCI до 2048" { Set-ItemProperty -Path $PciParams -Name "InterruptMessageLimit" -Value 2048 -Type DWord -Force *>&1 | Out-File -FilePath $global:LogPath -Append -Encoding UTF8 } # Увеличиваем лимит прерываний
Apply-Tweak "Отключение задержек толерантности шины (DisableLtr)" { Set-ItemProperty -Path $PciParams -Name "DisableLtr" -Value 1 -Type DWord -Force *>&1 | Out-File -FilePath $global:LogPath -Append -Encoding UTF8 } # 1 = Отключаем задержки толерантности шины
Apply-Tweak "Разрешение нативного управления PCI Express" { Set-ItemProperty -Path $PciParams -Name "PciExpressNativeControl" -Value 1 -Type DWord -Force *>&1 | Out-File -FilePath $global:LogPath -Append -Encoding UTF8 } # 1 = Разрешаем ОС нативно управлять PCI Express

# Глобальный аппаратный запрет ASPM (Сон PCIe) на уровне драйвера pci.sys
$PciSys = "HKLM:\SYSTEM\CurrentControlSet\Services\pci\Parameters"
if (!(Test-Path $PciSys)) { Apply-Tweak "Создание раздела параметров pci.sys" { New-Item -Path $PciSys -Force *>&1 | Out-File -FilePath $global:LogPath -Append -Encoding UTF8 } }
if ($global:OptHwSleep) {
    Apply-Tweak "Аппаратный запрет сна шины PCIe (DisableASPM)" { Set-ItemProperty -Path $PciSys -Name "DisableASPM" -Value 1 -Type DWord -Force *>&1 | Out-File -FilePath $global:LogPath -Append -Encoding UTF8 } # 1 = Полный запрет сна шины
    Apply-Tweak "Отключение состояния сна D3 для PCIe" { Set-ItemProperty -Path $PciSys -Name "DefaultD3State" -Value 0 -Type DWord -Force *>&1 | Out-File -FilePath $global:LogPath -Append -Encoding UTF8 } # 0 = Отключение состояния D3
    Write-Host "[WARNING] ASPM PCIe принудительно отключен" -ForegroundColor DarkGray
} else {
    Apply-Tweak "Разрешение сна шины PCIe (ASPM)" { Set-ItemProperty -Path $PciSys -Name "DisableASPM" -Value 0 -Type DWord -Force *>&1 | Out-File -FilePath $global:LogPath -Append -Encoding UTF8 } # Оставляем дефолт
    Apply-Tweak "Включение состояния сна D3 для PCIe" { Set-ItemProperty -Path $PciSys -Name "DefaultD3State" -Value 1 -Type DWord -Force *>&1 | Out-File -FilePath $global:LogPath -Append -Encoding UTF8 }
    Write-Host " ► ASPM PCIe оставлен включённым (Сон шины разрешен)" -ForegroundColor DarkGray
}

# Отключение DMI и PEG аппаратного сна (Делает связь CPU-Чипсет-USB монолитной)
Apply-Tweak "Отключение аппаратного сна DMI" { Set-ItemProperty -Path $PciParams -Name "DmiEnableAsm" -Value 0 -Type DWord -Force *>&1 | Out-File -FilePath $global:LogPath -Append -Encoding UTF8 }
Apply-Tweak "Отключение аппаратного сна PEG" { Set-ItemProperty -Path $PciParams -Name "PegAsmEnable" -Value 0 -Type DWord -Force *>&1 | Out-File -FilePath $global:LogPath -Append -Encoding UTF8 }
Apply-Tweak "Очистка HackFlags шины PCI (Защита от отвала GPU)" { Remove-ItemProperty -Path $PciSys -Name "HackFlags" -Force -ErrorAction SilentlyContinue *>&1 | Out-File -FilePath $global:LogPath -Append -Encoding UTF8 }

# Удаляем фиктивные лимиты MessageNumberLimit: Windows и драйвер обязаны считывать реальный лимит векторов из дескриптора PCIe
$DiscreteGPUs = Get-CimInstance Win32_VideoController | Where-Object { $_.Name -match "NVIDIA|AMD|Radeon" -and $_.Name -notmatch "Basic" }
foreach ($GPU in $DiscreteGPUs) {
    $MsiKey = "HKLM:\SYSTEM\CurrentControlSet\Enum\$($GPU.PNPDeviceID)\Device Parameters\Interrupt Management\MessageSignaledInterruptProperties"
    if (Test-Path $MsiKey) { 
        Apply-Tweak "Аппаратное согласование векторов MSI для $($GPU.Name)" { Remove-ItemProperty -Path $MsiKey -Name "MessageNumberLimit" *>&1 | Out-File -FilePath $global:LogPath -Append -Encoding UTF8 } 
    }
}

$SCSIControllers = Get-CimInstance Win32_SCSIController 2>> $env:SystemDrive\EastricaTools\Eastrica_ErrorTrace.log | Where-Object { $_.Name -match "NVMe|NVM Express" }
foreach ($scsi in $SCSIControllers) {
    if ($scsi.PNPDeviceID -match "^PCI") {
        $RegBase = "HKLM:\SYSTEM\CurrentControlSet\Enum\$($scsi.PNPDeviceID)\Device Parameters\Interrupt Management"
        if (Test-Path "$RegBase\MessageSignaledInterruptProperties") {
            Apply-Tweak "Аппаратное согласование векторов MSI для NVMe ($($scsi.Name))" { Remove-ItemProperty -Path "$RegBase\MessageSignaledInterruptProperties" -Name "MessageNumberLimit" *>&1 | Out-File -FilePath $global:LogPath -Append -Encoding UTF8 }
            Apply-Tweak "Активация MSI-X для NVMe" { Set-ItemProperty -Path $RegBase -Name "EnableMSIX" -Value 1 -Type DWord -Force *>&1 | Out-File -FilePath $global:LogPath -Append -Encoding UTF8 }
        }
    }
}

$NetAdaptersMSIX = Get-NetAdapter -Physical | Where-Object Status -eq 'Up'
foreach ($Adapter in $NetAdaptersMSIX) {
    if ($Adapter.PnPDeviceID -match "^PCI") {
        $RegBase = "HKLM:\SYSTEM\CurrentControlSet\Enum\$($Adapter.PnPDeviceID)\Device Parameters\Interrupt Management"
        if (Test-Path "$RegBase\MessageSignaledInterruptProperties") {
            $MsiPropKey = "$RegBase\MessageSignaledInterruptProperties"
            Apply-Tweak "Аппаратное согласование векторов MSI для сети ($($Adapter.Name))" { Remove-ItemProperty -Path $MsiPropKey -Name "MessageNumberLimit" *>&1 | Out-File -FilePath $global:LogPath -Append -Encoding UTF8 }
            Apply-Tweak "Проверка и активация поддержки MSI для сетевого адаптера" { Set-ItemProperty -Path $MsiPropKey -Name "MSISupported" -Value 1 -Type DWord -Force *>&1 | Out-File -FilePath $global:LogPath -Append -Encoding UTF8 }
        }
    }
}

# Понижение приоритета медленных SATA/AHCI жестких дисков (чтобы они не фризили систему)
$SataControllers = Get-CimInstance Win32_PnPEntity | Where-Object { ($_.Service -match "storahci|msahci|asahci64|asstahci") -or ($_.PNPClass -eq "HDC" -and $_.PNPDeviceID -match "^PCI") }
foreach ($Sata in $SataControllers) {
    $AffinityKey = "HKLM:\SYSTEM\CurrentControlSet\Enum\$($Sata.PNPDeviceID)\Device Parameters\Interrupt Management\Affinity Policy"
    if (!(Test-Path $AffinityKey)) { Apply-Tweak "Создание ключа Affinity для SATA" { New-Item -Path $AffinityKey -Force *>&1 | Out-File -FilePath $global:LogPath -Append -Encoding UTF8 } }
    Apply-Tweak "Нормальный приоритет прерываний для медленных SATA дисков" { Set-ItemProperty -Path $AffinityKey -Name "DevicePriority" -Value 2 -Type DWord -Force *>&1 | Out-File -FilePath $global:LogPath -Append -Encoding UTF8 } # 2 = Normal (Ниже, чем у GPU, Audio и NVMe)
}

Write-Host ""
# ==============================================================================
# Раздел 18: Экстремальный тюнинг видеокарт (NVIDIA, AMD, Intel)
# ==============================================================================
Show-ProgressStep -StepNum 18 -TotalSteps 81 -Activity "Оптимизация видеокарт (NVIDIA/AMD) и очистка VSync..."
Write-Host "==============================================================================" -ForegroundColor DarkGray
Write-Host "РАЗДЕЛ 18: ЭКСТРЕМАЛЬНЫЙ ТЮНИНГ ВИДЕОКАРТ (NVIDIA, AMD, INTEL)" -ForegroundColor Cyan
Write-Host "==============================================================================" -ForegroundColor DarkGray

$ClassPath = "HKLM:\SYSTEM\CurrentControlSet\Control\Class\{4d36e968-e325-11ce-bfc1-08002be10318}" # Ветка всех видеокарт в системе
Apply-Tweak "Захват прав на корневую ветку видеокарт" { Grant-RegPermission -RegPath $ClassPath } # Взламываем права на корневую ветку (Protected by SYSTEM)
$Adapters = @()
$baseKey = [Microsoft.Win32.Registry]::LocalMachine.OpenSubKey($ClassPath.Replace("HKLM:\", ""))
if ($baseKey) {
    foreach ($subName in $baseKey.GetSubKeyNames()) {
        if ($subName -match "^\d{4}$") {
            $Adapters += Get-Item -LiteralPath "$ClassPath\$subName" -ErrorAction SilentlyContinue
        }
    }
    $baseKey.Close()
}

if ($Adapters) {
    foreach ($Adapter in $Adapters) {
        $RegPath = $Adapter.PSPath
        $Provider = (Get-ItemProperty -LiteralPath $RegPath -Name "ProviderName" 2>> $env:SystemDrive\EastricaTools\Eastrica_ErrorTrace.log).ProviderName
        $Desc = (Get-ItemProperty -LiteralPath $RegPath -Name "DriverDesc" 2>> $env:SystemDrive\EastricaTools\Eastrica_ErrorTrace.log).DriverDesc

        # Пропускаем базовые драйверы Microsoft
        if (-not $Provider -or $Provider -match "Microsoft" -or $Desc -match "Basic") { continue }

        Apply-Tweak "Захват прав на адаптер ($($Adapter.PSChildName))" { Grant-RegPermission -RegPath $RegPath } # Взламываем права на подпапку конкретной карты (например, 0000)
        
        # Защита от потери герцовки монитора (Восстановление аппаратного DSC для 240Hz+ / 4K)
        Apply-Tweak "Восстановление поддержки высоких частот монитора (Очистка DscDisable)" {
            Remove-ItemProperty -LiteralPath $RegPath -Name "DscDisable" *>&1 | Out-File -FilePath $global:LogPath -Append -Encoding UTF8
        }
        
        # ==========================================
        # Твики для NVIDIA
        # ==========================================
        if ($Provider -match "NVIDIA" -or $Desc -match "NVIDIA") {
            Apply-Tweak "Удаление форсирования P0 State" { Remove-ItemProperty -LiteralPath $RegPath -Name "DisableDynamicPstate" *>&1 | Out-File -FilePath $global:LogPath -Append -Encoding UTF8 } # Удаляем форсирование P0 (Вызывает перегрев VRAM)
            Apply-Tweak "Удаление мусорного твика PerfLevelSrc" { Remove-ItemProperty -LiteralPath $RegPath -Name "PerfLevelSrc" *>&1 | Out-File -FilePath $global:LogPath -Append -Encoding UTF8 } # Удаляем неверный твик
            Apply-Tweak "Включение энергосбережения в простое (PowerMizer)" { Set-ItemProperty -LiteralPath $RegPath -Name "PowerMizerEnable" -Value 1 -Type DWord -Force *>&1 | Out-File -FilePath $global:LogPath -Append -Encoding UTF8 } # 1 = Включаем энергосбережение в простое
            Apply-Tweak "Сброс уровня PowerMizer" { Remove-ItemProperty -LiteralPath $RegPath -Name "PowerMizerLevel" *>&1 | Out-File -FilePath $global:LogPath -Append -Encoding UTF8 } # Сбрасываем уровень
            Apply-Tweak "Сброс уровня PowerMizer AC" { Remove-ItemProperty -LiteralPath $RegPath -Name "PowerMizerLevelAC" *>&1 | Out-File -FilePath $global:LogPath -Append -Encoding UTF8 }

            # Отключение мертвого 3D Stereo (Освобождение видеопамяти и DWM от старого 3D Vision)
            Apply-Tweak "Отключение поддержки 3D Stereo" { Set-ItemProperty -LiteralPath $RegPath -Name "0x11aa9e99" -Value 0 -Type DWord -Force *>&1 | Out-File -FilePath $global:LogPath -Append -Encoding UTF8 } # WKS_STEREO_SUPPORT
            Apply-Tweak "Отключение 3D Stereo Dongle" { Set-ItemProperty -LiteralPath $RegPath -Name "0x112493bd" -Value 0 -Type DWord -Force *>&1 | Out-File -FilePath $global:LogPath -Append -Encoding UTF8 } # WKS_STEREO_DONGLE_SUPPORT
            Apply-Tweak "Отключение API Stereo Mode" { Set-ItemProperty -LiteralPath $RegPath -Name "0x11e91a61" -Value 0 -Type DWord -Force *>&1 | Out-File -FilePath $global:LogPath -Append -Encoding UTF8 } # WKS_API_STEREO_MODE
            Apply-Tweak "Отключение Stereo Swap Mode" { Set-ItemProperty -LiteralPath $RegPath -Name "0x11333333" -Value 0 -Type DWord -Force *>&1 | Out-File -FilePath $global:LogPath -Append -Encoding UTF8 } # WKS_STEREO_SWAP_MODE

            # Отключение Workstation-композитинга (Снижает инпут-лаг на обычных игровых GeForce)
            Apply-Tweak "Отключение Workstation Scanout" { Set-ItemProperty -LiteralPath $RegPath -Name "0x11112255" -Value 0 -Type DWord -Force *>&1 | Out-File -FilePath $global:LogPath -Append -Encoding UTF8 } # WKS_SCANOUT_COMPOSITION_CONTROL
            Apply-Tweak "Отключение Workstation Post Processing" { Set-ItemProperty -LiteralPath $RegPath -Name "0x11112256" -Value 0 -Type DWord -Force *>&1 | Out-File -FilePath $global:LogPath -Append -Encoding UTF8 } # WKS_POST_PROCESSING_ENGINE_CONTROL
            Apply-Tweak "Отключение Workstation Feature Support" { Set-ItemProperty -LiteralPath $RegPath -Name "0x11d9dc84" -Value 0 -Type DWord -Force *>&1 | Out-File -FilePath $global:LogPath -Append -Encoding UTF8 } # WKS_FEATURE_SUPPORT_CONTROL

            # Отключение HDCP для NVIDIA (Убирает Display Lag и черные экраны при Alt+Tab, но полностью ломает воспроизведение DRM-видео - Кинопоиска, Netflix, стримингов в браузере или некоторых VR-шлемов).
            Apply-Tweak "Отключение HDCP защиты (NVIDIA)" { Set-ItemProperty -LiteralPath $RegPath -Name "DisableHDCP" -Value 1 -Type DWord -Force *>&1 | Out-File -FilePath $global:LogPath -Append -Encoding UTF8 }
            
            # Снимает лимит памяти в CUDA и прерывания
            Apply-Tweak "Отключение падения частоты VRAM в CUDA (ForceP2State)" { Set-ItemProperty -LiteralPath $RegPath -Name "CUDA_ForceP2State" -Value 0 -Type DWord -Force *>&1 | Out-File -FilePath $global:LogPath -Append -Encoding UTF8 } # Отключаем падение частоты памяти в вычислениях
            Apply-Tweak "Возврат аппаратного прерывания CUDA" { Remove-ItemProperty -LiteralPath $RegPath -Name "ComputePreemption" *>&1 | Out-File -FilePath $global:LogPath -Append -Encoding UTF8 } # Возвращаем аппаратное прерывание
            Apply-Tweak "Возврат аппаратного прерывания графики" { Remove-ItemProperty -LiteralPath $RegPath -Name "GraphicsPreemption" *>&1 | Out-File -FilePath $global:LogPath -Append -Encoding UTF8 } # Возвращаем аппаратное прерывание
            
            # Разрешение прерываний контекста CUDA (защита от фризов рабочего стола при работе нейросетей)
            Apply-Tweak "Разрешение прерываний контекста CUDA" {
                Set-ItemProperty -LiteralPath $RegPath -Name "DisableCudaContextPreemption" -Value 0 -Type DWord -Force *>&1 | Out-File -FilePath $global:LogPath -Append -Encoding UTF8
            }
            
            Apply-Tweak "Постоянная готовность шины памяти VRAM (RmMIONoPowerOff)" {
                Set-ItemProperty -LiteralPath $RegPath -Name "RmMIONoPowerOff" -Value 1 -Type DWord -Force *>&1 | Out-File -FilePath $global:LogPath -Append -Encoding UTF8
            }
            
            Apply-Tweak "Отключение зависания при сбоях видеодрайвера (DisableBugcheckCallback)" {
                Set-ItemProperty -LiteralPath $RegPath -Name "DisableBugcheckCallback" -Value 1 -Type DWord -Force *>&1 | Out-File -FilePath $global:LogPath -Append -Encoding UTF8
            }
            
            # Умное управление гибридной графикой (MsHybrid / Optimus / MUX Switch)
            $HasActiveIGPU = [bool]($global:GPUs | Where-Object {
                ($_.Name -match "Intel" -and $_.Name -notmatch "Arc|Iris Xe Max") -or 
                ($_.Name -match "Radeon.*Graphics|Vega|Radeon\(TM\) Graphics|RDNA")
            })
            $HasDiscreteGPU = [bool]($global:GPUs | Where-Object {
                ($_.Name -match "NVIDIA|GeForce|RTX|GTX|Quadro|Radeon RX|Radeon Pro") -and 
                ($_.Name -notmatch "Basic|Microsoft")
            })

            # Считаем систему классическим гибридом ТОЛЬКО если это ноутбук И в системе РЕАЛЬНО активны оба видеочипа
            $IsOptimusLaptop = $global:IsLaptop -and $HasActiveIGPU -and $HasDiscreteGPU

            if ($IsOptimusLaptop) {
                # --------------------------------------------------------------------------
                # 1. Гибридный ноутбук (Optimus: iGPU + dGPU работают вместе)
                # --------------------------------------------------------------------------
                # На гибридном ноутбуке удаление или обнуление (= 0) ломает Hand-off кадров 
                # на экран матрицы. Если ключи были повреждены прошлыми твикерами — восстанавливаем их.
                $CurrentMsHybrid = (Get-ItemProperty -LiteralPath $RegPath -Name "EnableMsHybrid" 2>> $env:SystemDrive\EastricaTools\Eastrica_ErrorTrace.log).EnableMsHybrid
                $CurrentHybridMode = (Get-ItemProperty -LiteralPath $RegPath -Name "MsHybridMode" 2>> $env:SystemDrive\EastricaTools\Eastrica_ErrorTrace.log).MsHybridMode

                if ($null -eq $CurrentMsHybrid -or $CurrentMsHybrid -eq 0) {
                    Apply-Tweak "Восстановление конвейера Optimus на ноутбуке (EnableMsHybrid = 1)" {
                        Set-ItemProperty -LiteralPath $RegPath -Name "EnableMsHybrid" -Value 1 -Type DWord -Force *>&1 | Out-File -FilePath $global:LogPath -Append -Encoding UTF8
                    }
                }
                if ($null -eq $CurrentHybridMode -or $CurrentHybridMode -eq 0) {
                    Apply-Tweak "Восстановление режима вывода кадров (MsHybridMode = 1)" {
                        Set-ItemProperty -LiteralPath $RegPath -Name "MsHybridMode" -Value 1 -Type DWord -Force *>&1 | Out-File -FilePath $global:LogPath -Append -Encoding UTF8
                    }
                }
            }
            else {
                # --------------------------------------------------------------------------
                # 2. Стационарный ПК или ноутбук с активным MUX Switch (только dGPU)
                # --------------------------------------------------------------------------
                # Сигнал идет напрямую в дисплей. Присутствие этих ключей заставляет DWM 
                # опрашивать шину в поисках второго чипа, порождая микростаттеры мыши.
                # КАТЕГОРИЧЕСКИ УДАЛЯЕМ (Remove), а не ставим 0!
                Apply-Tweak "Удаление паразитного опроса гибридной графики (EnableMsHybrid)" {
                    Remove-ItemProperty -LiteralPath $RegPath -Name "EnableMsHybrid" *>&1 | Out-File -FilePath $global:LogPath -Append -Encoding UTF8
                }
                Apply-Tweak "Удаление режима переключения графики (MsHybridMode)" {
                    Remove-ItemProperty -LiteralPath $RegPath -Name "MsHybridMode" *>&1 | Out-File -FilePath $global:LogPath -Append -Encoding UTF8
                }

                # Дополнительно сносим артефакты кросс-адаптерного сканирования CASO
                Apply-Tweak "Удаление кросс-адаптерного оверлея (CrossAdapterScanOut)" {
                    Remove-ItemProperty -LiteralPath $RegPath -Name "CrossAdapterScanOut" *>&1 | Out-File -FilePath $global:LogPath -Append -Encoding UTF8
                }
            }
        }
        
        # ==========================================
        # Твики для AMD / RADEON
        # ==========================================
        elseif ($Provider -match "Advanced Micro Devices" -or $Desc -match "AMD" -or $Desc -match "Radeon") {
            # Настройка ULPS (Ultra Low Power State)
            if ($global:IsLaptop) {
                # На ноутбуке включаем ULPS (Иначе высадит батарею)
                Apply-Tweak "Включение ULPS (Ноутбук)" { Set-ItemProperty -LiteralPath $RegPath -Name "EnableUlps" -Value 1 -Type DWord -Force *>&1 | Out-File -FilePath $global:LogPath -Append -Encoding UTF8 }
                Apply-Tweak "Включение ULPS NA" { Set-ItemProperty -LiteralPath $RegPath -Name "EnableUlps_NA" -Value 1 -Type String -Force *>&1 | Out-File -FilePath $global:LogPath -Append -Encoding UTF8 }
                Apply-Tweak "Включение Ulps2" { Set-ItemProperty -LiteralPath $RegPath -Name "Ulps2" -Value 1 -Type DWord -Force *>&1 | Out-File -FilePath $global:LogPath -Append -Encoding UTF8 }
            } else {
                # На ПК отключаем ULPS (Убирает просадки FPS)
                Apply-Tweak "Отключение ULPS (Устранение просадок FPS)" { Set-ItemProperty -LiteralPath $RegPath -Name "EnableUlps" -Value 0 -Type DWord -Force *>&1 | Out-File -FilePath $global:LogPath -Append -Encoding UTF8 }
                Apply-Tweak "Отключение ULPS NA" { Set-ItemProperty -LiteralPath $RegPath -Name "EnableUlps_NA" -Value 0 -Type String -Force *>&1 | Out-File -FilePath $global:LogPath -Append -Encoding UTF8 }
                Apply-Tweak "Отключение Ulps2" { Set-ItemProperty -LiteralPath $RegPath -Name "Ulps2" -Value 0 -Type DWord -Force *>&1 | Out-File -FilePath $global:LogPath -Append -Encoding UTF8 }
            }

            # Принудительное использование Resizable BAR (Smart Access Memory) для DX11, DX12 и Vulkan
            Apply-Tweak "Принудительное использование ReBAR для DX11" { Set-ItemProperty -LiteralPath $RegPath -Name "KMD_EnableReBarForDx11" -Value 1 -Type DWord -Force *>&1 | Out-File -FilePath $global:LogPath -Append -Encoding UTF8 }
            Apply-Tweak "Принудительное использование ReBAR для DX12" { Set-ItemProperty -LiteralPath $RegPath -Name "KMD_EnableReBarForDx12" -Value 1 -Type DWord -Force *>&1 | Out-File -FilePath $global:LogPath -Append -Encoding UTF8 }
            Apply-Tweak "Принудительное использование ReBAR для Vulkan" { Set-ItemProperty -LiteralPath $RegPath -Name "KMD_EnableReBarForVulkan" -Value 1 -Type DWord -Force *>&1 | Out-File -FilePath $global:LogPath -Append -Encoding UTF8 }

            # Отключение встроенной генерации кадров (AFMF 2) на уровне ядра
            Apply-Tweak "Отключение встроенной генерации кадров AFMF" { Set-ItemProperty -LiteralPath $RegPath -Name "KMD_EnableAFMF" -Value 0 -Type DWord -Force *>&1 | Out-File -FilePath $global:LogPath -Append -Encoding UTF8 } # 0 = AFMF выключен
            Apply-Tweak "Отключение генерации кадров дисплея (DalGFXEnableAFMF)" { Set-ItemProperty -LiteralPath $RegPath -Name "DalGFXEnableAFMF" -Value 0 -Type DWord -Force *>&1 | Out-File -FilePath $global:LogPath -Append -Encoding UTF8 }
            
            # Удаление Anti-Lag
            Apply-Tweak "Удаление Anti-Lag" { Remove-ItemProperty -LiteralPath $RegPath -Name "KMD_AntiLagEnabled" *>&1 | Out-File -FilePath $global:LogPath -Append -Encoding UTF8 } # Удалить старый твик
            Apply-Tweak "Удаление старого ключа AntiLagEnable" { Remove-ItemProperty -LiteralPath $RegPath -Name "KMD_EnableAntiLag" *>&1 | Out-File -FilePath $global:LogPath -Append -Encoding UTF8 } # Удалить старый твик
            Apply-Tweak "Удаление Anti-Lag 2 (NextGen)" { Remove-ItemProperty -LiteralPath $RegPath -Name "KMD_AntiLagNextGen" *>&1 | Out-File -FilePath $global:LogPath -Append -Encoding UTF8 } # Удалить старый твик

            # Экстремальный кэш шейдеров AMD
            $UmdPath = "$RegPath\UMD"
            if (!(Test-Path -Path $UmdPath)) { Apply-Tweak "Создание папки UMD" { New-Item -Path $UmdPath -Force *>&1 | Out-File -FilePath $global:LogPath -Append -Encoding UTF8 } } # Создаем подпапку UMD
            Apply-Tweak "Включение Shader Cache (AMD)" { Set-ItemProperty -LiteralPath $UmdPath -Name "ShaderCache" -Value "1" -Type String -Force *>&1 | Out-File -FilePath $global:LogPath -Append -Encoding UTF8 } # Включаем Shader Cache
            Apply-Tweak "Снятие лимита кэша шейдеров" { Remove-ItemProperty -LiteralPath $UmdPath -Name "ShaderCacheLimit" *>&1 | Out-File -FilePath $global:LogPath -Append -Encoding UTF8 } # Удаляем лимит кэша (Драйвер будет использовать 10GB системы)
            Apply-Tweak "Сохранение кэша шейдеров на диске" { Set-ItemProperty -LiteralPath $UmdPath -Name "ShaderCacheStorageMode" -Value 1 -Type DWord -Force *>&1 | Out-File -FilePath $global:LogPath -Append -Encoding UTF8 } # 1 = Включаем хранение на диске

            # Восстановление сна памяти AMD (Снижение энергопотребления видеокарты в простое)
            Apply-Tweak "Разрешение снижения частот VRAM видеокарт AMD в простое" { 
                Remove-ItemProperty -LiteralPath $RegPath -Name "PP_FclkDeepSleepDisable" *>&1 | Out-File -FilePath $global:LogPath -Append -Encoding UTF8
                Remove-ItemProperty -LiteralPath $RegPath -Name "PP_MclkDeepSleepDisable" *>&1 | Out-File -FilePath $global:LogPath -Append -Encoding UTF8
                Remove-ItemProperty -LiteralPath $RegPath -Name "PP_SclkDeepSleepDisable" *>&1 | Out-File -FilePath $global:LogPath -Append -Encoding UTF8
            }

            # Принудительная очередь кадров (Flip Queue Size = 1)
            Apply-Tweak "Очередь кадров = 1 (FlipQueueSize)" { Set-ItemProperty -LiteralPath $RegPath -Name "FlipQueueSize" -Value "1" -Type String -Force *>&1 | Out-File -FilePath $global:LogPath -Append -Encoding UTF8 }
            Apply-Tweak "Очередь кадров 3D = 1" { Set-ItemProperty -LiteralPath $RegPath -Name "Main3D_FlipQueueSize" -Value "1" -Type String -Force *>&1 | Out-File -FilePath $global:LogPath -Append -Encoding UTF8 }
            Apply-Tweak "Очередь кадров 3D DEF = 1" { Set-ItemProperty -LiteralPath $RegPath -Name "Main3D_DEF_FlipQueueSize" -Value "1" -Type String -Force *>&1 | Out-File -FilePath $global:LogPath -Append -Encoding UTF8 }

            # Убийство скрытых статтеров текстур
            Apply-Tweak "Наивысшее качество текстур (TextureLod = 0)" { Set-ItemProperty -LiteralPath $RegPath -Name "TextureLod" -Value 0 -Type DWord -Force *>&1 | Out-File -FilePath $global:LogPath -Append -Encoding UTF8 } # 0 = Наивысшее качество
            Apply-Tweak "Отключение снижения качества текстур (TFQ)" { Set-ItemProperty -LiteralPath $RegPath -Name "TFQ" -Value 0 -Type DWord -Force *>&1 | Out-File -FilePath $global:LogPath -Append -Encoding UTF8 } # Отключить снижение качества текстур
            Apply-Tweak "Оптимизация против статтеров (StutterMode = 0)" { Set-ItemProperty -LiteralPath $RegPath -Name "StutterMode" -Value 0 -Type DWord -Force *>&1 | Out-File -FilePath $global:LogPath -Append -Encoding UTF8 } # 0 = Оптимизация против статтеров
            
            # Отключение HDCP
            Apply-Tweak "Отключение HDCP защиты (AMD)" { Set-ItemProperty -LiteralPath $RegPath -Name "HDCPEnable" -Value 0 -Type DWord -Force *>&1 | Out-File -FilePath $global:LogPath -Append -Encoding UTF8 } # 0 = HDCP отключен
            
            Apply-Tweak "Возврат управления прерываниями графики ядру системы" { Remove-ItemProperty -LiteralPath $RegPath -Name "KMD_EnablePreemption" *>&1 | Out-File -FilePath $global:LogPath -Append -Encoding UTF8 } # Удалить твик (Оставить ядру)
            Apply-Tweak "Возврат управления прерываниями вычислений ядру системы" { Remove-ItemProperty -LiteralPath $RegPath -Name "KMD_EnableComputePreemption" *>&1 | Out-File -FilePath $global:LogPath -Append -Encoding UTF8 } # Удалить твик (Оставить ядру)
            
            # Гранулярное аппаратное прерывание графических команд AMD (Mid-Command)
            Apply-Tweak "Включение аппаратного Mid-Command Preemption для AMD" {
                Set-ItemProperty -LiteralPath $RegPath -Name "KMD_EnableGfxMidCmdPreemption" -Value 1 -Type DWord -Force *>&1 | Out-File -FilePath $global:LogPath -Append -Encoding UTF8
            }
            
            # Многопоточная оптимизация диспетчеризации Direct3D в драйвере AMD (DXX / DXC)
            $DxxPath = "$RegPath\UMD\DXX"
            $DxcPath = "$RegPath\UMD\DXC"
            if (!(Test-Path $DxxPath)) { New-Item -Path $DxxPath -Force *>&1 | Out-File -FilePath $global:LogPath -Append -Encoding UTF8 | Out-Null }
            if (!(Test-Path $DxcPath)) { New-Item -Path $DxcPath -Force *>&1 | Out-File -FilePath $global:LogPath -Append -Encoding UTF8 | Out-Null }
            
            Apply-Tweak "Включение многопоточности AMD DirectX (CpuAffinityOptimization)" {
                Set-ItemProperty -LiteralPath $RegPath -Name "CpuAffinityOptimization" -Value 1 -Type DWord -Force *>&1 | Out-File -FilePath $global:LogPath -Append -Encoding UTF8
                Set-ItemProperty -LiteralPath "$RegPath\UMD" -Name "CpuAffinityOptimization" -Value 1 -Type DWord -Force *>&1 | Out-File -FilePath $global:LogPath -Append -Encoding UTF8
                Set-ItemProperty -LiteralPath $DxxPath -Name "CpuAffinityOptimization" -Value "1" -Type String -Force *>&1 | Out-File -FilePath $global:LogPath -Append -Encoding UTF8
                Set-ItemProperty -LiteralPath $DxcPath -Name "CpuAffinityOptimization" -Value "1" -Type String -Force *>&1 | Out-File -FilePath $global:LogPath -Append -Encoding UTF8
            }
            
            # Отключение фонового ведения журналов и телеметрии видеодрайвера AMD
            Apply-Tweak "Отключение скрытых журналов драйвера AMD (Event Log / eRecord)" {
                Set-ItemProperty -LiteralPath $RegPath -Name "EnableAmdLog" -Value 0 -Type DWord -Force *>&1 | Out-File -FilePath $global:LogPath -Append -Encoding UTF8
                Set-ItemProperty -LiteralPath $RegPath -Name "KMD_EVENT_LOG" -Value 0 -Type DWord -Force *>&1 | Out-File -FilePath $global:LogPath -Append -Encoding UTF8
                Set-ItemProperty -LiteralPath $RegPath -Name "DisableeRecord" -Value 1 -Type DWord -Force *>&1 | Out-File -FilePath $global:LogPath -Append -Encoding UTF8
            }
            
            # Лечение мерцания экрана AMD (удаление вредоносных твиков таймингов шины)
            # Удаляет опасные ключи из сомнительных твик-паков, вызывающие черные вспышки и отвал DSC
            Apply-Tweak "Устранение мерцания экрана AMD (Очистка DalDramClockChangeLatencyNs)" {
                Remove-ItemProperty -LiteralPath $RegPath -Name "DalDramClockChangeLatencyNs" *>&1 | Out-File -FilePath $global:LogPath -Append -Encoding UTF8
                Remove-ItemProperty -LiteralPath $RegPath -Name "DalUrgentLatencyNs" *>&1 | Out-File -FilePath $global:LogPath -Append -Encoding UTF8
                Remove-ItemProperty -LiteralPath $RegPath -Name "DalNBLatencyForUnderFlow" *>&1 | Out-File -FilePath $global:LogPath -Append -Encoding UTF8
                Remove-ItemProperty -LiteralPath $RegPath -Name "memClockSwitchLatency" *>&1 | Out-File -FilePath $global:LogPath -Append -Encoding UTF8
            }
            
            # Полное снятие аппаратного лимита кадров с видеокарт AMD (без искусственных ограничений)
            Apply-Tweak "Снятие аппаратного лимита кадров AMD FRTC" { Remove-ItemProperty -LiteralPath $RegPath -Name "KMD_FRTEnabled" *>&1 | Out-File -FilePath $global:LogPath -Append -Encoding UTF8 }
            Apply-Tweak "Удаление целевой частоты кадров AMD FRTC" { Remove-ItemProperty -LiteralPath $RegPath -Name "KMD_FRTTarget" *>&1 | Out-File -FilePath $global:LogPath -Append -Encoding UTF8 }
            Apply-Tweak "Включение MPO в драйвере AMD" { Set-ItemProperty -LiteralPath $RegPath -Name "DisableMultiPlaneOverlay" -Value 0 -Type DWord -Force *>&1 | Out-File -FilePath $global:LogPath -Append -Encoding UTF8 } # 0 = Включить MPO в самом драйвере
            Apply-Tweak "Удаление запрета DirectFlip" { Remove-ItemProperty -LiteralPath $RegPath -Name "DalAllowDirectFlip" *>&1 | Out-File -FilePath $global:LogPath -Append -Encoding UTF8 } # Удалить запрет DirectFlip
            Apply-Tweak "Отключение драйверного VSync (DalVSyncControl)" { Set-ItemProperty -LiteralPath $RegPath -Name "DalVSyncControl" -Value 0 -Type DWord -Force *>&1 | Out-File -FilePath $global:LogPath -Append -Encoding UTF8 } # 0 = Отключить драйверный VSync
            
            # Умное управление гибридной графикой (MSHYBRID / OPTIMUS / MUX SWITCH)
            $HasActiveIGPU = [bool]($global:GPUs | Where-Object {
                ($_.Name -match "Intel" -and $_.Name -notmatch "Arc|Iris Xe Max") -or 
                ($_.Name -match "Radeon.*Graphics|Vega|Radeon\(TM\) Graphics|RDNA")
            })
            $HasDiscreteGPU = [bool]($global:GPUs | Where-Object {
                ($_.Name -match "NVIDIA|GeForce|RTX|GTX|Quadro|Radeon RX|Radeon Pro") -and 
                ($_.Name -notmatch "Basic|Microsoft")
            })

            # Считаем систему классическим гибридом ТОЛЬКО если это ноутбук И в системе РЕАЛЬНО активны оба видеочипа
            $IsOptimusLaptop = $global:IsLaptop -and $HasActiveIGPU -and $HasDiscreteGPU

            if ($IsOptimusLaptop) {
                # --------------------------------------------------------------------------
                # 1. Гибридный ноутбук (Optimus: iGPU + dGPU работают вместе)
                # --------------------------------------------------------------------------
                # На гибридном ноутбуке удаление или обнуление (= 0) ломает Hand-off кадров 
                # на экран матрицы. Если ключи были повреждены прошлыми твикерами — восстанавливаем их.
                $CurrentMsHybrid = (Get-ItemProperty -LiteralPath $RegPath -Name "EnableMsHybrid" 2>> $env:SystemDrive\EastricaTools\Eastrica_ErrorTrace.log).EnableMsHybrid
                $CurrentHybridMode = (Get-ItemProperty -LiteralPath $RegPath -Name "MsHybridMode" 2>> $env:SystemDrive\EastricaTools\Eastrica_ErrorTrace.log).MsHybridMode

                if ($null -eq $CurrentMsHybrid -or $CurrentMsHybrid -eq 0) {
                    Apply-Tweak "Восстановление конвейера Optimus на ноутбуке (EnableMsHybrid = 1)" {
                        Set-ItemProperty -LiteralPath $RegPath -Name "EnableMsHybrid" -Value 1 -Type DWord -Force *>&1 | Out-File -FilePath $global:LogPath -Append -Encoding UTF8
                    }
                }
                if ($null -eq $CurrentHybridMode -or $CurrentHybridMode -eq 0) {
                    Apply-Tweak "Восстановление режима вывода кадров (MsHybridMode = 1)" {
                        Set-ItemProperty -LiteralPath $RegPath -Name "MsHybridMode" -Value 1 -Type DWord -Force *>&1 | Out-File -FilePath $global:LogPath -Append -Encoding UTF8
                    }
                }
            }
            else {
                # --------------------------------------------------------------------------
                # 2. Стационарный ПК или ноутбук с активным MUX SWITCH (Только dGPU)
                # --------------------------------------------------------------------------
                # Сигнал идет напрямую в дисплей. Присутствие этих ключей заставляет DWM 
                # опрашивать шину в поисках второго чипа, порождая микростаттеры мыши.
                # КАТЕГОРИЧЕСКИ УДАЛЯЕМ (Remove), а не ставим 0!
                Apply-Tweak "Удаление паразитного опроса гибридной графики (EnableMsHybrid)" {
                    Remove-ItemProperty -LiteralPath $RegPath -Name "EnableMsHybrid" *>&1 | Out-File -FilePath $global:LogPath -Append -Encoding UTF8
                }
                Apply-Tweak "Удаление режима переключения графики (MsHybridMode)" {
                    Remove-ItemProperty -LiteralPath $RegPath -Name "MsHybridMode" *>&1 | Out-File -FilePath $global:LogPath -Append -Encoding UTF8
                }

                # Дополнительно сносим артефакты кросс-адаптерного сканирования CASO
                Apply-Tweak "Удаление кросс-адаптерного оверлея (CrossAdapterScanOut)" {
                    Remove-ItemProperty -LiteralPath $RegPath -Name "CrossAdapterScanOut" *>&1 | Out-File -FilePath $global:LogPath -Append -Encoding UTF8
                }
            }
        }
        # ==========================================
        # Твики для Intel (встройка)
        # ==========================================
        elseif ($Provider -match "Intel" -or $Desc -match "Intel") {
            Write-Host " ► Обнаружена видеокарта Intel. Настройка реестра..." -ForegroundColor DarkGray
            Apply-Tweak "Отключение HDCP защиты (Intel)" { Set-ItemProperty -LiteralPath $RegPath -Name "DisableHDCP" -Value 1 -Type DWord -Force *>&1 | Out-File -FilePath $global:LogPath -Append -Encoding UTF8 } # 1 = Отключение HDCP
            Apply-Tweak "Отключение Panel Self Refresh (Энергосбережение Intel)" { Set-ItemProperty -LiteralPath $RegPath -Name "FeatureTestControl" -Value 37458 -Type DWord -Force *>&1 | Out-File -FilePath $global:LogPath -Append -Encoding UTF8 } # 37458 = Отключение энергосбережения Panel Self Refresh (PSR)
        }
        Apply-Tweak "Восстановление прав на класс видеокарты" { Restore-RegPermission -RegPath $RegPath } # Возвращаем права системе
    }
}
Apply-Tweak "Восстановление прав на корневой класс видеокарт" { Restore-RegPermission -RegPath $ClassPath } # Возвращаем права на корневую ветку

# ==========================================
# Исправления для нового поколения AMD RX 9000
# ==========================================
if ($global:GPUs | Where-Object { $_.Name -match "RX 9\d{3}" }) {
    $ClassPath = "HKLM:\SYSTEM\CurrentControlSet\Control\Class\{4d36e968-e325-11ce-bfc1-08002be10318}"
    Apply-Tweak "Захват прав на корневой класс видеокарт (RX 9000)" { Grant-RegPermission -RegPath $ClassPath }
    $AmdAdapters = Get-SafeClassAdapters -ClassPath $ClassPath
 
    foreach ($Adapter in $AmdAdapters) {
        $RegPath  = $Adapter.PSPath
        $Provider = (Get-ItemProperty -LiteralPath $RegPath -Name "ProviderName" -ErrorAction SilentlyContinue).ProviderName
        $Desc     = (Get-ItemProperty -LiteralPath $RegPath -Name "DriverDesc" -ErrorAction SilentlyContinue).DriverDesc
 
        if (($Provider -match "Advanced Micro Devices") -and ($Desc -match "Radeon RX 9")) {
            Apply-Tweak "Захват прав на адаптер RX 9000" { Grant-RegPermission -RegPath $RegPath }
            $UmdPath = "$RegPath\UMD"
            if (!(Test-Path -LiteralPath $UmdPath)) { Apply-Tweak "Создание папки UMD для RX 9000" { New-Item -LiteralPath $UmdPath -Force *>&1 | Out-File -FilePath $global:LogPath -Append -Encoding UTF8 } }
 
            # Clock Stretching и Clock Gating на RDNA 4 НЕЛЬЗЯ отключать во избежание сбоя питания чипа
            Apply-Tweak "Безопасное состояние Clock Stretching для RDNA 4" { Remove-ItemProperty -LiteralPath $RegPath -Name "PP_DisableClockStretching" -Force -ErrorAction SilentlyContinue *>&1 | Out-File -FilePath $global:LogPath -Append -Encoding UTF8 }
            Apply-Tweak "Безопасное состояние Clock Gating для RDNA 4" { 
                Remove-ItemProperty -LiteralPath $RegPath -Name "KMD_DisableBlockGfxCG" -Force -ErrorAction SilentlyContinue *>&1 | Out-File -FilePath $global:LogPath -Append -Encoding UTF8
                Remove-ItemProperty -LiteralPath $RegPath -Name "KMD_DisableBlockSysCG" -Force -ErrorAction SilentlyContinue *>&1 | Out-File -FilePath $global:LogPath -Append -Encoding UTF8
            }

            # Настройки задержки и синхронизации
            Apply-Tweak "Включение Anti-Lag (KMD)" { Set-ItemProperty -LiteralPath $RegPath -Name "KMD_AntiLagEnabled" -Value 1 -Type DWord -Force *>&1 | Out-File -FilePath $global:LogPath -Append -Encoding UTF8 }
            Apply-Tweak "Отключение AFMF (Генерация кадров) KMD" { Set-ItemProperty -LiteralPath $RegPath -Name "KMD_EnableAFMF" -Value 0 -Type DWord -Force *>&1 | Out-File -FilePath $global:LogPath -Append -Encoding UTF8 }
            Apply-Tweak "Отключение AFMF 1 UMD" { Set-ItemProperty -LiteralPath $UmdPath -Name "AFMFEnable" -Value "0" -Type String -Force *>&1 | Out-File -FilePath $global:LogPath -Append -Encoding UTF8 }
            Apply-Tweak "Отключение AFMF 2 UMD" { Set-ItemProperty -LiteralPath $UmdPath -Name "AFMF2Enable" -Value "0" -Type String -Force *>&1 | Out-File -FilePath $global:LogPath -Append -Encoding UTF8 }
 
            # Resizable BAR для RDNA 4
            Apply-Tweak "Включение Smart Access Memory для RDNA 4" { Set-ItemProperty -LiteralPath $RegPath -Name "KMD_EnableSAM" -Value 1 -Type DWord -Force *>&1 | Out-File -FilePath $global:LogPath -Append -Encoding UTF8 }
            Apply-Tweak "Включение ReBAR для RDNA 4" { Set-ItemProperty -LiteralPath $RegPath -Name "KMD_EnableResizableBAR" -Value 1 -Type DWord -Force *>&1 | Out-File -FilePath $global:LogPath -Append -Encoding UTF8 }

            # Многопоточность шейдеров AMD (LLVM)
            Apply-Tweak "Многопоточная диспетчеризация шейдеров AMD (LLVM)" { [Environment]::SetEnvironmentVariable("AMD_ENABLE_LLVM_MULTITHREADING", "1", "Machine") }
            Apply-Tweak "Отключение лимита мультипоточной отправки команд AMD" { [Environment]::SetEnvironmentVariable("AMD_DISABLE_MULTI_THREAD_SUBMIT", "0", "Machine") }
            Apply-Tweak "Восстановление прав на адаптер RX 9000" { Restore-RegPermission -RegPath $RegPath }
        }
    }
    Apply-Tweak "Восстановление прав на корневой класс видеокарт (RX 9000)" { Restore-RegPermission -RegPath $ClassPath }
 
    # Отключение инструмента отчетов об ошибках AMD
    $AmdBugReport = "HKLM:\SOFTWARE\AMD\CN"
    if (!(Test-Path $AmdBugReport)) { Apply-Tweak "Создание раздела AMD CN" { New-Item -Path $AmdBugReport -Force *>&1 | Out-File -FilePath $global:LogPath -Append -Encoding UTF8 } }
    Apply-Tweak "Отключение диагностики AMD" { Set-ItemProperty -Path $AmdBugReport -Name "DiagnosticsEnabled" -Value 0 -Type DWord -Force *>&1 | Out-File -FilePath $global:LogPath -Append -Encoding UTF8 }
    Apply-Tweak "Отключение автозапуска диагностики AMD" { Set-ItemProperty -Path $AmdBugReport -Name "AutoStartEnabled" -Value 0 -Type DWord -Force *>&1 | Out-File -FilePath $global:LogPath -Append -Encoding UTF8 }
 
    if (Get-Service -Name "AMD Crash Defender Service" -ErrorAction SilentlyContinue) {
        Apply-Tweak "Остановка AMD Crash Defender Service" { Stop-Service -Name "AMD Crash Defender Service" -Force *>&1 | Out-File -FilePath $global:LogPath -Append -Encoding UTF8 }
        Apply-Tweak "Отключение автозапуска AMD Crash Defender Service" { Set-Service -Name "AMD Crash Defender Service" -StartupType Disabled *>&1 | Out-File -FilePath $global:LogPath -Append -Encoding UTF8 }
    }
 
    # Vulkan Implicit Layers — блокировка мусорных слоев AMD (исправление фризов Vulkan)
    $VulkanLayerPaths = @("HKLM:\SOFTWARE\Khronos\Vulkan\ImplicitLayers", "HKCU:\Software\Khronos\Vulkan\ImplicitLayers")
    foreach ($VkPath in $VulkanLayerPaths) {
        if (Test-Path $VkPath) {
            $Layers = (Get-Item -Path $VkPath).GetValueNames() # Получаем список внедренных слоев
            foreach ($Layer in $Layers) {
                # Ищем слои профилировщиков AMD
                if ($Layer -match "amd_rgp|amd_rra|amdPalRuntimeLayer|amd_crash") {
                    Apply-Tweak "Блокировка интеграции оверлея Vulkan ($Layer)" { Set-ItemProperty -Path $VkPath -Name $Layer -Value 0 -Type DWord -Force *>&1 | Out-File -FilePath $global:LogPath -Append -Encoding UTF8 } # 0 = Запретить интеграцию слоя в конвейер Vulkan
                }
            }
        }
    }
}

Write-Host " ► Очистка конфликтных слоев Vulkan (Implicit Layers)..." -ForegroundColor DarkGray
$VkPaths = @(
    "HKLM:\SOFTWARE\Khronos\Vulkan\ImplicitLayers",
    "HKLM:\SOFTWARE\WOW6432Node\Khronos\Vulkan\ImplicitLayers",
    "HKCU:\Software\Khronos\Vulkan\ImplicitLayers"
)
foreach ($VkPath in $VkPaths) {
    if (Test-Path $VkPath) {
        $Layers = (Get-Item -Path $VkPath).GetValueNames()
        foreach ($Layer in $Layers) {
            # Блокируем Discord, Overwolf, Twitch, OBS (старый), Epic Games, GOG
            if ($Layer -match "(?i)discord|overwolf|twitch|obs-vulkan|epicgames|gog|reshade|bandicam") {
                Apply-Tweak "Блокировка паразитного слоя Vulkan: $(Split-Path $Layer -Leaf)" { 
                    Set-ItemProperty -Path $VkPath -Name $Layer -Value 1 -Type DWord -Force *>&1 | Out-File -FilePath $global:LogPath -Append -Encoding UTF8 
                } # 1 = Слой отключен (в новых спецификациях Khronos Disable = 1)
            }
        }
    }
}

Write-Host ""
# ==============================================================================
# Раздел 19: Глобальные твики NVIDIA, ИИ-кэш и службы телеметрии
# ==============================================================================
Show-ProgressStep -StepNum 19 -TotalSteps 81 -Activity "Глобальные твики NVIDIA, ИИ-кэш и телеметрия..."
Write-Host "==============================================================================" -ForegroundColor DarkGray
Write-Host "РАЗДЕЛ 19: ГЛОБАЛЬНЫЕ ТВИКИ NVIDIA, ИИ-КЭШ И СЛУЖБЫ ТЕЛЕМЕТРИИ" -ForegroundColor Cyan
Write-Host "==============================================================================" -ForegroundColor DarkGray

# Разблокировка GPU Performance Counters (Аппаратный мониторинг без накладных расходов)
$PerfCounters1 = "HKLM:\SOFTWARE\NVIDIA Corporation\Global\NVTweak"
$PerfCounters2 = "HKLM:\SYSTEM\CurrentControlSet\Services\nvlddmkm\Global\NVTweak"
foreach ($Path in @($PerfCounters1, $PerfCounters2)) {
    if (!(Test-Path $Path)) { Apply-Tweak "Создание раздела NVTweak" { New-Item $Path -Force *>&1 | Out-File -FilePath $global:LogPath -Append -Encoding UTF8 } } # Создаем раздел, если его нет
    Apply-Tweak "Разрешение прямого мониторинга датчиков GPU (RmProfilingAdminOnly)" { Set-ItemProperty -Path $Path -Name "RmProfilingAdminOnly" -Value 0 -Type DWord -Force *>&1 | Out-File -FilePath $global:LogPath -Append -Encoding UTF8 } # 0 = Разрешает любым программам (Afterburner/HWiNFO) читать датчики видеокарты напрямую, не нагружая процессор
}

# Отключение скрытых шпионских задач и авто-обновлений NVIDIA в Планировщике
$NvTasks = @("NvTmRep", "NvTmMon", "NvProfileUpdaterDaily", "NvProfileUpdaterOnLogon")
foreach ($Task in $NvTasks) {
    Apply-Tweak "Отключение телеметрии NVIDIA в планировщике ($Task)" { Get-ScheduledTask -TaskName $Task -ErrorAction SilentlyContinue 2>> $env:SystemDrive\EastricaTools\Eastrica_ErrorTrace.log | Disable-ScheduledTask | Out-Null } # Мгновенно отключаем телеметрию (Telemetry Monitor/Reporter)
}

# Оптимизация иконки NVIDIA в трее (Снижение нагрузки на Проводник)
$NvGlobalTweak = "HKLM:\SOFTWARE\NVIDIA Corporation\Global\NVTweak"
if (!(Test-Path $NvGlobalTweak)) { Apply-Tweak "Создание раздела Global NVTweak" { New-Item $NvGlobalTweak -Force *>&1 | Out-File -FilePath $global:LogPath -Append -Encoding UTF8 } }
Apply-Tweak "Отключение современного интерфейса автозагрузки панели NVIDIA" { Set-ItemProperty -Path $NvGlobalTweak -Name "NvCplExposeWin80" -Value 0 -Type DWord -Force *>&1 | Out-File -FilePath $global:LogPath -Append -Encoding UTF8 } # 0 = Отключает современный интерфейс автозагрузки панели
Apply-Tweak "Отключение фонового поиска телевизоров NVIDIA" { Set-ItemProperty -Path $NvGlobalTweak -Name "NvCplTvLocaleAutoDetect" -Value 0 -Type DWord -Force *>&1 | Out-File -FilePath $global:LogPath -Append -Encoding UTF8 } # 0 = Отключает фоновый поиск телевизоров
Apply-Tweak "Отключение I2C опроса монитора (Устранение статтеров)" { Set-ItemProperty -Path $NvGlobalTweak -Name "RMDisableI2cReading" -Value 1 -Type DWord -Force *>&1 | Out-File -FilePath $global:LogPath -Append -Encoding UTF8 } # Фикс фризов от опроса мониторов (DDC/CI I2C Polling)
Apply-Tweak "Отображение иконки NVIDIA в трее" { Set-ItemProperty -Path $NvGlobalTweak -Name "NoTrayIcon" -Value 0 -Type DWord -Force *>&1 | Out-File -FilePath $global:LogPath -Append -Encoding UTF8 } # 0 = Показываем иконку (пользователям это обычно нужно)

# Отключение индикатора DLSS (Убирает водяной знак в углу экрана в играх с DLSS)
