# 2. Аппаратная блокировка исполняемых файлов телеметрии Windows (Outbound Application Blocking)
Apply-Tweak "Блокировка выхода в сеть системным процессам телеметрии" {
    $TelemetryExecutables = @(
        @{ Name = "Eastrica_Block_App_CompatTelRunner";  Path = "$env:SystemRoot\System32\CompatTelRunner.exe";  Desc = "Блокировка телеметрии Microsoft Compatibility Appraiser" },
        @{ Name = "Eastrica_Block_App_DeviceCensus";     Path = "$env:SystemRoot\System32\DeviceCensus.exe";     Desc = "Блокировка сбора данных об оборудовании Device Census" },
        @{ Name = "Eastrica_Block_App_WerFault";         Path = "$env:SystemRoot\System32\WerFault.exe";         Desc = "Блокировка отправки отчетов об ошибках WerFault" },
        @{ Name = "Eastrica_Block_App_WerFaultSecure";   Path = "$env:SystemRoot\System32\WerFaultSecure.exe";   Desc = "Блокировка защищенного отчета об ошибках WerFaultSecure" },
        @{ Name = "Eastrica_Block_App_WerMgr";           Path = "$env:SystemRoot\System32\wermgr.exe";           Desc = "Блокировка диспетчера отчетов об ошибках Windows Error Reporting" },
        @{ Name = "Eastrica_Block_App_SIHClient";        Path = "$env:SystemRoot\System32\SIHClient.exe";        Desc = "Блокировка сетевой активности Server-Initiated Healing Client" },
        @{ Name = "Eastrica_Block_App_SmartScreen";      Path = "$env:SystemRoot\System32\smartscreen.exe";      Desc = "Блокировка передачи хэшей запускаемых программ в SmartScreen" },
        @{ Name = "Eastrica_Block_App_GameBarFTServer";  Path = "$env:SystemRoot\System32\GameBarFTServer.exe";  Desc = "Блокировка сетевой телеметрии GameBar FT Server" },
        @{ Name = "Eastrica_Block_App_BcastDVR";         Path = "$env:SystemRoot\System32\bcastdvr.exe";         Desc = "Блокировка сетевой активности фонового рекордера Game DVR" },
        @{ Name = "Eastrica_Block_App_DiagTrackRunner";  Path = "$env:SystemRoot\System32\Dism\DismHost.exe";    Desc = "Блокировка сетевой активности автономного хоста диагностики DISM" }
    )

    foreach ($app in $TelemetryExecutables) {
        Remove-NetFirewallRule -DisplayName $app.Name -ErrorAction SilentlyContinue | Out-Null
        if (Test-Path -LiteralPath $app.Path) {
            New-NetFirewallRule -DisplayName $app.Name `
