                                -Enabled True `
                                -ErrorAction SilentlyContinue | Out-Null
        }
    }
}

# ==============================================================================
# Утилита тумблера сетевой блокировки для .EXE файлов (с динамическим текстом)
# ==============================================================================
$ToggleFwScriptPath = "$OptimizerDir\EastricaToggleFirewall.ps1"
$ToggleFwScriptCode = @'
param([string]$TargetApp = "")

if (!([Security.Principal.WindowsPrincipal][Security.Principal.WindowsIdentity]::GetCurrent()).IsInRole([Security.Principal.WindowsBuiltInRole] "Administrator")) {
    # Передача через массив аргументов гарантирует, что пути с пробелами не сломаются
    $ElevateArgs = @("-NoProfile", "-ExecutionPolicy", "Bypass", "-WindowStyle", "Hidden", "-File", "`"$PSCommandPath`"", "`"$TargetApp`"")
    Start-Process powershell.exe -ArgumentList $ElevateArgs -Verb RunAs
    Exit
}

$TargetApp = $TargetApp.Trim('"', ' ')
if (-not (Test-Path -LiteralPath $TargetApp)) { Exit }

$FileName = [System.IO.Path]::GetFileName($TargetApp)
$wshell = New-Object -ComObject Wscript.Shell

$global:IsRU = ((Get-UICulture).TwoLetterISOLanguageName -eq "ru")
function L ([string]$Ru, [string]$En) { if ($global:IsRU) { return $Ru } else { return $En } }

# Путь к зарегистрированному пункту контекстного меню в реестре
$MenuKey = "Registry::HKEY_CLASSES_ROOT\exefile\shell\EastricaToggleFirewall"

# Генерируем уникальное детерминированное имя правила на основе полного пути к файлу
$PathBytes = [System.Text.Encoding]::UTF8.GetBytes($TargetApp.ToLowerInvariant())
$Hasher = [System.Security.Cryptography.MD5]::Create()
$Hash = [BitConverter]::ToString($Hasher.ComputeHash($PathBytes)) -replace '-'
$RuleName = "Eastrica_Block_App_" + $Hash.Substring(0, 12)

# Проверяем, заблокировано ли приложение в данный момент
$ExistingRules = Get-NetFirewallRule -Name $RuleName -ErrorAction SilentlyContinue

if ($ExistingRules) {
    # =========================================================================
    # СОСТОЯНИЕ: БЫЛО ЗАБЛОКИРОВАНО -> РАЗБЛОКИРУЕМ
    # =========================================================================
    Remove-NetFirewallRule -Name "$RuleName", "${RuleName}_In" -ErrorAction SilentlyContinue | Out-Null

    $msg = L "Сетевой доступ РАЗБЛОКИРОВАН!`n`nФайл: $FileName`nИсходящий и входящий трафик полностью открыт." "Network access ALLOWED!`n`nFile: $FileName`nInbound and outbound traffic is fully restored."
    $wshell.Popup($msg, 4, (L "Брандмауэр Windows" "Windows Firewall"), 262208) | Out-Null
} else {
    # =========================================================================
    # СОСТОЯНИЕ: НЕ БЫЛО ЗАБЛОКИРОВАНО -> БЛОКИРУЕМ
    # =========================================================================
    New-NetFirewallRule -Name $RuleName `
                        -DisplayName "Eastrica_UserBlock_$FileName" `
                        -Description "Блокировка доступа в сеть в 1 клик через Eastrica Optimizer" `
                        -Direction Outbound `
                        -Program $TargetApp `
                        -Action Block `
                        -Profile Any `
                        -Enabled True `
                        -ErrorAction Stop | Out-Null

    New-NetFirewallRule -Name "${RuleName}_In" `
                        -DisplayName "Eastrica_UserBlock_${FileName}_In" `
                        -Description "Блокировка входящего трафика в 1 клик через Eastrica Optimizer" `
                        -Direction Inbound `
                        -Program $TargetApp `
                        -Action Block `
                        -Profile Any `
                        -Enabled True `
                        -ErrorAction Stop | Out-Null

    $msg = L "Сетевой доступ ЗАБЛОКИРОВАН!`n`nФайл: $FileName`nИсходящий и входящий трафик полностью перекрыт." "Network access BLOCKED!`n`nFile: $FileName`nOutbound and inbound traffic is completely blocked."
    $wshell.Popup($msg, 4, (L "Брандмауэр Windows" "Windows Firewall"), 262192) | Out-Null
}
'@

Apply-Tweak "Создание скрипта тумблера Брандмауэра для .EXE" { 
    Set-Content -Path $ToggleFwScriptPath -Value $ToggleFwScriptCode -Encoding UTF8 -Force *>&1 | Out-File -FilePath $global:LogPath -Append -Encoding UTF8 
}

