    # 1 = Принудительное включение режима Memory Saver / High Efficiency Mode на уровне ядра Chromium
    Apply-Tweak "Включение Memory Saver по умолчанию ($B)" { Set-ItemProperty -Path $B -Name "HighEfficiencyModeEnabled" -Value 1 -Type DWord -Force *>&1 | Out-File -FilePath $global:LogPath -Append -Encoding UTF8 }
    
    # 2 = Агрессивный сброс памяти неактивных вкладок (выгружает страницу из ОЗУ сразу после ухода с неё)
