    # 0 = Отключение перехвата медиа-клавиш клавиатуры (Устраняет DPC-фризы при смене треков во время игры)
    Apply-Tweak "Отключение перехвата медиа-клавиш в браузере ($B)" { Set-ItemProperty -Path $B -Name "HardwareMediaKeyHandlingEnabled" -Value 0 -Type DWord -Force *>&1 | Out-File -FilePath $global:LogPath -Append -Encoding UTF8 }
    
    # 0 = Отключение встроенного сканера безопасности Chrome Cleanup (Убирает периодический опрос накопителя C:)
    Apply-Tweak "Отключение встроенного антивируса Chrome ($B)" { Set-ItemProperty -Path $B -Name "ChromeCleanupEnabled" -Value 0 -Type DWord -Force *>&1 | Out-File -FilePath $global:LogPath -Append -Encoding UTF8 }
    
    # 0 = Отключение отправки телеметрии антивирусного сканера в Google
