    Apply-Tweak "Отключение сетевого узла IPFS в Brave" { Set-ItemProperty -Path $BravePolicyPath -Name "IPFSEnabled" -Value 0 -Type DWord -Force *>&1 | Out-File -FilePath $global:LogPath -Append -Encoding UTF8 }
    
    # 1 = Отключение службы вознаграждений Brave Rewards (Останавливает отправку телеметрии)
    Apply-Tweak "Отключение фоновой службы Brave Rewards" { Set-ItemProperty -Path $BravePolicyPath -Name "BraveRewardsDisabled" -Value 1 -Type DWord -Force *>&1 | Out-File -FilePath $global:LogPath -Append -Encoding UTF8 }
    
    # 0 = Запрет интеграции встроенного ИИ-помощника Leo (Устраняет фоновый процесс парсинга страниц)
    Apply-Tweak "Отключение фонового ИИ-помощника Leo в Brave" { Set-ItemProperty -Path $BravePolicyPath -Name "BraveAIChatEnabled" -Value 0 -Type DWord -Force *>&1 | Out-File -FilePath $global:LogPath -Append -Encoding UTF8 }
    
    # 1 = Отключение службы Brave VPN (Убирает сетевой адаптер-заглушку)
    Apply-Tweak "Отключение встроенного VPN в Brave" { Set-ItemProperty -Path $BravePolicyPath -Name "BraveVPNDisabled" -Value 1 -Type DWord -Force *>&1 | Out-File -FilePath $global:LogPath -Append -Encoding UTF8 }
    
    # 1 = Запрет фонового запуска анонимных вкладок Tor (Устраняет фоновый процесс tor.exe)
    Apply-Tweak "Отключение фонового демона Tor в Brave" { Set-ItemProperty -Path $BravePolicyPath -Name "TorDisabled" -Value 1 -Type DWord -Force *>&1 | Out-File -FilePath $global:LogPath -Append -Encoding UTF8 }
}

# Настройка усыпления вкладок для Microsoft Edge (Sleeping Tabs)
$EdgePolicyPath = "HKLM:\SOFTWARE\Policies\Microsoft\Edge"
if (Test-Path $EdgePolicyPath) {
    # 1 = Принудительное включение механизма заморозки неактивных вкладок Sleeping Tabs
    Apply-Tweak "Включение спящего режима вкладок в Edge" { Set-ItemProperty -Path $EdgePolicyPath -Name "SleepingTabsEnabled" -Value 1 -Type DWord -Force *>&1 | Out-File -FilePath $global:LogPath -Append -Encoding UTF8 }
    
    # 60 = Перевод вкладки в глубокий сон уже через 60 секунд неактивности (по умолчанию 2 часа)
    Apply-Tweak "Таймаут усыпления вкладок Edge (1 минута)" { Set-ItemProperty -Path $EdgePolicyPath -Name "SleepingTabsTimeout" -Value 60 -Type DWord -Force *>&1 | Out-File -FilePath $global:LogPath -Append -Encoding UTF8 }
