// ==============================================================================
user_pref("layers.acceleration.force-enabled", true); // Принудительное включение аппаратного ускорения слоев
user_pref("gfx.webrender.all", true);                  // Включение современного графического движка WebRender для всех элементов
user_pref("gfx.webrender.enabled", true);              // Активация конвейера WebRender
user_pref("gfx.webrender.force-legacy-layers", false); // Запрет отката на медленные программные слои рендеринга
user_pref("gfx.direct2d.disabled", false);             // Разрешение использования Direct2D для шрифтов и 2D-графики

