user_pref("gfx.webrender.compositor.force-enabled", true); // Форсирование композитора видеокарты
user_pref("layers.gpu-process.enabled", true);         // Изоляция графики в отдельный процесс видеокарты
user_pref("layers.gpu-process.force-enabled", true);   // Принудительный запуск выделенного процесса GPU
user_pref("gfx.webrender.precache-shaders", true);     // Предварительная компиляция шейдеров интерфейса (убирает статтеры скролла)
