// ==============================================================================
// 2 = Хранить в ОЗУ не более 2 страниц истории для кнопки "Назад" (вместо стандартных 8, экономит до 1.5 ГБ ОЗУ)
user_pref("browser.sessionhistory.max_total_viewers", 2);
// 15 = Лимит количества записей в истории текущей сессии на вкладку (по умолчанию 50)
user_pref("browser.sessionhistory.max_entries", 15);
// true = Агрессивная автоматическая выгрузка неактивных вкладок из ОЗУ при нехватке свободной памяти
user_pref("browser.tabs.unloadOnLowMemory", true);
// 524288 = Фиксированный лимит кэша оперативной памяти в 512 МБ (по умолчанию -1, что раздувает кэш бесконечно)
