user_pref("network.http.max-persistent-connections-per-server", 16); // Максимум постоянных соединений на один сервер
user_pref("network.http.pacing.requests.enabled", false); // Отключение искусственных пауз между сетевыми пакетами
user_pref("network.dns.disablePrefetch", true);         // Запрет фонового предзапроса DNS-адресов со страниц в простое
user_pref("network.dns.disablePrefetchFromHTTPS", true); // Запрет DNS-префетчинга по защищенному протоколу HTTPS
user_pref("network.prefetch-next", false);              // Запрет фоновой предзагрузки страниц по ссылкам, на которые вы не нажимали
user_pref("network.http.speculative-parallel-limit", 0); // Обнуление лимита упреждающих параллельных подключений

// ==============================================================================
// 7. Жесткое отключение фоновой телеметрии Firefox
// ==============================================================================
user_pref("datareporting.healthreport.uploadEnabled", false); // Запрет отправки отчетов о здоровье браузера
user_pref("datareporting.policy.dataSubmissionEnabled", false); // Запрет фоновой передачи пользовательских данных
user_pref("toolkit.telemetry.enabled", false);                 // Полное отключение подсистемы телеметрии Toolkit
user_pref("toolkit.telemetry.unified", false);                 // Отключение единого сборщика телеметрии
user_pref("toolkit.telemetry.server", "data:,");               // Обнуление адреса сервера отправки телеметрии
