Show-ProgressStep -StepNum 50 -TotalSteps 81 -Activity "Очистка и расширение кэша шейдеров..."
Write-Host "==============================================================================" -ForegroundColor DarkGray
Write-Host "РАЗДЕЛ 50: ОЧИСТКА И РАСШИРЕНИЕ КЭША ШЕЙДЕРОВ" -ForegroundColor Cyan
Write-Host "==============================================================================" -ForegroundColor DarkGray
Write-Host "[WARNING] При первом запуске любой игры после очистки кэша вы получите жуткие" -ForegroundColor DarkGray
Write-Host "фризы на 5-10 минут, пока шейдеры будут компилироваться заново. Это нормально." -ForegroundColor DarkGray

# Пути к папкам шейдеров разных драйверов (Включая RDNA 4 DX12)
$DXCache1 = "$env:LOCALAPPDATA\D3DSCache"
$DXCache2 = "$env:LOCALAPPDATA\NVIDIA\GLCache"
$DXCache3 = "$env:LOCALAPPDATA\AMD\DxCache"
$DXCache4 = "$env:LOCALAPPDATA\NVIDIA\DXCache"
$DXCache5 = "$env:LOCALAPPDATA\AMD\DxcCache"
$DXCache6 = "$env:LOCALAPPDATA\AMD\OglCache"

# Вспомогательная функция безопасной очистки кэша шейдеров без прерывания на заблокированных файлах DWM
function Clear-ShaderFolder-Safe ([string]$FolderPath) {
    if (Test-Path -LiteralPath $FolderPath) {
        Get-ChildItem -LiteralPath $FolderPath -Recurse -Force -ErrorAction SilentlyContinue | ForEach-Object {
            if (-not $_.PSIsContainer) {
                try { [System.IO.File]::Delete($_.FullName) } catch {}
            }
        }
        Get-ChildItem -LiteralPath $FolderPath -Recurse -Directory -Force -ErrorAction SilentlyContinue | 
            Sort-Object -Property FullName -Descending | 
            ForEach-Object { try { [System.IO.Directory]::Delete($_.FullName) } catch {} }
    }
}

# Физическое удаление старых/битых файлов шейдеров (заблокированные системой .nvph файлы аккуратно пропускаются)
Apply-Tweak "Удаление старого кэша D3DSCache" { Clear-ShaderFolder-Safe $DXCache1 }
Apply-Tweak "Удаление старого кэша NVIDIA GLCache" { Clear-ShaderFolder-Safe $DXCache2 }
Apply-Tweak "Удаление старого кэша AMD DxCache (DX11)" { Clear-ShaderFolder-Safe $DXCache3 }
Apply-Tweak "Удаление старого кэша NVIDIA DXCache" { Clear-ShaderFolder-Safe $DXCache4 }
Apply-Tweak "Удаление современного кэша AMD DxcCache (DX12/RDNA)" { Clear-ShaderFolder-Safe $DXCache5 }
Apply-Tweak "Удаление кэша AMD OglCache (OpenGL)" { Clear-ShaderFolder-Safe $DXCache6 }

# Глобальное системное расширение кэша шейдеров DirectX (Для всех видеокарт)
$DxGraphics = "HKLM:\SOFTWARE\Policies\Microsoft\Windows\DirectX"
if (!(Test-Path $DxGraphics)) { Apply-Tweak "Создание раздела DirectX Policy" { New-Item -Path $DxGraphics -Force *>&1 | Out-File -FilePath $global:LogPath -Append -Encoding UTF8 } }
Apply-Tweak "Включение аппаратного кэша DxgkShaderCache" { Set-ItemProperty -Path $DxGraphics -Name "EnableDxgkShaderCache" -Value 1 -Type DWord -Force *>&1 | Out-File -FilePath $global:LogPath -Append -Encoding UTF8 } # 1 = Включаем аппаратный кэш графического ядра ОС
Apply-Tweak "Снятие лимита размера кэша шейдеров" { Remove-ItemProperty -Path $DxGraphics -Name "ShaderCacheLimit" *>&1 | Out-File -FilePath $global:LogPath -Append -Encoding UTF8 }

# ==============================================================================
# Утилита ручной очистки кэша шейдеров (сохранение для запуска при смене драйвера)
# ==============================================================================
$ShaderCleanerPath = "$BaseDir\Scripts\EastricaShaderCleaner.ps1"
$ShaderCleanerCode = @'
if (!([Security.Principal.WindowsPrincipal][Security.Principal.WindowsIdentity]::GetCurrent()).IsInRole([Security.Principal.WindowsBuiltInRole] "Administrator")) {
    Start-Process powershell.exe -ArgumentList "-NoProfile -ExecutionPolicy Bypass -WindowStyle Hidden -File `"$PSCommandPath`"" -Verb RunAs
    Exit
}
# Скрипт безопасной ручной очистки поврежденного кэша шейдеров
$Paths = @(
    "$env:LOCALAPPDATA\D3DSCache\*",
    "$env:LOCALAPPDATA\NVIDIA\GLCache\*",
    "$env:LOCALAPPDATA\AMD\DxCache\*",
    "$env:LOCALAPPDATA\AMD\DxcCache\*",
    "$env:LOCALAPPDATA\AMD\OglCache\*",
    "$env:LOCALAPPDATA\NVIDIA\DXCache\*",
    "$env:LOCALAPPDATA\NVIDIA\ComputeCache\*"
)
foreach ($P in $Paths) {
    Remove-Item -Path $P -Recurse -Force 2>> $env:SystemDrive\EastricaTools\Eastrica_ErrorTrace.log
}
Write-Host "Кэш шейдеров успешно очищен." -ForegroundColor Green
'@
Apply-Tweak "Сохранение утилиты очистки шейдеров ($ShaderCleanerPath)" { 
    Set-Content -Path $ShaderCleanerPath -Value $ShaderCleanerCode -Encoding UTF8 -Force *>&1 | Out-File -FilePath $global:LogPath -Append -Encoding UTF8 
}

# Регистрируем задачу БЕЗ триггера запуска (только для ручного вызова или вызова по кнопке)
$CleanAction = New-ScheduledTaskAction -Execute "powershell.exe" -Argument "-WindowStyle Hidden -NoProfile -ExecutionPolicy Bypass -File `"$ShaderCleanerPath`""
$CleanSettings = New-ScheduledTaskSettingsSet -AllowStartIfOnBatteries -DontStopIfGoingOnBatteries -Hidden -StartWhenAvailable
$CleanPrincipal = New-ScheduledTaskPrincipal -UserId ([System.Security.Principal.WindowsIdentity]::GetCurrent().Name) -LogonType Interactive -RunLevel Highest

Apply-Tweak "Регистрация задачи ручной очистки шейдеров (По требованию)" { 
    Register-ScheduledTask -TaskName "Eastrica_ManualShaderCleaner" -Action $CleanAction -Settings $CleanSettings -Principal $CleanPrincipal -Force | Out-Null 
}

Write-Host ""
# ==============================================================================
# Раздел 51: Службы поиска, печати, ИИ-агентов и синхронизации
# ==============================================================================
Show-ProgressStep -StepNum 51 -TotalSteps 81 -Activity "Остановка служб поиска, печати и синхронизации..."
Write-Host "==============================================================================" -ForegroundColor DarkGray
Write-Host "РАЗДЕЛ 51: СЛУЖБЫ ПОИСКА, ПЕЧАТИ, ИИ-АГЕНТОВ И СИНХРОНИЗАЦИИ" -ForegroundColor Cyan
Write-Host "==============================================================================" -ForegroundColor DarkGray

if ($global:OptServices) {
    Apply-Tweak "Остановка службы Windows Search" { Stop-Service "WSearch" -Force *>&1 | Out-File -FilePath $global:LogPath -Append -Encoding UTF8 }
    Apply-Tweak "Отключение службы Windows Search" { Set-Service "WSearch" -StartupType Disabled *>&1 | Out-File -FilePath $global:LogPath -Append -Encoding UTF8 }
    
    # Службу Spooler останавливаем, но оставляем в режиме Manual, чтобы сохранялась возможность печати в PDF
    Apply-Tweak "Остановка диспетчера печати (Spooler)" { Stop-Service "Spooler" -Force -ErrorAction SilentlyContinue *>&1 | Out-File -FilePath $global:LogPath -Append -Encoding UTF8 }
    Apply-Tweak "Перевод диспетчера печати в режим Manual (Сохранение функции Print to PDF)" { 
        Set-Service "Spooler" -StartupType Manual *>&1 | Out-File -FilePath $global:LogPath -Append -Encoding UTF8 
    }
} else {
    Apply-Tweak "Включение службы Windows Search" { Set-Service "WSearch" -StartupType Automatic *>&1 | Out-File -FilePath $global:LogPath -Append -Encoding UTF8 } # Оставляем Поиск
    Apply-Tweak "Запуск службы Windows Search" { Start-Service "WSearch" *>&1 | Out-File -FilePath $global:LogPath -Append -Encoding UTF8 }
    Apply-Tweak "Включение диспетчера печати (Spooler)" { Set-Service "Spooler" -StartupType Automatic *>&1 | Out-File -FilePath $global:LogPath -Append -Encoding UTF8 } # Оставляем принтеры
    Apply-Tweak "Запуск диспетчера печати (Spooler)" { Start-Service "Spooler" *>&1 | Out-File -FilePath $global:LogPath -Append -Encoding UTF8 }
}

# Уничтожение Neural Compute Agents (Освобождение RAM от встроенного ИИ безопасности)
$AIServices = @("NcaSvc", "Amentm*", "webthreatdefusersvc*", "webthreatdefsvc")
foreach ($SvcPattern in $AIServices) {
    Get-Service -Name $SvcPattern -ErrorAction SilentlyContinue 2>> $env:SystemDrive\EastricaTools\Eastrica_ErrorTrace.log | ForEach-Object {
        $Svc = $_.Name
        Apply-Tweak "Остановка встроенного ИИ безопасности ($Svc)" { Stop-Service -Name $Svc -Force *>&1 | Out-File -FilePath $global:LogPath -Append -Encoding UTF8 } # Убиваем службы
        Apply-Tweak "Отключение автозапуска службы ИИ безопасности ($Svc)" { Set-Service -Name $Svc -StartupType Disabled *>&1 | Out-File -FilePath $global:LogPath -Append -Encoding UTF8 } # Отключаем их
        Apply-Tweak "Отключение службы ИИ безопасности в реестре ($Svc)" { Set-ItemProperty -Path "HKLM:\SYSTEM\CurrentControlSet\Services\$Svc" -Name "Start" -Value 4 -Type DWord -Force *>&1 | Out-File -FilePath $global:LogPath -Append -Encoding UTF8 } # Добиваем через реестр (4 = Disabled)
    }
}

# Разрешение интерфейсу Календаря отрисовываться в фоне (Для пользователя)
$BackgroundAppsPath = "HKCU:\Software\Microsoft\Windows\CurrentVersion\BackgroundAccessApplications"
if (!(Test-Path $BackgroundAppsPath)) { Apply-Tweak "Создание раздела BackgroundAccessApplications" { New-Item -Path $BackgroundAppsPath -Force *>&1 | Out-File -FilePath $global:LogPath -Append -Encoding UTF8 } }
Apply-Tweak "Разрешение фоновой работы UWP приложений (Календарь)" { Set-ItemProperty -Path $BackgroundAppsPath -Name "GlobalUserDisabled" -Value 0 -Type DWord -Force *>&1 | Out-File -FilePath $global:LogPath -Append -Encoding UTF8 } # 0 = Разрешить работу в фоне для пользователя
$BgAppsGlobal = "HKCU:\Software\Microsoft\Windows\CurrentVersion\BackgroundAccessApplications"
if (!(Test-Path $BgAppsGlobal)) { Apply-Tweak "Создание раздела BackgroundAppsGlobal" { New-Item -Path $BgAppsGlobal -Force *>&1 | Out-File -FilePath $global:LogPath -Append -Encoding UTF8 } }
Apply-Tweak "Глобальное разрешение фоновых UWP приложений" { Set-ItemProperty -Path $BgAppsGlobal -Name "BackgroundAppGlobalToggle" -Value 1 -Type DWord -Force *>&1 | Out-File -FilePath $global:LogPath -Append -Encoding UTF8 } # 1 = Глобально разрешить UWP приложения

# Уничтожение CDPUserSvc (служба платформы подключенных устройств)
# Главный виновник микро-статтеров раз в 5-10 минут. Она пингует сеть в поисках ваших смартфонов по Bluetooth/Wi-Fi.
Apply-Tweak "Отключение службы CDPSvc в реестре" { Set-ItemProperty -Path "HKLM:\SYSTEM\CurrentControlSet\Services\CDPSvc" -Name "Start" -Value 4 -Type DWord -Force *>&1 | Out-File -FilePath $global:LogPath -Append -Encoding UTF8 } # 4 = Disabled
Apply-Tweak "Отключение службы CDPUserSvc в реестре" { Set-ItemProperty -Path "HKLM:\SYSTEM\CurrentControlSet\Services\CDPUserSvc" -Name "Start" -Value 4 -Type DWord -Force *>&1 | Out-File -FilePath $global:LogPath -Append -Encoding UTF8 } # 4 = Disabled
# Убиваем динамические пользовательские дубликаты (CDPUserSvc_xxxx)
Get-ChildItem -Path "HKLM:\SYSTEM\CurrentControlSet\Services" 2>> $env:SystemDrive\EastricaTools\Eastrica_ErrorTrace.log | Where-Object { $_.PSChildName -match "^CDPUserSvc" } | ForEach-Object {
    Apply-Tweak "Отключение динамического дубликата CDPUserSvc ($($_.PSChildName))" { Set-ItemProperty -Path $_.PSPath -Name "Start" -Value 4 -Type DWord -Force *>&1 | Out-File -FilePath $global:LogPath -Append -Encoding UTF8 } # 4 = Disabled для дубликатов
}

# Отключение фонового опроса TPM (Защита от fTPM Stutters - аппаратных лагов при работе модуля шифрования)
if (-not $global:OptAntiCheat) {
    if (Get-Service -Name "TpmTasks" -ErrorAction SilentlyContinue 2>> $env:SystemDrive\EastricaTools\Eastrica_ErrorTrace.log) {
        Apply-Tweak "Остановка службы TpmTasks" { Stop-Service -Name "TpmTasks" -Force *>&1 | Out-File -FilePath $global:LogPath -Append -Encoding UTF8 } # Останавливаем
        Apply-Tweak "Отключение службы TpmTasks" { Set-Service -Name "TpmTasks" -StartupType Disabled *>&1 | Out-File -FilePath $global:LogPath -Append -Encoding UTF8 } # Отключаем
    }
    Apply-Tweak "Отключение фонового опроса TPM в планировщике" { Get-ScheduledTask -TaskPath "\Microsoft\Windows\TPM\" 2>> $env:SystemDrive\EastricaTools\Eastrica_ErrorTrace.log | Disable-ScheduledTask | Out-Null } # Выключаем периодические задачи в планировщике
}

# Блокировка Cross-Device Resume (Анти-статтер)
$CrossDevice = "HKLM:\SOFTWARE\Policies\Microsoft\Windows\System"
if (!(Test-Path $CrossDevice)) { Apply-Tweak "Создание раздела Policies System" { New-Item $CrossDevice -Force *>&1 | Out-File -FilePath $global:LogPath -Append -Encoding UTF8 } }
Apply-Tweak "Запрет сканирования сети для синхронизации буфера обмена (CrossDevice)" { Set-ItemProperty -Path $CrossDevice -Name "EnableCrossDeviceResume" -Value 0 -Type DWord -Force *>&1 | Out-File -FilePath $global:LogPath -Append -Encoding UTF8 } # 0 = Запрещает Windows сканировать сеть/Bluetooth в поисках устройств для синхронизации буфера обмена

# Оптимизация Bluetooth аудио (Отключение Absolute Volume)
$BthAVRCP = "HKLM:\SYSTEM\CurrentControlSet\Services\BthA2dp\Parameters"
if (!(Test-Path $BthAVRCP)) { Apply-Tweak "Создание раздела BthA2dp Parameters" { New-Item $BthAVRCP -Force *>&1 | Out-File -FilePath $global:LogPath -Append -Encoding UTF8 } }
Apply-Tweak "Отключение Absolute Volume для Bluetooth аудио" { Set-ItemProperty -Path $BthAVRCP -Name "DisableAbsoluteVolume" -Value 1 -Type DWord -Force *>&1 | Out-File -FilePath $global:LogPath -Append -Encoding UTF8 } # 1 = Отключает синхронизацию громкости Windows и наушников (Сильно снижает задержку сигнала и решает проблемы тихого звука)

# Восстановление службы WpnUserService (Критично для работы панели Календаря и уведомлений)
Get-ChildItem -Path "HKLM:\SYSTEM\CurrentControlSet\Services" 2>> $env:SystemDrive\EastricaTools\Eastrica_ErrorTrace.log | Where-Object { $_.PSChildName -match "^WpnUserService" } | ForEach-Object {
    Apply-Tweak "Включение службы WpnUserService ($($_.PSChildName))" { Set-ItemProperty -Path $_.PSPath -Name "Start" -Value 2 -Type DWord -Force *>&1 | Out-File -FilePath $global:LogPath -Append -Encoding UTF8 } # 2 = Auto
}
Apply-Tweak "Включение службы WpnService" { Set-ItemProperty -Path "HKLM:\SYSTEM\CurrentControlSet\Services\WpnService" -Name "Start" -Value 2 -Type DWord -Force *>&1 | Out-File -FilePath $global:LogPath -Append -Encoding UTF8 } # 2 = Auto
Apply-Tweak "Запуск службы WpnService" { Start-Service -Name "WpnService" *>&1 | Out-File -FilePath $global:LogPath -Append -Encoding UTF8 } # Запускаем

Write-Host ""
# ==============================================================================
# Раздел 52: Полировка интерфейса Проводника и UX Tweaks (абсолютная плавность)
# ==============================================================================
Show-ProgressStep -StepNum 52 -TotalSteps 81 -Activity "Полировка интерфейса Проводника и UX Tweaks..."
Write-Host "==============================================================================" -ForegroundColor DarkGray
Write-Host "РАЗДЕЛ 52: ПОЛИРОВКА ИНТЕРФЕЙСА ПРОВОДНИКА И UX TWEAKS (АБСОЛЮТНАЯ ПЛАВНОСТЬ)" -ForegroundColor Cyan
Write-Host "==============================================================================" -ForegroundColor DarkGray

# Возврат классического (быстрого) контекстного меню ПКМ в Windows 11
$ClassicMenu = "HKCU:\Software\Classes\CLSID\{86ca1aa0-34aa-4e8b-a509-50c905bae2a2}\InprocServer32"
if (!(Test-Path $ClassicMenu)) { Apply-Tweak "Создание ключа для классического меню ПКМ" { New-Item -Path $ClassicMenu -Force *>&1 | Out-File -FilePath $global:LogPath -Append -Encoding UTF8 } }
Apply-Tweak "Активация классического меню ПКМ (Windows 11)" { Set-Item -Path $ClassicMenu -Value "" -Force *>&1 | Out-File -FilePath $global:LogPath -Append -Encoding UTF8 } # Пустое значение отключает новый XAML-дизайн меню

# Глобальные настройки Проводника (Explorer Advanced)
$AdvExplorer = "HKCU:\Software\Microsoft\Windows\CurrentVersion\Explorer\Advanced"
Apply-Tweak "Не запускать папки в отдельном процессе (SeparateProcess)" { Set-ItemProperty -Path $AdvExplorer -Name "SeparateProcess" -Value 0 -Type DWord -Force *>&1 | Out-File -FilePath $global:LogPath -Append -Encoding UTF8 } # Расходует в 2–3 раза больше оперативной памяти на каждое окно
Apply-Tweak "Отключение сворачивания окон при тряске (Aero Shake)" { Set-ItemProperty -Path $AdvExplorer -Name "DisallowShaking" -Value 1 -Type DWord -Force *>&1 | Out-File -FilePath $global:LogPath -Append -Encoding UTF8 } # 1 = Отключает Aero Shake (сворачивание окон при тряске мышью)
Apply-Tweak "Отключение подсказок прикрепления окон (SnapAssist)" { Set-ItemProperty -Path $AdvExplorer -Name "EnableSnapAssistFlyout" -Value 0 -Type DWord -Force *>&1 | Out-File -FilePath $global:LogPath -Append -Encoding UTF8 } # 0 = Отключение Snap Assist (подсказки при прикреплении окон к краям)
Apply-Tweak "Отображение расширений файлов (.exe, .txt)" { Set-ItemProperty -Path $AdvExplorer -Name "HideFileExt" -Value 0 -Type DWord -Force *>&1 | Out-File -FilePath $global:LogPath -Append -Encoding UTF8 } # 0 = Показывать расширения файлов (.exe, .txt). Обязательно для безопасности!
Apply-Tweak "Отключение рекламы OneDrive в Проводнике" { Set-ItemProperty -Path $AdvExplorer -Name "ShowSyncProviderNotifications" -Value 0 -Type DWord -Force *>&1 | Out-File -FilePath $global:LogPath -Append -Encoding UTF8 } # 0 = Отключить рекламу OneDrive в Проводнике
Apply-Tweak "Скрытие недавно использованных файлов" { Set-ItemProperty -Path $AdvExplorer -Name "ShowRecent" -Value 0 -Type DWord -Force *>&1 | Out-File -FilePath $global:LogPath -Append -Encoding UTF8 } # 0 = Отключить показ "Недавно использованных файлов" (Ускоряет открытие "Мой Компьютер")
Apply-Tweak "Скрытие часто используемых папок" { Set-ItemProperty -Path $AdvExplorer -Name "ShowFrequent" -Value 0 -Type DWord -Force *>&1 | Out-File -FilePath $global:LogPath -Append -Encoding UTF8 } # 0 = Отключить показ "Часто используемых папок"
Apply-Tweak "Скрытие значка Виджетов с панели задач" { Set-ItemProperty -Path $AdvExplorer -Name "TaskbarDa" -Value 0 -Type DWord -Force *>&1 | Out-File -FilePath $global:LogPath -Append -Encoding UTF8 } # 0 = Скрывает виджеты. 'Da' означает Desktop Analytics (Служба новостей и интересов).
Apply-Tweak "Открытие 'Этот компьютер' вместо 'Домашней страницы'" { Set-ItemProperty -Path $AdvExplorer -Name "LaunchTo" -Value 1 -Type DWord -Force *>&1 | Out-File -FilePath $global:LogPath -Append -Encoding UTF8 } # 1 = Отключение "Домашней страницы". Проводник сразу будет открывать диск C: и другие (Этот компьютер).
Apply-Tweak "Скрытие иконки Чата (Teams) с панели задач" { Set-ItemProperty -Path $AdvExplorer -Name "TaskbarMn" -Value 0 -Type DWord -Force *>&1 | Out-File -FilePath $global:LogPath -Append -Encoding UTF8 } # 0 = Скрывает Чат. 'Mn' означает Meet Now (Функция "Собрание" из Skype/Teams).
Apply-Tweak "Скрытие иконки Представления задач" { Set-ItemProperty -Path $AdvExplorer -Name "ShowTaskViewButton" -Value 0 -Type DWord -Force *>&1 | Out-File -FilePath $global:LogPath -Append -Encoding UTF8 } # 0 = Скрывает иконку "Представление задач"

# Мгновенный график копирования файлов (EnthusiastMode)
$OpStatusMgr = "HKCU:\Software\Microsoft\Windows\CurrentVersion\Explorer\OperationStatusManager"
if (!(Test-Path $OpStatusMgr)) { Apply-Tweak "Создание раздела OperationStatusManager" { New-Item -Path $OpStatusMgr -Force *>&1 | Out-File -FilePath $global:LogPath -Append -Encoding UTF8 } }
Apply-Tweak "Мгновенное отображение графика копирования (EnthusiastMode)" { Set-ItemProperty -Path $OpStatusMgr -Name "EnthusiastMode" -Value 1 -Type DWord -Force *>&1 | Out-File -FilePath $global:LogPath -Append -Encoding UTF8 } # 1 = Принудительно разворачивает окно копирования файлов с детальной статистикой и графиком скорости

# Увеличение кэша иконок Проводника
$IconCacheKey = "HKLM:\SOFTWARE\Microsoft\Windows\CurrentVersion\Explorer"
Apply-Tweak "Увеличение кэша иконок Проводника до 8 МБ" { Set-ItemProperty -Path $IconCacheKey -Name "Max Cached Icons" -Value "8192" -Type String -Force *>&1 | Out-File -FilePath $global:LogPath -Append -Encoding UTF8 } # 8192 КБ (8 МБ). Устраняет секундные зависания Проводника при открытии папок с играми/программами.

# Очистка поиска от мусора (Веб-результаты и Кортана)
$SearchKey = "HKCU:\Software\Microsoft\Windows\CurrentVersion\Search"
if (!(Test-Path $SearchKey)) { Apply-Tweak "Создание раздела Search" { New-Item -Path $SearchKey -Force *>&1 | Out-File -FilePath $global:LogPath -Append -Encoding UTF8 } }
Apply-Tweak "Запрет веб-поиска в меню Пуск (BingSearchEnabled)" { Set-ItemProperty -Path $SearchKey -Name "BingSearchEnabled" -Value 0 -Type DWord -Force *>&1 | Out-File -FilePath $global:LogPath -Append -Encoding UTF8 } # 0 = Запрет искать файлы в интернете (Мгновенный локальный поиск)
Apply-Tweak "Запрет сбора данных Кортаной (CortanaConsent)" { Set-ItemProperty -Path $SearchKey -Name "CortanaConsent" -Value 0 -Type DWord -Force *>&1 | Out-File -FilePath $global:LogPath -Append -Encoding UTF8 } # 0 = Запрет Кортане собирать данные

$Feeds = "HKLM:\SOFTWARE\Policies\Microsoft\Dsh"
if (!(Test-Path $Feeds)) { Apply-Tweak "Создание раздела политик Dsh" { New-Item -Path $Feeds -Force *>&1 | Out-File -FilePath $global:LogPath -Append -Encoding UTF8 } }
Apply-Tweak "Отключение виджета Новостей и Интересов (AllowNewsAndInterests)" { Set-ItemProperty -Path $Feeds -Name "AllowNewsAndInterests" -Value 0 -Type DWord -Force *>&1 | Out-File -FilePath $global:LogPath -Append -Encoding UTF8 } # 0 = Отключаем виджет Новостей на панели задач

# Восстановление современного интерфейса папок и вкладок Проводника в Windows 11
$BlockXAML = "HKLM:\SOFTWARE\Microsoft\Windows\CurrentVersion\Shell Extensions\Blocked"
if (Test-Path $BlockXAML) {
    Apply-Tweak "Разблокировка вкладок и интерфейса папок (Win 11)" { Remove-ItemProperty -Path $BlockXAML -Name "{e2bf9676-5f8f-435c-97eb-11607a5bedf7}" *>&1 | Out-File -FilePath $global:LogPath -Append -Encoding UTF8 }
}

# Полный сброс базы данных шаблонов папок (Устраняет баг, когда папка с видео открывается как музыка)
$BagsPath = "HKCU:\Software\Classes\Local Settings\Software\Microsoft\Windows\Shell\Bags"
$BagMRUPath = "HKCU:\Software\Classes\Local Settings\Software\Microsoft\Windows\Shell\BagMRU"
$AllFoldersPath = "HKCU:\Software\Classes\Local Settings\Software\Microsoft\Windows\Shell\Bags\AllFolders\Shell"

if (Test-Path $BagsPath) { Apply-Tweak "Сброс базы данных Bags Проводника" { Remove-Item -LiteralPath $BagsPath -Recurse -Force *>&1 | Out-File -FilePath $global:LogPath -Append -Encoding UTF8 } } # Очищаем старую базу
if (Test-Path $BagMRUPath) { Apply-Tweak "Сброс истории BagMRU Проводника" { Remove-Item -LiteralPath $BagMRUPath -Recurse -Force *>&1 | Out-File -FilePath $global:LogPath -Append -Encoding UTF8 } } # Очищаем историю

if (!(Test-Path $AllFoldersPath)) { Apply-Tweak "Создание раздела AllFolders Shell" { New-Item -Path $AllFoldersPath -Force | Out-Null } }
Apply-Tweak "Установка универсального быстрого шаблона для всех папок" { Set-ItemProperty -Path $AllFoldersPath -Name "FolderType" -Value "NotSpecified" -Type String -Force *>&1 | Out-File -FilePath $global:LogPath -Append -Encoding UTF8 } # Применяем универсальный быстрый шаблон ко всем папкам

# Блокировка платформы Виджетов на уровне групповых политик Windows
$WidgetsPolicy = "HKLM:\SOFTWARE\Policies\Microsoft\Dsh"
if (!(Test-Path $WidgetsPolicy)) { Apply-Tweak "Создание раздела политик Dsh (Widgets)" { New-Item -Path $WidgetsPolicy -Force *>&1 | Out-File -FilePath $global:LogPath -Append -Encoding UTF8 } }
Apply-Tweak "Блокировка платформы Виджетов (Глобально)" { Set-ItemProperty -Path $WidgetsPolicy -Name "AllowNewsAndInterests" -Value 0 -Type DWord -Force *>&1 | Out-File -FilePath $global:LogPath -Append -Encoding UTF8 } # 0 = Полностью отключает и выгружает процессы Widgets из автозагрузки и ОЗУ

# Отключение "Галереи" (Gallery) в Win 11
# Она фоново сканирует и индексирует картинки на дисках, дико нагружая процессор
$Gallery = "HKLM:\SOFTWARE\Microsoft\Windows\CurrentVersion\Explorer\Desktop\NameSpace_41040327\{e88865ea-0e1c-4e20-9aa6-edcd0212c87c}"
if (Test-Path $Gallery) { Apply-Tweak "Удаление узла 'Галерея' из навигационной панели" { Remove-Item -LiteralPath $Gallery -Recurse -Force *>&1 | Out-File -FilePath $global:LogPath -Append -Encoding UTF8 } } # Удаляем узел из навигационной панели

# Глобальное отключение советов, подсказок, приветствий и скрытой рекламы в Windows 11/10
$ContentDel = "HKCU:\Software\Microsoft\Windows\CurrentVersion\ContentDeliveryManager"
if (!(Test-Path $ContentDel)) { Apply-Tweak "Создание раздела ContentDeliveryManager" { New-Item $ContentDel -Force *>&1 | Out-File -FilePath $global:LogPath -Append -Encoding UTF8 } }

$AdvTipsTweaks = @{
    "ContentDeliveryAllowed" = 0           # Запрет доставки облачного контента
    "FeatureManagementEnabled" = 0         # Отключение ИИ-управления фичами
    "OemPreInstalledAppsEnabled" = 0       # Запрет установки OEM-приложений
    "PreInstalledAppsEnabled" = 0          # Запрет установки спонсорских приложений
    "PreInstalledAppsEverEnabled" = 0      # Флаг отключения
    "SubscribedContentEnabled" = 0         # Запрет подписок
    "SubscribedContent-338387Enabled" = 0
    "SubscribedContent-338388Enabled" = 0
    "SubscribedContent-338393Enabled" = 0
    "SubscribedContent-353698Enabled" = 0
    "SubContent-310093Enabled" = 0         # Отключить "Windows Welcome Experience" (приветствие после обновлений)
    "SubscribedContent-310093Enabled" = 0
    "SubscribedContent-338389Enabled" = 0  # Отключить "Советы, подсказки и рекомендации при использовании Windows"
    "SubscribedContent-353696Enabled" = 0  # Отключить подсказки в настройках
    "SubscribedContent-353694Enabled" = 0
    "SystemPaneSuggestionsEnabled" = 0     # Отключить рекомендации (рекламу) приложений в меню "Пуск"
    "SilentInstalledAppsEnabled" = 0       # Запретить Windows незаметно скачивать спонсорские игры (Candy Crush)
    "SoftLandingEnabled" = 0               # Отключить всплывающие окна помощи
}
foreach ($Tweak in $AdvTipsTweaks.GetEnumerator()) {
    Apply-Tweak "Отключение скрытой рекламы/советов: $($Tweak.Name)" { Set-ItemProperty -Path $ContentDel -Name $Tweak.Name -Value $Tweak.Value -Type DWord -Force *>&1 | Out-File -FilePath $global:LogPath -Append -Encoding UTF8 } # Применяем массив отключений
}

# Отключение вкладок браузера в Alt+Tab (Zero Alt-Tab Latency)
Apply-Tweak "Отключение вкладок браузера в Alt+Tab (MultiTaskingAltTabFilter)" { Set-ItemProperty -Path $AdvExplorer -Name "MultiTaskingAltTabFilter" -Value 3 -Type DWord -Force *>&1 | Out-File -FilePath $global:LogPath -Append -Encoding UTF8 } # 3 = Показывать только открытые окна (Без сотен вкладок браузера Edge, которые вешают систему при нажатии Alt+Tab)

# Блокировка экрана приветствия (Scoobe)
$UserEngage = "HKCU:\Software\Microsoft\Windows\CurrentVersion\UserProfileEngagement"
if (!(Test-Path $UserEngage)) { Apply-Tweak "Создание раздела UserProfileEngagement" { New-Item -Path $UserEngage -Force *>&1 | Out-File -FilePath $global:LogPath -Append -Encoding UTF8 } }
Apply-Tweak "Блокировка экрана приветствия (ScoobeSystemSettingEnabled)" { Set-ItemProperty -Path $UserEngage -Name "ScoobeSystemSettingEnabled" -Value 0 -Type DWord -Force *>&1 | Out-File -FilePath $global:LogPath -Append -Encoding UTF8 } # 0 = Запрещает ОС навязчиво просить настроить сервисы Microsoft

# Оптимизация Steam
$SteamReg = "HKCU:\Software\Valve\Steam"
if (Test-Path $SteamReg) {
    Apply-Tweak "Отключение сглаживания шрифтов DirectWrite (Steam)" { Set-ItemProperty -Path $SteamReg -Name "DWriteEnable" -Value 0 -Type DWord -Force *>&1 | Out-File -FilePath $global:LogPath -Append -Encoding UTF8 } # Отключает сглаживание шрифтов DirectWrite
    Apply-Tweak "Включение рендеринга Steam на GPU (CEF_DisableGPU)" { Set-ItemProperty -Path $SteamReg -Name "CEF_DisableGPU" -Value 0 -Type DWord -Force *>&1 | Out-File -FilePath $global:LogPath -Append -Encoding UTF8 } # 1 = ЖЕСТКО ОТКЛЮЧИТЬ рендеринг Steam на видеокарте (Только CPU)
    Apply-Tweak "Включение композитинга Steam (CEF_DisableGPUCompositing)" { Set-ItemProperty -Path $SteamReg -Name "CEF_DisableGPUCompositing" -Value 0 -Type DWord -Force *>&1 | Out-File -FilePath $global:LogPath -Append -Encoding UTF8 } # 1 = Отключить композитинг
    Apply-Tweak "Отключение плавной прокрутки в Steam" { Set-ItemProperty -Path $SteamReg -Name "SmoothScrollWebviews" -Value 0 -Type DWord -Force *>&1 | Out-File -FilePath $global:LogPath -Append -Encoding UTF8 } # Отключить плавную прокрутку
    Apply-Tweak "Глобальное включение аппаратного ускорения в Steam" { Set-ItemProperty -Path $SteamReg -Name "EnableHardwareAccel" -Value 1 -Type DWord -Force *>&1 | Out-File -FilePath $global:LogPath -Append -Encoding UTF8 } # Глобальный флаг включения ускорения
}

# Отключение аппаратного ускорения в Discord, Epic Games, Battle.net и Spotify (Освобождение VRAM и защита от рассинхронизации DWM)
# 1. DISCORD (JSON Config)
$DiscordSettings = "$env:APPDATA\discord\settings.json"
if (Test-Path $DiscordSettings) {
    try {
        $json = Get-Content $DiscordSettings -Raw -ErrorAction Stop | ConvertFrom-Json
        # Добавляем или перезаписываем параметр
        $json | Add-Member -MemberType NoteProperty -Name "hardwareAcceleration" -Value $true -Force
        $json | Add-Member -MemberType NoteProperty -Name "enableHardwareAcceleration" -Value $true -Force
        Apply-Tweak "Включение аппаратного ускорения в Discord" { $json | ConvertTo-Json -Depth 10 | Set-Content $DiscordSettings -Encoding UTF8 -Force }
    } catch { }
}

# 2. BATTLE.NET (JSON Config)
$BnetSettings = "$env:APPDATA\Battle.net\Battle.net.config"
if (Test-Path $BnetSettings) {
    try {
        $json = Get-Content $BnetSettings -Raw -ErrorAction Stop | ConvertFrom-Json
        if ($null -ne $json.Client) {
            $json.Client | Add-Member -MemberType NoteProperty -Name "HardwareAcceleration" -Value "true" -Force
            Apply-Tweak "Включение аппаратного ускорения в Battle.net" { $json | ConvertTo-Json -Depth 10 | Set-Content $BnetSettings -Encoding UTF8 -Force }
        }
    } catch { }
}

# 3. EPIC GAMES LAUNCHER (INI Config)
$EpicConfigDir = "$env:LOCALAPPDATA\EpicGamesLauncher\Saved\Config\Windows"
$EpicConfig = "$EpicConfigDir\GameUserSettings.ini"
if (Test-Path $EpicConfigDir) {
    try {
        if (-not (Test-Path $EpicConfig)) { New-Item -Path $EpicConfig -ItemType File -Force | Out-Null }
        $EpicContent = Get-Content $EpicConfig -Raw 2>> $env:SystemDrive\EastricaTools\Eastrica_ErrorTrace.log
        
        if ($null -eq $EpicContent -or $EpicContent -notmatch "DisableHardwareAcceleration") {
            $EpicTweak = "`r`n[Launcher]`r`nDisableHardwareAcceleration=False`r`n"
            Apply-Tweak "Включение аппаратного ускорения в Epic Games" { Add-Content -Path $EpicConfig -Value $EpicTweak -Encoding UTF8 -Force }
        }
    } catch { }
}

# 4. SPOTIFY (Prefs Config)
$SpotifyPrefs = "$env:APPDATA\Spotify\Prefs"
if (Test-Path $SpotifyPrefs) {
    try {
        $PrefsContent = Get-Content $SpotifyPrefs -Raw 2>> $env:SystemDrive\EastricaTools\Eastrica_ErrorTrace.log
        if ($null -ne $PrefsContent) {
            if ($PrefsContent -match "app.hardware-acceleration-enabled") {
                $PrefsContent = $PrefsContent -replace 'app\.hardware-acceleration-enabled=.*', 'app.hardware-acceleration-enabled=true'
            } else {
                $PrefsContent += "`r`napp.hardware-acceleration-enabled=true"
            }
            Apply-Tweak "Включение аппаратного ускорения в Spotify" { $PrefsContent.Trim() | Set-Content -Path $SpotifyPrefs -Encoding UTF8 -Force }
        }
    } catch { }
}

Write-Host ""
# ==============================================================================
# Раздел 53: Настройка UAC, безопасности и эксплойт-защиты (Exploit Protection)
# ==============================================================================
Show-ProgressStep -StepNum 53 -TotalSteps 81 -Activity "Применение настроек UAC, безопасности и защиты..."
Write-Host "==============================================================================" -ForegroundColor DarkGray
Write-Host "РАЗДЕЛ 53: НАСТРОЙКА UAC, БЕЗОПАСНОСТИ И ЭКСПЛОЙТ-ЗАЩИТЫ (EXPLOIT PROTECTION)" -ForegroundColor Cyan
Write-Host "==============================================================================" -ForegroundColor DarkGray

$UAC = "HKLM:\SOFTWARE\Microsoft\Windows\CurrentVersion\Policies\System" # Ветка политик системы

# EnableLUA=1 сохраняем в обоих случаях, чтобы не ломать UWP-приложения, Калькулятор и Microsoft Store
Apply-Tweak "Защита целостности UWP (EnableLUA=1)" { 
    Set-ItemProperty -Path $UAC -Name "EnableLUA" -Value 1 -Type DWord -Force *>&1 | Out-File -FilePath $global:LogPath -Append -Encoding UTF8 
}

# Строгая привязка параметров UAC к выбранному чекбоксу пользователя
if ($global:OptUAC) {
    Write-Host " ► Применение режима хардкорного отключения подсказок UAC..." -ForegroundColor Yellow
    Apply-Tweak "Выполнение команд от админа без запроса (ConsentPromptBehaviorAdmin = 0)" { 
        Set-ItemProperty -Path $UAC -Name "ConsentPromptBehaviorAdmin" -Value 0 -Type DWord -Force *>&1 | Out-File -FilePath $global:LogPath -Append -Encoding UTF8 
    }
    Apply-Tweak "Отключение затемнения экрана (PromptOnSecureDesktop = 0)" { 
        Set-ItemProperty -Path $UAC -Name "PromptOnSecureDesktop" -Value 0 -Type DWord -Force *>&1 | Out-File -FilePath $global:LogPath -Append -Encoding UTF8 
    }
    Apply-Tweak "Отключение виртуализации файлов UAC (VirtualStore)" { 
        Set-ItemProperty -Path $UAC -Name "EnableVirtualization" -Value 0 -Type DWord -Force *>&1 | Out-File -FilePath $global:LogPath -Append -Encoding UTF8 
    }
    Apply-Tweak "Удаление фильтра токена Администратора" { 
        Remove-ItemProperty -Path $UAC -Name "FilterAdministratorToken" -Force -ErrorAction SilentlyContinue *>&1 | Out-File -FilePath $global:LogPath -Append -Encoding UTF8 
    }
} else {
    Write-Host " ► Сохранение стандартных безопасных уведомлений UAC..." -ForegroundColor DarkGray
    Apply-Tweak "Восстановление стандартного запроса UAC (ConsentPromptBehaviorAdmin = 5)" { 
        Set-ItemProperty -Path $UAC -Name "ConsentPromptBehaviorAdmin" -Value 5 -Type DWord -Force *>&1 | Out-File -FilePath $global:LogPath -Append -Encoding UTF8 
    }
    Apply-Tweak "Включение затемнения рабочего стола при запросе UAC (PromptOnSecureDesktop = 1)" { 
        Set-ItemProperty -Path $UAC -Name "PromptOnSecureDesktop" -Value 1 -Type DWord -Force *>&1 | Out-File -FilePath $global:LogPath -Append -Encoding UTF8 
    }
    Apply-Tweak "Включение виртуализации файлов UAC (Защита старых программ)" { 
        Set-ItemProperty -Path $UAC -Name "EnableVirtualization" -Value 1 -Type DWord -Force *>&1 | Out-File -FilePath $global:LogPath -Append -Encoding UTF8 
    }
    Apply-Tweak "Разрешение UWP-приложений для встроенного Администратора" { 
        Set-ItemProperty -Path $UAC -Name "FilterAdministratorToken" -Value 1 -Type DWord -Force *>&1 | Out-File -FilePath $global:LogPath -Append -Encoding UTF8 
    }
}

if (-not $global:OptAntiCheat) {
    Apply-Tweak "Отключение Exploit Protection для DWM (dwm.exe)" { Set-ProcessMitigation -Name dwm.exe -Disable CFG, EmulateAtlThunks, BottomUp, HighEntropy, SEHOP, StrictHandle *>&1 | Out-File -FilePath $global:LogPath -Append -Encoding UTF8 }
    Apply-Tweak "Отключение Exploit Protection для Проводника (explorer.exe)" { Set-ProcessMitigation -Name explorer.exe -Disable CFG, EmulateAtlThunks, BottomUp, HighEntropy, SEHOP, StrictHandle *>&1 | Out-File -FilePath $global:LogPath -Append -Encoding UTF8 }
} else {
    Apply-Tweak "Включение Exploit Protection для DWM (dwm.exe)" { Set-ProcessMitigation -Name dwm.exe -Enable DEP, CFG *>&1 | Out-File -FilePath $global:LogPath -Append -Encoding UTF8 }
    Apply-Tweak "Включение Exploit Protection для Проводника (explorer.exe)" { Set-ProcessMitigation -Name explorer.exe -Enable DEP, CFG *>&1 | Out-File -FilePath $global:LogPath -Append -Encoding UTF8 }
}

$Explorer = "HKCU:\Software\Microsoft\Windows\CurrentVersion\Explorer"
Apply-Tweak "Отключение приписки 'Ярлык' при создании ярлыков" { Set-ItemProperty -Path $Explorer -Name "link" -Value ([byte[]](0x00,0x00,0x00,0x00)) -Type Binary -Force *>&1 | Out-File -FilePath $global:LogPath -Append -Encoding UTF8 }
Apply-Tweak "Отображение всех значков в системном трее" { Set-ItemProperty -Path $Explorer -Name "EnableAutoTray" -Value 0 -Type DWord -Force *>&1 | Out-File -FilePath $global:LogPath -Append -Encoding UTF8 }

$SudoPolicy = "HKLM:\SOFTWARE\Policies\Microsoft\Windows\Sudo"
if (!(Test-Path $SudoPolicy)) { Apply-Tweak "Создание раздела политик Sudo" { New-Item -Path $SudoPolicy -Force *>&1 | Out-File -FilePath $global:LogPath -Append -Encoding UTF8 } }
Apply-Tweak "Отключение логики перехвата Sudo в ядре" { Set-ItemProperty -Path $SudoPolicy -Name "EnableSudo" -Value 0 -Type DWord -Force *>&1 | Out-File -FilePath $global:LogPath -Append -Encoding UTF8 }

$SystemPolicy = "HKLM:\SOFTWARE\Microsoft\Windows\CurrentVersion\Policies\System"
if (!(Test-Path $SystemPolicy)) { Apply-Tweak "Создание раздела System Policies" { New-Item $SystemPolicy -Force *>&1 | Out-File -FilePath $global:LogPath -Append -Encoding UTF8 } }
Apply-Tweak "Отключение Быстрой смены пользователя (HideFastUserSwitching)" { Set-ItemProperty -Path $SystemPolicy -Name "HideFastUserSwitching" -Value 1 -Type DWord -Force *>&1 | Out-File -FilePath $global:LogPath -Append -Encoding UTF8 }

Write-Host ""
# ==============================================================================
# Раздел 54: Program Compatibility Assistant (Помощник совместимости)
# ==============================================================================
Show-ProgressStep -StepNum 54 -TotalSteps 81 -Activity "Program Compatibility Assistant (Помощник совместимости)..."
Write-Host "==============================================================================" -ForegroundColor DarkGray
Write-Host "РАЗДЕЛ 54: PROGRAM COMPATIBILITY ASSISTANT (ПОМОЩНИК СОВМЕСТИМОСТИ)" -ForegroundColor Cyan
Write-Host "==============================================================================" -ForegroundColor DarkGray
if (-not $global:OptAntiCheat) {
    Apply-Tweak "Остановка службы PcaSvc (Помощник совместимости)" { Stop-Service -Name "PcaSvc" *>&1 | Out-File -FilePath $global:LogPath -Append -Encoding UTF8 } # Останавливаем службу помощника совместимости
    Apply-Tweak "Отключение службы PcaSvc" { Set-Service -Name "PcaSvc" -StartupType Disabled *>&1 | Out-File -FilePath $global:LogPath -Append -Encoding UTF8 } # Отключаем автозапуск (Она грузит диск, пытаясь анализировать каждый запущенный .exe файл)
    $PcaKey = "HKLM:\SOFTWARE\Policies\Microsoft\Windows\AppCompat" # Политика совместимости
    if (!(Test-Path $PcaKey)) { Apply-Tweak "Создание раздела политик AppCompat" { New-Item -Path $PcaKey -Force *>&1 | Out-File -FilePath $global:LogPath -Append -Encoding UTF8 } }
    Apply-Tweak "Запрет работы PCA (DisablePCA)" { Set-ItemProperty -Path $PcaKey -Name "DisablePCA" -Value 1 -Type DWord -Force *>&1 | Out-File -FilePath $global:LogPath -Append -Encoding UTF8 } # 1 = Запрет работы PCA
    Apply-Tweak "Запрет движка AppCompat (DisableEngine)" { Set-ItemProperty -Path $PcaKey -Name "DisableEngine" -Value 1 -Type DWord -Force *>&1 | Out-File -FilePath $global:LogPath -Append -Encoding UTF8 } # 1 = Запрет движка AppCompat
} else {
    # Античиты требуют активного PCA для проверки цифровых подписей старых драйверов
    Apply-Tweak "Перевод PcaSvc в ручной запуск (Режим Античита)" { Set-Service -Name "PcaSvc" -StartupType Manual *>&1 | Out-File -FilePath $global:LogPath -Append -Encoding UTF8 } # Возвращаем в ручной режим
    Apply-Tweak "Запуск службы PcaSvc" { Start-Service -Name "PcaSvc" *>&1 | Out-File -FilePath $global:LogPath -Append -Encoding UTF8 }
    $PcaKey = "HKLM:\SOFTWARE\Policies\Microsoft\Windows\AppCompat"
    if (!(Test-Path $PcaKey)) { Apply-Tweak "Создание раздела политик AppCompat" { New-Item -Path $PcaKey -Force *>&1 | Out-File -FilePath $global:LogPath -Append -Encoding UTF8 } }
    Apply-Tweak "Включение работы PCA" { Set-ItemProperty -Path $PcaKey -Name "DisablePCA" -Value 0 -Type DWord -Force *>&1 | Out-File -FilePath $global:LogPath -Append -Encoding UTF8 } # 0 = Разрешаем
    Apply-Tweak "Включение движка AppCompat" { Set-ItemProperty -Path $PcaKey -Name "DisableEngine" -Value 0 -Type DWord -Force *>&1 | Out-File -FilePath $global:LogPath -Append -Encoding UTF8 } # 0 = Разрешаем
}

# Очистка кэша совместимости
Apply-Tweak "Очистка кэша совместимости (AppCompatCache)" { Remove-ItemProperty -Path "HKLM:\SYSTEM\CurrentControlSet\Control\Session Manager\AppCompatCache" -Name "AppCompatCache" *>&1 | Out-File -FilePath $global:LogPath -Append -Encoding UTF8 } # Удаляем закэшированные баги совместимости

