Show-ProgressStep -StepNum 55 -TotalSteps 81 -Activity "Очистка старых контекстных меню..."
Write-Host "==============================================================================" -ForegroundColor DarkGray
Write-Host "РАЗДЕЛ 55: ОЧИСТКА СТАРЫХ КОНТЕКСТНЫХ МЕНЮ (ЗАЩИТА ОТ ДУБЛИКАТОВ)" -ForegroundColor Cyan
Write-Host "==============================================================================" -ForegroundColor DarkGray

# 1. Удаление устаревших одиночных пунктов меню предыдущих версий (включая .EXE и .LNK)
$OldMenuKeys = @(
    "HKCR:\exefile\shell\EastricaVIPLaunch",
    "HKCR:\exefile\shell\TurboLaunch",
    "HKCR:\exefile\shell\EastricaBlockFirewall",
    "HKCR:\exefile\shell\EastricaAllowFirewall",
    "HKCR:\lnkfile\shell\EastricaVIPLaunch",
    "HKCR:\lnkfile\shell\TurboLaunch",
    "HKCR:\Directory\Background\shell\RestartExplorer",
    "HKCR:\Directory\Background\Shell\KillNotResponding",
    "HKCR:\Directory\Background\shell\EastricaClearJunk",
    "HKCR:\Directory\Background\Shell\PowerMenu",
    "HKCR:\Directory\Background\Shell\RebootMenu",
    "HKCR:\Directory\Background\shell\EastricaSteamLite",
    "HKCR:\Directory\Background\shell\EastricaAudioFix",
    "HKCR:\Directory\Background\shell\EastricaAIFlush"
)

foreach ($Key in $OldMenuKeys) {
    if (Test-Path -LiteralPath $Key) {
        Apply-Tweak "Удаление старого контекстного меню ($Key)" {
            Remove-Item -LiteralPath $Key -Recurse -Force 2>> $env:SystemDrive\EastricaTools\Eastrica_ErrorTrace.log 
        }
    }
}

# 2. Очистка подменю главного меню Eastrica Tools
$EastricaShell = "HKCR:\Directory\Background\shell\EastricaTools\shell"
$OldToolsSubMenus = @(
    "00_ThreadDirector", "00_AIFlush", "01_ClearJunk", "01b_FlushRam", "01c_ClearShaders",
    "01_CleanMenu", "01_SteamLite", "01_SteamCompact", "02_CleanMenu", "02_RestartExplorer",
    "02_SystemMenu", "03_KillNotResponding", "03_SystemMenu", "04_AudioFix", "04_ResetWindowsUpdate",
    "04b_ToggleMPO", "04c_RestoreMaxHz", "05_SteamLite", "06_PowerMenu", "07_RebootMenu", "08_AIFlush"
)

foreach ($Sub in $OldToolsSubMenus) {
    $SubPath = "$EastricaShell\$Sub"
    if (Test-Path -LiteralPath $SubPath) {
        Apply-Tweak "Очистка подменю Eastrica Tools ($Sub)" {
            Remove-Item -LiteralPath $SubPath -Recurse -Force 2>> $env:SystemDrive\EastricaTools\Eastrica_ErrorTrace.log 
        }
    }
}

# 3. Очистка подменю второго меню Eastrica Tools Extra (Защита от фантомных пунктов при смене режимов)
$EastricaExtraShell = "HKCR:\Directory\Background\shell\EastricaToolsExtra\shell"
