if (!(Test-Path $EastricaMenu)) { Apply-Tweak "Создание корня меню Eastrica Tools" { New-Item -Path $EastricaMenu -Force *>&1 | Out-File -FilePath $global:LogPath -Append -Encoding UTF8 } }
Apply-Tweak "Установка названия (MUIVerb) для Eastrica Tools" { Set-ItemProperty -Path $EastricaMenu -Name "MUIVerb" -Value "Eastrica Tools" -Force *>&1 | Out-File -FilePath $global:LogPath -Append -Encoding UTF8 }
Apply-Tweak "Установка иконки для Eastrica Tools" { Set-ItemProperty -Path $EastricaMenu -Name "Icon" -Value "imageres.dll,-114" -Force *>&1 | Out-File -FilePath $global:LogPath -Append -Encoding UTF8 }
Apply-Tweak "Установка позиции (Middle) для Eastrica Tools" { Set-ItemProperty -Path $EastricaMenu -Name "Position" -Value "Middle" -Force *>&1 | Out-File -FilePath $global:LogPath -Append -Encoding UTF8 }
