if (!(Test-Path $EastricaShell)) { Apply-Tweak "Создание подраздела Shell для Eastrica Tools" { New-Item -Path $EastricaShell -Force *>&1 | Out-File -FilePath $global:LogPath -Append -Encoding UTF8 } }

