$CleanMenu = "$EastricaShell\02_CleanMenu"
$CleanShell = "$CleanMenu\shell"
if (!(Test-Path $CleanMenu)) { Apply-Tweak "Создание раздела меню 'Очистка'" { New-Item -Path $CleanMenu -Force *>&1 | Out-File -FilePath $global:LogPath -Append -Encoding UTF8 } }
Apply-Tweak "Установка названия подменю 'Очистка'" { Set-ItemProperty -Path $CleanMenu -Name "MUIVerb" -Value (L "Очистка" "Cleanup") -Force *>&1 | Out-File -FilePath $global:LogPath -Append -Encoding UTF8 }
Apply-Tweak "Установка иконки подменю 'Очистка'" { Set-ItemProperty -Path $CleanMenu -Name "Icon" -Value "cleanmgr.exe,0" -Force *>&1 | Out-File -FilePath $global:LogPath -Append -Encoding UTF8 }
Apply-Tweak "Включение подкоманд для подменю 'Очистка'" { Set-ItemProperty -Path $CleanMenu -Name "SubCommands" -Value "" -Type String -Force *>&1 | Out-File -FilePath $global:LogPath -Append -Encoding UTF8 }
if (!(Test-Path $CleanShell)) { Apply-Tweak "Создание Shell для подменю 'Очистка'" { New-Item -Path $CleanShell -Force *>&1 | Out-File -FilePath $global:LogPath -Append -Encoding UTF8 } }

