if (!(Test-Path $SystemShell)) { Apply-Tweak "Создание Shell для подменю 'Система'" { New-Item -Path $SystemShell -Force | Out-Null } }

# ---------------------------------------------------------
# Пункт: Очистить мусор и кэши
# ---------------------------------------------------------
$MenuKey_Junk = "$CleanShell\02_ClearJunk"
if (!(Test-Path $MenuKey_Junk)) { Apply-Tweak "Создание кнопки ClearJunk" { New-Item -Path $MenuKey_Junk -Force | Out-Null } }
Apply-Tweak "Установка названия для ClearJunk" { Set-ItemProperty -Path $MenuKey_Junk -Name "MUIVerb" -Value (L "Очистить мусор и кэши" "Clean Junk and Caches") -Force *>&1 | Out-File -FilePath $global:LogPath -Append -Encoding UTF8 }
Apply-Tweak "Установка иконки для ClearJunk" { Set-ItemProperty -Path $MenuKey_Junk -Name "Icon" -Value "shell32.dll,32" -Force *>&1 | Out-File -FilePath $global:LogPath -Append -Encoding UTF8 }

Write-Host ""
# ==============================================================================
# Раздел 57: Код графической утилиты очистки (ClearJunk)
# ==============================================================================
Show-ProgressStep -StepNum 57 -TotalSteps 81 -Activity "Генерация графической утилиты очистки (ClearJunk)..."
Write-Host "==============================================================================" -ForegroundColor DarkGray
Write-Host "РАЗДЕЛ 57: КОД ГРАФИЧЕСКОЙ УТИЛИТЫ ОЧИСТКИ (CLEARJUNK)" -ForegroundColor Cyan
Write-Host "==============================================================================" -ForegroundColor DarkGray
# Переменная $ClearScript содержит полноценный PowerShell-скрипт с графическим интерфейсом WinForms.
# Позже мы сожмем его и поместим прямо в реестр, чтобы он работал без файлов на диске.
$ClearScript = @'
if (!([Security.Principal.WindowsPrincipal][Security.Principal.WindowsIdentity]::GetCurrent()).IsInRole([Security.Principal.WindowsBuiltInRole] "Administrator")) {
    Start-Process powershell.exe -ArgumentList "-NoProfile -ExecutionPolicy Bypass -WindowStyle Hidden -File `"$PSCommandPath`"" -Verb RunAs
    Exit
}
Add-Type -AssemblyName System.Windows.Forms # Подгружаем библиотеку для создания окон
Add-Type -AssemblyName System.Drawing # Подгружаем библиотеку для работы с графикой и размерами

$global:IsRU = ((Get-UICulture).TwoLetterISOLanguageName -eq "ru")
function L ([string]$Ru, [string]$En) { if ($global:IsRU) { return $Ru } else { return $En } }

$g = [System.Drawing.Graphics]::FromHwnd([IntPtr]::Zero)
$Scale = $g.DpiX / 96.0
$g.Dispose()

$form = New-Object System.Windows.Forms.Form -Property @{TopMost=$true} # Создаем главное окно утилиты
$form.Text = (L "Eastrica Ultimate Windows Optimizer - Очистка системы" "Eastrica Ultimate Windows Optimizer - System Cleanup") # Заголовок окна
$form.Size = New-Object System.Drawing.Size([int](480 * $Scale), [int](130 * $Scale)) # Размер окна
$form.StartPosition = "CenterScreen" # Появляться строго по центру экрана
$form.FormBorderStyle = "FixedDialog" # Запрет на изменение размера
$form.ControlBox = $false # Скрываем крестик (чтобы не закрыли до конца очистки)
$form.TopMost = $true # Поверх всех остальных окон
$form.BackColor = [System.Drawing.Color]::FromArgb(26, 26, 30) # Темный фон
$form.ForeColor = [System.Drawing.Color]::White # Белый текст

try {
    $DwmCode = @"
    using System;
    using System.Runtime.InteropServices;
    public class DWM {
        [DllImport("dwmapi.dll")]
        public static extern int DwmSetWindowAttribute(IntPtr hwnd, int attr, ref int attrValue, int attrSize);
    }
"@
    if (-not ("DWM" -as [type])) { Add-Type -TypeDefinition $DwmCode -ErrorAction SilentlyContinue }
    $darkMode = 1
    [DWM]::DwmSetWindowAttribute($form.Handle, 20, [ref]$darkMode, 4) | Out-Null
    [DWM]::DwmSetWindowAttribute($form.Handle, 19, [ref]$darkMode, 4) | Out-Null
} catch {}

$lbl = New-Object System.Windows.Forms.Label # Создаем текстовую метку для статуса
$lbl.AutoSize = $false # Фиксированный размер
$lbl.Size = New-Object System.Drawing.Size([int](450 * $Scale), [int](20 * $Scale)) # Ширина метки
$lbl.Location = New-Object System.Drawing.Point([int](10 * $Scale), [int](15 * $Scale)) # Отступы
$lbl.Font = New-Object System.Drawing.Font("Segoe UI", 10) # Шрифт
$lbl.Text = "Подготовка к очистке..." # Стартовый текст
$form.Controls.Add($lbl) # Добавляем текст в окно

$pb = New-Object System.Windows.Forms.ProgressBar # Создаем полосу загрузки (Прогресс-бар)
$pb.Location = New-Object System.Drawing.Point([int](10 * $Scale), [int](45 * $Scale)) # Отступы
$pb.Size = New-Object System.Drawing.Size([int](445 * $Scale), [int](25 * $Scale)) # Размер полосы
$pb.Style = "Continuous" # Плавный стиль заполнения
$form.Controls.Add($pb) # Добавляем полосу в окно

$btnOk = New-Object System.Windows.Forms.Button
$btnOk.Size = New-Object System.Drawing.Size([int](140 * $Scale), [int](35 * $Scale))
$btnOk.Location = New-Object System.Drawing.Point([int](165 * $Scale), [int](40 * $Scale)) # Центрируем кнопку
$btnOk.Font = New-Object System.Drawing.Font("Segoe UI", 10, [System.Drawing.FontStyle]::Bold)
$btnOk.BackColor = [System.Drawing.Color]::FromArgb(0, 120, 215)
$btnOk.ForeColor = [System.Drawing.Color]::White
$btnOk.FlatStyle = [System.Windows.Forms.FlatStyle]::Flat
$btnOk.FlatAppearance.BorderSize = 0
$btnOk.Cursor = [System.Windows.Forms.Cursors]::Hand
$btnOk.Visible = $false # Скрыта до окончания работы
$form.Controls.Add($btnOk)

# Синхронизированная хеш-таблица для связи между главным окном и фоновым потоком (Runspace)
$syncHash = [hashtable]::Synchronized(@{})
$syncHash.Form = $form
$syncHash.Label = $lbl
$syncHash.ProgressBar = $pb
$syncHash.Button = $btnOk
$syncHash.CloseRequested = $false
$syncHash.IsRU = $global:IsRU

$btnOk.Add_Click({ $syncHash.CloseRequested = $true }) # При клике меняем флаг закрытия

# Создаем независимый фоновый поток (Runspace), чтобы очистка не вешала графический интерфейс
$Runspace = [System.Management.Automation.Runspaces.RunspaceFactory]::CreateRunspace()
$Runspace.ApartmentState = [System.Threading.ApartmentState]::STA
$Runspace.ThreadOptions = [System.Management.Automation.Runspaces.PSThreadOptions]::ReuseThread
$Runspace.Open()
$Runspace.SessionStateProxy.SetVariable("syncHash", $syncHash)

$ps = [powershell]::Create()
$ps.Runspace = $Runspace

# Изолированная логика очистки
[void]$ps.AddScript({
    function L ([string]$Ru, [string]$En) { if ($syncHash.IsRU) { return $Ru } else { return $En } }
    
    $script:totalSteps = 22 # Точное количество шагов
    $script:currentStep = 0

    function Next-Step($Message) {
        # Жестко инкрементируем переменную уровня скрипта
        $script:currentStep++ 
        $pct = [math]::Round(($script:currentStep / $script:totalSteps) * 100) 
        if ($pct -gt 100) { $pct = 100 } 
        
        # Передаем данные в UI-поток через защищенную хеш-таблицу
        $syncHash.CurrentPct = $pct
        $syncHash.CurrentMsg = $Message
        
        # Делегируем обновление графики в главный UI-поток
        $syncHash.Form.Invoke([action]{
            $syncHash.Label.Text = "[$($syncHash.CurrentPct)%] $($syncHash.CurrentMsg)"
            $syncHash.ProgressBar.Value = $syncHash.CurrentPct
        })
    }

    Next-Step (L "Остановка блокирующих служб..." "Stopping blocking services...")
    # Останавливаем службы обновлений и телеметрии, чтобы они отпустили временные файлы (иначе файлы не удалятся)
    $LockingServices = @("ClickToRunSvc", "wuauserv", "bits", "cryptsvc", "DPS", "DoSvc")
    foreach ($Svc in $LockingServices) {
        if ((Get-Service $Svc 2>> $env:SystemDrive\EastricaTools\Eastrica_ErrorTrace_Cleanup.log).Status -eq 'Running') {
            Stop-Service $Svc -Force 2>> $env:SystemDrive\EastricaTools\Eastrica_ErrorTrace_Cleanup.log # Экстренная остановка
        }
    }

    Next-Step (L "Очистка временных файлов (Temp/Prefetch)..." "Cleaning temporary files...")
    $TempPaths = @(
        "$env:TEMP\*",
        "$env:SystemRoot\Temp\*",
        "$env:SystemRoot\Prefetch\*",
        "$env:LOCALAPPDATA\Temp\*"
    )
    foreach ($Path in $TempPaths) { 
        Remove-Item -Path $Path -Recurse -Force 2>> $env:SystemDrive\EastricaTools\Eastrica_ErrorTrace_Cleanup.log # Сносим всё содержимое папок Temp
    }
    # Добиваем отдельные мусорные файлы по маске
    Get-ChildItem -Path "$env:TEMP\*", "$env:SystemRoot\Temp\*" -Include *.tmp, *.log, *.chk, *.dmp, *._mp, *.err -Recurse -File 2>> $env:SystemDrive\EastricaTools\Eastrica_ErrorTrace_Cleanup.log | Remove-Item -Force 2>> $env:SystemDrive\EastricaTools\Eastrica_ErrorTrace_Cleanup.log

    Next-Step (L "Удаление остатков обновлений и дампов..." "Removing update leftovers and dumps...")
    $UpdatePaths = @(
        "$env:SystemRoot\Minidump\*.dmp", # Дампы синих экранов
        "$env:SystemRoot\memory.dmp", # Полный дамп памяти
        "$env:SystemDrive\ProgramData\Microsoft\Windows\WER\*", # Отчеты об ошибках
        "$env:LOCALAPPDATA\CrashDumps\*", # Дампы крашей программ
        "$env:LOCALAPPDATA\Microsoft\Windows\WER\*", # Локальные отчеты
        "$env:SystemRoot\SoftwareDistribution\Download\*", # Кэш скачанных обновлений Windows
        "$env:SystemRoot\LiveKernelReports\*", # Дампы ядра
        "$env:SystemRoot\Logs\WindowsUpdate\*", # Логи апдейтов
        "$env:SystemRoot\Logs\DISM\*", # Логи DISM
        "$env:SystemRoot\Logs\MoSetup\*", # Логи установщика ОС
        "$env:SystemRoot\Panther\*" # Логи миграции
    )
    foreach ($Path in $UpdatePaths) { 
        Remove-Item -Path $Path -Recurse -Force 2>> $env:SystemDrive\EastricaTools\Eastrica_ErrorTrace_Cleanup.log
    }

    Next-Step (L "Очистка кэша шейдеров..." "Cleaning Shader Cache...")
    $ShaderPaths = @(
        "$env:LOCALAPPDATA\AMD\DxCache\*",
        "$env:LOCALAPPDATA\AMD\GLCache\*",
        "$env:LOCALAPPDATA\NVIDIA\ComputeCache\*",
        "$env:LOCALAPPDATA\NVIDIA\GLCache\*",
        "$env:LOCALAPPDATA\NVIDIA\DXCache\*",
        "$env:LOCALAPPDATA\NVIDIA Corporation\NV_Cache\*",
        "$env:LOCALAPPDATA\D3DSCache\*",
        "$env:LOCALAPPDATA\D3DShaders\*",
        "$env:LOCALAPPDATA\Microsoft\DirectX\ShaderCache\*"
    )
    foreach ($Path in $ShaderPaths) { 
        Remove-Item -Path $Path -Recurse -Force 2>> $env:SystemDrive\EastricaTools\Eastrica_ErrorTrace_Cleanup.log # Удаляем все кэши графики
    }

    Next-Step (L "Очистка иконок и кэшей доставки..." "Cleaning icons and delivery caches...")
    $CachePaths = @(
        "$env:LOCALAPPDATA\Microsoft\Windows\Explorer\thumbcache_*.db", # Кэш эскизов картинок
        "$env:LOCALAPPDATA\Microsoft\Windows\Explorer\iconcache_*.db", # Кэш иконок программ
        "$env:SystemDrive\Windows\ServiceProfiles\LocalService\AppData\Local\FontCache\*", # Кэш шрифтов
        "$env:SystemRoot\System32\FNTCACHE.DAT", # Системный файл кэша шрифтов
        "$env:SystemDrive\Windows\DeliveryOptimization\Cache\*", # Кэш доставки обновлений (Оптимизация доставки)
        "$env:SystemDrive\Windows\SoftwareDistribution\DeliveryOptimization\*",
        "$env:SystemDrive\Windows\ServiceProfiles\NetworkService\AppData\Local\Microsoft\Windows\DeliveryOptimization\*",
        "$env:ProgramData\Microsoft\Network\Downloader\*" # Кэш BITS
    )
    foreach ($Path in $CachePaths) { 
        Remove-Item -Path $Path -Recurse -Force 2>> $env:SystemDrive\EastricaTools\Eastrica_ErrorTrace_Cleanup.log 
    }

    Next-Step (L "Очистка кэшей браузеров..." "Cleaning browser caches...")
    $BrowserPaths = @(
        "$env:LOCALAPPDATA\Google\Chrome\User Data\*\Cache\Cache_Data\*",
        "$env:LOCALAPPDATA\Google\Chrome\User Data\*\Code Cache\*",
        "$env:LOCALAPPDATA\Microsoft\Edge\User Data\*\Cache\Cache_Data\*",
        "$env:LOCALAPPDATA\Microsoft\Edge\User Data\*\Code Cache\*",
        "$env:LOCALAPPDATA\BraveSoftware\Brave-Browser\User Data\*\Cache\Cache_Data\*",
        "$env:LOCALAPPDATA\BraveSoftware\Brave-Browser\User Data\*\Code Cache\*",
        "$env:LOCALAPPDATA\Yandex\YandexBrowser\User Data\*\Cache\*",
        "$env:LOCALAPPDATA\Opera Software\Opera Stable\Cache\Cache_Data\*",
        "$env:LOCALAPPDATA\Opera Software\Opera GX Stable\Cache\Cache_Data\*",
        "$env:LOCALAPPDATA\Mozilla\Firefox\Profiles\*\cache2\*"
    )
    foreach ($Path in $BrowserPaths) { 
        Remove-Item -Path $Path -Recurse -Force 2>> $env:SystemDrive\EastricaTools\Eastrica_ErrorTrace_Cleanup.log # Удаляет сотни мегабайт рекламных баннеров и картинок с сайтов
    }

    Next-Step (L "Очистка кэшей приложений..." "Cleaning app caches...")
    $AppCaches = @(
        "$env:APPDATA\discord\Cache\Cache_Data\*",
        "$env:APPDATA\discord\Code Cache\*",
        "$env:APPDATA\discord\GPUCache\*",
        "$env:LOCALAPPDATA\Spotify\Storage\*",
        "$env:LOCALAPPDATA\Spotify\Browser\Cache\*",
        "$env:APPDATA\Telegram Desktop\tdata\user_data\cache\*",
        "$env:APPDATA\Telegram Desktop\tdata\user_data\media_cache\*",
        "$env:LOCALAPPDATA\Packages\5319275A.WhatsAppDesktop_cv1g1gvanyjgm\LocalCache\*",
        "$env:LOCALAPPDATA\ViberPC\*\Cache\*",
        "$env:APPDATA\Code\Cache\*", # VS Code Cache
        "$env:APPDATA\Code\CachedData\*",
        "$env:APPDATA\Slack\Cache\*",
        "$env:APPDATA\Notion\Cache\*",
        "$env:APPDATA\Figma\Cache\*",
        "$env:LOCALAPPDATA\Crashpad\*", # Общие краш-репорты Electron
        "$env:LOCALAPPDATA\EpicGamesLauncher\Saved\webcache\*", # Кэш лаунчера Epic Games
        "$env:LOCALAPPDATA\Electronic Arts\EA Desktop\Cache\*", # EA App Cache
        "$env:LOCALAPPDATA\Ubisoft Game Launcher\Spool\*", # Ubisoft Cache
        "$env:LOCALAPPDATA\Rockstar Games\Launcher\cache\*", # Rockstar Cache
        "$env:LOCALAPPDATA\FiveM\FiveM.app\data\cache\*", # FiveM кэш (очень пухнет со временем)
        "$env:LOCALAPPDATA\FiveM\FiveM.app\data\server-cache\*",
        "$env:LOCALAPPDATA\FiveM\FiveM.app\data\server-cache-priv\*",
        "$env:LOCALAPPDATA\FiveM\FiveM.app\crashes\*",
        "$env:ProgramFiles (x86)\Steam\appcache\*", # Базовый кэш Steam
        "$env:ProgramFiles (x86)\Steam\depotcache\*",
        "$env:SystemDrive\ProgramData\NVIDIA Corporation\Downloader\*", # Скачанные драйверы NVIDIA (остатки)
        "$env:APPDATA\Macromedia\Flash Player\*",
        "$env:LOCALAPPDATA\Macromedia\Flash Player\*",
        "$env:APPDATA\Adobe\Common\Media Cache Files\*", # Adobe Premiere/AE кэш
        "$env:APPDATA\Adobe\Common\Media Cache\*",
        "$env:LOCALAPPDATA\Battle.net\Cache\*", # Battle.net Cache
        "$env:LOCALAPPDATA\GOG.com\Galaxy\webcache\*", # GOG Cache
        "$env:APPDATA\Microsoft\Teams\Cache\*",
        "$env:APPDATA\Microsoft\Teams\GPUCache\*",
        "$env:LOCALAPPDATA\Packages\MSTeams_8wekyb3d8bbwe\LocalCache\Microsoft\OTel\*",
        "$env:LOCALAPPDATA\Microsoft\Office\16.0\OfficeFileCache\*" # Office Cache
    )
    foreach ($Path in $AppCaches) { 
        Remove-Item -Path $Path -Recurse -Force 2>> $env:SystemDrive\EastricaTools\Eastrica_ErrorTrace_Cleanup.log 
    }

    # Динамический поиск Steam для зачистки его внутреннего веб-браузера (Chromium)
    $SteamPath = (Get-ItemProperty -Path "HKCU:\Software\Valve\Steam" -Name "SteamPath" 2>> $env:SystemDrive\EastricaTools\Eastrica_ErrorTrace_Cleanup.log).SteamPath
    if (-not $SteamPath) { $SteamPath = (Get-ItemProperty -Path "HKLM:\SOFTWARE\WOW6432Node\Valve\Steam" -Name "InstallPath" 2>> $env:SystemDrive\EastricaTools\Eastrica_ErrorTrace_Cleanup.log).InstallPath }
    if (-not $SteamPath) { $SteamPath = (Get-ItemProperty -Path "HKLM:\SOFTWARE\Valve\Steam" -Name "InstallPath" 2>> $env:SystemDrive\EastricaTools\Eastrica_ErrorTrace_Cleanup.log).InstallPath }
    if ($SteamPath) { $SteamPath = $SteamPath -replace '/', '\' } else { $SteamPath = "$env:ProgramFiles (x86)\Steam" }

    $SteamCaches = @(
        "$SteamPath\appcache\*",
        "$SteamPath\depotcache\*",
        "$SteamPath\config\htmlcache\*", # Закешированные баннеры магазина Steam
        "$env:LOCALAPPDATA\Steam\htmlcache\*"
    )
    foreach ($Path in $SteamCaches) { 
        Remove-Item -Path $Path -Recurse -Force 2>> $env:SystemDrive\EastricaTools\Eastrica_ErrorTrace_Cleanup.log 
    }

    Next-Step (L "Очистка кэшей среды разработки и ИИ..." "Cleaning dev and AI caches...")
    $DevCaches = @(
        "$env:USERPROFILE\.cache\huggingface\hub\tmp\*", # Недокачанные ИИ-модели
        "$env:USERPROFILE\.cargo\registry\cache\*", # Rust Cache
        "$env:USERPROFILE\.gradle\caches\*", # Java/Android Cache
        "$env:LOCALAPPDATA\pip\cache\*", # Python Packages Cache (Огромный размер)
        "$env:LOCALAPPDATA\Yarn\Cache\*", # Yarn Node Cache
        "$env:LOCALAPPDATA\NuGet\Cache\*", # C# Nuget Cache
        "$env:LOCALAPPDATA\npm-cache\*" # NPM Node Cache
    )
    foreach ($Path in $DevCaches) { 
        Remove-Item -Path $Path -Recurse -Force 2>> $env:SystemDrive\EastricaTools\Eastrica_ErrorTrace_Cleanup.log 
    }

    Next-Step (L "Очистка журналов CBS и интернет-кэша..." "Cleaning CBS logs and the internet cache...")
    $MiscPaths = @(
        "$env:APPDATA\Microsoft\Windows\Recent\*", # История "Недавних файлов"
        "$env:APPDATA\Microsoft\Windows\Recent\AutomaticDestinations\*", # Списки переходов Проводника
        "$env:APPDATA\Microsoft\Windows\Recent\CustomDestinations\*",
        "$env:LOCALAPPDATA\Microsoft\Windows\INetCache\*", # Кэш Internet Explorer/Системы
        "$env:LOCALAPPDATA\Microsoft\Windows\INetCookies\*", # Куки
        "$env:LOCALAPPDATA\Microsoft\Windows\WebCache\*",
        "$env:LOCALAPPDATA\Microsoft\Windows\Temporary Internet Files\*",
        "$env:LOCALAPPDATA\Microsoft\Windows\History\*",
        "$env:SystemDrive\Windows\Logs\CBS\*.log", # Логи компонентной базы (Часто весят гигабайты)
        "$env:SystemDrive\Windows\Logs\CBS\*.cab", # Сжатые логи CBS (Часто вызывают сбой диска С: из-за переполнения)
        "$env:SystemDrive\*.chk", # Обрывки файлов после проверки диска (Chkdsk)
        "$env:SystemRoot\Downloaded Program Files\*"
    )
    foreach ($Path in $MiscPaths) { 
        Remove-Item -Path $Path -Recurse -Force 2>> $env:SystemDrive\EastricaTools\Eastrica_ErrorTrace_Cleanup.log 
    }

    Next-Step (L "Очистка системного мусора..." "Cleaning system junk...")
    $SystemJunkPaths = @(
        "$env:SystemDrive\NVIDIA\*",   # Распакованные драйверы (уже не нужны после установки)
        "$env:SystemDrive\AMD\*",      # Распакованные драйверы
        "$env:SystemDrive\Intel\*",    # Распакованные драйверы
        "$env:SystemDrive\Windows.old\*", # Резервная копия старой Windows после переустановки
        "$env:ProgramData\Microsoft\Diagnosis\*", # Данные телеметрии
        "$env:SystemDrive\PerfLogs\System\Diagnostics\*", # Журналы производительности
        "$env:SystemRoot\System32\WDI\LogFiles\*", # Логи диагностики драйверов
        "$env:LOCALAPPDATA\Microsoft\Terminal Server Client\Cache\*", # Кэш удаленного рабочего стола
        "$env:SystemRoot\ServiceProfiles\NetworkService\AppData\Local\PeerDistRepub\*", # Кэш BranchCache
        "$env:SystemRoot\System32\SleepStudy\*", # Огромные логи спящего режима
        "$env:SystemRoot\System32\sru\*" # База данных SRUM (статистика сети и батареи)
    )
    foreach ($Path in $SystemJunkPaths) { 
        Remove-Item -Path $Path -Recurse -Force 2>> $env:SystemDrive\EastricaTools\Eastrica_ErrorTrace_Cleanup.log 
    }

    Next-Step (L "Дополнительная системная очистка..." "Additional system cleanup...")
    $SystemExtraPaths = @(
        "$env:SystemRoot\System32\spool\PRINTERS\*", # Зависшие очереди печати принтера
        "$env:USERPROFILE\AppData\LocalLow\Microsoft\CryptnetUrlCache\Content\*", # Кэш криптографии
        "$env:USERPROFILE\AppData\LocalLow\Microsoft\CryptnetUrlCache\MetaData\*",
        "$env:SystemDrive\ProgramData\Microsoft\Windows Defender\Definition Updates\Backup\*", # Старые базы Защитника
        "$env:ProgramData\Microsoft\Windows Defender\Quarantine\*", # Карантин Защитника
        "$env:LOCALAPPDATA\Packages\Microsoft.WindowsStore_8wekyb3d8bbwe\LocalCache\*", # Кэш магазина Windows
        "$env:LOCALAPPDATA\Packages\Microsoft.WindowsStore_8wekyb3d8bbwe\LocalState\cache\*",
        "$env:LOCALAPPDATA\Packages\Microsoft.XboxApp_8wekyb3d8bbwe\LocalCache\*", # Кэш приложения Xbox
        "$env:LOCALAPPDATA\Packages\Microsoft.GamingApp_8wekyb3d8bbwe\LocalCache\*",
        "$env:LOCALAPPDATA\Downloaded Installations\*" # Кэши установщиков MSI
    )
    foreach ($Path in $SystemExtraPaths) { 
        Remove-Item -Path $Path -Recurse -Force 2>> $env:SystemDrive\EastricaTools\Eastrica_ErrorTrace_Cleanup.log 
    }

    Next-Step (L "Очистка старых теневых копий (сохранение последней точки)..." "Cleaning up old shadow copies (retaining the latest point)...")
    try {
        # Получаем все теневые копии и сортируем от старых к новым
        $shadows = @(Get-CimInstance -ClassName Win32_ShadowCopy 2>> $env:SystemDrive\EastricaTools\Eastrica_ErrorTrace_Cleanup.log | Sort-Object InstallDate)
        
        # Если копий больше одной — удаляем все, кроме последней (SkipLast 1)
        if ($shadows.Count -gt 1) {
            $shadows | Select-Object -SkipLast 1 | Remove-CimInstance 2>> $env:SystemDrive\EastricaTools\Eastrica_ErrorTrace_Cleanup.log
        }
    } catch {}

    Next-Step (L "Очистка транзакционной NTFS (TxF) на системном диске..." "Cleaning up Transactional NTFS (TxF) on the system drive...")
    fsutil resource setautoreset true $env:SystemDrive\ > $null 2>&1 # Позволяет Windows и программам выполнять операции с файлами в виде транзакций

    Next-Step (L "Очистка старых пакетов драйверов (Driver Store)..." "Cleaning up old driver packages (Driver Store)...")
    # Принудительно выставляем галочки для профиля sagerun:1 в реестре
    Get-ChildItem -Path "HKLM:\SOFTWARE\Microsoft\Windows\CurrentVersion\Explorer\VolumeCaches" 2>> $env:SystemDrive\EastricaTools\Eastrica_ErrorTrace_Cleanup.log | ForEach-Object {
        Set-ItemProperty -Path $_.PSPath -Name "StateFlags0001" -Value 2 -Type DWord -Force 2>> $env:SystemDrive\EastricaTools\Eastrica_ErrorTrace_Cleanup.log
    }
    Start-Process -FilePath "cleanmgr.exe" -ArgumentList "/sagerun:1" -WindowStyle Hidden -Wait # Запускает встроенную утилиту очистки диска

    Next-Step (L "Очистка журналов событий Windows (Event Logs)..." "Cleaning Windows Event Logs...")
    wevtutil el | ForEach-Object { 
        wevtutil cl "$_" 2>$null # Проходимся по всем журналам Windows и мгновенно их зачищаем
    }

    Next-Step (L "Сброс кэша DNS, фоновых загрузок и корзины..." "Cleaning the DNS cache, background downloads, and Trash...")
    Clear-DnsClientCache 2>> $env:SystemDrive\EastricaTools\Eastrica_ErrorTrace_Cleanup.log # PowerShell сброс DNS
    ipconfig /flushdns > $null 2>&1 # CMD сброс DNS
    arp -d * > $null 2>&1 # Очистка таблицы маршрутизации ARP
    cmd /c "echo. | clip" > $null 2>&1 # Очистка буфера обмена (Текста, скопированного пользователем)
    try { bitsadmin.exe /reset /allusers > $null 2>&1 } catch {} # Сброс зависших загрузок BITS
    cmd /c "rd /s /q %SystemDrive%\`$Recycle.bin" > $null 2>&1 # Жесткая очистка Корзины

    Next-Step (L "Сжатие базы данных поиска..." "Compressing the search database...")
    if ((Get-Service -Name WSearch -ErrorAction SilentlyContinue 2>> $env:SystemDrive\EastricaTools\Eastrica_ErrorTrace_Cleanup.log).Status -ne 'Running') {
        # Если служба поиска отключена скриптом, мы можем физически удалить ее гигантскую базу данных
        Remove-Item -Path "$env:ProgramData\Microsoft\Search\Data\Applications\Windows\*" -Recurse -Force 2>> $env:SystemDrive\EastricaTools\Eastrica_ErrorTrace_Cleanup.log
    }

    Next-Step (L "Очистка хранилища компонентов (WinSxS)..." "Cleaning Component Store (WinSxS)...")
    $dism1 = Start-Process "Dism.exe" -ArgumentList "/online /Cleanup-Image /StartComponentCleanup /ResetBase /Quiet" -WindowStyle Hidden -PassThru
    while (-not $dism1.HasExited) { 
        Start-Sleep -Milliseconds 500 
    }

    $dism2 = Start-Process "Dism.exe" -ArgumentList "/online /Cleanup-Image /SPSuperseded /Quiet" -WindowStyle Hidden -PassThru
    while (-not $dism2.HasExited) { 
        Start-Sleep -Milliseconds 500 
    }

    Next-Step (L "Очистка системных логов и отчетов..." "Clearing system logs and reports...")
    # Сносим текстовые логи, которые система генерирует каждую секунду
    $SystemLogsPaths = @(
        "$env:SystemRoot\*.log",
        "$env:ALLUSERSPROFILE\Application Data\Microsoft\Dr Watson\*.log",
        "$env:ALLUSERSPROFILE\Application Data\Microsoft\Dr Watson\user.dmp",
        "$env:SystemRoot\debug\*.log",
        "$env:SystemRoot\debug\PASSWD.LOG",
        "$env:SystemRoot\debug\Setup\UpdSh.log",
        "$env:SystemRoot\debug\UserMode\*.log",
        "$env:SystemRoot\debug\UserMode\ChkAcc.bak",
        "$env:SystemRoot\debug\UserMode\userenv.bak",
        "$env:LOCALAPPDATA\Microsoft\Internet Explorer\brndlog.bak",
        "$env:LOCALAPPDATA\Microsoft\Internet Explorer\brndlog.txt",
        "$env:SystemRoot\Logs\NetSetup\*",
        "$env:SystemRoot\Logs\SIH\*",
        "$env:SystemRoot\Logs\waasmedic\*",
        "$env:SystemRoot\Microsoft.NET\Framework\*\*.log",
        "$env:SystemRoot\ntbtlog.txt",
        "$env:SystemRoot\OEWABLog.txt",
        "$env:SystemRoot\REGLOCS.OLD",
        "$env:SystemRoot\SchedLgU.txt",
        "$env:SystemRoot\security\logs\*.log",
        "$env:SystemRoot\security\logs\*.old",
        "$env:SystemRoot\setuplog.txt",
        "$env:SystemRoot\SoftwareDistribution\*.log",
        "$env:SystemRoot\System32\*.log",
        "$env:SystemRoot\System32\TZLog.log",
        "$env:SystemRoot\System32\config\systemprofile\Application Data\Microsoft\Internet Explorer\brndlog.bak",
        "$env:SystemRoot\System32\config\systemprofile\Application Data\Microsoft\Internet Explorer\brndlog.txt",
        "$env:SystemRoot\System32\LogFiles\AIT\AitEventLog.etl.*",
        "$env:SystemRoot\System32\LogFiles\Firewall\pfirewall.log*",
        "$env:SystemRoot\System32\LogFiles\Scm\SCM.EVM*",
        "$env:SystemRoot\System32\LogFiles\setupcln\*",
        "$env:SystemRoot\System32\LogFiles\WMI\Terminal*.etl",
        "$env:SystemRoot\System32\LogFiles\WMI\RTBackup\EtwRT.*etl",
        "$env:SystemRoot\System32\wbem\Logs\*.lo_",
        "$env:SystemRoot\System32\wbem\Logs\*.log"
    )
    foreach ($Path in $SystemLogsPaths) { 
        Remove-Item -Path $Path -Recurse -Force 2>> $env:SystemDrive\EastricaTools\Eastrica_ErrorTrace_Cleanup.log 
    }

    Next-Step (L "Удаление пустых папок (Оптимизация MFT)..." "Deleting empty folders (MFT optimization)...")
    $EmptyFolderTargets = @("$env:TEMP", "$env:SystemRoot\Temp", "$env:LOCALAPPDATA\Temp")
    foreach ($target in $EmptyFolderTargets) {
        if (Test-Path $target) {
            # Рекурсивный поиск и удаление папок, в которых вообще нет файлов (Снижает нагрузку на MFT таблицу NTFS)
            Get-ChildItem -Path $target -Recurse -Directory 2>> $env:SystemDrive\EastricaTools\Eastrica_ErrorTrace_Cleanup.log | 
                Where-Object { (Get-ChildItem -Path $_.FullName -Force 2>> $env:SystemDrive\EastricaTools\Eastrica_ErrorTrace_Cleanup.log | Measure-Object).Count -eq 0 } | 
                Remove-Item -Force -Recurse 2>> $env:SystemDrive\EastricaTools\Eastrica_ErrorTrace_Cleanup.log
        }
    }

    Next-Step (L "Сброс истории реестра и завершение..." "Resetting registry history and completion...")
    $RegKeysToClear = @(
        "HKCU:\Software\Microsoft\Windows\ShellNoRoam\MUICache", # Кэш путей к программам
        "HKCU:\Software\Classes\Local Settings\Software\Microsoft\Windows\Shell\MuiCache"
    )
    foreach ($Key in $RegKeysToClear) {
        if (Test-Path $Key) {
            Remove-Item -Path $Key -Recurse -Force 2>> $env:SystemDrive\EastricaTools\Eastrica_ErrorTrace_Cleanup.log # Удаляем
            New-Item -Path $Key -Force 2>> $env:SystemDrive\EastricaTools\Eastrica_ErrorTrace_Cleanup.log | Out-Null # Создаем чистый
        }
    }
    $WallpaperKey = "HKCU:\Software\Microsoft\Windows\CurrentVersion\Explorer\Wallpapers"
    if (Test-Path $WallpaperKey) {
        0..4 | ForEach-Object { Remove-ItemProperty -Path $WallpaperKey -Name "BackgroundHistoryPath$_" 2>> $env:SystemDrive\EastricaTools\Eastrica_ErrorTrace_Cleanup.log } # Очищаем историю обоев рабочего стола
    }
    Remove-Item -Path "$env:APPDATA\Microsoft\Windows\Themes\CachedFiles\*" -Force 2>> $env:SystemDrive\EastricaTools\Eastrica_ErrorTrace_Cleanup.log # Удаляем закэшированные обои

    # Восстанавливаем работу системных служб (Центр обновлений, криптография), чтобы не сломать ПК
    foreach ($Svc in $LockingServices) { 
        Start-Service $Svc 2>> $env:SystemDrive\EastricaTools\Eastrica_ErrorTrace_Cleanup.log 
    }

        # Меняем интерфейс: Прячем прогресс-бар, показываем кнопку
    $syncHash.Form.Invoke([action]{
        $syncHash.ProgressBar.Visible = $false
        $syncHash.Button.Visible = $true
    })

    # Таймер обратного отсчета (10 секунд до автозакрытия) в фоновом потоке с поддержкой EN/RU
    for ($i = 10; $i -gt 0; $i--) {
        if ($syncHash.CloseRequested) { break }
        
        $syncHash.CurrentI = $i
        
        $syncHash.Form.Invoke([action]{
            $syncHash.Label.Text = (L "Расширенная очистка завершена! Закрытие через $($syncHash.CurrentI) сек." "Deep cleanup completed! Closing in $($syncHash.CurrentI) sec.")
            $syncHash.Button.Text = "OK ($($syncHash.CurrentI))"
        })
        Start-Sleep -Seconds 1
    }

    # По завершении таймера даем команду главному окну закрыться
    $syncHash.Form.Invoke([action]{
        $syncHash.Form.Close()
    })
})

# Запускаем фоновый поток (Он начнет чистить систему)
$asyncResult = $ps.BeginInvoke()

# Перехватчик экстренного закрытия окна крестиком
$form.Add_FormClosed({
    $syncHash.CloseRequested = $true
    if ($ps.InvocationStateInfo.State -eq 'Running') {
        try { $ps.Stop() } catch {} # Жестко гасим пайплайн очистки
    }
})

# Показываем графическое окно в главном потоке (Оно не зависнет и будет принимать обновления)
$form.ShowDialog() | Out-Null

# Когда окно закрылось (пользователем или таймером), освобождаем ресурсы Runspace
try {
    if ($ps.InvocationStateInfo.State -eq 'Completed') {
        $ps.EndInvoke($asyncResult)
    }
    $ps.Dispose()
    $Runspace.Close()
    $Runspace.Dispose()
    $form.Dispose()
} catch {}
'@

Write-Host ""
# ==============================================================================
# Раздел 58: Инъекция скрипта очистки в реестр
# ==============================================================================
Show-ProgressStep -StepNum 58 -TotalSteps 81 -Activity "Инъекция скрипта очистки в реестр..."
Write-Host "==============================================================================" -ForegroundColor DarkGray
Write-Host "РАЗДЕЛ 58: ИНЪЕКЦИЯ СКРИПТА ОЧИСТКИ В РЕЕСТР" -ForegroundColor Cyan
Write-Host "==============================================================================" -ForegroundColor DarkGray
$ClearScriptPath = "$OptimizerDir\EastricaClearJunk.ps1"
Apply-Tweak "Сохранение утилиты очистки на диск" { 
    Set-Content -Path $ClearScriptPath -Value $ClearScript -Encoding UTF8 -Force *>&1 | Out-File -FilePath $global:LogPath -Append -Encoding UTF8 
}

if (!(Test-Path "$MenuKey_Junk\command")) { Apply-Tweak "Создание раздела команды для ClearJunk" { New-Item -Path "$MenuKey_Junk\command" -Force > $null 2>&1 } } # Создаем раздел команды в реестре
$FinalCmd_Junk = "powershell.exe -WindowStyle Hidden -NoProfile -ExecutionPolicy Bypass -File `"$ClearScriptPath`""
Apply-Tweak "Инъекция скрипта очистки (ClearJunk) в реестр ПКМ" { Set-Item -Path "$MenuKey_Junk\command" -Value $FinalCmd_Junk -Force > $null 2>&1 } # Записываем вызов в реестр

Write-Host ""
# ==============================================================================
# Раздел 59: Добавление остальных утилит в контекстное меню
# ==============================================================================
Show-ProgressStep -StepNum 59 -TotalSteps 81 -Activity "Добавление остальных утилит в контекстное меню..."
Write-Host "==============================================================================" -ForegroundColor DarkGray
Write-Host "РАЗДЕЛ 59: ДОБАВЛЕНИЕ ОСТАЛЬНЫХ УТИЛИТ В КОНТЕКСТНОЕ МЕНЮ" -ForegroundColor Cyan
Write-Host "==============================================================================" -ForegroundColor DarkGray

# ==============================================================================
# 1. Подраздел "Очистка" (Cleanup)
# ==============================================================================

# ---------------------------------------------------------
# Пункт: Быстрая очистка RAM и VRAM
# ---------------------------------------------------------
$RamScriptPath = "$OptimizerDir\EastricaFlushRam.ps1"
$RamScriptCode = @'
if (!([Security.Principal.WindowsPrincipal][Security.Principal.WindowsIdentity]::GetCurrent()).IsInRole([Security.Principal.WindowsBuiltInRole] "Administrator")) {
    Start-Process powershell.exe -ArgumentList "-NoProfile -ExecutionPolicy Bypass -WindowStyle Hidden -File `"$PSCommandPath`"" -Verb RunAs
    Exit
}
$c = @"
using System;
using System.Runtime.InteropServices;
using System.Diagnostics;
public class FastMem {
    [DllImport("ntdll.dll")] public static extern uint RtlAdjustPrivilege(int p, bool e, bool t, out bool pr);
    [DllImport("ntdll.dll")] public static extern int NtSetSystemInformation(int c, ref int i, int l);
    [DllImport("kernel32.dll")] public static extern bool SetSystemFileCacheSize(IntPtr min, IntPtr max, int f);
    [DllImport("psapi.dll")] public static extern bool EmptyWorkingSet(IntPtr hProcess);
    
    public static void Flush() {
        bool pr;
        RtlAdjustPrivilege(5, true, false, out pr);  // SeIncreaseQuotaPrivilege
        RtlAdjustPrivilege(13, true, false, out pr); // SeProfileSingleProcessPrivilege
        RtlAdjustPrivilege(10, true, false, out pr); // SeDebugPrivilege
        
        SetSystemFileCacheSize((IntPtr)(-1), (IntPtr)(-1), 0);
        
        string[] targets = { "dwm", "explorer", "chrome", "msedge", "brave", "opera", "firefox", "discord", "obs64", "SearchHost", "Widgets", "ShellExperienceHost", "ApplicationFrameHost", "TextInputHost", "EpicGamesLauncher", "steamwebhelper", "Battle.net", "Telegram" };
        foreach (string t in targets) {
            Process[] procs = Process.GetProcessesByName(t);
            foreach (Process p in procs) {
                try { EmptyWorkingSet(p.Handle); } catch {}
            }
        }
        
        int cmd = 4;
        NtSetSystemInformation(80, ref cmd, 4);
    }
}
"@
$FastMemDll = "$env:SystemDrive\EastricaTools\Scripts\FastMem.dll"
if (-not ("FastMem" -as [type])) {
    if (Test-Path $FastMemDll) {
        Add-Type -Path $FastMemDll
    } else {
        Add-Type -TypeDefinition $c -OutputAssembly $FastMemDll
    }
}
[FastMem]::Flush()
[System.GC]::Collect()
$wshell = New-Object -ComObject Wscript.Shell
$wshell.Popup("Оперативная память, VRAM и кэш Standby успешно очищены.", 5, "Eastrica RAM & VRAM Flush", 64) | Out-Null
'@
Apply-Tweak "Создание утилиты мгновенного сброса RAM и VRAM" { Set-Content -Path $RamScriptPath -Value $RamScriptCode -Encoding UTF8 -Force }

$MenuKey_Ram = "$CleanShell\01_FlushRam"
if (!(Test-Path "$MenuKey_Ram\command")) { Apply-Tweak "Создание ключа команды FlushRam" { New-Item -Path "$MenuKey_Ram\command" -Force *>&1 | Out-File -FilePath $global:LogPath -Append -Encoding UTF8 } }
Apply-Tweak "Установка названия для кнопки FlushRam" { Set-ItemProperty -Path $MenuKey_Ram -Name "MUIVerb" -Value (L "Быстрая очистка RAM и VRAM" "Instant RAM & VRAM Flush") -Force *>&1 | Out-File -FilePath $global:LogPath -Append -Encoding UTF8 }
Apply-Tweak "Установка иконки для кнопки FlushRam" { Set-ItemProperty -Path $MenuKey_Ram -Name "Icon" -Value "imageres.dll,-150" -Force *>&1 | Out-File -FilePath $global:LogPath -Append -Encoding UTF8 }
Apply-Tweak "Привязка команды сброса памяти" { Set-Item -Path "$MenuKey_Ram\command" -Value "powershell.exe -WindowStyle Hidden -NoProfile -ExecutionPolicy Bypass -File `"$RamScriptPath`"" -Force *>&1 | Out-File -FilePath $global:LogPath -Append -Encoding UTF8 }

# ==============================================================================
# 2. Подраздел "Система" (System)
# ==============================================================================

# ---------------------------------------------------------
# Пункт: Перезапустить Explorer
# ---------------------------------------------------------
$MenuKey_Exp = "$SystemShell\01_RestartExplorer"
if (!(Test-Path "$MenuKey_Exp\command")) { Apply-Tweak "Создание раздела команды для RestartExplorer" { New-Item -Path "$MenuKey_Exp\command" -Force | Out-Null } }
Apply-Tweak "Установка названия для кнопки RestartExplorer" { Set-ItemProperty -Path $MenuKey_Exp -Name "MUIVerb" -Value (L "Перезапустить Explorer" "Restart Explorer") -Force *>&1 | Out-File -FilePath $global:LogPath -Append -Encoding UTF8 }
Apply-Tweak "Установка иконки для кнопки RestartExplorer" { Set-ItemProperty -Path $MenuKey_Exp -Name "Icon" -Value "explorer.exe,0" -Force *>&1 | Out-File -FilePath $global:LogPath -Append -Encoding UTF8 }
$RestartExpCommand = 'powershell.exe -NoProfile -ExecutionPolicy Bypass -WindowStyle Hidden -Command "Get-Process -ErrorAction SilentlyContinue | Where-Object { -not $_.Responding } | Stop-Process -Force -ErrorAction SilentlyContinue; Stop-Process -Name explorer -Force -ErrorAction SilentlyContinue; Stop-Process -Name ''ShellExperienceHost'', ''TextInputHost'' -Force -ErrorAction SilentlyContinue; Start-Process explorer.exe; (New-Object -ComObject Wscript.Shell).Popup(''Проводник (Explorer) и зависшие процессы успешно перезапущены'', 3, ''Система'', 64) | Out-Null"'
Apply-Tweak "Привязка команды перезапуска Проводника к кнопке" { Set-Item -Path "$MenuKey_Exp\command" -Value $RestartExpCommand -Force *>&1 | Out-File -FilePath $global:LogPath -Append -Encoding UTF8 }

# ---------------------------------------------------------
# Пункт: Тумблер MPO (Динамический статус)
# ---------------------------------------------------------
if (-not $global:OptAI) {
    $MpoScriptPath = "$OptimizerDir\EastricaToggleMPO.ps1"
    $MpoScriptCode = @'
if (!([Security.Principal.WindowsPrincipal][Security.Principal.WindowsIdentity]::GetCurrent()).IsInRole([Security.Principal.WindowsBuiltInRole] "Administrator")) {
    Start-Process powershell.exe -ArgumentList "-NoProfile -ExecutionPolicy Bypass -WindowStyle Hidden -File `"$PSCommandPath`"" -Verb RunAs
    Exit
}
$DwmPath = "HKLM:\SOFTWARE\Microsoft\Windows\Dwm"
$MenuKey_MPO = "Registry::HKEY_CLASSES_ROOT\Directory\Background\shell\EastricaTools\shell\03_SystemMenu\shell\02_ToggleMPO"
$val = (Get-ItemProperty -Path $DwmPath -Name "OverlayTestMode" -ErrorAction SilentlyContinue).OverlayTestMode
$wshell = New-Object -ComObject Wscript.Shell

$global:IsRU = ((Get-UICulture).TwoLetterISOLanguageName -eq "ru")
function L ([string]$Ru, [string]$En) { if ($global:IsRU) { return $Ru } else { return $En } }

if ($val -eq 5) {
    Remove-ItemProperty -Path $DwmPath -Name "OverlayTestMode" -Force -ErrorAction SilentlyContinue
    Set-ItemProperty -Path $MenuKey_MPO -Name "MUIVerb" -Value (L "✔ MPO (Включен - DirectFlip)" "✔ MPO (Enabled - DirectFlip)") -Force
    Stop-Process -Name dwm -Force
    $wshell.Popup("MPO (Multi-Plane Overlay) включен.`nDirectFlip активен, DWM перезапущен.", 5, "Eastrica MPO Switcher", 262208) | Out-Null
} else {
    Set-ItemProperty -Path $DwmPath -Name "OverlayTestMode" -Value 5 -Type DWord -Force
    Set-ItemProperty -Path $MenuKey_MPO -Name "MUIVerb" -Value (L "❌ MPO (Выключен - Фикс мерцания)" "❌ MPO (Disabled - Flicker Fix)") -Force
    Stop-Process -Name dwm -Force
    $wshell.Popup("MPO выключен (Single-Plane mode).`nМерцание устранено, DWM перезапущен.", 5, "Eastrica MPO Switcher", 262208) | Out-Null
}
'@
    Apply-Tweak "Создание скрипта переключения MPO" { Set-Content -Path $MpoScriptPath -Value $MpoScriptCode -Encoding UTF8 -Force }

    $MenuKey_MPO = "$SystemShell\02_ToggleMPO"
    if (!(Test-Path "$MenuKey_MPO\command")) { Apply-Tweak "Создание ключа команды ToggleMPO" { New-Item -Path "$MenuKey_MPO\command" -Force | Out-Null } }
    
    # Первичная проверка статуса MPO для корректной надписи в меню
    $mpoCurrentVal = (Get-ItemProperty -Path "HKLM:\SOFTWARE\Microsoft\Windows\Dwm" -Name "OverlayTestMode" -ErrorAction SilentlyContinue).OverlayTestMode
    if ($mpoCurrentVal -eq 5) {
        $MpoInitialName = (L "❌ MPO (Выключен - Фикс мерцания)" "❌ MPO (Disabled - Flicker Fix)")
    } else {
        $MpoInitialName = (L "✔ MPO (Включен - DirectFlip)" "✔ MPO (Enabled - DirectFlip)")
    }
    
    Apply-Tweak "Установка названия для кнопки ToggleMPO" { Set-ItemProperty -Path $MenuKey_MPO -Name "MUIVerb" -Value $MpoInitialName -Force *>&1 | Out-File -FilePath $global:LogPath -Append -Encoding UTF8 }
    Apply-Tweak "Установка иконки для кнопки ToggleMPO" { Set-ItemProperty -Path $MenuKey_MPO -Name "Icon" -Value "imageres.dll,-1008" -Force *>&1 | Out-File -FilePath $global:LogPath -Append -Encoding UTF8 }
    Apply-Tweak "Привязка команды переключения MPO" { Set-Item -Path "$MenuKey_MPO\command" -Value "powershell.exe -WindowStyle Hidden -NoProfile -ExecutionPolicy Bypass -File `"$MpoScriptPath`"" -Force *>&1 | Out-File -FilePath $global:LogPath -Append -Encoding UTF8 }

# ---------------------------------------------------------
# Пункт: Восстановление максимальной герцовки
# ---------------------------------------------------------
    $HzScriptPath = "$OptimizerDir\EastricaRestoreHz.ps1"
    $HzScriptCode = @'
if (!([Security.Principal.WindowsPrincipal][Security.Principal.WindowsIdentity]::GetCurrent()).IsInRole([Security.Principal.WindowsBuiltInRole] "Administrator")) {
    Start-Process powershell.exe -ArgumentList "-NoProfile -ExecutionPolicy Bypass -WindowStyle Hidden -File `"$PSCommandPath`"" -Verb RunAs
    Exit
}
$hzCode = @"
using System;
using System.Runtime.InteropServices;
public class DisplayHzFix {
    [StructLayout(LayoutKind.Sequential, CharSet = CharSet.Ansi)]
    public struct DEVMODE {
        [MarshalAs(UnmanagedType.ByValTStr, SizeConst = 32)] public string dmDeviceName;
        public short dmSpecVersion; public short dmDriverVersion; public short dmSize; public short dmDriverExtra;
        public int dmFields; public int dmPositionX; public int dmPositionY; public int dmDisplayOrientation;
        public int dmDisplayFixedOutput; public short dmColor; public short dmDuplex; public short dmYResolution;
        public short dmTTOption; public short dmCollate;
        [MarshalAs(UnmanagedType.ByValTStr, SizeConst = 32)] public string dmFormName;
        public short dmLogPixels; public int dmBitsPerPel; public int dmPelsWidth; public int dmPelsHeight;
        public int dmDisplayFlags; public int dmDisplayFrequency;
    }
    [DllImport("user32.dll")] public static extern bool EnumDisplaySettings(string deviceName, int modeNum, ref DEVMODE devMode);
    [DllImport("user32.dll")] public static extern int ChangeDisplaySettings(ref DEVMODE devMode, int flags);

    public static int ApplyHighestHz() {
        DEVMODE current = new DEVMODE();
        current.dmSize = (short)Marshal.SizeOf(typeof(DEVMODE));
        if (!EnumDisplaySettings(null, -1, ref current)) return 0;
        
        int highestHz = current.dmDisplayFrequency;
        DEVMODE bestMode = current;
        DEVMODE temp = new DEVMODE();
        temp.dmSize = (short)Marshal.SizeOf(typeof(DEVMODE));
        
        int modeIndex = 0;
        while (EnumDisplaySettings(null, modeIndex, ref temp)) {
            if (temp.dmPelsWidth == current.dmPelsWidth && temp.dmPelsHeight == current.dmPelsHeight) {
                if (temp.dmDisplayFrequency > highestHz) {
                    highestHz = temp.dmDisplayFrequency;
                    bestMode = temp;
                }
            }
            modeIndex++;
        }
        
        if (highestHz > current.dmDisplayFrequency) {
            bestMode.dmFields = 0x00580000; // DM_PELSWIDTH (0x80000) | DM_PELSHEIGHT (0x100000) | DM_DISPLAYFREQUENCY (0x400000)
            ChangeDisplaySettings(ref bestMode, 0);
            return highestHz;
        }
        return current.dmDisplayFrequency;
    }
}
"@
Add-Type -TypeDefinition $hzCode
$applied = [DisplayHzFix]::ApplyHighestHz()
$wshell = New-Object -ComObject Wscript.Shell
$wshell.Popup("Герцовка дисплея установлена на максимум: $applied Hz", 5, "Eastrica Display Sync", 262208) | Out-Null
'@
Apply-Tweak "Создание утилиты восстановления герцовки" { Set-Content -Path $HzScriptPath -Value $HzScriptCode -Encoding UTF8 -Force }

$MenuKey_Hz = "$SystemShell\03_RestoreMaxHz"
if (!(Test-Path "$MenuKey_Hz\command")) { Apply-Tweak "Создание ключа команды RestoreMaxHz" { New-Item -Path "$MenuKey_Hz\command" -Force | Out-Null } }
Apply-Tweak "Установка названия для кнопки RestoreMaxHz" { Set-ItemProperty -Path $MenuKey_Hz -Name "MUIVerb" -Value (L "Восстановить максимальную герцовку (Hz)" "Restore Maximum Refresh Rate (Hz)") -Force *>&1 | Out-File -FilePath $global:LogPath -Append -Encoding UTF8 }
Apply-Tweak "Установка иконки для кнопки RestoreMaxHz" { Set-ItemProperty -Path $MenuKey_Hz -Name "Icon" -Value "imageres.dll,-109" -Force *>&1 | Out-File -FilePath $global:LogPath -Append -Encoding UTF8 }
Apply-Tweak "Привязка команды восстановления герцовки" { Set-Item -Path "$MenuKey_Hz\command" -Value "powershell.exe -WindowStyle Hidden -NoProfile -ExecutionPolicy Bypass -File `"$HzScriptPath`"" -Force *>&1 | Out-File -FilePath $global:LogPath -Append -Encoding UTF8 }
