# ==============================================================================
# Утилита аппаратного замера частоты опроса мыши (C# WinAPI Raw Input)
# ==============================================================================
$MouseTesterScriptPath = "$OptimizerDir\EastricaMouseTester.ps1"
$MouseTesterScriptCode = @'
Add-Type -AssemblyName System.Windows.Forms
Add-Type -AssemblyName System.Drawing

$global:IsRU = ((Get-UICulture).TwoLetterISOLanguageName -eq "ru")
function L ([string]$Ru, [string]$En) { if ($global:IsRU) { return $Ru } else { return $En } }

$MouseTesterCS = @"
using System;
using System.Collections.Generic;
using System.Diagnostics;
using System.Drawing;
using System.Runtime.InteropServices;
using System.Windows.Forms;

public class MouseTesterApp : Form {
    [StructLayout(LayoutKind.Sequential)]
    internal struct RAWINPUTDEVICE {
        public ushort usUsagePage;
        public ushort usUsage;
        public uint dwFlags;
        public IntPtr hwndTarget;
    }

    [StructLayout(LayoutKind.Sequential)]
    internal struct RAWINPUTHEADER {
        public uint dwType;
        public uint dwSize;
        public IntPtr hDevice;
        public IntPtr wParam;
    }

    [DllImport("user32.dll", SetLastError = true)]
    internal static extern bool RegisterRawInputDevices(RAWINPUTDEVICE[] pRawInputDevices, uint uiNumDevices, uint cbSize);

    [DllImport("user32.dll", SetLastError = true)]
    internal static extern uint GetRawInputData(IntPtr hRawInput, uint uiCommand, IntPtr pData, ref uint pcbSize, uint cbSizeHeader);

    [DllImport("dwmapi.dll")]
    internal static extern int DwmSetWindowAttribute(IntPtr hwnd, int attr, ref int attrValue, int attrSize);

    private const int WM_INPUT = 0x00FF;
    private const uint RID_INPUT = 0x10000003;
    private const uint RIDEV_INPUTSINK = 0x00000100;

    private IntPtr rawBuffer = IntPtr.Zero;
    private int headerSize = 0;
    private long lastTicks = 0;

    private double currentHz = 0;
    private double peakHz = 0;
    private double avgHz = 0;
    private double jitterHz = 0;
    private long totalSamples = 0;

    private Queue<double> hzHistory = new Queue<double>();
    private const int WINDOW_SIZE = 120;

    private Label lblCurrentVal;
    private Label lblPeakVal;
    private Label lblAvgVal;
    private Label lblJitterVal;
    private Label lblSampleCount;
    private Panel canvas;
    private System.Windows.Forms.Timer updateTimer;

    public MouseTesterApp(bool isRu) {
        this.Text = isRu ? "Eastrica - Тестер частоты опроса мыши (Raw Input)" : "Eastrica - Mouse Polling Rate Tester (Raw Input)";
        this.ClientSize = new Size(540, 420);
        this.StartPosition = FormStartPosition.CenterScreen;
        this.FormBorderStyle = FormBorderStyle.FixedDialog;
        this.MaximizeBox = false;
        this.BackColor = Color.FromArgb(20, 20, 24);
        this.ForeColor = Color.White;
        this.TopMost = true;

        // Включение темного заголовка DWM
        int darkMode = 1;
        DwmSetWindowAttribute(this.Handle, 20, ref darkMode, 4);
        DwmSetWindowAttribute(this.Handle, 19, ref darkMode, 4);

        headerSize = Marshal.SizeOf(typeof(RAWINPUTHEADER));
        rawBuffer = Marshal.AllocHGlobal(128);

        InitializeInterface(isRu);
        InitRawInput();

        updateTimer = new System.Windows.Forms.Timer();
        updateTimer.Interval = 16; // 60 FPS обновление интерфейса
        updateTimer.Tick += (s, e) => UpdateMetricsUI(isRu);
        updateTimer.Start();
    }

    private void InitializeInterface(bool isRu) {
        Label lblHeader = new Label {
            Text = isRu ? "Непрерывно двигайте мышью для фиксации частоты" : "Move mouse continuously inside window to measure rate",
            Font = new Font("Segoe UI", 10, FontStyle.Bold),
            ForeColor = Color.FromArgb(0, 200, 255),
            Location = new Point(15, 12),
            AutoSize = true
        };
        this.Controls.Add(lblHeader);

        // Карточка 1: Текущая частота
        Panel pnlCur = CreateMetricCard(15, 45, 120, 75, isRu ? "ТЕКУЩАЯ" : "CURRENT", Color.FromArgb(0, 200, 255));
        lblCurrentVal = (Label)pnlCur.Controls[1];

        // Карточка 2: Пиковая частота
        Panel pnlPeak = CreateMetricCard(145, 45, 120, 75, isRu ? "ПИКОВАЯ" : "PEAK", Color.FromArgb(50, 255, 100));
        lblPeakVal = (Label)pnlPeak.Controls[1];

        // Карточка 3: Средняя частота
        Panel pnlAvg = CreateMetricCard(275, 45, 120, 75, isRu ? "СРЕДНЯЯ" : "AVERAGE", Color.FromArgb(255, 200, 50));
        lblAvgVal = (Label)pnlAvg.Controls[1];

        // Карточка 4: Джиттер / Стабильность
        Panel pnlJit = CreateMetricCard(405, 45, 120, 75, isRu ? "ДЖИТТЕР" : "JITTER", Color.FromArgb(255, 80, 80));
        lblJitterVal = (Label)pnlJit.Controls[1];

        // Интерактивная зона движения мыши
        canvas = new Panel {
            Location = new Point(15, 130),
            Size = new Size(510, 210),
            BackColor = Color.FromArgb(28, 28, 34),
            BorderStyle = BorderStyle.FixedSingle
        };
        Label lblCanvasHint = new Label {
            Text = isRu ? "ЗОНА ДВИЖЕНИЯ МЫШИ" : "MOUSE TRACKING ZONE",
            Font = new Font("Segoe UI", 12, FontStyle.Bold),
            ForeColor = Color.FromArgb(55, 55, 65),
            Dock = DockStyle.Fill,
            TextAlign = ContentAlignment.MiddleCenter
        };
        canvas.Controls.Add(lblCanvasHint);
        this.Controls.Add(canvas);

        lblSampleCount = new Label {
            Text = (isRu ? "Пакетов получено: " : "Packets received: ") + "0",
            Font = new Font("Segoe UI", 9, FontStyle.Regular),
            ForeColor = Color.Gray,
            Location = new Point(15, 360),
            AutoSize = true
        };
        this.Controls.Add(lblSampleCount);

        Button btnReset = new Button {
            Text = isRu ? "СБРОС" : "RESET",
            Location = new Point(310, 355),
            Size = new Size(100, 32),
            BackColor = Color.FromArgb(45, 45, 52),
            ForeColor = Color.White,
            FlatStyle = FlatStyle.Flat
        };
        btnReset.FlatAppearance.BorderSize = 0;
        btnReset.Click += (s, e) => ResetMetrics();
        this.Controls.Add(btnReset);

        Button btnClose = new Button {
            Text = isRu ? "ЗАКРЫТЬ" : "CLOSE",
            Location = new Point(425, 355),
            Size = new Size(100, 32),
            BackColor = Color.FromArgb(0, 120, 215),
            ForeColor = Color.White,
            FlatStyle = FlatStyle.Flat,
            Font = new Font("Segoe UI", 9, FontStyle.Bold)
        };
        btnClose.FlatAppearance.BorderSize = 0;
        btnClose.Click += (s, e) => this.Close();
        this.Controls.Add(btnClose);
    }

    private Panel CreateMetricCard(int x, int y, int w, int h, string title, Color valueColor) {
        Panel pnl = new Panel {
            Location = new Point(x, y),
            Size = new Size(w, h),
            BackColor = Color.FromArgb(28, 28, 34),
            BorderStyle = BorderStyle.FixedSingle
        };
        Label lblTitle = new Label {
            Text = title,
            Font = new Font("Segoe UI", 8, FontStyle.Bold),
            ForeColor = Color.Gray,
            Location = new Point(5, 5),
            AutoSize = true
        };
        Label lblVal = new Label {
            Text = "0 Hz",
            Font = new Font("Segoe UI", 14, FontStyle.Bold),
            ForeColor = valueColor,
            Location = new Point(5, 28),
            AutoSize = true
        };
        pnl.Controls.Add(lblTitle);
        pnl.Controls.Add(lblVal);
        this.Controls.Add(pnl);
        return pnl;
    }

    private void InitRawInput() {
        RAWINPUTDEVICE[] rid = new RAWINPUTDEVICE[1];
        rid[0].usUsagePage = 0x01; // Generic Desktop Controls
        rid[0].usUsage = 0x02;     // Mouse
        rid[0].dwFlags = RIDEV_INPUTSINK;
        rid[0].hwndTarget = this.Handle;
        RegisterRawInputDevices(rid, 1, (uint)Marshal.SizeOf(typeof(RAWINPUTDEVICE)));
    }

    private void ResetMetrics() {
        lock (hzHistory) {
            hzHistory.Clear();
            currentHz = 0;
            peakHz = 0;
            avgHz = 0;
            jitterHz = 0;
            totalSamples = 0;
            lastTicks = 0;
        }
    }

    protected override void WndProc(ref Message m) {
        if (m.Msg == WM_INPUT) {
            uint size = 128;
            uint bytesCopied = GetRawInputData(m.LParam, RID_INPUT, rawBuffer, ref size, (uint)headerSize);
            if (bytesCopied > 0 && bytesCopied <= 128) {
                int lastX = Marshal.ReadInt32(rawBuffer, headerSize + 12);
                int lastY = Marshal.ReadInt32(rawBuffer, headerSize + 16);

                if (lastX != 0 || lastY != 0) {
                    long currentTicks = Stopwatch.GetTimestamp();
                    if (lastTicks != 0) {
                        long delta = currentTicks - lastTicks;
                        if (delta > 0) {
                            double deltaSec = (double)delta / Stopwatch.Frequency;
                            
                            // Фильтр системных дуплетов очереди: при частоте порта 1000Hz пакеты физически
                            // не могут приходить быстрее 0.45 мс (2200 Hz). Пакеты быстрее 0.45 мс — это
                            // сдвоенная вычитка очереди Windows, их объединяем для корректного расчета джиттера.
                            if (deltaSec >= 0.00045 && deltaSec < 0.04) {
                                double instantHz = 1.0 / deltaSec;
                                lock (hzHistory) {
                                    currentHz = instantHz;
                                    if (instantHz > peakHz) { peakHz = instantHz; }
                                    hzHistory.Enqueue(instantHz);
                                    if (hzHistory.Count > WINDOW_SIZE) { hzHistory.Dequeue(); }
                                    totalSamples++;
                                }
                                lastTicks = currentTicks;
                            }
                        }
                    } else {
                        lastTicks = currentTicks;
                    }
                }
            }
        }
        base.WndProc(ref m);
    }

    private void UpdateMetricsUI(bool isRu) {
        double sum = 0;
        int count = 0;
        double currentCopy, peakCopy;

        lock (hzHistory) {
            count = hzHistory.Count;
            if (count > 0) {
                foreach (double h in hzHistory) { sum += h; }
                avgHz = sum / count;

                // Расчет стандартного отклонения (Джиттер)
                double varianceSum = 0;
                foreach (double h in hzHistory) {
                    double diff = h - avgHz;
                    varianceSum += diff * diff;
                }
                jitterHz = Math.Sqrt(varianceSum / count);
            }
            currentCopy = currentHz;
            peakCopy = peakHz;
        }

        lblCurrentVal.Text = Math.Round(currentCopy) + " Hz";
        lblPeakVal.Text = Math.Round(peakCopy) + " Hz";
        lblAvgVal.Text = Math.Round(avgHz) + " Hz";
        lblJitterVal.Text = "± " + Math.Round(jitterHz) + " Hz";
        lblSampleCount.Text = (isRu ? "Пакетов получено: " : "Packets received: ") + totalSamples;
    }

    protected override void OnFormClosed(FormClosedEventArgs e) {
        if (updateTimer != null) { updateTimer.Stop(); updateTimer.Dispose(); }
        if (rawBuffer != IntPtr.Zero) { Marshal.FreeHGlobal(rawBuffer); rawBuffer = IntPtr.Zero; }
        base.OnFormClosed(e);
    }
}
"@

Add-Type -TypeDefinition $MouseTesterCS -ReferencedAssemblies "System.Windows.Forms", "System.Drawing"
[System.Windows.Forms.Application]::EnableVisualStyles()
$app = New-Object MouseTesterApp($global:IsRU)
$app.ShowDialog() | Out-Null
$app.Dispose()
'@

Apply-Tweak "Создание утилиты замера частоты мыши (Raw Input)" { 
    Set-Content -Path $MouseTesterScriptPath -Value $MouseTesterScriptCode -Encoding UTF8 -Force *>&1 | Out-File -FilePath $global:LogPath -Append -Encoding UTF8 
}

$MenuKey_MouseTest = "$SystemShell\05_MouseTester"
if (!(Test-Path "$MenuKey_MouseTest\command")) { 
    Apply-Tweak "Создание ключа команды MouseTester" { New-Item -Path "$MenuKey_MouseTest\command" -Force | Out-Null } 
}
Apply-Tweak "Установка названия для кнопки MouseTester" { Set-ItemProperty -Path $MenuKey_MouseTest -Name "MUIVerb" -Value (L "Тест частоты опроса мыши (Raw Input Hz)" "Mouse Polling Rate Tester (Raw Input Hz)") -Force *>&1 | Out-File -FilePath $global:LogPath -Append -Encoding UTF8 }
Apply-Tweak "Установка иконки для кнопки MouseTester" { Set-ItemProperty -Path $MenuKey_MouseTest -Name "Icon" -Value "main.cpl,0" -Force *>&1 | Out-File -FilePath $global:LogPath -Append -Encoding UTF8 }
Apply-Tweak "Привязка команды запуска тестера мыши" { Set-Item -Path "$MenuKey_MouseTest\command" -Value "powershell.exe -WindowStyle Hidden -NoProfile -ExecutionPolicy Bypass -File `"$MouseTesterScriptPath`"" -Force *>&1 | Out-File -FilePath $global:LogPath -Append -Encoding UTF8 }

# ---------------------------------------------------------
# Сброс и реанимация Центра обновлений (Reset WU)
# ---------------------------------------------------------
$ResetWuScriptPath = "$OptimizerDir\EastricaResetWindowsUpdate.ps1"
$ResetWuScriptCode = @'
# ==============================================================================
# Eastrica - полный сброс и реанимация Центра обновлений Windows (Reset WU)
# ==============================================================================
if (!([Security.Principal.WindowsPrincipal][Security.Principal.WindowsIdentity]::GetCurrent()).IsInRole([Security.Principal.WindowsBuiltInRole] "Administrator")) {
    Start-Process powershell.exe -ArgumentList "-NoProfile -ExecutionPolicy Bypass -File `"$PSCommandPath`"" -Verb RunAs
    Exit
}

Write-Host "Запуск глубокой реанимации компонентов Центра обновлений Windows..." -ForegroundColor Cyan

# 1. Остановка зависимых служб
$ServicesToStop = @("wuauserv", "cryptSvc", "bits", "msiserver", "dosvc", "waasmedicsvc")
foreach ($svc in $ServicesToStop) {
    try {
        Stop-Service -Name $svc -Force -ErrorAction SilentlyContinue
        cmd.exe /c "sc.exe config $svc start= demand >nul 2>&1"
    } catch {}
}

# Принудительное завершение зависших рабочих процессов установщика
Get-Process -Name "trustedinstaller", "tiworker", "wuauclt", "usoclient" -ErrorAction SilentlyContinue | Stop-Process -Force -ErrorAction SilentlyContinue

# 2. Сброс очередей BITS
try {
    Start-Process "bitsadmin.exe" -ArgumentList "/reset /allusers" -Wait -WindowStyle Hidden -ErrorAction SilentlyContinue
} catch {}

# 3. Полное удаление кэша обновлений и каталогов сертификатов
$FoldersToClear = @(
    "$env:SystemRoot\SoftwareDistribution",
    "$env:SystemRoot\System32\catroot2",
    "$env:ProgramData\Microsoft\Network\Downloader"
)

foreach ($folder in $FoldersToClear) {
    if (Test-Path $folder) {
        $folderLeaf = Split-Path $folder -Leaf
        $folderParent = Split-Path $folder -Parent
        $backupLeaf = "$folderLeaf.old_" + (Get-Date -Format "yyyyMMdd_HHmmss")
        $backupFullPath = Join-Path $folderParent $backupLeaf
        try {
            Rename-Item -Path $folder -NewName $backupLeaf -Force -ErrorAction Stop
            Remove-Item -Path $backupFullPath -Recurse -Force -ErrorAction SilentlyContinue
        } catch {
            # Если папка заблокирована, удаляем ее содержимое напрямую
            Get-ChildItem -Path $folder -Recurse -Force -ErrorAction SilentlyContinue | Remove-Item -Recurse -Force -ErrorAction SilentlyContinue
        }
    }
}

# Очистка логов обновлений
Remove-Item -Path "$env:SystemRoot\Logs\WindowsUpdate\*" -Recurse -Force -ErrorAction SilentlyContinue

# 4. Восстановление исходных дескрипторов безопасности (ACL) для BITS и wuauserv
cmd.exe /c 'sc.exe sdset bits D:(A;;CCLCSWRPWPDTLOCRRC;;;SY)(A;;CCDCLCSWRPWPDTLOCRSDRCWDWO;;;BA)(A;;CCLCSWLOCRRC;;;AU)(A;;CCLCSWLOCRRC;;;PU) >nul 2>&1'
cmd.exe /c 'sc.exe sdset wuauserv D:(A;;CCLCSWRPLORC;;;AU)(A;;CCDCLCSWRPWPDTLOCRSDRCWDWO;;;BA)(A;;CCDCLCSWRPWPDTLOCRSDRCWDWO;;;SY) >nul 2>&1'

# 5. Сброс сетевых прокси и Winsock каталогов
cmd.exe /c "netsh winsock reset >nul 2>&1"
cmd.exe /c "netsh winhttp reset proxy >nul 2>&1"

# 6. Повторная регистрация системных DLL библиотек Центра обновлений
$DllList = @(
    "atl.dll", "urlmon.dll", "mshtml.dll", "shdocvw.dll", "browseui.dll", "jscript.dll", "vbscript.dll",
    "scrrun.dll", "msxml.dll", "msxml3.dll", "msxml6.dll", "actxprxy.dll", "softpub.dll", "wintrust.dll",
    "dssenh.dll", "rsaenh.dll", "gpkcsp.dll", "sccbase.dll", "slbcsp.dll", "cryptdlg.dll", "oleaut32.dll",
    "ole32.dll", "shell32.dll", "initpki.dll", "wuapi.dll", "wuaueng.dll", "wucltui.dll", "wups.dll",
    "wups2.dll", "wuweb.dll", "qmgr.dll", "qmgrprxy.dll", "wucltux.dll", "muweb.dll", "wuwebv.dll"
)
foreach ($dll in $DllList) {
    Start-Process "regsvr32.exe" -ArgumentList "/s `"$dll`"" -Wait -WindowStyle Hidden -ErrorAction SilentlyContinue
}

# 7. Снятие блокировок в реестре (WSUS и отключенные серверы)
$WuPolicyKeys = @(
    "HKLM:\SOFTWARE\Policies\Microsoft\Windows\WindowsUpdate",
    "HKLM:\SOFTWARE\Policies\Microsoft\Windows\WindowsUpdate\AU"
)
foreach ($key in $WuPolicyKeys) {
    if (Test-Path $key) {
        Remove-ItemProperty -Path $key -Name "DisableWindowsUpdateAccess" -Force -ErrorAction SilentlyContinue
        Remove-ItemProperty -Path $key -Name "DoNotConnectToWindowsUpdateInternetLocations" -Force -ErrorAction SilentlyContinue
        Remove-ItemProperty -Path $key -Name "DisableWUServer" -Force -ErrorAction SilentlyContinue
    }
}

# 8. Запуск и перевод служб в штатный режим
$ServicesToStart = @("cryptSvc", "bits", "wuauserv", "dosvc")
foreach ($svc in $ServicesToStart) {
    try {
        cmd.exe /c "sc.exe config $svc start= auto >nul 2>&1"
        Start-Service -Name $svc -ErrorAction SilentlyContinue
    } catch {}
}

# 9. Принудительный сброс авторизации и повторный опрос серверов Microsoft
cmd.exe /c "usoclient.exe ResetAuthorization >nul 2>&1"
cmd.exe /c "usoclient.exe StartScan >nul 2>&1"

$wshell = New-Object -ComObject Wscript.Shell
$wshell.Popup("Компоненты Центра обновлений полностью реанимированы!`nКэш очищен, службы перезапущены, запущен поиск обновлений.", 6, "Eastrica Windows Update Reset", 64) | Out-Null
'@

Apply-Tweak "Создание скрипта сброса Windows Update" { 
    Set-Content -Path $ResetWuScriptPath -Value $ResetWuScriptCode -Encoding UTF8 -Force *>&1 | Out-File -FilePath $global:LogPath -Append -Encoding UTF8 
}

$MenuKey_ResetWU = "$SystemShell\04_ResetWindowsUpdate"
if (!(Test-Path "$MenuKey_ResetWU\command")) { 
    Apply-Tweak "Создание ключа команды ResetWindowsUpdate" { New-Item -Path "$MenuKey_ResetWU\command" -Force | Out-Null } 
}
