if (-not $global:OptAI) {
    $PowerScriptPath = "$OptimizerDir\EastricaSwitchPower.ps1"
    $PowerScriptCode = @'
param([string]$Mode = "Ultimate")

# Автоматическое повышение прав для гарантированной смены схемы питания и обновления меню в HKCR
if (!([Security.Principal.WindowsPrincipal][Security.Principal.WindowsIdentity]::GetCurrent()).IsInRole([Security.Principal.WindowsBuiltInRole] "Administrator")) {
    Start-Process powershell.exe -ArgumentList "-NoProfile -ExecutionPolicy Bypass -WindowStyle Hidden -File `"$PSCommandPath`" -Mode $Mode" -Verb RunAs
    Exit
}

$wshell = New-Object -ComObject Wscript.Shell
$global:IsRU = ((Get-UICulture).TwoLetterISOLanguageName -eq "ru")
function L ([string]$Ru, [string]$En) { if ($global:IsRU) { return $Ru } else { return $En } }

$allSchemes = powercfg.exe /list
$PowerBalanced = "381b4222-f694-41f0-9685-ff5bb260df2e"
$PowerUltimate = "e9a42b02-d5df-448d-aa00-03f14749eb61"

$ultMatch = $allSchemes | Select-String -Pattern "e9a42b02-d5df-448d-aa00-03f14749eb61|Ultimate|Максимальная производительность" | Select-Object -First 1
if ($ultMatch -and $ultMatch.ToString() -match "([a-f0-9]{8}-[a-f0-9]{4}-[a-f0-9]{4}-[a-f0-9]{4}-[a-f0-9]{12})") {
    $PowerUltimate = $matches[1]
} else {
    $highMatch = $allSchemes | Select-String -Pattern "8c5e7fda-e8bf-4a96-9a85-a6e23a8c635c|High performance|Высокая производительность" | Select-Object -First 1
    if ($highMatch -and $highMatch.ToString() -match "([a-f0-9]{8}-[a-f0-9]{4}-[a-f0-9]{4}-[a-f0-9]{4}-[a-f0-9]{12})") {
        $PowerUltimate = $matches[1]
    }
}

$msg = ""
if ($Mode -eq "Ultimate") {
    powercfg.exe /setactive $PowerUltimate
    $msg = (L "Схема 'Максимальная производительность' активирована" "Plan 'Ultimate Performance' is activated")
} else {
    powercfg.exe /setactive $PowerBalanced
    $msg = (L "Схема 'Сбалансированная' активирована" "Plan 'Balanced' is activated")
}

try {
    $MenuShell = "Registry::HKEY_CLASSES_ROOT\Directory\Background\shell\EastricaToolsExtra\shell\01_PowerMenu\shell"
    Set-ItemProperty -Path "$MenuShell\01_PowerUltimate" -Name "MUIVerb" -Value (L "Максимальная производительность (Игры/ИИ)" "Ultimate Performance (Gaming/AI)") -Force -ErrorAction SilentlyContinue
    Set-ItemProperty -Path "$MenuShell\02_PowerBalanced" -Name "MUIVerb" -Value (L "Сбалансированный режим (Серфинг/Медиа)" "Balanced Mode (Surfing/Media)") -Force -ErrorAction SilentlyContinue

    if ($Mode -eq "Ultimate") {
        Set-ItemProperty -Path "$MenuShell\01_PowerUltimate" -Name "MUIVerb" -Value (L "✔ Максимальная производительность (Игры/ИИ)" "✔ Ultimate Performance (Gaming/AI)") -Force -ErrorAction SilentlyContinue
    } else {
        Set-ItemProperty -Path "$MenuShell\02_PowerBalanced" -Name "MUIVerb" -Value (L "✔ Сбалансированный режим (Серфинг/Медиа)" "✔ Balanced Mode (Surfing/Media)") -Force -ErrorAction SilentlyContinue
    }
} catch {}

# 262208 = MB_ICONINFORMATION (64) + MB_TOPMOST (262144) — гарантирует показ поверх всех окон
$wshell.Popup($msg, 3, (L "Питание" "Power Plan"), 262208) | Out-Null
'@
    Apply-Tweak "Создание скрипта переключения питания" { Set-Content -Path $PowerScriptPath -Value $PowerScriptCode -Encoding UTF8 -Force }

    $MenuKey_Power = "$EastricaExtraShell\01_PowerMenu"
