    if (!(Test-Path $MenuKey_Power)) { Apply-Tweak "Создание раздела подменю PowerMenu" { New-Item -Path $MenuKey_Power -Force | Out-Null } }
    Apply-Tweak "Установка названия подменю PowerMenu" { Set-ItemProperty -Path $MenuKey_Power -Name "MUIVerb" -Value (L "Режим питания" "Power Plan") -Force *>&1 | Out-File -FilePath $global:LogPath -Append -Encoding UTF8 }
    Apply-Tweak "Установка иконки подменю PowerMenu" { Set-ItemProperty -Path $MenuKey_Power -Name "Icon" -Value "powercpl.dll" -Force *>&1 | Out-File -FilePath $global:LogPath -Append -Encoding UTF8 }
