    if (!(Test-Path $PowerShell)) { Apply-Tweak "Создание Shell для подменю PowerMenu" { New-Item -Path $PowerShell -Force | Out-Null } }

    $CurrentActivePlan = (powercfg /getactivescheme)
    $TitleUlt = if ($CurrentActivePlan -match "e9a42b02-d5df-448d-aa00-03f14749eb61|Ultimate|Максимальная производительность") { (L "✔ Максимальная производительность (Игры/ИИ)" "✔ Ultimate Performance (Gaming/AI)") } else { (L "Максимальная производительность (Игры/ИИ)" "Ultimate Performance (Gaming/AI)") }
    $TitleBal = if ($CurrentActivePlan -match "381b4222-f694-41f0-9685-ff5bb260df2e|Balanced|Сбалансированная") { (L "✔ Сбалансированный режим (Серфинг/Медиа)" "✔ Balanced Mode (Surfing/Media)") } else { (L "Сбалансированный режим (Серфинг/Медиа)" "Balanced Mode (Surfing/Media)") }

    $Ultimate = "$PowerShell\01_PowerUltimate"
    if (!(Test-Path "$Ultimate\command")) { Apply-Tweak "Создание команды PowerUltimate" { New-Item -Path "$Ultimate\command" -Force | Out-Null } }
    Apply-Tweak "Установка названия PowerUltimate" { Set-ItemProperty -Path $Ultimate -Name "MUIVerb" -Value $TitleUlt -Force *>&1 | Out-File -FilePath $global:LogPath -Append -Encoding UTF8 }
    Apply-Tweak "Установка иконки PowerUltimate" { Set-ItemProperty -Path $Ultimate -Name "Icon" -Value "powercpl.dll,-507" -Force *>&1 | Out-File -FilePath $global:LogPath -Append -Encoding UTF8 }
    Apply-Tweak "Привязка скрипта к PowerUltimate" { Set-Item -Path "$Ultimate\command" -Value "powershell.exe -WindowStyle Hidden -NoProfile -ExecutionPolicy Bypass -File `"$PowerScriptPath`" -Mode Ultimate" -Force *>&1 | Out-File -FilePath $global:LogPath -Append -Encoding UTF8 }

    $Balanced = "$PowerShell\02_PowerBalanced"
    if (!(Test-Path "$Balanced\command")) { Apply-Tweak "Создание команды PowerBalanced" { New-Item -Path "$Balanced\command" -Force | Out-Null } }
    Apply-Tweak "Установка названия PowerBalanced" { Set-ItemProperty -Path $Balanced -Name "MUIVerb" -Value $TitleBal -Force *>&1 | Out-File -FilePath $global:LogPath -Append -Encoding UTF8 }
    Apply-Tweak "Установка иконки PowerBalanced" { Set-ItemProperty -Path $Balanced -Name "Icon" -Value "powercpl.dll,-506" -Force *>&1 | Out-File -FilePath $global:LogPath -Append -Encoding UTF8 }
    Apply-Tweak "Привязка скрипта к PowerBalanced" { Set-Item -Path "$Balanced\command" -Value "powershell.exe -WindowStyle Hidden -NoProfile -ExecutionPolicy Bypass -File `"$PowerScriptPath`" -Mode Balanced" -Force *>&1 | Out-File -FilePath $global:LogPath -Append -Encoding UTF8 }
}

