    $ToggleSpoolerPath = "$OptimizerDir\EastricaToggleSpooler.ps1"
    $ToggleSpoolerCode = @'
if (!([Security.Principal.WindowsPrincipal][Security.Principal.WindowsIdentity]::GetCurrent()).IsInRole([Security.Principal.WindowsBuiltInRole] "Administrator")) {
    Start-Process powershell.exe -ArgumentList "-NoProfile -ExecutionPolicy Bypass -WindowStyle Hidden -File `"$PSCommandPath`"" -Verb RunAs
    Exit
}
$wshell = New-Object -ComObject Wscript.Shell
$svc = Get-Service "Spooler" -ErrorAction SilentlyContinue

$global:IsRU = ((Get-UICulture).TwoLetterISOLanguageName -eq "ru")
function L ([string]$Ru, [string]$En) { if ($global:IsRU) { return $Ru } else { return $En } }
$MenuKey_Spooler = "Registry::HKEY_CLASSES_ROOT\Directory\Background\shell\EastricaToolsExtra\shell\02_ServicesMenu\shell\01_ToggleSpooler"

if ($svc) {
    if ($svc.StartType -eq "Disabled") {
        Set-Service "Spooler" -StartupType Automatic
        Start-Service "Spooler" -ErrorAction SilentlyContinue
        Set-ItemProperty -Path $MenuKey_Spooler -Name "MUIVerb" -Value (L "✔ Принтер (Включен)" "✔ Printer (Enabled)") -Force
        $wshell.Popup((L "Диспетчер печати (Принтер) включен" "Print Spooler (Printer) is enabled"), 3, (L "Службы" "Services"), 262208) | Out-Null
    } else {
        Stop-Service "Spooler" -Force -ErrorAction SilentlyContinue
        Set-Service "Spooler" -StartupType Disabled
        Set-ItemProperty -Path $MenuKey_Spooler -Name "MUIVerb" -Value (L "❌ Принтер (Выключен)" "❌ Printer (Disabled)") -Force
        $wshell.Popup((L "Диспетчер печати (Принтер) выключен" "Print Spooler (Printer) is disabled"), 3, (L "Службы" "Services"), 262208) | Out-Null
    }
}
'@
    Apply-Tweak "Создание скрипта тумблера Принтера" { Set-Content -Path $ToggleSpoolerPath -Value $ToggleSpoolerCode -Encoding UTF8 -Force }

    $MenuKey_Spooler = "$ServicesMenuShell\01_ToggleSpooler"
