    # Первичная проверка статуса
    $spoolerCurrentState = (Get-Service "Spooler" -ErrorAction SilentlyContinue).StartType
    if ($spoolerCurrentState -eq "Disabled") {
        $SpoolerInitialName = (L "❌ Принтер (Выключен)" "❌ Printer (Disabled)")
    } else {
        $SpoolerInitialName = (L "✔ Принтер (Включен)" "✔ Printer (Enabled)")
