        Set-ItemProperty -Path $MenuKey_Spooler -Name "Icon" -Value "shell32.dll,16" -Force *>&1 | Out-File -FilePath $global:LogPath -Append -Encoding UTF8
        Set-Item -Path "$MenuKey_Spooler\command" -Value "powershell.exe -WindowStyle Hidden -NoProfile -ExecutionPolicy Bypass -File `"$ToggleSpoolerPath`"" -Force *>&1 | Out-File -FilePath $global:LogPath -Append -Encoding UTF8
