        Set-Item -Path "$MenuKey_Bluetooth\command" -Value "powershell.exe -WindowStyle Hidden -NoProfile -ExecutionPolicy Bypass -File `"$ToggleBtPath`"" -Force *>&1 | Out-File -FilePath $global:LogPath -Append -Encoding UTF8
