$DnsScriptPath = "$OptimizerDir\EastricaSwitchDNS.ps1"
$DnsScriptCode = @'
param([string]$Mode)
if (!([Security.Principal.WindowsPrincipal][Security.Principal.WindowsIdentity]::GetCurrent()).IsInRole([Security.Principal.WindowsBuiltInRole] "Administrator")) {
    Start-Process powershell.exe -ArgumentList "-NoProfile -ExecutionPolicy Bypass -WindowStyle Hidden -File `"$PSCommandPath`" -Mode $Mode" -Verb RunAs
    Exit
}
$wshell = New-Object -ComObject Wscript.Shell

# 1. Разрешаем работу DoH и DoT в системе
Set-ItemProperty -Path "HKLM:\SYSTEM\CurrentControlSet\Services\Dnscache\Parameters" -Name "EnableAutoDoh" -Value 2 -Type DWord -Force -ErrorAction SilentlyContinue
Remove-ItemProperty -Path "HKLM:\SOFTWARE\Policies\Microsoft\Windows NT\DNSClient" -Name "DoHPolicy" -Force -ErrorAction SilentlyContinue
cmd.exe /c "netsh dns add global dot=yes >nul 2>&1"

# 2. Умный поиск активного сетевого адаптера
$DefaultRoute = Get-NetRoute -DestinationPrefix '0.0.0.0/0' -ErrorAction SilentlyContinue | Where-Object { $_.NextHop -ne '0.0.0.0' } | Sort-Object RouteMetric | Select-Object -First 1
$ActiveAdapter = if ($DefaultRoute) { Get-NetAdapter -InterfaceIndex $DefaultRoute.InterfaceIndex -ErrorAction SilentlyContinue } else { $null }

if (-not $ActiveAdapter) {
    $wshell.Popup("Активный интернет-адаптер не найден!", 3, "Ошибка сети", 16) | Out-Null
    exit
}

$guid = if ($ActiveAdapter.InterfaceGuid -match '^\{.*\}$') { $ActiveAdapter.InterfaceGuid } else { "{$($ActiveAdapter.InterfaceGuid)}" }

# Список веток групповых политик браузеров для принудительного включения/отключения DoH
$BrowserPolicies = @(
    "HKLM:\SOFTWARE\Policies\Google\Chrome",
    "HKLM:\SOFTWARE\Policies\Microsoft\Edge",
    "HKLM:\SOFTWARE\Policies\BraveSoftware\Brave"
)

function Clear-BrowserDoH {
    foreach ($bp in $BrowserPolicies) {
        if (Test-Path $bp) {
            Remove-ItemProperty -Path $bp -Name "DnsOverHttpsMode" -Force -ErrorAction SilentlyContinue
            Remove-ItemProperty -Path $bp -Name "DnsOverHttpsTemplates" -Force -ErrorAction SilentlyContinue
        }
    }
}

function Set-BrowserDoH ([string]$TemplateUrl) {
    foreach ($bp in $BrowserPolicies) {
        if (!(Test-Path $bp)) { New-Item -Path $bp -Force | Out-Null }
        Set-ItemProperty -Path $bp -Name "DnsOverHttpsMode" -Value "automatic" -Type String -Force -ErrorAction SilentlyContinue
        Set-ItemProperty -Path $bp -Name "DnsOverHttpsTemplates" -Value $TemplateUrl -Type String -Force -ErrorAction SilentlyContinue
    }
}

# Массив поддерживаемых провайдеров блокировки рекламы для браузеров (Цикл перебора)
$HybridProfiles = @(
        @{ Name = "Control D"; Template = "https://freedns.controld.com/p1";                  Match = "controld" },
        @{ Name = "AdGuard";   Template = "https://dns.adguard-dns.com/dns-query";            Match = "adguard" },
        @{ Name = "NextDNS";   Template = "https://dns.nextdns.io";                           Match = "nextdns" },
        @{ Name = "Mullvad";   Template = "https://adblock.doh.mullvad.net/dns-query";        Match = "mullvad" }
    )

    $NetMenuShell = "Registry::HKEY_CLASSES_ROOT\Directory\Background\shell\EastricaToolsExtra\shell\03_NetworkMenu\shell"
    $global:IsRU = ((Get-UICulture).TwoLetterISOLanguageName -eq "ru")
    function L ([string]$Ru, [string]$En) { if ($global:IsRU) { return $Ru } else { return $En } }

if ($Mode -eq "Hybrid") {
    # --------------------------------------------------------------------------
    # ЦИКЛИЧЕСКИЙ ГИБРИДНЫЙ РЕЖИМ: Перебор DoH-провайдеров + Мин. пинг для игр
    # --------------------------------------------------------------------------
    # Проверяем текущий активный шаблон в политике браузеров
    $CurrentBrowserTemplate = (Get-ItemProperty -Path "HKLM:\SOFTWARE\Policies\Google\Chrome" -Name "DnsOverHttpsTemplates" -ErrorAction SilentlyContinue).DnsOverHttpsTemplates

    $TargetIdx = 0
    if ($CurrentBrowserTemplate) {
        for ($i = 0; $i -lt $HybridProfiles.Count; $i++) {
            if ($CurrentBrowserTemplate -match $HybridProfiles[$i].Match) {
                # Переключаем на следующий по кругу
                $TargetIdx = ($i + 1) % $HybridProfiles.Count
                break
            }
        }
    }

    $SelectedProfile = $HybridProfiles[$TargetIdx]
    $SelectedName = $SelectedProfile.Name
    $SelectedTemplate = $SelectedProfile.Template

    # 1. Применяем выбранный DoH-шаблон блокировки рекламы в браузеры
    Set-BrowserDoH $SelectedTemplate

    # 2. Экспресс-замер задержки серверов для сетевой карты (выбор минимального пинга для игр)
    $Candidates = @(
        @{ Name = "Cloudflare"; IP1 = "1.1.1.1"; IP2 = "1.0.0.1"; Template = "https://cloudflare-dns.com/dns-query"; Host = "cloudflare-dns.com" },
        @{ Name = "Google";     IP1 = "8.8.8.8"; IP2 = "8.8.4.4"; Template = "https://dns.google/dns-query";           Host = "dns.google" },
        @{ Name = "Quad9";      IP1 = "9.9.9.9"; IP2 = "149.112.112.112"; Template = "https://dns.quad9.net/dns-query"; Host = "dns.quad9.net" },
        @{ Name = "Yandex";     IP1 = "77.88.8.8"; IP2 = "77.88.8.1"; Template = ""; Host = "" }
    )

    $BestCandidate = $Candidates[0]
    $LowestPing = 99999
    foreach ($c in $Candidates) {
        try {
            $p = New-Object System.Net.NetworkInformation.Ping
            $r = $p.Send($c.IP1, 600)
            if ($r.Status -eq 'Success' -and $r.RoundtripTime -lt $LowestPing) {
                $LowestPing = $r.RoundtripTime
                $BestCandidate = $c
            }
        } catch {}
    }

    $DNS = @($BestCandidate.IP1, $BestCandidate.IP2)
    Set-DnsClientServerAddress -InterfaceIndex $ActiveAdapter.InterfaceIndex -ServerAddresses $DNS

    if (-not [string]::IsNullOrWhiteSpace($BestCandidate.Template)) {
        foreach ($ip in $DNS) {
            Add-DnsClientDohServerAddress -ServerAddress $ip -DohTemplate $BestCandidate.Template -AllowFallbackToUdp $true -AutoUpgrade $true -ErrorAction SilentlyContinue
        }
        cmd.exe /c "netsh dns add encryption server=$($DNS[0]) dohtemplate=$($BestCandidate.Template) dothost=$($BestCandidate.Host) autoupgrade=yes udpfallback=yes >nul 2>&1"
        cmd.exe /c "netsh dns add encryption server=$($DNS[1]) dohtemplate=$($BestCandidate.Template) dothost=$($BestCandidate.Host) autoupgrade=yes udpfallback=yes >nul 2>&1"
    }

    ipconfig /flushdns > $null
    $wshell.Popup("Гибридный режим переключен на: [$SelectedName]!`nСетевая карта: $($BestCandidate.Name) ($LowestPing ms)`nБраузеры: $SelectedName DoH (AdBlock)", 5, "Сеть и DNS", 262208) | Out-Null

    # Сбрасываем названия остальных кнопок
    Set-ItemProperty -Path "$NetMenuShell\02_DnsGame" -Name "MUIVerb" -Value (L "Игровой DNS (Cloudflare)" "Gaming DNS (Cloudflare)") -Force -ErrorAction SilentlyContinue
    Set-ItemProperty -Path "$NetMenuShell\03_DnsAd" -Name "MUIVerb" -Value (L "DNS Без Рекламы (AdGuard)" "AdBlock DNS (AdGuard)") -Force -ErrorAction SilentlyContinue
    Set-ItemProperty -Path "$NetMenuShell\04_DnsQuad9" -Name "MUIVerb" -Value (L "Защитный DNS (Quad9)" "Security DNS (Quad9)") -Force -ErrorAction SilentlyContinue
    Set-ItemProperty -Path "$NetMenuShell\05_DnsDefault" -Name "MUIVerb" -Value (L "Сбросить DNS (По умолчанию)" "Reset DNS (Default)") -Force -ErrorAction SilentlyContinue

    # Выставляем активную галочку с указанием выбранного сервиса
    Set-ItemProperty -Path "$NetMenuShell\01_DnsHybrid" -Name "MUIVerb" -Value (L "✔ Гибридный DNS [$SelectedName]" "✔ Hybrid DNS [$SelectedName]") -Force -ErrorAction SilentlyContinue

} elseif ($Mode -eq "Gaming") {
    Clear-BrowserDoH
    $DNS = @("1.1.1.1", "1.0.0.1")
    $Template = "https://cloudflare-dns.com/dns-query"
    $DotHost = "cloudflare-dns.com"
    
    foreach ($ip in $DNS) {
        Add-DnsClientDohServerAddress -ServerAddress $ip -DohTemplate $Template -AllowFallbackToUdp $true -AutoUpgrade $true -ErrorAction SilentlyContinue
    }
    Set-DnsClientServerAddress -InterfaceIndex $ActiveAdapter.InterfaceIndex -ServerAddresses $DNS
    
    foreach ($ip in $DNS) {
        $regPath = "HKLM:\SYSTEM\CurrentControlSet\Services\Dnscache\InterfaceSpecificParameters\$guid\DohInterfaceSettings\Doh\$ip"
        if (!(Test-Path $regPath)) { New-Item -Path $regPath -Force | Out-Null }
        Set-ItemProperty -Path $regPath -Name "DohFlags" -Value 1 -Type Qword -Force
        Set-ItemProperty -Path $regPath -Name "DohTemplate" -Value $Template -Type String -Force
    }

    cmd.exe /c "netsh dns add encryption server=1.1.1.1 dohtemplate=$Template dothost=$DotHost autoupgrade=yes udpfallback=yes >nul 2>&1"
    cmd.exe /c "netsh dns set encryption server=1.1.1.1 dohtemplate=$Template dothost=$DotHost autoupgrade=yes udpfallback=yes >nul 2>&1"
    cmd.exe /c "netsh dns add encryption server=1.0.0.1 dohtemplate=$Template dothost=$DotHost autoupgrade=yes udpfallback=yes >nul 2>&1"
    cmd.exe /c "netsh dns set encryption server=1.0.0.1 dohtemplate=$Template dothost=$DotHost autoupgrade=yes udpfallback=yes >nul 2>&1"

    ipconfig /flushdns > $null
    $wshell.Popup("Режим Киберспорта активирован!`nАдаптер: $($ActiveAdapter.Name)`nDNS: Cloudflare (DoH + DoT)", 4, "Сеть", 262208) | Out-Null

    Set-ItemProperty -Path "$NetMenuShell\01_DnsHybrid" -Name "MUIVerb" -Value (L "Гибридный DNS (Цикл перебора)" "Hybrid DNS (Cycle Providers)") -Force -ErrorAction SilentlyContinue
    Set-ItemProperty -Path "$NetMenuShell\02_DnsGame" -Name "MUIVerb" -Value (L "✔ Игровой DNS (Cloudflare)" "✔ Gaming DNS (Cloudflare)") -Force -ErrorAction SilentlyContinue
    Set-ItemProperty -Path "$NetMenuShell\03_DnsAd" -Name "MUIVerb" -Value (L "DNS Без Рекламы (AdGuard)" "AdBlock DNS (AdGuard)") -Force -ErrorAction SilentlyContinue
    Set-ItemProperty -Path "$NetMenuShell\04_DnsQuad9" -Name "MUIVerb" -Value (L "Защитный DNS (Quad9)" "Security DNS (Quad9)") -Force -ErrorAction SilentlyContinue
    Set-ItemProperty -Path "$NetMenuShell\05_DnsDefault" -Name "MUIVerb" -Value (L "Сбросить DNS (По умолчанию)" "Reset DNS (Default)") -Force -ErrorAction SilentlyContinue

} elseif ($Mode -eq "AdBlock") {
    Clear-BrowserDoH
    $DNS = @("94.140.14.14", "94.140.15.15")
    $Template = "https://dns.adguard-dns.com/dns-query"
    $DotHost = "dns.adguard-dns.com"
    
    foreach ($ip in $DNS) {
        Add-DnsClientDohServerAddress -ServerAddress $ip -DohTemplate $Template -AllowFallbackToUdp $true -AutoUpgrade $true -ErrorAction SilentlyContinue
    }
    Set-DnsClientServerAddress -InterfaceIndex $ActiveAdapter.InterfaceIndex -ServerAddresses $DNS
    
    foreach ($ip in $DNS) {
        $regPath = "HKLM:\SYSTEM\CurrentControlSet\Services\Dnscache\InterfaceSpecificParameters\$guid\DohInterfaceSettings\Doh\$ip"
        if (!(Test-Path $regPath)) { New-Item -Path $regPath -Force | Out-Null }
        Set-ItemProperty -Path $regPath -Name "DohFlags" -Value 1 -Type Qword -Force
        Set-ItemProperty -Path $regPath -Name "DohTemplate" -Value $Template -Type String -Force
    }

    cmd.exe /c "netsh dns add encryption server=94.140.14.14 dohtemplate=$Template dothost=$DotHost autoupgrade=yes udpfallback=yes >nul 2>&1"
    cmd.exe /c "netsh dns set encryption server=94.140.14.14 dohtemplate=$Template dothost=$DotHost autoupgrade=yes udpfallback=yes >nul 2>&1"
    cmd.exe /c "netsh dns add encryption server=94.140.15.15 dohtemplate=$Template dothost=$DotHost autoupgrade=yes udpfallback=yes >nul 2>&1"
    cmd.exe /c "netsh dns set encryption server=94.140.15.15 dohtemplate=$Template dothost=$DotHost autoupgrade=yes udpfallback=yes >nul 2>&1"

    ipconfig /flushdns > $null
    $wshell.Popup("Блокировщик рекламы активирован!`nАдаптер: $($ActiveAdapter.Name)`nDNS: AdGuard (DoH + DoT)", 4, "Сеть", 262208) | Out-Null

    Set-ItemProperty -Path "$NetMenuShell\01_DnsHybrid" -Name "MUIVerb" -Value (L "Гибридный DNS (Цикл перебора)" "Hybrid DNS (Cycle Providers)") -Force -ErrorAction SilentlyContinue
    Set-ItemProperty -Path "$NetMenuShell\02_DnsGame" -Name "MUIVerb" -Value (L "Игровой DNS (Cloudflare)" "Gaming DNS (Cloudflare)") -Force -ErrorAction SilentlyContinue
    Set-ItemProperty -Path "$NetMenuShell\03_DnsAd" -Name "MUIVerb" -Value (L "✔ DNS Без Рекламы (AdGuard)" "✔ AdBlock DNS (AdGuard)") -Force -ErrorAction SilentlyContinue
    Set-ItemProperty -Path "$NetMenuShell\04_DnsQuad9" -Name "MUIVerb" -Value (L "Защитный DNS (Quad9)" "Security DNS (Quad9)") -Force -ErrorAction SilentlyContinue
    Set-ItemProperty -Path "$NetMenuShell\05_DnsDefault" -Name "MUIVerb" -Value (L "Сбросить DNS (По умолчанию)" "Reset DNS (Default)") -Force -ErrorAction SilentlyContinue

} elseif ($Mode -eq "Security") {
    Clear-BrowserDoH
    $DNS = @("9.9.9.9", "149.112.112.112")
    $Template = "https://dns.quad9.net/dns-query"
    $DotHost = "dns.quad9.net"
    
    foreach ($ip in $DNS) {
        Add-DnsClientDohServerAddress -ServerAddress $ip -DohTemplate $Template -AllowFallbackToUdp $true -AutoUpgrade $true -ErrorAction SilentlyContinue
    }
    Set-DnsClientServerAddress -InterfaceIndex $ActiveAdapter.InterfaceIndex -ServerAddresses $DNS
    
    foreach ($ip in $DNS) {
        $regPath = "HKLM:\SYSTEM\CurrentControlSet\Services\Dnscache\InterfaceSpecificParameters\$guid\DohInterfaceSettings\Doh\$ip"
        if (!(Test-Path $regPath)) { New-Item -Path $regPath -Force | Out-Null }
        Set-ItemProperty -Path $regPath -Name "DohFlags" -Value 1 -Type Qword -Force
        Set-ItemProperty -Path $regPath -Name "DohTemplate" -Value $Template -Type String -Force
    }

    cmd.exe /c "netsh dns add encryption server=9.9.9.9 dohtemplate=$Template dothost=$DotHost autoupgrade=yes udpfallback=yes >nul 2>&1"
    cmd.exe /c "netsh dns set encryption server=9.9.9.9 dohtemplate=$Template dothost=$DotHost autoupgrade=yes udpfallback=yes >nul 2>&1"
    cmd.exe /c "netsh dns add encryption server=149.112.112.112 dohtemplate=$Template dothost=$DotHost autoupgrade=yes udpfallback=yes >nul 2>&1"
    cmd.exe /c "netsh dns set encryption server=149.112.112.112 dohtemplate=$Template dothost=$DotHost autoupgrade=yes udpfallback=yes >nul 2>&1"

    ipconfig /flushdns > $null
    $wshell.Popup("Защитный режим активирован!`nАдаптер: $($ActiveAdapter.Name)`nDNS: Quad9 (DoH + DoT)", 4, "Сеть", 262208) | Out-Null

    Set-ItemProperty -Path "$NetMenuShell\01_DnsHybrid" -Name "MUIVerb" -Value (L "Гибридный DNS (Цикл перебора)" "Hybrid DNS (Cycle Providers)") -Force -ErrorAction SilentlyContinue
    Set-ItemProperty -Path "$NetMenuShell\02_DnsGame" -Name "MUIVerb" -Value (L "Игровой DNS (Cloudflare)" "Gaming DNS (Cloudflare)") -Force -ErrorAction SilentlyContinue
    Set-ItemProperty -Path "$NetMenuShell\03_DnsAd" -Name "MUIVerb" -Value (L "DNS Без Рекламы (AdGuard)" "AdBlock DNS (AdGuard)") -Force -ErrorAction SilentlyContinue
    Set-ItemProperty -Path "$NetMenuShell\04_DnsQuad9" -Name "MUIVerb" -Value (L "✔ Защитный DNS (Quad9)" "✔ Security DNS (Quad9)") -Force -ErrorAction SilentlyContinue
    Set-ItemProperty -Path "$NetMenuShell\05_DnsDefault" -Name "MUIVerb" -Value (L "Сбросить DNS (По умолчанию)" "Reset DNS (Default)") -Force -ErrorAction SilentlyContinue

} elseif ($Mode -eq "Default") {
    Clear-BrowserDoH
    Set-DnsClientServerAddress -InterfaceIndex $ActiveAdapter.InterfaceIndex -ResetServerAddresses
    
    $dohSettingsPath = "HKLM:\SYSTEM\CurrentControlSet\Services\Dnscache\InterfaceSpecificParameters\$guid\DohInterfaceSettings"
    if (Test-Path $dohSettingsPath) { Remove-Item -Path $dohSettingsPath -Recurse -Force -ErrorAction SilentlyContinue }

    ipconfig /flushdns > $null
    $wshell.Popup("Сетевые настройки сброшены.`nУстановлен DNS провайдера по умолчанию.", 4, "Сеть", 262208) | Out-Null

    Set-ItemProperty -Path "$NetMenuShell\01_DnsHybrid" -Name "MUIVerb" -Value (L "Гибридный DNS (Цикл перебора)" "Hybrid DNS (Cycle Providers)") -Force -ErrorAction SilentlyContinue
    Set-ItemProperty -Path "$NetMenuShell\02_DnsGame" -Name "MUIVerb" -Value (L "Игровой DNS (Cloudflare)" "Gaming DNS (Cloudflare)") -Force -ErrorAction SilentlyContinue
    Set-ItemProperty -Path "$NetMenuShell\03_DnsAd" -Name "MUIVerb" -Value (L "DNS Без Рекламы (AdGuard)" "AdBlock DNS (AdGuard)") -Force -ErrorAction SilentlyContinue
    Set-ItemProperty -Path "$NetMenuShell\04_DnsQuad9" -Name "MUIVerb" -Value (L "Защитный DNS (Quad9)" "Security DNS (Quad9)") -Force -ErrorAction SilentlyContinue
    Set-ItemProperty -Path "$NetMenuShell\05_DnsDefault" -Name "MUIVerb" -Value (L "✔ Сбросить DNS (По умолчанию)" "✔ Reset DNS (Default)") -Force -ErrorAction SilentlyContinue
}
'@
Apply-Tweak "Создание скрипта переключения DNS" { Set-Content -Path $DnsScriptPath -Value $DnsScriptCode -Encoding UTF8 -Force }

# Проверка текущего DNS для первичной расстановки галочек
$DefaultRoute = Get-NetRoute -DestinationPrefix '0.0.0.0/0' -ErrorAction SilentlyContinue | Where-Object { $_.NextHop -ne '0.0.0.0' } | Sort-Object RouteMetric | Select-Object -First 1
$ActiveAdapter = if ($DefaultRoute) { Get-NetAdapter -InterfaceIndex $DefaultRoute.InterfaceIndex -ErrorAction SilentlyContinue } else { $null }

# Очищаем старые кнопки меню перед созданием новых
Remove-Item -Path "$NetMenuShell\*" -Recurse -Force -ErrorAction SilentlyContinue

$CurrentDnsMode = "Default"
$CurrentBrowserDoH = (Get-ItemProperty -Path "HKLM:\SOFTWARE\Policies\Google\Chrome" -Name "DnsOverHttpsTemplates" -ErrorAction SilentlyContinue).DnsOverHttpsTemplates

$ActiveHybridName = "Control D"
if ($CurrentBrowserDoH) {
    $CurrentDnsMode = "Hybrid"
    if ($CurrentBrowserDoH -match "controld") { $ActiveHybridName = "Control D" }
    elseif ($CurrentBrowserDoH -match "adguard") { $ActiveHybridName = "AdGuard" }
    elseif ($CurrentBrowserDoH -match "nextdns") { $ActiveHybridName = "NextDNS" }
    elseif ($CurrentBrowserDoH -match "mullvad") { $ActiveHybridName = "Mullvad" }
} elseif ($ActiveAdapter) {
    $DnsServers = (Get-DnsClientServerAddress -InterfaceIndex $ActiveAdapter.InterfaceIndex -AddressFamily IPv4 -ErrorAction SilentlyContinue).ServerAddresses
    if ($DnsServers -contains "1.1.1.1") { $CurrentDnsMode = "Gaming" }
    elseif ($DnsServers -contains "94.140.14.14") { $CurrentDnsMode = "AdBlock" }
    elseif ($DnsServers -contains "9.9.9.9") { $CurrentDnsMode = "Security" }
}

$TitleHybrid = if ($CurrentDnsMode -eq "Hybrid")   { (L "✔ Гибридный DNS [$ActiveHybridName]" "✔ Hybrid DNS [$ActiveHybridName]") } else { (L "Гибридный DNS (Цикл перебора)" "Hybrid DNS (Cycle Providers)") }
$TitleGame   = if ($CurrentDnsMode -eq "Gaming")   { (L "✔ Игровой DNS (Cloudflare)" "✔ Gaming DNS (Cloudflare)") } else { (L "Игровой DNS (Cloudflare)" "Gaming DNS (Cloudflare)") }
$TitleAd     = if ($CurrentDnsMode -eq "AdBlock")  { (L "✔ DNS Без Рекламы (AdGuard)" "✔ AdBlock DNS (AdGuard)") } else { (L "DNS Без Рекламы (AdGuard)" "AdBlock DNS (AdGuard)") }
$TitleSec    = if ($CurrentDnsMode -eq "Security") { (L "✔ Защитный DNS (Quad9)" "✔ Security DNS (Quad9)") } else { (L "Защитный DNS (Quad9)" "Security DNS (Quad9)") }
$TitleDef    = if ($CurrentDnsMode -eq "Default")  { (L "✔ Сбросить DNS (По умолчанию)" "✔ Reset DNS (Default)") } else { (L "Сбросить DNS (По умолчанию)" "Reset DNS (Default)") }

# Кнопка 01: Циклический гибридный режим (Перебор DoH провайдеров + мин. пинг для сетевой карты)
$MenuKey_DnsHybrid = "$NetMenuShell\01_DnsHybrid"
if (!(Test-Path "$MenuKey_DnsHybrid\command")) { New-Item -Path "$MenuKey_DnsHybrid\command" -Force | Out-Null }
Apply-Tweak "Кнопка DNS Hybrid (Цикл)" { 
    Set-ItemProperty -Path $MenuKey_DnsHybrid -Name "MUIVerb" -Value $TitleHybrid -Force
    Set-ItemProperty -Path $MenuKey_DnsHybrid -Name "Icon" -Value "imageres.dll,-1028" -Force
    Set-Item -Path "$MenuKey_DnsHybrid\command" -Value "powershell.exe -WindowStyle Hidden -NoProfile -ExecutionPolicy Bypass -File `"$DnsScriptPath`" -Mode Hybrid" -Force
}

# Кнопка 02: Cloudflare (Gaming) -> Синий щит
$MenuKey_DnsGame = "$NetMenuShell\02_DnsGame"
if (!(Test-Path "$MenuKey_DnsGame\command")) { New-Item -Path "$MenuKey_DnsGame\command" -Force | Out-Null }
Apply-Tweak "Кнопка DNS Gaming" { 
    Set-ItemProperty -Path $MenuKey_DnsGame -Name "MUIVerb" -Value $TitleGame -Force
    Set-ItemProperty -Path $MenuKey_DnsGame -Name "Icon" -Value "SecurityHealthSystray.exe,0" -Force
    Set-Item -Path "$MenuKey_DnsGame\command" -Value "powershell.exe -WindowStyle Hidden -NoProfile -ExecutionPolicy Bypass -File `"$DnsScriptPath`" -Mode Gaming" -Force
}

# Кнопка 03: AdGuard (AdBlock) -> Зеленый щит
$MenuKey_DnsAd = "$NetMenuShell\03_DnsAd"
if (!(Test-Path "$MenuKey_DnsAd\command")) { New-Item -Path "$MenuKey_DnsAd\command" -Force | Out-Null }
Apply-Tweak "Кнопка DNS AdGuard" { 
    Set-ItemProperty -Path $MenuKey_DnsAd -Name "MUIVerb" -Value $TitleAd -Force
    Set-ItemProperty -Path $MenuKey_DnsAd -Name "Icon" -Value "imageres.dll,-106" -Force
    Set-Item -Path "$MenuKey_DnsAd\command" -Value "powershell.exe -WindowStyle Hidden -NoProfile -ExecutionPolicy Bypass -File `"$DnsScriptPath`" -Mode AdBlock" -Force
}

# Кнопка 04: Quad9 (Security) -> Красный щит
$MenuKey_DnsQuad9 = "$NetMenuShell\04_DnsQuad9"
if (!(Test-Path "$MenuKey_DnsQuad9\command")) { New-Item -Path "$MenuKey_DnsQuad9\command" -Force | Out-Null }
Apply-Tweak "Кнопка DNS Quad9" { 
    Set-ItemProperty -Path $MenuKey_DnsQuad9 -Name "MUIVerb" -Value $TitleSec -Force
    Set-ItemProperty -Path $MenuKey_DnsQuad9 -Name "Icon" -Value "imageres.dll,-105" -Force
    Set-Item -Path "$MenuKey_DnsQuad9\command" -Value "powershell.exe -WindowStyle Hidden -NoProfile -ExecutionPolicy Bypass -File `"$DnsScriptPath`" -Mode Security" -Force
}

# Кнопка 05: Сброс DNS (Default) -> Стрелка сброса
$MenuKey_DnsDef = "$NetMenuShell\05_DnsDefault"
if (!(Test-Path "$MenuKey_DnsDef\command")) { New-Item -Path "$MenuKey_DnsDef\command" -Force | Out-Null }
Apply-Tweak "Кнопка DNS Default" { 
    Set-ItemProperty -Path $MenuKey_DnsDef -Name "MUIVerb" -Value $TitleDef -Force
    Set-ItemProperty -Path $MenuKey_DnsDef -Name "Icon" -Value "shell32.dll,238" -Force
    Set-Item -Path "$MenuKey_DnsDef\command" -Value "powershell.exe -WindowStyle Hidden -NoProfile -ExecutionPolicy Bypass -File `"$DnsScriptPath`" -Mode Default" -Force
}

# ---------------------------------------------------------
# Кнопка: Варианты перезагрузки
# ---------------------------------------------------------
$MenuKey_Reboot = "$EastricaExtraShell\04_RebootMenu"
$RebootShell = "$MenuKey_Reboot\shell"

if (Test-Path $MenuKey_Reboot) { Remove-Item -Path $MenuKey_Reboot -Recurse -Force -ErrorAction SilentlyContinue }
if (!(Test-Path $MenuKey_Reboot)) { Apply-Tweak "Создание раздела подменю RebootMenu" { New-Item -Path $MenuKey_Reboot -Force | Out-Null } }
Apply-Tweak "Установка названия подменю RebootMenu" { Set-ItemProperty -Path $MenuKey_Reboot -Name "MUIVerb" -Value (L "Варианты перезагрузки" "Reboot Options") -Force *>&1 | Out-File -FilePath $global:LogPath -Append -Encoding UTF8 }
Apply-Tweak "Установка иконки подменю RebootMenu" { Set-ItemProperty -Path $MenuKey_Reboot -Name "Icon" -Value "shell32.dll,27" -Force *>&1 | Out-File -FilePath $global:LogPath -Append -Encoding UTF8 }
Apply-Tweak "Включение подкоманд для RebootMenu" { Set-ItemProperty -Path $MenuKey_Reboot -Name "SubCommands" -Value "" -Type String -Force *>&1 | Out-File -FilePath $global:LogPath -Append -Encoding UTF8 }
if (!(Test-Path $RebootShell)) { Apply-Tweak "Создание Shell для подменю RebootMenu" { New-Item -Path $RebootShell -Force | Out-Null } }

$RebootSafeMode = "$RebootShell\01_RebootToSafeMode"
if (!(Test-Path $RebootSafeMode)) { Apply-Tweak "Создание ключа RebootToSafeMode" { New-Item -Path $RebootSafeMode -Force | Out-Null } }
if (!(Test-Path "$RebootSafeMode\command")) { Apply-Tweak "Создание команды RebootToSafeMode" { New-Item -Path "$RebootSafeMode\command" -Force | Out-Null } }
Apply-Tweak "Установка названия RebootToSafeMode" { Set-ItemProperty -Path $RebootSafeMode -Name "MUIVerb" -Value (L "Перезагрузка в безопасный режим" "Reboot to Safe Mode") -Force *>&1 | Out-File -FilePath $global:LogPath -Append -Encoding UTF8 }
Apply-Tweak "Установка иконки RebootToSafeMode" { Set-ItemProperty -Path $RebootSafeMode -Name "Icon" -Value "msconfig.exe,0" -Force *>&1 | Out-File -FilePath $global:LogPath -Append -Encoding UTF8 }
$SafeModeRunCmd = 'powershell.exe -NoProfile -ExecutionPolicy Bypass -WindowStyle Hidden -Command "$ws = New-Object -ComObject Wscript.Shell; if ($ws.Popup(''Перезагрузить компьютер в БЕЗОПАСНЫЙ РЕЖИМ прямо сейчас?`n`nВсе несохраненные данные будут закрыты.'', 0, ''Безопасный режим'', 4 + 48) -eq 6) { bcdedit /set {current} safeboot network; reg add HKLM\Software\Microsoft\Windows\CurrentVersion\RunOnce /v *AutoRemoveSafeBoot /t REG_SZ /d ''cmd.exe /c bcdedit /deletevalue {current} safeboot'' /f; shutdown /r /f /t 00 }"'
Apply-Tweak "Привязка команды перезагрузки в Safe Mode" { Set-Item -Path "$RebootSafeMode\command" -Value $SafeModeRunCmd -Force *>&1 | Out-File -FilePath $global:LogPath -Append -Encoding UTF8 }

$RebootBios = "$RebootShell\02_RebootToBios"
if (!(Test-Path $RebootBios)) { Apply-Tweak "Создание ключа RebootToBios" { New-Item -Path $RebootBios -Force | Out-Null } }
if (!(Test-Path "$RebootBios\command")) { Apply-Tweak "Создание команды RebootToBios" { New-Item -Path "$RebootBios\command" -Force | Out-Null } }
Apply-Tweak "Установка названия RebootToBios" { Set-ItemProperty -Path $RebootBios -Name "MUIVerb" -Value (L "Перезагрузка в BIOS (UEFI)" "Reboot to BIOS (UEFI)") -Force *>&1 | Out-File -FilePath $global:LogPath -Append -Encoding UTF8 }
Apply-Tweak "Установка иконки RebootToBios" { Set-ItemProperty -Path $RebootBios -Name "Icon" -Value "shell32.dll,12" -Force *>&1 | Out-File -FilePath $global:LogPath -Append -Encoding UTF8 }
$BiosRunCmd = 'powershell.exe -NoProfile -ExecutionPolicy Bypass -WindowStyle Hidden -Command "$ws = New-Object -ComObject Wscript.Shell; if ($ws.Popup(''Перезагрузить компьютер в BIOS (UEFI) прямо сейчас?`n`nВсе несохраненные данные будут закрыты.'', 0, ''Вход в BIOS'', 4 + 48) -eq 6) { shutdown /r /fw /t 00; if ($LASTEXITCODE -ne 0) { shutdown /r /t 00 } }"'
Apply-Tweak "Привязка команды перезагрузки в BIOS" { Set-Item -Path "$RebootBios\command" -Value $BiosRunCmd -Force *>&1 | Out-File -FilePath $global:LogPath -Append -Encoding UTF8 }

