Apply-Tweak "Блокировка пункта 'Передать на устройство'" { Set-ItemProperty -Path $BlockedExt -Name "{7AD84985-87B4-4a16-BE58-8B72A5B390F7}" -Value "" -Type String -Force *>&1 | Out-File -FilePath $global:LogPath -Append -Encoding UTF8 } # Блокируем "Передать на устройство" (Cast to Device)
