Apply-Tweak "Блокировка пункта 'Share with Skype'" { Set-ItemProperty -Path $BlockedExt -Name "{776DBC8D-7347-478C-8D71-791E12EF49D8}" -Value "" -Type String -Force *>&1 | Out-File -FilePath $global:LogPath -Append -Encoding UTF8 } # Блокируем интеграцию Skype (Share with Skype)

