Apply-Tweak "Отключение тоста 'Фокусировка внимания включена'" { Set-ItemProperty -Path $FocusAssistToast -Name "Enabled" -Value 0 -Type DWord -Force *>&1 | Out-File -FilePath $global:LogPath -Append -Encoding UTF8 } # 0 = Убираем тост "Фокусировка внимания включена"

