if (!(Test-Path $GameBarSettings)) { Apply-Tweak "Создание раздела GameBar" { New-Item -Path $GameBarSettings -Force *>&1 | Out-File -FilePath $global:LogPath -Append -Encoding UTF8 } } # Создаем
