$SearchTaskbar = "HKCU:\Software\Microsoft\Windows\CurrentVersion\Search" # Ветка поиска
if (!(Test-Path $SearchTaskbar)) { Apply-Tweak "Создание раздела Search" { New-Item -Path $SearchTaskbar -Force *>&1 | Out-File -FilePath $global:LogPath -Append -Encoding UTF8 } } # Создаем
