Apply-Tweak "Запрет сбора ваших опечаток и словаря" { Set-ItemProperty -Path $TextInput -Name "AllowLinguisticDataCollection" -Value 0 -Type DWord -Force *>&1 | Out-File -FilePath $global:LogPath -Append -Encoding UTF8 } # 0 = Запрет сбора ваших опечаток и словаря

