$Attachments = "HKCU:\Software\Microsoft\Windows\CurrentVersion\Policies\Attachments" # Ветка вложений
if (!(Test-Path $Attachments)) { Apply-Tweak "Создание раздела Attachments Policy" { New-Item -Path $Attachments -Force *>&1 | Out-File -FilePath $global:LogPath -Append -Encoding UTF8 } } # Создаем
Apply-Tweak "Запрет скрытых меток безопасности скачанных файлов (Zone.Identifier)" { Set-ItemProperty -Path $Attachments -Name "SaveZoneInformation" -Value 2 -Type DWord -Force *>&1 | Out-File -FilePath $global:LogPath -Append -Encoding UTF8 } # 2 = Не сохранять информацию о том, что файл скачан из Интернета (Избавляет от табличек "Файл может быть опасен")

