Apply-Tweak "Жесткий запрет функции Autorun" { Set-ItemProperty -Path $PolExplorer -Name "NoAutorun" -Value 1 -Type DWord -Force *>&1 | Out-File -FilePath $global:LogPath -Append -Encoding UTF8 } # 1 = Жесткий запрет функции Autorun

# Включение автоматического обновления корневых сертификатов
