Apply-Tweak "Разрешение автоматического обновления корневых сертификатов" { Set-ItemProperty -Path $CertPath -Name "DisableRootAutoUpdate" -Value 0 -Type DWord -Force *>&1 | Out-File -FilePath $global:LogPath -Append -Encoding UTF8 } # 0 = РАЗРЕШАЕМ автообновление (Критично для работы HTTPS, Магазина и Игр)

# Жесткое отключение Windows Copilot (ИИ-помощника в панели задач)
$CopilotPolUser = "HKCU:\Software\Policies\Microsoft\Windows\WindowsCopilot" # Блокировка Copilot для текущего пользователя и локальной машины
$CopilotPolMach = "HKLM:\SOFTWARE\Policies\Microsoft\Windows\WindowsCopilot"

foreach ($Path in @($CopilotPolUser, $CopilotPolMach)) {
