    Apply-Tweak "Выключение и скрытие Copilot (TurnOffWindowsCopilot)" { Set-ItemProperty -Path $Path -Name "TurnOffWindowsCopilot" -Value 1 -Type DWord -Force *>&1 | Out-File -FilePath $global:LogPath -Append -Encoding UTF8 } # 1 = Выключаем и скрываем Copilot
}

$WindowsAI = "HKLM:\SOFTWARE\Policies\Microsoft\Windows\WindowsAI"
if (!(Test-Path $WindowsAI)) { Apply-Tweak "Создание раздела WindowsAI" { New-Item $WindowsAI -Force *>&1 | Out-File -FilePath $global:LogPath -Append -Encoding UTF8 } }
Apply-Tweak "Отключение службы Recall и фонового ИИ-анализа данных" { Set-ItemProperty -Path $WindowsAI -Name "DisableAIDataAnalysis" -Value 1 -Type DWord -Force *>&1 | Out-File -FilePath $global:LogPath -Append -Encoding UTF8 } # Отключение Windows AI (Служба Recall и фоновый анализ данных)

# Физическое удаление UWP-приложения Copilot (Windows 11 24H2+)
Apply-Tweak "Физическое удаление приложения Copilot" { Get-AppxPackage -Name "*Microsoft.Windows.Ai.Copilot.Provider*" -AllUsers 2>> $env:SystemDrive\EastricaTools\Eastrica_ErrorTrace.log | Remove-AppxPackage -AllUsers *>&1 | Out-File -FilePath $global:LogPath -Append -Encoding UTF8 }

Write-Host ""
# ==============================================================================
# Раздел 62: Отклик интерфейса (UX/UI Latency) и оптимизация GDI
# ==============================================================================
Show-ProgressStep -StepNum 62 -TotalSteps 81 -Activity "Оптимизация отклика интерфейса (UX/UI Latency) и GDI..."
Write-Host "==============================================================================" -ForegroundColor DarkGray
Write-Host "РАЗДЕЛ 62: ОТКЛИК ИНТЕРФЕЙСА (UX/UI LATENCY) И ОПТИМИЗАЦИЯ GDI" -ForegroundColor Cyan
Write-Host "==============================================================================" -ForegroundColor DarkGray
$Desktop = "HKCU:\Control Panel\Desktop" # Системные настройки рабочего стола
Apply-Tweak "100% качество обоев рабочего стола (JPEGImportQuality)" { Set-ItemProperty -Path $Desktop -Name "JPEGImportQuality" -Value 100 -Type DWord -Force *>&1 | Out-File -FilePath $global:LogPath -Append -Encoding UTF8 } # 100 = Не сжимать качество обоев рабочего стола
Apply-Tweak "Увеличенная защита перехвата фокуса ввода во время игры (ForegroundLockTimeout=400000)" { Set-ItemProperty -Path $Desktop -Name "ForegroundLockTimeout" -Value 400000 -Type DWord -Force *>&1 | Out-File -FilePath $global:LogPath -Append -Encoding UTF8 } # 400000 мс (400 секунд). Если поставить здесь 0, фоновые программы получат право мгновенно воровать фокус (выбивать вас из игры на рабочий стол). Значение 400000 строго запрещает перехват фокуса.
Apply-Tweak "Минимальная задержка меню (MenuShowDelay=8мс)" { Set-ItemProperty -Path $Desktop -Name "MenuShowDelay" -Value 8 -Type String -Force *>&1 | Out-File -FilePath $global:LogPath -Append -Encoding UTF8 } # 8 мс = Задержка перед открытием выпадающих меню (Почти мгновенно, но защищает от ложных срабатываний)
Apply-Tweak "Автоматическое убийство зависших программ при выключении (AutoEndTasks)" { Set-ItemProperty -Path $Desktop -Name "AutoEndTasks" -Value 1 -Type String -Force *>&1 | Out-File -FilePath $global:LogPath -Append -Encoding UTF8 } # 1 = Автоматически убивать зависшие программы при выключении ПК
Apply-Tweak "5 сек ожидания закрытия программ (WaitToKillAppTimeout)" { Set-ItemProperty -Path $Desktop -Name "WaitToKillAppTimeout" -Value 5000 -Type String -Force *>&1 | Out-File -FilePath $global:LogPath -Append -Encoding UTF8 } # 5 сек = Время ожидания закрытия программ перед выключением ПК
Apply-Tweak "6 сек до объявления программы зависшей (HungAppTimeout)" { Set-ItemProperty -Path $Desktop -Name "HungAppTimeout" -Value 6000 -Type String -Force *>&1 | Out-File -FilePath $global:LogPath -Append -Encoding UTF8 } # 6 сек = Время, после которого программа считается зависшей (Не отвечает)
Apply-Tweak "Удаление таймаута низкоуровневых хуков" { Remove-ItemProperty -Path $Desktop -Name "LowLevelHooksTimeout" *>&1 | Out-File -FilePath $global:LogPath -Append -Encoding UTF8 } # Возвращаем стандартный системный буфер (5000 мс)
Apply-Tweak "Удаление отмены сброса ввода (BlockSendInputResets)" { Remove-ItemProperty -Path $Desktop -Name "BlockSendInputResets" *>&1 | Out-File -FilePath $global:LogPath -Append -Encoding UTF8 } # Убираем самодельную модификацию таблицы ввода, которой по умолчанию в чистой Windows вообще не существует.
Apply-Tweak "Мгновенное отслеживание активного окна (ActiveWndTrkTimeout=0)" { Set-ItemProperty -Path $Desktop -Name "ActiveWndTrkTimeout" -Value 0 -Type DWord -Force *>&1 | Out-File -FilePath $global:LogPath -Append -Encoding UTF8 } # 0 = Мгновенное отслеживание активного окна
Apply-Tweak "Отключение мигания кнопок панели задач (ForegroundFlashCount=0)" { Set-ItemProperty -Path $Desktop -Name "ForegroundFlashCount" -Value 0 -Type DWord -Force *>&1 | Out-File -FilePath $global:LogPath -Append -Encoding UTF8 } # 0 = Отключаем мигание кнопок в панели задач
Apply-Tweak "Скорость побега мыши с монитора (MouseMonitorEscapeSpeed=1)" { Set-ItemProperty -Path $Desktop -Name "MouseMonitorEscapeSpeed" -Value 1 -Type DWord -Force *>&1 | Out-File -FilePath $global:LogPath -Append -Encoding UTF8 } # 1 = Скорость побега мыши с монитора (Для мультимониторов)
Apply-Tweak "Включение Aero Snap (WindowArrangementActive=1)" { Set-ItemProperty -Path $Desktop -Name "WindowArrangementActive" -Value "1" -Type String -Force *>&1 | Out-File -FilePath $global:LogPath -Append -Encoding UTF8 } # 0 = Включение Aero Snap

if ($global:OptAI) {
    Apply-Tweak "Безопасный таймаут служб (WaitToKillServiceTimeout = 10000)" { Set-ItemProperty -Path "HKLM:\SYSTEM\CurrentControlSet\Control" -Name "WaitToKillServiceTimeout" -Value "10000" -Type String -Force *>&1 | Out-File -FilePath $global:LogPath -Append -Encoding UTF8 } # 10 сек для сохранения БД Docker/WSL
} else {
    Apply-Tweak "Быстрое убивание системных служб (WaitToKillServiceTimeout = 5000)" { Set-ItemProperty -Path "HKLM:\SYSTEM\CurrentControlSet\Control" -Name "WaitToKillServiceTimeout" -Value "5000" -Type String -Force *>&1 | Out-File -FilePath $global:LogPath -Append -Encoding UTF8 } # 5 сек для игр
}

# Восстановление пакетирования 2D-интерфейса (GDI).
$WinNT = "HKLM:\SOFTWARE\Microsoft\Windows NT\CurrentVersion\Windows" # Ветка Windows
Apply-Tweak "Удаление мусорного твика GDIProcessHandleQuota" { Remove-ItemProperty -Path $WinNT -Name "GDIProcessHandleQuota" *>&1 | Out-File -FilePath $global:LogPath -Append -Encoding UTF8 } # Удаление твика
Apply-Tweak "Удаление мусорного твика GdiBatchLimit" { Remove-ItemProperty -Path $WinNT -Name "GdiBatchLimit" *>&1 | Out-File -FilePath $global:LogPath -Append -Encoding UTF8 } # Удаление твика

# [GUI] Аппаратное ускорение 2D графики (GDI+ to Direct2D Hardware Promotion)
$Direct2D = "HKLM:\SOFTWARE\Microsoft\Direct2D" # Ветка Direct2D
if (!(Test-Path $Direct2D)) { Apply-Tweak "Создание раздела Direct2D" { New-Item $Direct2D -Force *>&1 | Out-File -FilePath $global:LogPath -Append -Encoding UTF8 } } # Создаем
if ($global:IsMultiMonitor) {
    Apply-Tweak "Отключение принудительного рендера 2D видеокартой (Защита DWM)" { Remove-ItemProperty -Path $Direct2D -Name "EnableGdiDxgiSurface" *>&1 | Out-File -FilePath $global:LogPath -Append -Encoding UTF8 }
    Apply-Tweak "Отключение многопоточности GDI/DXGI (Защита DWM)" { Remove-ItemProperty -Path $Direct2D -Name "EnableMultithreadedGdiDxgiSurface" *>&1 | Out-File -FilePath $global:LogPath -Append -Encoding UTF8 }
} else {
    Apply-Tweak "Аппаратный рендер 2D-графики видеокартой (EnableGdiDxgiSurface)" { Set-ItemProperty -Path $Direct2D -Name "EnableGdiDxgiSurface" -Value 1 -Type DWord -Force *>&1 | Out-File -FilePath $global:LogPath -Append -Encoding UTF8 }
    Apply-Tweak "Многопоточность для конвейера GDI/DXGI" { Set-ItemProperty -Path $Direct2D -Name "EnableMultithreadedGdiDxgiSurface" -Value 1 -Type DWord -Force *>&1 | Out-File -FilePath $global:LogPath -Append -Encoding UTF8 }
}

Write-Host ""
# ==============================================================================
# Раздел 63: Оптимизация для нейросетей и среды ИИ (Python, ComfyUI, WSL2)
# ==============================================================================
Show-ProgressStep -StepNum 63 -TotalSteps 81 -Activity "Применение элитных оптимизаций для нейросетей и Python..."
Write-Host "==============================================================================" -ForegroundColor DarkGray
Write-Host "РАЗДЕЛ 63: ОПТИМИЗАЦИЯ ДЛЯ НЕЙРОСЕТЕЙ И СРЕДЫ ИИ (PYTHON, COMFYUI, WSL2)" -ForegroundColor Cyan
Write-Host "==============================================================================" -ForegroundColor DarkGray
if ($global:OptAI) {
    # Разрешение выполнения PowerShell скриптов (Активация Python venv без ошибок политики)
    Apply-Tweak "Разрешение выполнения PowerShell скриптов (Bypass)" { Set-ExecutionPolicy -ExecutionPolicy Bypass -Scope CurrentUser -Force *>&1 | Out-File -FilePath $global:LogPath -Append -Encoding UTF8 }

    # Отключение перехвата команд Python встроенным Microsoft Store (App Execution Aliases)
    $PythonAliasDir = "HKCU:\SOFTWARE\Classes\Local Settings\Software\Microsoft\Windows\CurrentVersion\AppModel\SystemAppData\Microsoft.DesktopAppInstaller_8wekyb3d8bbwe\AppAliases"
    if (!(Test-Path $PythonAliasDir)) { Apply-Tweak "Создание раздела AppAliases" { New-Item -Path $PythonAliasDir -Force *>&1 | Out-File -FilePath $global:LogPath -Append -Encoding UTF8 } }
    Apply-Tweak "Отключение перехвата python.exe в Store" { Set-ItemProperty -Path $PythonAliasDir -Name "python.exe" -Value 0 -Type DWord -Force *>&1 | Out-File -FilePath $global:LogPath -Append -Encoding UTF8 } # 0 = Store больше не перехватывает команду python
    Apply-Tweak "Отключение перехвата python3.exe в Store" { Set-ItemProperty -Path $PythonAliasDir -Name "python3.exe" -Value 0 -Type DWord -Force *>&1 | Out-File -FilePath $global:LogPath -Append -Encoding UTF8 } # 0 = Store больше не перехватывает команду python3

    # Создание инвариантных путей кэша (Anti-Cyrillic & Anti-Space Fix)
    # Изолирует компиляторы PyTorch и Triton от кириллицы и пробелов в %USERPROFILE%.
    $SafeAICache = "$env:SystemDrive\AI_Cache"
    if (!(Test-Path "$SafeAICache\torch")) { Apply-Tweak "Создание папки кэша Torch ($SafeAICache\torch)" { New-Item -ItemType Directory -Force -Path "$SafeAICache\torch" *>&1 | Out-File -FilePath $global:LogPath -Append -Encoding UTF8 } } # Папка кэша Torch
    if (!(Test-Path "$SafeAICache\triton")) { Apply-Tweak "Создание папки кэша Triton ($SafeAICache\triton)" { New-Item -ItemType Directory -Force -Path "$SafeAICache\triton" *>&1 | Out-File -FilePath $global:LogPath -Append -Encoding UTF8 } } # Папка кэша Triton

    # Режим разработчика (Symlinks) + Снятие лимита длинных путей (260 символов)
    Apply-Tweak "Снятие лимита длинных путей (LongPathsEnabled)" { Set-ItemProperty -Path "HKLM:\SYSTEM\CurrentControlSet\Control\FileSystem" -Name "LongPathsEnabled" -Value 1 -Type DWord -Force *>&1 | Out-File -FilePath $global:LogPath -Append -Encoding UTF8 } # 1 = Снимаем лимит длины путей
    $DevMode = "HKLM:\SOFTWARE\Microsoft\Windows\CurrentVersion\AppModelUnlock"
    if (!(Test-Path $DevMode)) { Apply-Tweak "Создание раздела Developer Mode" { New-Item -Path $DevMode -Force *>&1 | Out-File -FilePath $global:LogPath -Append -Encoding UTF8 } }
    Apply-Tweak "Включение Developer Mode (DevLicense)" { Set-ItemProperty -Path $DevMode -Name "AllowDevelopmentWithoutDevLicense" -Value 1 -Type DWord -Force *>&1 | Out-File -FilePath $global:LogPath -Append -Encoding UTF8 }
    Apply-Tweak "Включение доверенных приложений (TrustedApps)" { Set-ItemProperty -Path $DevMode -Name "AllowAllTrustedApps" -Value 1 -Type DWord -Force *>&1 | Out-File -FilePath $global:LogPath -Append -Encoding UTF8 }

    # Разблокировка полной матрицы кросс-дисковых символических ссылок
    Apply-Tweak "Разрешение кросс-дисковых симлинков" { cmd /c "fsutil behavior set SymlinkEvaluation L2L:1 R2R:1 L2R:1 R2L:1" *>&1 | Out-File -FilePath $global:LogPath -Append -Encoding UTF8 } # Разрешает симлинки между разными дисками (C: > D:)

    # Квантование контекста Ollama (революция для LLM)
    Apply-Tweak "Квантование кэша Ollama до 8-бит (q8_0)" { [Environment]::SetEnvironmentVariable("OLLAMA_KV_CACHE_TYPE", "q8_0", "Machine") } # Сжимает кэш контекста диалога в 8-бит (q8_0), экономя 1-2 ГБ VRAM практически без потери качества

    # Защита от CUDA paging (зависаний при переполнении VRAM)
    Apply-Tweak "Удержание аллокаций в GPU VRAM (CUDA Force Device Alloc)" { [Environment]::SetEnvironmentVariable("CUDA_MANAGED_FORCE_DEVICE_ALLOC", "1", "Machine") } # Заставляет CUDA держать аллокации на GPU до последнего, избегая падения скорости генерации в 30 раз

    # Фикс загрузки CPU при использовании 2+ видеокарт (PyTorch / NCCL)
    Apply-Tweak "Запрет spin-polling процессора в PyTorch (NCCL Blocking Wait)" { [Environment]::SetEnvironmentVariable("TORCH_NCCL_BLOCKING_WAIT", "1", "Machine") } # Запрещает CPU крутиться в бесконечном цикле (spin-polling), разгружая 1 ядро с 100% до 0%

    # Обход искусственных ограничений Intel MKL для процессоров AMD Ryzen
    Apply-Tweak "Маскировка Ryzen под Intel для MKL" { [Environment]::SetEnvironmentVariable("MKL_DEBUG_CPU_TYPE", "5", "Machine") } # Заставляет библиотеку MKL считать процессор Intel-чипом
    Apply-Tweak "Принудительное включение инструкций AVX2 на Ryzen (MKL)" { [Environment]::SetEnvironmentVariable("MKL_ENABLE_INSTRUCTIONS", "AVX2", "Machine") } # Принудительно включает векторные инструкции AVX2 на Ryzen
    Apply-Tweak "Отключение спама предупреждениями OpenMP" { [Environment]::SetEnvironmentVariable("KMP_WARNINGS", "0", "Machine") } # Отключает спам предупреждениями OpenMP

    # Агрессивная оптимизация VRAM (NVIDIA / PyTorch)
    Apply-Tweak "Оптимизация сегментации и выделения VRAM (PyTorch)" { [Environment]::SetEnvironmentVariable("PYTORCH_CUDA_ALLOC_CONF", "expandable_segments:True,garbage_collection_threshold:0.8,max_split_size_mb:512,roundup_power2_divisions:16,pinned_use_cuda_host_register:True", "Machine") } # Включает асинхронный аллокатор cudaMallocAsync и сегментацию памяти

    # ComfyUI / Python стабильность
    Apply-Tweak "Защита от молчаливого вылета консоли ComfyUI" { [Environment]::SetEnvironmentVariable("KMP_DUPLICATE_LIB_OK", "TRUE", "Machine") } # Защита от молчаливого вылета консоли при конфликте нодов
    Apply-Tweak "Использование системного SDK компиляции (DISTUTILS)" { [Environment]::SetEnvironmentVariable("DISTUTILS_USE_SDK", "1", "Machine") } # Исправление ошибок компиляции кастомных нодов
    Apply-Tweak "Увеличение таймаутов загрузки моделей (HuggingFace)" { [Environment]::SetEnvironmentVariable("HF_HUB_HTTP_RETRIES", "5", "Machine") } # Увеличение таймаутов загрузки моделей из HuggingFace
    Apply-Tweak "Ленивая загрузка модулей CUDA (Экономия VRAM)" { [Environment]::SetEnvironmentVariable("CUDA_MODULE_LOADING", "LAZY", "Machine") } # Ленивая загрузка модулей CUDA (Экономит видеопамять)
    Apply-Tweak "Включение ускоренного API cuDNN v8 (PyTorch)" { [Environment]::SetEnvironmentVariable("TORCH_CUDNN_V8_API_ENABLED", "1", "Machine") } # Включает ускоренный v8 API cuDNN
    Apply-Tweak "Увеличение кэша компилятора CUDA до 10 ГБ" { [Environment]::SetEnvironmentVariable("CUDA_CACHE_MAXSIZE", "10737418240", "Machine") } # 10 ГБ кэша для компилятора CUDA

    # Оптимизация сети Hugging Face под гигантские веса (Защита от обрывов на 20GB+ файлах)
    Apply-Tweak "Увеличение таймаута загрузки весов HF до 10 минут" { [Environment]::SetEnvironmentVariable("HF_HUB_DOWNLOAD_TIMEOUT", "600", "Machine") }
    Apply-Tweak "Увеличение таймаута ETag Hugging Face" { [Environment]::SetEnvironmentVariable("HF_HUB_ETAG_TIMEOUT", "60", "Machine") }

    # Отключение фонового троттлинга CUDA при погасшем мониторе (Для ночных генераций)
    Apply-Tweak "Запрет сброса частот CUDA при отключении дисплея" { 
        powercfg /setacvalueindex scheme_current SUB_VIDEO VIDEOIDLE 0 *>&1 | Out-File -FilePath $global:LogPath -Append -Encoding UTF8
        powercfg /setacvalueindex scheme_current SUB_NONE CONSOLELOCK 0 *>&1 | Out-File -FilePath $global:LogPath -Append -Encoding UTF8
    }

    # Подавление мусорных логов компилятора TorchDynamo (Разгрузка диска от спама)
    Apply-Tweak "Отключение отладочного мусора TorchDynamo" { [Environment]::SetEnvironmentVariable("TORCH_COMPILE_DEBUG", "0", "Machine") }
    Apply-Tweak "Глушение логов Torch JIT" { [Environment]::SetEnvironmentVariable("TORCH_LOGS", "-all", "Machine") }

    # Активация режима Persistence Mode (Мгновенный старт инференса без лага инициализации)
    $NvidiaSmiPath = "$env:ProgramFiles\NVIDIA Corporation\NVSMI\nvidia-smi.exe"
    if (Test-Path $NvidiaSmiPath) {
        Apply-Tweak "Активация режима постоянства драйвера (nvidia-smi Persistence Mode)" { & $NvidiaSmiPath -pm 1 *>&1 | Out-File -FilePath $global:LogPath -Append -Encoding UTF8 }
    }

    # Оптимизация Vulkan для нейросетей на AMD Radeon
    Apply-Tweak "Фиксация первой видеокарты для Vulkan AI" { [Environment]::SetEnvironmentVariable("GGML_VK_VISIBLE_DEVICES", "0", "Machine") }
    Apply-Tweak "Запрет фрагментации VRAM в Vulkan AI" { [Environment]::SetEnvironmentVariable("GGML_VK_FORCE_MAX_ALLOCATION", "1", "Machine") }

    # Оптимизация DirectML (Снятие ограничений памяти для Microsoft ML)
    Apply-Tweak "Снятие лимитов DirectML аллокаций" { [Environment]::SetEnvironmentVariable("DML_VISIBLE_DEVICES", "0", "Machine") }

    # Оптимизация для AMD ROCm / HIP
    Apply-Tweak "Снятие лимита на выделение памяти AMD ROCm" { [Environment]::SetEnvironmentVariable("GPU_MAX_ALLOC_PERCENT", "100", "Machine") } # Снимает лимит на выделение памяти AMD
    Apply-Tweak "Принудительная компиляция ядер HIP" { [Environment]::SetEnvironmentVariable("HIP_FORCE_DEV_KERNARG", "1", "Machine") }

    # Тюнинг процессора для Llama.cpp / GGUF
    $PhysicalCores = ($global:ProcInfo).NumberOfCores
    Apply-Tweak "Ограничение потоков OpenMP физическими ядрами ($PhysicalCores)" { [Environment]::SetEnvironmentVariable("OMP_NUM_THREADS", "$PhysicalCores", "Machine") } # Ограничиваем OpenMP числом физических ядер
    Apply-Tweak "Запрет сна потоков OpenMP (KMP_BLOCKTIME=0)" { [Environment]::SetEnvironmentVariable("KMP_BLOCKTIME", "0", "Machine") } # 0 = Потоки не засыпают между генерацией токенов
    Apply-Tweak "Жесткая привязка потоков KMP (Affinity)" { [Environment]::SetEnvironmentVariable("KMP_AFFINITY", "granularity=fine,compact,1,0", "Machine") } # Жесткая привязка потоков
    Apply-Tweak "Отключение унифицированной памяти CUDA (GGML)" { [Environment]::SetEnvironmentVariable("GGML_CUDA_ENABLE_UNIFIED_MEMORY", "0", "Machine") }
    Apply-Tweak "Активная политика ожидания OpenMP" { [Environment]::SetEnvironmentVariable("OMP_WAIT_POLICY", "ACTIVE", "Machine") }
    Apply-Tweak "Запрет миграции потоков OpenMP на E-Cores" { [Environment]::SetEnvironmentVariable("OMP_PROC_BIND", "true", "Machine") } # Запрещает Windows кидать потоки инференса на E-Cores
    Apply-Tweak "8 параллельных потоков вычислений CUDA" { [Environment]::SetEnvironmentVariable("CUDA_DEVICE_MAX_CONNECTIONS", "8", "Machine") } # 8 параллельных потоков вычислений
    Apply-Tweak "Включение Flash Attention для Ollama" { [Environment]::SetEnvironmentVariable("OLLAMA_FLASH_ATTENTION", "1", "Machine") } # Включает Flash Attention для Ollama
    Apply-Tweak "Разрешение 4 параллельных диалогов Ollama" { [Environment]::SetEnvironmentVariable("OLLAMA_NUM_PARALLEL", "4", "Machine") } # Разрешает 4 параллельных диалога
    Apply-Tweak "Отключение багованного Triton в xFormers" { [Environment]::SetEnvironmentVariable("XFORMERS_FORCE_DISABLE_TRITON", "1", "Machine") } # Отключает багованный Triton для Windows в xFormers
    Apply-Tweak "Отключение телеметрии Ray" { [Environment]::SetEnvironmentVariable("RAY_DISABLE_TELEMETRY", "1", "Machine") } # Отключает телеметрии Ray
    Apply-Tweak "Отключение предупреждений симлинков HuggingFace" { [Environment]::SetEnvironmentVariable("HF_HUB_DISABLE_SYMLINKS_WARNING", "1", "Machine") }
    Apply-Tweak "Перенос JIT-кэша CUDA на инвариантный путь ($SafeAICache\cuda)" { [Environment]::SetEnvironmentVariable("CUDA_CACHE_PATH", "$SafeAICache\cuda", "Machine") } # Переносит JIT-кэш на чистый путь
    Apply-Tweak "Запрет создания дампов VRAM при OutOfMemory" { [Environment]::SetEnvironmentVariable("CUDA_ENABLE_COREDUMP_ON_EXCEPTION", "0", "Machine") } # Запрет создания дампов VRAM при OutOfMemory
    Apply-Tweak "Ограничение уровня логов OpenCV" { [Environment]::SetEnvironmentVariable("OPENCV_LOG_LEVEL", "ERROR", "Machine") }
    Apply-Tweak "Удержание 75% L2 кэша GPU для ускорения Ingestion" { [Environment]::SetEnvironmentVariable("CUDA_DEVICE_DEFAULT_PERSISTING_L2_CACHE_PERCENTAGE", "75", "Machine") } # Держит 75% L2 кэша GPU для ускорения Prompt Ingestion
    Apply-Tweak "Сортировка видеокарт по шине PCIe" { [Environment]::SetEnvironmentVariable("CUDA_DEVICE_ORDER", "PCI_BUS_ID", "Machine") } # Сортировка видеокарт по шине PCIe
    Apply-Tweak "Включение прямого DMA обмена (P2P) между 2+ GPU" { [Environment]::SetEnvironmentVariable("NCCL_P2P_DISABLE", "0", "Machine") } # Прямой обмен данными между 2+ GPU (Direct DMA)
    Apply-Tweak "Установка P2P уровня (NCCL)" { [Environment]::SetEnvironmentVariable("NCCL_P2P_LEVEL", "5", "Machine") }
    Apply-Tweak "Установка GDR уровня (NCCL)" { [Environment]::SetEnvironmentVariable("NCCL_NET_GDR_LEVEL", "5", "Machine") }
    Apply-Tweak "Включение Infiniband (NCCL)" { [Environment]::SetEnvironmentVariable("NCCL_IB_DISABLE", "0", "Machine") }

    if (!(Test-Path "$SafeAICache\inductor")) { Apply-Tweak "Создание папки кэша TorchInductor" { New-Item -ItemType Directory -Force -Path "$SafeAICache\inductor" *>&1 | Out-File -FilePath $global:LogPath -Append -Encoding UTF8 } }
    Apply-Tweak "Перенос кэша TorchInductor ($SafeAICache\inductor)" { [Environment]::SetEnvironmentVariable("TORCHINDUCTOR_CACHE_DIR", "$SafeAICache\inductor", "Machine") } # Кэш TorchInductor

    # Установка Ninja Build (Многопоточный компилятор C++ модулей для PyTorch)
    $NinjaDir = "$env:LOCALAPPDATA\Ninja"
    $NinjaPath = "$NinjaDir\ninja.exe"
    if (!(Test-Path $NinjaPath)) {
        Write-Host "Установка компилятора Ninja для ускорения PyTorch..." -ForegroundColor DarkGray
        try {
            if (!(Test-Path $NinjaDir)) { Apply-Tweak "Создание папки Ninja" { New-Item -ItemType Directory -Force -Path $NinjaDir | Out-Null } }
            $NinjaUrl = "https://github.com/ninja-build/ninja/releases/latest/download/ninja-win.zip"
            $NinjaZip = "$env:TEMP\ninja.zip"
            Apply-Tweak "Скачивание компилятора Ninja" { Download-File-Safe -Url $NinjaUrl -Output $NinjaZip }
            Apply-Tweak "Распаковка компилятора Ninja" { Expand-Archive -Path $NinjaZip -DestinationPath $NinjaDir -Force -ErrorAction Stop }
            Apply-Tweak "Удаление архива Ninja" { Remove-Item $NinjaZip -Force }
            $CurrentPath = [Environment]::GetEnvironmentVariable("PATH", "User")
            if ($CurrentPath -notmatch [regex]::Escape($NinjaDir)) {
                Apply-Tweak "Добавление Ninja в системную переменную PATH" { [Environment]::SetEnvironmentVariable("PATH", "$CurrentPath;$NinjaDir", "User") }
            }
        } catch { Write-Warning "Не удалось скачать Ninja. Компиляция Python будет идти в 1 поток." }
    }

    $SafeJobsByRam = [math]::Floor($global:TotalRAM / 2)
    $FinalJobs = [math]::Min($PhysicalCores, $SafeJobsByRam)
    if ($FinalJobs -lt 1) { $FinalJobs = 1 }
    Apply-Tweak "Установка $FinalJobs потоков сборки Ninja" { [Environment]::SetEnvironmentVariable("NINJA_FLAGS", "-j$FinalJobs", "Machine") } # Выделяем 1 поток Ninja на каждые 2 ГБ ОЗУ
    Apply-Tweak "Установка глобального лимита потоков сборки" { [Environment]::SetEnvironmentVariable("MAX_JOBS", "$FinalJobs", "Machine") } # Лимит потоков сборки
    Apply-Tweak "ROCm нативное отпределение карт AMD" { [Environment]::SetEnvironmentVariable("HSA_OVERRIDE_GFX_VERSION", $null, "Machine") } # ROCm определит карту нативно
    Apply-Tweak "Сброс ограничений видеокарт CUDA" { [Environment]::SetEnvironmentVariable("CUDA_VISIBLE_DEVICES", $null, "Machine") } # Сбрасываем ограничения видеокарт
    Apply-Tweak "Сброс ограничений видеокарт HIP" { [Environment]::SetEnvironmentVariable("HIP_VISIBLE_DEVICES", $null, "Machine") }
    # Apply-Tweak "Удержание модели Ollama в VRAM 30 сек" { [Environment]::SetEnvironmentVariable("OLLAMA_KEEP_ALIVE", "30s", "Machine") } # Держит модель в VRAM 30 секунд
    Apply-Tweak "Прямая загрузка safetensors в GPU" { [Environment]::SetEnvironmentVariable("SAFETENSORS_FAST_GPU", "1", "Machine") } # Прямая загрузка safetensors в GPU
    Apply-Tweak "Включение Rust-загрузчика HuggingFace (hf_transfer)" { [Environment]::SetEnvironmentVariable("HF_HUB_ENABLE_HF_TRANSFER", "1", "Machine") } # Включает скоростной загрузчик Rust для HuggingFace

    if (Get-Command pip 2>> $env:SystemDrive\EastricaTools\Eastrica_ErrorTrace.log) {
        Write-Host "Установка модуля hf_transfer для сверхбыстрой загрузки ИИ моделей..." -ForegroundColor DarkGray
        Apply-Tweak "Установка пакета hf_transfer через pip" { cmd /c "pip install hf_transfer --quiet --upgrade" *>&1 | Out-File -FilePath $global:LogPath -Append -Encoding UTF8 }
    }

    # Отключение телеметрии фреймворков ИИ
    Apply-Tweak "Отключение телеметрии Python" { [Environment]::SetEnvironmentVariable("PYTHONUNBUFFERED", "0", "Machine") }
    Apply-Tweak "Отключение телеметрии HuggingFace" { [Environment]::SetEnvironmentVariable("HF_HUB_DISABLE_TELEMETRY", "1", "Machine") }
    Apply-Tweak "Отключение аналитики Gradio" { [Environment]::SetEnvironmentVariable("GRADIO_ANALYTICS_ENABLED", "False", "Machine") }
    Apply-Tweak "Включение DO_NOT_TRACK" { [Environment]::SetEnvironmentVariable("DO_NOT_TRACK", "1", "Machine") }
    Apply-Tweak "Отключение анонимной телеметрии" { [Environment]::SetEnvironmentVariable("ANONYMIZED_TELEMETRY", "False", "Machine") }
    Apply-Tweak "Глобальное отключение телеметрии (DISABLE_TELEMETRY)" { [Environment]::SetEnvironmentVariable("DISABLE_TELEMETRY", "1", "Machine") }
    Apply-Tweak "Включение TensorRT FP16 в ONNX" { [Environment]::SetEnvironmentVariable("ORT_TENSORRT_FP16_ENABLE", "1", "Machine") } # Включает TensorRT FP16 в ONNX Runtime
    Apply-Tweak "Включение кэша движка TensorRT в ONNX" { [Environment]::SetEnvironmentVariable("ORT_TENSORRT_ENGINE_CACHE_ENABLE", "1", "Machine") }
    Apply-Tweak "Быстрое разрешение зависимостей pip" { [Environment]::SetEnvironmentVariable("PIP_USE_FEATURE", "fast-deps", "Machine") }
    Apply-Tweak "Отключение дублирования кэша pip" { [Environment]::SetEnvironmentVariable("PIP_NO_CACHE_DIR", "1", "Machine") } # Не сохранять дубликаты пакетов wheel
    Apply-Tweak "Удаление инструкций assert на лету (Python Optimize)" { [Environment]::SetEnvironmentVariable("PYTHONOPTIMIZE", "1", "Machine") } # Удаляет инструкции assert на лету (ускоряет Python)
    Apply-Tweak "Отключение проверок версий pip" { [Environment]::SetEnvironmentVariable("PIP_DISABLE_PIP_VERSION_CHECK", "1", "Machine") }
    Apply-Tweak "Установка OMP_MAX_ACTIVE_LEVELS=1" { [Environment]::SetEnvironmentVariable("OMP_MAX_ACTIVE_LEVELS", "1", "Machine") }
    Apply-Tweak "Включение oneDNN оптимизаций TensorFlow" { [Environment]::SetEnvironmentVariable("TF_ENABLE_ONEDNN_OPTS", "1", "Machine") } # oneDNN оптимизации TensorFlow
    Apply-Tweak "Скрытие welcome сообщений bitsandbytes" { [Environment]::SetEnvironmentVariable("BITSANDBYTES_NOWELCOME", "1", "Machine") }
    Apply-Tweak "Включение cuDNN Scaled Dot Product Attention" { [Environment]::SetEnvironmentVariable("TORCH_CUDNN_SDPA_ENABLED", "1", "Machine") } # cuDNN Scaled Dot Product Attention
    Apply-Tweak "Установка жестких ссылок для менеджера UV" { [Environment]::SetEnvironmentVariable("UV_LINK_MODE", "hardlink", "Machine") } # Менеджер UV использует жесткие ссылки
    Apply-Tweak "Перенос кэша менеджера UV" { [Environment]::SetEnvironmentVariable("UV_CACHE_DIR", "$SafeAICache\uv", "Machine") }
    Apply-Tweak "Параллелизм токенизаторов" { [Environment]::SetEnvironmentVariable("TOKENIZERS_PARALLELISM", "true", "Machine") }
    Apply-Tweak "Конфигурация рабочего пространства cuBLAS" { [Environment]::SetEnvironmentVariable("CUBLAS_WORKSPACE_CONFIG", ":4096:8", "Machine") } # Включает детерминированные алгоритмы в NVIDIA cuBLAS. Без этого параметра PyTorch/ComfyUI могут выдавать слегка разные картинки при одном и том же Seed из-за ошибок округления плавающей запятой в асинхронных потоках.
    Apply-Tweak "Отключение телеметрии cuDNN Frontend" { [Environment]::SetEnvironmentVariable("CUDNN_FRONTEND_NOTELEMETRY", "1", "Machine") }
    Apply-Tweak "Открытие порта Ollama для LAN и Docker" { [Environment]::SetEnvironmentVariable("OLLAMA_HOST", "0.0.0.0", "Machine") } # Открывает порт Ollama для локальной сети и Docker
    Apply-Tweak "Перенос папки расширений PyTorch" { [Environment]::SetEnvironmentVariable("TORCH_EXTENSIONS_DIR", "$SafeAICache\torch", "Machine") }
    Apply-Tweak "Перенос кэша Triton" { [Environment]::SetEnvironmentVariable("TRITON_CACHE_DIR", "$SafeAICache\triton", "Machine") }

    # Белый список форматов ИИ (Снимает предупреждения SmartScreen)
    $LowRiskTypes = "HKCU:\Software\Microsoft\Windows\CurrentVersion\Policies\Associations"
    if (!(Test-Path $LowRiskTypes)) { Apply-Tweak "Создание раздела Associations Policy" { New-Item -Path $LowRiskTypes -Force *>&1 | Out-File -FilePath $global:LogPath -Append -Encoding UTF8 } }
    $CurrentLowRisk = (Get-ItemProperty -Path $LowRiskTypes -Name "LowRiskFileTypes" 2>> $env:SystemDrive\EastricaTools\Eastrica_ErrorTrace.log).LowRiskFileTypes
    $AITypes = ".safetensors;.gguf;.pt;.pth;.bin;.onnx;.tensorrt"
    if ($CurrentLowRisk) {
        if ($CurrentLowRisk -notmatch "\.safetensors") {
            $NewLowRisk = "$CurrentLowRisk;$AITypes"
            Apply-Tweak "Добавление форматов ИИ в белый список SmartScreen" { Set-ItemProperty -Path $LowRiskTypes -Name "LowRiskFileTypes" -Value $NewLowRisk -Type String -Force *>&1 | Out-File -FilePath $global:LogPath -Append -Encoding UTF8 }
        }
    } else {
        Apply-Tweak "Создание белого списка SmartScreen для форматов ИИ" { Set-ItemProperty -Path $LowRiskTypes -Name "LowRiskFileTypes" -Value $AITypes -Type String -Force *>&1 | Out-File -FilePath $global:LogPath -Append -Encoding UTF8 }
    }
    
    Apply-Tweak "Добавление кэша ИИ в исключения Защитника Windows" { Add-MpPreference -ExclusionPath $SafeAICache *>&1 | Out-File -FilePath $global:LogPath -Append -Encoding UTF8 } # Добавляем кэш в исключения Defender
    try {
        $item = Get-Item -LiteralPath $SafeAICache -ErrorAction Stop
        if (($item.Attributes -band [System.IO.FileAttributes]::NotContentIndexed) -ne [System.IO.FileAttributes]::NotContentIndexed) {
            Apply-Tweak "Отключение индексации кэша ИИ" { $item.Attributes = $item.Attributes -bor [System.IO.FileAttributes]::NotContentIndexed } # Отключаем индексацию кэша ИИ
        }
    } catch {}

    # Настройка Jumbo Frames (MTU 9000) для внутренней сети WSL2/Docker
    $WslAdapter = Get-NetAdapter | Where-Object { $_.Name -match "WSL|vEthernet" -or $_.InterfaceDescription -match "WSL" } | Select-Object -First 1
    if ($null -ne $WslAdapter) {
        Apply-Tweak "Включение Jumbo Frames (MTU 9000) для WSL/Docker ($($WslAdapter.Name))" { cmd /c "netsh interface ipv4 set subinterface `"$($WslAdapter.Name)`" mtu=9000 store=persistent >nul 2>&1" } # Увеличивает скорость передачи тензоров между Windows и WSL в 6 раз
    }

    # Аппаратное ускорение сети внутри LINUX-контейнеров (WSL2 / DOCKER)
    Write-Host " ► Оптимизация виртуального коммутатора Hyper-V для ИИ..." -ForegroundColor DarkGray
    # Включаем Receive Segment Coalescing (RSC) аппаратно для виртуального свитча.
    # Это ускоряет скачивание гигантских ИИ-моделей внутри Docker/WSL в 2-3 раза, снижая нагрузку на CPU.
    try {
        if (Get-Command Get-VMSwitch -ErrorAction SilentlyContinue 2>> $env:SystemDrive\EastricaTools\Eastrica_ErrorTrace.log) {
            Get-VMSwitch 2>> $env:SystemDrive\EastricaTools\Eastrica_ErrorTrace.log | ForEach-Object {
                Apply-Tweak "Включение RSC на коммутаторе Hyper-V ($($_.Name))" { Set-VMSwitch -Name $_.Name -EnableSoftwareRsc $true *>&1 | Out-File -FilePath $global:LogPath -Append -Encoding UTF8 }
            }
        }
        # Включаем RSC на виртуальных сетевых адаптерах ОС
        Get-NetAdapter | Where-Object { $_.InterfaceDescription -match "Hyper-V|vEthernet" } | ForEach-Object {
            Apply-Tweak "Включение RSC IPv4 на $($_.Name)" { Enable-NetAdapterRsc -Name $_.Name -IPv4 *>&1 | Out-File -FilePath $global:LogPath -Append -Encoding UTF8 }
            Apply-Tweak "Включение RSC IPv6 на $($_.Name)" { Enable-NetAdapterRsc -Name $_.Name -IPv6 *>&1 | Out-File -FilePath $global:LogPath -Append -Encoding UTF8 }
        }
    } catch { }

    # Разблокировка локальных API (HTTP.sys) для AI-агентов
    $HttpParams = "HKLM:\SYSTEM\CurrentControlSet\Services\HTTP\Parameters"
    if (!(Test-Path $HttpParams)) { Apply-Tweak "Создание раздела HTTP Parameters" { New-Item $HttpParams -Force *>&1 | Out-File -FilePath $global:LogPath -Append -Encoding UTF8 } }
    Apply-Tweak "Отключение лимитов скорости запросов HTTP.sys" { Set-ItemProperty -Path $HttpParams -Name "EnableConnectionRateLimiting" -Value 0 -Type DWord -Force *>&1 | Out-File -FilePath $global:LogPath -Append -Encoding UTF8 } # 0 = Отключаем лимиты скорости запросов
    Apply-Tweak "Увеличение лимита одновременных подключений HTTP.sys до 100000" { Set-ItemProperty -Path $HttpParams -Name "MaxConnections" -Value 100000 -Type DWord -Force *>&1 | Out-File -FilePath $global:LogPath -Append -Encoding UTF8 } # 100000 одновременных подключений

    # Оптимизация Git и ускорение скачивания весов моделей через Git LFS (16 параллельных потоков)
    if (Get-Command git 2>> $env:SystemDrive\EastricaTools\Eastrica_ErrorTrace.log) {
        Apply-Tweak "Настройка Git: длинные пути" { cmd /c "git config --global core.longpaths true" *>&1 | Out-File -FilePath $global:LogPath -Append -Encoding UTF8 }
        Apply-Tweak "Настройка Git: кэш файловой системы" { cmd /c "git config --global core.fscache true" *>&1 | Out-File -FilePath $global:LogPath -Append -Encoding UTF8 }
        Apply-Tweak "Настройка Git: символические ссылки" { cmd /c "git config --global core.symlinks true" *>&1 | Out-File -FilePath $global:LogPath -Append -Encoding UTF8 }
        Apply-Tweak "Ускорение Git LFS для HuggingFace (16 потоков скачивания)" { cmd /c "git config --global lfs.concurrenttransfers 16" *>&1 | Out-File -FilePath $global:LogPath -Append -Encoding UTF8 }
    }

    # Приоритеты и Large Pages для ИИ-процессов
    $AIApps = @("python.exe", "pythonw.exe", "llama-server.exe", "main.exe", "ollama.exe", "comfyui.exe", "lmstudio.exe", "docker.exe", "node.exe", "vmmem.exe", "vmmemWSL.exe", "wslservice.exe", "com.docker.backend.exe", "com.docker.proxy.exe")

    # Интерактивный выбор кастомных процессов ИИ (цикл для выбора из разных папок по очереди)
    Write-Host ""
    Write-Host "Используете нестандартные ИИ-движки (кроме Ollama, ComfyUI, LM Studio)?" -ForegroundColor Magenta # Вопрос пользователю
    Write-Host "Выберите их .exe файлы, чтобы выдать им высший приоритет и Large Pages." -ForegroundColor White # Инструкция
    Write-Host "(Можно выбирать файлы по очереди из разных папок. Когда закончите — нажмите 'Отмена')" -ForegroundColor DarkGray

    while ($true) {
        $CustomAIFiles = Show-FileDialog-STA -Title "Выберите .exe файл ИИ-сервера (Нажмите 'Отмена', если закончили)" -Filter "Исполняемые файлы (*.exe)|*.exe" -MultiSelect
        
        # Если пользователь нажал "Отмена" или закрыл окно — выходим из цикла
        if ($null -eq $CustomAIFiles -or $CustomAIFiles.Count -eq 0) {
            break
        }

        foreach ($file in $CustomAIFiles) {
            $exeName = [System.IO.Path]::GetFileName($file)
            if ($AIApps -notcontains $exeName) {
                $AIApps += $exeName # Добавляем процесс в общий список на оптимизацию
                Write-Host " ► Добавлен кастомный процесс: $exeName" -ForegroundColor Cyan
            }
        }
    }

    foreach ($App in $AIApps) {
        $BaseAppPath = "HKLM:\SOFTWARE\Microsoft\Windows NT\CurrentVersion\Image File Execution Options\$App"
        $PerfPath = "$BaseAppPath\PerfOptions"
        if (!(Test-Path $PerfPath)) { Apply-Tweak "Создание IFEO для процесса ИИ ($App)" { New-Item -Path $PerfPath -Force *>&1 | Out-File -FilePath $global:LogPath -Append -Encoding UTF8 } }
        # Для python.exe оставляем обычный приоритет (2), чтобы тяжелые DataLoader'ы не вешали систему, а для Ollama и llama-server можно оставить High (3).
        $PrioVal = if ($App -match "python") { 2 } else { 3 }
        Apply-Tweak "Приоритет CPU для ИИ ($App)" { Set-ItemProperty -Path $PerfPath -Name "CpuPriorityClass" -Value $PrioVal -Type DWord -Force }
        Apply-Tweak "Высокий приоритет I/O для ИИ ($App)" { Set-ItemProperty -Path $PerfPath -Name "IoPriority" -Value 3 -Type DWord -Force } # 3 = High I/O
        Apply-Tweak "Использование Large Pages для ИИ ($App)" { Set-ItemProperty -Path $PerfPath -Name "UseLargePages" -Value 1 -Type DWord -Force } # 1 = Large Pages
        try { Apply-Tweak "Отключение Exploit Protection для ИИ ($App)" { Set-ProcessMitigation -Name $App -Disable CFG, SEHOP, ForceRelocateImages, StrictHandle *>&1 | Out-File -FilePath $global:LogPath -Append -Encoding UTF8 } } catch {}
    }

    # Динамический расчет памяти и конфигурация WSL2 (.wslconfig) с исправлением DNS и systemd
    $WslRamGB = [math]::Round($global:TotalRAM * 0.80)
    if ($WslRamGB -lt 4) { $WslRamGB = 4 }
    $wslConfigPath = "$env:USERPROFILE\.wslconfig"
    if (-not (Test-Path $wslConfigPath)) {
        $wslContent = @"
[wsl2]
memory=${WslRamGB}GB
autoMemoryReclaim=dropcache
idleThreshold=10000 
pageReporting=true
transparent_hugepage=always
networkingMode=mirrored
dnsTunneling=true
guiApplications=false
processors=0
swap=0

[experimental]
sparseVhd=true
autoProxy=true

[boot]
systemd=true
"@
        Apply-Tweak "Создание конфигурации WSL2 (.wslconfig)" { Set-Content -Path $wslConfigPath -Value $wslContent -Encoding UTF8 -Force *>&1 | Out-File -FilePath $global:LogPath -Append -Encoding UTF8 }
    }

    # Исключения и запрет сжатия для каталогов ИИ
    $RealUserProfile = $env:USERPROFILE
    if ($RealUserProfile -match "system32") {
        $User = (Get-CimInstance Win32_ComputerSystem).UserName
        if (-not [string]::IsNullOrWhiteSpace($User) -and $User.Contains('\')) {
            $RealUserProfile = "$env:SystemDrive\Users\$($User.Split('\')[1])"
        } else {
            # Резервный путь, если активного пользователя в данный момент нет
            $RealUserProfile = "$env:SystemDrive\Users\Default" 
        }
    }
    $RealLocalAppData = "$RealUserProfile\AppData\Local"
    $AiDirs = @("$RealUserProfile\.cache", "$RealUserProfile\.ollama", "$RealUserProfile\.lmstudio", "$RealUserProfile\.triton", "$RealLocalAppData\pip")
    foreach ($dir in $AiDirs) {
        if (!(Test-Path $dir)) { Apply-Tweak "Создание каталога ИИ ($dir)" { New-Item -ItemType Directory -Force -Path $dir *>&1 | Out-File -FilePath $global:LogPath -Append -Encoding UTF8 } }
        Apply-Tweak "Исключение каталога ИИ в Defender ($dir)" { Add-MpPreference -ExclusionPath $dir *>&1 | Out-File -FilePath $global:LogPath -Append -Encoding UTF8 }
        try {
            $item = Get-Item -LiteralPath $dir -ErrorAction Stop
            if (($item.Attributes -band [System.IO.FileAttributes]::NotContentIndexed) -ne [System.IO.FileAttributes]::NotContentIndexed) {
                Apply-Tweak "Отключение индексации каталога ИИ ($dir)" { $item.Attributes = $item.Attributes -bor [System.IO.FileAttributes]::NotContentIndexed } # Отключаем индексацию
            }
            Apply-Tweak "Отключение сжатия каталога ИИ ($dir)" { cmd.exe /c "compact /u /s:`"$dir`" /i /q >nul 2>&1" } # Отключаем сжатие папки
            Apply-Tweak "Отключение шифрования каталога ИИ ($dir)" { cmd.exe /c "cipher /d /s:`"$dir`" /i /q >nul 2>&1" }  # Отключаем шифрование папки
        } catch {}
    }

    # Интерактивный выбор папок с моделями для исключений
    if ([Environment]::UserInteractive -and $env:USERNAME -ne "SYSTEM" -and -not $Unattended) {
        Write-Host ""
        Write-Host "Хотите добавить кастомные папки с ИИ-моделями (GGUF/Safetensors) в исключения?" -ForegroundColor Magenta
        Write-Host "Это отключит сканирование Защитником и индексацию (Критично ускоряет загрузку в VRAM)." -ForegroundColor DarkGray
        Write-Host "(Можно выбирать по очереди. Когда закончите - нажмите 'Отмена')" -ForegroundColor DarkGray

    $AISelectedFolders = @() # Инициализируем пустой массив для выбранных папок
    while ($true) { # Бесконечный цикл, пока пользователь не нажмет "Отмена"
        # Используем нашу безопасную STA-функцию для выбора папок
        $FolderPath = Show-FolderBrowser-STA -Title "Выберите папку с моделями ИИ (или нажмите 'Отмена', если закончили)"
        
        if ([string]::IsNullOrWhiteSpace($FolderPath)) {
            break # Выход из цикла, если ничего не выбрано или окно закрыто
        }
        
        # Автоматическая нормализация корневых дисков через безопасное сложение строк (защита от ошибок путей)
        if ($FolderPath -match '^[a-zA-Z]$') {
            $FolderPath = $FolderPath + ":\" # Если выбрана просто буква диска (например, D), добавляем :\
        } elseif ($FolderPath -match '^[a-zA-Z]:$') {
            $FolderPath = $FolderPath + "\" # Если выбрано D:, добавляем \
        }
        
        if ($AISelectedFolders -notcontains $FolderPath) {
            $AISelectedFolders += $FolderPath # Добавляем путь в массив
            Write-Host " ► Добавлена папка ИИ: $FolderPath" -ForegroundColor Cyan
        }
    }

    # Если массив с папками не пуст
    if ($AISelectedFolders.Count -gt 0) {
        foreach ($dir in $AISelectedFolders) {
            Apply-Tweak "Исключение папки ИИ в Defender ($dir)" { Add-MpPreference -ExclusionPath $dir *>&1 | Out-File -FilePath $global:LogPath -Append -Encoding UTF8 } # Добавляем папку в белый список Защитника Windows
            try {
                $item = Get-Item -LiteralPath $dir -ErrorAction Stop # Получаем свойства папки
                # Если папка индексируется, снимаем атрибут (отключаем сканирование службой SearchIndexer)
                if (($item.Attributes -band [System.IO.FileAttributes]::NotContentIndexed) -ne [System.IO.FileAttributes]::NotContentIndexed) {
                    Apply-Tweak "Отключение индексации папки ИИ ($dir)" { $item.Attributes = $item.Attributes -bor [System.IO.FileAttributes]::NotContentIndexed }
                }
            } catch {}
            
            # Аппаратный запрет сжатия и шифрования папки для максимальной скорости чтения NVMe
            try {
                Apply-Tweak "Отключение сжатия папки ИИ ($dir)" { cmd.exe /c "compact /u /s:`"$dir`" /i /q >nul 2>&1" } # Выключаем файловое сжатие (Compression) в папке и подпапках
                Apply-Tweak "Отключение шифрования папки ИИ ($dir)" { cmd.exe /c "cipher /d /s:`"$dir`" /i /q >nul 2>&1" }  # Выключаем файловое шифрование (Encryption)
                
                # Ставим атрибут нормального файла (принудительно снимаем флаги сжатия)
                    $dirInfo = Get-Item -LiteralPath $dir 2>> $env:SystemDrive\EastricaTools\Eastrica_ErrorTrace.log
                    if ($dirInfo) {
                        Apply-Tweak "Снятие флагов сжатия с папки ИИ ($dir)" { $dirInfo.Attributes = $dirInfo.Attributes -band -bnot [System.IO.FileAttributes]::Compressed }
                    }
                } catch {}
            }
        }
    } else {
        Write-Host " ► Автоматический режим (Session 0 / SYSTEM). Выбор папок ИИ пропущен." -ForegroundColor DarkGray
    }
    
    Apply-Tweak "Исключение форматов ИИ в Defender" { Add-MpPreference -ExclusionExtension ".vhdx", ".vhd", ".gguf", ".safetensors", ".pt", ".bin", ".onnx", ".tensorrt" *>&1 | Out-File -FilePath $global:LogPath -Append -Encoding UTF8 } # Исключаем расширения ИИ
    Apply-Tweak "Исключение процессов ИИ в Defender" { Add-MpPreference -ExclusionProcess "python.exe", "ollama.exe", "llama-server.exe", "docker.exe", "node.exe", "cl.exe", "cmake.exe", "ninja.exe", "git.exe", "rustc.exe", "cargo.exe", "link.exe" *>&1 | Out-File -FilePath $global:LogPath -Append -Encoding UTF8 }

    # Кнопка быстрой очистки памяти ИИ в меню Eastrica Tools
    $AiMenuKey = "HKCR:\Directory\Background\shell\EastricaTools\shell\00_AIFlush"
    if (!(Test-Path $AiMenuKey)) { Apply-Tweak "Создание кнопки AIFlush в меню" { New-Item -Path $AiMenuKey -Force *>&1 | Out-File -FilePath $global:LogPath -Append -Encoding UTF8 } }
    Apply-Tweak "Установка названия кнопки AIFlush" { Set-ItemProperty -Path $AiMenuKey -Name "MUIVerb" -Value (L "Остановить ИИ и очистить память" "Stop AI and Flush Memory") -Force *>&1 | Out-File -FilePath $global:LogPath -Append -Encoding UTF8 }
    Apply-Tweak "Установка иконки кнопки AIFlush" { Set-ItemProperty -Path $AiMenuKey -Name "Icon" -Value "shell32.dll,12" -Force *>&1 | Out-File -FilePath $global:LogPath -Append -Encoding UTF8 }
    $AiCmdKey = "$AiMenuKey\command"
    if (!(Test-Path $AiCmdKey)) { Apply-Tweak "Создание команды AIFlush" { New-Item -Path $AiCmdKey -Force *>&1 | Out-File -FilePath $global:LogPath -Append -Encoding UTF8 } }

    $AiFlushScript = @'
Stop-Process -Name "python", "pythonw", "ollama", "ollama app", "llama-server", "comfyui", "lmstudio", "vmmem", "vmmemWSL" -Force 2>> $env:SystemDrive\EastricaTools\Eastrica_ErrorTrace.log
Get-Process -Name "node" 2>> $env:SystemDrive\EastricaTools\Eastrica_ErrorTrace.log | Where-Object { $_.Path -match "LM Studio|Ollama|ComfyUI|AI" } | Stop-Process -Force 2>> $env:SystemDrive\EastricaTools\Eastrica_ErrorTrace.log
wsl --shutdown
$TempModelCaches = @("$env:USERPROFILE\.cache\huggingface\hub\tmp\*", "$env:TEMP\gradio\*", "$env:TEMP\comfyui_temp\*")
foreach ($Path in $TempModelCaches) { Remove-Item -Path $Path -Recurse -Force 2>> $env:SystemDrive\EastricaTools\Eastrica_ErrorTrace.log }
$wshell = New-Object -ComObject Wscript.Shell
$wshell.Popup("ИИ-процессы завершены. Оперативная и видеопамять полностью очищены!", 3, "AI Memory Flush", 64)
'@
    $AiFlushPath = "$BaseDir\Scripts\EastricaAIFlush.ps1"
    Apply-Tweak "Сохранение скрипта очистки памяти ИИ" { Set-Content -Path $AiFlushPath -Value $AiFlushScript -Encoding UTF8 -Force }
    $AiFinalCmd = "powershell.exe -WindowStyle Hidden -Command `"Start-Process powershell.exe -ArgumentList '-NoProfile -ExecutionPolicy Bypass -WindowStyle Hidden -File \`"$AiFlushPath\`"' -Verb RunAs -WindowStyle Hidden`""
    Apply-Tweak "Инъекция скрипта AIFlush в реестр ПКМ" { Set-Item -Path $AiCmdKey -Value $AiFinalCmd -Force *>&1 | Out-File -FilePath $global:LogPath -Append -Encoding UTF8 }
    Write-Host "[OK] Нейро-окружение настроено. Кнопка сброса памяти добавлена в меню Eastrica Tools." -ForegroundColor DarkGray
} else {
    Apply-Tweak "Удаление скрипта очистки памяти ИИ (AIFlush)" { Remove-Item -Path "$BaseDir\Scripts\EastricaAIFlush.ps1" -Force *>&1 | Out-File -FilePath $global:LogPath -Append -Encoding UTF8 }
}

