    public class ConsoleHider {
        [DllImport("kernel32.dll")] public static extern IntPtr GetConsoleWindow(); // Получаем ID окна консоли
        [DllImport("user32.dll")] public static extern bool ShowWindow(IntPtr hWnd, int nCmdShow); // Функция скрытия окна
        public static void Hide() {
            IntPtr hWnd = GetConsoleWindow(); // Находим консоль
