# Инициализация логгера (с ограничением размера до 5 МБ)
$LogFile = "$env:SystemDrive\EastricaTools\ThreadDirector_Log.txt" # Путь лог-файла
function Write-Log {
    # Функция для записи отладочной информации
    param([string]$Message, [string]$Level = "INFO")
    $TimeStamp = Get-Date -Format "yyyy-MM-dd HH:mm:ss.fff" # Точное время
    $LogLine = "[$TimeStamp] [$Level] $Message" # Формируем строку
    try {
        if (!(Test-Path "$env:SystemDrive\EastricaTools")) { New-Item -ItemType Directory -Force -Path "$env:SystemDrive\EastricaTools" | Out-Null }
        if ((Get-Item $LogFile 2>> $env:SystemDrive\EastricaTools\Eastrica_ErrorTrace.log).Length -gt 5MB) { Clear-Content $LogFile } # Очищаем, если раздулся > 5 МБ
        Add-Content -Path $LogFile -Value $LogLine -Encoding UTF8 # Пишем в файл
    } catch {}
}

function Set-WlanAutoConfig {
    param([bool]$Enable)
    $state = if ($Enable) { "yes" } else { "no" }
    try {
        $wifiAdapters = Get-NetAdapter 2>> $env:SystemDrive\EastricaTools\Eastrica_ErrorTrace.log | Where-Object { $_.PhysicalMediaType -match '802\.11' }
        foreach ($adp in $wifiAdapters) {
            cmd.exe /c "netsh wlan set autoconfig enabled=$state interface=`"$($adp.Name)`" >nul 2>&1"
            Write-Log "Wi-Fi AutoConfig ($($adp.Name)) -> $state"
        }
    } catch {}
}

