$CS = @"
using System;
using System.Runtime.InteropServices;
using System.Text;

public class WinAPI {
    [StructLayout(LayoutKind.Sequential)]
    public struct MEMORYSTATUSEX {
        public uint dwLength;
        public uint dwMemoryLoad;
        public ulong ullTotalPhys;
        public ulong ullAvailPhys;
        public ulong ullTotalPageFile;
        public ulong ullAvailPageFile;
        public ulong ullTotalVirtual;
        public ulong ullAvailVirtual;
        public ulong ullAvailExtendedVirtual;
    }

    [DllImport("kernel32.dll", SetLastError = true)]
    public static extern bool GlobalMemoryStatusEx(ref MEMORYSTATUSEX lpBuffer);

    public static ulong GetFreeRamMB() {
        MEMORYSTATUSEX memStatus = new MEMORYSTATUSEX();
        memStatus.dwLength = (uint)Marshal.SizeOf(typeof(MEMORYSTATUSEX));
        if (GlobalMemoryStatusEx(ref memStatus)) {
            return memStatus.ullAvailPhys / (1024 * 1024);
        }
        return 999999;
    }

    [DllImport("kernel32.dll", SetLastError = true)]
    public static extern IntPtr OpenProcess(uint processAccess, bool bInheritHandle, int processId);
    
    [DllImport("kernel32.dll", SetLastError = true)]
    public static extern bool CloseHandle(IntPtr hObject);

    [DllImport("kernel32.dll", SetLastError = true)]
    public static extern bool QueryFullProcessImageName(IntPtr hProcess, uint dwFlags, StringBuilder lpExeName, ref uint lpdwSize);

    [DllImport("kernel32.dll", SetLastError = true)]
    public static extern bool GetExitCodeProcess(IntPtr hProcess, out uint lpExitCode);

    public static bool IsProcessAlive(int pid) {
        IntPtr hProc = OpenProcess(0x1000, false, pid); 
        if (hProc == IntPtr.Zero) return false;
        
        uint exitCode = 0;
        bool success = GetExitCodeProcess(hProc, out exitCode);
        CloseHandle(hProc);
        return success && (exitCode == 259);
    }

    public static string GetProcessNameFast(int pid) {
        IntPtr hProc = OpenProcess(0x1000, false, pid); 
        if (hProc != IntPtr.Zero) {
            StringBuilder sb = new StringBuilder(1024);
            uint size = (uint)sb.Capacity;
            if (QueryFullProcessImageName(hProc, 0, sb, ref size)) {
                CloseHandle(hProc);
                return System.IO.Path.GetFileNameWithoutExtension(sb.ToString()).ToLower();
            }
            CloseHandle(hProc);
        }
        return "";
    }

    public static string GetProcessPathFast(int pid) {
        IntPtr hProc = OpenProcess(0x1000, false, pid); 
        if (hProc != IntPtr.Zero) {
            StringBuilder sb = new StringBuilder(1024);
            uint size = (uint)sb.Capacity;
            if (QueryFullProcessImageName(hProc, 0, sb, ref size)) {
                CloseHandle(hProc);
                return sb.ToString();
            }
            CloseHandle(hProc);
        }
        return "";
    }

    [DllImport("kernel32.dll")]
    public static extern bool SetProcessAffinityMask(IntPtr hProcess, UIntPtr dwProcessAffinityMask);

    public static void SetAffinityFast(int pid, ulong mask) {
        IntPtr hProc = OpenProcess(0x0200, false, pid);
        if (hProc != IntPtr.Zero) {
            SetProcessAffinityMask(hProc, (UIntPtr)mask);
            CloseHandle(hProc);
        }
    }

    [DllImport("kernel32.dll")]
    public static extern bool SetPriorityClass(IntPtr hProcess, uint dwPriorityClass);

    public static void SetPriorityFast(int pid, uint priorityClass) {
        IntPtr hProc = OpenProcess(0x0200, false, pid);
        if (hProc != IntPtr.Zero) {
            SetPriorityClass(hProc, priorityClass);
            CloseHandle(hProc);
        }
    }

    [DllImport("user32.dll")] public static extern IntPtr GetForegroundWindow();
    [DllImport("user32.dll")] public static extern uint GetWindowThreadProcessId(IntPtr hWnd, out int lpdwProcessId);
    [DllImport("psapi.dll")]  public static extern bool EmptyWorkingSet(IntPtr hProcess); 
    
    public static void EmptyWorkingSetFast(int pid) {
        try {
            IntPtr hProc = OpenProcess(0x0100 | 0x0400, false, pid);
            if (hProc != IntPtr.Zero) {
                EmptyWorkingSet(hProc);
                CloseHandle(hProc);
            }
        } catch {}
    }

    [DllImport("user32.dll", SetLastError = true)] public static extern IntPtr FindWindow(string lpClassName, string lpWindowName);
    [DllImport("user32.dll", SetLastError = true)] public static extern IntPtr FindWindowEx(IntPtr hwndParent, IntPtr hwndChildAfter, string lpszClass, string lpszWindow);
    [DllImport("user32.dll")] public static extern bool ShowWindow(IntPtr hWnd, int nCmdShow);

    [DllImport("ntdll.dll")] public static extern uint RtlAdjustPrivilege(int Privilege, bool bEnablePrivilege, bool IsThreadPrivilege, out bool PreviousValue);
    [DllImport("ntdll.dll")] public static extern int NtSetSystemInformation(int SystemInformationClass, ref int SystemInformation, int SystemInformationLength);
    [DllImport("ntdll.dll")] public static extern int NtSetTimerResolution(uint DesiredResolution, bool SetResolution, out int CurrentResolution);
    
    [DllImport("ntdll.dll")] public static extern int NtSetInformationProcess(IntPtr processHandle, int processInformationClass, ref int processInformation, int processInformationLength);
    [DllImport("ntdll.dll")] public static extern int NtSetInformationProcess(IntPtr processHandle, int processInformationClass, ref uint processInformation, int processInformationLength);
    [DllImport("ntdll.dll")] public static extern int NtSetInformationProcess(IntPtr processHandle, int processInformationClass, ref PROCESS_POWER_THROTTLING_STATE processInformation, int processInformationLength);
    
    [DllImport("kernel32.dll")] static extern uint SetThreadExecutionState(uint esFlags);
    [DllImport("user32.dll")] public static extern short GetAsyncKeyState(int vKey);

    [DllImport("user32.dll")] public static extern int GetDisplayConfigBufferSizes(uint flags, out uint numPathArrayElements, out uint numModeInfoArrayElements);
    [DllImport("user32.dll")] public static extern int QueryDisplayConfig(uint flags, ref uint numPathArrayElements, IntPtr pathArray, ref uint numModeInfoArrayElements, IntPtr modeInfoArray, out uint currentTopologyId);

    public static uint GetCurrentTopology() {
        uint pathCount, modeCount, topology = 0;
        if (GetDisplayConfigBufferSizes(4, out pathCount, out modeCount) == 0) {
            IntPtr pathArray = Marshal.AllocHGlobal((int)pathCount * 72);
            IntPtr modeArray = Marshal.AllocHGlobal((int)modeCount * 64);
            QueryDisplayConfig(4, ref pathCount, pathArray, ref modeCount, modeArray, out topology);
            Marshal.FreeHGlobal(pathArray);
            Marshal.FreeHGlobal(modeArray);
        }
        return topology;
    }

    public static void PreventSleep() { SetThreadExecutionState(0x80000003); }
    public static void AllowSleep() { SetThreadExecutionState(0x80000000); }

    public delegate void WinEventDelegate(IntPtr hWinEventHook, uint eventType, IntPtr hwnd, int idObject, int idChild, uint dwEventThread, uint dwmsEventTime);
    [DllImport("user32.dll")] public static extern IntPtr SetWinEventHook(uint eventMin, uint eventMax, IntPtr hmodWinEventProc, WinEventDelegate lpfnWinEventProc, uint idProcess, uint idThread, uint dwFlags);
    [DllImport("user32.dll")] public static extern bool UnhookWinEvent(IntPtr hWinEventHook);

    public static WinEventDelegate ForegroundEventDelegate;
    public static IntPtr ForegroundHook = IntPtr.Zero;

    public static void StartForegroundHook(Action callback) {
        ForegroundEventDelegate = (hWinEventHook, eventType, hwnd, idObject, idChild, dwEventThread, dwmsEventTime) => {
            callback();
        };
        ForegroundHook = SetWinEventHook(3, 3, IntPtr.Zero, ForegroundEventDelegate, 0, 0, 0);
    }

    public static void StopForegroundHook() {
        if (ForegroundHook != IntPtr.Zero) {
            UnhookWinEvent(ForegroundHook);
            ForegroundHook = IntPtr.Zero;
        }
    }

    public static void SetPrioritySeparation(int value) {
        try {
            bool prev;
            RtlAdjustPrivilege(13, true, false, out prev);
            RtlAdjustPrivilege(14, true, false, out prev);
            NtSetSystemInformation(74, ref value, 4);
        } catch {}
    }

    [StructLayout(LayoutKind.Sequential)]
    public struct RECT { public int Left; public int Top; public int Right; public int Bottom; }
    [DllImport("user32.dll")] public static extern bool GetWindowRect(IntPtr hWnd, out RECT lpRect);
    [DllImport("user32.dll")] public static extern IntPtr MonitorFromWindow(IntPtr hwnd, uint dwFlags);
    
    [StructLayout(LayoutKind.Sequential)]
    public struct MONITORINFO { public uint cbSize; public RECT rcMonitor; public RECT rcWork; public uint dwFlags; }
    [DllImport("user32.dll")] public static extern bool GetMonitorInfo(IntPtr hMonitor, ref MONITORINFO lpmi);

    [DllImport("user32.dll")] public static extern bool SetProcessDPIAware();
    public static bool IsFullscreenOrBorderless(IntPtr hWnd) {
        SetProcessDPIAware();
        RECT appBounds;
        if (!GetWindowRect(hWnd, out appBounds)) return false;
        IntPtr hMonitor = MonitorFromWindow(hWnd, 2);
        if (hMonitor != IntPtr.Zero) {
            MONITORINFO mi = new MONITORINFO();
            mi.cbSize = (uint)Marshal.SizeOf(typeof(MONITORINFO));
            if (GetMonitorInfo(hMonitor, ref mi)) {
                long appWidth = (long)(appBounds.Right - appBounds.Left);
                long appHeight = (long)(appBounds.Bottom - appBounds.Top);
                long monWidth = (long)(mi.rcMonitor.Right - mi.rcMonitor.Left);
                long monHeight = (long)(mi.rcMonitor.Bottom - mi.rcMonitor.Top);

                long appArea = appWidth * appHeight;
                long monArea = monWidth * monHeight;
                
                if (monArea > 0 && appArea >= (long)(monArea * 0.95)) {
                    return true;
                }
            }
        }
        return false;
    }

    [DllImport("kernel32.dll", SetLastError = true)]
    public static extern bool SetSystemFileCacheSize(IntPtr MinimumFileCacheSize, IntPtr MaximumFileCacheSize, int Flags);

    public static void FlushSystemCacheAndStandby() {
        try { 
            bool prev;
            RtlAdjustPrivilege(5, true, false, out prev);
            RtlAdjustPrivilege(13, true, false, out prev);
            SetSystemFileCacheSize((IntPtr)(-1), (IntPtr)(-1), 0);
            int command = 4;
            NtSetSystemInformation(80, ref command, Marshal.SizeOf(command));
        } catch {}
    }

    [StructLayout(LayoutKind.Sequential)]
    public struct PROCESS_POWER_THROTTLING_STATE {
        public uint Version;
        public uint ControlMask;
        public uint StateMask;
    }

    public static void EnableEcoMode(int pid) {
        IntPtr hProc = OpenProcess(0x0200 | 0x0400, false, pid);
        if (hProc != IntPtr.Zero) {
            PROCESS_POWER_THROTTLING_STATE state = new PROCESS_POWER_THROTTLING_STATE();
            state.Version = 1;
            state.ControlMask = 1;
            state.StateMask = 1;
            NtSetInformationProcess(hProc, 77, ref state, Marshal.SizeOf(state));
            CloseHandle(hProc);
        }
    }

    public static void DisableEcoMode(int pid) {
        IntPtr hProc = OpenProcess(0x0200 | 0x0400, false, pid);
        if (hProc != IntPtr.Zero) {
            PROCESS_POWER_THROTTLING_STATE state = new PROCESS_POWER_THROTTLING_STATE();
            state.Version = 1;
            state.ControlMask = 1; 
            state.StateMask = 0;
            NtSetInformationProcess(hProc, 77, ref state, Marshal.SizeOf(state));
            CloseHandle(hProc);
        }
    }

    public static void SetMemoryPriority(int pid, uint priority) {
        IntPtr hProc = OpenProcess(0x0200 | 0x0400, false, pid); 
        if (hProc != IntPtr.Zero) {
            NtSetInformationProcess(hProc, 39, ref priority, 4);
            CloseHandle(hProc);
        }
    }

    [DllImport("kernel32.dll", SetLastError = true)]
    public static extern IntPtr CreateToolhelp32Snapshot(uint dwFlags, uint th32ProcessID);
    [DllImport("kernel32.dll")]
    public static extern bool Process32First(IntPtr hSnapshot, ref PROCESSENTRY32 lppe);
    [DllImport("kernel32.dll")]
    public static extern bool Process32Next(IntPtr hSnapshot, ref PROCESSENTRY32 lppe);

    [StructLayout(LayoutKind.Sequential)]
    public struct PROCESSENTRY32 {
        public uint dwSize;
        public uint cntUsage;
        public uint th32ProcessID;
        public IntPtr th32DefaultHeapID;
        public uint th32ModuleID;
        public uint cntThreads;
        public uint th32ParentProcessID;
        public int pcPriClassBase;
        public uint dwFlags;
        [MarshalAs(UnmanagedType.ByValTStr, SizeConst = 260)]
        public string szExeFile;
    }

    public static int[] GetProcessTree(int rootPid) {
        System.Collections.Generic.List<int> result = new System.Collections.Generic.List<int>();
        System.Collections.Generic.Dictionary<int, int> parentMap = new System.Collections.Generic.Dictionary<int, int>();
        
        IntPtr hSnapshot = CreateToolhelp32Snapshot(2, 0);
        if (hSnapshot != IntPtr.Zero && hSnapshot.ToInt64() != -1) {
            PROCESSENTRY32 pe32 = new PROCESSENTRY32();
            pe32.dwSize = (uint)Marshal.SizeOf(typeof(PROCESSENTRY32));
            if (Process32First(hSnapshot, ref pe32)) {
                do { parentMap[(int)pe32.th32ProcessID] = (int)pe32.th32ParentProcessID; }
                while (Process32Next(hSnapshot, ref pe32));
            }
            CloseHandle(hSnapshot);
        }
        
        System.Collections.Generic.Queue<int> queue = new System.Collections.Generic.Queue<int>();
        queue.Enqueue(rootPid);
        result.Add(rootPid);
        
        while(queue.Count > 0) {
            int curr = queue.Dequeue();
            foreach(var kvp in parentMap) {
                if (kvp.Value == curr) { queue.Enqueue(kvp.Key); result.Add(kvp.Key); }
            }
        }
        return result.ToArray();
    }
}

public class HotKeyManager : System.Windows.Forms.NativeWindow, IDisposable {
    public static bool PanicTriggered = false;
    private const int HOTKEY_ID = 9001;

    [DllImport("user32.dll", SetLastError = true)] 
    public static extern bool RegisterHotKey(IntPtr hWnd, int id, uint fsModifiers, uint vk);

    [DllImport("user32.dll", SetLastError = true)] 
    public static extern bool UnregisterHotKey(IntPtr hWnd, int id);

    public HotKeyManager() {
        this.CreateHandle(new System.Windows.Forms.CreateParams());
        RegisterHotKey(this.Handle, HOTKEY_ID, 0x0002 | 0x0004, 0x7B);
    }

    protected override void WndProc(ref System.Windows.Forms.Message m) {
        if (m.Msg == 0x0312 && m.WParam.ToInt32() == HOTKEY_ID) { 
            PanicTriggered = true; 
        }
        base.WndProc(ref m);
    }

    public void Dispose() {
        try {
            UnregisterHotKey(this.Handle, HOTKEY_ID);
            this.DestroyHandle();
        } catch {}
    }
}
"@
try {
    $DirectorDll = "$env:SystemDrive\EastricaTools\Scripts\EastricaDirectorCore.dll"
    if (-not ("WinAPI" -as [type])) {
        if (Test-Path $DirectorDll) {
            Add-Type -Path $DirectorDll -ErrorAction Stop
        } else {
            Add-Type -TypeDefinition $CS -OutputAssembly $DirectorDll -ReferencedAssemblies "System.Windows.Forms" -Language CSharp -ErrorAction Stop
        }
    }
    Write-Log "C# WinAPI успешно инициализирован (кэш DLL)"
} catch {
    Write-Log "Ошибка компиляции C#: $($_.Exception.Message)" "ERROR"
    [System.Windows.Forms.MessageBox]::Show("Сбой компилятора .NET. Работа Thread Director невозможна.", "Ошибка", 0, 16)
    Exit
}

Write-Log "Выполнение защитной разморозки процессов..."
$FailsafeApps = @("chrome", "msedge", "firefox", "brave", "opera", "yandex", "qbittorrent", "utorrent", "onedrive", "telegram", "viber", "whatsapp", "skype", "teams", "SearchIndexer", "SearchHost", "Widgets", "bcastdvr", "GameBar", "GameBarFTServer", "flux", "rtss", "LightBulb", "TiWorker", "MoUsoCoreWorker", "SearchFilterHost", "ApplicationFrameHost", "obs64", "discord", "ts3client", "steamwebhelper", "epicwebhelper", "Spotify")
foreach ($app in $FailsafeApps) {
    Get-Process -Name $app -ErrorAction SilentlyContinue | ForEach-Object {
        try {
            [WinAPI]::SetPriorityFast($_.Id, 0x00000020) # NORMAL
            [WinAPI]::SetMemoryPriority($_.Id, 5)
            [WinAPI]::DisableEcoMode($_.Id)
            [WinAPI]::SetAffinityFast($_.Id, ([uint64]::MaxValue)) # Разрешаем все ядра
        } catch {}
    }
}

# Выдаем самому Директору приоритет HIGH, чтобы он не завис при 100% нагрузке процессора игрой
try { (Get-Process -Id $PID).PriorityClass = [System.Diagnostics.ProcessPriorityClass]::High } catch {}

# 1. Авто-запрос прав администратора
if (!([Security.Principal.WindowsPrincipal][Security.Principal.WindowsIdentity]::GetCurrent()).IsInRole([Security.Principal.WindowsBuiltInRole] "Administrator")) {
    Write-Log "Запрос прав Администратора..." "WARN"
    $ArgsList = @("-NoProfile", "-ExecutionPolicy", "Bypass", "-WindowStyle", "Hidden", "-File", $MyInvocation.MyCommand.Path)
    if ($TargetApp) { 
        $CleanApp = $TargetApp.Trim('"')
        $ArgsList += "-TargetApp"
        $ArgsList += $CleanApp 
    }
    Start-Process powershell.exe -ArgumentList $ArgsList -Verb RunAs -WindowStyle Hidden
    Exit # Закрываем процесс без прав
}

