    $btnClose.FlatAppearance.BorderSize = 0
    $btnClose.Cursor = [System.Windows.Forms.Cursors]::Hand
    $btnClose.Font = New-Object System.Drawing.Font("Segoe UI", 10, [System.Drawing.FontStyle]::Bold)
    $btnClose.Add_Click({ $helpForm.Close() })
    
    $helpForm.Controls.Add($txtHelp)
    $helpForm.Controls.Add($btnClose)
    $helpForm.ShowDialog($form) | Out-Null
    $helpForm.Dispose()
})
