$form.Controls.Add($lblCreator)
$lblCreator.BringToFront()

# Восстановление сохраненного выбора из реестра
try {
    [Microsoft.Win32.Registry]::CurrentUser.CreateSubKey("Software\Eastrica\ThreadDirector") | Out-Null
} catch {}

$RegDir = "HKCU:\Software\Eastrica\ThreadDirector"
$SavedConfig = Get-ItemProperty -Path $RegDir 2>> $env:SystemDrive\EastricaTools\Eastrica_ErrorTrace.log

if ($null -ne $SavedConfig) {
    if ($SavedConfig.KillExplorer -eq 1) { $chkKillExplorer.Checked = $true }
    if ($SavedConfig.DisableSMT -eq 1) { $chkSMT.Checked = $true }
    if ($SavedConfig.BlackoutMonitors -eq 1) { $chkMonitors.Checked = $true }
    if ($SavedConfig.AutoFlush -eq 1) { $chkAutoFlush.Checked = $true }
    if ($SavedConfig.DisableBattery -eq 1) { $chkBattery.Checked = $true }
    if ($SavedConfig.ExplorerEco -eq 1 -or $SavedConfig.FreezeDWM -eq 1) { $chkExplorerEco.Checked = $true }
    if (-not [string]::IsNullOrWhiteSpace($SavedConfig.Whitelist)) {
        $txtWhitelist.Text = $SavedConfig.Whitelist
    } else {
        $txtWhitelist.Text = "discord, telegram, obs64, ts3client"
    }
} else {
    $txtWhitelist.Text = "discord, telegram, obs64, ts3client"
}

# Обработчики событий (Синхронное сохранение)
$chkKillExplorer.Add_CheckedChanged({
    $val = if ($chkKillExplorer.Checked) { 1 } else { 0 }
    Set-ItemProperty -Path "HKCU:\Software\Eastrica\ThreadDirector" -Name "KillExplorer" -Value $val -Type DWord -Force 2>> $env:SystemDrive\EastricaTools\Eastrica_ErrorTrace.log | Out-Null
})

$chkSMT.Add_CheckedChanged({
    $val = if ($chkSMT.Checked) { 1 } else { 0 }
    Set-ItemProperty -Path "HKCU:\Software\Eastrica\ThreadDirector" -Name "DisableSMT" -Value $val -Type DWord -Force 2>> $env:SystemDrive\EastricaTools\Eastrica_ErrorTrace.log | Out-Null
})

$chkMonitors.Add_CheckedChanged({
    $val = if ($chkMonitors.Checked) { 1 } else { 0 }
    Set-ItemProperty -Path "HKCU:\Software\Eastrica\ThreadDirector" -Name "BlackoutMonitors" -Value $val -Type DWord -Force 2>> $env:SystemDrive\EastricaTools\Eastrica_ErrorTrace.log | Out-Null
})

$chkAutoFlush.Add_CheckedChanged({
    $val = if ($chkAutoFlush.Checked) { 1 } else { 0 }
    Set-ItemProperty -Path "HKCU:\Software\Eastrica\ThreadDirector" -Name "AutoFlush" -Value $val -Type DWord -Force 2>> $env:SystemDrive\EastricaTools\Eastrica_ErrorTrace.log | Out-Null
})

$chkBattery.Add_CheckedChanged({
    $val = if ($chkBattery.Checked) { 1 } else { 0 }
    Set-ItemProperty -Path "HKCU:\Software\Eastrica\ThreadDirector" -Name "DisableBattery" -Value $val -Type DWord -Force 2>> $env:SystemDrive\EastricaTools\Eastrica_ErrorTrace.log | Out-Null
})

$chkExplorerEco.Add_CheckedChanged({
    $val = if ($chkExplorerEco.Checked) { 1 } else { 0 }
    Set-ItemProperty -Path "HKCU:\Software\Eastrica\ThreadDirector" -Name "ExplorerEco" -Value $val -Type DWord -Force 2>> $env:SystemDrive\EastricaTools\Eastrica_ErrorTrace.log | Out-Null
    Set-ItemProperty -Path "HKCU:\Software\Eastrica\ThreadDirector" -Name "FreezeDWM" -Value $val -Type DWord -Force 2>> $env:SystemDrive\EastricaTools\Eastrica_ErrorTrace.log | Out-Null
})

$txtWhitelist.Add_TextChanged({
    Set-ItemProperty -Path "HKCU:\Software\Eastrica\ThreadDirector" -Name "Whitelist" -Value $txtWhitelist.Text -Type String -Force 2>> $env:SystemDrive\EastricaTools\Eastrica_ErrorTrace.log | Out-Null
})

# Настройка системного трея (Иконка возле часов с интерактивным меню)
$notifyIcon = New-Object System.Windows.Forms.NotifyIcon
try { $notifyIcon.Icon = [System.Drawing.Icon]::ExtractAssociatedIcon("$env:SystemRoot\System32\perfmon.exe") } catch { $notifyIcon.Icon = [System.Drawing.SystemIcons]::Information }
$notifyIcon.Text = "Eastrica Thread Director"
$notifyIcon.Visible = $false

# Контекстное меню для управления утилитой из трея
$trayMenu = New-Object System.Windows.Forms.ContextMenuStrip
$itemOpen = $trayMenu.Items.Add((L "Развернуть окно настроек" "Open Settings Window"))
$itemOpen.Font = New-Object System.Drawing.Font("Segoe UI", 9, [System.Drawing.FontStyle]::Bold)
$itemOpen.Add_Click({
    $form.Show()
    $form.WindowState = [System.Windows.Forms.FormWindowState]::Normal
    $form.BringToFront()
})

$trayMenu.Items.Add("-") | Out-Null # Разделитель

$itemExit = $trayMenu.Items.Add((L "Завершить работу и восстановить систему" "Exit and Restore System"))
$itemExit.Add_Click({
    $timer.Stop()
    Restore-SystemState -ShowPopup $false
    try { $notifyIcon.Visible = $false; $notifyIcon.Dispose() } catch {}
    try { $form.Dispose() } catch {}
    [System.Environment]::Exit(0)
})

$notifyIcon.ContextMenuStrip = $trayMenu
$notifyIcon.Add_DoubleClick({
    $form.Show()
    $form.WindowState = [System.Windows.Forms.FormWindowState]::Normal
    $form.BringToFront()
})

$global:KeepRunning = $true # Флаг цикла

# Заранее получаем ID батареи, чтобы потом не тратить время на медленные WMI запросы при запуске игры
$global:BatId = $null
try { $global:BatId = (Get-PnpDevice -Class Battery 2>> $env:SystemDrive\EastricaTools\Eastrica_ErrorTrace.log | Where-Object { $_.InstanceId -match "PNP0C0A" }).InstanceId } catch {}

# ==============================================================================
# Интеллектуальный расчет масок (E-Cores & 3D V-Cache detect) для Директора
# ==============================================================================
$ProcInfo = Get-CimInstance Win32_Processor 2>> $env:SystemDrive\EastricaTools\Eastrica_ErrorTrace.log | Select-Object -First 1
$CpuName = $ProcInfo.Name
$TotalCores = $ProcInfo.NumberOfLogicalProcessors
$PhysCores = $ProcInfo.NumberOfCores
$IsIntel = $ProcInfo.Manufacturer -match "Intel"

[uint64]$TrashMask = 0
[uint64]$GameMask = 0

$IsHybridIntel = $IsIntel -and ($TotalCores -gt $PhysCores -or $CpuName -match "Ultra|1[234]\d{3}|2\d{3}")
if ($IsHybridIntel) {
    if ($TotalCores -gt $PhysCores) {
        $PCoreThreads = ($TotalCores - $PhysCores) * 2
        $ECores = $TotalCores - $PCoreThreads
    } else {
        if ($PhysCores -ge 24) { $PCoreThreads = 8 }
        elseif ($PhysCores -ge 16) { $PCoreThreads = 8 }
        elseif ($PhysCores -ge 10) { $PCoreThreads = 6 }
        elseif ($PhysCores -eq 8 -and $CpuName -match "Lunar|Ultra") { $PCoreThreads = 4 }
        else { $PCoreThreads = $PhysCores }
        $ECores = $TotalCores - $PCoreThreads
    }
} else {
    $PCoreThreads = $TotalCores
    $ECores = 0
}

# Сценарий 1: AMD Ryzen X3D (Два чиплета, V-Cache только на первом CCD)
if ($CpuName -match "7950X3D|9950X3D" -or $CpuName -match "7900X3D|9900X3D" -or $CpuName -match "7800X3D|9800X3D") {
    Write-Log "Обнаружен процессор AMD Ryzen 3D V-Cache: $CpuName"
    $HasSMT = ($TotalCores -gt $PhysCores)
    if ($CpuName -match "7950X3D|9950X3D") { $Ccd0_Threads = if ($HasSMT) { 16 } else { 8 } }
    elseif ($CpuName -match "7900X3D|9900X3D") { $Ccd0_Threads = if ($HasSMT) { 12 } else { 6 } }
    else { $Ccd0_Threads = $TotalCores }

    $TrashMask = [uint64](([uint64]1 -shl ($TotalCores - 1)) -bor ([uint64]1 -shl ($TotalCores - 2)))
    
    [uint64]$tempMask = 0
    if ($chkSMT.Checked) {
        for ($i = 2; $i -lt $Ccd0_Threads; $i += 2) { $tempMask = $tempMask -bor ([uint64]1 -shl $i) }
    } else {
        for ($i = 2; $i -lt $Ccd0_Threads; $i++) { $tempMask = $tempMask -bor ([uint64]1 -shl $i) }
    }
    $GameMask = [uint64]$tempMask
}
# Сценарий 2: Intel 12/13/14 Gen (P-Cores + E-Cores)
elseif ($IsIntel -and $ECores -gt 0) {
    Write-Log "Обнаружены E-Cores (Intel). P-Потоков: $PCoreThreads, E-Ядер: $ECores"
    $AllOnes = if ($TotalCores -ge 64) { [uint64]::MaxValue } else { ([uint64]1 -shl $TotalCores) - 1 }
    $TrashMask = [uint64]($AllOnes - (([uint64]1 -shl $PCoreThreads) - 1))
    
    if ($chkSMT.Checked) {
        [uint64]$tempMask = 0
        $HasSMT = ($TotalCores -gt $PhysCores)
        if ($chkSMT.Checked -and $HasSMT) {
            for ($i = 2; $i -lt $PCoreThreads; $i += 2) { $tempMask = $tempMask -bor ([uint64]1 -shl $i) }
        } else {
            for ($i = 2; $i -lt $PCoreThreads; $i++) { $tempMask = $tempMask -bor ([uint64]1 -shl $i) }
        }
        $GameMask = [uint64]$tempMask
    } else {
        $BaseGameMask = [uint64](([uint64]1 -shl $PCoreThreads) - 1)
        $GameMask = [uint64]($BaseGameMask - 3) # Минус нулевое ядро
    }
} 
# Сценарий 3: Классика (AMD без X3D, Intel Монолит)
else {
    Write-Log "Стандартный процессор (Монолит). Ядер: $TotalCores"
    $EffectiveCores = if ($TotalCores -gt 64) { 64 } else { $TotalCores }
    
    if ($EffectiveCores -le 2) {
        $TrashMask = [uint64]3; $GameMask = [uint64]3
    } elseif ($EffectiveCores -le 4) {
        $TrashMask = [uint64]8; $GameMask = [uint64]6
    } else {
        $TrashMask = [uint64](([uint64]1 -shl ($EffectiveCores - 1)) -bor ([uint64]1 -shl ($EffectiveCores - 2)))
        if ($chkSMT.Checked) {
            [uint64]$tempMask = 0
            for ($i = 2; $i -lt $EffectiveCores; $i += 2) { $tempMask = $tempMask -bor ([uint64]1 -shl $i) }
            $GameMask = [uint64]$tempMask
        } else {
            $GameMask = [uint64](([uint64]1 -shl $EffectiveCores) - 1 - 3)
        }
    }
}

if ($TotalCores -ge 64) {
    $FullMask = [uint64]::MaxValue # Безлимитная маска возврата для Threadripper / Xeon
} else {
    $FullMask = ([uint64]1 -shl $TotalCores) - 1 # Маска возврата
}
if ($GameMask -le 0) { $GameMask = $FullMask } # Защита от ошибки
if ($TrashMask -le 0) { $TrashMask = 1 } # Если E-ядер нет, жестко кидаем мусор на самое первое ядро (Core 0)

# Глобальные переменные отслеживания состояния
$script:LockedPID = 0 # ID процесса игры, которую мы "поймали"
$script:IsExplorerHidden = $false # Скрыт ли Проводник
$script:IsMonitorsDisabled = $false # Отключены ли вторые мониторы
$script:IsBatteryDisabled = $false # Отключена ли батарея
$script:SuspendedPIDs = @() # Список процессов, которые мы удушили в EcoMode
$script:isGameInForeground = $true # Свернул ли игрок игру
$global:SavedTopology = 4 # Топология мониторов по умолчанию (Расширить)

# Списки игнорирования и заморозки
# Эти программы Директор игнорирует при поиске игры в полноэкранном режиме
$IgnoreArray = @("explorer", "dwm", "searchhost", "cmd", "powershell", "taskmgr", "steam", "steamwebhelper", "epicgameslauncher", "battle.net", "riotclient", "upc", "origin", "eadesktop", "eabackgroundservice", "vgc", "vgtray", "faceit", "faceitclient", "chrome", "msedge", "firefox", "brave", "opera", "yandex", "devenv", "code", "idea64", "photoshop", "illustrator", "premiere", "vlc", "mpc-hc64", "rockstargameslauncher", "socialclubhelper", "launcher", "splash", "loading")

if ((powercfg /getactivescheme) -match "([a-f0-9\-]{36})") { $CurrentPlan = $matches[1] } # Сохраняем текущий план питания
$UltimatePlan = "e9a42b02-d5df-448d-aa00-03f14749eb61" # GUID Максимальной производительности
$script:RunningServices = @() # Сохраняем те службы, которые реально работали

# Тяжелые фоновые службы Windows, которые убивают диск и сеть во время игры
$ServicesToStop = @("WmiApSrv", "DiagTrack", "SysMain", "wuauserv", "UsoSvc", "bits", "DoSvc", "bthserv", "WSearch")

# Программы, которые будут переведены в глубокий ECO MODE (Мягкая заморозка памяти)
$AppsToSuspend = @("chrome", "msedge", "firefox", "brave", "opera", "yandex", "qbittorrent", "utorrent", "onedrive", "telegram", "viber", "whatsapp", "skype", "teams", "SearchIndexer", "SearchHost", "Widgets", "bcastdvr", "GameBar", "GameBarFTServer", "flux", "rtss", "LightBulb", "TiWorker", "MoUsoCoreWorker", "SearchFilterHost", "ApplicationFrameHost", "obs64", "discord", "ts3client")

# Программы, которым будет срезан приоритет и выдана ссылка на E-Cores (TrashMask)
$TrashApps = @("steamwebhelper", "epicwebhelper", "Spotify")

# ==============================================================================
# Блок безопасного восстановления (Restore System State)
# ==============================================================================
# Срабатывает мгновенно, как только вы выходите из игры (или жмете Ctrl+Shift+F12)
function Restore-SystemState {
    param([bool]$ShowPopup = $true)
    Write-Log "=== ВЫЗОВ ВОССТАНОВЛЕНИЯ СИСТЕМЫ ==="
    Set-WlanAutoConfig -Enable $true
    
    # 1. Возвращаем всплывающие уведомления Windows (Тосты)
    try {
        $NocPath = "HKCU:\Software\Microsoft\Windows\CurrentVersion\Notifications\Settings"
        Set-ItemProperty -Path $NocPath -Name "NOC_GLOBAL_SETTING_TOASTS_STATE" -Value 1 -Type DWord -Force 2>> $env:SystemDrive\EastricaTools\Eastrica_ErrorTrace.log
    } catch {}

    # Снимаем флаг активности игры в реестре
    try { Set-ItemProperty -Path "HKLM:\SOFTWARE\Eastrica" -Name "GameActive" -Value 0 -Type DWord -Force 2>> $env:SystemDrive\EastricaTools\Eastrica_ErrorTrace.log } catch {}
    
    Write-Log "Синхронизация квантов планировщика Eastrica (Win32PrioritySeparation = 42)..."
    try { [WinAPI]::SetPrioritySeparation(42) } catch {}
    
    # 2. Восстанавливаем вторые мониторы (если они отключались)
    if ($script:IsMonitorsDisabled) {
        Write-Log "Восстановление исходной топологии мониторов ($global:SavedTopology)..."
        try {
            if ($global:SavedTopology -eq 2) { cmd.exe /q /c "DisplaySwitch.exe /clone >nul 2>&1" } # Дублировать
            elseif ($global:SavedTopology -eq 4) { cmd.exe /q /c "DisplaySwitch.exe /extend >nul 2>&1" } # Расширить
            elseif ($global:SavedTopology -eq 8) { cmd.exe /q /c "DisplaySwitch.exe /external >nul 2>&1" } # Только второй
            else { cmd.exe /q /c "DisplaySwitch.exe /extend >nul 2>&1" }
            $script:IsMonitorsDisabled = $false 
        } catch {}
    }

    # 3. Восстанавливаем батарею ноутбука
    if ($script:IsBatteryDisabled -and $global:BatId) {
        Write-Log "Включение ACPI-батареи..."
        try { 
            cmd.exe /c "pnputil /enable-device `"$global:BatId`" >nul 2>&1"
            $script:IsBatteryDisabled = $false
            Write-Log "Батарея успешно включена."
        } catch {}
    }

    # 4. Разрешаем ПК уходить в спящий режим
    try { [WinAPI]::AllowSleep() } catch {}
    
    # 5. Возвращаем стандартное разрешение таймера ядра Windows
    try { 
        $currentRes = 0
        [WinAPI]::NtSetTimerResolution(5000, $false, [ref]$currentRes) | Out-Null 
    } catch {}
    
    # 6. Снимаем изоляцию с Оконного Менеджера (DWM) и Проводника (Explorer)
    Get-Process -Name "dwm", "explorer" 2>> $env:SystemDrive\EastricaTools\Eastrica_ErrorTrace.log | ForEach-Object {
        try { 
            [WinAPI]::SetPriorityFast($_.Id, 0x00000020) # 0x20 = NORMAL_PRIORITY_CLASS
            [WinAPI]::SetAffinityFast($_.Id, $FullMask)  # Разрешаем им снова работать на всех ядрах процессора
        } catch {}
    }

    # 7. Удаляем VIP-правило QoS сетевого стека
    try { Remove-NetQosPolicy -Name "Eastrica_TempQoS" -Confirm:$false -ErrorAction SilentlyContinue | Out-Null } catch {}
    # Удаляем разрешающее правило обхода WFP Брандмауэра
    try { Remove-NetFirewallRule -DisplayName "Eastrica_TempWFP" -ErrorAction SilentlyContinue } catch {}

    # 8. Возвращаем интерфейс Рабочего Стола на всех мониторах
    if ($script:IsExplorerHidden) {
        Write-Log "Восстановление видимости Проводника (Explorer) на всех мониторах..."
        try { 
            $progman = [WinAPI]::FindWindow("Progman", $null)
            if ($progman -ne [IntPtr]::Zero) { [WinAPI]::ShowWindow($progman, 5) } # 5 = SW_SHOW
            
            $workerW = [WinAPI]::FindWindow("WorkerW", $null)
            if ($workerW -ne [IntPtr]::Zero) { [WinAPI]::ShowWindow($workerW, 5) }
            
            # Показываем главную панель задач
            $taskbar = [WinAPI]::FindWindow("Shell_TrayWnd", $null)
            if ($taskbar -ne [IntPtr]::Zero) { [WinAPI]::ShowWindow($taskbar, 5) }
            
            # Показываем вторичные панели задач на дополнительных мониторах
            $secTaskbar = [WinAPI]::FindWindow("Shell_SecondaryTrayWnd", $null)
            while ($secTaskbar -ne [IntPtr]::Zero) {
                [WinAPI]::ShowWindow($secTaskbar, 5)
                # Ищем следующую панель при наличии 3+ мониторов
                $secTaskbar = [WinAPI]::FindWindowEx([IntPtr]::Zero, $secTaskbar, "Shell_SecondaryTrayWnd", $null)
            }
            
            $script:IsExplorerHidden = $false
            Get-Process -Name "ShellExperienceHost", "TextInputHost", "StartMenuExperienceHost" -ErrorAction SilentlyContinue | Stop-Process -Force
            
            if ((Get-Process "explorer" -ErrorAction SilentlyContinue) -eq $null) {
                Write-Log "Процесс explorer не найден, запускаем принудительно..."
                Start-Process "explorer.exe"
            }
        } catch {
            Write-Log "ОШИБКА восстановления Проводника: $($_.Exception.Message)" "ERROR"
        }
    }

    # 9. Разморозка всех "удушенных" фоновых приложений (Soft Resume)
    if ($script:SuspendedPIDs -and $script:SuspendedPIDs.Count -gt 0) {
        Write-Log "Плавная разморозка $($script:SuspendedPIDs.Count) процессов (Soft Resume)..."
        foreach ($pidToResume in $script:SuspendedPIDs) {
            try { 
                [WinAPI]::SetMemoryPriority($pidToResume, 5) # Возвращаем приоритет памяти в норму (5)
                [WinAPI]::DisableEcoMode($pidToResume)       # Отключаем ограничение тактов (Eco Mode)
                [WinAPI]::SetAffinityFast($pidToResume, $FullMask) # Разрешаем процессам (типа Discord) использовать нормальные ядра
            } catch {}
        }
        $script:SuspendedPIDs = @() # Очищаем массив
    }
    
    # 10. Возврат плана электропитания
    if ($CurrentPlan) { try { powercfg.exe /setactive $CurrentPlan >$null 2>&1 } catch {} }
    
    # 11. Включение фоновых служб обновления и телеметрии (если они были нужны)
    if ($script:RunningServices.Count -gt 0) {
        foreach($s in $script:RunningServices) { 
            try { Start-Process "sc.exe" -ArgumentList "start $s" -WindowStyle Hidden } catch {} 
        }
        $script:RunningServices = @()
    }
    
    # 12. Снятие изоляции с мусорных лаунчеров (Steam/Epic)
    $AllToRestore = $TrashApps + $AppsToSuspend
    foreach ($t in $AllToRestore) {
        Get-Process -Name $t 2>> $env:SystemDrive\EastricaTools\Eastrica_ErrorTrace.log | ForEach-Object {
            try { 
                [WinAPI]::SetPriorityFast($_.Id, 0x00000020) # NORMAL
                [WinAPI]::SetAffinityFast($_.Id, $FullMask) 
            } catch {}
        }
    }
    
    $script:LockedPID = 0
    try { 
        [WinAPI]::FlushSystemCacheAndStandby()
        [System.GC]::Collect()
        [System.GC]::WaitForPendingFinalizers()
    } catch {}
    
    Write-Log "=== Восстановление завершено ==="

    # 13. Выводим окно с таймером об успешном окончании игры
    if ($ShowPopup) {
        try { 
            # Обращаемся к элементу UI через Invoke, так как находимся в фоновом потоке
            if ($notifyIcon) { $form.Invoke([action]{ $notifyIcon.Visible = $false }) }
            
            $msgForm = New-Object System.Windows.Forms.Form
            $msgForm.FormBorderStyle = [System.Windows.Forms.FormBorderStyle]::None
            $msgForm.StartPosition = [System.Windows.Forms.FormStartPosition]::CenterScreen
            $msgForm.Size = New-Object System.Drawing.Size([int](420 * $Scale), [int](95 * $Scale))
            $msgForm.BackColor = [System.Drawing.Color]::FromArgb(26, 26, 30)
            $msgForm.TopMost = $true

            $msgForm.Add_Paint({
                param($sender, $e)
                $pen = New-Object System.Drawing.Pen([System.Drawing.Color]::FromArgb(0, 120, 215), 2)
                $rect = New-Object System.Drawing.Rectangle(0, 0, ($sender.Width - 1), ($sender.Height - 1))
                $e.Graphics.DrawRectangle($pen, $rect)
                $pen.Dispose()
            })

            $msgLabel = New-Object System.Windows.Forms.Label
            $msgLabel.AutoSize = $false
            $msgLabel.Dock = [System.Windows.Forms.DockStyle]::Fill
            $msgLabel.TextAlign = [System.Drawing.ContentAlignment]::MiddleCenter
            $msgLabel.ForeColor = [System.Drawing.Color]::White
            $msgLabel.Font = New-Object System.Drawing.Font("Segoe UI", 10, [System.Drawing.FontStyle]::Bold)
            $msgForm.Controls.Add($msgLabel)

            $script:timeLeft = 3
            $msgTextFormat = L "Игра закрыта. Система полностью восстановлена!`nЗакрытие через {0} сек..." "Game closed. System restored successfully!`nClosing in {0} sec..."
            $msgLabel.Text = [string]::Format($msgTextFormat, $script:timeLeft)

            $closeTimer = New-Object System.Windows.Forms.Timer
            $closeTimer.Interval = 1000
            $closeTimer.Add_Tick({
                $script:timeLeft--
                if ($script:timeLeft -le 0) {
                    $closeTimer.Stop()
                    $msgForm.Close()
                } else {
                    $msgLabel.Text = [string]::Format($msgTextFormat, $script:timeLeft)
                }
            })
            
            $msgForm.Add_Load({ $closeTimer.Start() })
            $msgForm.ShowDialog() | Out-Null
            $msgForm.Dispose()
        } catch {}
    }
}

Write-Log "Ожидание полноэкранного приложения..."

$timer = New-Object System.Windows.Forms.Timer
# Фоновый пульс 2000 мс (только проверка жизни процесса и Standby RAM, реакция на окна переведена на WinEventHook)
$timer.Interval = 2000 

$ProcessWatcherLogic = {
    try {
        if ($script:LockedPID -eq 0) {
            # --- Игра еще не найдена ---
            $hWnd = [WinAPI]::GetForegroundWindow() # Получаем ID окна, которое сейчас на переднем плане (В фокусе)
            if ($hWnd -ne [IntPtr]::Zero) {
                # 1. Проверяем окно на Fullscreen (Native API вызов, без WMI, чтобы не грузить ЦП)
                if ([WinAPI]::IsFullscreenOrBorderless($hWnd)) {
                    $pidRef = 0
                    [WinAPI]::GetWindowThreadProcessId($hWnd, [ref]$pidRef) | Out-Null # Узнаем, какому процессу принадлежит это полноэкранное окно
                    
                    # Исключаем захват самого скрипта (себя)
                    if ($pidRef -gt 0 -and $pidRef -ne $PID) {
                        # 2. Получаем имя процесса сверхбыстрым WinAPI-методом (в обход Get-Process)
                        $pName = [WinAPI]::GetProcessNameFast($pidRef)
                        
                        if ($pName -ne "") {
                            $isIgnored = $false
                            # Базовая фильтрация: Игнорируем лаунчеры, оверлеи и античиты (Если их заморозить, игра вылетит)
                            if ($pName -match "launcher|overlay|anticheat|crashreporter|crashhandler|eac_|^eac$|battleye|beservice") {
                                $isIgnored = $true
                            } else {
                                # Сверяем с глобальным белым списком ОС
                                foreach ($item in $IgnoreArray) { 
                                    if ($pName -eq $item) { $isIgnored = $true; break } 
                                }
                            }
                            
                            if (-not $isIgnored) {
                                # --- Игра найдена и захвачена в залог ---
                                $script:LockedPID = $pidRef # Сохраняем PID игры
                                try { (New-Object System.Media.SoundPlayer "$env:windir\Media\Speech On.wav").Play() } catch {}
                                Write-Log "=== ИГРА НАЙДЕНА: $pName.exe (PID: $pidRef) ==="
                                Set-WlanAutoConfig -Enable $false

                                # --- Защита стримеров и киберспортсменов ---
                                Get-Process -Name "obs64", "discord", "ts3client" 2>> $env:SystemDrive\EastricaTools\Eastrica_ErrorTrace.log | ForEach-Object {
                                    try {
                                        [WinAPI]::SetPriorityFast($_.Id, 0x00008000) # ABOVE_NORMAL_PRIORITY (Выше среднего)
                                        [WinAPI]::SetAffinityFast($_.Id, $GameMask)  # Оставляем OBS/Discord на мощных P-Cores
                                        Write-Log "Режим Стримера: Защищен процесс $($_.ProcessName)"
                                    } catch {}
                                }
                                
                                # Пишем статус игры в глобальный реестр (полезно для сторонних скриптов)
                                try { Set-ItemProperty -Path "HKLM:\SOFTWARE\Eastrica" -Name "GameActive" -Value 1 -Type DWord -Force 2>> $env:SystemDrive\EastricaTools\Eastrica_ErrorTrace.log } catch {}
                                
                                # Прячем конфигуратор (Окно GUI) и включаем иконку в трее через Invoke (защита от потоков)
                                if ($form.Visible) {
                                    $form.Invoke([action]{
                                        $form.Hide()
                                        if ($notifyIcon) { $notifyIcon.Visible = $true }
                                    })
                                }
                                
                                # Запрещаем всплывающие уведомления Windows, чтобы они не выбивали игру на рабочий стол
                                try {
                                    $NocPath = "HKCU:\Software\Microsoft\Windows\CurrentVersion\Notifications\Settings"
                                    if (!(Test-Path $NocPath)) { New-Item $NocPath -Force | Out-Null }
                                    Set-ItemProperty -Path $NocPath -Name "NOC_GLOBAL_SETTING_TOASTS_STATE" -Value 0 -Type DWord -Force 2>> $env:SystemDrive\EastricaTools\Eastrica_ErrorTrace.log
                                } catch {}

                                Start-Sleep -Milliseconds 800 # Небольшая задержка перед жесткими твиками
                                
                                # 1. Отключение вторых мониторов
                                if ($script:optMonitors) {
                                    try {
                                        $global:SavedTopology = [WinAPI]::GetCurrentTopology() # Запоминаем: у вас дублирование, расширение или что-то еще?
                                        if ($global:SavedTopology -ne 1) {
                                            Write-Log "Топология мониторов сохранена ($global:SavedTopology). Отключение дополнительных дисплеев..."
                                            cmd.exe /q /c "DisplaySwitch.exe /internal >nul 2>&1" # Выключаем все мониторы, кроме основного (Снимает нагрузку с DWM и GPU)
                                            $script:IsMonitorsDisabled = $true
                                        }
                                    } catch {}
                                }
                                
                                # 2. Анти-сон
                                try { [WinAPI]::PreventSleep(); Write-Log "Анти-сон включен." } catch {} # Жестко запрещаем ПК спать, пока игра открыта

                                # 3. Форсирование GPU (мгновенно через WinAPI, 0% задержки)
                                try {
                                    $exePath = [WinAPI]::GetProcessPathFast($pidRef)
                                    if ($exePath -and $exePath -ne "") {
                                        $GpuPrefs = "HKCU:\Software\Microsoft\DirectX\UserGpuPreferences"
                                        if (!(Test-Path $GpuPrefs)) { New-Item $GpuPrefs -Force | Out-Null }
                                        Set-ItemProperty -Path $GpuPrefs -Name $exePath -Value "GpuPreference=2;" -Type String -Force 2>> $env:SystemDrive\EastricaTools\Eastrica_ErrorTrace.log
                                    }
                                } catch {}
                                
                                # 4. Таймер
                                $currentRes = 0
                                [WinAPI]::NtSetTimerResolution(5000, $true, [ref]$currentRes) | Out-Null # Ускоряем глобальный системный таймер ядра до 0.5 мс (Максимальная отзывчивость движка игры)
                                
                                # Применяем приоритет, кванты и affinity строго один раз (без спама и сброса кэша)
                                try {
                                    [WinAPI]::SetPriorityFast($script:LockedPID, 0x00000080)
                                    [WinAPI]::SetAffinityFast($script:LockedPID, $GameMask)
                                    [WinAPI]::SetPrioritySeparation(42)
                                } catch {}

                                # 5. Изоляция DWM и Explorer (Оконный менеджер и Проводник)
                                Get-Process -Name "explorer" 2>> $env:SystemDrive\EastricaTools\Eastrica_ErrorTrace.log | ForEach-Object { 
                                    try { 
                                        if ($script:optExplorerEco) {
                                            [WinAPI]::SetPriorityFast($_.Id, 0x00000040) # IDLE_PRIORITY_CLASS
                                            [WinAPI]::SetAffinityFast($_.Id, $TrashMask) # Проводник убираем на E-Cores
                                        }
                                    } catch {} 
                                }
                                Get-Process -Name "dwm" 2>> $env:SystemDrive\EastricaTools\Eastrica_ErrorTrace.log | ForEach-Object { 
                                    try { 
                                        # DWM удерживается на P-Cores с высшим приоритетом во избежание статтеров кадра
                                        [WinAPI]::SetPriorityFast($_.Id, 0x00000080) # DWM получает HIGH Priority на P-Cores
                                        [WinAPI]::SetAffinityFast($_.Id, $GameMask)  # Отрисовка кадров идет на мощных ядрах
                                    } catch {} 
                                }
                                
                                Get-Process -Name "GameBar*", "bcastdvr", "smartscreen", "Widgets" 2>> $env:SystemDrive\EastricaTools\Eastrica_ErrorTrace.log | Stop-Process -Force
                                
                                # 6. QoS (Выделенный канал интернета)
                                try {
                                    Remove-NetQosPolicy -Name "Eastrica_TempQoS" -Confirm:$false 2>> $env:SystemDrive\EastricaTools\Eastrica_ErrorTrace.log
                                    New-NetQosPolicy -Name "Eastrica_TempQoS" -AppPathNameMatchCondition "$pName.exe" -DSCPAction 46 -PriorityValue8021Action 5 -NetworkProfile All -Confirm:$false -ErrorAction SilentlyContinue | Out-Null # Сетевая карта будет обрабатывать пакеты ИГРЫ первыми (Нулевой пинг)
                                } catch {}
                                # Прямой обход инспекции Брандмауэра (WFP Bypass) для нулевой сетевой задержки игры
                                try {
                                    $exePath = [WinAPI]::GetProcessPathFast($script:LockedPID)
                                    if ($exePath -ne "") {
                                        Remove-NetFirewallRule -DisplayName "Eastrica_TempWFP" -ErrorAction SilentlyContinue
                                        New-NetFirewallRule -DisplayName "Eastrica_TempWFP" -Direction Outbound -Program "$exePath" -Action Allow -Protocol Any -Profile Any -ErrorAction SilentlyContinue | Out-Null
                                    }
                                } catch {}
                                
                                # 7. Питание и Службы
                                if ($CurrentPlan -ne $UltimatePlan) { try { powercfg.exe /setactive $UltimatePlan >$null 2>&1 } catch {} } # Включаем план максимальной производительности
                                foreach($s in $ServicesToStop) { 
                                    try { 
                                        if ((Get-Service $s 2>> $env:SystemDrive\EastricaTools\Eastrica_ErrorTrace.log).Status -eq 'Running') {
                                            $script:RunningServices += $s
                                            Start-Process "sc.exe" -ArgumentList "stop $s" -WindowStyle Hidden
                                        }
                                    } catch {} 
                                }
                                
                                # 8. Отключение батареи (Фикс DPC)
                                if ($script:optBattery -and $global:BatId) {
                                    Write-Log "Отключение ACPI-батареи (PNP0C0A)..."
                                    try {
                                        $Vendor = (Get-CimInstance Win32_ComputerSystem 2>> $env:SystemDrive\EastricaTools\Eastrica_ErrorTrace.log).Manufacturer
                                        if ($Vendor -match "ASUS|Lenovo|Razer|Alienware") {
                                            Write-Log "Батарея не отключена: обнаружен вендор $Vendor (Аппаратный троттлинг)" "WARN"
                                        } else {
                                            cmd.exe /c "pnputil /disable-device `"$global:BatId`" >nul 2>&1"
                                            $script:IsBatteryDisabled = $true
                                            Write-Log "Батарея успешно отключена"
                                        }
                                    } catch {}
                                }
                                
                                try { ipconfig /flushdns | Out-Null; arp -d * 2>$null | Out-Null } catch {} # Очищаем сетевой кэш
                                
                                # 9. Фильтрация и мягкая заморозка (Eco Mode)
                                # Получаем список исключений, которые вписал юзер из кэшированной переменной
                                $RawWhiteList = $script:whiteListText -split ',' | ForEach-Object { $_.Trim().ToLower() } | Where-Object { $_ -ne "" }
                                
                                Write-Log "Снижение приоритета фоновых программ (TrashApps)..."
                                foreach ($t in $TrashApps) {
                                    Get-Process -Name $t 2>> $env:SystemDrive\EastricaTools\Eastrica_ErrorTrace.log | ForEach-Object {
                                        $pNameLow = $_.ProcessName.ToLower()
                                        $isWhitelisted = $false
                                        foreach ($w in $RawWhiteList) { if ($pNameLow -match $w) { $isWhitelisted = $true; break } } # Проверяем белый список
                                        
                                        if (-not $isWhitelisted) {
                                            try { 
                                                [WinAPI]::SetPriorityFast($_.Id, 0x00000040) # IDLE PRIORITY (Самый низкий приоритет ЦП)
                                                [WinAPI]::SetAffinityFast($_.Id, $TrashMask) # Выкидываем лаунчеры на E-ядра
                                            } catch {}
                                        }
                                    }
                                }
                                
                                Write-Log "Мягкая заморозка древа процессов (Eco Mode)..."
                                foreach ($app in $AppsToSuspend) {
                                    Get-Process -Name $app 2>> $env:SystemDrive\EastricaTools\Eastrica_ErrorTrace.log | ForEach-Object {
                                        $pNameLow = $_.ProcessName.ToLower()
                                        $isWhitelisted = $false
                                        foreach ($w in $RawWhiteList) { if ($pNameLow -match $w) { $isWhitelisted = $true; break } } # Игнорируем Discord и OBS, если они в вайтлисте
                                        
                                        if (-not $isWhitelisted) {
                                            # Важно: находим все дочерние процессы! Хром, например, создает 30 штук.
                                            $treePIDs = [WinAPI]::GetProcessTree($_.Id)
                                            foreach ($tPid in $treePIDs) {
                                                if ($script:SuspendedPIDs -notcontains $tPid) {
                                                    try {
                                                        [WinAPI]::SetPriorityFast($tPid, 0x00004000) # 0x4000 = BELOW_NORMAL_PRIORITY_CLASS
                                                        [WinAPI]::SetMemoryPriority($tPid, 1) 
                                                        [WinAPI]::EnableEcoMode($tPid) 
                                                        [WinAPI]::SetAffinityFast($tPid, $TrashMask) 
                                                        $script:SuspendedPIDs += $tPid 
                                                    } catch {}
                                                }
                                            }
                                            Write-Log "Дерево процесса $($_.ProcessName) (PID: $($_.Id)) удушено (BelowNormal + EcoMode)."
                                        }
                                    }
                                }
                                
                                # 10. Безопасное скрытие интерфейса Windows на всех мониторах
                                if ($script:optKillExplorer) {
                                    try { 
                                        $progman = [WinAPI]::FindWindow("Progman", $null)
                                        if ($progman -ne [IntPtr]::Zero) { [WinAPI]::ShowWindow($progman, 0) } # 0 = SW_HIDE
                                        
                                        $workerW = [WinAPI]::FindWindow("WorkerW", $null)
                                        if ($workerW -ne [IntPtr]::Zero) { [WinAPI]::ShowWindow($workerW, 0) }
                                        
                                        # Скрываем главную панель задач
                                        $taskbar = [WinAPI]::FindWindow("Shell_TrayWnd", $null)
                                        if ($taskbar -ne [IntPtr]::Zero) { [WinAPI]::ShowWindow($taskbar, 0) }
                                        
                                        # Скрываем вторичные панели задач на всех дополнительных мониторах
                                        $secTaskbar = [WinAPI]::FindWindow("Shell_SecondaryTrayWnd", $null)
                                        while ($secTaskbar -ne [IntPtr]::Zero) {
                                            [WinAPI]::ShowWindow($secTaskbar, 0)
                                            $secTaskbar = [WinAPI]::FindWindowEx([IntPtr]::Zero, $secTaskbar, "Shell_SecondaryTrayWnd", $null)
                                        }
                                        
                                        $script:IsExplorerHidden = $true
                                        Write-Log "Интерфейс Проводника на всех экранах безопасно скрыт (SW_HIDE)."
                                    } catch {}
                                }
                                
                                # Финализация захвата игры (очистка памяти строго в момент старта)
                                try { 
                                    [WinAPI]::FlushSystemCacheAndStandby()
                                    [System.GC]::Collect()
                                    [System.GC]::WaitForPendingFinalizers()
                                    Write-Log "System Cache & Standby List очищены." 
                                } catch {}
                            }
                        }
                    }
                }
            }
        } else {
            # ==============================================================
            # --- Игра уже запущена (отслеживаем её состояние) ---
            # ==============================================================
            $isGameRunning = $true

            # Если пользователь нажал Ctrl + Shift + F12 (Хук сработал на уровне ОС)
            if ([HotKeyManager]::PanicTriggered) {
                [HotKeyManager]::PanicTriggered = $false # Сбрасываем флаг
                Write-Log "!!! СРАБОТАЛ PANIC HOTKEY (Ctrl+Shift+F12) !!!" "WARN"
                $isGameRunning = $false # Принудительно разрываем цикл
                try { (New-Object System.Media.SoundPlayer "$env:windir\Media\Speech Off.wav").Play() } catch {}
            } else {
                # Нормальная проверка: Жив ли процесс игры в оперативной памяти?
                # Запрашиваем код завершения процесса. Если 259 (STILL_ACTIVE) — он жив.
                $isGameRunning = [WinAPI]::IsProcessAlive($script:LockedPID)
            }

            if ($isGameRunning) {
                # --- Логика Alt+Tab (сворачивание игры) ---
                $currentHwnd = [WinAPI]::GetForegroundWindow() # Кто сейчас на экране?
                $fgPid = 0
                [WinAPI]::GetWindowThreadProcessId($currentHwnd, [ref]$fgPid) | Out-Null
                
                $fgName = [WinAPI]::GetProcessNameFast($fgPid)
                # Игнорируем оверлеи (Они отрисовываются поверх игры, но это не значит, что игру свернули)
                $isOverlay = ($fgName -match "steamwebhelper|discord|gamebar|rtss|nvidia|shellappruntime|volume")

                # Если окно игры потеряло фокус (Игрок свернулся на рабочий стол или браузер)
                if ($fgPid -ne $script:LockedPID -and $script:isGameInForeground -and -not $isOverlay) {
                    $script:isGameInForeground = $false # Меняем флаг
                    Write-Log "Игра свернута (Alt+Tab). Разморозка фоновых приложений..."
                    Set-WlanAutoConfig -Enable $true
                    
                    Write-Log "Синхронизация квантов планировщика Eastrica (Win32PrioritySeparation = 42)..."
                    try { [WinAPI]::SetPrioritySeparation(42) } catch {}
                    
                    if ($script:IsExplorerHidden) {
                        Write-Log "Восстановление видимости Проводника (Alt+Tab)..."
                        try { 
                            $progman = [WinAPI]::FindWindow("Progman", $null)
                            if ($progman -ne [IntPtr]::Zero) { [WinAPI]::ShowWindow($progman, 5) }
                            $workerW = [WinAPI]::FindWindow("WorkerW", $null)
                            if ($workerW -ne [IntPtr]::Zero) { [WinAPI]::ShowWindow($workerW, 5) }
                            $taskbar = [WinAPI]::FindWindow("Shell_TrayWnd", $null)
                            if ($taskbar -ne [IntPtr]::Zero) { [WinAPI]::ShowWindow($taskbar, 5) }
                            Get-Process -Name "ShellExperienceHost", "TextInputHost", "StartMenuExperienceHost" -ErrorAction SilentlyContinue | Stop-Process -Force
                        } catch {}
                    }

                    # При сворачивании игры (Alt+Tab)
                    if ($script:optExplorerEco) {
                        Get-Process -Name "explorer" 2>> $env:SystemDrive\EastricaTools\Eastrica_ErrorTrace.log | ForEach-Object { 
                            try { [WinAPI]::SetAffinityFast($_.Id, $TrashMask) } catch {} 
                        }
                        Get-Process -Name "dwm" 2>> $env:SystemDrive\EastricaTools\Eastrica_ErrorTrace.log | ForEach-Object { 
                            try { [WinAPI]::SetAffinityFast($_.Id, $GameMask) } catch {} 
                        }
                    }
                    
                    # Плавная разморозка замороженных процессов (Браузеров/Discord), чтобы они работали нормально
                    foreach ($susPid in $script:SuspendedPIDs) {
                        try { 
                            [WinAPI]::SetPriorityFast($susPid, 0x00000020) # Возвращаем NORMAL_PRIORITY_CLASS
                            [WinAPI]::SetMemoryPriority($susPid, 5)       # Возвращаем нормальный приоритет RAM
                            [WinAPI]::DisableEcoMode($susPid)             # Выключаем Eco Mode
                            [WinAPI]::SetAffinityFast($susPid, $FullMask) # Разрешаем работать на всех ядрах
                        } catch {}
                    }
                } 
                # Если игрок вернулся обратно в окно игры (Развернул)
                elseif ($fgPid -eq $script:LockedPID -and -not $script:isGameInForeground) {
                    $script:isGameInForeground = $true
                    Write-Log "Игра развернута. Повторная изоляция (Однократно)..."
                    Set-WlanAutoConfig -Enable $false
                    
                    # При возврате в игру применяем настройки строго 1 раз (без спама и микростаттеров)
                    try {
                        [WinAPI]::SetPriorityFast($script:LockedPID, 0x00000080)
                        [WinAPI]::SetAffinityFast($script:LockedPID, $GameMask)
                        [WinAPI]::SetPrioritySeparation(42)
                    } catch {}

                    if ($script:IsExplorerHidden) {
                        Write-Log "Скрытие видимости Проводника (Alt+Tab)..."
                        try { 
                            $progman = [WinAPI]::FindWindow("Progman", $null)
                            if ($progman -ne [IntPtr]::Zero) { [WinAPI]::ShowWindow($progman, 0) }
                            $workerW = [WinAPI]::FindWindow("WorkerW", $null)
                            if ($workerW -ne [IntPtr]::Zero) { [WinAPI]::ShowWindow($workerW, 0) }
                            $taskbar = [WinAPI]::FindWindow("Shell_TrayWnd", $null)
                            if ($taskbar -ne [IntPtr]::Zero) { [WinAPI]::ShowWindow($taskbar, 0) }
                        } catch {}
                    }

                    # Жестко замораживаем всё обратно
                    foreach ($susPid in $script:SuspendedPIDs) {
                        try { 
                            [WinAPI]::SetMemoryPriority($susPid, 1)
                            [WinAPI]::EnableEcoMode($susPid)
                            [WinAPI]::SetAffinityFast($susPid, $TrashMask)
                        } catch {}
                    }

                    # При возврате в игру
                    if ($script:optExplorerEco) {
                        Get-Process -Name "explorer" 2>> $env:SystemDrive\EastricaTools\Eastrica_ErrorTrace.log | ForEach-Object { 
                            try { [WinAPI]::SetAffinityFast($_.Id, $TrashMask) } catch {} 
                        }
                        Get-Process -Name "dwm" 2>> $env:SystemDrive\EastricaTools\Eastrica_ErrorTrace.log | ForEach-Object { 
                            try { [WinAPI]::SetAffinityFast($_.Id, $GameMask) } catch {} 
                        }
                    }
                }

                # --- Интеллектуальная очистка памяти (Smart RAM Flush) ---
                if ($script:isGameInForeground -and $script:optAutoFlush) {
                    # Получаем текущий объем доступной (свободной) оперативной памяти в мегабайтах через C# WinAPI
                    # Вызов работает мгновенно (за 0.001мс) и не нагружает процессор в отличие от WMI-запросов
                    $FreeRamMB = [WinAPI]::GetFreeRamMB()
                    
                    # Если свободной памяти осталось меньше 1500 МБ (Критический уровень перед началом статтеров)
                    if ($FreeRamMB -lt 1500) {
                        try {
                            # 1. Сжимаем рабочие наборы памяти (Working Set) ТОЛЬКО у свернутых фоновых программ
                            # Кэш самой игры остается нетронутым, что исключает фризы при возвращении в игру
                            foreach ($susPid in $script:SuspendedPIDs) {
                                try { [WinAPI]::EmptyWorkingSetFast($susPid) } catch {}
                            }
                            
                            # 2. Жестко вычищаем кэш файловой системы и ожидающую память (Standby List),
                            # которая "съедает" ОЗУ и заставляет Windows использовать медленный файл подкачки на SSD
                            [WinAPI]::FlushSystemCacheAndStandby()
                            
                            # 3. Записываем событие экстренной очистки в лог-файл Директора для отладки
                            Write-Log "Критически мало ОЗУ ($FreeRamMB MB). Экстренная интеллектуальная очистка выполнена." "WARN"
                        } catch {}
                    }
                }
            }

            if (-not $isGameRunning) {
                # --- Игрок вышел из игры (или она крашнулась) ---
                Write-Log "=== ИГРА ЗАКРЫТА ИЛИ СБРОШЕНА ==="
                $timer.Stop() # Сначала глушим таймер
                Restore-SystemState # Вызываем блок восстановления системы
                
                # Полное уничтожение иконки трея и окна через безопасный Invoke из фонового потока
                try { if ($notifyIcon) { $form.Invoke([action]{ $notifyIcon.Visible = $false; $notifyIcon.Dispose() }) } } catch {}
                try { $form.Invoke([action]{ $form.Dispose() }) } catch {}
                
                # Application::Exit() удалено для предотвращения зависания/краша потоков
                [System.Environment]::Exit(0) # Жесткое завершение процесса без зависания
            }
        }
    } catch {
        Write-Log "Критическая ошибка в главном цикле: $($_.Exception.Message)" "ERROR"
    }
}

# Обработчик ручного закрытия окна (с освобождением хука хоткея)
$form.Add_FormClosed({ 
    $global:KeepRunning = $false 
    $timer.Stop()
    if ($script:LockedPID -ne 0 -or $script:IsExplorerHidden -or $script:SuspendedPIDs.Count -gt 0) {
        Restore-SystemState -ShowPopup $false
    }
    # Корректное освобождение зарегистрированного хоткея Ctrl+Shift+F12
    if ($global:hkManager) {
        try { $global:hkManager.Dispose() } catch {}
    }
    try { 
        if ($notifyIcon) { 
            $notifyIcon.Visible = $false 
            $notifyIcon.Dispose() 
        } 
    } catch {}
    Write-Log "Окно закрыто пользователем. Хоткей освобожден. Выход."
    Write-Log "================================================================================"
    [System.Environment]::Exit(0)
})

# Кнопка запуска (для ПКМ Рабочего стола, .exe и .lnk файлов)
$btnLaunch = New-Object System.Windows.Forms.Button
if ($TargetApp -and (Test-Path $TargetApp)) {
    $btnLaunch.Text = (L "ЗАПУСТИТЬ ИГРУ" "LAUNCH GAME")
} else {
    $btnLaunch.Text = (L "ЗАПУСТИТЬ ОЖИДАНИЕ ИГРЫ" "START GAME MONITORING")
}
$btnLaunch.Size = New-Object System.Drawing.Size([int](435 * $Scale), [int](42 * $Scale))
$btnLaunch.Location = New-Object System.Drawing.Point([int](12 * $Scale), [int](298 * $Scale))
$btnLaunch.Font = New-Object System.Drawing.Font("Segoe UI", 11, [System.Drawing.FontStyle]::Bold)
$btnLaunch.BackColor = [System.Drawing.Color]::FromArgb(0, 120, 215)
$btnLaunch.ForeColor = [System.Drawing.Color]::White
$btnLaunch.FlatStyle = [System.Windows.Forms.FlatStyle]::Flat
$btnLaunch.FlatAppearance.BorderSize = 0
$btnLaunch.Cursor = [System.Windows.Forms.Cursors]::Hand

$btnLaunch.Add_Click({
    $btnLaunch.Enabled = $false
    $btnLaunch.BackColor = [System.Drawing.Color]::FromArgb(45, 45, 50)
    $btnLaunch.Text = (L "ОЖИДАНИЕ ПОЛНОЭКРАННОЙ ИГРЫ..." "WAITING FOR FULLSCREEN GAME...")
    $lbl.Text = (L "Ожидание запуска игры в полноэкранном режиме..." "Waiting for game launch in fullscreen mode...")
    $pb.Style = "Marquee"
    $pb.MarqueeAnimationSpeed = 8

    # Кэшируем значения всех элементов управления (WinForms) в переменные уровня скрипта,
    # чтобы фоновый поток (Task::Run) мог читать их без ошибки Cross-Thread Operation.
    $script:optMonitors = $chkMonitors.Checked
    $script:optBattery = $chkBattery.Checked
    $script:optExplorerEco = $chkExplorerEco.Checked
    $script:optKillExplorer = $chkKillExplorer.Checked
    $script:optAutoFlush = $chkAutoFlush.Checked
    $script:whiteListText = $txtWhitelist.Text

    # Пересчитываем маску ядер с учетом только что выбранной галочки SMT
    if ($CpuName -match "7950X3D|9950X3D" -or $CpuName -match "7900X3D|9900X3D" -or $CpuName -match "7800X3D|9800X3D") {
        [uint64]$tempMask = 0
        if ($chkSMT.Checked) {
            for ($i = 2; $i -lt $Ccd0_Threads; $i += 2) { $tempMask = $tempMask -bor ([uint64]1 -shl $i) }
        } else {
            for ($i = 2; $i -lt $Ccd0_Threads; $i++) { $tempMask = $tempMask -bor ([uint64]1 -shl $i) }
        }
        $script:GameMask = [uint64]$tempMask
    } elseif ($IsIntel -and $ECores -gt 0) {
        if ($chkSMT.Checked) {
            [uint64]$tempMask = 0
            $HasSMT = ($TotalCores -gt $PhysCores)
            if ($chkSMT.Checked -and $HasSMT) {
                for ($i = 2; $i -lt $PCoreThreads; $i += 2) { $tempMask = $tempMask -bor ([uint64]1 -shl $i) }
            } else {
                for ($i = 2; $i -lt $PCoreThreads; $i++) { $tempMask = $tempMask -bor ([uint64]1 -shl $i) }
            }
            $script:GameMask = [uint64]$tempMask
        } else {
            $BaseGameMask = [uint64](([uint64]1 -shl $PCoreThreads) - 1)
            $script:GameMask = [uint64]($BaseGameMask - 3)
        }
    } else {
        if ($EffectiveCores -gt 4) {
            if ($chkSMT.Checked) {
                [uint64]$tempMask = 0
                for ($i = 2; $i -lt $EffectiveCores; $i += 2) { $tempMask = $tempMask -bor ([uint64]1 -shl $i) }
                $script:GameMask = [uint64]$tempMask
            } else {
                $script:GameMask = [uint64](([uint64]1 -shl $EffectiveCores) - 1 - 3)
            }
        }
    }
    if ($script:GameMask -le 0) { $script:GameMask = $FullMask }

    # Если запуск был через ПКМ по .exe или .lnk файлу — запускаем саму игру
    if ($TargetApp -and (Test-Path $TargetApp)) {
        Write-Log "Режим ПКМ: Попытка запуска целевого приложения: $TargetApp"
        try { 
            [System.GC]::Collect() # Вызываем системный сборщик мусора перед запуском тяжелой игры
            [System.GC]::WaitForPendingFinalizers()
            [WinAPI]::FlushSystemCacheAndStandby() # Жестко очищаем оперативную память (Замена ISLC)
            if ($TargetApp.EndsWith(".lnk", [System.StringComparison]::OrdinalIgnoreCase)) {
                Start-Process $TargetApp -ErrorAction Stop
            } else {
                $WorkDir = Split-Path $TargetApp
                Start-Process $TargetApp -WorkingDirectory $WorkDir -ErrorAction Stop
            }
            Write-Log "Приложение успешно запущено."
        } catch {
            Write-Log "Ошибка запуска приложения $TargetApp : $($_.Exception.Message)" "ERROR"
        }
    }

    # Заворачиваем тяжелую логику в асинхронный Task, чтобы не вешать главный поток иконки в трее
    $timer.Add_Tick({ [System.Threading.Tasks.Task]::Run({ & $ProcessWatcherLogic }) })
    # Запуск аппаратного хука смены окон (0% нагрузки на CPU)
    [WinAPI]::StartForegroundHook({ [System.Threading.Tasks.Task]::Run({ & $ProcessWatcherLogic }) })
    $timer.Start()
})
$form.Controls.Add($btnLaunch)
$form.AcceptButton = $btnLaunch # Позволяет запускать игру нажатием клавиши Enter

$global:hkManager = New-Object HotKeyManager # Активация аппаратного хука клавиатуры
[System.Windows.Forms.Application]::Run($form) # Запуск отображения графического окна

# Финализация в самом конце Thread Director (после закрытия формы)
try { [WinAPI]::StopForegroundHook() } catch {}
if ($global:hkManager) {
    try { $global:hkManager.Dispose() } catch {}
}
try { if ($notifyIcon) { $notifyIcon.Visible = $false; $notifyIcon.Dispose() } } catch {}
if ($form -ne $null -and -not $form.IsDisposed) {
    try { $form.Dispose() } catch {}
}
[System.Environment]::Exit(0)
'@

