Show-ProgressStep -StepNum 65 -TotalSteps 81 -Activity "Интеграция Eastrica Thread Director в меню ПКМ..."
Write-Host "==============================================================================" -ForegroundColor DarkGray
Write-Host 'РАЗДЕЛ 65: ИНТЕГРАЦИЯ "EASTRICA THREAD DIRECTOR" В КОНТЕКСТНЫЕ МЕНЮ (ПКМ)' -ForegroundColor Cyan
Write-Host "==============================================================================" -ForegroundColor DarkGray

$DirectorMenuKey = "HKCR:\Directory\Background\shell\EastricaTools\shell\00_ThreadDirector"
$ExeMenuKey = "HKCR:\exefile\shell\EastricaThreadDirectorLaunch"
$LnkMenuKey = "HKCR:\lnkfile\shell\EastricaThreadDirectorLaunch"

# Регистрация тумблера Брандмауэра для всех .EXE файлов
$FwToggleMenuKey = "HKCR:\exefile\shell\EastricaToggleFirewall"
if (!(Test-Path "$FwToggleMenuKey\command")) { Apply-Tweak "Создание команды тумблера Брандмауэра" { New-Item -Path "$FwToggleMenuKey\command" -Force | Out-Null } }
Apply-Tweak "Установка названия тумблера Брандмауэра для .EXE" { Set-ItemProperty -Path $FwToggleMenuKey -Name "MUIVerb" -Value (L "Блокировать / Разрешить сеть (Брандмауэр)" "Block / Allow Network (Firewall)") -Force *>&1 | Out-File -FilePath $global:LogPath -Append -Encoding UTF8 }
Apply-Tweak "Установка иконки тумблера Брандмауэра для .EXE" { Set-ItemProperty -Path $FwToggleMenuKey -Name "Icon" -Value "firewallcontrolpanel.dll,-1" -Force *>&1 | Out-File -FilePath $global:LogPath -Append -Encoding UTF8 }
