Apply-Tweak "Инъекция вызова тумблера Брандмауэра в меню .EXE" { Set-Item -Path "$FwToggleMenuKey\command" -Value $FwToggleCmd -Force *>&1 | Out-File -FilePath $global:LogPath -Append -Encoding UTF8 }

if (-not $global:OptAI) {
