    Apply-Tweak "Установка иконки меню для .LNK" { Set-ItemProperty -Path $LnkMenuKey -Name "Icon" -Value "perfmon.exe,0" -Force *>&1 | Out-File -FilePath $global:LogPath -Append -Encoding UTF8 }
    $LnkCmdKey = "$LnkMenuKey\command"
