    Apply-Tweak "Инъекция команды запуска (TargetApp) для Ярлыков (.LNK)" { Set-Item -Path $LnkCmdKey -Value $LaunchCmd -Force *>&1 | Out-File -FilePath $global:LogPath -Append -Encoding UTF8 }
} else {
