    Apply-Tweak "Удаление меню ThreadDirector с рабочего стола" { Remove-Item -LiteralPath $DirectorMenuKey -Recurse -Force *>&1 | Out-File -FilePath $global:LogPath -Append -Encoding UTF8 }
    Apply-Tweak "Удаление меню запуска ThreadDirector для .EXE" { Remove-Item -LiteralPath $ExeMenuKey -Recurse -Force *>&1 | Out-File -FilePath $global:LogPath -Append -Encoding UTF8 }
    Apply-Tweak "Удаление меню запуска ThreadDirector для .LNK" { Remove-Item -LiteralPath $LnkMenuKey -Recurse -Force *>&1 | Out-File -FilePath $global:LogPath -Append -Encoding UTF8 }
}

Write-Host ""
# ==============================================================================
# Раздел 66: Управление оперативной памятью и резервом диска
# ==============================================================================
Show-ProgressStep -StepNum 66 -TotalSteps 81 -Activity "Управление оперативной памятью и резервом диска..."
Write-Host "==============================================================================" -ForegroundColor DarkGray
Write-Host "РАЗДЕЛ 66: УПРАВЛЕНИЕ ОПЕРАТИВНОЙ ПАМЯТЬЮ И РЕЗЕРВОМ ДИСКА" -ForegroundColor Cyan
Write-Host "==============================================================================" -ForegroundColor DarkGray

# Освобождение 7GB дискового пространства (Reserved Storage)
# Windows 10/11 "крадет" 7+ ГБ на диске С: "на всякий случай" для обновлений. Отключаем это.
Apply-Tweak "Освобождение 7ГБ резервного хранилища (DISM ReservedStorage)" { DISM /Online /Set-ReservedStorageState /State:Disabled /Quiet /NoRestart *>&1 | Out-File -FilePath $global:LogPath -Append -Encoding UTF8 } # Освобождает резервное хранилище

# Умное управление сжатием памяти (Memory Compression & Page Combining)
if ($global:TotalRAM -ge 32) {
    # Отключаем объединение страниц: убивает фоновый сканер ядра, который постоянно ищет дубликаты в оперативной памяти.
    Apply-Tweak "Отключение поиска дубликатов ОЗУ (Disable-MMAgent PageCombining)" { try { Disable-MMAgent -PageCombining -ErrorAction Stop *>&1 | Out-File -FilePath $global:LogPath -Append -Encoding UTF8 } catch {} } # Отключаем поиск дубликатов ОЗУ
} else {
    Apply-Tweak "Включение объединения страниц ОЗУ)" { try { Enable-MMAgent -PageCombining -ErrorAction Stop *>&1 | Out-File -FilePath $global:LogPath -Append -Encoding UTF8 } catch {} } # Включаем объединение страниц
}
Apply-Tweak "Включение сжатия памяти" { try { Enable-MMAgent -MemoryCompression -ErrorAction Stop *>&1 | Out-File -FilePath $global:LogPath -Append -Encoding UTF8 } catch {} } # Отключение сжатия ОЗУ вызывает мощные фризы (статтеры) в тяжелых сценах

# Умная настройка службы SysMain (SuperFetch) на основе характеристик ПК
$SysDrivePart = Get-Partition -DriveLetter $env:SystemDrive.TrimEnd(':') -ErrorAction SilentlyContinue
$SysDrive = Get-PhysicalDisk | Where-Object { $_.DeviceId -eq $SysDrivePart.DiskNumber } 2>> $env:SystemDrive\EastricaTools\Eastrica_ErrorTrace.log # Надежно получаем физический системный диск
if ($global:TotalRAM -ge 16 -and ($SysDrive.MediaType -eq "SSD" -or $SysDrive.BusType -eq "NVMe")) {
    Write-Host " ► NVMe + 16GB+ RAM: Полное отключение SysMain (SuperFetch) для чистого I/O..." -ForegroundColor DarkGray
    Apply-Tweak "Остановка службы SysMain (SuperFetch)" { Stop-Service -Name "SysMain" -Force *>&1 | Out-File -FilePath $global:LogPath -Append -Encoding UTF8 } # При 16 ГБ и быстром SSD предварительное кэширование в ОЗУ только вредит дислокации страниц
    Apply-Tweak "Отключение службы SysMain (SuperFetch)" { Set-Service -Name "SysMain" -StartupType Disabled *>&1 | Out-File -FilePath $global:LogPath -Append -Encoding UTF8 } # Отключаем
} else {
    Write-Host " ► HDD / Мало RAM: SysMain оставлена включенной для защиты от статтеров диска." -ForegroundColor DarkGray
    Apply-Tweak "Включение службы SysMain (SuperFetch)" { Set-Service -Name "SysMain" -StartupType Automatic *>&1 | Out-File -FilePath $global:LogPath -Append -Encoding UTF8 } # Включаем, чтобы HDD не умирал от случайного чтения
    Apply-Tweak "Запуск службы SysMain (SuperFetch)" { Start-Service -Name "SysMain" *>&1 | Out-File -FilePath $global:LogPath -Append -Encoding UTF8 }
}

Write-Host ""
# ==============================================================================
# Раздел 67: Права на блокировку памяти (SeLockMemoryPrivilege)
# ==============================================================================
Show-ProgressStep -StepNum 67 -TotalSteps 81 -Activity "Предоставление прав на блокировку памяти..."
Write-Host "==============================================================================" -ForegroundColor DarkGray
Write-Host "РАЗДЕЛ 67: ПРАВА НА БЛОКИРОВКУ ПАМЯТИ (SELOCKMEMORYPRIVILEGE)" -ForegroundColor Cyan
Write-Host "==============================================================================" -ForegroundColor DarkGray
# Суть: Позволяет играм (и эмуляторам) блокировать свои страницы в ОЗУ, запрещая ОС выгружать их на диск.
$LsaCode = @"
using System;
using System.Runtime.InteropServices;
public class LsaWrapper {
    [StructLayout(LayoutKind.Sequential)] struct LSA_OBJECT_ATTRIBUTES { public int Length; public IntPtr RootDirectory; public IntPtr ObjectName; public uint Attributes; public IntPtr SecurityDescriptor; public IntPtr SecurityQualityOfService; }
    [StructLayout(LayoutKind.Sequential)] struct LSA_UNICODE_STRING { public ushort Length; public ushort MaximumLength; public IntPtr Buffer; }
    [DllImport("advapi32.dll")] static extern uint LsaOpenPolicy(IntPtr SystemName, ref LSA_OBJECT_ATTRIBUTES ObjectAttributes, uint AccessMask, out IntPtr PolicyHandle);
    [DllImport("advapi32.dll")] static extern uint LsaAddAccountRights(IntPtr PolicyHandle, IntPtr AccountSid, LSA_UNICODE_STRING[] UserRights, uint CountOfRights);
    [DllImport("advapi32.dll")] static extern uint LsaClose(IntPtr ObjectHandle);
    [DllImport("advapi32.dll")] static extern bool ConvertStringSidToSid(string StringSid, out IntPtr Sid);
    
    public static bool GrantLockMemory(string sid) {
        IntPtr policy; LSA_OBJECT_ATTRIBUTES attr = new LSA_OBJECT_ATTRIBUTES(); attr.Length = Marshal.SizeOf(typeof(LSA_OBJECT_ATTRIBUTES));
        if (LsaOpenPolicy(IntPtr.Zero, ref attr, 0x0810, out policy) == 0) {
            IntPtr pSid;
            if (ConvertStringSidToSid(sid, out pSid)) {
                LSA_UNICODE_STRING[] rights = new LSA_UNICODE_STRING[1];
                rights[0].Buffer = Marshal.StringToHGlobalUni("SeLockMemoryPrivilege");
                rights[0].Length = (ushort)(21 * 2); rights[0].MaximumLength = (ushort)((21 + 1) * 2);
                uint res = LsaAddAccountRights(policy, pSid, rights, 1);
                LsaClose(policy);
                return res == 0;
            }
        } return false;
    }
}
"@
if (-not ("LsaWrapper" -as [type])) { Add-Type -TypeDefinition $LsaCode -Language CSharp }

# Получаем SID текущего пользователя и SID группы локальных администраторов (S-1-5-32-544)
$CurrentIdent = [System.Security.Principal.WindowsIdentity]::GetCurrent()
$UserSID = $CurrentIdent.User.Value
$AdminGroupSID = "S-1-5-32-544" # Псевдоним встроенной группы BUILTIN\Administrators

Apply-Tweak "Выдача прав на блокировку страниц в памяти (SeLockMemoryPrivilege)" { 
    # Выдаем права текущему пользователю
    [void][LsaWrapper]::GrantLockMemory($UserSID)
    # Гарантированно выдаем права всей группе Администраторов для стабильной работы при установке через OOBE/SYSTEM
    if (-not [LsaWrapper]::GrantLockMemory($AdminGroupSID)) { 
        throw "Не удалось выдать SeLockMemoryPrivilege группе Администраторов" 
    }
}

# Выдача прав на мгновенную аллокацию файлов (Zero-filling bypass для Steam/Epic)
$VolumeCode = @"
using System;
using System.Runtime.InteropServices;
public class LsaVolume {
    [StructLayout(LayoutKind.Sequential)] struct LSA_OBJECT_ATTRIBUTES { public int Length; public IntPtr RootDirectory; public IntPtr ObjectName; public uint Attributes; public IntPtr SecurityDescriptor; public IntPtr SecurityQualityOfService; }
    [StructLayout(LayoutKind.Sequential)] struct LSA_UNICODE_STRING { public ushort Length; public ushort MaximumLength; public IntPtr Buffer; }
    [DllImport("advapi32.dll")] static extern uint LsaOpenPolicy(IntPtr SystemName, ref LSA_OBJECT_ATTRIBUTES ObjectAttributes, uint AccessMask, out IntPtr PolicyHandle);
    [DllImport("advapi32.dll")] static extern uint LsaAddAccountRights(IntPtr PolicyHandle, IntPtr AccountSid, LSA_UNICODE_STRING[] UserRights, uint CountOfRights);
    [DllImport("advapi32.dll")] static extern uint LsaClose(IntPtr ObjectHandle);
    [DllImport("advapi32.dll")] static extern bool ConvertStringSidToSid(string StringSid, out IntPtr Sid);
    
    public static bool GrantManageVolume(string sid) {
        IntPtr policy; LSA_OBJECT_ATTRIBUTES attr = new LSA_OBJECT_ATTRIBUTES(); attr.Length = Marshal.SizeOf(typeof(LSA_OBJECT_ATTRIBUTES));
        if (LsaOpenPolicy(IntPtr.Zero, ref attr, 0x0810, out policy) == 0) {
            IntPtr pSid;
            if (ConvertStringSidToSid(sid, out pSid)) {
                LSA_UNICODE_STRING[] rights = new LSA_UNICODE_STRING[1];
                rights[0].Buffer = Marshal.StringToHGlobalUni("SeManageVolumePrivilege");
                rights[0].Length = (ushort)(23 * 2); rights[0].MaximumLength = (ushort)((23 + 1) * 2);
                uint res = LsaAddAccountRights(policy, pSid, rights, 1);
                LsaClose(policy);
                return res == 0;
            }
        } return false;
    }
}
"@
if (-not ("LsaVolume" -as [type])) { Add-Type -TypeDefinition $VolumeCode -Language CSharp }

Apply-Tweak "Выдача прав на мгновенное выделение дискового пространства (Steam/Epic: SeManageVolumePrivilege)" { 
    [void][LsaVolume]::GrantManageVolume($UserSID)
    if (-not [LsaVolume]::GrantManageVolume($AdminGroupSID)) { 
        throw "Не удалось выдать SeManageVolumePrivilege группе Администраторов" 
    }
}

Write-Host ""
