Apply-Tweak "Восстановление опроса термозон материнской платы (Защита кулеров)" { Remove-ItemProperty -Path $ThermalZone -Name "DisableActivePolling" *>&1 | Out-File -FilePath $global:LogPath -Append -Encoding UTF8 }

# Блокировка автоматического обновления драйверов
