Apply-Tweak "Запрет принудительной перезагрузки при входе пользователя (NoAutoReboot)" { Set-ItemProperty -Path $WU_AU -Name "NoAutoRebootWithLoggedOnUsers" -Value 1 -Type DWord -Force *>&1 | Out-File -FilePath $global:LogPath -Append -Encoding UTF8 } # 1 = Запрет ребута
Apply-Tweak "Уведомлять о загрузке обновлений без авто-установки (AUOptions=2)" { Set-ItemProperty -Path $WU_AU -Name "AUOptions" -Value 2 -Type DWord -Force *>&1 | Out-File -FilePath $global:LogPath -Append -Encoding UTF8 } # 2 = Только уведомлять

# Запрет поиска драйверов в Центре обновлений при подключении новых устройств (например, мыши)
