Apply-Tweak "Отключение ИИ-определения активных часов" { Set-ItemProperty -Path $ActiveHours -Name "SmartActiveHoursState" -Value 2 -Type DWord -Force *>&1 | Out-File -FilePath $global:LogPath -Append -Encoding UTF8 } # 2 = Отключить ИИ-определение активных часов
