Apply-Tweak "Установка конца активности на 02:00 ночи" { Set-ItemProperty -Path $ActiveHours -Name "ActiveHoursEnd" -Value 2 -Type DWord -Force *>&1 | Out-File -FilePath $global:LogPath -Append -Encoding UTF8 }      # 2 = Конец в 02:00 ночи (18 часов — это максимум, который позволяет задать ОС)

