Apply-Tweak "Запрет фонового обслуживания системы (MaintenanceDisabled)" { Set-ItemProperty -Path $AutoMaintenance -Name "MaintenanceDisabled" -Value 1 -Type DWord -Force *>&1 | Out-File -FilePath $global:LogPath -Append -Encoding UTF8 } # 1 = Запрещает ОС запускать дефрагментацию/сканирование в простое без вашего ведома

