Apply-Tweak "Авто-удаление ярлыка Edge" { Set-ItemProperty -Path $EdgeUpdate -Name "RemoveDesktopShortcutDefault" -Value 1 -Type DWord -Force *>&1 | Out-File -FilePath $global:LogPath -Append -Encoding UTF8 } # 1 = Удалять ярлык автоматически

