$EdgePoly = "HKLM:\SOFTWARE\Policies\Microsoft\Edge"
if (!(Test-Path $EdgePoly)) { Apply-Tweak "Создание раздела политик Edge" { New-Item $EdgePoly -Force *>&1 | Out-File -FilePath $global:LogPath -Append -Encoding UTF8 } }
