$QoS_Key = "HKLM:\SOFTWARE\Policies\Microsoft\Windows\QoS"
if (!(Test-Path $QoS_Key)) { Apply-Tweak "Создание раздела QoS (Policies)" { New-Item -Path $QoS_Key -Force *>&1 | Out-File -FilePath $global:LogPath -Append -Encoding UTF8 } }
if ($global:OptTCP) {
