$SmartScreenEdge = "HKCU:\Software\Classes\Local Settings\Software\Microsoft\Windows\CurrentVersion\AppContainer\Storage\microsoft.microsoftedge_8wekyb3d8bbwe\MicrosoftEdge\PhishingFilter"
if (!(Test-Path $SmartScreenEdge)) { Apply-Tweak "Создание раздела PhishingFilter для Edge" { New-Item $SmartScreenEdge -Force *>&1 | Out-File -FilePath $global:LogPath -Append -Encoding UTF8 } }
Apply-Tweak "Отключение фишинг-фильтра в UWP-контейнере Edge" { Set-ItemProperty -Path $SmartScreenEdge -Name "EnabledV9" -Value 0 -Type DWord -Force *>&1 | Out-File -FilePath $global:LogPath -Append -Encoding UTF8 } # 0 = Отключаем только фишинг-фильтр внутри UWP контейнера Edge

# Сохраняем аппаратное ускорение WebView2 для всех частот обновления, чтобы не ломать UI современных лаунчеров и окна авторизации
$WebViewPath = "HKLM:\SOFTWARE\Policies\Microsoft\Edge\WebView2"
