Apply-Tweak "Восстановление аппаратного ускорения WebView2" { Remove-ItemProperty -Path $WebViewPath -Name "AdditionalBrowserArguments" *>&1 | Out-File -FilePath $global:LogPath -Append -Encoding UTF8 }

