# ==============================================================================
Show-ProgressStep -StepNum 71 -TotalSteps 81 -Activity "Применение твиков загрузчика Windows (BCDEdit)..."
Write-Host "==============================================================================" -ForegroundColor DarkGray
Write-Host "РАЗДЕЛ 71: ТВИКИ ЗАГРУЗЧИКА WINDOWS (BCDEDIT)" -ForegroundColor Cyan
Write-Host "==============================================================================" -ForegroundColor DarkGray

# Классическое и тихое поведение загрузчика (Ускорение запуска ПК)
Apply-Tweak "Отключение меню дополнительных вариантов загрузки (advancedoptions)" { cmd.exe /c "bcdedit /set {current} advancedoptions No >nul 2>&1"; $global:LASTEXITCODE = 0 }
Apply-Tweak "Отключение редактирования опций загрузчика (optionsedit)" { cmd.exe /c "bcdedit /set {current} optionsedit No >nul 2>&1"; $global:LASTEXITCODE = 0 }
Apply-Tweak "Установка текстового меню загрузки (bootmenupolicy Standard)" { cmd.exe /c "bcdedit /set {current} bootmenupolicy Standard >nul 2>&1"; $global:LASTEXITCODE = 0 }
Apply-Tweak "Стандартная анимация загрузчика (bootux Standard)" { cmd.exe /c "bcdedit /set {current} bootux Standard >nul 2>&1"; $global:LASTEXITCODE = 0 }
Apply-Tweak "Скрытие логотипа системы/Материнской платы при запуске (quietboot Yes)" { cmd.exe /c "bcdedit /set {current} quietboot Yes >nul 2>&1"; $global:LASTEXITCODE = 0 }
Apply-Tweak "Сброс принудительного x2apic (Защита от конфликта с IOMMU)" { cmd.exe /c "bcdedit /deletevalue x2apicpolicy >nul 2>&1"; $global:LASTEXITCODE = 0 } # Доверяем выбор архитектуре ядра или удаляем форсирование во избежание конфликта с IOMMU
Apply-Tweak "Удаление принудительного highestmode (Защита от черного экрана UEFI)" { 
    if ((cmd.exe /c "bcdedit /enum {current}") -match "\bhighestmode\b") { cmd.exe /c "bcdedit /deletevalue {current} highestmode >nul 2>&1" }
    $global:LASTEXITCODE = 0 
}

# Удаление устаревших и фейковых политик доступа к PCI, которые ломают систему
Apply-Tweak "Удаление мусорного твика configaccesspolicy" { cmd.exe /c "bcdedit /deletevalue configaccesspolicy >nul 2>&1"; $global:LASTEXITCODE = 0 } # Мусорный твик из Windows 7
Apply-Tweak "Удаление мусорного твика MSI из BCD" { cmd.exe /c "bcdedit /deletevalue MSI >nul 2>&1"; $global:LASTEXITCODE = 0 } # Мусорный твик
Apply-Tweak "Удаление мусорного твика pciExpress из BCD" { cmd.exe /c "bcdedit /deletevalue pciExpress >nul 2>&1"; $global:LASTEXITCODE = 0 } # Мусорный твик
Apply-Tweak "Удаление мусорного твика usefirmwarepcisettings" { cmd.exe /c "bcdedit /deletevalue usefirmwarepcisettings >nul 2>&1"; $global:LASTEXITCODE = 0 } # Мусорный твик

# Запрет использования физических адресов (устарело для UEFI)
$IsUEFI = (Get-ComputerInfo 2>> $env:SystemDrive\EastricaTools\Eastrica_ErrorTrace.log).BiosFirmwareType -match "UEFI" -or ($env:firmware_type -eq 'UEFI')
if (-not $IsUEFI) {
    Apply-Tweak "Отключение использования физических путей (Legacy BIOS)" { bcdedit /set usephysicaldestination No *>&1 | Out-File -FilePath $global:LogPath -Append -Encoding UTF8 } # На старых BIOS (Legacy) отключаем использование физических путей
} else {
    Apply-Tweak "Удаление флага usephysicaldestination (Для UEFI)" { cmd.exe /c "bcdedit /deletevalue usephysicaldestination >nul 2>&1"; $global:LASTEXITCODE = 0 } # На UEFI просто удаляем этот параметр
}

# Отключение проверки драйверов при ранней загрузке (ELAM - Early Launch Anti-Malware)
if ($global:OptAntiCheat) {
    # Античиты (Vanguard/FACEIT) ТРЕБУЮТ ELAM, чтобы загрузить свои модули защиты до запуска ОС.
    Apply-Tweak "Удаление запрета ELAM (Режим Античита)" { cmd.exe /c "bcdedit /deletevalue disableelamdrivers >nul 2>&1"; $global:LASTEXITCODE = 0 } # Удаляем запрет ELAM
    Apply-Tweak "Включение изолированного контекста ядра (Режим Античита)" { bcdedit /set isolatedcontext Yes *>&1 | Out-File -FilePath $global:LogPath -Append -Encoding UTF8 } # Включаем изолированный контекст ядра
} else {
    # Без античитов: отключаем ELAM для более быстрой загрузки Windows
    Apply-Tweak "Отключение ELAM (Быстрая загрузка)" { bcdedit /set disableelamdrivers Yes *>&1 | Out-File -FilePath $global:LogPath -Append -Encoding UTF8 } # Yes = Отключить ELAM
    Apply-Tweak "Отключение изолированного контекста ядра" { bcdedit /set isolatedcontext No *>&1 | Out-File -FilePath $global:LogPath -Append -Encoding UTF8 } # No = Отключить изоляцию
}

# Отключение TPM Boot Entropy (Снижение DPC и ускорение загрузки)
if (-not $global:OptAntiCheat) {
    Apply-Tweak "Отключение TPM Boot Entropy (Быстрый старт)" { bcdedit /set tpmbootentropy ForceDisable *>&1 | Out-File -FilePath $global:LogPath -Append -Encoding UTF8 } # Запрет запросов к медленному TPM-чипу при старте ОС
} else {
    Apply-Tweak "Включение TPM Boot Entropy (Режим Античита)" { cmd.exe /c "bcdedit /deletevalue tpmbootentropy >nul 2>&1"; $global:LASTEXITCODE = 0 } # Античиту нужен TPM
}

Write-Host ""
# ==============================================================================
# Раздел 72: AOT компиляция .NET и активация DirectPlay
# ==============================================================================
Show-ProgressStep -StepNum 72 -TotalSteps 81 -Activity "AOT компиляция .NET и активация DirectPlay..."
Write-Host "==============================================================================" -ForegroundColor DarkGray
Write-Host "РАЗДЕЛ 72: AOT КОМПИЛЯЦИЯ .NET И АКТИВАЦИЯ DIRECTPLAY" -ForegroundColor Cyan
Write-Host "==============================================================================" -ForegroundColor DarkGray

Write-Host " ► Принудительная AOT-компиляция .NET сборок (Защита от фризов в Unity-играх)..." -ForegroundColor DarkGray
# Утилита NGEN заранее компилирует библиотеки .NET в машинный код, чтобы процессор не тратил на это время прямо во время игры.
$NGEN_64 = "$env:windir\Microsoft.NET\Framework64\v4.0.30319\ngen.exe"
$NGEN_32 = "$env:windir\Microsoft.NET\Framework\v4.0.30319\ngen.exe"
if (Test-Path $NGEN_64) { Apply-Tweak "Запуск x64 компиляции (NGEN)" { Start-Process -FilePath $NGEN_64 -ArgumentList "executeQueuedItems" -Wait -WindowStyle Hidden } } # Запуск компиляции x64
if (Test-Path $NGEN_32) { Apply-Tweak "Запуск x86 компиляции (NGEN)" { Start-Process -FilePath $NGEN_32 -ArgumentList "executeQueuedItems" -Wait -WindowStyle Hidden } } # Запуск компиляции x86

# Включение компонента DirectPlay (Жизненно необходимо для старых игр начала нулевых)
try {
    Apply-Tweak "Установка компонента DirectPlay (DISM)" { Start-Process -FilePath "dism.exe" -ArgumentList "/online /enable-feature /featurename:DirectPlay /all /norestart /quiet" -Wait -NoNewWindow } # Тихая установка компонента через DISM
} catch { }

Write-Host ""
# ==============================================================================
# Раздел 73: Авто-скачивание утилит (DirectX, VC++, NPI, HIDUSBF)
# ==============================================================================
Show-ProgressStep -StepNum 73 -TotalSteps 81 -Activity "Авто-скачивание утилит (DirectX, VC++, NPI, HIDUSBF)..."
Write-Host "==============================================================================" -ForegroundColor DarkGray
Write-Host "РАЗДЕЛ 73: АВТО-СКАЧИВАНИЕ УТИЛИТ (DIRECTX, VC++, NPI, HIDUSBF)" -ForegroundColor Cyan
Write-Host "==============================================================================" -ForegroundColor DarkGray

# Быстрая проверка пинга для определения сети
$global:IsOnline = $false
try {
    $ping = New-Object System.Net.NetworkInformation.Ping
    if ($ping.Send("8.8.8.8", 1500).Status -eq 'Success' -or $ping.Send("1.1.1.1", 1500).Status -eq 'Success') { 
        $global:IsOnline = $true 
    }
} catch {}

if (-not $global:IsOnline) {
    Write-Host ""
    Write-Host "[WARNING] ОТСУТСТВУЕТ ПОДКЛЮЧЕНИЕ К ИНТЕРНЕТУ!" -ForegroundColor Yellow
    Write-Host "Скачивание драйверов и программ пропущено." -ForegroundColor DarkGray
} else {

    if (Get-Command winget -ErrorAction SilentlyContinue 2>> $env:SystemDrive\EastricaTools\Eastrica_ErrorTrace.log) {
        # Принудительная синхронизация базы каталога winget
        try { cmd.exe /c "winget source update --accept-source-agreements --disable-interactivity >nul 2>&1" } catch {}
        
        # Защита от зависания при автоматической (тихой) установке через OOBE / Autounattend
        if ([Environment]::UserInteractive -and $env:USERNAME -ne "SYSTEM" -and -not $Unattended) {
            Write-Host ""
            Write-Host "Хотите обновить все установленные программы на ПК до последних версий (winget)?" -ForegroundColor Magenta
            $UpgradeResponse = Read-Host "(Y - Да, обновить / N - Пропустить)"
            
            if ($UpgradeResponse -match "^[YyДд]") {
                Write-Host " ► Фоновое обновление всех установленных программ..." -ForegroundColor Yellow
                Write-Host "Это может занять несколько минут. Пожалуйста, подождите." -ForegroundColor DarkGray
                
                Apply-Tweak "Запуск фонового обновления всех программ (winget upgrade --all)" { 
                    $upgArgs = "upgrade --all --accept-package-agreements --accept-source-agreements --silent"
                    $upgProc = Start-Process -FilePath "winget" -ArgumentList $upgArgs -WindowStyle Hidden -PassThru 2>> $env:SystemDrive\EastricaTools\Eastrica_ErrorTrace.log 
                    if ($upgProc) {
                        if (-not $upgProc.WaitForExit(300000)) { try { $upgProc.Kill() } catch {} } # 5 минут максимум
                    }
                }
                Write-Host "[OK] Процесс обновления программ завершен." -ForegroundColor DarkGray
            } else {
                Write-Host " ► Обновление программ пропущено." -ForegroundColor DarkGray
            }
        } else {
            Write-Host " ► Автоматический режим (SYSTEM). Интерактивное обновление программ пропущено." -ForegroundColor DarkGray
        }
    }

    # Установка DirectX Web Setup с умным фолбэком
    Write-Host " ► Скачивание и обновление пакета DirectX..." -ForegroundColor DarkGray
    $DX_Installed = $false
    
    if (Get-Command winget 2>> $env:SystemDrive\EastricaTools\Eastrica_ErrorTrace.log) {
        try {
            Apply-Tweak "Обновление AppInstaller (winget)" { Add-AppxPackage -RegisterByFamilyName -MainPackage Microsoft.DesktopAppInstaller_8wekyb3d8bbwe *>&1 | Out-File -FilePath $global:LogPath -Append -Encoding UTF8 }
            Apply-Tweak "Установка пакета Microsoft.DirectX через winget" { Install-ViaWinget "Microsoft.DirectX" }
            $DX_Installed = $true
        } catch {
            Write-Host " ► Winget сбойнул. Переход на прямое скачивание DirectX..." -ForegroundColor Yellow
        }
    }
    
    if (-not $DX_Installed) {
        $DX_Url = "https://download.microsoft.com/download/1/7/1/1718CCC4-6315-4D8E-9543-8E28A4E18C4C/dxwebsetup.exe"
        $DX_File = "$BaseDir\dxwebsetup.exe"
        Apply-Tweak "Скачивание dxwebsetup.exe с серверов Microsoft" { Download-File-Safe -Url $DX_Url -Output $DX_File }
        if (Test-Path $DX_File) {
            Apply-Tweak "Тихая установка DirectX (dxwebsetup /Q)" { 
                $dxProc = Start-Process -FilePath $DX_File -ArgumentList "/Q" -PassThru 2>> $env:SystemDrive\EastricaTools\Eastrica_ErrorTrace.log
                if ($dxProc) { if (-not $dxProc.WaitForExit(180000)) { try { $dxProc.Kill() } catch {} } }
            }
        }
    }
    Write-Host "[OK] Пакет DirectX успешно обработан" -ForegroundColor DarkGray

    # Visual C++ AIO (Полный пакет библиотек, Must Have для абсолютно всех игр)
    $VC_Url = "https://github.com/abbodi1406/vcredist/releases/latest/download/VisualCppRedist_AIO_x86_x64.exe"
    $VC_File = "$BaseDir\VisualCppRedist_AIO.exe"
    Write-Host " ► Скачивание и обновление библиотек VISUAL C++..." -ForegroundColor DarkGray
    Apply-Tweak "Скачивание библиотек VISUAL C++ AIO" { Download-File-Safe -Url $VC_Url -Output $VC_File }
    if (Test-Path $VC_File) {
        Apply-Tweak "Тихая установка VISUAL C++ AIO" { 
            $vcProc = Start-Process -FilePath $VC_File -ArgumentList "/ai /gm2" -PassThru 2>> $env:SystemDrive\EastricaTools\Eastrica_ErrorTrace.log
            if ($vcProc) { if (-not $vcProc.WaitForExit(180000)) { try { $vcProc.Kill() } catch {} } }
        }
    }

    if (-not $global:OptAI) {
	    # LatencyMon (Программа для проверки задержек DPC и поиска драйверов, вызывающих лаги)
        Write-Host " ► Скачивание LatencyMon (Проверка задержек DPC)..." -ForegroundColor DarkGray
        $LatMonFile = "$BaseDir\LatencyMon_Setup.exe"
        Apply-Tweak "Скачивание установщика LatencyMon" { Download-File-Safe -Url "https://www.resplendence.com/download/LatencyMon.exe" -Output $LatMonFile }
        if (Test-Path $LatMonFile) {
            Write-Host "[OK] LatencyMon сохранен: $LatMonFile" -ForegroundColor Green
        }

        # GoInterruptPolicy (Утилита для ручной привязки прерываний MSI Mode)
        Write-Host " ► Скачивание GoInterruptPolicy (Ручная привязка прерываний MSI Mode)..." -ForegroundColor DarkGray
        $GipFile = "$BaseDir\GoInterruptPolicy.exe"
        Apply-Tweak "Скачивание утилиты GoInterruptPolicy" { Download-File-Safe -Url "https://github.com/spddl/GoInterruptPolicy/releases/download/v1.8.0/GoInterruptPolicy.exe" -Output $GipFile }
        if (Test-Path $GipFile) {
            Write-Host "[OK] GoInterruptPolicy сохранен: $GipFile" -ForegroundColor Green
        }

        # HIDUSBF (Утилита разгона мыши до 8000Hz)
        # ВНИМАНИЕ: Для работы кастомного USB-драйвера в Win10/11 нужно выключить Secure Boot в BIOS.
        Write-Host " ► Скачивание HIDUSBF (Разгон мыши до 8000Hz)..." -ForegroundColor DarkGray
        Apply-Tweak "Скачивание архива HIDUSBF" { Download-File-Safe -Url "https://github.com/LordOfMice/hidusbf/raw/master/hidusbf.zip" -Output "$BaseDir\hidusbf.zip" }
        if (Test-Path "$BaseDir\hidusbf.zip") {
            $CI_Config = "HKLM:\SYSTEM\CurrentControlSet\Control\CI\Config"
            if (!(Test-Path $CI_Config)) { Apply-Tweak "Создание раздела CI Config (HIDUSBF)" { New-Item $CI_Config -Force *>&1 | Out-File -FilePath $global:LogPath -Append -Encoding UTF8 } }
            if (-not $global:OptAntiCheat) {
                # Если античит выключен — разрешаем драйверу HIDUSBF работать в системе
                Apply-Tweak "Отключение блок-листа уязвимых драйверов (HIDUSBF)" { Set-ItemProperty -Path $CI_Config -Name "VulnerableDriverBlocklistEnable" -Value 0 -Type DWord -Force *>&1 | Out-File -FilePath $global:LogPath -Append -Encoding UTF8 } # Отключаем блок-лист уязвимых драйверов
                Apply-Tweak "Сброс тестового режима BCD" { bcdedit /deletevalue testsigning *>&1 | Out-File -FilePath $global:LogPath -Append -Encoding UTF8 } # Сброс тестового режима
                # Проверяем состояние Secure Boot: если он активен, nointegritychecks гарантированно вернет ошибку
                $isSecureBoot = $false
                try { $isSecureBoot = [bool](Confirm-SecureBootUEFI -ErrorAction SilentlyContinue) } catch {}
                if (-not $isSecureBoot) {
                    Apply-Tweak "Разрешение драйверов без цифровой подписи (nointegritychecks)" { bcdedit /set nointegritychecks on *>&1 | Out-File -FilePath $global:LogPath -Append -Encoding UTF8 }
                } else {
                    Write-Host " ► [ПРОПУСК] nointegritychecks пропущен: параметр заблокирован Secure Boot UEFI" -ForegroundColor DarkGray
                }
            } else {
                # Если включен античит-режим (FACEIT/Vanguard), жестко возвращаем безопасность, иначе получите бан.
                Apply-Tweak "Включение блок-листа уязвимых драйверов (Режим Античита)" { Set-ItemProperty -Path $CI_Config -Name "VulnerableDriverBlocklistEnable" -Value 1 -Type DWord -Force *>&1 | Out-File -FilePath $global:LogPath -Append -Encoding UTF8 }
                Apply-Tweak "Удаление тестового режима BCD (Режим Античита)" { 
                    if ((cmd.exe /c "bcdedit /enum {current}") -match "\btestsigning\b") { cmd.exe /c "bcdedit /deletevalue {current} testsigning >nul 2>&1" }
                    $global:LASTEXITCODE = 0
                }
                Apply-Tweak "Включение проверки цифровой подписи драйверов (Режим Античита)" { 
                    if ((cmd.exe /c "bcdedit /enum {current}") -match "\bnointegritychecks\b") { cmd.exe /c "bcdedit /deletevalue {current} nointegritychecks >nul 2>&1" }
                    $global:LASTEXITCODE = 0
                }
            }
            Apply-Tweak "Распаковка архива HIDUSBF" { Expand-Archive -Path "$BaseDir\hidusbf.zip" -DestinationPath "$BaseDir\HIDUSBF" -Force *>&1 | Out-File -FilePath $global:LogPath -Append -Encoding UTF8 } # Распаковываем
            Apply-Tweak "Удаление архива HIDUSBF" { Remove-Item "$BaseDir\hidusbf.zip" -Force *>&1 | Out-File -FilePath $global:LogPath -Append -Encoding UTF8 } # Удаляем архив
            Write-Host "[OK] HIDUSBF помещен в папке $BaseDir\HIDUSBF" -ForegroundColor Green
        }
    }

    # NVIDIA Profile Inspector (NPI) - Инструмент для скрытых настроек видеокарты
    $HasNVIDIA = [bool]($global:GPUs | Where-Object { $_.Name -match "NVIDIA" })
    if ($HasNVIDIA) {
        Write-Host " ► Скачивание NVIDIA Profile Inspector и настройка скрытых профилей NVIDIA..." -ForegroundColor DarkGray
        $NPI_Url = "https://github.com/Orbmu2k/nvidiaProfileInspector/releases/latest/download/nvidiaProfileInspector.zip"
        $NPI_Zip = "$BaseDir\nvidiaProfileInspector.zip"
        $NPI_Dir = "$BaseDir\NPI"
        $NipPath = "$NPI_Dir\EastricaProfile.nip"
        
        Apply-Tweak "Скачивание архива NVIDIA Profile Inspector" { Download-File-Safe -Url $NPI_Url -Output $NPI_Zip }
        if (Test-Path $NPI_Zip) {
            if (!(Test-Path $NPI_Dir)) { Apply-Tweak "Создание папки NPI" { New-Item -ItemType Directory -Path $NPI_Dir -Force *>&1 | Out-File -FilePath $global:LogPath -Append -Encoding UTF8 } }
            Apply-Tweak "Распаковка NVIDIA Profile Inspector" { Expand-Archive -Path $NPI_Zip -DestinationPath $NPI_Dir -Force *>&1 | Out-File -FilePath $global:LogPath -Append -Encoding UTF8 }
            
            # Резервное копирование текущего профиля
            $NPI_BackupPath = "$BackupDir\NVIDIA_Profile_Backup.nip"
            Apply-Tweak "Резервное копирование текущего профиля NVIDIA" {
                $backupArgs = "-exportCurrentProfile `"$NPI_BackupPath`""
                $backupProc = Start-Process -FilePath "$NPI_Dir\nvidiaProfileInspector.exe" -ArgumentList $backupArgs -PassThru -WindowStyle Hidden
                if ($backupProc) { $backupProc.WaitForExit(15000) | Out-Null }
            }

            Apply-Tweak "Удаление архива NVIDIA Profile Inspector" { Remove-Item $NPI_Zip -Force *>&1 | Out-File -FilePath $global:LogPath -Append -Encoding UTF8 }
            
            if ($global:OptAI) {
                # ==============================================================================
                # Профиль для ИИ, рендера и стриминга (Compute / Data Science)
                # ==============================================================================
                $NipContent = @"
<?xml version="1.0" encoding="utf-16"?>
<ArrayOfProfile>
  <Profile>
    <ProfileName>Base Profile</ProfileName>
    <Executeables />
    <Settings>
      <!-- Power Management Mode: Optimal Power -->
      <ProfileSetting>
        <SettingNameInfo>Power management mode</SettingNameInfo>
        <SettingID>274197361</SettingID>
        <SettingValue>5</SettingValue>
        <ValueType>Dword</ValueType>
      </ProfileSetting>
      
      <!-- CUDA - Force P2 State: Off (Максимальная частота VRAM P0) -->
      <ProfileSetting>
        <SettingNameInfo>CUDA - Force P2 State</SettingNameInfo>
        <SettingID>275085817</SettingID>
        <SettingValue>0</SettingValue>
        <ValueType>Dword</ValueType>
      </ProfileSetting>
      
      <!-- CUDA - Sysmem Fallback Policy: Prefer Sysmem Fallback (Официальный ID: 283962569) -->
      <ProfileSetting>
        <SettingNameInfo>CUDA Sysmem Fallback Policy</SettingNameInfo>
        <SettingID>283962569</SettingID>
        <SettingValue>1</SettingValue>
        <ValueType>Dword</ValueType>
      </ProfileSetting>
      
      <!-- Threaded Optimization: On -->
      <ProfileSetting>
        <SettingNameInfo>Threaded optimization</SettingNameInfo>
        <SettingID>274606621</SettingID>
        <SettingValue>1</SettingValue>
        <ValueType>Dword</ValueType>
      </ProfileSetting>
      
      <!-- Vulkan/OpenGL present method: Prefer layered on DXGI Swapchain -->
      <ProfileSetting>
        <SettingNameInfo>Vulkan/OpenGL present method</SettingNameInfo>
        <SettingID>553229069</SettingID>
        <SettingValue>1</SettingValue>
        <ValueType>Dword</ValueType>
      </ProfileSetting>

      <!-- NVIDIA Reflex: Off -->
      <ProfileSetting>
        <SettingNameInfo>NVIDIA Reflex</SettingNameInfo>
        <SettingID>277041152</SettingID>
        <SettingValue>0</SettingValue>
        <ValueType>Dword</ValueType>
      </ProfileSetting>

      <!-- Texture filtering - Quality: High Quality -->
      <ProfileSetting>
        <SettingNameInfo>Texture filtering - Quality</SettingNameInfo>
        <SettingID>13510289</SettingID>
        <SettingValue>0</SettingValue>
        <ValueType>Dword</ValueType>
      </ProfileSetting>

      <!-- Shader Cache Size: 10 GB -->
      <ProfileSetting>
        <SettingNameInfo>Shader disk cache maximum size</SettingNameInfo>
        <SettingID>282894272</SettingID>
        <SettingValue>64</SettingValue>
        <ValueType>Dword</ValueType>
      </ProfileSetting>

      <!-- Глобальное форсирование Resizable BAR (Только валидные параметры Feature и Options) -->
      <ProfileSetting>
        <SettingNameInfo>rBAR - Feature</SettingNameInfo>
        <SettingID>983226</SettingID>
        <SettingValue>1</SettingValue>
        <ValueType>Dword</ValueType>
      </ProfileSetting>
      <ProfileSetting>
        <SettingNameInfo>rBAR - Options</SettingNameInfo>
        <SettingID>983227</SettingID>
        <SettingValue>1</SettingValue>
        <ValueType>Dword</ValueType>
      </ProfileSetting>
    </Settings>
  </Profile>
</ArrayOfProfile>
"@
                Write-Host "[NPI] Применен профиль: AI / COMPUTE (Compute Optimize, ReBAR, P2-State Off)" -ForegroundColor Cyan
            } else {
                # ==============================================================================
                # Профиль для игр (Zero Input Lag / eSports)
                # ==============================================================================
                $ExeStrings = ""
                if ($global:NvGameExes) {
                    foreach ($exe in $global:NvGameExes) {
                        $ExeStrings += "        <string>$exe</string>`r`n"
                    }
                }

                $NipContent = @"
<?xml version="1.0" encoding="utf-16"?>
<ArrayOfProfile>
  <Profile>
    <ProfileName>Base Profile</ProfileName>
    <Executeables />
    <Settings>
      <!-- Power Management: Оптимальное (Холодная видеокарта на рабочем столе) -->
      <ProfileSetting><SettingID>274197361</SettingID><SettingValue>5</SettingValue><ValueType>Dword</ValueType></ProfileSetting>
      
      <!-- NVIDIA Reflex: Low Latency Mode Ultra -->
      <ProfileSetting><SettingID>277041152</SettingID><SettingValue>2</SettingValue><ValueType>Dword</ValueType></ProfileSetting>
      
      <!-- SILK Smoothness: Off (Убирает искусственное сглаживание кадров) -->
      <ProfileSetting><SettingID>270198627</SettingID><SettingValue>0</SettingValue><ValueType>Dword</ValueType></ProfileSetting>
      
      <!-- Preferred Refresh Rate: Highest Available -->
      <ProfileSetting><SettingID>274502707</SettingID><SettingValue>1</SettingValue><ValueType>Dword</ValueType></ProfileSetting>
      
      <!-- Multi-display acceleration: Single Display Performance Mode -->
      <ProfileSetting><SettingID>276652957</SettingID><SettingValue>0</SettingValue><ValueType>Dword</ValueType></ProfileSetting>
      
      <!-- Max Pre-rendered Frames: 1 (Минимальная очередь кадров CPU) -->
      <ProfileSetting><SettingID>8102046</SettingID><SettingValue>1</SettingValue><ValueType>Dword</ValueType></ProfileSetting>
      
      <!-- Virtual Reality Pre-rendered Frames: 1 -->
      <ProfileSetting><SettingID>269553971</SettingID><SettingValue>1</SettingValue><ValueType>Dword</ValueType></ProfileSetting>
      
      <!-- Texture Filtering - Quality: High Performance -->
      <ProfileSetting><SettingID>13510289</SettingID><SettingValue>20</SettingValue><ValueType>Dword</ValueType></ProfileSetting>
      
      <!-- Texture Filtering - Negative LOD Bias: Clamp -->
      <ProfileSetting><SettingID>7573135</SettingID><SettingValue>1</SettingValue><ValueType>Dword</ValueType></ProfileSetting>
      
      <!-- Texture Filtering - Trilinear & Anisotropic Optimization: On -->
      <ProfileSetting><SettingID>277041150</SettingID><SettingValue>1</SettingValue><ValueType>Dword</ValueType></ProfileSetting>
      <ProfileSetting><SettingID>276089180</SettingID><SettingValue>1</SettingValue><ValueType>Dword</ValueType></ProfileSetting>
      
      <!-- Threaded Optimization: On -->
      <ProfileSetting><SettingID>274606621</SettingID><SettingValue>1</SettingValue><ValueType>Dword</ValueType></ProfileSetting>

      <!-- Vertical Sync: Force Off (Аппаратное отключение VSync) -->
      <ProfileSetting><SettingID>11041231</SettingID><SettingValue>13850400</SettingValue><ValueType>Dword</ValueType></ProfileSetting>

      <!-- Antialiasing - Gamma correction: Off (Снижает нагрузку на GPU) -->
      <ProfileSetting><SettingID>276658822</SettingID><SettingValue>0</SettingValue><ValueType>Dword</ValueType></ProfileSetting>

      <!-- Shader Cache Size: 10 GB -->
      <ProfileSetting><SettingID>282894272</SettingID><SettingValue>64</SettingValue><ValueType>Dword</ValueType></ProfileSetting>

      <!-- Vulkan/OpenGL present method: Prefer layered on DXGI Swapchain (Independent Flip для Vulkan) -->
      <ProfileSetting><SettingID>553229069</SettingID><SettingValue>1</SettingValue><ValueType>Dword</ValueType></ProfileSetting>

      <!-- Triple Buffering OpenGL: Off (Минимальная задержка кадров OpenGL) -->
      <ProfileSetting><SettingID>274744526</SettingID><SettingValue>0</SettingValue><ValueType>Dword</ValueType></ProfileSetting>

      <!-- СЕКРЕТНЫЙ ТВИК: Глобальное форсирование Resizable BAR для всех игр -->
      <ProfileSetting><SettingID>983226</SettingID><SettingValue>1</SettingValue><ValueType>Dword</ValueType></ProfileSetting> <!-- rBAR Feature -->
      <ProfileSetting><SettingID>983227</SettingID><SettingValue>1</SettingValue><ValueType>Dword</ValueType></ProfileSetting> <!-- rBAR Options -->
      <ProfileSetting><SettingID>983295</SettingID><SettingValue>0</SettingValue><ValueType>Dword</ValueType></ProfileSetting> <!-- rBAR Size Limit (0 = Безлимит) -->
    </Settings>
  </Profile>
"@
                # Если мы выбрали хотя бы одну игру, создаем для них отдельный профиль с Максимальной мощностью
                if ($ExeStrings -ne "") {
                    $NipContent += @"
  <Profile>
    <ProfileName>Eastrica Optimized Games</ProfileName>
    <Executeables>
$ExeStrings    </Executeables>
    <Settings>
      <!-- ДЛЯ ИГР: Prefer Maximum Performance (Видеокарта не сбрасывает частоты в игре) -->
      <ProfileSetting><SettingID>274197361</SettingID><SettingValue>1</SettingValue><ValueType>Dword</ValueType></ProfileSetting>

      <!-- АВТОМАТИЧЕСКИЙ АППАРАТНЫЙ ЛИМИТ КАДРОВ ДЛЯ ИДЕАЛЬНОГО G-SYNC -->
      $($MaxFps = if ($global:RefreshRate -ge 120) { $global:RefreshRate - 3 } elseif ($global:RefreshRate -ge 60) { $global:RefreshRate - 1 } else { 0 };
        if ($MaxFps -gt 0) {
            "<!-- Max Frame Rate ($MaxFps FPS) -->`r`n      <ProfileSetting><SettingID>277041154</SettingID><SettingValue>$MaxFps</SettingValue><ValueType>Dword</ValueType></ProfileSetting>`r`n" +
            "      <!-- Background Frame Rate (30 FPS при Alt+Tab) -->`r`n      <ProfileSetting><SettingID>277041157</SettingID><SettingValue>30</SettingValue><ValueType>Dword</ValueType></ProfileSetting>"
        } else { "" }
      )
    </Settings>
  </Profile>
"@
                }
                $NipContent += @"
</ArrayOfProfile>
"@
                Write-Host "[NPI] Применен профиль: GAMING (Global ReBAR, VSync Off, Reflex Ultra)" -ForegroundColor Cyan
            }
            
            Apply-Tweak "Генерация файла профиля NPI (.nip)" { [System.IO.File]::WriteAllText($NipPath, $NipContent, [System.Text.Encoding]::Unicode) }
            
            # Закрываем программы, которые блокируют NVAPI базу настроек
            Get-Process -Name "nvidiaProfileInspector", "nvcplui" -ErrorAction SilentlyContinue | Stop-Process -Force 2>$null

            # Запускаем импорт с чистой передачей массива аргументов (без ломающихся кавычек)
            Apply-Tweak "Импорт профиля в драйвер NVIDIA (NPI -silentImport)" { 
                $npiExe = "$NPI_Dir\nvidiaProfileInspector.exe"
                $npiProc = Start-Process -FilePath $npiExe -ArgumentList @("-silentImport", $NipPath) -PassThru -WindowStyle Hidden 2>> $env:SystemDrive\EastricaTools\Eastrica_ErrorTrace.log
                if ($npiProc) { 
                    if (-not $npiProc.WaitForExit(30000)) { try { $npiProc.Kill() } catch {} } 
                }
            }
        }
    }

    # MSI Afterburner (Лучшая утилита для фиксации частот, андервольтинга и мониторинга видеокарты)
    Write-Host " ► Скачивание и установка MSI Afterburner..." -ForegroundColor DarkGray
    try {
        if (-not (Get-Command winget -ErrorAction SilentlyContinue)) { throw "Winget не найден" }
        Apply-Tweak "Установка MSI Afterburner (winget)" { Install-ViaWinget "Guru3D.Afterburner" }
    } catch {
        Write-Host " ► Winget недоступен. Прямое скачивание MSI Afterburner..." -ForegroundColor Yellow
        $MsiZip = "$BaseDir\MSIAfterburner.zip"
        $MsiExtract = "$BaseDir\MSIAfterburner"
        Apply-Tweak "Скачивание MSI Afterburner (Fallback)" { Download-File-Safe -Url "https://download.msi.com/uti_exe/vga/MSIAfterburnerSetup.zip" -Output $MsiZip }
        if (Test-Path $MsiZip) {
            Expand-Archive -Path $MsiZip -DestinationPath $MsiExtract -Force
            $SetupExe = Get-ChildItem -Path $MsiExtract -Filter "*.exe" | Select-Object -First 1
            if ($SetupExe) { Start-Process -FilePath $SetupExe.FullName -ArgumentList "/S" -Wait -WindowStyle Hidden }
            Remove-Item $MsiZip -Force
        }
    }

    if (-not $global:OptAI) {
        # DDU и PROCESS LASSO
        Write-Host " ► Скачивание и установка Process Lasso..." -ForegroundColor DarkGray
        $LassoInstalled = $false

        if (Get-Command winget -ErrorAction SilentlyContinue) {
            try {
                # Пробуем через Winget напрямую
                Install-ViaWinget "Bitsum.ProcessLasso"
                $LassoInstalled = $true
                Write-Host "[OK] Установка Process Lasso через winget" -ForegroundColor Green
            } catch {
                Write-Host " ► Winget завершился с ошибкой. Переход на прямое скачивание..." -ForegroundColor Yellow
            }
        }

        # Если через winget поставить не удалось — скачиваем официальный инсталлятор
        if (-not $LassoInstalled) {
            $LassoExe = "$BaseDir\ProcessLassoSetup.exe"
            Apply-Tweak "Прямое скачивание и тихая установка Process Lasso" { 
                Download-File-Safe -Url "https://bitsum.com/files/processlassosetup64.exe" -Output $LassoExe
                if (Test-Path $LassoExe) { 
                    Start-Process -FilePath $LassoExe -ArgumentList "/S" -Wait -WindowStyle Hidden 
                }
            }
        }
    
        # Настройка оптимизированного профиля Process Lasso (probalance.ini)
        Apply-Tweak "Настройка профиля Process Lasso (probalance.ini)" {
            Get-Process -Name "ProcessLasso", "processgovernor" -ErrorAction SilentlyContinue | Stop-Process -Force
            Start-Sleep -Seconds 1
            $lassoDir = "$env:APPDATA\ProcessLasso"
            if (-not (Test-Path $lassoDir)) { New-Item -Path $lassoDir -ItemType Directory -Force | Out-Null }
            $GameRuleList = if ($global:NvGameExes -and $global:NvGameExes.Count -gt 0) { ($global:NvGameExes | Select-Object -Unique) -join "," } else { "" }
            $probalanceConfig = "[ProBalance]`r`nEnabled=1`r`nIgnoreForegroundProcesses=1`r`nIgnoreChildrenOf=steam.exe,epicgameslauncher.exe,vgc.exe,battlenet.exe`r`nProBalanceExclusions=audiodg.exe,dwm.exe,obs64.exe,vrserver.exe,vgc.exe,vgtray.exe,faceit.exe,faceitclient.exe,EasyAntiCheat.exe,EasyAntiCheat_EOS.exe,beservice.exe`r`nProBalanceExcludeGames=1`r`nSmartIO=1`r`nHideTrayIcon=0`r`nProBalanceExcludeChildren=1`r`nProBalanceExcludeForeground=1`r`n`r`n[PerformanceModeProcesses]`r`n$GameRuleList"
            Set-Content -Path "$lassoDir\prolasso.ini" -Value $probalanceConfig -Encoding UTF8 -Force
        }
        Write-Host "[OK] Process Lasso успешно настроен." -ForegroundColor DarkGray

        Write-Host " ► Скачивание Display Driver Uninstaller (Очистка драйверов NVIDIA и AMD)..." -ForegroundColor DarkGray
        try {
            if (-not (Get-Command winget -ErrorAction SilentlyContinue)) { throw "Winget не найден" }
            Apply-Tweak "Установка Display Driver Uninstaller (winget)" { Install-ViaWinget "Wagnardsoft.DisplayDriverUninstaller" }
        } catch {
            Write-Host " ► Winget недоступен. DDU пропущен. Пожалуйста, скачайте DDU вручную с Guru3D." -ForegroundColor Yellow
        }

        Write-Host " ► Скачивание CapFrameX..." -ForegroundColor DarkGray
        try {
            if (-not (Get-Command winget -ErrorAction SilentlyContinue)) { throw "Winget не найден" }
            Apply-Tweak "Установка CapFrameX (winget)" { Install-ViaWinget "CXWorld.CapFrameX" }
        } catch {
            Write-Host " ► Winget недоступен. Прямое скачивание CapFrameX..." -ForegroundColor Yellow
            $CfxExe = "$BaseDir\CapFrameX_Setup.exe"
            Apply-Tweak "Скачивание CapFrameX (Fallback)" { Download-File-Safe -Url "https://github.com/CXWorld/CapFrameX/releases/latest/download/CapFrameX_Setup.exe" -Output $CfxExe }
            if (Test-Path $CfxExe) { Start-Process -FilePath $CfxExe -ArgumentList "/SILENT" -Wait -WindowStyle Hidden }
        }
    }

    # NVCleanstall (Утилита для очистки драйвера NVIDIA от телеметрии и мусора при установке)
    if ($HasNVIDIA) {
        if (Get-Command winget 2>> $env:SystemDrive\EastricaTools\Eastrica_ErrorTrace.log) {
            Write-Host " ► Скачивание NVCleanstall (Оптимизация драйвера NVIDIA)..." -ForegroundColor DarkGray
            Apply-Tweak "Установка NVCleanstall через winget" { Install-ViaWinget "TechPowerUp.NVCleanstall" }
        } else {
            Write-Host " ► [ПРОПУСК] NVCleanstall: Утилита winget не найдена. Пожалуйста, скачайте вручную с TechPowerUp." -ForegroundColor Yellow
        }
    }

    # Radeon Software Slimmer (Утилита для вырезания мусора из драйвера AMD)
    $HasAMD = [bool]($global:GPUs | Where-Object { $_.Name -match "AMD|Radeon" })
    if ($HasAMD) {
        Write-Host " ► Скачивание Radeon Software Slimmer (Оптимизация драйвера AMD)..." -ForegroundColor DarkGray
        try {
            $RSS_ZipPath = "$BaseDir\RadeonSoftwareSlimmer.zip"
            $RSS_ExtractDir = "$BaseDir\RadeonSoftwareSlimmer"
            
            $RSS_ZipUrl = "https://github.com/GSDragoon/RadeonSoftwareSlimmer/releases/download/1.12.0/RadeonSoftwareSlimmer_1.12.0_net48.zip"
            try {
                # Заголовок User-Agent ОБЯЗАТЕЛЕН для GitHub API, иначе сервер вернет 403 Forbidden
                $headers = @{ "User-Agent" = "EastricaOptimizer/1.0" }
                $ReleaseInfo = Invoke-RestMethod -Uri "https://api.github.com/repos/GSDragoon/RadeonSoftwareSlimmer/releases/latest" -Headers $headers -TimeoutSec 10 -ErrorAction Stop
                $Asset = $ReleaseInfo.assets | Where-Object { $_.name -match "net48\.zip$" } | Select-Object -First 1
                if ($Asset) { $RSS_ZipUrl = $Asset.browser_download_url }
            } catch {
                # При ошибке API используем проверенную прямую ссылку на релиз
            }
            
            Apply-Tweak "Скачивание архива RadeonSoftwareSlimmer" { Download-File-Safe -Url $RSS_ZipUrl -Output $RSS_ZipPath }
            
            if (Test-Path $RSS_ZipPath) {
                if (!(Test-Path $RSS_ExtractDir)) { New-Item -ItemType Directory -Path $RSS_ExtractDir -Force | Out-Null }
                Apply-Tweak "Распаковка архива RadeonSoftwareSlimmer" { Expand-Archive -Path $RSS_ZipPath -DestinationPath $RSS_ExtractDir -Force *>&1 | Out-File -FilePath $global:LogPath -Append -Encoding UTF8 }
                Remove-Item $RSS_ZipPath -Force -ErrorAction SilentlyContinue
                Write-Host "[OK] Radeon Software Slimmer сохранен: $RSS_ExtractDir" -ForegroundColor Green
            }
        } catch {
            Write-Warning " ► [ОШИБКА] Не удалось загрузить Radeon Software Slimmer: $($_.Exception.Message)"
        }
    }

    if (-not $global:OptAI) {
        # Тихая переустановка Gaming Services через Winget
        if ([Environment]::UserInteractive -and $env:USERNAME -ne "SYSTEM") {
            Write-Host " ► Тихий сброс и установка Gaming Services..." -ForegroundColor DarkGray

            Apply-Tweak "Удаление старых пакетов Gaming Services" {
                Get-AppxPackage -Name "Microsoft.GamingServices" -AllUsers 2>> $env:SystemDrive\EastricaTools\Eastrica_ErrorTrace.log | Remove-AppxPackage -AllUsers *>&1 | Out-File -FilePath $global:LogPath -Append -Encoding UTF8
            }

            if (Get-Command winget 2>> $env:SystemDrive\EastricaTools\Eastrica_ErrorTrace.log) {
                Apply-Tweak "Тихая установка Gaming Services через winget" {
                    Install-ViaWinget "9MWPM2CQNLHN"
                }
            } else {
                # Фолбэк на открытие магазина, если winget в системе сломан
                Apply-Tweak "Открытие страницы Gaming Services в MS Store (Резерв)" {
                    Start-Process "ms-windows-store://pdp/?productid=9MWPM2CQNLHN"
                }
            }
        }
    }
}

Write-Host ""
# ==============================================================================
# Раздел 74: Системные переменные (Elite Frametime & Stutter Fixes)
# ==============================================================================
Show-ProgressStep -StepNum 74 -TotalSteps 81 -Activity "Применение системных переменных для идеального фреймтайма..."
Write-Host "==============================================================================" -ForegroundColor DarkGray
Write-Host "РАЗДЕЛ 74: СИСТЕМНЫЕ ПЕРЕМЕННЫЕ (ELITE FRAMETIME & STUTTER FIXES)" -ForegroundColor Cyan
Write-Host "==============================================================================" -ForegroundColor DarkGray

if (-not $global:OptAI) {
    # Твики для игр (Отключаются, если выбран режим ИИ, так как ИИ использует те же переменные)
    
    # Игровые эмуляторы консолей (RPCS3, CEMU, Dolphin, Yuzu/Ryujinx), которые сами управляют своими потоками. Принудительный форсинг вызывает вылеты с ошибкой OpenGL Context Creation Failed.
    Apply-Tweak "Многопоточность OpenGL NVIDIA (__GL_THREADED_OPTIMIZATIONS)" { [Environment]::SetEnvironmentVariable("__GL_THREADED_OPTIMIZATIONS", $null, "Machine") } 
    
    # Аппаратное отключение вертикальной синхронизации (VSync) на уровне OpenGL. Дает минимальный инпут-лаг в старых шутерах и эмуляторах.
    Apply-Tweak "Аппаратное отключение VSync OpenGL (__GL_SYNC_TO_VBLANK)" { [Environment]::SetEnvironmentVariable("__GL_SYNC_TO_VBLANK", "0", "Machine") }
    
    # Ультра-низкая очередь кадров OpenGL (аналог Max Pre-rendered frames = 1 для DX)
    Apply-Tweak "Низкая очередь кадров OpenGL (__GL_MaxFramesAllowed)" { [Environment]::SetEnvironmentVariable("__GL_MaxFramesAllowed", "1", "Machine") }
    
    # Включение постоянного кэша состояний Vulkan (DXVK). Исключает фризы при повторном прохождении локации.
    Apply-Tweak "Постоянный кэш состояний Vulkan DXVK (DXVK_STATE_CACHE)" { [Environment]::SetEnvironmentVariable("DXVK_STATE_CACHE", "1", "Machine") }
    
    # Разрешение DXVK напрямую общаться с драйвером NVIDIA (Включает поддержку DLSS и Reflex в старых играх через Vulkan)
    Apply-Tweak "Поддержка NVAPI для DXVK (DXVK_ENABLE_NVAPI)" { [Environment]::SetEnvironmentVariable("DXVK_ENABLE_NVAPI", "1", "Machine") }
    
    # Отключение телеметрии и логов DXVK (Снижает I/O нагрузку на SSD)
    Apply-Tweak "Отключение логов DXVK (DXVK_LOG_LEVEL=none)" { [Environment]::SetEnvironmentVariable("DXVK_LOG_LEVEL", "none", "Machine") }
    
    # Автоматическое определение объема кэша шейдеров на основе свободного места диска C:
    $SysDriveFreeSpace = (Get-CimInstance Win32_LogicalDisk -Filter "DeviceID='$($env:SystemDrive)'" 2>> $env:SystemDrive\EastricaTools\Eastrica_ErrorTrace.log).FreeSpace
    if ($null -ne $SysDriveFreeSpace -and $SysDriveFreeSpace -lt 50GB) {
        $ShaderCacheValue = "1024" # 1 ГБ для забитых дисков (< 50 ГБ свободно)
        Write-Host " ► Места на диске C: < 50 ГБ. Кэш шейдеров установлен на 1 ГБ." -ForegroundColor Yellow
    } else {
        $ShaderCacheValue = "10240" # 10 ГБ для нормальных дисков
        Write-Host " ► Места на диске достаточно. Кэш шейдеров установлен на 10 ГБ." -ForegroundColor DarkGray
    }

    # Установка кэша шейдеров NVIDIA
    Apply-Tweak "Включение кэша шейдеров NVIDIA (__GL_SHADER_DISK_CACHE)" { [Environment]::SetEnvironmentVariable("__GL_SHADER_DISK_CACHE", "1", "Machine") }
    Apply-Tweak "Установка размера кэша шейдеров NVIDIA ($ShaderCacheValue MB)" { [Environment]::SetEnvironmentVariable("__GL_SHADER_DISK_CACHE_SIZE", $ShaderCacheValue, "Machine") }
    
    # Разрешает драйверу удалять старые шейдеры при обновлении драйвера (Очистка от мусора)
    Apply-Tweak "Разрешение очистки старых шейдеров NVIDIA" { [Environment]::SetEnvironmentVariable("__GL_SHADER_DISK_CACHE_SKIP_CLEANUP", "0", "Machine") }
    
    # Установка кэша DirectX
    Apply-Tweak "Разрешение удаления старого кэша D3D" { [Environment]::SetEnvironmentVariable("D3D_DISABLE_SHADER_CACHE_DELETION", $null, "Machine") }
    Apply-Tweak "Установка размера кэша D3D ($ShaderCacheValue MB)" { [Environment]::SetEnvironmentVariable("D3D_SHADER_CACHE_SIZE", $ShaderCacheValue, "Machine") }
    
    # Отключение Auto SR (Апскейлинг ОС) и DirectSR (Генерация кадров)
    $GraphicsPolicy = "HKLM:\SOFTWARE\Policies\Microsoft\Windows\Graphics"
    if (!(Test-Path $GraphicsPolicy)) { Apply-Tweak "Создание раздела политик Graphics" { New-Item -Path $GraphicsPolicy -Force *>&1 | Out-File -FilePath $global:LogPath -Append -Encoding UTF8 } }
    Apply-Tweak "Глобальное отключение Auto SR (Устранение инпут-лага апскейлера ОС)" { Set-ItemProperty -Path $GraphicsPolicy -Name "DisableAutoSR" -Value 1 -Type DWord -Force *>&1 | Out-File -FilePath $global:LogPath -Append -Encoding UTF8 }
    # Отключение телеметрии DirectSR (Встроенный API Microsoft для DLSS/FSR)
    Apply-Tweak "Отключение телеметрии DirectSR" { Set-ItemProperty -Path $GraphicsPolicy -Name "DisableDirectSRTelemetry" -Value 1 -Type DWord -Force *>&1 | Out-File -FilePath $global:LogPath -Append -Encoding UTF8 }
    
    # Очистка системных переменных от выдуманных параметров, не поддерживаемых средой выполнения DirectX 12:
    # Параметры D3D12_PIPELINE_STATE_CACHE_CONTROL_MULTITHREADED, D3D12_AGILITY_SDK_DISABLE_TELEMETRY и D3D12_DISABLE_ERROR_REPORTING
    # не существуют в официальном Microsoft Agility SDK. Удаляем их из системного окружения.
    Apply-Tweak "Очистка невалидных переменных окружения DirectX 12" { 
        [Environment]::SetEnvironmentVariable("D3D12_PIPELINE_STATE_CACHE_CONTROL_MULTITHREADED", $null, "Machine")
        [Environment]::SetEnvironmentVariable("D3D12_SYNC_COMMAND_QUEUE", $null, "Machine")
        [Environment]::SetEnvironmentVariable("D3D12_AGILITY_SDK_DISABLE_TELEMETRY", $null, "Machine")
        [Environment]::SetEnvironmentVariable("D3D12_DISABLE_ERROR_REPORTING", $null, "Machine")
        [Environment]::SetEnvironmentVariable("ELECTRON_TRASH_ON_EXIT", $null, "Machine")
    }
    
    # Запрещает Electron-приложениям (Discord) генерировать логи безопасности
    Apply-Tweak "Запрет логов безопасности Electron (Discord)" { [Environment]::SetEnvironmentVariable("ELECTRON_DISABLE_SECURITY_WARNINGS", "1", "Machine") }
    Apply-Tweak "Отключение общего логирования Electron" { [Environment]::SetEnvironmentVariable("ELECTRON_ENABLE_LOGGING", "0", "Machine") }
    
    # Запрещает Chromium создавать "Crashpad" пайпы (скрытые каналы для отчетов о падениях приложения)
    Apply-Tweak "Отключение пайпов отчетов Chromium (Crashpad)" { [Environment]::SetEnvironmentVariable("CHROME_CRASHPAD_PIPE_NAME", "none", "Machine") }
    
    # Принудительная распаковка текстур силами GPU (Технология DirectStorage). Разгружает процессор до 30%.
    Apply-Tweak "Принудительная распаковка текстур на GPU (DirectStorage)" { [Environment]::SetEnvironmentVariable("dstorage_force_gpu_decompression", $null, "Machine") } # DirectStorage сам умеет определять, способна ли видеокарта распаковывать ассеты быстрее процессора.
    
    # Отключение телеметрии API DirectStorage
    Apply-Tweak "Отключение телеметрии DirectStorage" { [Environment]::SetEnvironmentVariable("dstorage_disable_builtin_telemetry", "1", "Machine") }
    
    # Запрет использования старого API ввода-вывода (Win32 I/O) для игр
    Apply-Tweak "Запрет устаревшего Win32 I/O для DirectStorage" { [Environment]::SetEnvironmentVariable("dstorage_disable_legacy_file_io", $null, "Machine") } # DirectStorage сам умеет определять, способна ли видеокарта распаковывать ассеты быстрее процессора.
    
    # Очистка системной переменной SDL_AUDIODRIVER (защита от потери звука в старых играх на SDL 1.2; в SDL 2+ WASAPI активен по умолчанию)
    Apply-Tweak "Сброс системного форсирования SDL_AUDIODRIVER (Совместимость со старыми играми)" { [Environment]::SetEnvironmentVariable("SDL_AUDIODRIVER", $null, "Machine") }
    
    # Запрещает движку SDL переименовывать потоки процессора в реальном времени (вызов SetThreadDescription вызывает спайки DPC)
    Apply-Tweak "Запрет движку SDL переименовывать потоки CPU (Фикс DPC)" { [Environment]::SetEnvironmentVariable("SDL_HINT_WINDOWS_DISABLE_THREAD_NAMING", "1", "Machine") }
    
    # Отключает встроенный поллинг джойстиков, если они не подключены (Снижает нагрузку на USB-шину)
    Apply-Tweak "Отключение поллинга джойстиков SDL (Снижение нагрузки на USB)" { [Environment]::SetEnvironmentVariable("SDL_JOYSTICK_DISABLE_HIDAPI", "1", "Machine") }
    
    # Асинхронные очереди задач GTS должны работать для полноценной многопоточности в играх на Unreal Engine
    Apply-Tweak "Удаление блокировки асинхронных очередей задач GTS (Unreal Engine Fix)" {
        [Environment]::SetEnvironmentVariable("DISABLE_GTS_ASYNC_WORK_QUEUE", $null, "Machine")
    }
    Apply-Tweak "Удаление блокировки GTS Async Compute (Unreal Engine Fix)" {
        [Environment]::SetEnvironmentVariable("DISABLE_GTS_ASYNC_COMPUTE", $null, "Machine")
    } 
    
    # Запрещает вычислительным потокам засыпать в ожидании данных
    Apply-Tweak "Запрет вычислительным потокам KMP засыпать (KMP_BLOCKTIME=0)" { [Environment]::SetEnvironmentVariable("KMP_BLOCKTIME", "0", "Machine") }

    # Unity Engine: Принудительный многопоточный рендеринг и отключение телеметрии движка
    Apply-Tweak "Unity: Форсирование многопоточного рендеринга" { [Environment]::SetEnvironmentVariable("UNITY_MULTITHREADED_RENDERING", "1", "Machine") }
    Apply-Tweak "Unity: Отключение встроенной телеметрии" { [Environment]::SetEnvironmentVariable("UNITY_DISABLE_TELEMETRY", "1", "Machine") }

    # Jemalloc: Борьба с фрагментацией ОЗУ (Помогает от утечек памяти в Rust, Minecraft)
    Apply-Tweak "Jemalloc: Оптимизация фрагментации памяти" { [Environment]::SetEnvironmentVariable("MALLOC_CONF", "dirty_decay_ms:2000,muzzy_decay_ms:2000", "Machine") }
}

# Принудительное включение вычислений формата TF32 для видеокарт NVIDIA. Ускоряет генерацию DLSS-кадров на ~30%.
Apply-Tweak "Включение формата TF32 для NVIDIA (Ускорение DLSS)" { [Environment]::SetEnvironmentVariable("NVIDIA_TF32_OVERRIDE", "1", "Machine") }

# Очищаем системный NODE_OPTIONS на уровне Machine во избежание краха сред разработки Node.js, Vite и VS Code
Apply-Tweak "Очистка системной переменной NODE_OPTIONS (Защита сборок Node.js)" { [Environment]::SetEnvironmentVariable("NODE_OPTIONS", $null, "Machine") }

# Очистка путей DirectX SDK (Исключает лишние поиски системных DLL по диску)
Apply-Tweak "Очистка системной переменной DXSDK_DIR" { [Environment]::SetEnvironmentVariable("DXSDK_DIR", "", "Machine") }

# Отключает сбор данных при использовании PowerShell и библиотек .NET (многие игры на Unity используют их в фоне)
Apply-Tweak "Отключение телеметрии PowerShell" { [Environment]::SetEnvironmentVariable("POWERSHELL_TELEMETRY_OPTOUT", "1", "Machine") }
Apply-Tweak "Отключение телеметрии .NET CLI" { [Environment]::SetEnvironmentVariable("DOTNET_CLI_TELEMETRY_OPTOUT", "1", "Machine") }

# Включение Tiered PGO для .NET (Динамическая оптимизация кода в реальном времени). Заметно ускоряет работу C# программ.
Apply-Tweak "Включение динамической оптимизации Tiered PGO для .NET" { [Environment]::SetEnvironmentVariable("DOTNET_TieredPGO", "1", "Machine") }

Write-Host ""
# ==============================================================================
# Раздел 75: Очистка вредных фоновых служб (обнаружение, геймпады)
# ==============================================================================
Show-ProgressStep -StepNum 75 -TotalSteps 81 -Activity "Очистка вредных фоновых служб..."
Write-Host "==============================================================================" -ForegroundColor DarkGray
Write-Host "РАЗДЕЛ 75: ОЧИСТКА ВРЕДНЫХ ФОНОВЫХ СЛУЖБ (ОБНАРУЖЕНИЕ, ГЕЙМПАДЫ)" -ForegroundColor Cyan
Write-Host "==============================================================================" -ForegroundColor DarkGray
# Список служб 100% мусора и телеметрии (Их отключение безопасно для игр)
$DiscoveryServices = @(
    "SSDPSRV",       # Обнаружение SSDP (постоянно сканирует сеть на наличие Smart-TV и роутеров)
    "upnphost",      # Узел универсальных PNP-устройств (работает в паре с SSDP)
    "FDResPub",      # Публикация ресурсов (поиск принтеров и сетевых папок соседей)
    "DusmSvc",       # Использование данных (считает каждый скачанный мегабайт, постоянно дергая диск для записи статистики)
    "icssvc",        # Общий доступ к интернету (нужна только если раздаете Wi-Fi с ПК как с роутера)
    "WMPNetworkSvc"  # Отключение сканирования ваших медиафайлов (музыки/видео) в фоне
)

foreach ($Svc in $DiscoveryServices) {
    if (Get-Service -Name $Svc -ErrorAction SilentlyContinue 2>> $env:SystemDrive\EastricaTools\Eastrica_ErrorTrace.log) {
        Apply-Tweak "Остановка мусорной службы обнаружения ($Svc)" { Stop-Service -Name $Svc -Force *>&1 | Out-File -FilePath $global:LogPath -Append -Encoding UTF8 } # Останавливаем
        Apply-Tweak "Отключение автозапуска службы обнаружения ($Svc)" { Set-Service -Name $Svc -StartupType Disabled *>&1 | Out-File -FilePath $global:LogPath -Append -Encoding UTF8 } # Выключаем из автозагрузки
    }
}

# Отключение служб геймпадов (Micro-stutter & USB Polling Fix)
# Службы Xbox и GameInput спамят USB-контроллер запросами на поиск геймпадов (даже если их нет).
if ($global:OptServices) {
    # Оставляем GameInputSvc в режиме Manual (Она нужна для клавиатур/мышей в современных играх Microsoft)
    if (Get-Service -Name "GameInputSvc" -ErrorAction SilentlyContinue 2>> $env:SystemDrive\EastricaTools\Eastrica_ErrorTrace.log) {
        Apply-Tweak "Перевод GameInputSvc в ручной запуск" { Set-Service -Name "GameInputSvc" -StartupType Manual *>&1 | Out-File -FilePath $global:LogPath -Append -Encoding UTF8 }
    }

    # Переводим службу аксессуаров Xbox в "Вручную" вместо полного отключения
    # Это уберет фоновый опрос USB-порта, но сохранит работу геймпада при его физическом подключении
    if (Get-Service -Name "XboxGipSvc" -ErrorAction SilentlyContinue 2>> $env:SystemDrive\EastricaTools\Eastrica_ErrorTrace.log) {
        Apply-Tweak "Остановка службы аксессуаров Xbox (XboxGipSvc)" { Stop-Service -Name "XboxGipSvc" -Force *>&1 | Out-File -FilePath $global:LogPath -Append -Encoding UTF8 }
        Apply-Tweak "Перевод службы XboxGipSvc в ручной запуск" { Set-Service -Name "XboxGipSvc" -StartupType Manual *>&1 | Out-File -FilePath $global:LogPath -Append -Encoding UTF8 }
    }
} else {
    # Если галочка "Services" не стоит, возвращаем штатный автозапуск служб Windows (Для принтеров, поиска и геймпадов).
    $DefaultServices = @("GameInputSvc", "XboxGipSvc")
    foreach ($Svc in $DefaultServices) {
        if (Get-Service -Name $Svc -ErrorAction SilentlyContinue -ErrorAction SilentlyContinue 2>> $env:SystemDrive\EastricaTools\Eastrica_ErrorTrace.log) {
            Apply-Tweak "Восстановление автозапуска службы геймпадов ($Svc)" { Set-Service -Name $Svc -StartupType Automatic *>&1 | Out-File -FilePath $global:LogPath -Append -Encoding UTF8 }
            Apply-Tweak "Запуск службы геймпадов ($Svc)" { Start-Service -Name $Svc *>&1 | Out-File -FilePath $global:LogPath -Append -Encoding UTF8 }
        }
    }
}

# Восстановление драйвера фильтрации дисков Game Pass (gameflt)
    $GamefltPath = "HKLM:\SYSTEM\CurrentControlSet\Services\gameflt"
    if (Test-Path $GamefltPath) {
        # Использование Set-Service на системном драйвере ломает его! Используем только прямое обращение к реестру.
        Apply-Tweak "Восстановление запуска gameflt в реестре (Auto/3)" { Set-ItemProperty -Path $GamefltPath -Name "Start" -Value 3 -Type DWord -Force *>&1 | Out-File -FilePath $global:LogPath -Append -Encoding UTF8 }
        Apply-Tweak "Принудительный запуск драйвера Xbox (gameflt)" { 
            $proc = Start-Process -FilePath "sc.exe" -ArgumentList "start gameflt" -Wait -WindowStyle Hidden -PassThru
            # Код 0 = успешно запущен, Код 1056 = уже был запущен
            if ($proc.ExitCode -ne 0 -and $proc.ExitCode -ne 1056) { throw "ExitCode: $($proc.ExitCode)" }
        }
    }

# Фикс для мышей с высокой частотой опроса (1000Hz - 8000Hz)
# Разгружает системный процесс CSRSS.exe от необходимости парсить каждое движение мыши для телеметрии "удобства ввода"
$InputPersonalization = "HKCU:\Software\Microsoft\InputPersonalization"
if (!(Test-Path $InputPersonalization)) { Apply-Tweak "Создание раздела InputPersonalization" { New-Item $InputPersonalization -Force *>&1 | Out-File -FilePath $global:LogPath -Append -Encoding UTF8 } }
Apply-Tweak "Запрет скрытого сбора текста (RestrictImplicitTextCollection)" { Set-ItemProperty -Path $InputPersonalization -Name "RestrictImplicitTextCollection" -Value 1 -Type DWord -Force *>&1 | Out-File -FilePath $global:LogPath -Append -Encoding UTF8 } # 1 = Запрет скрытого сбора текста
Apply-Tweak "Запрет скрытого сбора рукописного ввода (RestrictImplicitInkCollection)" { Set-ItemProperty -Path $InputPersonalization -Name "RestrictImplicitInkCollection" -Value 1 -Type DWord -Force *>&1 | Out-File -FilePath $global:LogPath -Append -Encoding UTF8 } # 1 = Запрет скрытого сбора рукописного ввода

Write-Host ""
# ==============================================================================
# Раздел 76: Zero-Stutter I/O & Bus Optimization (аппаратный сон и задержки)
# ==============================================================================
Show-ProgressStep -StepNum 76 -TotalSteps 81 -Activity "Оптимизация I/O и шин (Zero-Stutter)..."
Write-Host "==============================================================================" -ForegroundColor DarkGray
Write-Host "РАЗДЕЛ 76: ZERO-STUTTER I/O & BUS OPTIMIZATION (АППАРАТНЫЙ СОН И ЗАДЕРЖКИ)" -ForegroundColor Cyan
Write-Host "==============================================================================" -ForegroundColor DarkGray

# Глубокое отключение сна для звуковых карт (Устранение заиканий звука)
$AudioClass = "HKLM:\SYSTEM\CurrentControlSet\Control\Class\{4d36e96c-e325-11ce-bfc1-08002be10318}"
if ($global:OptHwSleep) {
    Apply-Tweak "Захват прав на класс аудиоустройств" { Grant-RegPermission -RegPath $AudioClass } # Взлом класса
    $AudioDevices = Get-SafeClassAdapters -ClassPath $AudioClass
    
    foreach ($Dev in $AudioDevices) {
        $PowerKey = "$($Dev.PSPath)\PowerSettings"
        if (Test-Path -LiteralPath $PowerKey) {
            Apply-Tweak "Захват прав на настройки питания аудиоустройства" { Grant-RegPermission -RegPath $PowerKey }
            Apply-Tweak "Отключение сна звука от сети (ConservationIdleTime=FF)" { Set-ItemProperty -LiteralPath $PowerKey -Name "ConservationIdleTime" -Value ([byte[]](0xff,0xff,0xff,0xff)) -Type Binary -Force *>&1 | Out-File -FilePath $global:LogPath -Append -Encoding UTF8 } # FF FF FF FF — это бинарное (шестнадцатеричное) представление максимального 32-битного числа (4 294 967 295 секунд). Мы фактически задаем таймаут сна в бесконечность.
            Apply-Tweak "Отключение сна звука от батареи (PerformanceIdleTime=FF)" { Set-ItemProperty -LiteralPath $PowerKey -Name "PerformanceIdleTime" -Value ([byte[]](0xff,0xff,0xff,0xff)) -Type Binary -Force *>&1 | Out-File -FilePath $global:LogPath -Append -Encoding UTF8 } # Отключаем сон от батареи
            Apply-Tweak "Запрет перехода в состояние энергосбережения звука (IdlePowerState)" { Set-ItemProperty -LiteralPath $PowerKey -Name "IdlePowerState" -Value ([byte[]](0x00,0x00,0x00,0x00)) -Type Binary -Force *>&1 | Out-File -FilePath $global:LogPath -Append -Encoding UTF8 } # Запрет перехода в состояние энергосбережения
            Apply-Tweak "Возврат прав на настройки питания аудиоустройства" { Restore-RegPermission -RegPath $PowerKey }
        }
    }

    # Запрет контроллерам дисков (StorPort) управлять питанием
    $StorPort = "HKLM:\SYSTEM\CurrentControlSet\Control\StorPort"
    if (!(Test-Path $StorPort)) { Apply-Tweak "Создание раздела StorPort" { New-Item -Path $StorPort -Force *>&1 | Out-File -FilePath $global:LogPath -Append -Encoding UTF8 } }
    Apply-Tweak "Жесткий запрет StorPort усыплять диски (EnableIdlePowerManagement)" { Set-ItemProperty -Path $StorPort -Name "EnableIdlePowerManagement" -Value 0 -Type DWord -Force *>&1 | Out-File -FilePath $global:LogPath -Append -Encoding UTF8 } # 0 = Жестко запрещаем StorPort усыплять диски
}

# Изоляция прерываний USB Audio ЦАП / Внешних звуковых карт (Убирает хрипы USB-наушников)
$AudioDevices = Get-SafeClassAdapters -ClassPath $AudioClass
foreach ($Dev in $AudioDevices) {
    Apply-Tweak "Захват прав на аудиоустройство" { Grant-RegPermission -RegPath $Dev.PSPath }
    # 1 = Снимаем любые программные лимиты на размер аудио-буфера в драйвере системной шины
    Apply-Tweak "Снятие лимитов аудио-буфера (BypassAudioRoutings)" { Set-ItemProperty -LiteralPath $Dev.PSPath -Name "BypassAudioRoutings" -Value 1 -Type DWord -Force *>&1 | Out-File -FilePath $global:LogPath -Append -Encoding UTF8 }
    Apply-Tweak "Отключение энергосбережения аудио ЦАПа (DisablePowerManagement)" { Set-ItemProperty -LiteralPath $Dev.PSPath -Name "DisablePowerManagement" -Value 1 -Type DWord -Force *>&1 | Out-File -FilePath $global:LogPath -Append -Encoding UTF8 } # 1 = Отключаем энергосбережение ЦАПа
    Apply-Tweak "Возврат прав на аудиоустройство" { Restore-RegPermission -RegPath $Dev.PSPath }
}
Apply-Tweak "Возврат прав на класс аудиоустройств" { Restore-RegPermission -RegPath $AudioClass }

# Фикс фризов от фонового опроса устройств (Device Setup Manager)
# Служба DsmSvc периодически ищет драйверы и метаданные в интернете для всех USB и PCI устройств. В момент ее активации шина "залипает" на долю секунды.
if (Get-Service -Name "DsmSvc" -ErrorAction SilentlyContinue 2>> $env:SystemDrive\EastricaTools\Eastrica_ErrorTrace.log) {
    Apply-Tweak "Перевод службы DsmSvc в режим Вручную" { Set-ItemProperty -Path "HKLM:\SYSTEM\CurrentControlSet\Services\DsmSvc" -Name "Start" -Value 3 -Type DWord -Force *>&1 | Out-File -FilePath $global:LogPath -Append -Encoding UTF8 }
}

# Отключение фонового логирования ошибок шины (PCIe AER)
# Каждый микро-сбой на шине PCIe заставляет ядро Windows писать лог через WHEA, что вызывает фризы (особенно на AMD).
$WheaErrors = "HKLM:\SYSTEM\CurrentControlSet\Services\Whea\Errors"
if (!(Test-Path $WheaErrors)) { Apply-Tweak "Создание раздела Whea Errors" { New-Item -Path $WheaErrors -Force *>&1 | Out-File -FilePath $global:LogPath -Append -Encoding UTF8 } }
Apply-Tweak "Запрет записи логов ошибок PCIe (DisableErrorLogging)" { Set-ItemProperty -Path $WheaErrors -Name "DisableErrorLogging" -Value 1 -Type DWord -Force *>&1 | Out-File -FilePath $global:LogPath -Append -Encoding UTF8 } # 1 = Запрет записи логов

# Kernel NMI & Crash Dump paralysis
# Жестко запрещаем ядру генерировать тяжелые дампы памяти при сбоях (Система просто мгновенно перезагрузится, а не будет висеть намертво).
$CrashControl = "HKLM:\SYSTEM\CurrentControlSet\Control\CrashControl"
if (!(Test-Path $CrashControl)) { Apply-Tweak "Создание раздела CrashControl" { New-Item -Path $CrashControl -Force *>&1 | Out-File -FilePath $global:LogPath -Append -Encoding UTF8 } }
Apply-Tweak "Запрет записи системных дампов памяти (CrashDumpEnabled)" { Set-ItemProperty -Path $CrashControl -Name "CrashDumpEnabled" -Value 0 -Type DWord -Force *>&1 | Out-File -FilePath $global:LogPath -Append -Encoding UTF8 } # 0 = Не писать дамп
Apply-Tweak "Запрет записи событий краша в журнал (LogEvent)" { Set-ItemProperty -Path $CrashControl -Name "LogEvent" -Value 0 -Type DWord -Force *>&1 | Out-File -FilePath $global:LogPath -Append -Encoding UTF8 } # 0 = Не писать событие в Журнал
Apply-Tweak "Запрет NMI дампов" { Set-ItemProperty -Path $CrashControl -Name "NMICrashDump" -Value 0 -Type DWord -Force *>&1 | Out-File -FilePath $global:LogPath -Append -Encoding UTF8 } # 0 = Запрет NMI дампов
Apply-Tweak "Отключение автоматической перезагрузки при синем экране (AutoReboot)" { Set-ItemProperty -Path $CrashControl -Name "AutoReboot" -Value 0 -Type DWord -Force *>&1 | Out-File -FilePath $global:LogPath -Append -Encoding UTF8 } # 0 = Не перезагружаться автоматически (оставит синий экран висеть, чтобы вы успели прочитать код ошибки)

# Запрет создания дампов памяти видеокарты (Устраняет жесткие фризы по 5-10 секунд при микро-сбоях видеодрайвера)
$LiveKernel = "HKLM:\SYSTEM\CurrentControlSet\Control\CrashControl\LiveKernelReports"
if (!(Test-Path $LiveKernel)) { Apply-Tweak "Создание раздела LiveKernelReports" { New-Item $LiveKernel -Force *>&1 | Out-File -FilePath $global:LogPath -Append -Encoding UTF8 } }
Apply-Tweak "Удаление старых дампов ядра видеокарты (DeleteLiveKernelReports)" { Set-ItemProperty -Path $LiveKernel -Name "DeleteLiveKernelReports" -Value 1 -Type DWord -Force *>&1 | Out-File -FilePath $global:LogPath -Append -Encoding UTF8 } # 1 = Удалять старые дампы ядра
Apply-Tweak "Запрет создания новых дампов ядра видеокарты (DisableLiveKernelReports)" { Set-ItemProperty -Path $LiveKernel -Name "DisableLiveKernelReports" -Value 1 -Type DWord -Force *>&1 | Out-File -FilePath $global:LogPath -Append -Encoding UTF8 } # 1 = Запретить создавать новые дампы

Write-Host ""
# ==============================================================================
# Раздел 77: Защитник Windows (аппаратная изоляция) и AMSI
# ==============================================================================
Show-ProgressStep -StepNum 77 -TotalSteps 81 -Activity "Аппаратная изоляция Защитника Windows и AMSI..."
Write-Host "==============================================================================" -ForegroundColor DarkGray
Write-Host "РАЗДЕЛ 77: ЗАЩИТНИК WINDOWS (АППАРАТНАЯ ИЗОЛЯЦИЯ) И AMSI" -ForegroundColor Cyan
Write-Host "==============================================================================" -ForegroundColor DarkGray

if ($global:OptDefender) {
    Write-Host "[WARNING] Чтобы инспекция Защитника отключилась, у вас должна быть ВЫКЛЮЧЕНА" -ForegroundColor DarkGray
    Write-Host "'Защита от подделки' (Tamper Protection) в настройках безопасности Windows!" -ForegroundColor DarkGray
    try {
        # Отключаем мониторинг поведения, проверку файлов на лету, сканирование скриптов и архивов
        Apply-Tweak "Отключение модулей проверки Защитника Windows" { Set-MpPreference -DisableBehaviorMonitoring $true -DisableIOAVProtection $true -DisableScriptScanning $true -DisableArchiveScanning $true *>&1 | Out-File -FilePath $global:LogPath -Append -Encoding UTF8 }
    } catch { Write-Warning "Ошибка при выполнении: $($_.Exception.Message)" }

    if (Get-Service -Name "WdNisSvc" -ErrorAction SilentlyContinue) {
        $tamper = (Get-ItemProperty -Path "HKLM:\SOFTWARE\Microsoft\Windows Defender\Features" -Name "TamperProtection" -ErrorAction SilentlyContinue).TamperProtection
        if ($tamper -eq 4) {
            # Защита от подделки выключена — остановка разрешена
            Apply-Tweak "Остановка службы инспекции сети Защитника (WdNisSvc)" { 
                cmd.exe /c "sc.exe stop WdNisSvc >nul 2>&1"
                $global:LASTEXITCODE = 0
            }
            Apply-Tweak "Отключение службы инспекции сети Защитника (WdNisSvc)" { 
                Set-ItemProperty -Path "HKLM:\SYSTEM\CurrentControlSet\Services\WdNisSvc" -Name "Start" -Value 4 -Type DWord -Force *>&1 | Out-File -FilePath $global:LogPath -Append -Encoding UTF8
                cmd.exe /c "sc.exe config WdNisSvc start= disabled >nul 2>&1"
                $global:LASTEXITCODE = 0
            }
        } else {
            Write-Host " ► [Пропуск] WdNisSvc защищена от остановки (Включена защита от подделки Tamper Protection)." -ForegroundColor DarkGray
        }
    }

    # Отключаем драйвер сетевой инспекции Защитника (WdFilter оставляем нетронутым во избежание BSOD INACCESSIBLE_BOOT_DEVICE)
    $WdDrivers = @("WdNisDrv")
    foreach ($drv in $WdDrivers) {
        $DrvPath = "HKLM:\SYSTEM\CurrentControlSet\Services\$drv"
        if (Test-Path $DrvPath) {
            Apply-Tweak "Отключение сетевой инспекции трафика Защитника ($drv)" { Set-ItemProperty -Path $DrvPath -Name "Start" -Value 4 -Type DWord -Force *>&1 | Out-File -FilePath $global:LogPath -Append -Encoding UTF8 }
        }
    }

    # Удушаем главный движок сканирования Защитника (MsMpEng.exe), чтобы он не мог забрать мощность CPU у игры
    $DefenderPerf = "HKLM:\SOFTWARE\Microsoft\Windows NT\CurrentVersion\Image File Execution Options\MsMpEng.exe\PerfOptions"
    if (!(Test-Path $DefenderPerf)) { Apply-Tweak "Создание профиля IFEO для движка Защитника (MsMpEng.exe)" { New-Item $DefenderPerf -Force *>&1 | Out-File -FilePath $global:LogPath -Append -Encoding UTF8 } }
    Apply-Tweak "Низший приоритет CPU для сканера Защитника" { Set-ItemProperty -Path $DefenderPerf -Name "CpuPriorityClass" -Value 1 -Type DWord -Force *>&1 | Out-File -FilePath $global:LogPath -Append -Encoding UTF8 } # 1 = Idle Priority (Низший)
    Apply-Tweak "Низший приоритет I/O для сканера Защитника" { Set-ItemProperty -Path $DefenderPerf -Name "IoPriority" -Value 0 -Type DWord -Force *>&1 | Out-File -FilePath $global:LogPath -Append -Encoding UTF8 } # 0 = Низший приоритет чтения диска

    # Скрытие иконки "Безопасность Windows" из системного трея (рядом с часами)
    $SecuritySystray = "HKLM:\SOFTWARE\Policies\Microsoft\Windows Defender Security Center\Systray"
    if (!(Test-Path $SecuritySystray)) { Apply-Tweak "Создание раздела Systray Security Center" { New-Item -Path $SecuritySystray -Force *>&1 | Out-File -FilePath $global:LogPath -Append -Encoding UTF8 } }
    Apply-Tweak "Скрытие иконки Защитника из трея (HideSystray)" { Set-ItemProperty -Path $SecuritySystray -Name "HideSystray" -Value 1 -Type DWord -Force *>&1 | Out-File -FilePath $global:LogPath -Append -Encoding UTF8 } # 1 = Скрыть значок щита

    Apply-Tweak "Удаление SecurityHealthSystray из автозагрузки" { Remove-ItemProperty -Path "HKLM:\SOFTWARE\Microsoft\Windows\CurrentVersion\Run" -Name "SecurityHealth" -Force *>&1 | Out-File -FilePath $global:LogPath -Append -Encoding UTF8 }
} else {
    # Восстановление Защитника Windows к заводским настройкам
    try {
        Apply-Tweak "Восстановление модулей проверки Защитника Windows" { Set-MpPreference -DisableBehaviorMonitoring $false -DisableIOAVProtection $false -DisableScriptScanning $false -DisableArchiveScanning $false *>&1 | Out-File -FilePath $global:LogPath -Append -Encoding UTF8 }
    } catch { Write-Warning "Ошибка при выполнении: $($_.Exception.Message)" }

    if (Get-Service -Name "WdNisSvc" -ErrorAction SilentlyContinue 2>> $env:SystemDrive\EastricaTools\Eastrica_ErrorTrace.log) {
        Apply-Tweak "Включение службы инспекции сети Защитника (WdNisSvc)" { Set-Service -Name "WdNisSvc" -StartupType Automatic *>&1 | Out-File -FilePath $global:LogPath -Append -Encoding UTF8 }
        Apply-Tweak "Запуск службы инспекции сети Защитника (WdNisSvc)" { Start-Service -Name "WdNisSvc" *>&1 | Out-File -FilePath $global:LogPath -Append -Encoding UTF8 }
    }

    $WdDrivers = @("WdNisDrv")
    foreach ($drv in $WdDrivers) {
        $DrvPath = "HKLM:\SYSTEM\CurrentControlSet\Services\$drv"
        if (Test-Path $DrvPath) { Apply-Tweak "Восстановление сетевой инспекции трафика Защитника ($drv)" { Set-ItemProperty -Path $DrvPath -Name "Start" -Value 2 -Type DWord -Force *>&1 | Out-File -FilePath $global:LogPath -Append -Encoding UTF8 } } # 2 = Автостарт
    }

    # Снимаем ограничения (Удушение) с движка
    Apply-Tweak "Удаление ограничений IFEO для сканера Защитника" { Remove-Item -Path "HKLM:\SOFTWARE\Microsoft\Windows NT\CurrentVersion\Image File Execution Options\MsMpEng.exe" *>&1 | Out-File -FilePath $global:LogPath -Append -Encoding UTF8 }

    $SecuritySystray = "HKLM:\SOFTWARE\Policies\Microsoft\Windows Defender Security Center\Systray"
    if (!(Test-Path $SecuritySystray)) { Apply-Tweak "Создание раздела Systray Security Center" { New-Item -Path $SecuritySystray -Force *>&1 | Out-File -FilePath $global:LogPath -Append -Encoding UTF8 } }
    Apply-Tweak "Отображение иконки Защитника в трее (HideSystray=0)" { Set-ItemProperty -Path $SecuritySystray -Name "HideSystray" -Value 0 -Type DWord -Force *>&1 | Out-File -FilePath $global:LogPath -Append -Encoding UTF8 } # 0 = Показать щит

    Apply-Tweak "Запись SecurityHealthSystray в автозагрузку" { Set-ItemProperty -Path "HKLM:\SOFTWARE\Microsoft\Windows\CurrentVersion\Run" -Name "SecurityHealth" -Value "%windir%\system32\SecurityHealthSystray.exe" -Type String -Force *>&1 | Out-File -FilePath $global:LogPath -Append -Encoding UTF8 }
}

# Устанавливаем режим Boot ТОЛЬКО если драйвер физически существует в системе, иначе получим BSOD
if (Test-Path "$env:SystemRoot\System32\drivers\WdFilter.sys") {
    Apply-Tweak "Установка драйвера WdFilter в режим Boot (Защита от BSOD)" { 
        Grant-RegPermission -RegPath "HKLM:\SYSTEM\CurrentControlSet\Services\WdFilter"
        Set-ItemProperty -Path "HKLM:\SYSTEM\CurrentControlSet\Services\WdFilter" -Name "Start" -Value 0 -Type DWord -Force -ErrorAction SilentlyContinue *>&1 | Out-File -FilePath $global:LogPath -Append -Encoding UTF8 
        Restore-RegPermission -RegPath "HKLM:\SYSTEM\CurrentControlSet\Services\WdFilter"
        # Вызов sc.exe выполняется изолированно; при блокировке со стороны Tamper Protection код ошибки сбрасывается
        cmd.exe /c "sc.exe config WdFilter start= boot >nul 2>&1"
        $global:LASTEXITCODE = 0
    }
} else {
    Write-Host " ► [ПРОПУСК] Драйвер WdFilter.sys удален из ОС. Твик пропущен во избежание BSOD." -ForegroundColor DarkGray
}

# Полное отключение AMSI (Antimalware Scan Interface)
# AMSI перехватывает и проверяет каждый запускаемый скрипт или программу на вирусы. Его отключение ускоряет запуск ПО в разы.
$AmsiKey = "HKLM:\SOFTWARE\Microsoft\AMSI\Providers"
if (-not $global:OptAntiCheat) {
    if (Test-Path $AmsiKey) {
        Apply-Tweak "Блокировка интеграции провайдера AMSI" { Set-ItemProperty -Path "$AmsiKey\{2781761E-28E0-4109-99FE-B9D127C57AFE}" -Name "AMSI" -Value 0 -Type DWord -Force *>&1 | Out-File -FilePath $global:LogPath -Append -Encoding UTF8 } # 0 = Блокируем интеграцию провайдера Microsoft
    }
} else {
    # Античиты могут кикнуть, если увидят, что интерфейс антивируса (AMSI) выключен
    if (Test-Path $AmsiKey) {
        Apply-Tweak "Удаление блокировки AMSI (Режим Античита)" { Remove-ItemProperty -Path "$AmsiKey\{2781761E-28E0-4109-99FE-B9D127C57AFE}" -Name "AMSI" *>&1 | Out-File -FilePath $global:LogPath -Append -Encoding UTF8 } # Удаляем твик
    }
}

Write-Host ""
# ==============================================================================
# Раздел 78: Очистка журналов событий и трассировки ядра (ETW)
# ==============================================================================
Show-ProgressStep -StepNum 78 -TotalSteps 81 -Activity "Очистка журналов событий и трассировки ядра (ETW)..."
Write-Host "==============================================================================" -ForegroundColor DarkGray
Write-Host "РАЗДЕЛ 78: ОЧИСТКА ЖУРНАЛОВ СОБЫТИЙ И ТРАССИРОВКИ ЯДРА (ETW)" -ForegroundColor Cyan
Write-Host "==============================================================================" -ForegroundColor DarkGray

# Изоляция журналов событий (I/O Spikes Fix)
# Ограничиваем размер главных логов до 1 МБ. Предотвращает ситуацию, когда ядро сбрасывает 
# огромный кэш ошибок на медленный диск прямо во время активной перестрелки в игре.
$EventLogs = @("Application", "System", "Security", "Setup")
foreach ($Log in $EventLogs) {
    Apply-Tweak "Ограничение размера журнала событий $Log до 1 МБ" { 
        cmd.exe /c "wevtutil sl `"$Log`" /ms:1048576 >nul 2>&1"
        $global:LASTEXITCODE = 0 
    }
}

Apply-Tweak "Пакетная очистка системных журналов событий (Нативный вызов)" { 
    $session = New-Object System.Diagnostics.Eventing.Reader.EventLogSession
    $allLogs = $session.GetLogNames()
    foreach ($log in $allLogs) {
        try {
            $session.ClearLog($log)
        } catch {
            # Защищенные или отключенные аналитические каналы (например, LiveId/Analytic) пропускаются без выброса исключения
        }
    }
    $global:LASTEXITCODE = 0 
}

# Глушим встроенные логгеры телеметрии и оверлеев (Работающие прямо в ОЗУ)
$ActiveLoggers = @("EventLog-AirSpaceChannel", "DiagLog", "WdiContextLog", "GameRecorder", "GameOverlay", "XboxNetApiSvc")

# Проверка Tamper Protection (Защита от подделки). Значение 4 = Выключено, 5 = Включено.
$TamperStatus = (Get-ItemProperty -Path "HKLM:\SOFTWARE\Microsoft\Windows Defender\Features" -Name "TamperProtection" 2>> $env:SystemDrive\EastricaTools\Eastrica_ErrorTrace.log).TamperProtection
if ($TamperStatus -eq 4) {
    $ActiveLoggers += "DefenderApiLogger" # Если защита выключена, мы имеем право заглушить логгер Защитника
}

foreach ($Logger in $ActiveLoggers) {
    Apply-Tweak "Принудительная остановка логгера $Logger" { 
        cmd /c "logman stop `"$Logger`" -ets >nul 2>&1" *>&1 | Out-File -FilePath $global:LogPath -Append -Encoding UTF8
        $global:LASTEXITCODE = 0 
    }
}

if ($global:OptAntiCheat) {
    # Проверяем, запущен ли логгер ядра перед попыткой старта
    $ckclStatus = cmd.exe /c "logman query `"Circular Kernel Context Logger`" -ets 2>&1" | Out-String
    if ($ckclStatus -match "(?i)running|работает|started") {
        Write-Host " ► Системный логгер ядра CKCL уже активен" -ForegroundColor DarkGray
    } else {
        Apply-Tweak "Запуск системного логгера ядра CKCL (Режим Античита)" { 
            cmd.exe /c "logman start `"Circular Kernel Context Logger`" -ets >nul 2>&1"
            $global:LASTEXITCODE = 0
        }
    }
} else {
    # В хардкорном режиме останавливаем только мусорные телеметрические сессии ETW.
    # Сессии ядра NT Kernel Logger, Audio, Circular Kernel Context Logger и логгеры графики DWM
    # обязаны оставаться активными, иначе ломаются счетчики производительности, оверлеи и синхронизация звука.
    $ActiveEtwSessions = (cmd.exe /c "logman query -ets 2>&1") | Where-Object { $_ -match "^[A-Za-z0-9_]" } | ForEach-Object { ($_ -split '\s{2,}')[0].Trim() }
    
    # Расширенный защитный белый список жизненно важных сессий ядра Windows:
    $EtwWhiteList = @(
        "EventLog-System", 
        "EventLog-Application", 
        "EventLog-Security", 
        "NT Kernel Logger", 
        "Circular Kernel Context Logger", 
        "Audio", 
        "ScreenOnAgent", 
        "UBPM"
    )
    
    foreach ($Session in $ActiveEtwSessions) {
        if ($Session -notin $EtwWhiteList -and $Session -ne "Name" -and -not [string]::IsNullOrWhiteSpace($Session)) {
            Apply-Tweak "Остановка телеметрической ETW сессии ($Session)" { 
                cmd.exe /c "logman stop `"$Session`" -ets >nul 2>&1"
                $global:LASTEXITCODE = 0
            }
        }
    }
}

# Полная блокировка WerFault (Подсистема отчетов об ошибках Windows)
$WER = "HKLM:\SOFTWARE\Microsoft\Windows\Windows Error Reporting"
if (!(Test-Path $WER)) { Apply-Tweak "Создание раздела Windows Error Reporting" { New-Item $WER -Force *>&1 | Out-File -FilePath $global:LogPath -Append -Encoding UTF8 } }
Apply-Tweak "Отключение создания отчетов об ошибках (WerFault)" { Set-ItemProperty -Path $WER -Name "Disabled" -Value 1 -Type DWord -Force *>&1 | Out-File -FilePath $global:LogPath -Append -Encoding UTF8 } # 1 = Выключить создание отчетов при крашах игр
$WER_Policy = "HKLM:\SOFTWARE\Policies\Microsoft\Windows\Windows Error Reporting" # Политика отчетов
if (!(Test-Path $WER_Policy)) { Apply-Tweak "Создание раздела политик Windows Error Reporting" { New-Item -Path $WER_Policy -Force *>&1 | Out-File -FilePath $global:LogPath -Append -Encoding UTF8 } }
Apply-Tweak "Отключение политик создания отчетов об ошибках" { Set-ItemProperty -Path $WER_Policy -Name "Disabled" -Value 1 -Type DWord -Force *>&1 | Out-File -FilePath $global:LogPath -Append -Encoding UTF8 } # 1 = Выключить

# Принудительная команда TRIM (Сброс мусора с SSD-диска)
Apply-Tweak "Принудительный TRIM диска C: (Optimize-Volume)" { Optimize-Volume -DriveLetter C -ReTrim *>&1 | Out-File -FilePath $global:LogPath -Append -Encoding UTF8 } # Ускоряет запись на диск после масштабной чистки

Write-Host ""
# ==============================================================================
# Раздел 79: Проверка статуса Resizable BAR и вывод результатов
# ==============================================================================
Show-ProgressStep -StepNum 79 -TotalSteps 81 -Activity "Проверка статуса Resizable BAR..."
Write-Host "==============================================================================" -ForegroundColor DarkGray
Write-Host "РАЗДЕЛ 79: ПРОВЕРКА СТАТУСА RESIZABLE BAR И ВЫВОД РЕЗУЛЬТАТОВ" -ForegroundColor Cyan
Write-Host "==============================================================================" -ForegroundColor DarkGray
Write-Host " ► Проверка статуса Resizable BAR (Smart Access Memory)..." -ForegroundColor Magenta
$ReBarHardwareEnabled = $false
$ReBarDriverEnabled = $false

# 1. Проверка статуса драйвера и аппаратной поддержки
$ClassPath = "HKLM:\SYSTEM\CurrentControlSet\Control\Class\{4d36e968-e325-11ce-bfc1-08002be10318}"
$VideoAdapters = Get-SafeClassAdapters -ClassPath $ClassPath

foreach ($Adapter in $VideoAdapters) {
    $RegKey = Get-Item -LiteralPath $Adapter.PSPath
    $Provider = $RegKey.GetValue("ProviderName")
    $Desc = $RegKey.GetValue("DriverDesc")

    # Игнорируем виртуальный монитор Parsec и базовые адаптеры
    if ($Desc -match "Parsec|Virtual|Basic|Microsoft|Idd") { continue }

    # Для видеокарт AMD Radeon (RX 6000 / 7000 / 9000)
    if ($Provider -match "Advanced Micro Devices" -or $Desc -match "AMD|Radeon") {
        $Dx12State  = $RegKey.GetValue("KMD_EnableReBarForDx12")
        $Dx11State  = $RegKey.GetValue("KMD_EnableReBarForDx11")
        $SamState   = $RegKey.GetValue("KMD_EnableSAM")
        $RebarState = $RegKey.GetValue("KMD_EnableResizableBAR")
        
        # Если в драйвере активен SAM/ReBAR — видеокарта аппаратно и программно готова
        if ($Dx12State -eq 1 -or $Dx11State -eq 1 -or $SamState -eq 1 -or $RebarState -eq 1) {
            $ReBarDriverEnabled = $true
            $ReBarHardwareEnabled = $true
        }
    } 
    # Для видеокарт NVIDIA GeForce
    elseif ($Provider -match "NVIDIA") {
        $NvReBar = $RegKey.GetValue("RmGpuEnableResizableBar")
        if ($NvReBar -eq 1) { 
            $ReBarDriverEnabled = $true
            # $ReBarHardwareEnabled намеренно не ставится в $true, чтобы отработала реальная проверка BAR1 через nvidia-smi
        }
    } 
    # Для видеокарт Intel ARC
    elseif ($Provider -match "Intel") {
        $ReBarHardwareEnabled = $true
        $ReBarDriverEnabled = $true
    }
}

# Аппаратная проверка реального размера BAR1 через nvidia-smi (точный статус BIOS)
if (-not $ReBarHardwareEnabled) {
    $smiPath = (Get-Command "nvidia-smi.exe" -ErrorAction SilentlyContinue).Source
    if (-not $smiPath) {
        $candidates = @("$env:SystemRoot\System32\nvidia-smi.exe", "$env:ProgramFiles\NVIDIA Corporation\NVSMI\nvidia-smi.exe")
        foreach ($c in $candidates) { if (Test-Path $c) { $smiPath = $c; break } }
    }
    if ($smiPath) {
        try {
            $bar1 = & $smiPath --query-gpu=bar1.total --format=csv,noheader,nounits 2>$null
            if ($null -ne $bar1) {
                # Безопасный построчный парсинг для конфигураций с несколькими видеокартами
                $barValues = ($bar1 -split "`r?`n") | ForEach-Object { $_.Trim() } | Where-Object { $_ -match '^\d+$' }
                foreach ($val in $barValues) {
                    if ([int64]$val -gt 256) {
                        $ReBarHardwareEnabled = $true
                        $ReBarDriverEnabled = $true
                        break
                    }
                }
            }
        } catch {}
    }
}

# Вывод результатов
if ($ReBarHardwareEnabled) {
    Write-Host " ► Resizable BAR аппаратно включен" -ForegroundColor Green
} else {
    Write-Host "[WARNING] Resizable BAR аппаратно выключен (Включите Above 4G Decoding и" -ForegroundColor Yellow
    Write-Host "Resizable BAR в настройках BIOS UEFI, а также отключите CSM Support)" -ForegroundColor Yellow
}

if ($ReBarDriverEnabled) {
    Write-Host " ► Принудительный Resizable BAR в драйвере включен" -ForegroundColor Green
} else {
    Write-Host "[WARNING] Принудительный Resizable BAR в драйвере выключен" -ForegroundColor DarkGray
}

$global:TimerResAfter = [TimerAPI]::GetCurrentResolutionMs()
Write-Host ""
# ==============================================================================
# Раздел 80: Диагностика и контроль таймингов
# ==============================================================================
Show-ProgressStep -StepNum 80 -TotalSteps 81 -Activity "Диагностика и контроль таймингов..."
Write-Host "==============================================================================" -ForegroundColor DarkGray
Write-Host "РАЗДЕЛ 80: ДИАГНОСТИКА И КОНТРОЛЬ ТАЙМИНГОВ" -ForegroundColor Cyan
Write-Host "==============================================================================" -ForegroundColor DarkGray
Write-Host " ► Проверка конфигурации и частот оперативной памяти (XMP/EXPO)..." -ForegroundColor Magenta
try {
    # Запрашиваем данные о физических планках ОЗУ
    $PhysicalMemory = Get-CimInstance Win32_PhysicalMemory -ErrorAction Stop
    
    $TotalCapacity = 0
    $MinSpeed = 99999
    $IsJedec = $false
    
    foreach ($Stick in $PhysicalMemory) {
        $TotalCapacity += $Stick.Capacity
        
        # ConfiguredClockSpeed показывает реальную рабочую частоту, на которой завелась память
        $CurrentSpeed = $Stick.ConfiguredClockSpeed
        if ($null -eq $CurrentSpeed -or $CurrentSpeed -eq 0) {
            $CurrentSpeed = $Stick.Speed # Резервный фоллбэк на заявленную скорость, если BIOS скрыл Configured
        }
        
        if ($CurrentSpeed -lt $MinSpeed) { $MinSpeed = $CurrentSpeed }
    }
    
    $TotalRAM_GB = [math]::Round($TotalCapacity / 1GB)
    
    # Эвристика определения JEDEC (базовых профилей)
    # Память считается JEDEC только если DDR4 <= 2666 или чистая DDR5 <= 4800 (без перекрытия с DDR4 3200/3600)
    $IsDDR5 = ($MinSpeed -gt 3600)
    if ((-not $IsDDR5 -and $MinSpeed -le 2666 -and $MinSpeed -ge 2133) -or ($IsDDR5 -and $MinSpeed -le 4800)) {
        $IsJedec = $true
    }

    Write-Host " ► Установлено ОЗУ: $TotalRAM_GB GB" -ForegroundColor DarkGray
    Write-Host " ► Текущая частота шины: $MinSpeed MHz" -ForegroundColor DarkGray

    if ($IsJedec) {
        Write-Host ""
        Write-Host "[WARNING] Оперативная память работает на базовой частоте (JEDEC)!" -ForegroundColor DarkGray
        Write-Host "* XMP / EXPO профиль в BIOS, скорее всего, не активирован." -ForegroundColor DarkGray
        Write-Host "* Это создаст жесткое 'бутылочное горлышко' (Bottleneck)" -ForegroundColor DarkGray
        Write-Host "* для DWM, процессора и задач ИИ." -ForegroundColor DarkGray
        
        # Принудительная запись алерта в лог-файл для дальнейшего траблшутинга машинного парка
        [System.IO.File]::AppendAllText($global:LogPath, "CRITICAL WARNING: RAM is running at JEDEC fallback speed ($MinSpeed MHz). XMP/EXPO is likely disabled in BIOS." + [Environment]::NewLine, [System.Text.Encoding]::UTF8)
    } else {
        Write-Host ""
        Write-Host " ► Частота памяти в норме. Высокоскоростной XMP/EXPO профиль активен." -ForegroundColor Green
    }
} catch {
    Write-Host ""
    Write-Host "[WARNING] Не удалось получить прямой доступ к контроллеру памяти через WMI." -ForegroundColor DarkGray
    [System.IO.File]::AppendAllText($global:LogPath, "RAM DIAGNOSTICS: WMI query failed. Error: $($_.Exception.Message)" + [Environment]::NewLine, [System.Text.Encoding]::UTF8)
}

Write-Host "------------------------------------------------------------------------------" -ForegroundColor DarkGray
Write-Host " ► Аппаратный аудит стабильности процессора, памяти и шины PCIe (WHEA-Logger)..." -ForegroundColor Magenta

if (-not $global:WheaAuditRun) {
    Write-Host " ► [ПРОПУСК] Журнал WHEA недоступен или служба журналов отключена." -ForegroundColor DarkGray
} elseif ($global:WheaEventsFound) {
    Write-Host ""
    Write-Host "==============================================================================" -ForegroundColor Yellow
    Write-Host "[WARNING] ВНИМАНИЕ: В СИСТЕМЕ ОБНАРУЖЕНЫ АППАРАТНЫЕ ОШИБКИ WHEA ($global:TotalWhea шт.)!" -ForegroundColor Red
    Write-Host "==============================================================================" -ForegroundColor Yellow
    Write-Host "Это указывает на нестабильность разгона, андервольтинга, шины или таймингов ОЗУ." -ForegroundColor DarkGray
    Write-Host "Аппаратные сбои WHEA вызывают микро-статтеры (подлагивания) кадра в играх.`n" -ForegroundColor DarkGray

    if ($global:WheaSummary.CpuCacheErrors -gt 0 -or $global:WheaSummary.FatalMceErrors -gt 0) {
        Write-Host " • Ошибки процессора / кэша (Event 18/19): $($global:WheaSummary.CpuCacheErrors + $global:WheaSummary.FatalMceErrors) шт." -ForegroundColor Yellow
        if ($global:FailingCores.Count -gt 0) {
            $coresStr = ($global:FailingCores | Sort-Object) -join ', '
            Write-Host "   ► Сбойные логические потоки (APIC ID): [$coresStr]" -ForegroundColor Red
            Write-Host "   ► РЕКОМЕНДАЦИЯ: Ослабьте Curve Optimizer / поднимите вольтаж (Vcore) на этих ядрах!" -ForegroundColor DarkGray
        }
    }

    if ($global:WheaSummary.PcieErrors -gt 0) {
        Write-Host " • Ошибки шины PCI Express (Event 17): $($global:WheaSummary.PcieErrors) шт." -ForegroundColor Yellow
        Write-Host "   ► РЕКОМЕНДАЦИЯ: Проверьте райзер видеокарты, контакт NVMe накопителя" -ForegroundColor DarkGray
        Write-Host "     или переключите слот PCIe в BIOS с Gen 4/5 на Gen 3/4." -ForegroundColor DarkGray
    }

    if ($global:WheaSummary.MemoryErrors -gt 0) {
        Write-Host " • Ошибки шины памяти (Event 47/1): $($global:WheaSummary.MemoryErrors) шт." -ForegroundColor Yellow
        Write-Host "   ► РЕКОМЕНДАЦИЯ: Тайминги ОЗУ пережаты, либо нестабилен профиль XMP/EXPO." -ForegroundColor DarkGray
    }

    if ($global:WheaSummary.OtherErrors -gt 0) {
        $otherIdsStr = ($global:OtherWheaIDs | Sort-Object) -join ', '
        Write-Host " • Прочие аппаратные ошибки (Event ID: $otherIdsStr): $($global:WheaSummary.OtherErrors) шт." -ForegroundColor Yellow
        Write-Host "   ► РЕКОМЕНДАЦИЯ: Найдите код события $otherIdsStr в интернете для уточнения причины." -ForegroundColor DarkGray
    }

    $logWheaMsg = "[WHEA AUDIT] Total: $($global:TotalWhea) events. CPU: $($global:WheaSummary.CpuCacheErrors), PCIe: $($global:WheaSummary.PcieErrors), RAM: $($global:WheaSummary.MemoryErrors), Other: $($global:WheaSummary.OtherErrors) (IDs: $(($global:OtherWheaIDs -join ','))). Failing APIC IDs: $(($global:FailingCores -join ','))`r`n"
    try { Add-Content -Path $global:LogPath -Value $logWheaMsg -Encoding UTF8 } catch {}
} else {
    Write-Host " ► Аппаратных ошибок WHEA не зафиксировано (Шина, процессор и память стабильны)." -ForegroundColor Green
    try { Add-Content -Path $global:LogPath -Value "[WHEA AUDIT] Clean. No hardware errors found in the last 7 days.`r`n" -Encoding UTF8 } catch {}
}

Write-Host "------------------------------------------------------------------------------" -ForegroundColor DarkGray
Write-Host " ► Экспресс-замер аппаратных задержек ядра DPC/ISR (5 секунд)..." -ForegroundColor Magenta
try {
    # Включаем счетчики ядра PerfOS, чтобы класс WMI гарантированно существовал
    cmd.exe /c "lodctr /e:PerfOS >nul 2>&1"

    $TotalDpcPercent = 0.0
    $TotalDpcQueue = 0.0
    $SampleCount = 5

    for ($i = 0; $i -lt $SampleCount; $i++) {
        Start-Sleep -Seconds 1
        $PerfData = Get-CimInstance -ClassName Win32_PerfFormattedData_PerfOS_Processor -Filter "Name='_Total'" -ErrorAction Stop
        $TotalDpcPercent += [double]$PerfData.PercentDPCTime
        $TotalDpcQueue += [double]$PerfData.DPCsQueuedPersec
    }

    $AvgDpc = [math]::Round($TotalDpcPercent / $SampleCount, 2)
    $AvgQueue = [math]::Round($TotalDpcQueue / $SampleCount)

    Write-Host " ► Средняя загрузка ядра прерываниями DPC: $AvgDpc%" -ForegroundColor DarkGray
    Write-Host " ► Частота очереди DPC: $AvgQueue процедур/сек" -ForegroundColor DarkGray

    if ($AvgDpc -le 2.0) {
        Write-Host " ► Аппаратные задержки DPC находятся в идеальном диапазоне" -ForegroundColor Green
        [System.IO.File]::AppendAllText($global:LogPath, "[DPC CHECK] Excellent: $AvgDpc%, Queue: $AvgQueue/s`r`n", [System.Text.Encoding]::UTF8)
    } else {
        Write-Host "[WARNING] Зафиксирована повышенная задержка DPC ($AvgDpc%)!" -ForegroundColor DarkGray
        Write-Host "Рекомендуется проверить систему утилитой LatencyMon для выявления" -ForegroundColor DarkGray
        Write-Host "проблемного драйвера." -ForegroundColor DarkGray
        [System.IO.File]::AppendAllText($global:LogPath, "[DPC CHECK] High latency detected: $AvgDpc%, Queue: $AvgQueue/s`r`n", [System.Text.Encoding]::UTF8)
    }
} catch {
    Write-Host "[WARNING] Не удалось получить данные счетчиков ядра (Служба счетчиков" -ForegroundColor DarkGray
    Write-Host "отключена или недоступна)." -ForegroundColor DarkGray
    [System.IO.File]::AppendAllText($global:LogPath, "[DPC CHECK] Counter read skipped or failed: $($_.Exception.Message)`r`n", [System.Text.Encoding]::UTF8)
}

Write-Host "------------------------------------------------------------------------------" -ForegroundColor DarkGray
Write-Host " ► Разрешение системного таймера ядра (Timer Resolution):" -ForegroundColor Magenta
Write-Host " ► До оптимизации:    $([math]::Round($global:TimerResBefore, 3)) ms" -ForegroundColor DarkGray
Write-Host " ► После оптимизации: $([math]::Round($global:TimerResAfter, 3)) ms" -ForegroundColor Green
Write-Host ""
Write-Host ""
Write-Host "=================================================================================================================" -ForegroundColor Yellow
Write-Host ">>>  ОПТИМИЗАЦИЯ СИСТЕМЫ ЗАВЕРШЕНА УСПЕШНО  <<<" -ForegroundColor Green
Write-Host "Для вступления всех изменений в силу НЕОБХОДИМА ПЕРЕЗАГРУЗКА ПК!" -ForegroundColor Red
Write-Host "=================================================================================================================" -ForegroundColor Yellow
Write-Host ""
Write-Host ""
# Генерация деинсталлятора реестра в самом конце, когда ВСЕ твики уже записаны в лог
Apply-Tweak "Генерация скрипта точечного восстановления (Eastrica_Registry_Rollback.ps1)" { Build-RegistryRollbackScript }
Write-Host ""
# ==============================================================================
# Раздел 81: Финальные инструкции для пользователя
# ==============================================================================
Show-ProgressStep -StepNum 81 -TotalSteps 81 -Activity "Сохранение руководства пользователя..."

# Генерация текстового гайда на рабочий стол с оригинальными инструкциями
$ManualGuidePath = "$([Environment]::GetFolderPath('Desktop'))\Eastrica_Manual_Guide.txt"
